window.SEMIPRIME_SOURCES={"RiemannGaussian.SemiprimeBinomialExecutionBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeBinomialExecutionTracked\n\n/-! # Integer coefficient and scratch bounds for executed parity interpolation -/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeBinomialExecutionBounds\nopen scoped BigOperators\nopen SemiprimeBinomialExecution\n\n/-- Every actual scalar dot prefix has an absolute bound before cancellations. -/\ntheorem dot_bound (kernel : Array ℕ) (a : Array ℤ) (row len M B : ℕ)\n    (hk : ∀ i<len,natCoeff kernel (row-i)≤ M)\n    (ha : ∀ i<len,|coeff a i|≤(B : ℤ)) :\n    |(dot kernel a row len).value|≤(len*M*B : ℕ) := by\n  rw [dot_value]\n  calc\n    _ ≤ ∑ i∈Finset.range len,|(natCoeff kernel (row-i) : ℤ)*coeff a i| := Finset.abs_sum_le_sum_abs _ _\n    _ ≤ ∑ _i∈Finset.range len,(M : ℤ)*(B : ℤ) := by\n      apply Finset.sum_le_sum\n      intro i hi\n      have hindex := Finset.mem_range.mp hi\n      rw [abs_mul,Int.abs_natCast]\n      exact mul_le_mul (by exact_mod_cast hk i hindex) (ha i hindex) (abs_nonneg _) (by positivity)\n    _ = _ := by simp [Nat.mul_assoc]\n\n/-- A simple positive majorant of every stage of the unitriangular solve. -/\ndef solveBase (total M : ℕ) : ℕ := total*M+1\n\n/-- All cached solve coefficients have a uniform integer bound, including every prefix. -/\ntheorem solve_bound (kernel : Array ℕ) (target : ℕ → ℤ) (total M Z : ℕ)\n    (hk : ∀ i≤ total,natCoeff kernel i≤ M)\n    (ht : ∀ i<total,|target i|≤(Z : ℤ)) (len : ℕ) (hlen : len≤ total) :\n    ∀ i<len,|coeff (solve kernel target len).coefficients i|≤(Z*solveBase total M^len : ℕ) := by\n  induction len with\n  | zero => intro i hi; omega\n  | succ len ih =>\n    have hprev := ih (by omega : len≤ total)\n    intro i hi\n    by_cases he : i=len\n    · subst i\n      rw [solve_new,← dot_value]\n      have hd := dot_bound kernel (solve kernel target len).coefficients len len M\n        (Z*solveBase total M^len) (fun j _ => hk _ (by omega)) hprev\n      have hab := abs_sub (target len) (dot kernel (solve kernel target len).coefficients len len).value\n      have hz := ht len (by omega)\n      have hpower : 1≤ solveBase total M^len := by\n        simpa only [one_pow] using Nat.pow_le_pow_left\n          (show 1≤ solveBase total M by unfold solveBase; omega) len\n      have hNat : Z+len*M*(Z*solveBase total M^len)≤ Z*solveBase total M^(len+1) := by\n        calc\n          _ ≤ Z*solveBase total M^len+total*M*(Z*solveBase total M^len) :=\n            Nat.add_le_add (by simpa using Nat.mul_le_mul_left Z hpower)\n              (Nat.mul_le_mul_right _ (Nat.mul_le_mul_right M (by omega : len≤ total)))\n          _ = _ := by rw [pow_succ]; unfold solveBase; ring\n      have hsum : |target len-(dot kernel (solve kernel target len).coefficients len len).value|≤\n          (Z+len*M*(Z*solveBase total M^len) : ℕ) := by\n        exact hab.trans (by exact_mod_cast add_le_add hz hd)\n      exact hsum.trans (by exact_mod_cast hNat)\n    · rw [solve_old _ _ _ _ (by omega : i<len)]\n      have hp := Nat.pow_le_pow_right (show 1≤ solveBase total M by unfold solveBase; omega)\n        (Nat.le_succ len)\n      exact (hprev i (by omega)).trans (by exact_mod_cast Nat.mul_le_mul_left Z hp)\n\n/-- The explicit Pascal supplier never exceeds the native binomial height. -/\ntheorem chooseRow_bound (R A k : ℕ) (hk : k≤ R) : natCoeff (chooseRow R A) k≤ 2^A := by\n  rw [chooseRow_correct R A k hk]\n  exact Nat.choose_le_two_pow _ _\n\n/-- The lower solution's magnitude is just a small integer power of two. -/\ntheorem lower_abs (A s : ℕ) : |lower A s|=(2 : ℤ)^s := by\n  simp [lower,abs_mul,abs_pow]\n\n/-- Every runtime reversed target is bounded, including natural zero extension. -/\ntheorem target_bound (A R k : ℕ) : |lower A (R-(k+1))|≤(2^R : ℕ) := by\n  rw [lower_abs]\n  exact_mod_cast Nat.pow_le_pow_right (by decide : 1≤ 2) (Nat.sub_le R (k+1))\n\n/-- Uniform height of every acquired original-order parity coefficient. -/\ntheorem parity_bound (A R : ℕ) (j : Fin R) :\n    |parity A R j|≤(2^R*(R*2^A+1)^R : ℕ) := by\n  have h := solve_bound (chooseRow R A) (fun k => lower A (R-(k+1))) R (2^A) (2^R)\n    (fun k hk => chooseRow_bound R A k hk) (fun k _ => target_bound A R k) R le_rfl j.rev.val j.rev.isLt\n  exact h\n\n/-- All completed integer coefficients fit an explicit polynomial exponent envelope. -/\ntheorem parity_bound_power (A R : ℕ) (j : Fin R) :\n    |parity A R j|≤(2^(R*(A+Nat.clog 2 (R+1)+1)) : ℕ) := by\n  have hbase : R*2^A+1≤ 2^(A+Nat.clog 2 (R+1)) := by\n    calc\n      R*2^A+1 ≤ (R+1)*2^A := by have hp : 1≤ 2^A := Nat.one_le_pow _ _ (by decide); nlinarith\n      _ ≤ (2^Nat.clog 2 (R+1))*2^A := Nat.mul_le_mul_right _ (Nat.le_pow_clog (by decide) _)\n      _ = _ := by rw [pow_add]; ring\n  have hp := Nat.mul_le_mul_left (2^R) (Nat.pow_le_pow_left hbase R)\n  have he : 2^R*(2^(A+Nat.clog 2 (R+1)))^R=2^(R*(A+Nat.clog 2 (R+1)+1)) := by\n    rw [← pow_mul,← pow_add]\n    congr 1\n    ring\n  exact (parity_bound A R j).trans (by exact_mod_cast hp.trans_eq he)\n\n/-- The fully tracked acquired vector retains the same explicit integer bit envelope. -/\ntheorem acquiredParity_bound_power (A R : ℕ) (j : Fin R) :\n    |SemiprimeBinomialExecutionTracked.acquiredParity A R j|≤\n      (2^(R*(A+Nat.clog 2 (R+1)+1)) : ℕ) := by\n  have h : SemiprimeBinomialExecutionTracked.acquiredParity A R=parity A R :=\n    (SemiprimeBinomialExecutionTracked.acquiredParity_eq A R).trans (parity_eq A R).symm\n  rw [h]\n  exact parity_bound_power A R j\n\n/-- Even the retained next target power has only R+1 binary digits. -/\ntheorem acquiredLower_next_bound (A R : ℕ) :\n    |(SemiprimeBinomialExecutionTracked.acquireLower\n      (SemiprimeBinomialExecutionTracked.sign A).1 R).next|=(2 : ℤ)^R := by\n  rw [SemiprimeBinomialExecutionTracked.acquireLower_next,\n    SemiprimeBinomialExecutionTracked.sign_value]\n  exact lower_abs A R\n\nend RiemannGaussian.SemiprimeBinomialExecutionBounds\n","RiemannGaussian.SemiprimeBitIndexClipping":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeBitIndexBasis\n\n/-!\n# Boolean signed clipping of original index-basis lines\n\nSigned magnitudes retain every physical input bit. Borrow arithmetic,\nsign flags and restoring division compute the original inclusive clipping\nbounds. Mathematical integer interpretation is specification only. Actual\ncoordinate/point emission, acquisition and full machine/memory costs remain\nseparate obligations.\n-/\n\nnamespace RiemannGaussian.SemiprimeBitIndexClipping\n\nopen SemiprimeBitArithmetic SemiprimeBitDivision SemiprimeBitPrimeScan\nopen SemiprimeBitIndexRoots SemiprimeIndexEnumeration\n\n/-- Original signed magnitude, allowing both encodings of zero. -/\nstructure SignedWord where\n  /-- Boolean sign; true means negation of the unsigned magnitude. -/\n  negative : Bool\n  /-- Actual little-endian word, including its supplied high-zero padding. -/\n  magnitude : List Bool\n\n/-- Mathematical signed interpretation; executable word paths never call it. -/\nabbrev SignedWord.value (word : SignedWord) : ℤ :=\n  if word.negative=true then -(bitValue word.magnitude : ℤ) else bitValue word.magnitude\n\n/-- Toggle the actual sign flag, sharing the original physical magnitude.\nEvery caller includes the one NOT gate in its own clock. -/\ndef negateWord (word : SignedWord) : SignedWord := ⟨!word.negative,word.magnitude⟩\n\n/-- Sign toggling is exact even for the two zero encodings. -/\ntheorem negateWord_value (word : SignedWord) : (negateWord word).value= -word.value := by\n  cases word with\n  | mk negative magnitude => cases negative <;> simp [negateWord,SignedWord.value]\n\n/-- Sign toggling preserves the actual physical input word. -/\ntheorem negateWord_magnitude (word : SignedWord) : (negateWord word).magnitude=word.magnitude := rfl\n\n/-- Actual signed sum and all executed unsigned diagnostics. -/\nstructure SignedSumReport where\n  /-- The actual addition, only when the two signs agree. -/\n  addition : Option BitReport\n  /-- First full subtraction when the signs differ. -/\n  difference : Option SubReport\n  /-- Reverse full subtraction, only after first underflow. -/\n  reverse : Option SubReport\n  /-- Computed signed magnitude, with no native integer output. -/\n  word : SignedWord\n  /-- All arithmetic, sign decisions and retained diagnostics. -/\n  clock : ℕ\n\n/-- Same signs add magnitudes. Opposite signs subtract in the original\norientation, reversing after actual borrow; failed first work remains paid. -/\ndef addSignedBits (left right : SignedWord) : SignedSumReport :=\n  if left.negative=right.negative then\n    let addition := addBits left.magnitude right.magnitude false\n    ⟨some addition,none,none,⟨left.negative,addition.bits⟩,bitCost addition+4⟩\n  else\n    let difference := subBits left.magnitude right.magnitude false\n    if difference.borrow=true then\n      let reverse := subBits right.magnitude left.magnitude false\n      ⟨none,some difference,some reverse,⟨right.negative,reverse.result.bits⟩,\n        bitCost difference.result+bitCost reverse.result+8⟩\n    else\n      ⟨none,some difference,none,⟨left.negative,difference.result.bits⟩,\n        bitCost difference.result+6⟩\n\n/-- The signed sum preserves exact integer addition on arbitrary padded\nwords, including cancellation and either sign representation of zero. -/\ntheorem addSignedBits_value (left right : SignedWord) :\n    (addSignedBits left right).word.value=left.value+right.value := by\n  have ha := addBits_correct left.magnitude right.magnitude false\n  simp only [bitNat,Bool.false_eq_true,ite_false,Nat.add_zero] at ha\n  have hb := subBits_borrow_iff left.magnitude right.magnitude false\n  simp only [bitNat,Bool.false_eq_true,ite_false,Nat.add_zero] at hb\n  by_cases hs : left.negative=right.negative\n  · unfold addSignedBits\n    rw [ite_eq_left hs]\n    dsimp only [SignedWord.value]\n    rw [ha]\n    rw [←hs]\n    split <;> push_cast <;> ring\n  · by_cases hc : (subBits left.magnitude right.magnitude false).borrow=true\n    · have hl := hb.mp hc\n      have hr : (subBits right.magnitude left.magnitude false).borrow=false :=\n        (subBits_borrow_false _ _).mpr hl.le\n      have hd := subBits_difference hr\n      have hv : ((bitValue left.magnitude : ℤ)+(bitValue right.magnitude-bitValue left.magnitude : ℕ))=\n          bitValue right.magnitude := by omega\n      unfold addSignedBits\n      rw [ite_eq_right hs,ite_eq_left hc]\n      dsimp only [SignedWord.value]\n      rw [hd]\n      cases hn : left.negative <;> cases hm : right.negative <;>\n        simp only [hn,hm,Bool.false_eq_true,reduceIte] at hs ⊢ <;> first | exact False.elim (hs (by trivial)) | omega\n    · have hr : (subBits left.magnitude right.magnitude false).borrow=false := by\n        cases hh : (subBits left.magnitude right.magnitude false).borrow with\n        | false => rfl\n        | true => exact False.elim (hc hh)\n      have hle := (subBits_borrow_false _ _).mp hr\n      have hd := subBits_difference hr\n      have hv : ((bitValue right.magnitude : ℤ)+(bitValue left.magnitude-bitValue right.magnitude : ℕ))=\n          bitValue left.magnitude := by omega\n      unfold addSignedBits\n      rw [ite_eq_right hs,ite_eq_right hc]\n      dsimp only [SignedWord.value]\n      rw [hd]\n      cases hn : left.negative <;> cases hm : right.negative <;>\n        simp only [hn,hm,Bool.false_eq_true,reduceIte] at hs ⊢ <;> first | exact False.elim (hs (by trivial)) | omega\n\n/-- Every signed sum pays full physical arithmetic and grows width at\nmost one cell. Failed opposite-sign subtraction is included. -/\ntheorem addSignedBits_cost_width {W : ℕ} {left right : SignedWord}\n    (hl : left.magnitude.length≤W) (hr : right.magnitude.length≤W) :\n    (addSignedBits left right).clock≤40*(W+1) ∧\n      (addSignedBits left right).word.magnitude.length≤W+1 := by\n  have ha := bounded_addBits hl hr false\n  have hd := subBits_cost left.magnitude right.magnitude false\n  have hdw := (subBits_counts left.magnitude right.magnitude false).2.2.2.2\n  have hb := subBits_cost right.magnitude left.magnitude false\n  have hbw := (subBits_counts right.magnitude left.magnitude false).2.2.2.2\n  unfold addSignedBits\n  dsimp only\n  split\n  · dsimp only\n    constructor <;> omega\n  · split <;> dsimp only <;> constructor <;> omega\n\n/-- Exact signed subtraction pays its actual sign NOT before addition. -/\ndef subSignedBits (left right : SignedWord) : SignedSumReport :=\n  let child := addSignedBits left (negateWord right)\n  {child with clock := child.clock+1}\n\n/-- Signed subtraction preserves the original integer operation. -/\ntheorem subSignedBits_value (left right : SignedWord) :\n    (subSignedBits left right).word.value=left.value-right.value := by\n  rw [subSignedBits,addSignedBits_value,negateWord_value,sub_eq_add_neg]\n\n/-- Subtraction's full clock and physical output include its sign gate. -/\ntheorem subSignedBits_cost_width {W : ℕ} {left right : SignedWord}\n    (hl : left.magnitude.length≤W) (hr : right.magnitude.length≤W) :\n    (subSignedBits left right).clock≤41*(W+1) ∧\n      (subSignedBits left right).word.magnitude.length≤W+1 := by\n  have hc := addSignedBits_cost_width (left:=left) (right:=negateWord right) hl hr\n  dsimp only [subSignedBits]\n  exact ⟨by omega,hc.2⟩\n\n/-- Actual unsigned product and its computed signed output. -/\nstructure SignedProductReport where\n  /-- Full Boolean multiplication report, including every intermediate write. -/\n  product : BitReport\n  /-- Magnitude is the computed product; sign is the actual XOR. -/\n  word : SignedWord\n  /-- Full multiplication, XOR gate and retained output decisions. -/\n  clock : ℕ\n\n/-- Compute signed multiplication with the existing Boolean circuit. -/\ndef mulSignedBits (left right : SignedWord) : SignedProductReport :=\n  let product := mulBits left.magnitude right.magnitude\n  ⟨product,⟨Bool.xor left.negative right.negative,product.bits⟩,bitCost product+3⟩\n\n/-- Arbitrary signed magnitudes multiply exactly, including signed zeros. -/\ntheorem mulSignedBits_value (left right : SignedWord) :\n    (mulSignedBits left right).word.value=left.value*right.value := by\n  unfold mulSignedBits\n  dsimp only [SignedWord.value]\n  rw [mulBits_correct]\n  cases hn : left.negative <;> cases hm : right.negative <;>\n    simp only [Bool.xor_false,Bool.xor_true,Bool.false_eq_true,reduceIte,\n      Bool.not_false,Bool.not_true] <;> push_cast <;> ring\n\n/-- Complete signed multiplication remains quadratic in physical width. -/\ntheorem mulSignedBits_cost_width {W : ℕ} {left right : SignedWord}\n    (hl : left.magnitude.length≤W) (hr : right.magnitude.length≤W) :\n    (mulSignedBits left right).clock≤24*(W+1)^2+4 ∧\n      (mulSignedBits left right).word.magnitude.length≤3*W := by\n  have hc := bounded_mulBits hl hr\n  dsimp only [mulSignedBits]\n  exact ⟨by omega,hc.2⟩\n\n/-- Both unsigned borrow comparisons and zero diagnostics for signed order. -/\nstructure SignedOrderReport where\n  /-- right magnitude minus left, recognizing the nonnegative-sign order. -/\n  forward : SubReport\n  /-- left magnitude minus right, recognizing the reversed negative order. -/\n  backward : SubReport\n  /-- Actual full scans, required to treat both signed zeros equally. -/\n  leftNonzero : NonzeroReport\n  /-- The original right magnitude's actual full nonzero scan. -/\n  rightNonzero : NonzeroReport\n  /-- Computed signed less-or-equal flag. -/\n  le : Bool\n  /-- All comparisons, full scans, sign gates and decisions. -/\n  clock : ℕ\n\n/-- Compare arbitrary signed magnitudes, explicitly retaining the zero\ntest on the positive-left/negative-right branch. No integer order is called. -/\ndef leSignedBits (left right : SignedWord) : SignedOrderReport :=\n  let forward := subBits right.magnitude left.magnitude false\n  let backward := subBits left.magnitude right.magnitude false\n  let leftNonzero := nonzeroBits left.magnitude\n  let rightNonzero := nonzeroBits right.magnitude\n  let le := if left.negative=true then\n      if right.negative=true then !backward.borrow else true\n    else if right.negative=true then !leftNonzero.nonzero && !rightNonzero.nonzero\n    else !forward.borrow\n  ⟨forward,backward,leftNonzero,rightNonzero,le,\n    bitCost forward.result+bitCost backward.result+leftNonzero.clock+rightNonzero.clock+8⟩\n\n/-- Signed comparison is exact on every representation, including negative\nzero and physically padded words. -/\ntheorem leSignedBits_exact (left right : SignedWord) :\n    (leSignedBits left right).le=true ↔ left.value≤right.value := by\n  have hf := subBits_borrow_false right.magnitude left.magnitude\n  have hb := subBits_borrow_false left.magnitude right.magnitude\n  cases hn : left.negative with\n  | false =>\n    cases hm : right.negative with\n    | false =>\n      simp only [leSignedBits,SignedWord.value,hn,hm,Bool.false_eq_true,reduceIte,\n        Bool.not_eq,Bool.not_eq_true,hf]\n      omega\n    | true =>\n      simp only [leSignedBits,SignedWord.value,hn,hm,Bool.false_eq_true,reduceIte,\n        Bool.and_eq_true,Bool.not_eq,Bool.not_eq_true,nonzeroBits_false_iff]\n      omega\n  | true =>\n    cases hm : right.negative with\n    | false =>\n      simp only [leSignedBits,SignedWord.value,hn,hm,Bool.false_eq_true,reduceIte]\n      constructor\n      · intro _\n        omega\n      · intro _\n        trivial\n    | true =>\n      simp only [leSignedBits,SignedWord.value,hn,hm,reduceIte,Bool.not_eq,Bool.not_eq_true,hb]\n      omega\n\n/-- Every signed order operation includes both complete borrows and scans. -/\ntheorem leSignedBits_cost {W : ℕ} {left right : SignedWord}\n    (hl : left.magnitude.length≤W) (hr : right.magnitude.length≤W) :\n    (leSignedBits left right).clock≤40*(W+1) := by\n  have hf := subBits_cost right.magnitude left.magnitude false\n  have hb := subBits_cost left.magnitude right.magnitude false\n  have hz0 := nonzeroBits_cost left.magnitude\n  have hz1 := nonzeroBits_cost right.magnitude\n  dsimp only [leSignedBits]\n  omega\n\n/-- Actual restoring division is physically bounded even at denominator\nzero, where it retains the original dividend as the remainder. -/\ntheorem divideBits_all_width (xs ys : List Bool) :\n    (divideBits xs ys).quotient.length≤xs.length ∧\n      (divideBits xs ys).remainder.length≤max xs.length ys.length := by\n  by_cases hb : (nonzeroBits ys).nonzero=true\n  · have hw := divideBits_widths (xs:=xs) ((nonzeroBits_correct ys).mp hb)\n    exact ⟨hw.2.le,hw.1.le.trans (Nat.le_max_right _ _)⟩\n  · simp only [divideBits,ite_eq_right hb,List.length_nil]\n    exact ⟨Nat.zero_le _,Nat.le_max_left _ _⟩\n\n/-- The arithmetic correction for negative floor division by a positive\nunsigned denominator. Only the mathematical specification uses integers. -/\ntheorem negative_nat_floor (n d : ℕ) (hd : 0<d) :\n    (-(n : ℤ))/(d : ℤ)=\n      if n%d=0 then -((n/d : ℕ) : ℤ) else -((n/d+1 : ℕ) : ℤ) := by\n  have hD : (0 : ℤ)<d := by exact_mod_cast hd\n  have he : (n : ℤ)=(n%d : ℕ)+(d : ℤ)*(n/d : ℕ) := by\n    exact_mod_cast (Nat.mod_add_div n d).symm\n  have hr : ((n%d : ℕ) : ℤ)<d := by exact_mod_cast Nat.mod_lt n hd\n  by_cases hz : n%d=0\n  · rw [ite_eq_left hz,Int.ediv_eq_iff_of_pos hD]\n    simp only [hz,Nat.cast_zero,zero_add] at he\n    constructor <;> nlinarith\n  · have hp : (0 : ℤ)<((n%d : ℕ) : ℤ) := by exact_mod_cast (show 0<n%d by omega)\n    rw [ite_eq_right hz,Int.ediv_eq_iff_of_pos hD]\n    simp only [Nat.cast_add,Nat.cast_one]\n    constructor <;> nlinarith\n\n/-- Actual signed floor quotient, retaining full division and rounding work. -/\nstructure SignedFloorReport where\n  /-- Full unsigned magnitude quotient/remainder circuit. -/\n  division : DivisionReport\n  /-- Actual divisor scan; denominator zero suppresses the correction. -/\n  denominatorNonzero : NonzeroReport\n  /-- Actual full remainder scan distinguishes exact divisibility. -/\n  remainderNonzero : NonzeroReport\n  /-- Executed quotient plus one; paid even when the output retains quotient. -/\n  increment : BitReport\n  /-- Computed signed floor word. -/\n  word : SignedWord\n  /-- All restoring work, both scans, increment, sign gates and decisions. -/\n  clock : ℕ\n\n/-- Negative nonintegral quotients round down by increasing the computed\nmagnitude. Both zero signs and zero denominators are handled by actual flags. -/\ndef floorSignedBits (numerator : SignedWord) (denominator : List Bool) : SignedFloorReport :=\n  let division := divideBits numerator.magnitude denominator\n  let denominatorNonzero := nonzeroBits denominator\n  let remainderNonzero := nonzeroBits division.remainder\n  let increment := addBits division.quotient [true] false\n  let correction := numerator.negative && denominatorNonzero.nonzero && remainderNonzero.nonzero\n  let word := ⟨numerator.negative,if correction=true then increment.bits else division.quotient⟩\n  ⟨division,denominatorNonzero,remainderNonzero,increment,word,\n    division.clock+denominatorNonzero.clock+remainderNonzero.clock+bitCost increment+8⟩\n\n/-- The actual floor equals original integer Euclidean division for every\nunsigned denominator word, including zero and arbitrary high-zero padding. -/\ntheorem floorSignedBits_value (numerator : SignedWord) (denominator : List Bool) :\n    (floorSignedBits numerator denominator).word.value=\n      numerator.value/(bitValue denominator : ℤ) := by\n  have hq := (divideBits_correct numerator.magnitude denominator).1\n  have hr := (divideBits_correct numerator.magnitude denominator).2\n  have hi := addBits_correct (divideBits numerator.magnitude denominator).quotient [true] false\n  simp only [bitValue,bitNat,ite_true,Bool.false_eq_true,ite_false,\n    Nat.mul_zero,Nat.add_zero] at hi\n  cases hn : numerator.negative\n  · simp only [floorSignedBits,SignedWord.value,hn,Bool.false_and,Bool.false_eq_true,reduceIte]\n    rw [hq,Int.natCast_ediv]\n  · by_cases hD : 0<bitValue denominator\n    · have hd := (nonzeroBits_correct denominator).mpr hD\n      by_cases hR : bitValue numerator.magnitude%bitValue denominator=0\n      · have hz := (nonzeroBits_false_iff (divideBits numerator.magnitude denominator).remainder).mpr\n          (hr.trans hR)\n        simp only [floorSignedBits,SignedWord.value,hn,hd,hz,Bool.true_and,Bool.and_false,\n          Bool.false_eq_true,reduceIte]\n        rw [hq,negative_nat_floor _ _ hD,ite_eq_left hR]\n      · have hp : 0<bitValue (divideBits numerator.magnitude denominator).remainder := by\n          rw [hr]\n          omega\n        have hz := (nonzeroBits_correct _).mpr hp\n        simp only [floorSignedBits,SignedWord.value,hn,hd,hz,Bool.true_and,reduceIte]\n        rw [hi,hq,negative_nat_floor _ _ hD,ite_eq_right hR]\n    · have hzero : bitValue denominator=0 := by omega\n      have hd := (nonzeroBits_false_iff denominator).mpr hzero\n      simp only [floorSignedBits,SignedWord.value,hn,hd,Bool.and_false,Bool.false_and,\n        Bool.false_eq_true,reduceIte]\n      rw [hq,hzero,Nat.div_zero]\n      simp only [Nat.cast_zero,Int.ediv_zero,neg_zero]\n\n/-- Floor output and complete rounding clock stay physically bounded on\nall inputs; the discarded increment is included. -/\ntheorem floorSignedBits_cost_width {W : ℕ} {numerator : SignedWord} {denominator : List Bool}\n    (hn : numerator.magnitude.length≤W) (hd : denominator.length≤W) :\n    (floorSignedBits numerator denominator).clock≤150*(W+1)^2 ∧\n      (floorSignedBits numerator denominator).word.magnitude.length≤W+2 := by\n  have hw := divideBits_all_width numerator.magnitude denominator\n  have hq : (divideBits numerator.magnitude denominator).quotient.length≤W := hw.1.trans hn\n  have hr : (divideBits numerator.magnitude denominator).remainder.length≤W := by omega\n  have hdiv := bounded_divideBits (by omega : numerator.magnitude.length≤3*W) hd\n  have hdn := nonzeroBits_cost denominator\n  have hrn := nonzeroBits_cost (divideBits numerator.magnitude denominator).remainder\n  have hadd := bounded_addBits (by omega : (divideBits numerator.magnitude denominator).quotient.length≤W+1)\n    (by simp only [List.length_cons,List.length_nil]; omega : ([true] : List Bool).length≤W+1) false\n  constructor\n  · dsimp only [floorSignedBits]\n    nlinarith [hadd.1]\n  · unfold floorSignedBits\n    dsimp only\n    split <;> omega\n\n/-- Actual floor on the negated input and the sign-toggled ceiling output. -/\nstructure SignedCeilReport where\n  /-- Complete floor report, including actual quotient and rounding diagnostics. -/\n  floor : SignedFloorReport\n  /-- Computed signed ceiling word. -/\n  word : SignedWord\n  /-- Complete floor clock and the two actual sign NOT gates. -/\n  clock : ℕ\n\n/-- Construct ceiling by the original exact identity -floor(-a/d). -/\ndef ceilSignedBits (numerator : SignedWord) (denominator : List Bool) : SignedCeilReport :=\n  let floor := floorSignedBits (negateWord numerator) denominator\n  ⟨floor,negateWord floor.word,floor.clock+2⟩\n\n/-- Actual ceiling preserves the original signed ceiling operation. -/\ntheorem ceilSignedBits_value (numerator : SignedWord) (denominator : List Bool) :\n    (ceilSignedBits numerator denominator).word.value=\n      ceilDivide numerator.value (bitValue denominator) := by\n  dsimp only [ceilSignedBits]\n  rw [negateWord_value,floorSignedBits_value,negateWord_value]\n  rfl\n\n/-- Ceiling's two sign gates and every floor primitive are included. -/\ntheorem ceilSignedBits_cost_width {W : ℕ} {numerator : SignedWord} {denominator : List Bool}\n    (hn : numerator.magnitude.length≤W) (hd : denominator.length≤W) :\n    (ceilSignedBits numerator denominator).clock≤160*(W+1)^2 ∧\n      (ceilSignedBits numerator denominator).word.magnitude.length≤W+2 := by\n  have hc := floorSignedBits_cost_width (numerator:=negateWord numerator) hn hd\n  constructor\n  · change (floorSignedBits (negateWord numerator) denominator).clock+2≤160*(W+1)^2\n    nlinarith [hc.1]\n  · exact hc.2\n\n/-- Original inclusive signed bounds, retained as actual words. -/\nstructure WordInterval where\n  /-- Actual lower endpoint word; it may be negative or zero. -/\n  lower : SignedWord\n  /-- Actual upper endpoint word, including impossible reversed bounds. -/\n  upper : SignedWord\n\n/-- Mathematical interpretation of original bounds, never a data-path call. -/\nabbrev WordInterval.interpret (bounds : WordInterval) : IntegerInterval :=\n  ⟨bounds.lower.value,bounds.upper.value⟩\n\n/-- Original impossible [1,0] word bounds. The caller pays its one true cell. -/\ndef emptyWordInterval : WordInterval := ⟨⟨false,[true]⟩,⟨false,[]⟩⟩\n\n/-- The literal impossible word interval preserves the original empty bounds. -/\ntheorem emptyWordInterval_value : emptyWordInterval.interpret=emptyInterval := rfl\n\n/-- Both signed endpoint comparisons and the actually selected clipped bounds. -/\nstructure IntersectionWordReport where\n  /-- Original lower endpoint order, used to select the signed maximum. -/\n  lowerOrder : SignedOrderReport\n  /-- Original upper endpoint order, used to select the signed minimum. -/\n  upperOrder : SignedOrderReport\n  /-- Selected original endpoint words, sharing their physical magnitudes. -/\n  bounds : WordInterval\n  /-- Both full signed comparisons and actual endpoint decisions. -/\n  clock : ℕ\n\n/-- Clip bounds before any coordinate list is constructed. Signed order\nselects original endpoint words and does not serialize integer values. -/\ndef intersectIntervalsBits (first second : WordInterval) : IntersectionWordReport :=\n  let lowerOrder := leSignedBits first.lower second.lower\n  let upperOrder := leSignedBits first.upper second.upper\n  let lower := if lowerOrder.le=true then second.lower else first.lower\n  let upper := if upperOrder.le=true then first.upper else second.upper\n  ⟨lowerOrder,upperOrder,⟨lower,upper⟩,lowerOrder.clock+upperOrder.clock+3⟩\n\n/-- Actual endpoint selection preserves the full original signed intersection. -/\ntheorem intersectIntervalsBits_value (first second : WordInterval) :\n    (intersectIntervalsBits first second).bounds.interpret=\n      intersectInterval first.interpret second.interpret := by\n  dsimp only [intersectIntervalsBits,WordInterval.interpret,intersectInterval,\n    maxInteger,minInteger]\n  split <;> split <;> simp_all only [leSignedBits_exact] <;> rfl\n\n/-- Clipping pays both signed comparisons; selected physical endpoints\ncannot exceed the original input widths. -/\ntheorem intersectIntervalsBits_cost_width {W : ℕ} {first second : WordInterval}\n    (h0 : first.lower.magnitude.length≤W) (h1 : first.upper.magnitude.length≤W)\n    (h2 : second.lower.magnitude.length≤W) (h3 : second.upper.magnitude.length≤W) :\n    (intersectIntervalsBits first second).clock≤100*(W+1) ∧\n      (intersectIntervalsBits first second).bounds.lower.magnitude.length≤W ∧\n      (intersectIntervalsBits first second).bounds.upper.magnitude.length≤W := by\n  have hlo := leSignedBits_cost h0 h2\n  have hhi := leSignedBits_cost h1 h3\n  constructor\n  · dsimp only [intersectIntervalsBits]\n    omega\n  · unfold intersectIntervalsBits\n    dsimp only\n    constructor <;> split <;> omega\n\n/-- Original offset differences and complete signed floor/ceiling reports. -/\nstructure PositiveLinearWordReport where\n  /-- Actual lower-offset subtraction. -/\n  lowerDifference : SignedSumReport\n  /-- Actual upper-offset subtraction. -/\n  upperDifference : SignedSumReport\n  /-- Computed lower coordinate ceiling. -/\n  lowerDivision : SignedCeilReport\n  /-- Computed upper coordinate floor. -/\n  upperDivision : SignedFloorReport\n  /-- Original inclusive signed coordinate endpoints. -/\n  bounds : WordInterval\n  /-- Every subtraction, both rounded divisions and retained output decisions. -/\n  clock : ℕ\n\n/-- Compute the original positive-step coordinate bounds from actual\nsigned offsets. Rounding is performed by Boolean circuits on all words. -/\ndef positiveLinearBits (offset : SignedWord) (step : List Bool)\n    (lower upper : SignedWord) : PositiveLinearWordReport :=\n  let lo := subSignedBits lower offset\n  let hi := subSignedBits upper offset\n  let lowerDivision := ceilSignedBits lo.word step\n  let upperDivision := floorSignedBits hi.word step\n  ⟨lo,hi,lowerDivision,upperDivision,⟨lowerDivision.word,upperDivision.word⟩,\n    lo.clock+hi.clock+lowerDivision.clock+upperDivision.clock+4⟩\n\n/-- The actual signed coordinate bounds match the original floor/ceiling\nconstruction for every denominator encoding, including zero. -/\ntheorem positiveLinearBits_value (offset : SignedWord) (step : List Bool)\n    (lower upper : SignedWord) :\n    (positiveLinearBits offset step lower upper).bounds.interpret=\n      positiveLinearInterval offset.value (bitValue step) lower.value upper.value := by\n  dsimp only [positiveLinearBits,WordInterval.interpret,positiveLinearInterval]\n  apply congrArg₂ IntegerInterval.mk\n  · rw [ceilSignedBits_value,subSignedBits_value]\n  · rw [floorSignedBits_value,subSignedBits_value]\n\n/-- Both coordinate divisions include negative rounding, discarded\nincrements and all original subtraction work in a quadratic physical clock. -/\ntheorem positiveLinearBits_cost_width {W : ℕ} {offset lower upper : SignedWord} {step : List Bool}\n    (ho : offset.magnitude.length≤W) (hs : step.length≤W)\n    (hl : lower.magnitude.length≤W) (hu : upper.magnitude.length≤W) :\n    (positiveLinearBits offset step lower upper).clock≤1500*(W+1)^2 ∧\n      (positiveLinearBits offset step lower upper).bounds.lower.magnitude.length≤W+3 ∧\n      (positiveLinearBits offset step lower upper).bounds.upper.magnitude.length≤W+3 := by\n  have hlo := subSignedBits_cost_width hl ho\n  have hhi := subSignedBits_cost_width hu ho\n  have hs' : step.length≤W+1 := by omega\n  have hlower := ceilSignedBits_cost_width hlo.2 hs'\n  have hupper := floorSignedBits_cost_width hhi.2 hs'\n  dsimp only [positiveLinearBits]\n  exact ⟨by nlinarith [hlo.1,hhi.1,hlower.1,hupper.1],hlower.2,hupper.2⟩\n\n/-- Actual nonzero-step division/clipping or actual zero-step constant checks. -/\nstructure LinearClipWordReport where\n  /-- Full original step-magnitude scan, recognizing both encodings of zero. -/\n  stepNonzero : NonzeroReport\n  /-- Exact rounded bounds, only for a nonzero signed step. -/\n  positive : Option PositiveLinearWordReport\n  /-- Actual original interval clipping, only after a nonzero step. -/\n  intersection : Option IntersectionWordReport\n  /-- Both actual constant-coordinate tests, only for a zero step. -/\n  constantChecks : Option (SignedOrderReport×SignedOrderReport)\n  /-- Final original inclusive signed bounds. -/\n  bounds : WordInterval\n  /-- Complete branch clock, including sign flips and literal empty bound. -/\n  clock : ℕ\n\n/-- Execute original signed line clipping before building any coordinates.\nNegative steps negate offset/upper/lower and share the actual magnitude.\nZero steps request no rounded division and inspect both constant bounds. -/\ndef linearIntervalBits (offset step lower upper : SignedWord) (initial : WordInterval) :\n    LinearClipWordReport :=\n  let nonzero := nonzeroBits step.magnitude\n  if nonzero.nonzero=true then\n    if step.negative=true then\n      let positive := positiveLinearBits (negateWord offset) step.magnitude\n        (negateWord upper) (negateWord lower)\n      let intersection := intersectIntervalsBits initial positive.bounds\n      ⟨nonzero,some positive,some intersection,none,intersection.bounds,\n        nonzero.clock+positive.clock+intersection.clock+7⟩\n    else\n      let positive := positiveLinearBits offset step.magnitude lower upper\n      let intersection := intersectIntervalsBits initial positive.bounds\n      ⟨nonzero,some positive,some intersection,none,intersection.bounds,\n        nonzero.clock+positive.clock+intersection.clock+4⟩\n  else\n    let first := leSignedBits lower offset\n    let second := leSignedBits offset upper\n    let bounds := if (first.le && second.le)=true then initial else emptyWordInterval\n    ⟨nonzero,none,none,some (first,second),bounds,nonzero.clock+first.clock+second.clock+6⟩\n\n/-- Every original positive, negative and zero-step clipping outcome is\npreserved exactly on arbitrary signed/padded words, with no canonicality\nor valid-interval premise and no native integer branch in the data path. -/\ntheorem linearIntervalBits_value (offset step lower upper : SignedWord) (initial : WordInterval) :\n    (linearIntervalBits offset step lower upper initial).bounds.interpret=\n      linearInterval offset.value step.value lower.value upper.value initial.interpret := by\n  by_cases hn : (nonzeroBits step.magnitude).nonzero=true\n  · have hmag := (nonzeroBits_correct _).mp hn\n    by_cases hs : step.negative=true\n    · have hstep : step.value= -(bitValue step.magnitude : ℤ) := by\n        simp only [SignedWord.value,ite_eq_left hs]\n      have hnegative : step.value<0 := by rw [hstep]; omega\n      have hnotpositive : ¬0<step.value := by omega\n      unfold linearIntervalBits\n      rw [ite_eq_left hn,ite_eq_left hs]\n      dsimp only\n      rw [intersectIntervalsBits_value,positiveLinearBits_value,\n        negateWord_value,negateWord_value,negateWord_value]\n      unfold linearInterval\n      rw [ite_eq_right hnotpositive,ite_eq_left hnegative,hstep,neg_neg]\n    · have hstep : step.value=(bitValue step.magnitude : ℤ) := by\n        simp only [SignedWord.value,ite_eq_right hs]\n      have hpositive : 0<step.value := by rw [hstep]; exact_mod_cast hmag\n      unfold linearIntervalBits\n      rw [ite_eq_left hn,ite_eq_right hs]\n      dsimp only\n      rw [intersectIntervalsBits_value,positiveLinearBits_value]\n      unfold linearInterval\n      rw [ite_eq_left hpositive,hstep]\n  · have hzero := (nonzeroBits_false_iff _).mp (Bool.eq_false_of_not_eq_true hn)\n    have hstep : step.value=0 := by simp [SignedWord.value,hzero]\n    by_cases hi : lower.value≤offset.value ∧ offset.value≤upper.value\n    · have hc : ((leSignedBits lower offset).le && (leSignedBits offset upper).le)=true :=\n        (Bool.and_eq_true _ _).mpr ⟨(leSignedBits_exact _ _).mpr hi.1,(leSignedBits_exact _ _).mpr hi.2⟩\n      unfold linearIntervalBits\n      rw [ite_eq_right hn]\n      dsimp only\n      rw [ite_eq_left hc]\n      simp only [linearInterval,hstep,lt_self_iff_false,ite_false,ite_eq_left hi]\n    · have hc : ¬((leSignedBits lower offset).le && (leSignedBits offset upper).le)=true := by\n        intro h\n        obtain ⟨h0,h1⟩ := (Bool.and_eq_true _ _).mp h\n        exact hi ⟨(leSignedBits_exact _ _).mp h0,(leSignedBits_exact _ _).mp h1⟩\n      unfold linearIntervalBits\n      rw [ite_eq_right hn]\n      dsimp only\n      rw [ite_eq_right hc,emptyWordInterval_value]\n      simp only [linearInterval,hstep,lt_self_iff_false,ite_false,ite_eq_right hi]\n\n/-- Exact inclusive membership in the original clipped line, including\nempty bounds and every constant-coordinate branch. This is a specification\nof the bounds, not an implementation of coordinate-word emission. -/\ntheorem mem_linearIntervalBits (offset step lower upper : SignedWord)\n    (initial : WordInterval) (i : ℤ) :\n    i∈(linearIntervalBits offset step lower upper initial).bounds.interpret.entries ↔\n      i∈initial.interpret.entries ∧ lower.value≤offset.value+i*step.value ∧\n        offset.value+i*step.value≤upper.value := by\n  rw [linearIntervalBits_value]\n  exact mem_linearInterval _ _ _ _ _ _\n\n/-- Full signed/zero-step clipping has quadratic physical bit work and\nbounded output words. All comparisons, negative rounding, both zero-step\ntests, sign gates and literal impossible bounds are included. -/\ntheorem linearIntervalBits_cost_width {W : ℕ} {offset step lower upper : SignedWord}\n    {initial : WordInterval}\n    (ho : offset.magnitude.length≤W) (hs : step.magnitude.length≤W)\n    (hl : lower.magnitude.length≤W) (hu : upper.magnitude.length≤W)\n    (hi0 : initial.lower.magnitude.length≤W) (hi1 : initial.upper.magnitude.length≤W) :\n    (linearIntervalBits offset step lower upper initial).clock≤2000*(W+1)^2 ∧\n      (linearIntervalBits offset step lower upper initial).bounds.lower.magnitude.length≤W+3 ∧\n      (linearIntervalBits offset step lower upper initial).bounds.upper.magnitude.length≤W+3 := by\n  have hbudget : 3*W+1+1500*(W+1)^2+100*(W+4)+7≤2000*(W+1)^2 := by\n    nlinarith only []\n  have hzeroBudget : 3*W+1+40*(W+1)+40*(W+1)+6≤2000*(W+1)^2 := by\n    nlinarith only []\n  have hp := positiveLinearBits_cost_width (offset:=offset) (step:=step.magnitude)\n    (lower:=lower) (upper:=upper) ho hs hl hu\n  have hn := positiveLinearBits_cost_width (offset:=negateWord offset) (step:=step.magnitude)\n    (lower:=negateWord upper) (upper:=negateWord lower) ho hs hu hl\n  have hi0' : initial.lower.magnitude.length≤W+3 := by omega\n  have hi1' : initial.upper.magnitude.length≤W+3 := by omega\n  have hpc := intersectIntervalsBits_cost_width (first:=initial)\n    (second:=(positiveLinearBits offset step.magnitude lower upper).bounds)\n    hi0' hi1' hp.2.1 hp.2.2\n  have hnc := intersectIntervalsBits_cost_width (first:=initial)\n    (second:=(positiveLinearBits (negateWord offset) step.magnitude\n      (negateWord upper) (negateWord lower)).bounds) hi0' hi1' hn.2.1 hn.2.2\n  have hz0 := leSignedBits_cost hl ho\n  have hz1 := leSignedBits_cost ho hu\n  have hz := nonzeroBits_cost step.magnitude\n  unfold linearIntervalBits\n  dsimp only\n  split\n  · split\n    · dsimp only\n      refine ⟨?_,hnc.2⟩\n      omega\n    · dsimp only\n      refine ⟨?_,hpc.2⟩\n      omega\n  · dsimp only\n    constructor\n    · omega\n    · split\n      · exact ⟨by omega,by omega⟩\n      · change ([true] : List Bool).length≤W+3 ∧ ([] : List Bool).length≤W+3\n        simp only [List.length_cons,List.length_nil]\n        exact ⟨by omega,by omega⟩\n\nend RiemannGaussian.SemiprimeBitIndexClipping\n","RiemannGaussian.SemiprimeBooleanNetwork":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeMacroFermatNetwork\nimport Mathlib.Data.BitVec\n\n/-!\n# Concrete finite Boolean multiplication relation\n\nAll words are literal finite bit vectors with their standard little-endian\nbinary decoding. The relation explicitly checks normalized Fourier inversion,\ncanonical coefficients, INTEGER carries and nontrivial input flags. Its accepted\nextensions will be counted by an explicit equivalence, not an assumed semantic\ncorrectness premise. This finite relation does not yet assert the Python\ncompiler's exact two-stage port layout or its small-arity/wire cost.\n-/\nnamespace RiemannGaussian.SemiprimeBooleanNetwork\nopen scoped BigOperators\nattribute [local instance] Classical.propDecidable\nopen SemiprimeMacroFermatNetwork\n\n/-- Literal finite-width binary encoding. -/\ndef encode (width value : ℕ) : BitVec width := BitVec.ofNat width value\n\n/-- Literal little-endian binary decoding. -/\ndef decode {width : ℕ} (word : BitVec width) : ℕ := word.toNat\n\n/-- Encoding a value within width loses no information. -/\ntheorem decode_encode {width value : ℕ} (h : value<2^width) :\n    decode (encode width value)=value := by\n  simp [decode,encode,BitVec.toNat_ofNat,Nat.mod_eq_of_lt h]\n\n/-- Every bit word is the encoding of its decoded value. -/\ntheorem encode_decode {width : ℕ} (word : BitVec width) :\n    encode width (decode word)=word := by\n  apply BitVec.eq_of_toNat_eq\n  simp [decode,encode]\n\n/-- Binary words and their exact bounded integer values are in bijection. -/\ndef wordEquiv (width : ℕ) : BitVec width ≃ Fin (2^width) where\n  toFun word := ⟨decode word,word.isLt⟩\n  invFun value := encode width value.val\n  left_inv := encode_decode\n  right_inv value := Fin.ext (decode_encode value.isLt)\n\n/-- Enumerate exactly the actual finite binary words through their canonical values. -/\ninstance bitWordFintype (width : ℕ) : Fintype (BitVec width) :=\n  Fintype.ofEquiv (Fin (2^width)) (wordEquiv width).symm\n\n/-- Finite digit/word arrays have zero outside their declared ports. -/\ndef values {size width : ℕ} (words : Fin size→BitVec width) (i : ℕ) : ℕ :=\n  if h : i<size then decode (words ⟨i,h⟩) else 0\n\n/-- Decoding at a declared port is exact. -/\ntheorem values_at {size width : ℕ} (words : Fin size→BitVec width) (i : Fin size) :\n    values words i.val=decode (words i) := by simp [values]\n\n/-- Every decoded finite port fits its physical width. -/\ntheorem values_bound {size width : ℕ} (words : Fin size→BitVec width)\n    (i : ℕ) (hi : i<size) : values words i<2^width := by\n  simpa [values,hi,decode] using (words ⟨i,hi⟩).isLt\n\n/-- Literal integer value of the input digit ports. -/\ndef operand {digits bits : ℕ} (words : Fin digits→BitVec bits) : ℕ :=\n  ∑ i∈Finset.range digits,values words i*(2^bits)^i\n\n\n/-- Input digit arithmetic agrees with the literal least-significant-first split. -/\ntheorem operand_succ {digits bits : ℕ} (words : Fin (digits+1)→BitVec bits) :\n    operand words=decode (words 0)+2^bits*operand (fun i : Fin digits => words i.succ) := by\n  unfold operand\n  rw [radix_sum_succ]\n  rw [show values words 0=decode (words 0) by simp [values]]\n  congr 1\n  apply congrArg (fun x : ℕ => 2^bits*x)\n  apply Finset.sum_congr rfl\n  intro k hk\n  have hk' := Finset.mem_range.mp hk\n  simp only [values,show k+1<digits+1 by omega,show k<digits by omega,dite_eq_left]\n  rfl\n\n/-- Exact finite digit words always represent an integer within their total width. -/\ntheorem operand_bound {digits bits : ℕ} (words : Fin digits→BitVec bits) :\n    operand words<(2^bits)^digits := by\n  induction digits with\n  | zero => simp [operand]\n  | succ digits ih =>\n    rw [operand_succ,pow_succ]\n    have ht := ih (fun i => words i.succ)\n    have hh := (words 0).isLt\n    change decode (words 0)<2^bits at hh\n    nlinarith\n\n/-- The positional value is injective on literal fixed-length digit words. -/\ntheorem operand_injective (digits bits : ℕ) :\n    Function.Injective (operand : (Fin digits→BitVec bits)→ℕ) := by\n  induction digits with\n  | zero => intro x y h; funext i; exact Fin.elim0 i\n  | succ digits ih =>\n    intro x y he\n    rw [operand_succ,operand_succ] at he\n    have hx := (x 0).isLt\n    have hy := (y 0).isLt\n    have hhead : decode (x 0)=decode (y 0) := by\n      have hm := congrArg (fun v : ℕ => v%2^bits) he\n      simpa [Nat.add_mod,Nat.mul_mod,decode,Nat.mod_eq_of_lt hx,Nat.mod_eq_of_lt hy] using hm\n    have htail : operand (fun i : Fin digits => x i.succ)=\n        operand (fun i : Fin digits => y i.succ) := by\n      have hp : 0<(2 : ℕ)^bits := by positivity\n      nlinarith\n    have ht := ih htail\n    funext i\n    refine Fin.cases ?_ (fun j => ?_) i\n    · exact BitVec.eq_of_toNat_eq hhead\n    · exact congrFun ht j\n\n/-- Input digits are in bijection with the actual bounded integers, not\nmerely an unspecified finite set of the same size. -/\nnoncomputable def operandEquiv (digits bits : ℕ) :\n    (Fin digits→BitVec bits) ≃ Fin ((2^bits)^digits) :=\n  Equiv.ofBijective (fun words => ⟨operand words,operand_bound words⟩) (by\n    apply (Fintype.bijective_iff_injective_and_card _).mpr\n    constructor\n    · intro x y h\n      exact operand_injective digits bits (congrArg Fin.val h)\n    · have hc : Fintype.card (BitVec bits)=2^bits :=\n        (Fintype.card_congr (wordEquiv bits)).trans (Fintype.card_fin _)\n      simp only [Fintype.card_fun,Fintype.card_fin,hc])\n\n/-- The nontriviality flag checks the actual input value, not an oracle. -/\ndef nontrivialFlag {digits bits : ℕ} (words : Fin digits→BitVec bits) : Bool :=\n  decide (2≤operand words)\n\n/-- All actual internal finite Boolean words and two input flags. -/\nstructure Extension (d : ℕ) where\n  /-- Canonical inverse-output coefficient words. -/\n  coefficient : Fin (macroLength d)→BitVec (macroLength d+1)\n  /-- Physical n-bit carries, including both boundary positions. -/\n  carry : Fin (macroLength d+1)→BitVec (macroLength d)\n  /-- Nontrivial left-input flag. -/\n  leftFlag : Bool\n  /-- Nontrivial right-input flag. -/\n  rightFlag : Bool\n  deriving Fintype\n\n/-- Explicit local-predicate conjunction for the constructed finite relation.\nThe Fourier inverse formula is computed from the actual inputs, not supplied\nas a convolution-correctness hypothesis. -/\ndef Valid {digits bits : ℕ} (d : ℕ) (left right : Fin digits→BitVec bits)\n    (target : ℕ→ℕ) (extension : Extension d) : Prop :=\n  ArithmeticNetworkValid d (values left) (values right) target\n    (values extension.coefficient) (values extension.carry) digits (2^bits) ∧\n  extension.leftFlag=nontrivialFlag left ∧ extension.leftFlag=true ∧\n  extension.rightFlag=nontrivialFlag right ∧ extension.rightFlag=true\n\n/-- Explicit finite input-pair predicate corresponding to nontrivial factors. -/\ndef FactorPair {digits bits : ℕ} (left right : Fin digits→BitVec bits) (N : ℕ) : Prop :=\n  2≤operand left ∧ 2≤operand right ∧ operand left*operand right=N\n\n/-- The relation's literal nontriviality flags force both factors to exceed one. -/\ntheorem valid_nontrivial {digits bits d : ℕ} {left right : Fin digits→BitVec bits}\n    {target : ℕ→ℕ} {extension : Extension d} (h : Valid d left right target extension) :\n    2≤operand left ∧ 2≤operand right := by\n  have hl : nontrivialFlag left=true := h.2.1.symm.trans h.2.2.1\n  have hr : nontrivialFlag right=true := h.2.2.2.1.symm.trans h.2.2.2.2\n  exact ⟨of_decide_eq_true hl,of_decide_eq_true hr⟩\n\n/-- Accepted bit-word extensions imply the actual nontrivial digit product. -/\ntheorem valid_sound {digits bits d : ℕ} (left right : Fin digits→BitVec bits)\n    (target : ℕ→ℕ) (extension : Extension d)\n    (hsize : 2*digits≤macroLength d)\n    (hbound : digits*(2^bits)^2<2^(macroLength d)+1)\n    (htarget : ∀ i, i<macroLength d → target i<2^bits)\n    (h : Valid d left right target extension) :\n    FactorPair left right (∑ k∈Finset.range (macroLength d),target k*(2^bits)^k) := by\n  have hp := (arithmetic_network_iff d (values left) (values right) target digits (2^bits)\n    (by positivity) hsize (values_bound left) (values_bound right) htarget hbound).mp\n    ⟨values extension.coefficient,values extension.carry,h.1⟩\n  exact ⟨(valid_nontrivial h).1,(valid_nontrivial h).2,hp⟩\n\n/-- The constructed finite Boolean relation has at most one internal\nextension for each input pair, including every physical carry bit. -/\ntheorem valid_unique {digits bits d : ℕ} (left right : Fin digits→BitVec bits)\n    (target : ℕ→ℕ) (first second : Extension d)\n    (hsize : 2*digits≤macroLength d)\n    (hbound : digits*(2^bits)^2<2^(macroLength d)+1)\n    (hfirst : Valid d left right target first)\n    (hsecond : Valid d left right target second) : first=second := by\n  have hu := arithmetic_network_unique d (values left) (values right) target\n    (values first.coefficient) (values second.coefficient)\n    (values first.carry) (values second.carry) digits (2^bits) (by positivity)\n    hsize (values_bound left) (values_bound right) hbound hfirst.1 hsecond.1\n  have hc : first.coefficient=second.coefficient := by\n    funext j\n    apply BitVec.eq_of_toNat_eq\n    simpa only [values_at,decode] using hu.1 j.val j.isLt\n  have hk : first.carry=second.carry := by\n    funext j\n    apply BitVec.eq_of_toNat_eq\n    simpa only [values_at,decode] using hu.2 j.val (by have := j.isLt; omega)\n  have hl : first.leftFlag=second.leftFlag := hfirst.2.1.trans hsecond.2.1.symm\n  have hr : first.rightFlag=second.rightFlag := hfirst.2.2.2.1.trans hsecond.2.2.2.1.symm\n  cases first\n  cases second\n  simp_all\n\n/-- Every true nontrivial input product has a valid finite bit extension.\nThe strict physical carry capacity is derived, not assumed as a witness. -/\ntheorem valid_complete {digits bits d : ℕ} (left right : Fin digits→BitVec bits)\n    (target : ℕ→ℕ) (hbits : 0<bits) (hquarter : macroLength d=4*bits)\n    (hdigits : digits≤bits) (htarget : ∀ i, i<macroLength d → target i<2^bits)\n    (hpair : FactorPair left right\n      (∑ k∈Finset.range (macroLength d),target k*(2^bits)^k)) :\n    ∃ extension,Valid d left right target extension := by\n  let n := macroLength d\n  have hn : 0<n := by dsimp [n,macroLength]; positivity\n  have hsize : 2*digits≤n := by dsimp [n]; omega\n  have hstrict := compiler_quarter_strict_bound digits bits n hdigits hbits hquarter\n  have hbound : digits*(2^bits)^2<2^n+1 := by omega\n  obtain ⟨output,carry,harith⟩ :=\n    (arithmetic_network_iff d (values left) (values right) target digits (2^bits)\n      (by positivity) hsize (values_bound left) (values_bound right) htarget hbound).mpr hpair.2.2\n  have heq := canonical_inverse_convolution d (values left) (values right) output\n    digits (2^bits) hsize (values_bound left) (values_bound right) hbound harith.1 harith.2.1\n  have hc : ∀ k, k<n → output k≤digits*(2^bits)^2 := by\n    intro k hk\n    rw [heq k hk]\n    exact convolution_bound _ _ digits (2^bits) k (values_bound left) (values_bound right)\n  have hcap := compiler_carry_capacity output target carry digits bits n hdigits hbits\n    hquarter harith.2.2.1 hc harith.2.2.2.2\n  have hout : ∀ k, k<n → output k<2^(n+1) := by\n    intro k hk\n    have hp : 0<(2 : ℕ)^n := by positivity\n    have hh := harith.1 k hk\n    change output k<2^n+1 at hh\n    rw [pow_succ]\n    omega\n  let extension : Extension d :=\n    ⟨fun i => encode (n+1) (output i.val),fun i => encode n (carry i.val),\n      nontrivialFlag left,nontrivialFlag right⟩\n  have ho : ∀ k, k<n → values extension.coefficient k=output k := by\n    intro k hk\n    exact (values_at extension.coefficient ⟨k,hk⟩).trans (decode_encode (hout k hk))\n  have hh : ∀ k, k≤n → values extension.carry k=carry k := by\n    intro k hk\n    exact (values_at extension.carry ⟨k,by omega⟩).trans (decode_encode (hcap k hk))\n  refine ⟨extension,?_,rfl,?_,rfl,?_⟩\n  · refine ⟨?_,?_,?_,?_,?_⟩\n    · intro k hk\n      rw [ho k hk]\n      exact harith.1 k hk\n    · intro k hk\n      rw [ho k hk]\n      exact harith.2.1 k hk\n    · rw [hh 0 (by omega)]\n      exact harith.2.2.1\n    · rw [hh n (by omega)]\n      exact harith.2.2.2.1\n    · intro k hk\n      rw [ho k hk,hh k (by omega),hh (k+1) (by omega)]\n      exact harith.2.2.2.2 k hk\n  · exact decide_eq_true hpair.1\n  · exact decide_eq_true hpair.2.1\n\n/-- One accepted input pair contributes exactly one Boolean extension;\na false pair contributes none. No extension-count oracle is assumed. -/\ntheorem extension_count {digits bits d : ℕ} (left right : Fin digits→BitVec bits)\n    (target : ℕ→ℕ) (hbits : 0<bits) (hquarter : macroLength d=4*bits)\n    (hdigits : digits≤bits) (htarget : ∀ i, i<macroLength d → target i<2^bits) :\n    (∑ extension : Extension d,if Valid d left right target extension then (1 : ℕ) else 0)=\n      if FactorPair left right\n        (∑ k∈Finset.range (macroLength d),target k*(2^bits)^k) then 1 else 0 := by\n  classical\n  have hsize : 2*digits≤macroLength d := by omega\n  have hstrict := compiler_quarter_strict_bound digits bits (macroLength d) hdigits hbits hquarter\n  have hbound : digits*(2^bits)^2<2^(macroLength d)+1 := by omega\n  by_cases hp : FactorPair left right\n      (∑ k∈Finset.range (macroLength d),target k*(2^bits)^k)\n  · rw [ite_eq_left hp]\n    obtain ⟨extension,he⟩ := valid_complete left right target hbits hquarter hdigits htarget hp\n    rw [Finset.sum_eq_single extension]\n    · exact ite_eq_left he\n    · intro other ho hne\n      apply ite_eq_right\n      intro hother\n      exact hne (valid_unique left right target other extension hsize hbound hother he)\n    · intro hnot\n      exact False.elim (hnot (Finset.mem_univ extension))\n  · rw [ite_eq_right hp]\n    apply Finset.sum_eq_zero\n    intro extension he\n    apply ite_eq_right\n    intro hv\n    exact hp (valid_sound left right target extension hsize hbound htarget hv)\n\n/-- The literal 0/1 Boolean-relation contraction over all input and internal\nbit words. This is a definition by finite sums, not an execution-time claim. -/\nnoncomputable def contraction (d digits bits : ℕ) (target : ℕ→ℕ) : ℕ := by\n  classical\n  exact ∑ left : Fin digits→BitVec bits,∑ right : Fin digits→BitVec bits,\n    ∑ extension : Extension d,if Valid d left right target extension then 1 else 0\n\n/-- The constructed Boolean relation counts precisely the ordered nontrivial\nINTEGER factor pairs within its input width. The only numerical premises are\npublic radix, coefficient-capacity and target-digit bounds. -/\ntheorem contraction_counts_factor_pairs (d digits bits : ℕ) (target : ℕ→ℕ)\n    (hbits : 0<bits) (hquarter : macroLength d=4*bits) (hdigits : digits≤bits)\n    (htarget : ∀ i, i<macroLength d → target i<2^bits) :\n    contraction d digits bits target=\n      ∑ P : Fin ((2^bits)^digits),∑ Q : Fin ((2^bits)^digits),\n        if 2≤P.val ∧ 2≤Q.val ∧ P.val*Q.val=\n          (∑ k∈Finset.range (macroLength d),target k*(2^bits)^k) then 1 else 0 := by\n  classical\n  unfold contraction\n  simp_rw [extension_count _ _ target hbits hquarter hdigits htarget]\n  apply Fintype.sum_equiv (operandEquiv digits bits)\n  intro left\n  apply Fintype.sum_equiv (operandEquiv digits bits)\n  intro right\n  simp only [FactorPair,operandEquiv,Equiv.ofBijective_apply]\n  split_ifs with h <;> simp [h]\n\n/-- The bit vector is precisely its ordered list of Boolean least-significant\nports; thus the relation really is a finite Boolean assignment relation. -/\ntheorem bit_ports_bijective (width : ℕ) :\n    Function.Bijective (fun word : BitVec width => word.getLsb) := by\n  apply (Fintype.bijective_iff_injective_and_card _).mpr\n  constructor\n  · intro x y he\n    apply BitVec.eq_of_getLsbD_eq\n    intro i hi\n    exact congrFun he ⟨i,hi⟩\n  · have hc : Fintype.card (BitVec width)=2^width :=\n      (Fintype.card_congr (wordEquiv width)).trans (Fintype.card_fin _)\n    simpa only [Fintype.card_fun,Fintype.card_fin,Fintype.card_bool] using hc\n\n/-- Literal Boolean port conversion, with no unspecified enumeration. -/\nnoncomputable def bitPortsEquiv (width : ℕ) : BitVec width ≃ (Fin width→Bool) :=\n  Equiv.ofBijective (fun word => word.getLsb) (bit_ports_bijective width)\n\n/-- Subdividing every Boolean edge inserts one actual equality predicate;\nevery original accepted assignment has exactly one copy assignment. -/\ntheorem equality_subdivision_count {I : Type*} [Fintype I] (accepted : (I→Bool)→Prop) :\n    (∑ original : I→Bool,∑ copy : I→Bool,\n      if (∀ i,copy i=original i) ∧ accepted original then (1 : ℕ) else 0)=\n      ∑ original : I→Bool,if accepted original then 1 else 0 := by\n  classical\n  apply Finset.sum_congr rfl\n  intro original ho\n  have he : (∑ copy : I→Bool,\n      if (∀ i,copy i=original i) ∧ accepted original then (1 : ℕ) else 0)=\n      ∑ copy : I→Bool,if copy=original then (if accepted original then 1 else 0) else 0 := by\n    apply Finset.sum_congr rfl\n    intro copy hc\n    by_cases hp : copy=original\n    · subst copy\n      simp\n    · have hn : ¬∀ i,copy i=original i := fun h => hp (funext h)\n      simp [hp,hn]\n  rw [he]\n  simp\n\n/-- Explicit vertices of the constructed finite relational network. -/\ninductive Check (d : ℕ)\n  | canonical : Fin (macroLength d)→Check d\n  | inverse : Fin (macroLength d)→Check d\n  | carry : Fin (macroLength d)→Check d\n  | initial : Check d\n  | terminal : Check d\n  | leftValue : Check d\n  | leftTrue : Check d\n  | rightValue : Check d\n  | rightTrue : Check d\n  deriving DecidableEq,Fintype\n\n/-- Literal local arithmetic/flag predicates; the inverse vertex reads all\ninput digits but only its single output coefficient. Its scope is therefore\nlarger than the Python compiler's two-stage macro implementation. -/\ndef localCheck {digits bits : ℕ} (d : ℕ) (left right : Fin digits→BitVec bits)\n    (target : ℕ→ℕ) (extension : Extension d) : Check d→Prop\n  | .canonical j => values extension.coefficient j.val<2^(macroLength d)+1\n  | .inverse j =>\n      (macroLength d : MacroRing d)*(values extension.coefficient j.val : MacroRing d)=\n        fourier 4 (macroLength d)\n          (fun k => fourier 4 digits (fun i => (values left i : MacroRing d)) k*\n            fourier 4 digits (fun i => (values right i : MacroRing d)) k)\n          (if j.val=0 then 0 else macroLength d-j.val)\n  | .carry j => values extension.coefficient j.val+values extension.carry j.val=\n      target j.val+2^bits*values extension.carry (j.val+1)\n  | .initial => values extension.carry 0=0\n  | .terminal => values extension.carry (macroLength d)=0\n  | .leftValue => extension.leftFlag=nontrivialFlag left\n  | .leftTrue => extension.leftFlag=true\n  | .rightValue => extension.rightFlag=nontrivialFlag right\n  | .rightTrue => extension.rightFlag=true\n\n/-- Validity is DERIVED equivalent to all literal local checks. -/\ntheorem valid_iff_local {digits bits d : ℕ} (left right : Fin digits→BitVec bits)\n    (target : ℕ→ℕ) (extension : Extension d) :\n    Valid d left right target extension ↔ ∀ check,localCheck d left right target extension check := by\n  constructor\n  · intro h check\n    cases check with\n    | canonical j => exact h.1.1 j.val j.isLt\n    | inverse j => exact h.1.2.1 j.val j.isLt\n    | carry j => exact h.1.2.2.2.2 j.val j.isLt\n    | initial => exact h.1.2.2.1\n    | terminal => exact h.1.2.2.2.1\n    | leftValue => exact h.2.1\n    | leftTrue => exact h.2.2.1\n    | rightValue => exact h.2.2.2.1\n    | rightTrue => exact h.2.2.2.2\n  · intro h\n    refine ⟨⟨?_,?_,h .initial,h .terminal,?_⟩,\n      h .leftValue,h .leftTrue,h .rightValue,h .rightTrue⟩\n    · intro j hj\n      exact h (.canonical ⟨j,hj⟩)\n    · intro j hj\n      exact h (.inverse ⟨j,hj⟩)\n    · intro j hj\n      exact h (.carry ⟨j,hj⟩)\n\n/-- Every local tensor is an actual computed zero/one predicate. -/\nnoncomputable def localEntry {digits bits : ℕ} (d : ℕ) (left right : Fin digits→BitVec bits)\n    (target : ℕ→ℕ) (extension : Extension d) (check : Check d) : ℕ :=\n  if localCheck d left right target extension check then 1 else 0\n\n/-- The local tensor product agrees with validity; no graph-semantic\ncorrectness assumption is used. -/\ntheorem local_product {digits bits d : ℕ} (left right : Fin digits→BitVec bits)\n    (target : ℕ→ℕ) (extension : Extension d) :\n    (∏ check : Check d,localEntry d left right target extension check)=\n      if Valid d left right target extension then 1 else 0 := by\n  classical\n  by_cases hp : Valid d left right target extension\n  · rw [ite_eq_left hp]\n    apply Finset.prod_eq_one\n    intro check hc\n    exact ite_eq_left ((valid_iff_local left right target extension).mp hp check)\n  · rw [ite_eq_right hp]\n    have hn : ¬∀ check,localCheck d left right target extension check :=\n      fun h => hp ((valid_iff_local left right target extension).mpr h)\n    obtain ⟨check,hcheck⟩ := not_forall.mp hn\n    apply Finset.prod_eq_zero (Finset.mem_univ check)\n    exact ite_eq_right hcheck\n\n/-- Summing the literal local 0/1 tensor product counts nontrivial factor\npairs. The displayed larger inverse scopes are not a free small-port compiler. -/\ntheorem local_contraction_counts_factor_pairs (d digits bits : ℕ) (target : ℕ→ℕ)\n    (hbits : 0<bits) (hquarter : macroLength d=4*bits) (hdigits : digits≤bits)\n    (htarget : ∀ i, i<macroLength d → target i<2^bits) :\n    (∑ left : Fin digits→BitVec bits,∑ right : Fin digits→BitVec bits,\n      ∑ extension : Extension d,∏ check : Check d,localEntry d left right target extension check)=\n      ∑ P : Fin ((2^bits)^digits),∑ Q : Fin ((2^bits)^digits),\n        if 2≤P.val ∧ 2≤Q.val ∧ P.val*Q.val=\n          (∑ k∈Finset.range (macroLength d),target k*(2^bits)^k) then 1 else 0 := by\n  simp_rw [local_product]\n  exact contraction_counts_factor_pairs d digits bits target hbits hquarter hdigits htarget\n\nend RiemannGaussian.SemiprimeBooleanNetwork\n","RiemannGaussian.SemiprimeD1BinaryDigitAcquisition":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackTransformBounds\nimport RiemannGaussian.SemiprimeD1StackDigitBankBounds\n\n/-! # Original-input transform and full digit-bank acquisition\nOne fixed finite program starts with ONLY binary N. It executes the complete\ntransform supplier, physically copies its retained N and acquired radix tally,\nthen executes the complete EOF-driven digit bank. No prepared metadata, width,\ndigit count, digit value or evaluator is a caller input.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 700000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1BinaryDigitAcquisition\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace Meta\nexport SemiprimeD1StackTransform (Stack Label Local program input initial)\nend Meta\nnamespace Bank\nexport SemiprimeD1StackDigitBank (Stack Label program original output)\nend Bank\n\n/-- All metadata/bank data and one real copy-restoration stack are fixed before input. -/\nabbrev Stack := Meta.Stack⊕(Bank.Stack⊕Unit)\n\n/-- Fixed literal pipeline control. -/\ninductive Control where\n  | start | copyInput | copyRadix | bankCall | done\n  deriving DecidableEq,Repr\n\n/-- Explicit fixed control catalogue, independent of all input sizes. -/\ninstance : Fintype Control := Fintype.ofList [.start,.copyInput,.copyRadix,.bankCall,.done]\n  (by intro k;cases k <;> simp)\n\n/-- Fixed nested component labels, not input-sized bytecode. -/\nabbrev Label := Control⊕(Meta.Label⊕((Bool×Fin 9)⊕Bank.Label))\n\n/-- Static metadata-stack inclusion. -/\ndef metaStack : Meta.Stack→Stack := Sum.inl\n/-- Static bank-stack inclusion. -/\ndef bankStack (k : Bank.Stack) : Stack := .inr (.inl k)\n/-- One literal restoration stack for both inter-stage copy calls. -/\ndef copyTemporary : Stack := .inr (.inr ())\n\n/-- Literal control label. -/\ndef mainLabel : Control→Label := Sum.inl\n/-- Literal metadata code inclusion. -/\ndef metaLabel (l : Meta.Label) : Label := .inr (.inl l)\n/-- Literal inter-stage copy code inclusion. -/\ndef copyLabel (radix : Bool) (l : Fin 9) : Label := .inr (.inr (.inl (radix,l)))\n/-- Literal full bank code inclusion. -/\ndef bankLabel (l : Bank.Label) : Label := .inr (.inr (.inr l))\n\n/-- Actual retained source is original binary input or physically acquired radix. -/\ndef copySource (radix : Bool) : Stack := metaStack (if radix then .radix else .input)\n/-- Actual bank destination is original binary word or cached physical width. -/\ndef copyTarget (radix : Bool) : Stack := bankStack (if radix then .inl .width else Bank.original)\n\n/-- Real three-stack copy operand map; nothing is preloaded by the caller. -/\ndef copyStack (radix : Bool) : Fin 3→Stack :=\n  fun k=>if k=0 then copySource radix else if k=1 then copyTarget radix else copyTemporary\n\n/-- Complete finite instruction table, preserving both components' nested calls. -/\ndef program : Label→C.Instruction Stack Label\n  | .inl .start => .call (metaLabel (.inl .start)) (mainLabel .copyInput)\n  | .inl .copyInput => .call (copyLabel false 0) (mainLabel .copyRadix)\n  | .inl .copyRadix => .call (copyLabel true 0) (mainLabel .bankCall)\n  | .inl .bankCall => .call (bankLabel (SemiprimeD1StackDigitBank.control .start)) (mainLabel .done)\n  | .inl .done => .base .halt\n  | .inr (.inl l) => SemiprimeD1StackValidationLink.instruction metaStack metaLabel (Meta.program l)\n  | .inr (.inr (.inl (r,l))) =>\n      SemiprimeD1StackMultiplierLink.instruction (copyStack r) (copyLabel r) (SemiprimeD1StackCopy.code l)\n  | .inr (.inr (.inr l)) => SemiprimeD1StackValidationLink.instruction bankStack bankLabel (Bank.program l)\n\n/-- Literal combined physical store; no runtime answer is synthesized by this proof view. -/\ndef store (metadata : Meta.Stack→List Bool) (bank : Bank.Stack→List Bool) (temporary : List Bool) : Stack→List Bool :=\n  Sum.elim metadata (Sum.elim bank (fun _=>temporary))\n\n/-- True original-input initial data, every bank/copy/derived metadata stack empty. -/\ndef input (bits : List Bool) : Stack→List Bool := store (Meta.input bits) (fun _=>[]) []\n\n/-- Original-input source state before any metadata call. -/\ndef initial (bits : List Bool) : C.State Stack Label := ⟨some (mainLabel .start),none,none,input bits,[]⟩\n\n/-- All real inter-stage copy stacks are distinct. -/\ntheorem copyStack_injective (radix : Bool) : Function.Injective (copyStack radix) := by\n  intro i j h\n  cases radix <;> fin_cases i <;> fin_cases j <;>\n    simp_all [copyStack,copySource,copyTarget,copyTemporary,metaStack,bankStack,SemiprimeD1StackDigitBank.original]\n\n/-- One fixed actual machine whose sole initial input is the original binary integer. -/\ndef machine : Turing.FinTM2 :=\n  SemiprimeD1StackCalls.machine (metaStack .input) (bankStack Bank.output) (mainLabel .start) program\n\n/-- Every data/return alphabet is finite and fixed before N. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite (metaStack .input) (bankStack Bank.output) (mainLabel .start) program\n\n/-- Internal control is finite, containing no native N/digit/cache answer. -/\ntheorem control_finite : Finite machine.σ :=\n  SemiprimeD1StackCalls.control_finite (metaStack .input) (bankStack Bank.output) (mainLabel .start) program\n\nend RiemannGaussian.SemiprimeD1BinaryDigitAcquisition\n","RiemannGaussian.SemiprimeD1BoundaryLeafLoad":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1BoundaryLeafReport\nimport RiemannGaussian.SemiprimeD1BoundaryLeafPorts\nimport RiemannGaussian.SemiprimeD1BoundaryPotential\n\n/-! # Actual leaf dimensions and acquired partition loads -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1BoundaryLeafLoad\nopen SemiprimeD1BoundaryPlan (Graph Load loadValue)\nopen SemiprimeD1BoundaryLeaf\nopen SemiprimeD1BoundaryLeafPorts\n\n/-- Removing index metadata does not change a source predicate's selected count. -/\ntheorem selected_length {α : Type} (xs : List α) (f : α → Bool) :\n    (selectedIndices xs (fun x => f x.1)).length=(xs.filter f).length := by\n  unfold selectedIndices\n  rw [List.length_map,←List.length_map (f:=Prod.fst)]\n  have h : ((xs.zipIdx.filter (fun x => f x.1)).map Prod.fst)=xs.filter f := by\n    change List.map Prod.fst (List.filter (f ∘ Prod.fst) xs.zipIdx)=_\n    rw [←List.filter_map]\n    simp\n  rw [h]\n\n/-- Every actual class incident catalogue is exactly its acquired load count. -/\ntheorem bucket_load (g : Graph) (colours : List Nat) (c : Nat) :\n    (classPorts g colours c).1.length=loadValue g colours (.bucket c) := by\n  exact selected_length g.edges (fun e => colours.getD e.1 0==c || colours.getD e.2 0==c)\n\n/-- A generic source-ordinal scan for a colour endpoint predicate. -/\ndef scan (g : Graph) (f : Nat → Nat → Bool) (colours : List Nat) : List Nat :=\n  selectedIndices g.edges (fun x => f (colours.getD x.1.1 0) (colours.getD x.1.2 0))\n\n/-- The actual prefix boundary predicate. -/\ndef prefixBoundary (j a b : Nat) : Bool := (a<j)!=(b<j)\n\n/-- One colour's actual boundary predicate. -/\ndef colourBoundary (c a b : Nat) : Bool := (a==c)!=(b==c)\n\n/-- Prefix and next-colour membership are exclusive at each endpoint. -/\ntheorem boundary_step (j a b : Nat) :\n    (prefixBoundary j a b != colourBoundary j a b)=prefixBoundary (j+1) a b := by\n  unfold prefixBoundary colourBoundary\n  by_cases ha : a<j <;> by_cases hb : b<j <;>\n    by_cases hea : a=j <;> by_cases heb : b=j <;>\n      simp [ha,hb,hea,heb,show (a<j+1 ↔ a<j ∨ a=j) by omega,\n        show (b<j+1 ↔ b<j ∨ b=j) by omega]\n\n/-- Endpoints in different prefix/next/future regions are exactly the union\nof the two old boundaries. -/\ntheorem union_step (j a b : Nat) :\n    (prefixBoundary j a b || colourBoundary j a b)=\n      SemiprimeD1BoundaryPlan.indicator (.merge (j+1)) a b := by\n  unfold prefixBoundary colourBoundary SemiprimeD1BoundaryPlan.indicator SemiprimeD1BoundaryPlan.region\n  simp only [Nat.add_sub_cancel]\n  by_cases ha : a<j <;> by_cases hb : b<j <;>\n    by_cases hea : a=j <;> by_cases heb : b=j <;> simp [ha,hb,hea,heb]\n\n/-- Original endpoints at an ordinal, with the runtime's actual defaults. -/\ndef endpoints (g : Graph) (colours : List Nat) (p : Nat) : Nat × Nat :=\n  let e:=g.edges.getD p (0,0)\n  (colours.getD e.1 0,colours.getD e.2 0)\n\ntheorem scan_mem (g : Graph) (f : Nat → Nat → Bool) (colours : List Nat) (p : Nat) :\n    p∈scan g f colours ↔ p<g.edges.length ∧ f (endpoints g colours p).1 (endpoints g colours p).2=true := by\n  by_cases hp : p<g.edges.length\n  · simp only [scan,selectedIndices_mem _ _ p hp,endpoints,List.getD_eq_getElem _ _ hp,true_and,hp]\n  · constructor\n    · intro h\n      exact False.elim (hp (selectedIndices_lt _ _ p h))\n    · exact fun h => False.elim (hp h.1)\n\n/-- Two boundary lists model a particular actual endpoint predicate. -/\ndef Models (g : Graph) (colours : List Nat) (f : Nat → Nat → Bool) (xs : List Nat) : Prop :=\n  xs.Nodup ∧ ∀p,p∈xs ↔ p∈scan g f colours\n\ntheorem colour_models (g : Graph) (colours : List Nat) (c : Nat) :\n    Models g colours (colourBoundary c) (classPorts g colours c).2 := by\n  exact ⟨(classPorts_nodup g colours c).2,fun _ => Iff.rfl⟩\n\n/-- Actual symmetric difference updates the precise prefix boundary. -/\ntheorem remaining_models (g : Graph) (colours : List Nat) (j : Nat) (left right : List Nat)\n    (hl : Models g colours (prefixBoundary j) left)\n    (hr : Models g colours (colourBoundary j) right) :\n    Models g colours (prefixBoundary (j+1)) (remainingPorts left right) := by\n  refine ⟨remainingPorts_nodup left right,?_⟩\n  intro p\n  rw [remainingPorts_mem,hl.2,hr.2]\n  simp only [scan_mem]\n  by_cases hp : p<g.edges.length\n  · simp only [hp,true_and]\n    have h:=boundary_step j (endpoints g colours p).1 (endpoints g colours p).2\n    cases hleft : prefixBoundary j (endpoints g colours p).1 (endpoints g colours p).2 <;>\n      cases hright : colourBoundary j (endpoints g colours p).1 (endpoints g colours p).2 <;>\n        simp_all\n  · simp [hp]\n\n/-- The physically enumerated union has precisely its three-region load size. -/\ntheorem union_load (g : Graph) (colours : List Nat) (j : Nat) (left right : List Nat)\n    (hl : Models g colours (prefixBoundary j) left)\n    (hr : Models g colours (colourBoundary j) right) :\n    (unionPorts left right).length=loadValue g colours (.merge (j+1)) := by\n  have hn:=selectedIndices_nodup g.edges\n    (fun x => SemiprimeD1BoundaryPlan.indicator (.merge (j+1)) (colours.getD x.1.1 0) (colours.getD x.1.2 0))\n  have hperm : (unionPorts left right).Perm\n      (scan g (SemiprimeD1BoundaryPlan.indicator (.merge (j+1))) colours) := by\n    apply (List.perm_ext_iff_of_nodup (unionPorts_nodup left right) hn).mpr\n    intro p\n    change p∈unionPorts left right ↔ p∈scan g (SemiprimeD1BoundaryPlan.indicator (.merge (j+1))) colours\n    rw [unionPorts_mem,hl.2,hr.2]\n    simp only [scan_mem]\n    by_cases hp : p<g.edges.length\n    · simp only [hp,true_and]\n      rw [←union_step]\n      simp\n    · simp [hp]\n  exact hperm.length_eq.trans (selected_length g.edges\n    (fun e => SemiprimeD1BoundaryPlan.indicator (.merge (j+1))\n      (colours.getD e.1 0) (colours.getD e.2 0)))\n\n/-- The runtime's actual chain keeps the prefix boundary at each step. -/\ntheorem mergeWidth_chain (ctx : SemiprimeD1JetAxes.Context) (g : Graph) (vs : List Vertex)\n    (colours : List Nat) (j n W : Nat) (first : SemiprimeD1BoundaryRecords.Tensor)\n    (hfirst : Models g colours (prefixBoundary j) first.ports)\n    (hloads : ∀i,j≤ i → i<j+n → loadValue g colours (.merge (i+1))≤ W) :\n    SemiprimeD1BoundaryLeafBounds.mergeWidth ctx first\n      ((List.range' j n).map (fun c => (bucket ctx g vs colours c).value))≤ W := by\n  induction n generalizing j first with\n  | zero => simp only [List.range'_zero,List.map_nil,SemiprimeD1BoundaryLeafBounds.mergeWidth]; omega\n  | succ n ih =>\n    have hr:=colour_models g colours j\n    have hu:=union_load g colours j first.ports (classPorts g colours j).2 hfirst hr\n    have hrem:=remaining_models g colours j first.ports (classPorts g colours j).2 hfirst hr\n    have htail:=ih (j+1) (SemiprimeD1BoundaryLeaf.merge ctx first (bucket ctx g vs colours j).value).value\n      hrem (fun i hi hj => hloads i (by omega) (by omega))\n    rw [List.range'_succ,List.map_cons,SemiprimeD1BoundaryLeafBounds.mergeWidth]\n    apply max_le\n    · exact hu.le.trans (hloads j (by omega) (by omega))\n    · exact htail\n\n/-- A list maximum fold dominates every stored measured load. -/\ntheorem member_le_foldl (xs : List Nat) (x a : Nat) (hx : x∈xs) : x≤ xs.foldl max a := by\n  induction xs generalizing a with\n  | nil => simp at hx\n  | cons y ys ih =>\n    simp only [List.foldl_cons]\n    rcases List.mem_cons.mp hx with rfl | hx\n    · have aux : ∀(xs : List Nat) (a : Nat),a≤ xs.foldl max a := by\n        intro xs a\n        induction xs generalizing a with\n        | nil => rfl\n        | cons x xs ih => exact (Nat.le_max_left _ _).trans (ih _)\n      exact (Nat.le_max_right a x).trans (aux ys (max a x))\n    · exact ih _ hx\n\n/-- Every load measured by actual acquisition is below its retained width. -/\ntheorem load_le_width (g : Graph) (l : Load)\n    (hl : l∈SemiprimeD1BoundaryPlan.loads (SemiprimeD1BoundaryPlan.acquire g).k) :\n    loadValue g (SemiprimeD1BoundaryPlan.acquire g).colours l≤\n      (SemiprimeD1BoundaryPlan.acquire g).width := by\n  apply member_le_foldl _ _ 0\n  exact List.mem_map.mpr ⟨l,hl,rfl⟩\n\n/-- Every actual bucket incident dimension is one of the acquired loads. -/\ntheorem acquired_bucket_le (g : Graph) (c : Nat)\n    (hc : c<(SemiprimeD1BoundaryPlan.acquire g).k) :\n    (classPorts g (SemiprimeD1BoundaryPlan.acquire g).colours c).1.length≤\n      (SemiprimeD1BoundaryPlan.acquire g).width := by\n  rw [bucket_load]\n  apply load_le_width\n  exact List.mem_append_left _ (List.mem_map.mpr ⟨c,List.mem_range.mpr hc,rfl⟩)\n\n/-- Exact final prefix metadata for the executed consecutive merge chain. -/\ntheorem mergeAll_models (ctx : SemiprimeD1JetAxes.Context) (g : Graph) (vs : List Vertex)\n    (colours : List Nat) (j n : Nat) (first : SemiprimeD1BoundaryRecords.Tensor)\n    (hfirst : Models g colours (prefixBoundary j) first.ports) :\n    Models g colours (prefixBoundary (j+n))\n      (mergeAll ctx first ((List.range' j n).map (fun c => (bucket ctx g vs colours c).value))).value.ports := by\n  induction n generalizing j first with\n  | zero => simpa only [List.range'_zero,List.map_nil,mergeAll,Nat.add_zero] using hfirst\n  | succ n ih =>\n    have hr:=colour_models g colours j\n    have hrem:=remaining_models g colours j first.ports (classPorts g colours j).2 hfirst hr\n    have ht:=ih (j+1) (SemiprimeD1BoundaryLeaf.merge ctx first (bucket ctx g vs colours j).value).value hrem\n    simpa only [List.range'_succ,List.map_cons,mergeAll,Nat.add_assoc,Nat.add_comm 1 n] using ht\n\n/-- The first actual class is exactly the first prefix boundary. -/\ntheorem initial_models (g : Graph) (colours : List Nat) :\n    Models g colours (prefixBoundary 1) (classPorts g colours 0).2 := by\n  have h:=colour_models g colours 0\n  have he : colourBoundary 0=prefixBoundary 1 := by\n    funext a b\n    by_cases ha : a=0 <;> by_cases hb : b=0 <;> simp [colourBoundary,prefixBoundary,ha,hb]\n  rw [he] at h\n  exact h\n\n/-- The acquired class list has its literal first bucket and consecutive tail. -/\ntheorem buckets_split (ctx : SemiprimeD1JetAxes.Context) (g : Graph) (vs : List Vertex)\n    (colours : List Nat) (k : Nat) (hk : 0<k) :\n    (List.range k).map (bucket ctx g vs colours)=\n      bucket ctx g vs colours 0::(List.range' 1 (k-1)).map (bucket ctx g vs colours) := by\n  cases k with\n  | zero => omega\n  | succ n => simp only [List.range_eq_range',List.range'_succ,List.map_cons,Nat.add_sub_cancel,Nat.zero_add]\n\n/-- Actual closed leaf output metadata models the entire acquired prefix. -/\ntheorem acquired_models (ctx : SemiprimeD1JetAxes.Context) (net : Network) :\n    Models (SemiprimeD1BoundaryPlan.graph net)\n      (SemiprimeD1BoundaryPlan.acquire (SemiprimeD1BoundaryPlan.graph net)).colours\n      (prefixBoundary (SemiprimeD1BoundaryPlan.acquire (SemiprimeD1BoundaryPlan.graph net)).k)\n      (acquire ctx net).tensor.ports := by\n  let g:=SemiprimeD1BoundaryPlan.graph net\n  let vs:=SemiprimeD1TensorNetwork.vertices net\n  let plan:=SemiprimeD1BoundaryPlan.acquire g\n  have hk : 0<plan.k := by have h:=(SemiprimeD1BoundaryChoice.chooseK_bounds g).1; exact lt_of_lt_of_le (by omega : 0<2) h\n  have hs:=buckets_split ctx g vs plan.colours plan.k hk\n  have hm:=mergeAll_models ctx g vs plan.colours 1 (plan.k-1)\n    (bucket ctx g vs plan.colours 0).value (initial_models g plan.colours)\n  have hk':1+(plan.k-1)=plan.k := by omega\n  rw [hk'] at hm\n  change Models g plan.colours (prefixBoundary plan.k)\n    (mergeAll ctx (((List.range plan.k).map (bucket ctx g vs plan.colours)).headD ⟨⟨[],[]⟩,1⟩).value\n      ((((List.range plan.k).map (bucket ctx g vs plan.colours)).tail).map SemiprimeD1BoundaryPlan.Work.value)).value.ports\n  rw [hs]\n  simpa only [List.headD_cons,List.tail_cons,List.map_map,Function.comp_def] using hm\n\n/-- Closed acquisition colours every endpoint inside its own actual menu. -/\ntheorem acquired_endpoint_colours (g : Graph) (hvalid : SemiprimeD1BoundaryPotential.Valid g)\n    (p : Nat) (hp : p<g.edges.length) :\n    (endpoints g (SemiprimeD1BoundaryPlan.acquire g).colours p).1<(SemiprimeD1BoundaryPlan.acquire g).k ∧\n    (endpoints g (SemiprimeD1BoundaryPlan.acquire g).colours p).2<(SemiprimeD1BoundaryPlan.acquire g).k := by\n  have he:=hvalid g.edges[p] (List.getElem_mem hp)\n  have hl:=SemiprimeD1BoundaryChoice.acquire_length g\n  unfold endpoints\n  rw [List.getD_eq_getElem _ _ hp]\n  dsimp only\n  constructor\n  · have hi : g.edges[p].1<(SemiprimeD1BoundaryPlan.acquire g).colours.length := by omega\n    rw [List.getD_eq_getElem _ _ hi]\n    exact SemiprimeD1BoundaryChoice.acquire_colours g _ (List.getElem_mem hi)\n  · have hi : g.edges[p].2<(SemiprimeD1BoundaryPlan.acquire g).colours.length := by omega\n    rw [List.getD_eq_getElem _ _ hi]\n    exact SemiprimeD1BoundaryChoice.acquire_colours g _ (List.getElem_mem hi)\n\n/-- Every actual merge is exhausted: the closed leaf's final port list is empty. -/\ntheorem acquired_empty_ports (ctx : SemiprimeD1JetAxes.Context) (net : Network) :\n    (acquire ctx net).tensor.ports=[] := by\n  have hm:=acquired_models ctx net\n  apply List.eq_nil_iff_forall_not_mem.mpr\n  intro p hp\n  have hscan:=(hm.2 p).mp hp\n  obtain ⟨hbound,hpred⟩:= (scan_mem _ _ _ p).mp hscan\n  have hc:=acquired_endpoint_colours _ (SemiprimeD1BoundaryPotential.graph_valid net) p hbound\n  simp [prefixBoundary,hc.1,hc.2] at hpred\n\n/-- Every consecutive merge event is in the acquired measurement list. -/\ntheorem merge_load_member (k j : Nat) (hj : 1≤ j) (hk : j<k) :\n    Load.merge (j+1)∈SemiprimeD1BoundaryPlan.loads k := by\n  apply List.mem_append_right\n  apply List.mem_map.mpr\n  refine ⟨j-1,List.mem_range.mpr (by omega),?_⟩\n  congr 1\n  omega\n\n/-- The closed actual merge maximum is bounded by the acquired measured maximum. -/\ntheorem acquired_mergeWidth_le (ctx : SemiprimeD1JetAxes.Context) (net : Network) :\n    let bs:=SemiprimeD1BoundaryLeafReport.buckets ctx net\n    SemiprimeD1BoundaryLeafBounds.mergeWidth ctx (bs.headD ⟨⟨[],[]⟩,1⟩).value\n      (bs.tail.map SemiprimeD1BoundaryPlan.Work.value)≤\n      (SemiprimeD1BoundaryPlan.acquire (SemiprimeD1BoundaryPlan.graph net)).width := by\n  let g:=SemiprimeD1BoundaryPlan.graph net\n  let vs:=SemiprimeD1TensorNetwork.vertices net\n  let plan:=SemiprimeD1BoundaryPlan.acquire g\n  have hk : 0<plan.k := by have h:=(SemiprimeD1BoundaryChoice.chooseK_bounds g).1; exact lt_of_lt_of_le (by omega : 0<2) h\n  have hs:=buckets_split ctx g vs plan.colours plan.k hk\n  have hm:=mergeWidth_chain ctx g vs plan.colours 1 (plan.k-1) plan.width\n    (bucket ctx g vs plan.colours 0).value (initial_models g plan.colours)\n    (fun j hj hlast => load_le_width g (.merge (j+1)) (merge_load_member plan.k j hj (by omega)))\n  change SemiprimeD1BoundaryLeafBounds.mergeWidth ctx\n    (((List.range plan.k).map (bucket ctx g vs plan.colours)).headD ⟨⟨[],[]⟩,1⟩).value\n    ((((List.range plan.k).map (bucket ctx g vs plan.colours)).tail).map SemiprimeD1BoundaryPlan.Work.value)≤ plan.width\n  rw [hs]\n  simpa only [List.headD_cons,List.tail_cons,List.map_map,Function.comp_def] using hm\n\n/-- Each stored vertex is selected by its actual acquired colour. -/\ntheorem acquired_vertex_le (net : Network) (hw : SemiprimeD1TensorNetwork.WellFormed net)\n    (v : Vertex) (hv : v∈SemiprimeD1TensorNetwork.vertices net) :\n    v.ports.length≤(SemiprimeD1BoundaryPlan.acquire (SemiprimeD1BoundaryPlan.graph net)).width := by\n  let g:=SemiprimeD1BoundaryPlan.graph net\n  let vs:=SemiprimeD1TensorNetwork.vertices net\n  let plan:=SemiprimeD1BoundaryPlan.acquire g\n  obtain ⟨i,hi,he⟩:=List.mem_iff_getElem.mp hv\n  let c:=plan.colours.getD i 0\n  have hic : i<plan.colours.length := by rw [SemiprimeD1BoundaryChoice.acquire_length]; exact hi\n  have hc : c<plan.k := by\n    unfold c\n    rw [List.getD_eq_getElem _ _ hic]\n    exact SemiprimeD1BoundaryChoice.acquire_colours g _ (List.getElem_mem hic)\n  have hsel : v∈classVertices vs plan.colours c := by\n    apply List.mem_map.mpr\n    refine ⟨(v,i),List.mem_filter.mpr ⟨?_,?_⟩,rfl⟩\n    · exact List.mk_mem_zipIdx_iff_getElem?.mpr (by rw [List.getElem?_eq_getElem hi,he])\n    · simp only [c,beq_self_eq_true]\n  exact (class_vertex_arity net hw plan.colours c v hsel).trans (acquired_bucket_le g c hc)\n\n/-- A maximum of intrinsically bounded metadata stays bounded. -/\ntheorem maximum_le (ns : List Nat) (W : Nat) (h : ∀n∈ns,n≤ W) :\n    SemiprimeD1BoundaryLeafReport.maximum ns≤ W := by\n  induction ns with\n  | nil => exact Nat.zero_le _\n  | cons n ns ih =>\n    exact max_le (h n List.mem_cons_self) (ih (fun x hx => h x (List.mem_cons_of_mem _ hx)))\n\n/-- The runtime's own complete class/vertex/merge width is bounded by its own\nacquired measured partition. No partition or width advice is an input. -/\ntheorem width_le_plan (ctx : SemiprimeD1JetAxes.Context) (net : Network)\n    (hw : SemiprimeD1TensorNetwork.WellFormed net) :\n    SemiprimeD1BoundaryLeafReport.width ctx net≤\n      (SemiprimeD1BoundaryPlan.acquire (SemiprimeD1BoundaryPlan.graph net)).width := by\n  unfold SemiprimeD1BoundaryLeafReport.width\n  apply max_le\n  · apply maximum_le\n    intro n hn\n    obtain ⟨c,hc,rfl⟩:=List.mem_map.mp hn\n    exact acquired_bucket_le _ c (List.mem_range.mp hc)\n  · apply max_le\n    · apply maximum_le\n      intro n hn\n      obtain ⟨v,hv,rfl⟩:=List.mem_map.mp hn\n      exact acquired_vertex_le net hw v hv\n    · exact acquired_mergeWidth_le ctx net\n\n/-- Complete current-context inventory and actual metadata polynomial factor.\nThe axis sum pays each stored bound even for arbitrarily many rank-one axes. -/\ndef reportFactor (ctx : SemiprimeD1JetAxes.Context) (net : Network) : Nat :=\n  SemiprimeD1BoundaryLeafReport.polynomial ctx net (SemiprimeD1BoundaryLeafReport.width ctx net)+\n    ctx.axes.length+ctx.axes.sum+ctx.rank+ctx.precision+1\n\n/-- The closed native retained report has a single exponential in its own\nacquired partition width. All coefficient delimiters, scalar precision,\naxis metadata, and the actual full-jet arithmetic budget are retained. -/\ntheorem run_clock_acquired (ctx : SemiprimeD1JetAxes.Context) (net : Network)\n    (hw : SemiprimeD1TensorNetwork.WellFormed net)\n    (hg : SemiprimeD1LeafCounter.Good ctx (SemiprimeD1TensorNetwork.vertices net)) :\n    (run ctx net).clock≤\n      (SemiprimeD1BoundaryPlan.acquire (SemiprimeD1BoundaryPlan.graph net)).clock+\n      10*inputMass (SemiprimeD1TensorNetwork.vertices net)+\n      reportFactor ctx net*(2^(SemiprimeD1BoundaryPlan.acquire (SemiprimeD1BoundaryPlan.graph net)).width+1) := by\n  apply (SemiprimeD1BoundaryLeafReport.run_clock ctx net hg).trans\n  apply Nat.add_le_add_left\n  apply Nat.mul_le_mul\n  · unfold reportFactor\n    omega\n  · exact Nat.add_le_add_right (Nat.pow_le_pow_right (by omega) (width_le_plan ctx net hw)) 1\n\nend RiemannGaussian.SemiprimeD1BoundaryLeafLoad\n","RiemannGaussian.SemiprimeD1BoundaryOverlap":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1BoundaryPotential\n\n/-! # Ordered overlap counting for literal endpoint occurrences\nParallel occurrences retain separate list positions throughout these bounds.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1BoundaryOverlap\nopen SemiprimeD1BoundaryPlan\n\n/-- Two original occurrences share an endpoint. -/\ndef touches (e f : Nat × Nat) : Bool :=\n  (f.1 == e.1 || f.2 == e.1) || (f.1 == e.2 || f.2 == e.2)\n\n/-- The maximum fold retains its initial lower bound. -/\ntheorem le_foldl_max (xs : List Nat) (a : Nat) : a ≤ xs.foldl max a := by\n  induction xs generalizing a with\n  | nil => rfl\n  | cons x xs ih => exact (Nat.le_max_left a x).trans (ih (max a x))\n\n/-- Each literal list member is bounded by its computed maximum fold. -/\ntheorem member_le_foldl_max (xs : List Nat) (a x : Nat) (hx : x ∈ xs) :\n    x ≤ xs.foldl max a := by\n  induction xs generalizing a with\n  | nil => simp at hx\n  | cons y xs ih =>\n    rcases List.mem_cons.mp hx with rfl | hh\n    · exact (Nat.le_max_right a x).trans (le_foldl_max xs (max a x))\n    · exact ih (max a y) hh\n\n/-- Every valid endpoint degree is bounded by the executed maximum degree. -/\ntheorem degree_le_maxDegree (g : Graph) (v : Nat) (hv : v < g.vertices) :\n    degree g v ≤ maxDegree g := by\n  apply member_le_foldl_max\n  exact List.mem_map.mpr ⟨v, List.mem_range.mpr hv, rfl⟩\n\n/-- A union-filter count is bounded by the two individual occurrence counts. -/\ntheorem filter_or_length_le {α : Type} (xs : List α) (p q : α → Bool) :\n    (xs.filter (fun x => p x || q x)).length ≤ (xs.filter p).length + (xs.filter q).length := by\n  induction xs with\n  | nil => simp\n  | cons x xs ih =>\n    cases hp : p x <;> cases hq : q x <;> simp [hp, hq] at * <;> omega\n\n/-- All occurrences sharing either endpoint are counted by the endpoint degrees. -/\ntheorem touching_length_le_degrees (g : Graph) (e : Nat × Nat) :\n    (g.edges.filter (touches e)).length ≤ degree g e.1 + degree g e.2 := by\n  exact filter_or_length_le g.edges _ _\n\n/-- One edge has at most twice the executed maximum degree many overlaps. -/\ntheorem touching_length_le (g : Graph) (e : Nat × Nat)\n    (he : e ∈ g.edges) (hg : SemiprimeD1BoundaryPotential.Valid g) :\n    (g.edges.filter (touches e)).length ≤ 2 * maxDegree g := by\n  have h := hg e he\n  have h1 := degree_le_maxDegree g e.1 h.1\n  have h2 := degree_le_maxDegree g e.2 h.2.1\n  have h3 := touching_length_le_degrees g e\n  omega\n\n/-- Sum of uniformly bounded original occurrence values. -/\ntheorem sum_map_le {α : Type} (xs : List α) (f : α → Nat) (b : Nat)\n    (hf : ∀ x ∈ xs, f x ≤ b) : (xs.map f).sum ≤ xs.length * b := by\n  induction xs with\n  | nil => simp\n  | cons x xs ih =>\n    have h1 := hf x (by simp)\n    have h2 := ih (fun y hy => hf y (by simp [hy]))\n    simp only [List.map_cons, List.sum_cons, List.length_cons, Nat.add_mul, one_mul]\n    omega\n\n/-- The number of ordered overlapping occurrence pairs is at most `2*M*Delta`. -/\ntheorem ordered_overlaps_le (g : Graph) (hg : SemiprimeD1BoundaryPotential.Valid g) :\n    ((g.edges.flatMap (fun e => g.edges.map (fun f => (e, f)))).filter\n      (fun ef => touches ef.1 ef.2)).length ≤ 2 * g.edges.length * maxDegree g := by\n  have he : ((g.edges.flatMap (fun e => g.edges.map (fun f => (e, f)))).filter\n      (fun ef => touches ef.1 ef.2)).length =\n      (g.edges.map (fun e => (g.edges.filter (touches e)).length)).sum := by\n    simp [List.filter_flatMap, List.filter_map, List.length_flatMap, Function.comp_def]\n  rw [he]\n  have hh := sum_map_le g.edges (fun e => (g.edges.filter (touches e)).length)\n    (2 * maxDegree g) (fun e he => touching_length_le g e he hg)\n  nlinarith\n\nend RiemannGaussian.SemiprimeD1BoundaryOverlap\n","RiemannGaussian.SemiprimeD1BoundaryRecordsAttachBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1BoundaryRecordsContractBounds\nimport RiemannGaussian.SemiprimeD1BoundaryRecordsLookupBounds\n\n/-! # Executed two-sort boundary attachment -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1BoundaryRecordsAttachBounds\nopen SemiprimeD1BoundaryRecords\nopen SemiprimeD1BoundaryRecordsCanonical\nopen SemiprimeD1BoundaryRecordsReduction\nopen SemiprimeD1BoundaryRecordsGroupBounds\nopen SemiprimeD1BoundaryRecordsContractBounds\nopen SemiprimeD1BoundaryRecordsLookupBounds\nopen SemiprimeD1JetAxes (Context)\n\n/-- Complete request bytes include both route and projected lookup address. -/\ndef requestBudget (ctx : Context) (K T : Nat) : Nat := recordBudget ctx K+T+1\n\ntheorem requests_properties (ctx : Context) (source target : List Nat) (K : Nat)\n    (es : List Entry) (hg : GoodEntries ctx es) (hk : Keys K es) :\n    ∀ e∈(requests source target es).value,\n      size e≤requestBudget ctx K target.length ∧\n      (Request.unpack e).words.length≤ctx.rank ∧ (Request.unpack e).route.length≤K := by\n  induction es with\n  | nil => simp [requests]\n  | cons e es ih =>\n    intro x hx\n    rcases List.mem_cons.mp hx with rfl | hx\n    · have hs:=size_le ctx K e (hg e List.mem_cons_self) (hk e List.mem_cons_self)\n      have hn:=(hg e List.mem_cons_self).1\n      have hkey:=hk e List.mem_cons_self\n      have hp:=project_length e.key source target\n      simp only [Request.pack,Request.unpack,List.tail_cons,List.headD_cons]\n      constructor\n      · unfold size requestBudget recordBudget at *\n        simp only [List.map_cons,List.sum_cons,List.length_cons]\n        nlinarith\n      · exact ⟨hn.le,hkey⟩\n    · exact ih (fun x hx => hg x (List.mem_cons_of_mem _ hx))\n        (fun x hx => hk x (List.mem_cons_of_mem _ hx)) x hx\n\ntheorem requests_clock (ctx : Context) (source target : List Nat) (K : Nat)\n    (es : List Entry) (hg : GoodEntries ctx es) (hk : Keys K es) :\n    (requests source target es).clock ≤\n      (projectBudget source target K+3*recordBudget ctx K+8)*(es.length+1) := by\n  induction es with\n  | nil => simp only [requests,List.length_nil,Nat.zero_add,Nat.mul_one]; omega\n  | cons e es ih =>\n    have ht:=ih (fun x hx => hg x (List.mem_cons_of_mem _ hx))\n      (fun x hx => hk x (List.mem_cons_of_mem _ hx))\n    have hp:=project_clock e.key source target K (hk e List.mem_cons_self)\n    have hs:=size_le ctx K e (hg e List.mem_cons_self) (hk e List.mem_cons_self)\n    simp only [requests,List.length_cons]\n    nlinarith\n\n/-- Joined keys are the original request routes, including missing-table zero. -/\ntheorem lookupFuel_keys (ctx : Context) :\n    (fuel : Nat) → (rs ts : List Entry) → (K : Nat) → rs.length+ts.length≤fuel →\n    (∀e∈rs,(Request.unpack e).route.length≤K) → Keys K (lookupFuel ctx fuel rs ts).value\n  | 0,rs,ts,K,h,_ => by\n    have hr : rs=[] := List.eq_nil_of_length_eq_zero (by omega)\n    subst rs\n    simp [lookupFuel,Keys]\n  | _+1,[],_,_,_,_ => by simp [lookupFuel,Keys]\n  | fuel+1,r::rs,[],K,h,hk => by\n    intro e he\n    rcases List.mem_cons.mp he with rfl | he\n    · exact hk r List.mem_cons_self\n    · exact lookupFuel_keys ctx fuel rs [] K (by simp only [List.length_cons,List.length_nil,Nat.add_zero] at h ⊢;omega)\n        (fun e he => hk e (List.mem_cons_of_mem _ he)) e he\n  | fuel+1,r::rs,t::ts,K,h,hk => by\n    rw [lookupFuel]\n    cases ho : (compareKey r.key t.key).value\n    · intro e he\n      rcases List.mem_cons.mp he with rfl | he\n      · exact hk r List.mem_cons_self\n      · exact lookupFuel_keys ctx fuel rs (t::ts) K\n          (by simp only [List.length_cons] at h ⊢;omega)\n          (fun e he => hk e (List.mem_cons_of_mem _ he)) e he\n    · intro e he\n      rcases List.mem_cons.mp he with rfl | he\n      · exact hk r List.mem_cons_self\n      · exact lookupFuel_keys ctx fuel rs (t::ts) K\n          (by simp only [List.length_cons] at h ⊢;omega)\n          (fun e he => hk e (List.mem_cons_of_mem _ he)) e he\n    · exact lookupFuel_keys ctx fuel (r::rs) ts K\n        (by simp only [List.length_cons] at h ⊢;omega) hk\n\n/-- Per-record allowance for both real sorts and full arithmetic join. -/\ndef attachBudget (ctx : Context) (source target : List Nat) (K B W : Nat) : Nat :=\n  projectBudget source target K+3*recordBudget ctx K+8+\n    200*(requestBudget ctx K target.length+1)*(W+3)+\n    joinBudget ctx (requestBudget ctx K target.length+B)+\n    200*(recordBudget ctx K+1)*(W+3)+7\n\n/-- Attachment is linear in accumulator plus literal-table count; the separate\nfactor pays full jet arithmetic, identifier widths and the two logarithmic sorts. -/\ntheorem attach_clock_pow (ctx : Context) (source target : List Nat) (K B W : Nat)\n    (acc table : List Entry) (hg : GoodEntries ctx acc) (hk : Keys K acc)\n    (hb : ∀e∈table,size e≤B) (ht : ∀e∈table,e.words.length≤ctx.rank)\n    (hn : acc.length≤2^W) :\n    (attach ctx source target acc table).clock ≤\n      attachBudget ctx source target K B W*(2^W+table.length+1) := by\n  let rs:=(requests source target acc).value\n  let ordered:=(sort rs).value\n  let joined:=lookupFuel ctx (ordered.length+table.length+1) ordered table\n  have hp:=requests_properties ctx source target K acc hg hk\n  have ho : ∀e∈ordered,size e≤requestBudget ctx K target.length ∧\n      (Request.unpack e).words.length≤ctx.rank ∧ (Request.unpack e).route.length≤K := by\n    intro e he\n    exact hp e ((SemiprimeD1BoundaryRecordsSort.sort_perm rs).mem_iff.mp he)\n  have hrl : rs.length=acc.length := requests_length source target acc\n  have hol : ordered.length=acc.length := (SemiprimeD1BoundaryRecordsSort.sort_length rs).trans hrl\n  have hjl : joined.value.length=acc.length := (lookupFuel_length ctx _ _ _ (by omega)).trans hol\n  have hreq:=requests_clock ctx source target K acc hg hk\n  have hsort:=SemiprimeD1BoundaryRecordsSortBounds.sort_clock_pow rs\n    (requestBudget ctx K target.length) W (fun e he => (hp e he).1) (by rw [hrl]; exact hn)\n  have hjoin:=lookupFuel_clock ctx (ordered.length+table.length+1) ordered table\n    (requestBudget ctx K target.length+B) (by omega)\n    (fun e he => (ho e he).1.trans (Nat.le_add_right _ _))\n    (fun e he => (hb e he).trans (Nat.le_add_left _ _))\n    (fun e he => (ho e he).2.1) ht\n  have hjg:=lookupFuel_good ctx (ordered.length+table.length+1) ordered table (by omega)\n  have hjk:=lookupFuel_keys ctx (ordered.length+table.length+1) ordered table K (by omega)\n    (fun e he => (ho e he).2.2)\n  have hrestore:=SemiprimeD1BoundaryRecordsSortBounds.sort_clock_pow joined.value\n    (recordBudget ctx K) W (fun e he => size_le ctx K e (hjg e he) (hjk e he))\n    (by rw [hjl]; exact hn)\n  have hreq':=hreq.trans (Nat.mul_le_mul_left _ (by omega : acc.length+1≤2^W+table.length+1))\n  have hs' : (sort rs).clock ≤\n      (200*(requestBudget ctx K target.length+1)*(W+3))*(2^W+table.length+1) := by\n    apply hsort.trans\n    calc\n      _ = (200*(requestBudget ctx K target.length+1)*(W+3))*(2^W+1) := by ring\n      _ ≤ _ := Nat.mul_le_mul_left _ (by omega)\n  have hj':=hjoin.trans (Nat.mul_le_mul_left _ (by omega : ordered.length+table.length+1≤2^W+table.length+1))\n  have hr' : (sort joined.value).clock ≤\n      (200*(recordBudget ctx K+1)*(W+3))*(2^W+table.length+1) := by\n    apply hrestore.trans\n    calc\n      _ = (200*(recordBudget ctx K+1)*(W+3))*(2^W+1) := by ring\n      _ ≤ _ := Nat.mul_le_mul_left _ (by omega)\n  change (requests source target acc).clock+(sort rs).clock+joined.clock+(sort joined.value).clock+7≤_\n  unfold attachBudget\n  nlinarith only [hreq',hs',hj',hr',Nat.zero_le (2^W),Nat.zero_le table.length]\n\nend RiemannGaussian.SemiprimeD1BoundaryRecordsAttachBounds\n","RiemannGaussian.SemiprimeD1CanonicalInput":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceCompactBits\nimport RiemannGaussian.SemiprimeMacroParameters\n\n/-! # Original physical input length and the goal's binary size\nCanonical binary inputs have exactly the size used in the requested exponent.\nNormalization of a supplied physical word is itself the existing paid Boolean\ntrim, and its linear input-scan cost is retained rather than silently erased.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1CanonicalInput\nopen SemiprimeBitArithmetic SemiprimeSourceCompactBits\n\n/-- The literal goal size equals the original public macro size, also at zero. -/\ntheorem size_eq_clog (N : ℕ) : SemiprimeMacroParameters.bitLength N=Nat.clog 2 (N+1) := by\n  apply Nat.le_antisymm\n  · apply Nat.size_le.mpr\n    have hp := Nat.le_pow_clog (by decide : 1 < (2:ℕ)) (N+1)\n    omega\n  · apply Nat.clog_le_of_le_pow\n    exact Nat.succ_le_of_lt (Nat.lt_size_self N)\n\n/-- Every canonical original binary word has precisely the theorem's size. -/\ntheorem compact_length (input : List Bool) (h : Compact input) :\n    input.length=SemiprimeMacroParameters.bitLength (bitValue input) := by\n  apply Nat.le_antisymm\n  · rw [size_eq_clog]\n    exact compact_length_clog input h\n  · exact Nat.size_le.mpr (bitValue_lt_width input)\n\n/-- Paid physical normalization preserves the original integer. -/\ntheorem trim_original (input : List Bool) :\n    bitValue (trim input).bits=bitValue input ∧ Compact (trim input).bits := by\n  exact ⟨trim_value input,trim_compact input⟩\n\n/-- The actual normalized word has exact original goal size; reading any supplied\npadding remains the explicit trim_clock cost below. -/\ntheorem trim_goal_length (input : List Bool) :\n    (trim input).bits.length=Nat.clog 2 (bitValue input+1) := by\n  rw [compact_length (trim input).bits (trim_compact input),size_eq_clog,trim_value]\n\n/-- The normalization scan is linear in the actual supplied physical word. -/\ntheorem trim_work (input : List Bool) : (trim input).clock=6*input.length+1 := trim_clock input\n\nend RiemannGaussian.SemiprimeD1CanonicalInput\n","RiemannGaussian.SemiprimeD1ChildGraphSemantics":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ChildGraph\n\n/-! # Original endpoint refinement of the physically acquired child graph\nSemantic finite-word expressions occur only in proofs of physical colour tests.\nThe child tensor-entry builder and inactive-vertex constant-one semantics remain\nseparate from this literal graph incidence construction.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2800000\nnamespace RiemannGaussian.SemiprimeD1ChildGraphSemantics\nopen SemiprimeD1ChildGraph SemiprimeD1PacketInventory SemiprimeBitArithmetic\nopen SemiprimeD1CollisionOriginal\n\n/-- The executed byte test supplies the concrete decidable predicate. -/\ntheorem equalBytes_value (xs ys : List Bool) : (equalBytes xs ys).value=decide (xs=ys) := by\n  apply Bool.eq_iff_iff.mpr\n  simpa only [decide_eq_true_eq] using equalBytes_correct xs ys\n\n/-- Packet buckets retain exactly the original endpoint list multiplicities. -/\ntheorem bucket_value {vertices : ℕ} (key : List Bool) (es : List (Endpoint vertices)) :\n    (bucket key es).value=es.filter (fun e => decide (e.packet=key)) := by\n  induction es with\n  | nil => rfl\n  | cons e es ih => simp only [bucket,ih,equalBytes_value,List.filter_cons]\n\n/-- All observed packet buckets are cached in the same original discovery order. -/\ntheorem buckets_value {vertices : ℕ} (es : List (Endpoint vertices)) (keys : List (List Bool)) :\n    (buckets es keys).value=keys.map (fun key => es.filter (fun e => decide (e.packet=key))) := by\n  induction keys with\n  | nil => rfl\n  | cons key keys ih => simp only [buckets,ih,bucket_value,List.map_cons]\n\n/-- Number of child factor vertices is the actual observed packet count. -/\ntheorem factors_length {n F r a : ℕ} {inputArity : Fin F→ℕ}\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n)\n    (source : SemiprimeD1PacketReplayOriginal.Acquired n F a inputArity) (q : Fin a) (g : Fin r) :\n    (fromReplay inputOwner source q g).factors.length=source.state.packets.length := by\n  change (buckets _ _).value.length=_\n  rw [buckets_value,List.length_map]\n\n/-- Physical colour comparison of original palette bytes, without a getter oracle. -/\ntheorem test_fields {r a : ℕ} (word : OAI.Algorithms.SubexponentialSAT.MulticolorTypes.Word r a)\n    (q : Fin a) (g : Fin r) :\n    (testColour (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits q.val\n      (SemiprimeD1OrientationPalette.fields word)).value=true ↔ word q=g := by\n  rw [testColour_correct]\n  simp only [SemiprimeD1OrientationPalette.fields,List.getElem?_ofFn,q.isLt,↓reduceDIte,\n    Option.getD_some,SemiprimeSourceHistogramHeadRefinement.numberKey_value,\n    SemiprimeSourceHistogramPortKeys.encodeKey_value,Fin.ext_iff]\n\n/-- Exact two original selected-colour endpoint tests for one actual occurrence. -/\ntheorem one_original (n F r a : ℕ) [NeZero r] (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n)\n    (q : Fin a) (g : Fin r) (i : (e : Fin F)×Fin (inputArity e)) (out : Placement)\n    (hs : out.source=SemiprimeD1IncidenceAcquisition.originalKey n F r a inputArity inputOwner i) :\n    (one inputOwner\n      (SemiprimeD1IncidenceAcquisition.acquire n F r a inputArity inputOwner).selection.cache.rows.source.dictionary\n      a q.val (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits i out).value=\n      (if (SemiprimeD1SelectedCollision.selectedLabel n F r a inputArity inputOwner i).1 q=g\n        then [(endpoints inputOwner i out).1] else [])++\n      (if (SemiprimeD1SelectedCollision.selectedLabel n F r a inputArity inputOwner i).2 q=g\n        then [(endpoints inputOwner i out).2] else []) := by\n  have hrows := SemiprimeD1PacketRowsOriginal.original_read n F r a inputArity inputOwner i\n  dsimp only [SemiprimeD1PacketRowsOriginal.originalRead] at hrows\n  have hlt := test_fields (SemiprimeD1SelectedCollision.selectedLabel n F r a inputArity inputOwner i).1 q g\n  have hrt := test_fields (SemiprimeD1SelectedCollision.selectedLabel n F r a inputArity inputOwner i).2 q g\n  simp only [one,hs,hrows.1,hrows.2.1]\n  simp only [hlt,hrt]\n\n/-- Same-order scan semantics, with all original repeated occurrences retained. -/\ntheorem scan_value {n F : ℕ} {inputArity : Fin F→ℕ}\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n)\n    (dict : SemiprimeSourceHistogramRows.Dictionary) (a q : ℕ) (target : List Bool)\n    (pairs : List (((e : Fin F)×Fin (inputArity e))×Placement)) :\n    (scan inputOwner dict a q target pairs).value=\n      pairs.flatMap (fun p => (one inputOwner dict a q target p.1 p.2).value) := by\n  induction pairs with\n  | nil => rfl\n  | cons p pairs ih => simp only [scan,ih,List.flatMap_cons]\n\n/-- Source-map equality supplies exact original pairing, not a zip oracle. -/\ntheorem zip_alignment {I : Type*} (is : List I) (ps : List Placement) (key : I→List Bool)\n    (hs : ps.map Placement.source=is.map key) :\n    ∀ pair∈is.zip ps,pair.2.source=key pair.1 := by\n  induction is generalizing ps with\n  | nil => simp\n  | cons i is ih =>\n    cases ps with\n    | nil => simp at hs\n    | cons p ps =>\n      simp only [List.map_cons,List.cons.injEq] at hs\n      intro pair hp\n      rcases List.mem_cons.mp hp with he|he\n      · subst pair\n        exact hs.1\n      · exact ih ps hs.2 pair he\n\n/-- Original metadata stream in the retained replay is the actual port list. -/\ntheorem original_ports (n F r a : ℕ) (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n) :\n    (SemiprimeD1PacketReplayOriginal.acquire n F r a inputArity inputOwner).padding.source.selection.cache.data.metadata.incidences=\n      ports n F a inputArity := by\n  change (SemiprimeSourceHistogramSetup.acquire n F r a 0 inputArity inputOwner).data.metadata.incidences=_\n  rw [SemiprimeSourceHistogramSetup.metadata_actual]\n  rfl\n\n/-- A full original pairing preserves counts of every original-port predicate. -/\ntheorem zip_countP {I : Type*} (is : List I) (ps : List Placement)\n    (hl : is.length=ps.length) (pred : I→Bool) :\n    (is.zip ps).countP (fun pair => pred pair.1)=is.countP pred := by\n  induction is generalizing ps with\n  | nil => simp\n  | cons i is ih =>\n    cases ps with\n    | nil => simp at hl\n    | cons p ps =>\n      simp only [List.length_cons,Nat.add_right_cancel_iff] at hl\n      simpa only [List.zip_cons_cons,List.countP_cons] using\n        congrArg (fun n => n+(if pred i then 1 else 0)) (ih ps hl)\n\n/-- Each actual source occurrence contributes precisely its selected two endpoints. -/\ntheorem scan_length_original (n F r a : ℕ) [NeZero r] (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n)\n    (q : Fin a) (g : Fin r) (pairs : List (((e : Fin F)×Fin (inputArity e))×Placement))\n    (hp : ∀ pair∈pairs,pair.2.source=\n      SemiprimeD1IncidenceAcquisition.originalKey n F r a inputArity inputOwner pair.1) :\n    (scan inputOwner\n      (SemiprimeD1IncidenceAcquisition.acquire n F r a inputArity inputOwner).selection.cache.rows.source.dictionary\n      a q.val (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits pairs).value.length=\n    pairs.countP (fun pair => decide\n      ((SemiprimeD1SelectedCollision.selectedLabel n F r a inputArity inputOwner pair.1).1 q=g))+\n    pairs.countP (fun pair => decide\n      ((SemiprimeD1SelectedCollision.selectedLabel n F r a inputArity inputOwner pair.1).2 q=g)) := by\n  induction pairs with\n  | nil => rfl\n  | cons pair pairs ih =>\n    have hh := one_original n F r a inputArity inputOwner q g pair.1 pair.2\n      (hp pair List.mem_cons_self)\n    have ht := ih (fun p h => hp p (List.mem_cons_of_mem _ h))\n    change ((one _ _ _ _ _ _ _).value++(scan _ _ _ _ _ pairs).value).length=_\n    rw [List.length_append,hh,ht,List.length_append,List.countP_cons,List.countP_cons]\n    split_ifs <;> simp_all <;> omega\n\n/-- Exact original child endpoint count; no balancing/count answer is supplied. -/\ntheorem endpoint_count (n F r a : ℕ) [NeZero r] (inputArity : Fin F→ℕ)\n    (inputOwner : ((e : Fin F)×Fin (inputArity e))→Fin n) (q : Fin a) (g : Fin r) :\n    (acquire n F r a inputArity inputOwner q g).endpoints.length=\n      SemiprimeD1GroupBalance.selectedGroupCount n F r a inputArity inputOwner true q g+\n      SemiprimeD1GroupBalance.selectedGroupCount n F r a inputArity inputOwner false q g := by\n  let source := SemiprimeD1PacketReplayOriginal.acquire n F r a inputArity inputOwner\n  have hs := SemiprimeD1PacketReplayOriginal.sources n F r a inputArity inputOwner\n  rw [SemiprimeD1IncidenceAcquisition.keys_original] at hs\n  have hl : (ports n F a inputArity).length=source.placements.length := by\n    have h := congrArg List.length hs\n    simp only [List.length_map] at h\n    exact h.symm\n  have hp := zip_alignment (ports n F a inputArity) source.placements\n    (SemiprimeD1IncidenceAcquisition.originalKey n F r a inputArity inputOwner) hs\n  have he := scan_length_original n F r a inputArity inputOwner q g _ hp\n  rw [zip_countP _ _ hl (fun i => decide ((SemiprimeD1SelectedCollision.selectedLabel n F r a inputArity inputOwner i).1 q=g)),\n    zip_countP _ _ hl (fun i => decide ((SemiprimeD1SelectedCollision.selectedLabel n F r a inputArity inputOwner i).2 q=g))] at he\n  change (scan _ _ _ _ _ _).value.length=_\n  rw [original_ports]\n  change (scan inputOwner\n      (SemiprimeD1IncidenceAcquisition.acquire n F r a inputArity inputOwner).selection.cache.rows.source.dictionary\n      a q.val (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits\n      ((ports n F a inputArity).zip source.placements)).value.length=_\n  simpa only [SemiprimeD1GroupBalance.selectedGroupCount,SemiprimeD1GroupBalance.groupCount,\n    SemiprimeD1GroupBalance.colour,ite_true,Bool.false_eq_true,ite_false] using he\n\nend RiemannGaussian.SemiprimeD1ChildGraphSemantics\n","RiemannGaussian.SemiprimeD1ChildNetworkTapeBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ChildNetworkTape\n\n/-! # Complete active old-table tape-copy report bounds\nRepeated alignment, individual lifts and recopy scans remain in the actual\nbudget. Degree guards concern literal input/output scopes, never clock advice.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1ChildNetworkTapeBudget\nopen SemiprimeD1JetAxes SemiprimeD1TensorTables SemiprimeD1ChildNetworkTape\nopen SemiprimeD1ChildNetwork (Pullback parentVertex parentVertex_good)\nopen SemiprimeD1ChildTableCopyTape (tapeBudget tableCap)\n\n/-- Every canonical-port table recopy serializes and scans its actual source each time. -/\ntheorem copyTable_clock {d : ℕ} (ports : List ℕ) (table : Table d) :\n    (copyTable ports table).2 ≤ (tapeBudget (storage table)+7)*2^ports.length := by\n  have h:=build_clock ports.length (tapeBudget (storage table))\n    (fun bits => SemiprimeD1TensorTapeLookup.fromTable table bits)\n    (fun bits _ => SemiprimeD1ChildTableCopyTape.fromTable_clock table bits)\n  change (build ports.length (fun bits => SemiprimeD1TensorTapeLookup.fromTable table bits)).clock+3 ≤ _\n  omega\n\n/-- Actual parent storage is contained in the literal current network inventory. -/\ntheorem parent_storage_le (net : SemiprimeD1TensorNetwork.Network)\n    (v : Fin (net.leftCount+net.rows.length)) :\n    storage (parentVertex net v).table ≤ SemiprimeD1NetworkStateResources.inventory net := by\n  have h:=SemiprimeD1TensorTapeOriginal.member_le_sum (SemiprimeD1TensorNetwork.vertices net)\n    (fun w => storage w.table+w.ports.length+1) (parentVertex net v) (List.getElem_mem _)\n  unfold SemiprimeD1NetworkStateResources.inventory\n  omega\n\n/-- Fixed positive-polynomial overhead in input inventory and explicit local table caps. -/\ndef leftBudget (old : Context) (extra : List ℕ) (p D O I v : ℕ) : ℕ :=\n  2*O+(tapeBudget I+7)*2^D+\n    SemiprimeD1ChildTensorTablesTape.cacheBudget old extra p D (tableCap old D)+\n    (tapeBudget (tableCap ⟨extra++old.axes,p⟩ D)+7)*2^D+D+v+12\n\n/-- Actual leftOne pays two routing acquisitions, full eager alignment, every\nper-entry integer lift, and full canonical recopy, with no external work supplier. -/\ntheorem leftOne_clock {a : ℕ} (net : SemiprimeD1TensorNetwork.Network)\n    (data : Pullback net a) (old : Context) (extra : List ℕ) (p D : ℕ)\n    (v : Fin (net.leftCount+net.rows.length))\n    (hg : SemiprimeD1TensorNetwork.Good old net) (he : 0<extra.prod)\n    (ho : (SemiprimeD1ChildTableOrder.acquire (SemiprimeD1TensorNetwork.owner net.rows) data v).old.length ≤ D)\n    (hc : (SemiprimeD1ChildTableOrder.acquire (SemiprimeD1TensorNetwork.owner net.rows) data v).child.length ≤ D)\n    (hp : (SemiprimeD1TensorNetwork.leftPorts (SemiprimeD1TensorNetworkLayout.childRows data.graph) v).length ≤ D) :\n    (leftOne net data old extra p v).2 ≤ leftBudget old extra p D\n      (SemiprimeD1ChildTableOrder.acquire (SemiprimeD1TensorNetwork.owner net.rows) data v).clock\n      (SemiprimeD1NetworkStateResources.inventory net) v.val := by\n  let order:=SemiprimeD1ChildTableOrder.acquire (SemiprimeD1TensorNetwork.owner net.rows) data v\n  let parent:=parentVertex net v\n  let aligned:=build order.old.length (fun bits => SemiprimeD1TensorTapeLookup.fromTable parent.table bits)\n  let copied:=SemiprimeD1ChildTensorTablesTape.fromCache\n    (SemiprimeD1TensorNetwork.owner net.rows) data v old extra p aligned.table\n  let ports:=SemiprimeD1TensorNetwork.leftPorts (SemiprimeD1TensorNetworkLayout.childRows data.graph) v\n  have hparent:=parentVertex_good old net hg v\n  have haligned:=build_clock order.old.length (tapeBudget (storage parent.table))\n    (fun bits => SemiprimeD1TensorTapeLookup.fromTable parent.table bits)\n    (fun bits _ => SemiprimeD1ChildTableCopyTape.fromTable_clock parent.table bits)\n  have haGood : Good old aligned.table := build_good old _ _ (by\n    intro bits _\n    rw [SemiprimeD1TensorTapeLookup.fromTable_words]\n    exact lookup_good old parent.table hparent bits)\n  have hcClock:=SemiprimeD1ChildTensorTablesTape.fromCache_clock\n    (SemiprimeD1TensorNetwork.owner net.rows) data v old extra p D aligned.table haGood he ho hc\n  have hcGood:=SemiprimeD1ChildTensorTablesTape.fromCache_good\n    (SemiprimeD1TensorNetwork.owner net.rows) data v old extra p aligned.table haGood he\n  have hcopy:=copyTable_clock ports copied.table\n  have hdegree : copied.degree ≤ D := by\n    dsimp only [copied,SemiprimeD1ChildTensorTablesTape.fromCache]\n    split\n    · exact hc\n    · exact Nat.zero_le _\n  have hAS:=SemiprimeD1ChildTableCopyTape.storage_le_cap old aligned.table haGood D ho\n  have hCS:=SemiprimeD1ChildTableCopyTape.storage_le_cap ⟨extra++old.axes,p⟩ copied.table hcGood D hdegree\n  have hA : (tapeBudget (storage parent.table)+7)*2^order.old.length ≤\n      (tapeBudget (SemiprimeD1NetworkStateResources.inventory net)+7)*2^D := by\n    apply Nat.mul_le_mul\n    · exact Nat.add_le_add_right (SemiprimeD1ChildTableCopyTape.tapeBudget_mono (parent_storage_le net v)) 7\n    · exact Nat.pow_le_pow_right (by decide) ho\n  have hC : (tapeBudget (storage copied.table)+7)*2^ports.length ≤\n      (tapeBudget (tableCap ⟨extra++old.axes,p⟩ D)+7)*2^D := by\n    apply Nat.mul_le_mul\n    · exact Nat.add_le_add_right (SemiprimeD1ChildTableCopyTape.tapeBudget_mono hCS) 7\n    · exact Nat.pow_le_pow_right (by decide) hp\n  have ha' : aligned.clock ≤ (tapeBudget (SemiprimeD1NetworkStateResources.inventory net)+7)*2^D :=\n    (Nat.le_trans (Nat.le_add_right aligned.clock 5) haligned).trans hA\n  have hc' : copied.clock ≤ order.clock+\n      SemiprimeD1ChildTensorTablesTape.cacheBudget old extra p D (tableCap old D) :=\n    hcClock.trans (Nat.add_le_add_left\n      (SemiprimeD1ChildTensorTablesTape.cacheBudget_mono old extra p D hAS) order.clock)\n  have hr' : (copyTable ports copied.table).2 ≤\n      (tapeBudget (tableCap ⟨extra++old.axes,p⟩ D)+7)*2^D := hcopy.trans hC\n  have hleft : (leftOne net data old extra p v).2=\n      order.clock+aligned.clock+copied.clock+(copyTable ports copied.table).2+ports.length+v.val+12 := rfl\n  have hports : ports.length ≤ D := hp\n  rw [hleft]\n  calc\n    _ ≤ order.clock+(tapeBudget (SemiprimeD1NetworkStateResources.inventory net)+7)*2^D+\n        (order.clock+SemiprimeD1ChildTensorTablesTape.cacheBudget old extra p D (tableCap old D))+\n        (tapeBudget (tableCap ⟨extra++old.axes,p⟩ D)+7)*2^D+D+v.val+12 := by omega\n    _ = _ := by unfold leftBudget;ring\n\n/-- A computed literal scope cap, not a supplied degree/clock certificate. -/\ndef localDegree {a : ℕ} (net : SemiprimeD1TensorNetwork.Network) (data : Pullback net a)\n    (v : Fin (net.leftCount+net.rows.length)) : ℕ :=\n  let order:=SemiprimeD1ChildTableOrder.acquire (SemiprimeD1TensorNetwork.owner net.rows) data v\n  order.old.length+order.child.length+\n    (SemiprimeD1TensorNetwork.leftPorts (SemiprimeD1TensorNetworkLayout.childRows data.graph) v).length\n\n/-- Closed actual old-vertex report from literal network/routing data only. -/\ntheorem leftOne_clock_closed {a : ℕ} (net : SemiprimeD1TensorNetwork.Network)\n    (data : Pullback net a) (old : Context) (extra : List ℕ) (p : ℕ)\n    (v : Fin (net.leftCount+net.rows.length))\n    (hg : SemiprimeD1TensorNetwork.Good old net) (he : 0<extra.prod) :\n    (leftOne net data old extra p v).2 ≤ leftBudget old extra p (localDegree net data v)\n      (SemiprimeD1ChildTableOrder.acquire (SemiprimeD1TensorNetwork.owner net.rows) data v).clock\n      (SemiprimeD1NetworkStateResources.inventory net) v.val := by\n  apply leftOne_clock net data old extra p _ v hg he\n  all_goals unfold localDegree;dsimp only;omega\n\n/-- The complete static left cache retains every actual repeated eager-copy report. -/\ntheorem acquireLeft_clock_bound {a : ℕ} (net : SemiprimeD1TensorNetwork.Network)\n    (data : Pullback net a) (old : Context) (extra : List ℕ) (p : ℕ)\n    (hg : SemiprimeD1TensorNetwork.Good old net) (he : 0<extra.prod) :\n    (acquireLeft net data old extra p).clock ≤\n      (List.ofFn (fun v : Fin (net.leftCount+net.rows.length) =>\n        leftBudget old extra p (localDegree net data v)\n          (SemiprimeD1ChildTableOrder.acquire (SemiprimeD1TensorNetwork.owner net.rows) data v).clock\n          (SemiprimeD1NetworkStateResources.inventory net) v.val)).sum+\n      10*(net.leftCount+net.rows.length+1) := by\n  rw [acquireLeft_clock]\n  apply Nat.add_le_add_right\n  simp only [Vector.toList_ofFn,List.map_ofFn,Function.comp_def,List.sum_ofFn]\n  apply Finset.sum_le_sum\n  intro v hv\n  exact leftOne_clock_closed net data old extra p v hg he\n\nend RiemannGaussian.SemiprimeD1ChildNetworkTapeBudget\n","RiemannGaussian.SemiprimeD1ChildWordPolynomial":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ChildWordClockFactor\nimport RiemannGaussian.SemiprimeD1ChildPrefactorPolynomial\n\n/-! # Fixed scalar growth of the actual word-only eager child\nThe actual old inventory is an explicit scalar input to the coefficient; full\n2^(3D) table serialization is factored separately. Original grid cardinality is\ncapped separately from its exponent, never replaced by an exponential cap.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2500000\nset_option maxRecDepth 8192\nnamespace RiemannGaussian.SemiprimeD1ChildWordPolynomial\nopen SemiprimeD1JetAxes SemiprimeD1ChildPrefactorPolynomial\n\n/-- Diagonal scalar coefficient of the actual physical word/table backend. -/\ndef envelope (S a : ℕ) : ℕ :=\n  SemiprimeD1ChildWordClockFactor.prefactor (context S) (axes S)\n    S a S S S S S S S S S S S S S S S\n\n/-- Fixed constants bound the actual expanded scalar prefactor on all original\nexponent/cardinality pairs satisfying their independently derived caps. -/\ntheorem envelope_monomial : Bound envelope := by\n  unfold envelope\n  simp only [SemiprimeD1ChildWordClockFactor.prefactor,\n    SemiprimeD1ChildWordClockFactor.leftFactor,\n    SemiprimeD1WordPacketClockFactor.rightFactor,\n    SemiprimeD1WordPacketClockFactor.storageCoefficient,\n    SemiprimeD1WordPacketClockFactor.tapeCoefficient,\n    SemiprimeD1ChildTableCopyTape.tapeBudget,\n    SemiprimeD1ChildTableCopy.liftBudget,\n    SemiprimeD1WordPacketEntryClock.wireClock,\n    SemiprimeD1WordPacketEntryClock.gatherClock,\n    SemiprimeD1WordPacketEntryClock.nonAffineClock,\n    SemiprimeD1WordPacketEntryClock.entryPolynomial,\n    SemiprimeD1WordPacketArithmeticClock.mulClock,\n    SemiprimeD1WordPacketArithmeticClock.addClock,\n    SemiprimeD1WordPacketArithmeticClock.oneClock,\n    SemiprimeD1WordPacketArithmeticClock.signClock,\n    SemiprimeD1WordPacketArithmeticClock.baseClock,\n    SemiprimeD1WordPacketArithmeticClock.rowBaseClock,\n    SemiprimeD1WordPacketCoefficientClock.sameBitClock,\n    SemiprimeD1WordPacketCoefficientClock.modeClock,\n    SemiprimeD1WordPacketCoefficientClock.coefficientClock,\n    SemiprimeD1WordPacketCoefficientClock.recipeClock,\n    SemiprimeD1PacketSourceClock.powerClock,\n    SemiprimeD1PacketSourceClock.sourceTermClock,\n    SemiprimeD1PacketSourceClock.sourceFactorClock,\n    SemiprimeD1PacketArithmeticClock.mulClock,\n    SemiprimeD1PacketArithmeticClock.addClock,\n    SemiprimeD1PacketArithmeticClock.oneClock,\n    SemiprimeD1JetWordKernelBounds.signedBudget,\n    SemiprimeD1JetWordKernelBounds.sourceBudget,\n    SemiprimeD1JetWordKernelBounds.linearBudget,\n    SemiprimeD1JetWordKernelBounds.entryBudget,\n    SemiprimeD1JetWordKernelBounds.originalWidth,\n    SemiprimeD1JetWordKernelBounds.budget,\n    SemiprimeD1KernelEntryBounds.stepBudget,\n    SemiprimeD1KernelEntryBounds.contentWidth,\n    SemiprimeD1KernelEntryBounds.denominatorWidth,\n    SemiprimeD1KernelEntryBounds.budget,\n    SemiprimeD1KernelProductBits.budget,\n    SemiprimeD1KernelDenominatorBits.budget,\n    SemiprimeD1NormalizedLinearBits.budget,\n    SemiprimeD1JetWordModeScalarBounds.inverseBudget,\n    SemiprimeD1JetWordModeScalarBounds.stepBudget,\n    SemiprimeD1JetWordModeScalarBounds.budget,\n    SemiprimeD1JetWordModeBounds.budget,\n    SemiprimeD1JetModeBitsBounds.geometricStage,\n    SemiprimeD1JetRingBounds.termBudget,\n    SemiprimeD1JetRingBounds.mulAtBudget,\n    SemiprimeD1JetRingBounds.mulBudget,\n    SemiprimeD1JetAffineCoefficientBounds.addBudget,\n    SemiprimeD1JetAffineCoefficientBounds.stageConstant,\n    SemiprimeSourceHistogramPortKeys.encodeBudget,\n    SemiprimeD1WireKernelOriginal.size,context,axes,SemiprimeD1JetAxes.Context.rank,\n    List.prod_append,List.prod_replicate,List.prod_cons,List.prod_nil,one_pow,\n    List.length_append,List.length_replicate,List.length_cons,List.length_nil,\n    Nat.one_mul,Nat.mul_one,pow_succ]\n  gridBoundArithmetic\n\n\n\n/-- Literal original scalar and context fields dominate the new backend's\nexpanded physical/tape prefactor. Actual inventory I remains an explicit cap. -/\ntheorem prefactor_le_envelope (old : Context) (extra : List ℕ)\n    (p a D A K P T B L E NF M I W G O H U : ℕ)\n    (hrank : old.rank ≤ U) (hprecision : old.precision ≤ U)\n    (haxes : old.axes.length ≤ U) (hprod : extra.prod ≤ U) (hlen : extra.length ≤ U)\n    (h : ∀x∈[p,D,A,K,P,T,B,L,E,NF,M,I,W,G,O,H],x ≤ U) :\n    SemiprimeD1ChildWordClockFactor.prefactor old extra p a D A K P T B L E NF M I W G O H ≤\n      envelope U a := by\n  change old.axes.prod ≤ U at hrank\n  have h0 : p ≤ U := h p (by simp)\n  have h1 : D ≤ U := h D (by simp)\n  have h2 : A ≤ U := h A (by simp)\n  have h3 : K ≤ U := h K (by simp)\n  have h4 : P ≤ U := h P (by simp)\n  have h5 : T ≤ U := h T (by simp)\n  have h6 : B ≤ U := h B (by simp)\n  have h7 : L ≤ U := h L (by simp)\n  have h8 : E ≤ U := h E (by simp)\n  have h9 : NF ≤ U := h NF (by simp)\n  have h10 : M ≤ U := h M (by simp)\n  have h11 : I ≤ U := h I (by simp)\n  have h12 : W ≤ U := h W (by simp)\n  have h13 : G ≤ U := h G (by simp)\n  have h14 : O ≤ U := h O (by simp)\n  have h15 : H ≤ U := h H (by simp)\n  simp only [envelope,SemiprimeD1ChildWordClockFactor.prefactor,\n    SemiprimeD1ChildWordClockFactor.leftFactor,\n    SemiprimeD1WordPacketClockFactor.rightFactor,\n    SemiprimeD1WordPacketClockFactor.storageCoefficient,\n    SemiprimeD1WordPacketClockFactor.tapeCoefficient,\n    SemiprimeD1ChildTableCopyTape.tapeBudget,\n    SemiprimeD1ChildTableCopy.liftBudget,\n    SemiprimeD1WordPacketEntryClock.wireClock,\n    SemiprimeD1WordPacketEntryClock.gatherClock,\n    SemiprimeD1WordPacketEntryClock.nonAffineClock,\n    SemiprimeD1WordPacketEntryClock.entryPolynomial,\n    SemiprimeD1WordPacketArithmeticClock.mulClock,\n    SemiprimeD1WordPacketArithmeticClock.addClock,\n    SemiprimeD1WordPacketArithmeticClock.oneClock,\n    SemiprimeD1WordPacketArithmeticClock.signClock,\n    SemiprimeD1WordPacketArithmeticClock.baseClock,\n    SemiprimeD1WordPacketArithmeticClock.rowBaseClock,\n    SemiprimeD1WordPacketCoefficientClock.sameBitClock,\n    SemiprimeD1WordPacketCoefficientClock.modeClock,\n    SemiprimeD1WordPacketCoefficientClock.coefficientClock,\n    SemiprimeD1WordPacketCoefficientClock.recipeClock,\n    SemiprimeD1PacketSourceClock.powerClock,\n    SemiprimeD1PacketSourceClock.sourceTermClock,\n    SemiprimeD1PacketSourceClock.sourceFactorClock,\n    SemiprimeD1PacketArithmeticClock.mulClock,\n    SemiprimeD1PacketArithmeticClock.addClock,\n    SemiprimeD1PacketArithmeticClock.oneClock,\n    SemiprimeD1JetWordKernelBounds.signedBudget,\n    SemiprimeD1JetWordKernelBounds.sourceBudget,\n    SemiprimeD1JetWordKernelBounds.linearBudget,\n    SemiprimeD1JetWordKernelBounds.entryBudget,\n    SemiprimeD1JetWordKernelBounds.originalWidth,\n    SemiprimeD1JetWordKernelBounds.budget,\n    SemiprimeD1KernelEntryBounds.stepBudget,\n    SemiprimeD1KernelEntryBounds.contentWidth,\n    SemiprimeD1KernelEntryBounds.denominatorWidth,\n    SemiprimeD1KernelEntryBounds.budget,\n    SemiprimeD1KernelProductBits.budget,\n    SemiprimeD1KernelDenominatorBits.budget,\n    SemiprimeD1NormalizedLinearBits.budget,\n    SemiprimeD1JetWordModeScalarBounds.inverseBudget,\n    SemiprimeD1JetWordModeScalarBounds.stepBudget,\n    SemiprimeD1JetWordModeScalarBounds.budget,\n    SemiprimeD1JetWordModeBounds.budget,\n    SemiprimeD1JetModeBitsBounds.geometricStage,\n    SemiprimeD1JetRingBounds.termBudget,\n    SemiprimeD1JetRingBounds.mulAtBudget,\n    SemiprimeD1JetRingBounds.mulBudget,\n    SemiprimeD1JetAffineCoefficientBounds.addBudget,\n    SemiprimeD1JetAffineCoefficientBounds.stageConstant,\n    SemiprimeSourceHistogramPortKeys.encodeBudget,\n    SemiprimeD1WireKernelOriginal.size,context,axes,SemiprimeD1JetAxes.Context.rank,\n    List.prod_append,List.prod_replicate,List.prod_cons,List.prod_nil,one_pow,\n    List.length_append,List.length_replicate,List.length_cons,List.length_nil,\n    Nat.one_mul,Nat.mul_one,pow_succ]\n  gcongr <;> omega\n\nend RiemannGaussian.SemiprimeD1ChildWordPolynomial\n","RiemannGaussian.SemiprimeD1CrossingBit":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport Mathlib\n\n/-! # Actual same-bit crossing excludes the next two-adic power\nNo grid bound and no displacement valuation premise is assumed. Negative\ninterpolation nodes are included by integer remainder arithmetic.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1CrossingBit\n\n/-- Adding exactly2^i flips the i-th bit even after reducing modulo2^(i+1). -/\ntheorem same_bit_not_shift (x y i : ℕ) (hbit : x.testBit i=y.testBit i) :\n    y%2^(i+1)≠(2^i+x)%2^(i+1) := by\n  intro h\n  have hb:=congrArg (fun z : ℕ => z.testBit i) h\n  simp only [Nat.testBit_mod_two_pow,Nat.lt_succ_self,decide_true,Bool.true_and,\n    Nat.testBit_two_pow_add_eq] at hb\n  rw [←hbit] at hb\n  cases h : x.testBit i <;> simp [h] at hb\n\n/-- Original crossing displacement cannot be divisible by the next power of two. -/\ntheorem crossing_not_dvd (t : ℤ) (x y i : ℕ)\n    (ht : t%(2^(i+1):ℤ)=(2^i:ℤ)) (hbit : x.testBit i=y.testBit i) :\n    ¬(2^(i+1):ℤ)∣t-y+x := by\n  intro hd\n  have hp : (0:ℤ)<2^i := by positivity\n  have ht' : Int.ModEq (2^(i+1)) t (2^i) := by\n    change t%_=(2^i:ℤ)%_\n    rw [ht,Int.emod_eq_of_lt (by positivity) (by rw [pow_succ];omega)]\n  have hz := hd.modEq_zero_int.add_right (y:ℤ)\n  have hx := ht'.add_right (x:ℤ)\n  have hz' : Int.ModEq (2^(i+1)) (t+x) y := by convert hz using 1 <;> ring\n  have hy : Int.ModEq (2^(i+1)) (y:ℤ) (2^i+x) := hz'.symm.trans hx\n  have hn : Nat.ModEq (2^(i+1)) y (2^i+x) := by\n    apply Int.natCast_modEq_iff.mp\n    simpa only [Nat.cast_pow,Nat.cast_ofNat,Nat.cast_add] using hy\n  exact same_bit_not_shift x y i hbit hn\n\n/-- Same-bit crossings have a nonzero displacement with valuation at most i. -/\ntheorem crossing_nonzero_and_val_le (t : ℤ) (x y i : ℕ)\n    (ht : t%(2^(i+1):ℤ)=(2^i:ℤ)) (hbit : x.testBit i=y.testBit i) :\n    (t - (y : ℤ) + (x : ℤ) ≠ 0) ∧ (padicValInt 2 (t - y + x) ≤ i) := by\n  have hd:=crossing_not_dvd t x y i ht hbit\n  constructor\n  · intro hz\n    apply hd\n    rw [hz]\n    exact dvd_zero _\n  · by_contra h\n    have hv : i+1≤padicValInt 2 (t-y+x) := by omega\n    exact hd ((padicValInt_dvd_iff_of_ne_one (by decide : 2≠1) (i+1) _).mpr (Or.inr hv))\n\n/-- An actual nonzero node of valuation i has the unique half-modulus residue.\nThis includes negative odd quotients. -/\ntheorem node_mod_of_valuation (t : ℤ) (i : ℕ) (ht : t≠0)\n    (hi : padicValInt 2 t=i) : t%(2^(i+1):ℤ)=(2^i:ℤ) := by\n  have hd : (2:ℤ)^i∣t := by rw [←hi];exact padicValInt_dvd t\n  have hn : ¬(2:ℤ)^(i+1)∣t := by\n    intro hpow\n    have hh := (padicValInt_dvd_iff_of_ne_one (p:=2) (by decide : 2≠1) (i+1) t).mp hpow\n    rcases hh with hz|hv\n    · exact ht hz\n    · omega\n  rcases hd with ⟨q,hq⟩\n  have hqnot : ¬(2:ℤ)∣q := by\n    intro he\n    rcases he with ⟨k,hk⟩\n    apply hn\n    refine ⟨k,?_⟩\n    rw [hq,hk,pow_succ]\n    ring\n  have hqr : q%2=1 := by\n    have hzero : q%2≠0 := by simpa only [Int.dvd_iff_emod_eq_zero] using hqnot\n    have hnon:=Int.emod_nonneg q (by decide : (2:ℤ)≠0)\n    have hlt:=Int.emod_lt_of_pos q (by decide : (0:ℤ)<2)\n    omega\n  rw [hq,pow_succ,Int.mul_emod_mul_of_pos q 2 (by positivity),hqr,mul_one]\n\n/-- Original valuation-plus-same-bit conditions discharge displacement assumptions. -/\ntheorem crossing_of_valuation (t : ℤ) (x y i : ℕ) (ht : t≠0)\n    (hi : padicValInt 2 t=i) (hbit : x.testBit i=y.testBit i) :\n    (t - (y : ℤ) + (x : ℤ) ≠ 0) ∧ (padicValInt 2 (t - y + x) ≤ i) :=\n  crossing_nonzero_and_val_le t x y i (node_mod_of_valuation t i ht hi) hbit\n\nend RiemannGaussian.SemiprimeD1CrossingBit\n","RiemannGaussian.SemiprimeD1DyadicCongruence":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1DyadicInteger\nimport RiemannGaussian.SemiprimeBitArithmetic\n\n/-! # Exact kernel of the legitimate dyadic reduction map\nActual child residue equality derives the scalar D.5 error contract. The kernel\nproof uses actual canonical odd denominators, not a rational-to-modular map.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1DyadicCongruence\nopen SemiprimeD1DyadicBounds SemiprimeD1DyadicInteger SemiprimeD1RecoveryResidue\n  SemiprimeD1CrossingCoefficient SemiprimeD1CrossingResidue\n\n/-- The kernel of actual restricted reduction is EXACTLY the required dyadic precision. -/\ntheorem reduce_zero_iff (p : ℕ) (q : ℚ) (hq : AtLeast 0 q) :\n    reduce p q=0 ↔ AtLeast (p:ℤ) q := by\n  refine ⟨?_,reduce_error_zero p q⟩\n  intro hz\n  by_cases hqz : q=0\n  · rw [hqz]\n    exact zero _\n  have hodd := denominator_odd q hq\n  have hnot : ¬2∣q.den := by\n    simpa only [← even_iff_two_dvd] using Nat.not_even_iff_odd.mpr hodd\n  have hvden : padicValNat 2 q.den=0 := padicValNat.eq_zero_of_not_dvd hnot\n  have ho : Odd (canonicalFraction q).denominator := by\n    change Odd ((q.den:ℕ):ℤ)\n    exact_mod_cast hodd\n  have he := residue_denominator p (canonicalFraction q) ho\n  have he' : (q.den:ZMod (2^p))*reduce p q=(q.num:ZMod (2^p)) := by\n    simpa only [reduce,canonicalFraction,Int.cast_natCast] using he\n  rw [hz,mul_zero] at he'\n  have hd := (ZMod.intCast_zmod_eq_zero_iff_dvd q.num (2^p)).mp he'.symm\n  have hd' : (2:ℤ)^p∣q.num := by exact_mod_cast hd\n  have hv := (padicValInt_dvd_iff (p:=2) p q.num).mp hd'\n  have hvn := hv.resolve_left (Rat.num_ne_zero.mpr hqz)\n  right\n  simp only [padicValRat,hvden,Nat.cast_zero,sub_zero]\n  exact_mod_cast hvn\n\n/-- Integral rationals have the same actual residue IFF their difference has full precision. -/\ntheorem reduce_eq_iff (p : ℕ) (q r : ℚ) (hq : AtLeast 0 q) (hr : AtLeast 0 r) :\n    reduce p q=reduce p r ↔ AtLeast (p:ℤ) (q-r) := by\n  have hs : AtLeast 0 (q-r) := by simpa only [sub_eq_add_neg] using add hq (neg hr)\n  have he := map_sub (reduction p) (⟨q,hq⟩:integers) (⟨r,hr⟩:integers)\n  change reduce p (q-r)=reduce p q-reduce p r at he\n  rw [← sub_eq_zero,← he]\n  exact reduce_zero_iff p (q-r) hs\n\n/-- Actual canonical child word equality DERIVES the retained D.5 representative error. -/\ntheorem child_word_error (p : ℕ) (q : ℚ) (hq : AtLeast 0 q) (bs : List Bool)\n    (hchild : reduce p q=(SemiprimeBitArithmetic.bitValue bs:ZMod (2^p))) :\n    AtLeast (p:ℤ) ((SemiprimeBitArithmetic.bitValue bs:ℚ)-q) := by\n  have hi : AtLeast 0 (SemiprimeBitArithmetic.bitValue bs:ℚ) := by\n    simpa only [Int.cast_natCast] using integer (SemiprimeBitArithmetic.bitValue bs:ℤ)\n  have he : reduce p (SemiprimeBitArithmetic.bitValue bs:ℚ)=\n      (SemiprimeBitArithmetic.bitValue bs:ZMod (2^p)) := by\n    simpa only [Int.cast_natCast] using reduce_integer p (SemiprimeBitArithmetic.bitValue bs:ℤ)\n  exact (reduce_eq_iff p _ q hi hq).mp (he.trans hchild.symm)\n\n/-- The explicit integral source needs no supplied integrality proof at the child seam. -/\ntheorem source_word_error (p : ℕ) (q : integers) (bs : List Bool)\n    (hchild : reduction p q=(SemiprimeBitArithmetic.bitValue bs:ZMod (2^p))) :\n    AtLeast (p:ℤ) ((SemiprimeBitArithmetic.bitValue bs:ℚ)-q.val) :=\n  child_word_error p q.val q.property bs hchild\n\nend RiemannGaussian.SemiprimeD1DyadicCongruence\n","RiemannGaussian.SemiprimeD1DyadicInteger":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecoveryResidue\n\n/-! # The legitimate odd-denominator reduction ring homomorphism\nReduction is defined ONLY on the subring of2-adically integral rationals. It is\nnot a ring homomorphism from all rationals into a characteristic2-power ring.\nThis semantic bridge has no attached execution-cost claim.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1DyadicInteger\nopen scoped BigOperators\nopen SemiprimeD1WireKernelOriginal SemiprimeD1DyadicBounds SemiprimeD1RecoveryResidue\n  SemiprimeD1CrossingCoefficient SemiprimeD1CrossingResidue SemiprimeD1CrossingModulo\n\n/-- The actual rational subring with odd canonical denominators. -/\ndef integers : Subring ℚ where\n  carrier := AtLeast 0\n  zero_mem' := zero 0\n  one_mem' := one\n  add_mem' := fun ha hb => add ha hb\n  neg_mem' := fun ha => neg ha\n  mul_mem' := by\n    intro a b ha hb\n    change AtLeast 0 (a*b)\n    exact mul ha hb\n\n/-- Native product fraction used only to prove consistency of unit inversion. -/\ndef fractionMul (a b : Coefficient) : Coefficient :=\n  ⟨a.numerator*b.numerator,a.denominator*b.denominator⟩\n\n/-- Literal fraction multiplication has its original rational value. -/\ntheorem fractionMul_value (a b : Coefficient) :\n    value (fractionMul a b)=value a*value b := by\n  simp only [value,fractionMul,Int.cast_mul]\n  ring\n\n/-- Multiplication of actual odd-denominator fractions commutes with native reduction. -/\ntheorem fractionMul_residue (p : ℕ) (a b : Coefficient)\n    (ha : Odd a.denominator) (hb : Odd b.denominator) :\n    residue p (fractionMul a b)=residue p a*residue p b := by\n  apply (odd_unit _ (ha.mul hb) p).mul_left_cancel\n  change ((fractionMul a b).denominator:ZMod (2^p))*_= _\n  rw [residue_denominator p (fractionMul a b) (ha.mul hb)]\n  simp only [fractionMul,Int.cast_mul]\n  calc\n    _ = ((a.denominator:ZMod (2^p))*residue p a)*\n        ((b.denominator:ZMod (2^p))*residue p b) := by\n          rw [residue_denominator p a ha,residue_denominator p b hb]\n    _ = _ := by ring\n\n/-- Restricted native reduction preserves addition; integrality derives every oddness fact. -/\ntheorem reduce_add (p : ℕ) (a b : ℚ) (ha : AtLeast 0 a) (hb : AtLeast 0 b) :\n    reduce p (a+b)=reduce p a+reduce p b := by\n  have hao : Odd (canonicalFraction a).denominator := by\n    change Odd ((a.den:ℕ):ℤ)\n    exact_mod_cast denominator_odd a ha\n  have hbo : Odd (canonicalFraction b).denominator := by\n    change Odd ((b.den:ℕ):ℤ)\n    exact_mod_cast denominator_odd b hb\n  have hsum : Odd (canonicalFraction (a+b)).denominator := by\n    change Odd (((a+b).den:ℕ):ℤ)\n    exact_mod_cast denominator_odd (a+b) (add ha hb)\n  have he := residue_eq_of_value_eq p (canonicalFraction (a+b))\n    (fractionAdd (canonicalFraction a) (canonicalFraction b)) hsum (hao.mul hbo)\n    (by rw [canonicalFraction_value,fractionAdd_value _ _ hao hbo,canonicalFraction_value,canonicalFraction_value])\n  exact he.trans (fractionAdd_residue p _ _ hao hbo)\n\n/-- Restricted native reduction preserves multiplication with no illegal Q-to-ZMod map. -/\ntheorem reduce_mul (p : ℕ) (a b : ℚ) (ha : AtLeast 0 a) (hb : AtLeast 0 b) :\n    reduce p (a*b)=reduce p a*reduce p b := by\n  have hao : Odd (canonicalFraction a).denominator := by\n    change Odd ((a.den:ℕ):ℤ)\n    exact_mod_cast denominator_odd a ha\n  have hbo : Odd (canonicalFraction b).denominator := by\n    change Odd ((b.den:ℕ):ℤ)\n    exact_mod_cast denominator_odd b hb\n  have hi : AtLeast 0 (a*b) := by simpa only [add_zero] using mul ha hb\n  have hprod : Odd (canonicalFraction (a*b)).denominator := by\n    change Odd (((a*b).den:ℕ):ℤ)\n    exact_mod_cast denominator_odd (a*b) hi\n  have he := residue_eq_of_value_eq p (canonicalFraction (a*b))\n    (fractionMul (canonicalFraction a) (canonicalFraction b)) hprod (hao.mul hbo)\n    (by rw [canonicalFraction_value,fractionMul_value,canonicalFraction_value,canonicalFraction_value])\n  exact he.trans (fractionMul_residue p _ _ hao hbo)\n\n/-- The legitimate original odd-localization map into the finite dyadic ring. -/\ndef reduction (p : ℕ) : integers →+* ZMod (2^p) where\n  toFun q := reduce p q.val\n  map_zero' := by simpa using reduce_integer p 0\n  map_one' := by simpa using reduce_integer p 1\n  map_add' a b := reduce_add p a.val b.val a.property b.property\n  map_mul' a b := reduce_mul p a.val b.val a.property b.property\n\n/-- Integer constants have their usual modular values under the restricted map. -/\ntheorem reduction_integer (p : ℕ) (z : ℤ) : reduction p (z:integers)=(z:ZMod (2^p)) := by\n  change reduce p (z:ℚ)=_\n  exact reduce_integer p z\n\n/-- The restricted map commutes with finite contractions, including zero divisors\nin the target ring. Every source factor is genuinely in the integral subring. -/\ntheorem reduction_contraction {X E : Type*} (xs : Finset X) (es : Finset E)\n    (p : ℕ) (T : X → E → integers) :\n    reduction p (∑x∈xs,∏e∈es,T x e)=∑x∈xs,∏e∈es,reduction p (T x e) := by\n  simp only [map_sum,map_prod]\n\nend RiemannGaussian.SemiprimeD1DyadicInteger\n","RiemannGaussian.SemiprimeD1HermiteWeightHeight":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1HermiteDenominatorBits\n\n/-! # Actual original D.9 weight and weightPrefix common denominators\nEvery retained weight and partial coefficient sum uses ONE original-derived\ncommon denominator. No repeated-sum denominator multiplication is used.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1HermiteWeightHeight\nopen scoped BigOperators\nopen SemiprimeJetArray SemiprimeJetArrayHeight SemiprimeHermiteArrayHeight\n  SemiprimeD1JetRecoveryWeights SemiprimeD1JetRecoveryGrid SemiprimeD1TaperedLoss\n  SemiprimeD1WireKernelOriginal SemiprimeD1HermiteDenominatorHeight\n  SemiprimeD1HermiteDenominatorBits\n\n/-- Literal representations of powers have fixed power denominators. -/\ntheorem representation_pow {q : ℚ} {d B : ℕ} (hq : Representation q d B) (n : ℕ) :\n    Representation (q^n) (d^n) (B^n) := by\n  induction n with\n  | zero => exact ⟨1,by simp,by simp⟩\n  | succ n ih =>\n    simpa only [pow_succ] using representation_mul ih hq\n\n/-- Actual scalar E_t0 uses acquired signed integer products with a positive denominator. -/\ndef scalarDenominator (a h u t : ℕ) : ℕ :=\n  (SemiprimeD1JetRecoveryScalarHeight.denominator a h u t).natAbs\n\n/-- Actual E_t0 numerator magnitude before reduction. -/\ndef scalarNumerator (a h u t : ℕ) : ℕ :=\n  (SemiprimeD1JetRecoveryScalarHeight.numerator a h u t).natAbs\n\n/-- The actual scalar denominator is positive, not advised. -/\ntheorem scalarDenominator_pos (a h u t : ℕ) : 0<scalarDenominator a h u t :=\n  Int.natAbs_pos.mpr (SemiprimeD1JetRecoveryScalarHeight.denominator_ne_zero a h u t)\n\n/-- Exact original E_t0 representation, preserving all scalar signs. -/\ntheorem scalar_representation (a h u t : ℕ) :\n    Representation (Ezero a h u t) (scalarDenominator a h u t) (scalarNumerator a h u t) := by\n  rw [SemiprimeD1JetRecoveryScalarHeight.ratio_spec]\n  exact int_ratio_representation _ _\n\n/-- Original evaluation argument has numerator at most2L and denominator exactly2L. -/\ntheorem argument_representation (a : ℕ) (t : Fin (size a)) :\n    Representation (SemiprimeD1WeightPrecision.argument a t.val) (size a) (size a) := by\n  have h := int_ratio_representation (-point a t.val) ((2:ℤ)^(a+1))\n  have he : ((2:ℤ)^(a+1)).natAbs=size a := by norm_num [Int.natAbs_pow,SemiprimeD1WireKernelOriginal.size]\n  rw [he] at h\n  have hm := representation_mono h (by\n    simpa only [Int.natAbs_neg] using (SemiprimeD1JetRecoveryScalarHeight.point_abs_lt a t.val t.isLt).le)\n  simpa only [SemiprimeD1WeightPrecision.argument,Int.cast_neg,Int.cast_pow,Int.cast_ofNat] using hm\n\n/-- Power padding uses a single actual2L denominator, not a new denominator per sum. -/\ntheorem argument_power_representation (a h u : ℕ) (t : Fin (size a)) (k : ℕ)\n    (hk : k≤nodeMultiplicity a h u t.val) :\n    Representation ((SemiprimeD1WeightPrecision.argument a t.val)^k)\n      ((size a)^nodeMultiplicity a h u t.val) ((size a)^nodeMultiplicity a h u t.val) := by\n  exact representation_power_extend (size a) (size a) k _ (by unfold SemiprimeD1WireKernelOriginal.size;positivity)\n    le_rfl hk (representation_pow (argument_representation a t) k)\n\n/-- Actual common denominator of ALL retained weights at one original node. -/\ndef weightDenominator (a h u t : ℕ) : ℕ :=\n  scalarDenominator a h u t*(sourceDenominator a h u t*size a)^nodeMultiplicity a h u t\n\n/-- Explicit fixed numerator envelope for ALL actual weight sums/prefixes at one node. -/\ndef weightNumerator (a h u t : ℕ) : ℕ :=\n  scalarNumerator a h u t*nodeMultiplicity a h u t*\n    (inverseBase (nodeMultiplicity a h u t) (sourceDenominator a h u t)\n      (sourceNumerator a h u t)*size a)^nodeMultiplicity a h u t\n\n/-- Actual native scalar coefficient-sum weightPrefix, with the same original caches as acquire. -/\ndef weightPrefix (a h u t j len : ℕ) : ℚ :=\n  Ezero a h u t*∑k∈Finset.range len,if j≤k then\n    coefficient (acquire a h u t).inverse.coefficients (k-j)*\n      (SemiprimeD1WeightPrecision.argument a t)^k else 0\n\n/-- EVERY actual node-weight weightPrefix has ONE fixed denominator, derived solely from\noriginal factors/inverse recurrence and literal loop indices. -/\ntheorem prefix_representation (a h u : ℕ) (t : Fin (size a))\n    (hq : 0<nodeMultiplicity a h u t.val) (j len : ℕ) (hlen : len≤nodeMultiplicity a h u t.val) :\n    Representation (weightPrefix a h u t.val j len) (weightDenominator a h u t.val) (weightNumerator a h u t.val) := by\n  let q := nodeMultiplicity a h u t.val\n  let D := sourceDenominator a h u t.val\n  let V := inverseBase q D (sourceNumerator a h u t.val)\n  have hs : Representation\n      (∑k∈Finset.range len,if j≤k then coefficient (acquire a h u t.val).inverse.coefficients (k-j)*\n          (SemiprimeD1WeightPrecision.argument a t.val)^k else 0)\n      ((D*size a)^q) (len*(V*size a)^q) := by\n    have hh := representation_sum (Finset.range len)\n      (fun k => if j≤k then coefficient (acquire a h u t.val).inverse.coefficients (k-j)*\n        (SemiprimeD1WeightPrecision.argument a t.val)^k else 0) ((D*size a)^q) ((V*size a)^q) (by\n        intro k hk\n        have hkl := Finset.mem_range.mp hk\n        by_cases hj : j≤k\n        · simp only [hj,ite_true]\n          have hm := representation_mul (original_inverse_representation a h u t hq (k-j) (by omega))\n            (argument_power_representation a h u t k (by omega))\n          simpa only [mul_pow] using hm\n        · simp only [hj,ite_false]\n          exact representation_mono (representation_zero _) (Nat.zero_le _))\n    simpa only [Finset.card_range] using hh\n  have hm := representation_mul (scalar_representation a h u t.val) hs\n  apply representation_mono hm\n  unfold weightNumerator\n  dsimp only [q,D,V] at *\n  nlinarith [Nat.mul_le_mul_left (scalarNumerator a h u t.val*\n    (inverseBase (nodeMultiplicity a h u t.val) (sourceDenominator a h u t.val)\n      (sourceNumerator a h u t.val)*size a)^nodeMultiplicity a h u t.val) hlen]\n\n/-- Each actual stored weight is the full weightPrefix and has the SAME common denominator. -/\ntheorem weight_representation (a h u : ℕ) (t : Fin (size a))\n    (hq : 0<nodeMultiplicity a h u t.val) (j : ℕ) (hj : j<nodeMultiplicity a h u t.val) :\n    Representation (coefficient (acquire a h u t.val).weights j)\n      (weightDenominator a h u t.val) (weightNumerator a h u t.val) := by\n  rw [acquire_weight a h u t.val j hj]\n  exact prefix_representation a h u t hq j _ le_rfl\n\n/-- The original weight denominator is positive even when a partial sum is zero. -/\ntheorem weightDenominator_pos (a h u t : ℕ) : 0<weightDenominator a h u t := by\n  unfold weightDenominator\n  exact Nat.mul_pos (scalarDenominator_pos _ _ _ _) (pow_pos\n    (Nat.mul_pos (sourceDenominator_pos _ _ _ _) (by unfold SemiprimeD1WireKernelOriginal.size;positivity)) _)\n\n/-- Canonical normalization of every actual weight weightPrefix cannot increase the derived bounds. -/\ntheorem prefix_reduced_bounds (a h u : ℕ) (t : Fin (size a))\n    (hq : 0<nodeMultiplicity a h u t.val) (j len : ℕ) (hlen : len≤nodeMultiplicity a h u t.val) :\n    (weightPrefix a h u t.val j len).den≤weightDenominator a h u t.val ∧\n    (weightPrefix a h u t.val j len).num.natAbs≤weightNumerator a h u t.val :=\n  representation_reduced_bound (weightDenominator_pos _ _ _ _)\n    (prefix_representation a h u t hq j len hlen)\n\nend RiemannGaussian.SemiprimeD1HermiteWeightHeight\n","RiemannGaussian.SemiprimeD1JetEmbedding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetOperations\n\n/-! # Actual same-precision outer-axis word embedding\nAll old coordinates survive. No upward-precision ring homomorphism is asserted.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 200000\nnamespace RiemannGaussian.SemiprimeD1JetEmbedding\nopen scoped BigOperators\nopen SemiprimeD1JetAxes SemiprimeD1JetBoxIndex SemiprimeD1JetInterpretation\nnoncomputable section\n\n/-- Positive outer radices split the actual dense extent. -/\ntheorem rank_split (q n : ℕ) (hq : 0<q) : q*n=n+n*(q-1) := by\n  have h := Nat.sub_add_cancel hq\n  nlinarith\n\n\n/-- The runtime axis-list dimensions agree with the quotient's fresh-axis dimensions. -/\ntheorem dims_cons (q : ℕ) (axes : List ℕ) :\n    dims (q::axes)=SemiprimeD1JetAlgebra.outerDims q (dims axes) := by\n  funext i\n  refine Fin.cases ?_ (fun j=>?_) i <;> rfl\n\n/-- Every old dense index has zero fresh exponent and all original exponents. -/\ntheorem exponent_shift (q : ℕ) (axes : List ℕ) (i : ℕ) (hi : i<axes.prod) :\n    exponent (q::axes) i=Finsupp.embDomain (SemiprimeD1JetAlgebra.axisShift axes.length)\n      (exponent axes i) := by\n  ext j\n  refine Fin.cases ?_ (fun k=>?_) j\n  · have hz : (Finsupp.embDomain (SemiprimeD1JetAlgebra.axisShift axes.length)\n        (exponent axes i)) 0=0 := by\n      apply Finsupp.embDomain_of_notMem_range\n      rintro ⟨k,hk⟩\n      exact Fin.succ_ne_zero k hk\n    simp only [exponent_apply,digitFn,Fin.cases_zero,Nat.div_eq_of_lt hi,hz]\n  · change digitFn axes (i%axes.prod) k=\n      (Finsupp.embDomain (SemiprimeD1JetAlgebra.axisShift axes.length) (exponent axes i))\n        ((SemiprimeD1JetAlgebra.axisShift axes.length) k)\n    rw [Finsupp.embDomain_apply_self,Nat.mod_eq_of_lt hi]\n    rfl\n\n/-- Literal finite-series representative of the acquired dense words. -/\ndef series (ctx : Context) (ws : List (List Bool)) :\n    MvPowerSeries (Fin ctx.axes.length) (ZMod (2^ctx.precision)) :=\n  ∑i : Fin ctx.rank,MvPowerSeries.monomial (exponent ctx.axes i)\n    (SemiprimeD1JetRingBits.coefficient ctx ws i.val)\n\n/-- Actual interpretation projects its literal finite acquired series. -/\ntheorem interpret_series (ctx : Context) (ws : List (List Bool)) :\n    interpret ctx ws=SemiprimeD1JetAlgebra.project (dims ctx.axes) (series ctx ws) := by\n  simp only [interpret,series,map_sum,basis]\n\n/-- Actual appended zero words extend the finite series by variable renaming only. -/\ntheorem series_zero_extend (ctx : Context) (ws : List (List Bool)) (q : ℕ) (hq : 0<q)\n    (hshape : ws.length=ctx.rank) :\n    series ⟨q::ctx.axes,ctx.precision⟩ (ws++List.replicate (ctx.rank*(q-1)) [])=\n      MvPowerSeries.rename (SemiprimeD1JetAlgebra.axisShift ctx.axes.length)\n        (series ctx ws) := by\n  classical\n  change (∑i : Fin (q*ctx.rank),\n      MvPowerSeries.monomial (exponent (q::ctx.axes) i.val)\n        (SemiprimeD1JetRingBits.coefficient ⟨q::ctx.axes,ctx.precision⟩\n          (ws++List.replicate (ctx.rank*(q-1)) []) i.val))=_\n  rw [Fin.sum_univ_eq_sum_range (fun i=>\n    MvPowerSeries.monomial (exponent (q::ctx.axes) i)\n      (SemiprimeD1JetRingBits.coefficient ⟨q::ctx.axes,ctx.precision⟩\n        (ws++List.replicate (ctx.rank*(q-1)) []) i)) (q*ctx.rank)]\n  have hsplit : q*ctx.rank=ctx.rank+ctx.rank*(q-1) := by\n    exact rank_split q ctx.rank hq\n  rw [hsplit,Finset.sum_range_add]\n  have hz : (∑x∈Finset.range (ctx.rank*(q-1)),\n      MvPowerSeries.monomial (exponent (q::ctx.axes) (ctx.rank+x))\n        (SemiprimeD1JetRingBits.coefficient ⟨q::ctx.axes,ctx.precision⟩\n          (ws++List.replicate (ctx.rank*(q-1)) [])\n          (ctx.rank+x)))=0 := by\n    apply Finset.sum_eq_zero\n    intro x hx\n    simp only [SemiprimeD1JetRingBits.coefficient,List.getElem?_append,hshape]\n    simp [SemiprimeBitArithmetic.bitValue]\n  rw [hz,add_zero]\n  simp only [series,map_sum]\n  rw [Fin.sum_univ_eq_sum_range (fun i=>\n    MvPowerSeries.rename (SemiprimeD1JetAlgebra.axisShift ctx.axes.length)\n      (MvPowerSeries.monomial (exponent ctx.axes i)\n        (SemiprimeD1JetRingBits.coefficient ctx ws i))) ctx.rank]\n  apply Finset.sum_congr rfl\n  intro i hi\n  have hir : i<ctx.rank := Finset.mem_range.mp hi\n  rw [MvPowerSeries.rename_monomial]\n  have he : Finsupp.mapDomain (SemiprimeD1JetAlgebra.axisShift ctx.axes.length)\n      (exponent ctx.axes i)=\n      Finsupp.embDomain (SemiprimeD1JetAlgebra.axisShift ctx.axes.length)\n        (exponent ctx.axes i) := (Finsupp.embDomain_eq_mapDomain _ _).symm\n  rw [he,←exponent_shift q ctx.axes i hir]\n  congr 1\n  simp only [SemiprimeD1JetRingBits.coefficient]\n  rw [List.getElem?_append_left (by omega : i<ws.length)]\n\n/-- Equal dimension functions induce the identical quotient projection. -/\ntheorem project_heq {σ R : Type*} [CommRing R] (a b : σ→ℕ) (h : a=b)\n    (f : MvPowerSeries σ R) :\n    HEq (SemiprimeD1JetAlgebra.project a f) (SemiprimeD1JetAlgebra.project b f) := by\n  cases h\n  rfl\n\n/-- The concrete actual vector embedding is the SAME-precision quotient ring map.\nHEq records only the propositionally equal list/finite-function dimension types. -/\ntheorem embed_interpret (entry : Tagged) (q : ℕ) (hq : 0<q)\n    (hshape : entry.coefficients.length=entry.current.rank) :\n    HEq (interpret (embed entry [q] entry.current.precision).value.current\n      (embed entry [q] entry.current.precision).value.coefficients)\n      (SemiprimeD1JetAlgebra.outerEmbedding q (dims entry.current.axes)\n        (interpret entry.current entry.coefficients)) := by\n  have hc : (embed entry [q] entry.current.precision).value.current=\n      ⟨q::entry.current.axes,entry.current.precision⟩ := rfl\n  rw [hc,embed_coefficients]\n  simp only [List.prod_cons,List.prod_nil,Nat.mul_one]\n  rw [interpret_series,series_zero_extend entry.current entry.coefficients q hq hshape,\n    interpret_series,SemiprimeD1JetAlgebra.outerEmbedding_project]\n  change HEq (SemiprimeD1JetAlgebra.project (dims (q::entry.current.axes)) _)\n    (SemiprimeD1JetAlgebra.project\n      (SemiprimeD1JetAlgebra.outerDims q (dims entry.current.axes)) _)\n  exact project_heq _ _ (dims_cons q entry.current.axes) _\n\nend\nend RiemannGaussian.SemiprimeD1JetEmbedding\n","RiemannGaussian.SemiprimeD1JetModeBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetKernelBits\n\n/-! # Actual physical finite inverse caches and universal crossing modes\nNo native modular inversion or requested coefficient list executes. The cache\nis acquired by scalar multiplication from the physically acquired odd inverse.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1JetModeBits\nopen scoped BigOperators\nopen SemiprimeBitArithmetic SemiprimeD1JetAxes SemiprimeD1JetInterpretation\nopen SemiprimeD1JetAffineCoefficient (JetRun)\nopen SemiprimeD1JetPolynomialBits SemiprimeD1JetKernelBits\n\n/-- Acquired ascending scalar coefficient words and all retained work. -/\nstructure Cache where\n  /-- Physical coefficient array in the original degree order. -/\n  words : List (List Bool)\n  /-- Actual copies, products, allocation and control. -/\n  clock : ℕ\n\n/-- Acquire each finite geometric coefficient once, then cache its physical word. -/\ndef geometric (p : ℕ) (ratio current : List Bool) : ℕ→Cache\n  | 0 => ⟨[],1⟩\n  | n+1 =>\n    let here:=SemiprimeSourceCompactBits.copy current\n    let next:=SemiprimeD1JetScalarBits.mul p ratio current\n    let tail:=geometric p ratio next.bits n\n    ⟨here.bits::tail.words,here.clock+next.clock+tail.clock+5⟩\n\n/-- Actual finite cache length is the requested number of acquired coefficients. -/\ntheorem geometric_length (p : ℕ) (ratio current : List Bool) (n : ℕ) :\n    (geometric p ratio current n).words.length=n := by\n  induction n generalizing current with\n  | zero => rfl\n  | succ n ih => simp only [geometric,List.length_cons,ih]\n\n/-- Every acquired geometric coefficient has its original multiplicative meaning. -/\ntheorem geometric_coefficient (p : ℕ) (ratio current : List Bool) (n i : ℕ) (hi : i<n) :\n    (bitValue ((geometric p ratio current n).words.getD i []):ZMod (2^p))=\n      (bitValue current:ZMod (2^p))*(bitValue ratio:ZMod (2^p))^i := by\n  induction n generalizing current i with\n  | zero => omega\n  | succ n ih =>\n    cases i with\n    | zero => simp only [geometric,List.getD_cons_zero,SemiprimeSourceCompactBits.copy_bits,pow_zero,mul_one]\n    | succ i =>\n      change (bitValue ((geometric p ratio (SemiprimeD1JetScalarBits.mul p ratio current).bits n).words.getD i []):ZMod (2^p))=_\n      rw [ih _ i (by omega),SemiprimeD1JetScalarBits.mul_zmod,pow_succ]\n      ring\n\n/-- Acquire the inverse constant and the signed slope ratio by physical operations. -/\ndef inverseCache (p : ℕ) (constant slope : ℤ) : Cache :=\n  let c:=integer p constant\n  let s:=integer p slope\n  let inverse:=SemiprimeD1OddInverseBits.inverse p c.bits\n  let negative:=SemiprimeD1OddInverseBits.negativeOne p\n  let opposite:=SemiprimeD1JetScalarBits.mul p negative.bits s.bits\n  let ratio:=SemiprimeD1JetScalarBits.mul p opposite.bits inverse.bits\n  let out:=geometric p ratio.bits inverse.bits p\n  ⟨out.words,c.clock+s.clock+inverse.clock+negative.clock+opposite.clock+ratio.clock+out.clock+15⟩\n\n/-- The acquired inverse cache has exactly the original precision length. -/\ntheorem inverseCache_length (p : ℕ) (constant slope : ℤ) :\n    (inverseCache p constant slope).words.length=p := geometric_length _ _ _ _\n\n/-- Cache values agree with the original finite inverse coefficient formula. -/\ntheorem inverseCache_coefficient (p : ℕ) (constant slope : ℤ) (hp : 0<p) (hc : Odd constant)\n    (i : ℕ) (hi : i<p) :\n    (bitValue ((inverseCache p constant slope).words.getD i []):ZMod (2^p))=\n      (SemiprimeD1OddAffineInverse.coefficients p constant slope).getD i 0 := by\n  change (bitValue ((geometric p\n    (SemiprimeD1JetScalarBits.mul p\n      (SemiprimeD1JetScalarBits.mul p (SemiprimeD1OddInverseBits.negativeOne p).bits (integer p slope).bits).bits\n      (SemiprimeD1OddInverseBits.inverse p (integer p constant).bits).bits).bits\n    (SemiprimeD1OddInverseBits.inverse p (integer p constant).bits).bits p).words.getD i []):ZMod (2^p))=_\n  rw [geometric_coefficient _ _ _ _ _ hi,SemiprimeD1JetScalarBits.mul_zmod,\n    SemiprimeD1JetScalarBits.mul_zmod,inverse_value p constant hp hc,integer_value]\n  have hn:=SemiprimeD1OddInverseBits.negativeOne_zmod p\n  change (bitValue (SemiprimeD1OddInverseBits.negativeOne p).bits:ZMod (2^p)) = -1 at hn\n  rw [hn,neg_one_mul]\n  simp [SemiprimeD1OddAffineInverse.coefficients,hi]\n\n/-- Actual Horner evaluation of the acquired inverse cache equals the original finite list value. -/\ntheorem inverseCache_value (ctx : Context) (z : List (List Bool)) (constant slope : ℤ)\n    (hpos : ∀q∈ctx.axes,0<q) (hp : 0<ctx.precision) (hc : Odd constant) :\n    interpret ctx (horner ctx z (inverseCache ctx.precision constant slope).words).words=\n      SemiprimeD1UniversalModeData.inverseValue ctx.precision\n        (SemiprimeD1JetAlgebra.constants (SemiprimeD1JetBoxIndex.dims ctx.axes)) (interpret ctx z)\n        (SemiprimeD1OddAffineInverse.coefficients ctx.precision constant slope) := by\n  rw [horner_sum ctx z _ hpos]\n  simp only [inverseCache_length,SemiprimeD1UniversalModeData.inverseValue,\n    SemiprimeD1OddAffineInverse.coefficients_length]\n  apply Finset.sum_congr rfl\n  intro i hi\n  rw [inverseCache_coefficient ctx.precision constant slope hp hc i (Finset.mem_range.mp hi)]\n  rfl\n\n/-- Complete concrete mode evaluation from original native grid indices.\nAll physical base/cache/Horner/step/power reports are retained exactly once. -/\ndef mode (ctx : Context) (z : JetRun) (k center i j d b : ℕ) : JetRun :=\n  let base:=entry ctx z (SemiprimeD1WireKernelEntry.acquire k center j d)\n  let factor:=SemiprimeD1WireKernelFactors.normalizedFactor k j d\n  let cache:=inverseCache ctx.precision factor.constant factor.slope\n  let inverse:=horner ctx z.words cache.words\n  let step:=integerVector ctx (SemiprimeD1CrossingExpansion.step k i j d)\n  let ratio:=SemiprimeD1JetRingBits.mul ctx step.words inverse.words\n  let raised:=power ctx ratio.words b\n  let out:=SemiprimeD1JetRingBits.mul ctx base.words raised.words\n  ⟨out.words,base.clock+cache.clock+inverse.clock+step.clock+ratio.clock+raised.clock+out.clock+20⟩\n\n/-- Concrete physical modes equal the original universal mode-data evaluation. -/\ntheorem mode_value (ctx : Context) (z : JetRun) (k center i j d b : ℕ)\n    (hpos : ∀q∈ctx.axes,0<q) (hp : 0<ctx.precision) (hcenter : center<2^k) (hne : d≠j) :\n    interpret ctx (mode ctx z k center i j d b).words=\n      SemiprimeD1UniversalModeData.evaluate ctx.precision\n        (SemiprimeD1JetAlgebra.constants (SemiprimeD1JetBoxIndex.dims ctx.axes)) (interpret ctx z.words)\n        (SemiprimeD1UniversalModeData.acquire ctx.precision k center i j d b) := by\n  change interpret ctx (SemiprimeD1JetRingBits.mul ctx\n    (entry ctx z (SemiprimeD1WireKernelEntry.acquire k center j d)).words\n    (power ctx (SemiprimeD1JetRingBits.mul ctx\n      (integerVector ctx (SemiprimeD1CrossingExpansion.step k i j d)).words\n      (horner ctx z.words (inverseCache ctx.precision\n        (SemiprimeD1WireKernelFactors.normalizedFactor k j d).constant\n        (SemiprimeD1WireKernelFactors.normalizedFactor k j d).slope).words).words).words b).words).words=_\n  rw [SemiprimeD1JetOperations.interpret_mul ctx _ _ hpos,\n    entry_value ctx z _ hpos hp (SemiprimeD1WireKernelEntry.denominator_odd k center hcenter),\n    power_value ctx _ b hpos,SemiprimeD1JetOperations.interpret_mul ctx _ _ hpos,\n    integerVector_value ctx _ hpos,inverseCache_value ctx _ _ _ hpos hp\n      (SemiprimeD1CrossingCoefficient.normalized_constant_odd k j d hne)]\n  rfl\n\n/-- Original crossing-mode producer from actual grid, row and column indices. -/\ndef acquireOriginal (ctx : Context) (z : JetRun) (a i b : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (x y₀ : Fin (2^a)) : JetRun :=\n  mode ctx z (a+1) (SemiprimeD1WireKernelOriginal.center a) i t.val\n    (SemiprimeD1CrossingPaper.baseIndex a x y₀) b\n\n/-- Actual same-bit source conditions discharge all mode units and inverse-data requirements. -/\ntheorem acquireOriginal_value (ctx : Context) (z : JetRun) (a i b : ℕ)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (x y₀ : Fin (2^a))\n    (hpos : ∀q∈ctx.axes,0<q) (hp : 0<ctx.precision)\n    (ht : SemiprimeD1WireKernelOriginal.point a t.val≠0)\n    (hi : padicValInt 2 (SemiprimeD1WireKernelOriginal.point a t.val)=i)\n    (hbit : x.val.testBit i=y₀.val.testBit i) :\n    interpret ctx (acquireOriginal ctx z a i b t x y₀).words=\n      SemiprimeD1UniversalModeData.evaluate ctx.precision\n        (SemiprimeD1JetAlgebra.constants (SemiprimeD1JetBoxIndex.dims ctx.axes)) (interpret ctx z.words)\n        (SemiprimeD1UniversalModeData.acquireOriginal ctx.precision a i b t x y₀) := by\n  obtain ⟨hne,_⟩:=SemiprimeD1CrossingPaper.original_crossing a i t x y₀ ht hi hbit\n  exact mode_value ctx z (a+1) (SemiprimeD1WireKernelOriginal.center a) i t.val\n    (SemiprimeD1CrossingPaper.baseIndex a x y₀) b hpos hp\n    (SemiprimeD1WireKernelOriginal.center_lt a) hne\n\nend RiemannGaussian.SemiprimeD1JetModeBits\n","RiemannGaussian.SemiprimeD1JetPolynomialCoefficient":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetInterpretation\n\n/-! # Exact finite polynomial coefficients at a fresh nilpotent axis\nNo domain, field, or multiplicative valuation assumption is used. Retained fresh\ncoefficients are literal polynomial coefficients in the ENTIRE old jet ring.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1JetPolynomialCoefficient\nopen scoped BigOperators\nopen Polynomial SemiprimeD1JetAlgebra SemiprimeD1JetInterpretation\nnoncomputable section\nvariable {m : ℕ} {R : Type*} [CommRing R]\n\n/-- Fresh exponent j and ALL original old exponents. -/\ndef blockExponent (j : ℕ) (e : Fin m→₀ℕ) : Fin (m+1)→₀ℕ :=\n  Finsupp.single 0 j+Finsupp.embDomain (axisShift m) e\n\n/-- Shifted old exponents have no fresh coordinate. -/\ntheorem shifted_zero (e : Fin m→₀ℕ) : (Finsupp.embDomain (axisShift m) e) 0=0 := by\n  apply Finsupp.embDomain_of_notMem_range\n  rintro ⟨i,hi⟩\n  exact Fin.succ_ne_zero i hi\n\n/-- The block exponent has exactly the requested fresh exponent. -/\ntheorem block_zero (j : ℕ) (e : Fin m→₀ℕ) : blockExponent j e 0=j := by\n  simp only [blockExponent,Finsupp.add_apply,Finsupp.single_eq_same,shifted_zero,Nat.add_zero]\n\n/-- Every retained polynomial block belongs to the actual rectangular quotient box. -/\ntheorem block_inBox (q : ℕ) (dims : Fin m→ℕ) (j : ℕ) (hj : j<q)\n    (e : Fin m→₀ℕ) (he : InBox dims e) : InBox (outerDims q dims) (blockExponent j e) := by\n  intro i\n  refine Fin.cases ?_ (fun k => ?_) i\n  · simpa only [block_zero,outerDims,Fin.cases_zero] using hj\n  · change (Finsupp.single (0:Fin (m+1)) j) k.succ+\n      (Finsupp.embDomain (axisShift m) e) ((axisShift m) k)<dims k\n    simpa only [Finsupp.single_apply,Ne.symm (Fin.succ_ne_zero k),ite_false,Nat.zero_add,\n      Finsupp.embDomain_apply_self] using he k\n\n/-- The original renamed series has exactly one fresh monomial degree after multiplication. -/\ntheorem series_monomial_coefficient (f : MvPowerSeries (Fin m) R) (e : Fin m→₀ℕ) (j n : ℕ) :\n    MvPowerSeries.coeff (blockExponent j e)\n      (MvPowerSeries.rename (axisShift m) f*(MvPowerSeries.X (0:Fin (m+1)))^n)=\n      if n=j then MvPowerSeries.coeff e f else 0 := by\n  classical\n  rw [MvPowerSeries.X_pow_eq,MvPowerSeries.coeff_mul_monomial]\n  by_cases hn : n≤j\n  · have hle : Finsupp.single (0:Fin (m+1)) n≤blockExponent j e := by\n      intro i\n      refine Fin.cases ?_ (fun k => ?_) i\n      · simpa only [Finsupp.single_eq_same,block_zero] using hn\n      · simp only [Finsupp.single_apply,Ne.symm (Fin.succ_ne_zero k),ite_false]\n        exact Nat.zero_le _\n    rw [ite_eq_left hle,mul_one]\n    by_cases hnj : n=j\n    · subst n\n      have hsub : blockExponent j e-Finsupp.single 0 j=Finsupp.embDomain (axisShift m) e := by\n        unfold blockExponent\n        exact add_tsub_cancel_left _ _\n      rw [hsub,MvPowerSeries.coeff_embDomain_rename,ite_eq_left rfl]\n    · have hpos : 0<(blockExponent j e-(Finsupp.single (0:Fin (m+1)) n) : Fin (m+1)→₀ℕ) 0 := by\n        simp only [Finsupp.tsub_apply,block_zero,Finsupp.single_eq_same]\n        omega\n      have hnot : blockExponent j e-Finsupp.single 0 n∉Set.range (Finsupp.mapDomain (axisShift m)) := by\n        rintro ⟨d,hd⟩\n        rw [← Finsupp.embDomain_eq_mapDomain] at hd\n        have hz := congrArg (fun z => z (0:Fin (m+1))) hd\n        rw [shifted_zero] at hz\n        omega\n      rw [MvPowerSeries.coeff_rename_eq_zero (axisShift m) f hnot,ite_eq_right hnj]\n  · have hnot : ¬Finsupp.single (0:Fin (m+1)) n≤blockExponent j e := by\n      intro h\n      have hz := h 0\n      simp only [Finsupp.single_eq_same,block_zero] at hz\n      exact hn hz\n    rw [ite_eq_right hnot,ite_eq_right (by omega : n≠j)]\n\n/-- Exact polynomial-monomial extraction in the actual quotient, including old zero divisors. -/\ntheorem monomial_coefficient (q : ℕ) (dims : Fin m→ℕ) (j : ℕ) (hj : j<q)\n    (e : Fin m→₀ℕ) (he : InBox dims e) (n : ℕ) (c : Algebra dims R) :\n    coefficient (outerDims q dims) (blockExponent j e) (block_inBox q dims j hj e he)\n      (outerEmbedding q dims c*(fresh q dims)^n)=\n      if n=j then coefficient dims e he c else 0 := by\n  induction c using Quotient.inductionOn with\n  | h c =>\n    change coefficient (outerDims q dims) (blockExponent j e) (block_inBox q dims j hj e he)\n      (outerEmbedding q dims (project dims c)*(project (outerDims q dims) (MvPowerSeries.X 0))^n)=_\n    rw [outerEmbedding_project,←map_pow,←map_mul,coefficient_project]\n    change _=if n=j then MvPowerSeries.coeff e c else 0\n    exact series_monomial_coefficient c e j n\n\n/-- The retained fresh-j coefficient is EXACTLY F.coeffj in ALL old coordinates. -/\ntheorem polynomial_coefficient (q : ℕ) (dims : Fin m→ℕ) (j : ℕ) (hj : j<q)\n    (e : Fin m→₀ℕ) (he : InBox dims e) (F : Polynomial (Algebra dims R)) :\n    coefficient (outerDims q dims) (blockExponent j e) (block_inBox q dims j hj e he)\n      (F.eval₂ (outerEmbedding q dims) (fresh q dims))=\n      coefficient dims e he (F.coeff j) := by\n  classical\n  induction F using Polynomial.induction_on' with\n  | add F G hF hG =>\n    simp only [Polynomial.eval₂_add,quotient_coefficient_add,Polynomial.coeff_add,hF,hG]\n  | monomial n c =>\n    rw [Polynomial.eval₂_monomial,monomial_coefficient q dims j hj e he n c,Polynomial.coeff_monomial]\n    split_ifs <;> simp only [quotient_coefficient_zero]\n\nend\nend RiemannGaussian.SemiprimeD1JetPolynomialCoefficient\n","RiemannGaussian.SemiprimeD1JetWordModeBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetWordKernelBits\nimport RiemannGaussian.SemiprimeD1JetWordModeScalarBounds\n\n/-! # Full original crossing modes from acquired words\nThe original base entry and scalar suppliers execute once each. Every physical\nsource/cache/Horner/vector product/power report is retained. Original native\nmode data appear only in the literal-byte correctness theorem.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 900000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1JetWordModeBits\nopen SemiprimeBitArithmetic SemiprimeD1JetAxes SemiprimeD1JetInterpretation\nopen SemiprimeD1JetAffineCoefficient (JetRun)\nopen SemiprimeD1JetPolynomialBits SemiprimeD1RecoveryIntegerBits\nopen SemiprimeD1WireKernelOriginal\nattribute [local irreducible] SemiprimeD1JetWordModeScalarBits.acquireOriginal\n  SemiprimeD1JetWordKernelBits.acquireOriginal\n\n/-- Full actual original mode from the acquired base, scalar cache and step words. -/\ndef acquireOriginal (ctx : Context) (z : JetRun) (a i b : ℕ)\n    (t : Fin (size a)) (x y₀ : Fin (2^a)) : JetRun :=\n  let base:=SemiprimeD1JetWordKernelBits.acquireOriginal ctx z a t x y₀\n  let source:=SemiprimeD1JetWordModeScalarBits.acquireOriginal ctx.precision a i t x y₀\n  let inverse:=horner ctx z.words source.cache.words\n  let tile:=SemiprimeD1JetWordSourceBits.constant ctx (positive source.step)\n  let ratio:=SemiprimeD1JetRingBits.mul ctx tile.words inverse.words\n  let raised:=power ctx ratio.words b\n  let out:=SemiprimeD1JetRingBits.mul ctx base.words raised.words\n  ⟨out.words,base.clock+source.clock+inverse.clock+tile.clock+ratio.clock+raised.clock+out.clock+20⟩\n\n/-- Literal output bytes agree with the frozen original mode. Distinct source\nand arithmetic reports are not identified or transferred by this equality. -/\ntheorem acquireOriginal_words (ctx : Context) (hpos : ctx.Positive) (z : JetRun)\n    (a i b : ℕ) (t : Fin (size a)) (x y₀ : Fin (2^a)) :\n    (acquireOriginal ctx z a i b t x y₀).words=\n      (SemiprimeD1JetModeBits.acquireOriginal ctx z a i b t x y₀).words := by\n  have hstep:(positive (SemiprimeD1JetWordModeScalarBits.acquireOriginal\n      ctx.precision a i t x y₀).step).value=\n      SemiprimeD1CrossingExpansion.step (a+1) i t.val (displacement a x y₀).val :=\n    SemiprimeD1JetWordModeScalarBits.acquire_step_value ctx.precision a i t x y₀\n  dsimp only [acquireOriginal,SemiprimeD1JetModeBits.acquireOriginal,SemiprimeD1JetModeBits.mode]\n  rw [SemiprimeD1JetWordKernelBits.acquireOriginal_words ctx hpos z a t x y₀,\n    SemiprimeD1JetWordModeScalarBits.acquire_cache_words,\n    SemiprimeD1JetWordSourceBits.constant_words_eq_integerVector ctx _ _ hstep]\n  rfl\n\n/-- The full physical output has its current context's rank and precision. -/\ntheorem acquireOriginal_good (ctx : Context) (z : JetRun) (a i b : ℕ)\n    (t : Fin (size a)) (x y₀ : Fin (2^a)) :\n    SemiprimeD1JetAffineCoefficientBounds.Good ctx (acquireOriginal ctx z a i b t x y₀).words :=\n  SemiprimeD1JetAffineCoefficientBounds.mul_good _ _ _\n/-- The actual word-only original mode has the universal crossing interpretation\nunder the original point/valuation/same-bit conditions, with no supplied unit. -/\ntheorem acquireOriginal_value (ctx : Context) (z : JetRun) (a i b : ℕ)\n    (t : Fin (size a)) (x y₀ : Fin (2^a))\n    (hpos:ctx.Positive) (hp:0<ctx.precision)\n    (ht:point a t.val≠0) (hi:padicValInt 2 (point a t.val)=i)\n    (hbit:x.val.testBit i=y₀.val.testBit i) :\n    interpret ctx (acquireOriginal ctx z a i b t x y₀).words=\n      SemiprimeD1UniversalModeData.evaluate ctx.precision\n        (SemiprimeD1JetAlgebra.constants (SemiprimeD1JetBoxIndex.dims ctx.axes))\n        (interpret ctx z.words)\n        (SemiprimeD1UniversalModeData.acquireOriginal ctx.precision a i b t x y₀) := by\n  rw [acquireOriginal_words ctx hpos]\n  exact SemiprimeD1JetModeBits.acquireOriginal_value ctx z a i b t x y₀ hpos hp ht hi hbit\nend RiemannGaussian.SemiprimeD1JetWordModeBits\n","RiemannGaussian.SemiprimeD1KernelEntryBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1KernelEntryBits\n\n/-! # Original-dimension bounds for the acquired physical entry\nAll factors, contents and division widths are derived from actual grid words.\nThe clock retains digit-stage reports; lowering native dimension/displacement\nand digit primitives to one tape machine remains a separate obligation.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1KernelEntryBounds\nopen SemiprimeBitArithmetic SemiprimeBitDivision SemiprimeBitIndexClipping\nopen SemiprimeD1RecoveryIntegerBits SemiprimeD1KernelEntryBits\nopen SemiprimeD1WireKernelOriginal\n\n/-- Actual skip/normalization budget per original grid item. -/\ndef stepBudget (k W : ℕ) : ℕ :=\n  41*(W+1)+3*(W+1)+1+SemiprimeD1NormalizedLinearBits.budget k W+5\n\n/-- Cached acquisition cannot create additional grid factors. -/\ntheorem gather_length (k : ℕ) (j d : List Bool) (qs : List (List Bool)) :\n    (gather k j d qs).values.length≤qs.length := by\n  rw [gather_values,List.length_map]\n  exact List.length_filter_le _ _\n\n/-- Every actual retained factor inherits widths from original grid words. -/\ntheorem gather_width (k W : ℕ) (j d : List Bool) (qs : List (List Bool))\n    (hj:j.length≤W) (hqs:∀q∈qs,q.length≤W)\n    (f : SemiprimeD1NormalizedLinearBits.Run) (hf:f∈(gather k j d qs).values) :\n    f.content.length≤k+W+2 ∧f.constant.magnitude.length≤W+1 ∧f.slope.length≤k+1 := by\n  rw [gather_values] at hf\n  obtain ⟨q,hq,rfl⟩:=List.mem_map.mp hf\n  have hmem: q∈qs:=(List.mem_filter.mp hq).1\n  exact SemiprimeD1NormalizedLinearBits.acquire_width k W j q hj (hqs q hmem)\n\n/-- All skip scans and actual retained factor callbacks are paid. -/\ntheorem gather_clock (k W : ℕ) (j d : List Bool) (qs : List (List Bool))\n    (hj:j.length≤W) (hd:d.length≤W) (hqs:∀q∈qs,q.length≤W) :\n    (gather k j d qs).clock≤qs.length*stepBudget k W+1 := by\n  induction qs with\n  | nil => simp only [gather,List.length_nil,Nat.zero_mul,Nat.zero_add,le_refl]\n  | cons q qs ih =>\n    have hq:=hqs q List.mem_cons_self\n    have ht:=ih (fun z hz=>hqs z (List.mem_cons_of_mem q hz))\n    have hs:=subSignedBits_cost_width (left:=positive q) (right:=positive d) hq hd\n    have hn:=nonzeroBits_cost (subSignedBits (positive q) (positive d)).word.magnitude\n    have hf:=SemiprimeD1NormalizedLinearBits.acquire_clock k W j q hj hq\n    dsimp only [gather]\n    split <;> dsimp only <;>\n      simp only [List.length_cons,Nat.add_mul,Nat.one_mul] <;> unfold stepBudget at * <;> omega\n\n/-- Original numerator content word width. -/\ndef contentWidth (a N : ℕ) : ℕ := 2*N*(2*a+5)+1\n\n/-- Original derivative content word width. -/\ndef denominatorWidth (a N : ℕ) : ℕ := 2*N*(a+2)+2\n\n/-- Monotonicity of the already executed short-factor product budget. -/\ntheorem product_budget_mono (n N W : ℕ) (h:n≤N) :\n    SemiprimeD1KernelProductBits.budget n W≤SemiprimeD1KernelProductBits.budget N W := by\n  unfold SemiprimeD1KernelProductBits.budget\n  gcongr\n\n/-- Original grid words bound the full cached content product. -/\ntheorem numerator_width (a : ℕ) (t : Fin (size a)) (x y : Fin (2^a)) :\n    (SemiprimeD1KernelEntryBits.acquireOriginal a t x y).numeratorContent.length≤contentWidth a (size a) := by\n  let grid:=SemiprimeSourceCompactWordIds.acquire (size a)\n  let j:=SemiprimeEncodedRowSelection.digits (a+1) t.val\n  let d:=SemiprimeEncodedRowSelection.digits (a+1) (displacement a x y).val\n  let fs:=gather (a+1) j.bits d.bits grid.value\n  have hj:j.bits.length≤a+2:=by rw [SemiprimeEncodedRowSelection.digits_length];omega\n  have hgrid:∀q∈grid.value,q.length≤a+2:=by\n    intro q hq\n    exact (SemiprimeD1KernelDenominatorBits.grid_width a q hq).trans (by omega)\n  have hlen:fs.values.length≤ size a:=(gather_length _ _ _ _).trans\n    (by rw [SemiprimeSourceCompactWordIds.acquire_length])\n  have hw:∀w∈fs.values.map (fun f=>positive f.content),w.magnitude.length≤2*a+5:=by\n    intro w hw\n    obtain ⟨f,hf,rfl⟩:=List.mem_map.mp hw\n    have h:=(gather_width (a+1) (a+2) j.bits d.bits grid.value hj hgrid f hf).1\n    change f.content.length≤_\n    omega\n  have hp:=SemiprimeD1KernelProductBits.run_width _ (2*a+5) hw\n  rw [List.length_map] at hp\n  change (SemiprimeD1KernelProductBits.run _).word.magnitude.length≤_\n  unfold contentWidth\n  exact hp.trans (by gcongr)\n\n/-- Derivative content width follows the actual derivative and strip recursion. -/\ntheorem denominator_content_width (a : ℕ) :\n    (SemiprimeD1KernelDenominatorBits.run a).content.length≤denominatorWidth a (size a) := by\n  have hs:=(SemiprimeD1RecoveryStripBits.lengths\n    (SemiprimeD1KernelDenominatorBits.raw a).word.magnitude).1\n  have hr:=SemiprimeD1KernelDenominatorBits.raw_width a\n  change (SemiprimeD1RecoveryStripBits.acquire\n    (SemiprimeD1KernelDenominatorBits.raw a).word.magnitude).content.length≤_\n  unfold denominatorWidth\n  omega\n\n/-- Quotient width is derived from the positive actual derivative content. -/\ntheorem powerFactor_width (a : ℕ) (t : Fin (size a)) (x y : Fin (2^a)) :\n    (SemiprimeD1KernelEntryBits.acquireOriginal a t x y).powerFactor.length≤contentWidth a (size a) := by\n  have hp:0<bitValue (SemiprimeD1KernelDenominatorBits.run a).content:=by\n    rw [SemiprimeD1KernelDenominatorBits.run_content];positivity\n  have hw:=(divideBits_widths (xs:=(SemiprimeD1KernelEntryBits.acquireOriginal a t x y).numeratorContent) hp).2\n  change (divideBits _ _).quotient.length≤_\n  exact hw.le.trans (numerator_width a t x y)\n\n/-- Fixed polynomial in original grid dimensions, with every repeated setup retained. -/\ndef budget (a N : ℕ) : ℕ :=\n  N*(30*(a+4)+20)+1+2*(4*(a+1)+1)+N*stepBudget (a+1) (a+2)+1+\n  SemiprimeD1KernelProductBits.budget N (2*a+5)+\n  SemiprimeD1KernelDenominatorBits.budget a N+\n  contentWidth a N*(16*denominatorWidth a N+20)+7*denominatorWidth a N+4+12\n\n/-- Original cached factor count and all literal factor widths. -/\ntheorem acquire_factor_bounds (a : ℕ) (t : Fin (size a)) (x y : Fin (2^a)) :\n    (SemiprimeD1KernelEntryBits.acquireOriginal a t x y).factors.length≤ size a ∧\n    ∀f∈(SemiprimeD1KernelEntryBits.acquireOriginal a t x y).factors,\n      f.content.length≤2*a+5 ∧f.constant.magnitude.length≤a+3 ∧f.slope.length≤a+2 := by\n  constructor\n  · exact (gather_length _ _ _ _).trans (by rw [SemiprimeSourceCompactWordIds.acquire_length])\n  · intro f hf\n    have hj:(SemiprimeEncodedRowSelection.digits (a+1) t.val).bits.length≤a+2:=by\n      rw [SemiprimeEncodedRowSelection.digits_length];omega\n    have hg:∀q∈(SemiprimeSourceCompactWordIds.acquire (size a)).value,q.length≤a+2:=by\n      intro q hq\n      exact (SemiprimeD1KernelDenominatorBits.grid_width a q hq).trans (by omega)\n    have h:=gather_width (a+1) (a+2) _ _ _ hj hg f hf\n    rcases h with ⟨hc,hm,hs⟩\n    exact ⟨by omega,by omega,by omega⟩\n\n/-- Full acquisition clock from original dimensions, with no supplied answers. -/\ntheorem acquire_clock (a : ℕ) (t : Fin (size a)) (x y : Fin (2^a)) :\n    (SemiprimeD1KernelEntryBits.acquireOriginal a t x y).clock≤budget a (size a) := by\n  let grid:=SemiprimeSourceCompactWordIds.acquire (size a)\n  let j:=SemiprimeEncodedRowSelection.digits (a+1) t.val\n  let d:=SemiprimeEncodedRowSelection.digits (a+1) (displacement a x y).val\n  let fs:=gather (a+1) j.bits d.bits grid.value\n  let numerator:=SemiprimeD1KernelProductBits.run (fs.values.map (fun f=>positive f.content))\n  let denominator:=SemiprimeD1KernelDenominatorBits.run a\n  let power:=divideBits numerator.word.magnitude denominator.content\n  have hj:j.bits.length≤a+2:=by rw [SemiprimeEncodedRowSelection.digits_length];omega\n  have hd:d.bits.length≤a+2:=by rw [SemiprimeEncodedRowSelection.digits_length];omega\n  have hgrid:∀q∈grid.value,q.length≤a+2:=by\n    intro q hq\n    exact (SemiprimeD1KernelDenominatorBits.grid_width a q hq).trans (by omega)\n  have hfs:fs.clock≤ size a*stepBudget (a+1) (a+2)+1:=by\n    have h:=gather_clock (a+1) (a+2) j.bits d.bits grid.value hj hd hgrid\n    rw [SemiprimeSourceCompactWordIds.acquire_length] at h\n    exact h\n  have hlen:fs.values.length≤ size a:=(gather_length _ _ _ _).trans\n    (by rw [SemiprimeSourceCompactWordIds.acquire_length])\n  have hw:∀w∈fs.values.map (fun f=>positive f.content),w.magnitude.length≤2*a+5:=by\n    intro w hw\n    obtain ⟨f,hf,rfl⟩:=List.mem_map.mp hw\n    have h:=(gather_width (a+1) (a+2) j.bits d.bits grid.value hj hgrid f hf).1\n    change f.content.length≤_\n    omega\n  have hn:numerator.clock≤SemiprimeD1KernelProductBits.budget (size a) (2*a+5):=by\n    have h:=SemiprimeD1KernelProductBits.run_clock _ (2*a+5) hw\n    rw [List.length_map] at h\n    exact h.trans (product_budget_mono _ _ _ hlen)\n  have hnum:numerator.word.magnitude.length≤contentWidth a (size a):=numerator_width a t x y\n  have hden:denominator.content.length≤denominatorWidth a (size a):=denominator_content_width a\n  have hdiv:power.clock≤contentWidth a (size a)*(16*denominatorWidth a (size a)+20)+\n      7*denominatorWidth a (size a)+4:=by\n    have h:=divideBits_cost numerator.word.magnitude denominator.content\n    exact h.trans (by gcongr)\n  have hdc:denominator.clock≤SemiprimeD1KernelDenominatorBits.budget a (size a):=\n    SemiprimeD1KernelDenominatorBits.run_clock a\n  have hjc:j.work=4*(a+1)+1:=SemiprimeEncodedRowSelection.digits_work _ _\n  have hdd:d.work=4*(a+1)+1:=SemiprimeEncodedRowSelection.digits_work _ _\n  have hid:grid.work≤ size a*(30*(a+4)+20)+1:=by\n    have h:=SemiprimeSourceCompactWordIds.acquire_clock (size a)\n    have hn:1≤ size a:=by unfold size;exact Nat.one_le_two_pow\n    have hl:Nat.clog 2 (size a+1)≤a+2:=by\n      apply Nat.clog_le_of_le_pow\n      have he:2^(a+2)=2*size a:=by unfold size;rw [show a+2=(a+1)+1 by omega,pow_succ];ring\n      rw [he];omega\n    have hs:SemiprimeSourceCompactWordIds.stepBudget (size a)≤30*(a+4)+20:=by\n      unfold SemiprimeSourceCompactWordIds.stepBudget;omega\n    exact h.trans (Nat.add_le_add_right (Nat.mul_le_mul_left _ hs) 1)\n  change grid.work+j.work+d.work+fs.clock+numerator.clock+denominator.clock+power.clock+12≤_\n  unfold budget\n  omega\n\n/-- Literal retained Boolean payload in one cached normalized factor. -/\ndef factorCells (f : SemiprimeD1NormalizedLinearBits.Run) : ℕ :=\n  f.content.length+f.constant.magnitude.length+f.slope.length\n\n/-- Finite metadata-list summation counts every retained cell. -/\ntheorem list_cells_le {α : Type} (xs : List α) (cells : α→ℕ) (C : ℕ)\n    (h:∀x∈xs,cells x≤C) : (xs.map cells).sum≤xs.length*C := by\n  induction xs with\n  | nil => simp only [List.map_nil,List.sum_nil,List.length_nil,Nat.zero_mul,le_refl]\n  | cons x xs ih =>\n    have hx:=h x List.mem_cons_self\n    have ht:=ih (fun y hy=>h y (List.mem_cons_of_mem x hy))\n    simp only [List.map_cons,List.sum_cons,List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- Original factor count and widths give a concrete retained-cache payload bound. -/\ntheorem acquire_factor_cells (a : ℕ) (t : Fin (size a)) (x y : Fin (2^a)) :\n    (((SemiprimeD1KernelEntryBits.acquireOriginal a t x y).factors).map factorCells).sum≤\n      size a*(4*a+10) := by\n  have hb:=acquire_factor_bounds a t x y\n  have hh:=list_cells_le (SemiprimeD1KernelEntryBits.acquireOriginal a t x y).factors\n    factorCells (4*a+10) (by\n      intro f hf\n      rcases hb.2 f hf with ⟨hc,hm,hs⟩\n      unfold factorCells\n      omega)\n  exact hh.trans (Nat.mul_le_mul_right _ hb.1)\n\nend RiemannGaussian.SemiprimeD1KernelEntryBounds\n","RiemannGaussian.SemiprimeD1LeafReady":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1LeafRate\nimport RiemannGaussian.SemiprimeD1PathRate\nimport RiemannGaussian.SemiprimeSourceLayoutRate\n\n/-! # Eventual original-input acceptance of the literal D.1 leaf checks\nActual binary ceiling logarithms, integer floors and fixed constants are retained.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1LeafReady\nopen scoped Topology\nopen Filter SemiprimeD1Schedule SemiprimeD1PrecisionEnvelope SemiprimeD1LeafRate\n\n/-- Literal logarithmic minimum-level guard has sublinear cubed size. -/\ntheorem eventually_minimum_cube :\n    ∀ᶠ lam : ℕ in atTop,(minimumLevels lam)^3 ≤ lam := by\n  have hlog := (tendsto_add_atTop_nat 1).eventually\n    (SemiprimeSourceLayoutRate.eventually_clog_power_le_rpow 3 (1/2) (by norm_num))\n  filter_upwards [hlog,eventually_ge_atTop (12000000:ℕ)] with lam hl hlam\n  have hm : 1 ≤ Nat.clog 2 (lam+1) := Nat.clog_pos (by decide) (by omega)\n  have hB : minimumLevels lam ≤ 12*Nat.clog 2 (lam+1) := by unfold minimumLevels;omega\n  have hp : (minimumLevels lam:ℝ)^3 ≤ (12*(Nat.clog 2 (lam+1):ℝ))^3 := by\n    exact_mod_cast Nat.pow_le_pow_left hB 3\n  have hlambda : (12000000:ℝ) ≤ lam := by exact_mod_cast hlam\n  have hquad : (0:ℝ) ≤ (lam:ℝ)*((lam:ℝ)-12000000) :=\n    mul_nonneg (by positivity) (by linarith)\n  have hsqrt : Real.sqrt (lam+1:ℕ) ≤ (lam:ℝ)/1728 := by\n    apply (Real.sqrt_le_left (by positivity)).mpr\n    push_cast\n    nlinarith\n  rw [←Real.sqrt_eq_rpow] at hl\n  have hfinal : (minimumLevels lam:ℝ)^3 ≤ lam := by nlinarith\n  exact_mod_cast hfinal\n\n/-- Large actual root quotient and two computed integer checks imply RootReady. -/\ntheorem rootReady_of_numeric (s lam : ℕ)\n    (hB : (minimumLevels lam)^3 ≤ lam)\n    (hlarge : (2*epsilonDenominator)^2 ≤ lam/epsilonDenominator)\n    (hinput : lam^2 ≤ s) : RootReady s lam := by\n  let b:=lam/epsilonDenominator\n  have hK : 0<epsilonDenominator := by norm_num [epsilonDenominator]\n  have hb1 : 1 ≤ b := by\n    dsimp [b]\n    norm_num only [epsilonDenominator] at hlarge ⊢\n    omega\n  have hlambda : epsilonDenominator ≤ lam := by\n    have hm:=Nat.mul_le_mul_right epsilonDenominator hb1\n    have hd:=Nat.div_mul_le_self lam epsilonDenominator\n    dsimp only [b] at hm\n    simpa only [Nat.one_mul] using hm.trans hd\n  have hlambda2 : 1<lam := by norm_num only [epsilonDenominator] at hlambda;omega\n  have hk : Nat.sqrt lam+1 ≤ lam := by have:=Nat.sqrt_lt_self hlambda2;omega\n  have hroot : lam ≤ (2*epsilonDenominator)*b := by\n    simpa only [b,epsilonDenominator,show 2*(128*1024)=262144 by norm_num] using\n      SemiprimeD1PathRate.root_floor_bound lam hlambda\n  have hcube : lam^2 ≤ b^3 := by\n    calc\n      _ ≤ ((2*epsilonDenominator)*b)^2 := Nat.pow_le_pow_left hroot 2\n      _ = (2*epsilonDenominator)^2*b^2 := by ring\n      _ ≤ b*b^2 := Nat.mul_le_mul_right _ hlarge\n      _ = b^3 := by ring\n  refine ⟨by change 0<b;omega,?_,?_⟩\n  · exact (Nat.mul_le_mul hB hk).trans (by simpa only [pow_two] using hcube)\n  · exact (Nat.mul_le_mul_left lam hk).trans (by simpa only [pow_two] using hinput)\n\n/-- The original binary input parameter's square is eventually paid by root size. -/\ntheorem eventually_input_square :\n    ∀ᶠ s : ℕ in atTop,(Nat.clog 2 (s+2))^2 ≤ s := by\n  have hlog := (tendsto_add_atTop_nat 2).eventually\n    (SemiprimeSourceLayoutRate.eventually_clog_power_le_rpow 2 (1/2) (by norm_num))\n  filter_upwards [hlog,eventually_ge_atTop (3:ℕ)] with s hl hs\n  rw [←Real.sqrt_eq_rpow] at hl\n  have hsR : (3:ℝ) ≤ s := by exact_mod_cast hs\n  have hroot : Real.sqrt (s+2:ℕ) ≤ (s:ℝ) := by\n    apply (Real.sqrt_le_left (by positivity)).mpr\n    push_cast\n    have hh : (0:ℝ) ≤ ((s:ℝ)-2)*((s:ℝ)+1) := mul_nonneg (by linarith) (by positivity)\n    nlinarith\n  exact_mod_cast hl.trans hroot\n\n/-- Every literal RootReady check eventually succeeds at the actual original\nparameter lam=clog2(s+2), with no eventual-acceptance premise. -/\ntheorem eventually_rootReady :\n    ∀ᶠ s : ℕ in atTop,RootReady s (Nat.clog 2 (s+2)) := by\n  have ht : Tendsto (fun s : ℕ => Nat.clog 2 (s+2)) atTop atTop :=\n    SemiprimeCounterRate.tendsto_clog_two_atTop.comp (tendsto_add_atTop_nat 2)\n  have hB:=ht.eventually eventually_minimum_cube\n  have hlarge:=ht.eventually (eventually_ge_atTop\n    ((2*epsilonDenominator)^2*epsilonDenominator))\n  filter_upwards [hB,hlarge,eventually_input_square] with s hBs hLs hIs\n  apply rootReady_of_numeric s (Nat.clog 2 (s+2)) hBs _ hIs\n  exact (Nat.le_div_iff_mul_le (by norm_num [epsilonDenominator])).mpr hLs\n\n/-- Uniform original-input bound for EVERY actual stopped path node,\nwith all extra leaf guards discharged eventually rather than assumed. -/\ntheorem eventually_inactive_leaf :\n    ∀ᶠ s : ℕ in atTop,∀d M : ℕ,\n      M*8^d ≤ s → ¬Active s (Nat.clog 2 (s+2)) d M →\n      (M:ℝ) ≤ (s:ℝ)/Real.sqrt (Nat.clog 2 (s+2):ℕ)+1 := by\n  filter_upwards [eventually_rootReady] with s hr\n  intro d M hpath hstop\n  exact inactive_real_leaf s _ d M hr hpath hstop\n\nend RiemannGaussian.SemiprimeD1LeafReady\n","RiemannGaussian.SemiprimeD1NetworkAcquiredQueries":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketQueryProduct\nimport RiemannGaussian.SemiprimeD1OriginalChildProduct\nimport RiemannGaussian.SemiprimeD1ChildContractionSum\nimport RiemannGaussian.SemiprimeD1NetworkPacketPolynomial\n\n/-! # Acquired original queries join the actual network and actual child integrands\nEvery original table factor, packet entry and endpoint bit is read from its\nactual constructor. The assignment sums here are erased algebraic identities;\nthe executed controller uses only its acquired menu and recursive child calls.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 220000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1NetworkAcquiredQueries\nopen scoped BigOperators\nopen SemiprimeD1TensorNetwork SemiprimeD1JetAxes SemiprimeD1JetInterpretation\nopen SemiprimeD1OriginalChildProduct SemiprimeD1PacketQueryProduct\nopen SemiprimeD1ChildNetworkIntegrand SemiprimeD1ChildPacketEntrySemantics\nopen SemiprimeD1ChildOldEntryAssignment SemiprimeD1OriginalDoubleAssignments\nopen SemiprimeD1JetBoxIndex SemiprimeD1JetScalarMap SemiprimeD1DyadicInteger\nnoncomputable section\nattribute [local irreducible] SemiprimeD1PacketReplayOriginal.acquire SemiprimeD1ChildGraph.acquire\n\n/-- Actual original occurrence assignments of the literal network. -/\nabbrev OriginalBits (net : Network) (r a : ℕ) :=\n  Bits net.leftCount net.rows.length r a (arity net.rows) (owner net.rows)\n\n/-- The original individual right-X/left-Y table factors at CHILD precision. -/\ndef oldFactor (net : Network) (old : Context) (q p r a : ℕ)\n    (x y : OriginalBits net r a) : Carrier ⟨q::old.axes,p⟩ :=\n  SemiprimeD1JetBlockPolynomial.actualEmbedding old q p\n    ((net.right.toList.map (fun v => interpret ⟨old.axes,p⟩\n      (SemiprimeD1TensorTables.valueAt v.table (SemiprimeD1LeafCounter.localAssignment x v)))).prod) *\n  SemiprimeD1JetBlockPolynomial.actualEmbedding old q p\n    ((net.left.toList.map (fun v => interpret ⟨old.axes,p⟩\n      (SemiprimeD1TensorTables.valueAt v.table (SemiprimeD1LeafCounter.localAssignment y v)))).prod)\n\n/-- The actually cached packet term is exactly the actual queried entry;\nborrowing changes only reports, and the header supplies the original bucket. -/\ntheorem packetTerm_query (net : Network) (r a u p0 : ℕ) (i : Fin a) (g : Fin r)\n    (ctx : Context) (z : SemiprimeD1JetRingBits.Run)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ)\n    (bits : Incidence net.rows × Bool → Bool)\n    (f : Fin (original net r a).state.packets.length) (hpos : ctx.Positive) :\n    packetTerm net r a u p0 i g ctx z t beta bits f =\n      queryEntry ctx z net.leftCount net.rows.length r a u p0 (arity net.rows) (owner net.rows)\n        i (f,g) (endpointBits net r a bits) t beta := by\n  let source := node net r a u p0 i\n  let cache := SemiprimeD1PacketModeMask.fromModes source f i g\n  let points := ((SemiprimeD1ChildGraph.fromReplay (owner net.rows) source.packets i g).factors[f.val]?).getD []\n  have hp : source.packets = SemiprimeD1PacketReplayOriginal.acquire net.leftCount net.rows.length r a\n      (arity net.rows) (owner net.rows) := rfl\n  have he := congrArg (fun replay =>\n    ((SemiprimeD1ChildGraph.fromReplay (owner net.rows) replay i g).factors[f.val]?).getD []) hp\n  have hgraph : SemiprimeD1ChildGraph.acquire net.leftCount net.rows.length r a (arity net.rows)\n      (owner net.rows) i g = SemiprimeD1ChildGraph.fromReplay (owner net.rows)\n        (SemiprimeD1PacketReplayOriginal.acquire net.leftCount net.rows.length r a\n          (arity net.rows) (owner net.rows)) i g := by\n    unfold SemiprimeD1ChildGraph.acquire\n    rfl\n  change interpret ctx (SemiprimeD1PacketEntryBits.evaluate ctx (SemiprimeD1PacketEntryBits.borrow z)\n    a i t cache points beta (points.map (endpointBits net r a bits))).words = _\n  refine (SemiprimeD1PacketEntryPolynomial.evaluate_borrow ctx z a i t cache points beta _ hpos).trans ?_\n  dsimp only [queryEntry]\n  have he' := he.trans (congrArg (fun graph : SemiprimeD1ChildGraph.Graph (net.leftCount+net.rows.length) =>\n    (graph.factors[f.val]?).getD []) hgraph.symm)\n  exact congrArg (fun endpoints => interpret ctx (SemiprimeD1PacketEntryBits.evaluate ctx z a i t cache\n    endpoints beta (endpoints.map (endpointBits net r a bits))).words) he'\n\n/-- At each original X/Y assignment, the product of all EXECUTED child\nintegrands is exactly its original old factor times the actual queried\npacket/group product. No local truth or source-vector answer is a premise. -/\ntheorem child_product_original (net : Network) (hw : WellFormed net) (old : Context)\n    (hg : Good old net) (q p r a u : ℕ) [NeZero r] (hq : 0 < q) (i : Fin a)\n    (z : SemiprimeD1JetRingBits.Run) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (beta : List ℕ) (x y : OriginalBits net r a) (hpos : (⟨q::old.axes,p⟩ : Context).Positive) :\n    (∏ g : Fin r,interpret ⟨q::old.axes,p⟩\n      (SemiprimeD1LeafCounter.evaluateAssignment ⟨q::old.axes,p⟩\n        (vertices (child net old [q] p r a u i g z t beta))\n        (List.ofFn (networkAssignment net r a i g\n          (SemiprimeD1PacketAssignmentRows.tagBits net.leftCount net.rows.length r a\n            (arity net.rows) (owner net.rows) x y)))).words) =\n      oldFactor net old q p r a x y *\n      ∏ fg : Fin (original net r a).state.packets.length × Fin r,\n        queryEntry ⟨q::old.axes,p⟩ z net.leftCount net.rows.length r a u old.precision\n          (arity net.rows) (owner net.rows) i fg\n          (endpointBits net r a (SemiprimeD1PacketAssignmentRows.tagBits net.leftCount net.rows.length r a\n            (arity net.rows) (owner net.rows) x y)) t beta := by\n  have hc := all_child_integrands net hw old [q] p r a u i z t beta\n    (SemiprimeD1PacketAssignmentRows.tagBits net.leftCount net.rows.length r a\n      (arity net.rows) (owner net.rows) x y) hpos\n  have hp := original_parent_product net hw old hg q p r a hq x y\n  simp only [List.singleton_append] at hc\n  refine hc.trans ?_\n  apply congrArg₂ (·*·)\n  · exact hp\n  · rw [Fintype.prod_prod_type]\n    apply Finset.prod_congr rfl\n    intro f _\n    apply Finset.prod_congr rfl\n    intro g _\n    exact packetTerm_query net r a u old.precision i g ⟨q::old.axes,p⟩ z t beta _ f hpos\n\n/-- A literal acquired list commutes with the two original finite assignment\nsums, preserving its actual order and every zero contribution. -/\ntheorem sum_double_list {X Y B R : Type*} [Fintype X] [Fintype Y] [CommSemiring R]\n    (items : List B) (factor : X → Y → R) (term : B → X → Y → R) :\n    (∑ x : X,∑ y : Y,factor x y * (items.map (fun b => term b x y)).sum) =\n      (items.map (fun b => ∑ x : X,∑ y : Y,factor x y * term b x y)).sum := by\n  classical\n  induction items with\n  | nil => simp only [List.map_nil,List.sum_nil,mul_zero,Finset.sum_const_zero]\n  | cons b items ih =>\n    simp only [List.map_cons,List.sum_cons,mul_add,Finset.sum_add_distrib,ih]\n\n/-- COMPLETE actual original-network D.16 contraction. Only literal network\ndata, its actual acquired mode menu and actual constructed child leaf values\noccur. No table/coefficient/source-vector/projection or collision answer is\nsupplied. The leaf values on the right are the erased recursive specifications.\n-/\ntheorem network_query_contraction (net : Network) (hw : WellFormed net) (old : Context)\n    (hg : Good old net) (q p r a u : ℕ) [NeZero r] (i : Fin a)\n    (z : SemiprimeD1JetRingBits.Run) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (hprecision : p = (node net r a u old.precision i).precision)\n    (hpos : old.Positive) (hq : 0 < q) (hp : 0 < p)\n    (ht : SemiprimeD1WireKernelOriginal.point a t.val ≠ 0)\n    (hi : padicValInt 2 (SemiprimeD1WireKernelOriginal.point a t.val) = i.val) :\n    ((SemiprimeD1NetworkIntegralDeformation.networkPolynomial old.axes net.leftCount net.rows.length r a\n      (arity net.rows) (owner net.rows) t net.left.toList net.right.toList).map\n        (scalarMap (dims old.axes) (reduction p))).eval₂\n          (SemiprimeD1JetBlockPolynomial.actualEmbedding old q p)\n          (interpret ⟨q::old.axes,p⟩ z.words) =\n      ((node net r a u old.precision i).modes.values.map (fun beta =>\n        ∏ g : Fin r,interpret ⟨q::old.axes,p⟩\n          (leaf ⟨q::old.axes,p⟩ (child net old [q] p r a u i g z t beta)).words)).sum := by\n  let current : Context := ⟨q::old.axes,p⟩\n  let f : Carrier ⟨old.axes,p⟩ →+* Carrier current :=\n    SemiprimeD1JetBlockPolynomial.actualEmbedding old q p\n  let source := node net r a u old.precision i\n  let sigma := fun x y : OriginalBits net r a => endpointBits net r a\n    (SemiprimeD1PacketAssignmentRows.tagBits net.leftCount net.rows.length r a\n      (arity net.rows) (owner net.rows) x y)\n  let query := fun beta (x y : OriginalBits net r a) =>\n    ∏ fg : Fin (original net r a).state.packets.length × Fin r,\n      queryEntry current z net.leftCount net.rows.length r a u old.precision\n        (arity net.rows) (owner net.rows) i fg (sigma x y) t beta\n  have hcurrent : current.Positive := by\n    intro j hj\n    rcases List.mem_cons.mp hj with rfl | hj\n    · exact hq\n    · exact hpos j hj\n  have hs := SemiprimeD1NetworkPacketPolynomial.network_packet_polynomial old.axes current f\n    (SemiprimeD1ChildFreshLiftValue.actualEmbedding_constants old q p) z net r a u old.precision i t\n      hprecision hcurrent hp ht hi\n  have heval (x y : OriginalBits net r a) :\n      MvPolynomial.eval\n        (SemiprimeD1PacketSourceVector.values current net.leftCount net.rows.length r a (p-1)\n          (arity net.rows) (owner net.rows) i (sigma x y))\n        (∏ packet : Fin (original net r a).state.packets.length,∏ g : Fin r,\n          SemiprimeD1PacketRowProducts.packetPolynomial current z net.leftCount net.rows.length r a u\n            old.precision (arity net.rows) (owner net.rows) i packet g (sigma x y) t) =\n      (source.modes.values.map (fun beta => query beta x y)).sum := by\n    have he := original_eval_queries current z net.leftCount net.rows.length r a u old.precision\n      (arity net.rows) (owner net.rows) i (sigma x y) t hprecision hcurrent hp ht hi\n    have hprod :\n        (∏ packet : Fin (original net r a).state.packets.length,∏ g : Fin r,\n          SemiprimeD1PacketRowProducts.packetPolynomial current z net.leftCount net.rows.length r a u\n            old.precision (arity net.rows) (owner net.rows) i packet g (sigma x y) t) =\n        ∏ fg : Fin (original net r a).state.packets.length × Fin r,\n          SemiprimeD1PacketRowProducts.packetPolynomial current z net.leftCount net.rows.length r a u\n            old.precision (arity net.rows) (owner net.rows) i fg.1 fg.2 (sigma x y) t := by\n      rw [Fintype.prod_prod_type]\n    exact (congrArg (MvPolynomial.eval\n      (SemiprimeD1PacketSourceVector.values current net.leftCount net.rows.length r a (p-1)\n        (arity net.rows) (owner net.rows) i (sigma x y))) hprod).trans he\n  calc\n    _ = ∑ x : OriginalBits net r a,∑ y : OriginalBits net r a,\n        oldFactor net old q p r a x y *\n        MvPolynomial.eval\n          (SemiprimeD1PacketSourceVector.values current net.leftCount net.rows.length r a (p-1)\n            (arity net.rows) (owner net.rows) i (sigma x y))\n          (∏ packet : Fin (original net r a).state.packets.length,∏ g : Fin r,\n            SemiprimeD1PacketRowProducts.packetPolynomial current z net.leftCount net.rows.length r a u\n              old.precision (arity net.rows) (owner net.rows) i packet g (sigma x y) t) := hs\n    _ = ∑ x : OriginalBits net r a,∑ y : OriginalBits net r a,\n        oldFactor net old q p r a x y * (source.modes.values.map (fun beta => query beta x y)).sum := by\n      apply Finset.sum_congr rfl\n      intro x _\n      apply Finset.sum_congr rfl\n      intro y _\n      exact congrArg (fun value => oldFactor net old q p r a x y * value) (heval x y)\n    _ = (source.modes.values.map (fun beta => ∑ x : OriginalBits net r a,∑ y : OriginalBits net r a,\n        oldFactor net old q p r a x y * query beta x y)).sum :=\n      sum_double_list source.modes.values (oldFactor net old q p r a) query\n    _ = _ := by\n      apply congrArg List.sum\n      apply List.map_congr_left\n      intro beta _\n      have hpoint (x y : OriginalBits net r a) :=\n        child_product_original net hw old hg q p r a u hq i z t beta x y hcurrent\n      have hsum := SemiprimeD1ChildContractionSum.sum_child_contractions net old [q] p r a u i z t beta hcurrent\n      simp only [List.singleton_append] at hsum\n      refine Eq.trans ?_ hsum\n      apply Finset.sum_congr rfl\n      intro x _\n      apply Finset.sum_congr rfl\n      intro y _\n      exact (hpoint x y).symm\n\nend\nend RiemannGaussian.SemiprimeD1NetworkAcquiredQueries\n","RiemannGaussian.SemiprimeD1NormalizedLinearBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecoveryStripBits\nimport RiemannGaussian.SemiprimeD1RadixOperandBits\nimport RiemannGaussian.SemiprimeD1WireKernelFactors\nimport RiemannGaussian.SemiprimeBitIndexGeometry\n\n/-! # Physical normalized original linear factors\nSubtraction, low-bit stripping and unsigned division acquire the factor. Native\nvaluations and exact integer quotients occur only in the correctness statement.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 500000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1NormalizedLinearBits\nopen SemiprimeBitArithmetic SemiprimeBitDivision SemiprimeBitIndexClipping\nopen SemiprimeBitIndexGeometry SemiprimeBitFermatArithmetic\nopen SemiprimeD1RecoveryIntegerBits SemiprimeD1WireKernelFactors\n\n/-- Acquired content, signed constant, slope and retained physical work. -/\nstructure Run where\n  /-- Literal dyadic content word. -/\n  content : List Bool\n  /-- Signed stripped difference. -/\n  constant : SignedWord\n  /-- Exact alpha/content quotient word. -/\n  slope : List Bool\n  /-- All arithmetic and allocation reports. -/\n  clock : ℕ\n\n/-- Actual shifted-one alpha, including radix allocation. -/\ndef alpha (k : ℕ) : SemiprimeD1RadixOperandBits.Run :=\n  let shifted:=shiftTemplateBits (List.replicate k false) [true]\n  ⟨shifted.bits,bitCost shifted+3*k+2⟩\n\n/-- Alpha has its original exact value. -/\ntheorem alpha_value (k : ℕ) : bitValue (alpha k).bits=2^k := by\n  have h:bitValue [true]=1:=rfl\n  simpa only [alpha,List.length_replicate,h,Nat.mul_one] using\n    (shiftTemplateBits_exact (List.replicate k false) [true]).1\n\n/-- Compute the original factor using physical words only. -/\ndef acquire (k : ℕ) (j q : List Bool) : Run :=\n  let a:=alpha k\n  let delta:=subSignedBits (positive j) (positive q)\n  let test:=nonzeroBits delta.word.magnitude\n  if test.nonzero then\n    let stripped:=SemiprimeD1RecoveryStripBits.acquire delta.word.magnitude\n    let quotient:=divideBits a.bits stripped.content\n    ⟨stripped.content,⟨delta.word.negative,stripped.odd⟩,quotient.quotient,\n      a.clock+delta.clock+test.clock+stripped.clock+quotient.clock+8⟩\n  else\n    ⟨a.bits,positive [],[true],a.clock+delta.clock+test.clock+8⟩\n\n/-- Exact signed subtraction at the original indices. -/\ntheorem difference_value (j q : List Bool) :\n    (subSignedBits (positive j) (positive q)).word.value=\n      difference (bitValue j) (bitValue q) := by\n  exact subSignedBits_value (positive j) (positive q)\n\n/-- The acquired content matches the original normalization exponent. -/\ntheorem acquire_content (k : ℕ) (j q : List Bool) :\n    bitValue (acquire k j q).content=2^factorOrder k (bitValue j) (bitValue q) := by\n  have hv:=difference_value j q\n  have ha:=signedWord_natAbs (subSignedBits (positive j) (positive q)).word\n  dsimp only [acquire]\n  split\n  next h =>\n    have hp:= (nonzeroBits_correct _).mp h\n    rw [SemiprimeD1RecoveryStripBits.content_value _ hp]\n    unfold SemiprimeD1IntegerRecoveryResidue.content\n    rw [←ha,hv]\n    have hn:bitValue q≠bitValue j:=by\n      intro he\n      simp only [difference,he,sub_self] at hv ha\n      omega\n    simp only [factorOrder,ite_eq_right hn,padicValInt]\n  next h =>\n    have hz:bitValue (subSignedBits (positive j) (positive q)).word.magnitude=0:=by\n      have hh:=nonzeroBits_correct (subSignedBits (positive j) (positive q)).word.magnitude\n      cases hb:(nonzeroBits (subSignedBits (positive j) (positive q)).word.magnitude).nonzero\n      · have :¬0<bitValue (subSignedBits (positive j) (positive q)).word.magnitude:=by\n          intro hp; have ht:=hh.mpr hp; simp [hb] at ht\n        omega\n      · contradiction\n    have he:bitValue q=bitValue j:=by\n      rw [hz] at ha\n      have hh:Int.natAbs (difference (bitValue j) (bitValue q))=0:=by simpa [hv] using ha\n      have :=Int.natAbs_eq_zero.mp hh\n      unfold difference at this\n      omega\n    simpa only [factorOrder,ite_eq_left he] using alpha_value k\n/-- The acquired signed constant reconstructs the actual signed difference. -/\ntheorem acquire_reconstruct (k : ℕ) (j q : List Bool) :\n    (acquire k j q).constant.value*(bitValue (acquire k j q).content:ℤ)=\n      difference (bitValue j) (bitValue q) := by\n  have hv:=difference_value j q\n  have ha:=signedWord_natAbs (subSignedBits (positive j) (positive q)).word\n  dsimp only [acquire]\n  split\n  next h =>\n    have hf:=SemiprimeD1RecoveryStripBits.factor\n      (subSignedBits (positive j) (positive q)).word.magnitude\n    have hi:(bitValue (subSignedBits (positive j) (positive q)).word.magnitude:ℤ)=\n        (bitValue (SemiprimeD1RecoveryStripBits.acquire\n          (subSignedBits (positive j) (positive q)).word.magnitude).content:ℤ)*\n        (bitValue (SemiprimeD1RecoveryStripBits.acquire\n          (subSignedBits (positive j) (positive q)).word.magnitude).odd:ℤ):=by\n      exact_mod_cast hf\n    rw [←hv]\n    cases hs:(subSignedBits (positive j) (positive q)).word.negative <;>\n      simp only [SignedWord.value,hs,Bool.false_eq_true,ite_false,ite_true] <;>\n      nlinarith only [hi]\n  next h =>\n    have hh:=nonzeroBits_correct (subSignedBits (positive j) (positive q)).word.magnitude\n    have hz:bitValue (subSignedBits (positive j) (positive q)).word.magnitude=0:=by\n      by_contra hn\n      have hp:0<bitValue (subSignedBits (positive j) (positive q)).word.magnitude:=by omega\n      exact h (hh.mpr hp)\n    have hd:difference (bitValue j) (bitValue q)=0:=by\n      apply Int.natAbs_eq_zero.mp\n      rw [←hv,ha,hz]\n    simp only [positive,SignedWord.value,Bool.false_eq_true,ite_false,bitValue,\n      Int.natCast_zero,zero_mul,hd]\n\n/-- The physical constant is the original normalized signed coefficient. -/\ntheorem acquire_constant (k : ℕ) (j q : List Bool) :\n    (acquire k j q).constant.value=(normalizedFactor k (bitValue j) (bitValue q)).constant := by\n  have h:=acquire_reconstruct k j q\n  rw [acquire_content] at h\n  have hc:=normalized_constant k (bitValue j) (bitValue q)\n  have hp:(2:ℤ)^factorOrder k (bitValue j) (bitValue q)≠0:=by positivity\n  have hcast:((2^factorOrder k (bitValue j) (bitValue q):ℕ):ℤ)=\n      (2:ℤ)^factorOrder k (bitValue j) (bitValue q):=by norm_cast\n  rw [hcast] at h\n  exact mul_right_cancel₀ hp (h.trans hc.symm)\n\n/-- The original range guards derive exact slope division, without quotient advice. -/\ntheorem acquire_slope (k : ℕ) (j q : List Bool)\n    (hj:bitValue j<2^k) (hq:bitValue q<2^k) :\n    (bitValue (acquire k j q).slope:ℤ)=\n      (normalizedFactor k (bitValue j) (bitValue q)).slope := by\n  have hcontent:=acquire_content k j q\n  have hdiv:=factorOrder_dvd_alpha k (bitValue j) (bitValue q) hj hq\n  have hd:(2^factorOrder k (bitValue j) (bitValue q):ℕ)∣2^k:=by\n    exact_mod_cast hdiv\n  have hs:=normalized_slope k (bitValue j) (bitValue q) hj hq\n  dsimp only [acquire] at hcontent ⊢\n  split\n  next h =>\n    simp only [ite_eq_left h] at hcontent\n    have hv:bitValue (divideBits (alpha k).bits\n        (SemiprimeD1RecoveryStripBits.acquire\n          (subSignedBits (positive j) (positive q)).word.magnitude).content).quotient=\n        2^k/2^factorOrder k (bitValue j) (bitValue q):=by\n      rw [(divideBits_correct _ _).1,alpha_value,hcontent]\n    rw [hv]\n    have he:(2^k/2^factorOrder k (bitValue j) (bitValue q):ℕ)*\n        2^factorOrder k (bitValue j) (bitValue q)=2^k:=Nat.div_mul_cancel hd\n    have hei:((2^k/2^factorOrder k (bitValue j) (bitValue q):ℕ):ℤ)*\n        (2:ℤ)^factorOrder k (bitValue j) (bitValue q)=(2:ℤ)^k:=by exact_mod_cast he\n    exact mul_right_cancel₀ (by positivity : (2:ℤ)^factorOrder k (bitValue j) (bitValue q)≠0)\n      (hei.trans hs.symm)\n  next h =>\n    simp only [ite_eq_right h] at hcontent\n    have he:factorOrder k (bitValue j) (bitValue q)=k:=by\n      rw [alpha_value] at hcontent\n      exact (Nat.pow_right_injective (by decide : 1<(2:ℕ))) hcontent.symm\n    rw [he] at hs\n    have hp:(2:ℤ)^k≠0:=by positivity\n    have hh:(1:ℤ)*(2:ℤ)^k=(normalizedFactor k (bitValue j) (bitValue q)).slope*(2:ℤ)^k:=by\n      simpa only [one_mul] using hs.symm\n    exact mul_right_cancel₀ hp hh\n/-- Genuine alpha width, including its high one. -/\ntheorem alpha_length (k : ℕ) : (alpha k).bits.length=k+1 := by\n  simpa only [alpha,List.length_replicate,List.length_cons,List.length_nil] using\n    (shiftTemplateBits_exact (List.replicate k false) [true]).2.1\n\n/-- All alpha construction work is retained. -/\ntheorem alpha_clock (k : ℕ) : (alpha k).clock=6*k+3 := by\n  have h:=(shiftTemplateBits_exact (List.replicate k false) [true]).2.2\n  simp only [List.length_replicate] at h\n  dsimp only [alpha]\n  rw [h]\n  omega\n\n/-- Original physical input sizes derive every output width; no fit advice. -/\ntheorem acquire_width (k W : ℕ) (j q : List Bool)\n    (hj:j.length≤W) (hq:q.length≤W) :\n    (acquire k j q).content.length≤k+W+2 ∧\n    (acquire k j q).constant.magnitude.length≤W+1 ∧\n    (acquire k j q).slope.length≤k+1 := by\n  have hw:=(subSignedBits_cost_width (left:=positive j) (right:=positive q) hj hq).2\n  have hs:=SemiprimeD1RecoveryStripBits.lengths\n    (subSignedBits (positive j) (positive q)).word.magnitude\n  dsimp only [acquire]\n  split\n  next h =>\n    rcases SemiprimeD1RecoveryStripBits.content_power\n        (subSignedBits (positive j) (positive q)).word.magnitude with ⟨v,hv⟩\n    have hp:0<bitValue (SemiprimeD1RecoveryStripBits.acquire\n        (subSignedBits (positive j) (positive q)).word.magnitude).content:=by rw [hv]; positivity\n    have hd:=(divideBits_widths (xs:=(alpha k).bits) hp).2\n    rw [alpha_length] at hd\n    dsimp only\n    exact ⟨by omega,by omega,by omega⟩\n  next h =>\n    simp only [alpha_length,positive,List.length_nil,List.length_cons]\n    omega\n\n/-- Explicit polynomial physical arithmetic/list budget. -/\ndef budget (k W : ℕ) : ℕ :=\n  6*k+3+41*(W+1)+(3*(W+1)+1)+(8*(W+1)+10)+\n    (k+1)*(16*(W+2)+20)+7*(W+2)+4+8\n\n/-- Complete executed report bound from original input widths only. -/\ntheorem acquire_clock (k W : ℕ) (j q : List Bool)\n    (hj:j.length≤W) (hq:q.length≤W) :\n    (acquire k j q).clock≤budget k W := by\n  have hdelta:=subSignedBits_cost_width (left:=positive j) (right:=positive q) hj hq\n  have ht:=nonzeroBits_cost (subSignedBits (positive j) (positive q)).word.magnitude\n  have hs:=SemiprimeD1RecoveryStripBits.acquire_clock\n    (subSignedBits (positive j) (positive q)).word.magnitude\n  have hl:=SemiprimeD1RecoveryStripBits.lengths\n    (subSignedBits (positive j) (positive q)).word.magnitude\n  have hd:=divideBits_cost (alpha k).bits (SemiprimeD1RecoveryStripBits.acquire\n    (subSignedBits (positive j) (positive q)).word.magnitude).content\n  rw [alpha_length] at hd\n  have hbound:(k+1)*(16*(SemiprimeD1RecoveryStripBits.acquire\n      (subSignedBits (positive j) (positive q)).word.magnitude).content.length+20)≤\n      (k+1)*(16*(W+2)+20):=by\n    apply Nat.mul_le_mul_left\n    omega\n  dsimp only [acquire]\n  split <;> dsimp only <;> rw [alpha_clock] <;> unfold budget <;> omega\nend RiemannGaussian.SemiprimeD1NormalizedLinearBits\n","RiemannGaussian.SemiprimeD1OrientationInverseBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1OrientationInverse\n\n/-! # Actual physical inverse parser/copy report bounds\nAll widths are derived from the original key and slot lengths. No intermediate\nFits, inverse answer, semantic colour or externally chosen width controls execution.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1OrientationInverseBounds\nopen SemiprimeD1OrientationBits SemiprimeD1OrientationInverse\nopen SemiprimeBitIndexClipping SemiprimeSourceHistogramKeyBits\n\n/-- Every actual parser output is an input slice/copy and every inspected cell is paid. -/\ntheorem split_metrics : (key : List Bool) →\n    (split key).first.length≤key.length ∧ (split key).rest.length≤key.length ∧\n      (split key).clock≤6*key.length+3\n  | [] => by simp [split]\n  | false::ys => by simp [split]\n  | true::[] => by simp [split]\n  | true::b::bs => by\n    obtain ⟨hf,hr,hc⟩ := split_metrics bs\n    simp only [split,List.length_cons]\n    omega\n\n/-- Every inverse padding temporary has only original high bits plus slot bits. -/\ntheorem index_length (key slots : List Bool) :\n    (recover key slots).index.length≤key.length+slots.length := by\n  induction slots generalizing key with\n  | nil => simp [recover,SemiprimeSourceCompactBits.copy_bits]\n  | cons bit slots ih =>\n    let field := split key\n    let colours := split field.first\n    let tail := recover field.rest slots\n    have hf : field.rest.length≤key.length := (split_metrics key).2.1\n    have ht : tail.index.length≤field.rest.length+slots.length := ih field.rest\n    have htrim := SemiprimeSourceCompactBits.trim_length (bit::tail.index)\n    change (if equality (leSignedBits ⟨false,colours.first⟩ ⟨false,colours.rest⟩)\n      then SemiprimeSourceCompactBits.trim (bit::tail.index)\n      else SemiprimeSourceCompactBits.copy tail.index).bits.length≤_\n    simp only [List.length_cons]\n    split_ifs\n    · simp only [List.length_cons] at htrim\n      omega\n    · rw [SemiprimeSourceCompactBits.copy_bits]\n      omega\n\n/-- Full inverse report bound from actual original key/slot lengths, valid or malformed.\nThe statement includes all recursive parses, borrows, zero scans, copies and trims;\nit does not claim a complete external address/tape machine simulation. -/\ntheorem recover_clock (key slots : List Bool) :\n    (recover key slots).clock≤200*(slots.length+1)*(key.length+slots.length+1) := by\n  induction slots generalizing key with\n  | nil => simp only [recover,SemiprimeSourceCompactBits.copy_clock,List.length_nil];omega\n  | cons bit slots ih =>\n    let field := split key\n    let colours := split field.first\n    let tail := recover field.rest slots\n    let order := leSignedBits ⟨false,colours.first⟩ ⟨false,colours.rest⟩\n    let eq := equality order\n    have hf := split_metrics key\n    have hc := split_metrics field.first\n    have hcl : colours.first.length≤key.length := hc.1.trans hf.1\n    have hcr : colours.rest.length≤key.length := hc.2.1.trans hf.1\n    have ho : order.clock≤40*(key.length+1) := leSignedBits_cost hcl hcr\n    have ht : tail.clock≤200*(slots.length+1)*(key.length+slots.length+1) :=\n      (ih field.rest).trans (by gcongr;exact hf.2.1)\n    have hj : tail.index.length≤key.length+slots.length :=\n      (index_length field.rest slots).trans (Nat.add_le_add_right hf.2.1 _)\n    have hleft : (if eq then colours.first else if bit then colours.rest else colours.first).length≤key.length := by\n      split_ifs <;> assumption\n    have hright : (if eq then colours.rest else if bit then colours.first else colours.rest).length≤key.length := by\n      split_ifs <;> assumption\n    have hi : (if eq then SemiprimeSourceCompactBits.trim (bit::tail.index)\n        else SemiprimeSourceCompactBits.copy tail.index).clock≤6*(key.length+slots.length+1)+1 := by\n      split_ifs <;> simp only [SemiprimeSourceCompactBits.trim_clock,\n        SemiprimeSourceCompactBits.copy_clock,List.length_cons] <;> omega\n    change field.clock+colours.clock+tail.clock+order.clock+\n      (SemiprimeSourceCompactBits.copy (if eq then colours.first else if bit then colours.rest else colours.first)).clock+\n      (SemiprimeSourceCompactBits.copy (if eq then colours.rest else if bit then colours.first else colours.rest)).clock+\n      (if eq then SemiprimeSourceCompactBits.trim (bit::tail.index)\n        else SemiprimeSourceCompactBits.copy tail.index).clock+30≤_\n    rw [SemiprimeSourceCompactBits.copy_clock,SemiprimeSourceCompactBits.copy_clock]\n    simp only [List.length_cons]\n    nlinarith\n\nend RiemannGaussian.SemiprimeD1OrientationInverseBounds\n","RiemannGaussian.SemiprimeD1OriginalDoubleAssignments":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketAssignmentRows\n\n/-! # Original X/Y assignments biject with the actual two-sided incidence tags\nThe correspondence uses the acquired original placement order. Together with\nthe computed child pullbacks it turns the original double assignment sum into\nindependent sums on the actual child scopes, without a projection oracle.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2200000\nnamespace RiemannGaussian.SemiprimeD1OriginalDoubleAssignments\nopen scoped BigOperators\nopen SemiprimeD1OriginalIncidenceIndex SemiprimeD1PacketAssignmentRows\nopen SemiprimeD1ChildAssignmentEquiv\nnoncomputable section\n\n/-- Original Boolean assignments on the actual acquired occurrence stream. -/\nabbrev Bits (n F r a : ℕ) (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n) :=\n  Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).placements.length → Bool\n\n/-- The inverse reads the computed position inverse and preserves both sides;\nit does not select or solve any Boolean assignment. -/\ndef doubleAssignments (n F r a : ℕ) (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n) :\n    (Bits n F r a arity owner × Bits n F r a arity owner) ≃ (Tag arity → Bool) where\n  toFun xy := tagBits n F r a arity owner xy.1 xy.2\n  invFun bits :=\n    (fun j => bits ((position n F r a arity owner).symm j,false),\n     fun j => bits ((position n F r a arity owner).symm j,true))\n  left_inv xy := by\n    apply Prod.ext <;> funext j\n    · simp only [tagBits,Bool.false_eq_true,ite_false,Equiv.apply_symm_apply]\n    · simp only [tagBits,ite_true,Equiv.apply_symm_apply]\n  right_inv bits := by\n    funext tag\n    rcases tag with ⟨port,side⟩\n    cases side <;> simp only [tagBits,Bool.false_eq_true,ite_false,ite_true,\n      Equiv.symm_apply_apply]\n\n/-- The original two assignment sums are exactly one sum over original tags,\nincluding the empty-incidence case. -/\ntheorem sum_original {R : Type*} [AddCommMonoid R] (n F r a : ℕ)\n    (arity : Fin F → ℕ) (owner : ((e : Fin F) × Fin (arity e)) → Fin n)\n    (term : (Tag arity → Bool) → R) :\n    (∑ x : Bits n F r a arity owner,∑ y : Bits n F r a arity owner,\n      term (tagBits n F r a arity owner x y)) = ∑ bits : Tag arity → Bool, term bits := by\n  classical\n  have h := (doubleAssignments n F r a arity owner).sum_comp term\n  change (∑ xy : Bits n F r a arity owner × Bits n F r a arity owner,\n    term (tagBits n F r a arity owner xy.1 xy.2)) = _ at h\n  simpa only [Fintype.sum_prod_type] using h\n\n/-- Applying the actual cached colour partition to the original X/Y sum\ngives independent contractions on the actual acquired child scopes. -/\ntheorem sum_child_products {R : Type*} [CommRing R] (n F r a : ℕ) [NeZero r]\n    (arity : Fin F → ℕ) (owner : ((e : Fin F) × Fin (arity e)) → Fin n) (i : Fin a)\n    (term : (g : Fin r) → (Fin (scope n F r a arity owner i g) → Bool) → R) :\n    (∑ x : Bits n F r a arity owner,∑ y : Bits n F r a arity owner,\n      ∏ g : Fin r,term g (assignments n F r a arity owner i\n        (tagBits n F r a arity owner x y) g)) =\n      ∏ g : Fin r,∑ bits : Fin (scope n F r a arity owner i g) → Bool,term g bits := by\n  exact (sum_original n F r a arity owner (fun bits =>\n    ∏ g,term g (assignments n F r a arity owner i bits g))).trans\n      (sum_product n F r a arity owner i term)\n\nend\nend RiemannGaussian.SemiprimeD1OriginalDoubleAssignments\n","RiemannGaussian.SemiprimeD1PackedMomentAlgebra":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport Mathlib\n\n/-! # Exact first-moment cancellation in a scalar square modulus\nThese are finite algebra identities. They do not supply a contraction value,\nits coefficient acquisition or a runtime bound. Higher terms are discarded\nonly in the FINAL scalar ring, never in intermediate integer lifts.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1PackedMomentAlgebra\nopen scoped BigOperators\n\n/-- A square-zero marker retains the constant and the complete first moment. -/\ntheorem marked_product {E R : Type*} [CommSemiring R] (s : Finset E)\n    (b : R) (hb : b*b=0) (w : E→R) :\n    (∏ e ∈ s, (1+b*w e))=1+b*(∑ e ∈ s, w e) := by\n  classical\n  induction s using Finset.induction_on with\n  | empty => simp\n  | @insert e s he ih =>\n    rw [Finset.prod_insert he,Finset.sum_insert he,ih]\n    calc\n      _ = 1+b*(w e+∑ j ∈ s, w j)+(b*b)*(w e*(∑ j ∈ s, w j)) := by ring\n      _ = _ := by rw [hb]; simp\n\n/-- Literal local checker zeros still reject an entire assignment. -/\ntheorem checked_product {E R : Type*} [Fintype E] [CommSemiring R]\n    (test : E→Bool) (b : R) (hb : b*b=0) (w : E→R) :\n    (∏e,if test e then 1+b*w e else 0)=\n      if ∀e,test e=true then 1+b*(∑e,w e) else 0 := by\n  classical\n  by_cases h : ∀e,test e=true\n  · rw [ite_eq_left h]\n    simpa only [h,ite_true] using marked_product Finset.univ b hb w\n  · rw [ite_eq_right h]\n    obtain ⟨e,he⟩ := not_forall.mp h\n    exact Finset.prod_eq_zero (Finset.mem_univ e) (ite_eq_right he)\n\n/-- The public base itself is square-zero in the FINAL ring modulo its square. -/\ntheorem base_square_zero (B : ℕ) : (B : ZMod (B^2))*(B : ZMod (B^2))=0 := by\n  rw [←Nat.cast_mul,←pow_two,ZMod.natCast_self]\n\n/-- Count and first moment cannot carry into each other when each is below B. -/\ntheorem packed_lt (B c S : ℕ) (hc : c<B) (hS : S<B) : c+B*S<B^2 := by\n  have hB : 0<B := by omega\n  have hs : S+1≤B := by omega\n  have hm := Nat.mul_le_mul_left B hs\n  nlinarith only [hc,hm]\n\n/-- Low and high base-B digits recover the exact count and first moment. -/\ntheorem unpack (B c S : ℕ) (hB : 0<B) (hc : c<B) :\n    (c+B*S)%B=c ∧ (c+B*S)/B=S := by\n  constructor\n  · rw [Nat.add_mul_mod_self_left,Nat.mod_eq_of_lt hc]\n  · rw [Nat.add_mul_div_left _ _ hB,Nat.div_eq_of_lt hc,Nat.zero_add]\n\n/-- The canonical scalar residue has the same two exact digits; no oracle\nfor the count or sum is introduced by this readout identity. -/\ntheorem residue_unpack (B c S : ℕ) (hc : c<B) (hS : S<B) :\n    ((c+B*S : ℕ) : ZMod (B^2)).val=c+B*S ∧\n      ((c+B*S : ℕ) : ZMod (B^2)).val%B=c ∧\n      ((c+B*S : ℕ) : ZMod (B^2)).val/B=S := by\n  have hv : ((c+B*S : ℕ) : ZMod (B^2)).val=c+B*S := by\n    rw [ZMod.val_natCast,Nat.mod_eq_of_lt (packed_lt B c S hc hS)]\n  have h := unpack B c S (by omega) hc\n  exact ⟨hv,by rw [hv];exact h.1,by rw [hv];exact h.2⟩\n\nend RiemannGaussian.SemiprimeD1PackedMomentAlgebra\n","RiemannGaussian.SemiprimeD1PackedRootFactoryInputs":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PackedRootCaches\n/-! # Actual original-input operands for the structural child factory\nThe complete63 selector,21 occurrence and59 inventory allocations already\nexist in Root2505. These are fixed address inclusions, not runtime getters.\nNo coefficient or table payload is among these structural inputs.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnoncomputable section\nnamespace RiemannGaussian.SemiprimeD1PackedRootFactoryInputs\nopen SemiprimeBitArithmetic (bitValue)\nnamespace P\nexport SemiprimeD1StackPackedRootInput (Stack rootStack output)\nexport SemiprimeD1StackPackedRootInputEncoding (done)\nend P\nnamespace S\nexport SemiprimeD1StackSourceIncidenceSelect (Stack environmentStack aux)\nend S\nnamespace O\nexport SemiprimeD1StackSourceOccurrences (Stack)\nend O\nnamespace I\nexport SemiprimeD1StackPacketInventory (Stack)\nend I\n/-- Every selector role is an already allocated literal root address. -/\ndef selector (k : S.Stack) : P.Stack := SemiprimeD1PackedRootCaches.sourceStack\n  (SemiprimeD1StackSourceSelectionAcquire.selectorStack k)\n/-- Every occurrence role is an already allocated literal root address. -/\ndef occurrence (k : O.Stack) : P.Stack := SemiprimeD1PackedRootCaches.sourceStack\n  (SemiprimeD1StackSourceSelectionAcquire.occurrenceStack k)\n/-- Every inventory role is retained, including unused maps and shadows. -/\ndef inventory (k : I.Stack) : P.Stack := P.rootStack (SemiprimeD1StackRootPacketInventory.inventoryStack k)\n/-- All143 actual retained roles, with no duplicate allocation or discarded shadow. -/\nabbrev Cache := S.Stack⊕(O.Stack⊕I.Stack)\n/-- The exact static inclusion of the complete three-bank cache into Root2505. -/\ndef cache : Cache→P.Stack := Sum.elim selector (Sum.elim occurrence inventory)\n/-- The actual complete selector bank has its NEW weighted-network interpretation. -/\ntheorem selector_original (bits : List Bool) (hN : 0<bitValue bits) (k : S.Stack) :\n    (P.done bits hN).data (selector k)=\n      (SemiprimeD1StackSourceSelectionAcquireEncoding.selectorDone\n        (SemiprimeD1StackMarkedRootRecordsNetwork.network (bitValue bits) hN)\n        (SemiprimeD1StackRootSelectionAcquireEncoding.dimension bits)).data k :=\n  (SemiprimeD1PackedRootCaches.source_original bits hN\n    (SemiprimeD1StackSourceSelectionAcquire.selectorStack k)).trans\n      (SemiprimeD1StackSourceSelectionAcquireOriginal.selector_retained _ _ k)\n/-- The actual complete occurrence bank has its NEW weighted-network interpretation. -/\ntheorem occurrence_original (bits : List Bool) (hN : 0<bitValue bits) (k : O.Stack) :\n    (P.done bits hN).data (occurrence k)=\n      (SemiprimeD1StackSourceSelectionAcquireEncoding.occurrenceDone\n        (SemiprimeD1StackMarkedRootRecordsNetwork.network (bitValue bits) hN)).data k :=\n  (SemiprimeD1PackedRootCaches.source_original bits hN\n    (SemiprimeD1StackSourceSelectionAcquire.occurrenceStack k)).trans\n      (SemiprimeD1StackSourceSelectionAcquireOriginal.occurrence_retained _ _ k)\n/-- Every actual inventory word remains exactly its own stopped producer word. -/\ntheorem inventory_retained (bits : List Bool) (hN : 0<bitValue bits) (k : I.Stack) :\n    (P.done bits hN).data (inventory k)=\n      (SemiprimeD1StackRootPacketInventoryEncoding.inventoryDone bits hN).data k :=\n  (SemiprimeD1StackPackedRootInputOriginal.all_root_retained bits hN\n    (SemiprimeD1StackRootPacketInventory.inventoryStack k)).trans\n      (SemiprimeD1StackRootPacketInventoryExecution.inventory_retained bits hN k)\n/-- Physical selected-ID dictionary operand; it contains no table coefficients. -/\ndef environment : P.Stack := selector (S.environmentStack (SemiprimeD1StackSourceEnvironment.aux .dictionary))\n/-- Physical original colour-row catalogue operand. -/\ndef catalogue : P.Stack := selector (S.aux .catalogue)\n/-- Physical owner-marker operand, including isolated owners. -/\ndef owners : P.Stack := selector (S.aux .owners)\n/-- Physical factor-marker operand, including empty factors. -/\ndef factors : P.Stack := selector (S.aux .factors)\n/-- Physical original occurrence pair stream, with repetitions retained. -/\ndef pairs : P.Stack := occurrence .output\n/-- Physical chronological placement operand, distinct from the record table. -/\ndef placements : P.Stack := inventory SemiprimeD1StackPacketInventory.output\n/-- Physical observed-packet operand, in actual first-discovery order. -/\ndef packets : P.Stack := inventory SemiprimeD1StackPacketInventory.packets\n/-- All143 roles really remain distinct after their static inclusion into the original root bank. -/\ntheorem cache_injective : Function.Injective cache := by\n  intro a b h\n  rcases a with a|a|a <;> rcases b with b|b|b <;>\n    simp only [cache,Sum.elim_inl,Sum.elim_inr,selector,occurrence,inventory,\n      SemiprimeD1PackedRootCaches.sourceStack,SemiprimeD1StackPackedRootInput.rootStack,\n      SemiprimeD1StackRootPacketInventory.rootStack,SemiprimeD1StackRootPacketInventory.inventoryStack,\n      SemiprimeD1StackRootRecoveryWidth.rootStack,SemiprimeD1StackRootPacketPadding.rootStack,\n      SemiprimeD1StackRootSelectionAcquire.acquisitionStack,\n      SemiprimeD1StackSourceSelectionAcquire.selectorStack,\n      SemiprimeD1StackSourceSelectionAcquire.occurrenceStack,Sum.inl.injEq,Sum.inr.injEq,\n      Sum.inl_ne_inr,Sum.inr_ne_inl] at h <;> cases h <;> rfl\nend RiemannGaussian.SemiprimeD1PackedRootFactoryInputs\n","RiemannGaussian.SemiprimeD1PacketAssignmentRows":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketRowProducts\nimport RiemannGaussian.SemiprimeD1OriginalIncidenceIndex\nimport RiemannGaussian.SemiprimeD1PacketInventoryCoverage\n\n/-! # Original X/Y assignments on physically resolved packet endpoints\nThe typed occurrence/placement pairing and unique physical ID bank determine\nevery endpoint bit. No endpoint-to-original-bit correspondence is assumed.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 3500000\nnamespace RiemannGaussian.SemiprimeD1PacketAssignmentRows\nopen SemiprimeD1ChildGraph SemiprimeD1PacketInventory\nopen SemiprimeD1ChildPortPullbackCorrectness SemiprimeD1ChildAssignmentEquiv\nopen SemiprimeD1ChildAssignmentEndpoint SemiprimeD1OriginalIncidenceIndex\nnoncomputable section\n\n/-- The two original occurrence assignments retain their distinct endpoint side. -/\ndef tagBits (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (x y : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).placements.length→Bool)\n    (tag : Tag arity) : Bool :=\n  if tag.2 then y (position n F r a arity owner tag.1) else x (position n F r a arity owner tag.1)\n\n/-- Exact resolved bits of both endpoints of EVERY actual original paired port. -/\ntheorem original_pair_bits (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (q : Fin a) (g : Fin r)\n    (bits : Tag arity→Bool) (pair : ((e : Fin F)×Fin (arity e))×Placement)\n    (hp : pair∈originalPairs n F r a arity owner) :\n    originalEndpointBit n F r a arity owner bits (endpoints owner pair.1 pair.2).1=bits (pair.1,true) ∧\n    originalEndpointBit n F r a arity owner bits (endpoints owner pair.1 pair.2).2=bits (pair.1,false) := by\n  let ids := (originalPairs n F r a arity owner).map (fun p => (p.2.edge,p.1))\n  have hn : (ids.map Prod.fst).Nodup := by\n    simpa only [ids_value] using ids_nodup n F r a arity owner q g\n  have hf := findPort_member ids hn pair.2.edge pair.1 (List.mem_map.mpr ⟨pair,hp,rfl⟩)\n  simp only [originalEndpointBit,resolve,endpoints]\n  change (((SemiprimeD1ChildPortPullback.findPort pair.2.edge ids).value.map (fun i => (i,true))).map bits).getD false=_ ∧\n    (((SemiprimeD1ChildPortPullback.findPort pair.2.edge ids).value.map (fun i => (i,false))).map bits).getD false=_\n  rw [hf]\n  exact ⟨rfl,rfl⟩\n\n/-- Actual original endpoint reads are exactly the original Y/X coordinate bits\nat the computed occurrence position, including repeated parallel incidences. -/\ntheorem original_pair_xy (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (q : Fin a) (g : Fin r)\n    (x y : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).placements.length→Bool)\n    (pair : ((e : Fin F)×Fin (arity e))×Placement)\n    (hp : pair∈originalPairs n F r a arity owner) :\n    originalEndpointBit n F r a arity owner (tagBits n F r a arity owner x y)\n      (endpoints owner pair.1 pair.2).1=y (position n F r a arity owner pair.1) ∧\n    originalEndpointBit n F r a arity owner (tagBits n F r a arity owner x y)\n      (endpoints owner pair.1 pair.2).2=x (position n F r a arity owner pair.1) := by\n  simpa only [tagBits,ite_true,Bool.false_eq_true,ite_false] using\n    original_pair_bits n F r a arity owner q g (tagBits n F r a arity owner x y) pair hp\n\nend\nend RiemannGaussian.SemiprimeD1PacketAssignmentRows\n","RiemannGaussian.SemiprimeD1PacketCoefficientClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketArithmeticClock\n\n/-! # Actual packet mode coefficients and cached affine row acquisition\nAll same-bit checks and actual signed crossing-mode calls are charged. Numeric\nmode/tile caps describe acquired original catalogue fields, not supplied entry\nvalues or intermediate width/clock answers.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 150000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1PacketCoefficientClock\nopen SemiprimeD1JetAxes SemiprimeD1JetAffineCoefficient SemiprimeD1JetAffineCoefficientBounds\nopen SemiprimeD1PacketEntryBits SemiprimeD1PacketEntryInputs SemiprimeD1PacketArithmeticClock\n\n/-- Original physical index acquisition and both actual bit scans. -/\ndef sameBitClock (a : ℕ) : ℕ := 2*SemiprimeSourceHistogramPortKeys.encodeBudget (2^a)+8*a+9\n\n/-- Same-bit control is computed, never assumed as a branch oracle. -/\ntheorem sameBit_clock (a : ℕ) (i : Fin a) (x y : Fin (2^a)) :\n    (sameBit x.val y.val i.val).work ≤ sameBitClock a := by\n  have hx := SemiprimeSourceHistogramPortKeys.encodeKey_clock x.val (2^a) x.isLt.le\n  have hy := SemiprimeSourceHistogramPortKeys.encodeKey_clock y.val (2^a) y.isLt.le\n  have hl := SemiprimeD1ModeRoutingBits.readBit_work\n    (SemiprimeSourceHistogramPortKeys.encodeKey x.val).bits i.val\n  have hr := SemiprimeD1ModeRoutingBits.readBit_work\n    (SemiprimeSourceHistogramPortKeys.encodeKey y.val).bits i.val\n  change (SemiprimeSourceHistogramPortKeys.encodeKey x.val).clock+\n    (SemiprimeSourceHistogramPortKeys.encodeKey y.val).clock+_+_+5 ≤ _\n  unfold sameBitClock\n  omega\n\n/-- Mode budget is monotone in the actual finite original mode exponent. -/\ntheorem mode_order_mono (ctx : Context) (a b B : ℕ) (hb : b ≤ B) :\n    SemiprimeD1JetModeBitsBounds.modeBudget ctx ctx.precision (2^(a+1)*(a+1)) (2^(a+1)) b ≤\n      SemiprimeD1JetModeBitsBounds.modeBudget ctx ctx.precision (2^(a+1)*(a+1)) (2^(a+1)) B := by\n  unfold SemiprimeD1JetModeBitsBounds.modeBudget\n  gcongr\n\n/-- Whole crossing coefficient, including both zero and active physical branches. -/\ndef coefficientClock (ctx : Context) (a B T : ℕ) : ℕ :=\n  SemiprimeD1JetModeBitsBounds.modeBudget ctx ctx.precision (2^(a+1)*(a+1)) (2^(a+1)) B+\n    signClock ctx+sameBitClock a+T+2^a+2^a+10+ctx.rank+1\n\n/-- Every actual catalogue coefficient derives canonical current shape. -/\ntheorem coefficient_good (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (item : SemiprimeD1PacketModeMask.Item) : Good ctx (coefficient ctx z a i t row item).words := by\n  dsimp only [coefficient]\n  split\n  · exact signed_good ctx _ _ (SemiprimeD1JetModeBitsBounds.mode_good ctx _ _ _ _ _ _ _)\n  · exact zero_good ctx\n\n/-- Whole actual physical coefficient cost from original acquired input bounds. -/\ntheorem coefficient_clock (ctx : Context) (z : JetRun) (hz : Good ctx z.words) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (item : SemiprimeD1PacketModeMask.Item) (B T : ℕ)\n    (hb : item.mode.order ≤ B) (ht : item.tile ≤ T) :\n    (coefficient ctx z a i t row item).clock ≤ coefficientClock ctx a B T := by\n  let tile : Fin (2^a) := ⟨item.tile%2^a,Nat.mod_lt _ (by positivity)⟩\n  have htest := sameBit_clock a i row.slot tile\n  have hmode := SemiprimeD1JetModeBitsBounds.acquireOriginal_clock ctx (borrow z) a i.val\n    item.mode.order t row.slot tile ctx.precision le_rfl hz.1.le hz.2\n  have hmodeGood : Good ctx (SemiprimeD1JetModeBits.acquireOriginal ctx (borrow z) a i.val\n      item.mode.order t row.slot tile).words := SemiprimeD1JetModeBitsBounds.mode_good ctx _ _ _ _ _ _ _\n  have hsign := signed_clock ctx (!row.bit)\n    (SemiprimeD1JetModeBits.acquireOriginal ctx (borrow z) a i.val item.mode.order t row.slot tile) hmodeGood\n  have hbound := mode_order_mono ctx a _ B hb\n  change (SemiprimeD1JetModeBits.acquireOriginal ctx (borrow z) a i.val item.mode.order t row.slot tile).clock ≤\n    0+SemiprimeD1JetModeBitsBounds.modeBudget ctx ctx.precision (2^(a+1)*(a+1)) (2^(a+1)) item.mode.order at hmode\n  simp only [Nat.zero_add] at hmode\n  have hrow : row.slot.val ≤ 2^a := row.slot.isLt.le\n  dsimp only [coefficient]\n  split\n  · change (signed ctx (!row.bit)\n      (SemiprimeD1JetModeBits.acquireOriginal ctx (borrow z) a i.val item.mode.order t row.slot tile)).clock+\n      (sameBit row.slot.val tile.val i.val).work+item.tile+row.slot.val+2^a+10 ≤ _\n    unfold coefficientClock\n    omega\n  · change ctx.rank+1+(sameBit row.slot.val tile.val i.val).work+item.tile+row.slot.val+2^a+10 ≤ _\n    unfold coefficientClock\n    omega\n\n/-- Actual coefficient-vector list traversal, with every called coefficient paid. -/\ntheorem coefficients_clock (ctx : Context) (z : JetRun) (hz : Good ctx z.words) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (items : List SemiprimeD1PacketModeMask.Item) (B T : ℕ)\n    (hb : ∀item∈items,item.mode.order ≤ B) (ht : ∀item∈items,item.tile ≤ T) :\n    (coefficients ctx z a i t row items).work ≤ items.length*(coefficientClock ctx a B T+4)+1 := by\n  induction items with\n  | nil => simp only [coefficients,List.length_nil,Nat.zero_mul,Nat.zero_add,le_refl]\n  | cons item items ih =>\n    have hh := coefficient_clock ctx z hz a i t row item B T (hb _ List.mem_cons_self) (ht _ List.mem_cons_self)\n    have hh' := ih (fun x hx => hb x (List.mem_cons_of_mem _ hx)) (fun x hx => ht x (List.mem_cons_of_mem _ hx))\n    change (coefficient ctx z a i t row item).clock+(coefficients ctx z a i t row items).work+4 ≤ _\n    simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- Computed row recipe satisfies the actual physical coefficient interpreter's\nsource invariant, with no intermediate shape or fit advice. -/\ntheorem recipe_source (ctx : Context) (z : JetRun) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) :\n    Source ctx ctx.precision items.length (recipe ctx z a i t row columns items).value := by\n  have hb := rowBase_good ctx z a t row columns\n  refine ⟨hb.1.le,hb.2,?_,?_⟩\n  · change (coefficients ctx z a i t row items).value.length ≤ items.length\n    rw [SemiprimeD1PacketEntryValue.coefficients_value,List.length_map]\n  · intro v hv\n    change v ∈ (coefficients ctx z a i t row items).value at hv\n    rw [SemiprimeD1PacketEntryValue.coefficients_value] at hv\n    obtain ⟨item,_,rfl⟩ := List.mem_map.mp hv\n    have hh := coefficient_good ctx z a i t row item\n    exact ⟨hh.1.le,hh.2⟩\n\n/-- Full row acquisition budget, polynomial in the original catalogue and row columns. -/\ndef recipeClock (ctx : Context) (a C K B T : ℕ) : ℕ :=\n  rowBaseClock ctx a C+K*(coefficientClock ctx a B T+4)+6\n\n/-- Cached base and coefficient producers are both retained by the actual recipe. -/\ntheorem recipe_clock (ctx : Context) (z : JetRun) (hz : Good ctx z.words) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) (B T : ℕ)\n    (hb : ∀item∈items,item.mode.order ≤ B) (ht : ∀item∈items,item.tile ≤ T) :\n    (recipe ctx z a i t row columns items).work ≤ recipeClock ctx a columns.length items.length B T := by\n  have hbase := rowBase_clock ctx z hz a t row columns\n  have hcoeff := coefficients_clock ctx z hz a i t row items B T hb ht\n  change (rowBase ctx z a t row columns).clock+(coefficients ctx z a i t row items).work+5 ≤ _\n  unfold recipeClock\n  omega\n\n/-- All actual real rows are acquired once; no local truth table callback is supplied. -/\ntheorem recipes_clock (ctx : Context) (z : JetRun) (hz : Good ctx z.words) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (columns : List (Wire a))\n    (items : List SemiprimeD1PacketModeMask.Item) (rows : List (Wire a)) (B T : ℕ)\n    (hb : ∀item∈items,item.mode.order ≤ B) (ht : ∀item∈items,item.tile ≤ T) :\n    (recipes ctx z a i t columns items rows).work ≤\n      rows.length*(recipeClock ctx a columns.length items.length B T+4)+1 := by\n  induction rows with\n  | nil => simp only [recipes,List.length_nil,Nat.zero_mul,Nat.zero_add,le_refl]\n  | cons row rows ih =>\n    have hh := recipe_clock ctx z hz a i t row columns items B T hb ht\n    change (recipe ctx z a i t row columns items).work+(recipes ctx z a i t columns items rows).work+4 ≤ _\n    simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\nend RiemannGaussian.SemiprimeD1PacketCoefficientClock\n","RiemannGaussian.SemiprimeD1PacketPolynomialSupport":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketModeOriginal\nimport RiemannGaussian.SemiprimeD1PacketEntryComponents\n\n/-! # Actual acquired row polynomials use only the packet target modes\nThe support property is derived from the executed coefficient masks and actual\nrecipe list. No desired support or semantic coefficient-zero advice is supplied.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2800000\nnamespace RiemannGaussian.SemiprimeD1PacketPolynomialSupport\nopen scoped BigOperators\nopen SemiprimeD1SeparatedCoefficient SemiprimeD1PacketModeProjection\nopen SemiprimeD1PacketEntryBits SemiprimeD1PacketEntryValue SemiprimeD1PacketEntryInputs\nopen SemiprimeD1JetAxes SemiprimeD1JetInterpretation\nnoncomputable section\nvariable {V R : Type*} [CommRing R]\n\n/-- Zero coefficients use no mode. -/\ntheorem on_zero (S : Set V) : On S (0 : MvPolynomial V R) := by\n  intro e he\n  have hz : (0 : MvPolynomial V R).coeff e=0 := by simp\n  exact False.elim (he hz)\n\n/-- A literal base value uses no mode. -/\ntheorem on_constant (S : Set V) (c : R) : On S (MvPolynomial.C c) := by\n  intro e he v _\n  by_cases hz : e=0\n  · simp only [hz,Finsupp.zero_apply]\n  · exact False.elim (he (MvPolynomial.coeff_C_of_ne_zero hz c))\n\n/-- An acquired mode variable belongs to its actual designated family. -/\ntheorem on_variable (S : Set V) (v : V) (hv : v∈S) : On S (MvPolynomial.X v : MvPolynomial V R) := by\n  classical\n  intro e he w hw\n  have hz : Finsupp.single v 1=e := by\n    by_contra hn\n    simp only [MvPolynomial.coeff_X,hn,ite_false,ne_eq,not_true_eq_false] at he\n  rw [←hz]\n  have hne : v≠w := by intro h;exact hw (h ▸ hv)\n  simp only [Finsupp.single_apply,hne,ite_false]\n\n/-- Addition cannot introduce a mode absent from both actual summands. -/\ntheorem on_add (S : Set V) (P Q : MvPolynomial V R) (hp : On S P) (hq : On S Q) : On S (P+Q) := by\n  intro e he v hv\n  by_cases hP : P.coeff e=0\n  · have hQ : Q.coeff e≠0 := by\n      intro hz\n      apply he\n      simp only [AddMonoidAlgebra.coeff_add,Finsupp.add_apply,hP,hz,zero_add]\n    exact hq e hQ v hv\n  · exact hp e hP v hv\n\n/-- Literal list sums preserve support, retaining duplicates rather than deduplicating rows. -/\ntheorem on_list_sum (S : Set V) (ps : List (MvPolynomial V R)) (hp : ∀p∈ps,On S p) : On S ps.sum := by\n  induction ps with\n  | nil => exact on_zero S\n  | cons p ps ih =>\n    exact on_add S p ps.sum (hp p List.mem_cons_self) (ih (fun q hq => hp q (List.mem_cons_of_mem p hq)))\n\n/-- Literal list products preserve the exact repeated row family. -/\ntheorem on_list_prod (S : Set V) (ps : List (MvPolynomial V R)) (hp : ∀p∈ps,On S p) : On S ps.prod := by\n  induction ps with\n  | nil => exact on_one S\n  | cons p ps ih =>\n    exact on_mul S p ps.prod (hp p List.mem_cons_self) (ih (fun q hq => hp q (List.mem_cons_of_mem p hq)))\n\n/-- Actual zero coefficients outside a set imply support of the complete affine row. -/\ntheorem rowPolynomial_on (S : Set ℕ) (K : ℕ) (row : SemiprimeD1AffineCoefficient.Row R)\n    (hc : ∀ j, j < K → j ∉ S → row.coefficients.getD j 0 = 0) :\n    On S (SemiprimeD1AffineCoefficient.rowPolynomial K row) := by\n  unfold SemiprimeD1AffineCoefficient.rowPolynomial\n  apply on_add S _ _ (on_constant S row.base)\n  apply on_list_sum\n  intro p hp\n  obtain ⟨j,hj,rfl⟩ := List.mem_map.mp hp\n  by_cases hs : j∈S\n  · exact on_mul S _ _ (on_constant S _) (on_variable S j hs)\n  · have hz := hc j (List.mem_range.mp hj) hs\n    simpa only [hz,map_zero,zero_mul] using (on_zero (R:=R) S)\n\n/-- Executed packet masks really zero every coefficient outside the target family. -/\ntheorem coefficient_zero (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (item : SemiprimeD1PacketModeMask.Item) (hz : (item.inPacket && item.targetHere)=false) :\n    interpret ctx (coefficient ctx z a i t row item).words=0 := by\n  simp only [coefficient,hz,Bool.false_and,Bool.false_eq_true,ite_false]\n  exact SemiprimeD1JetAffineCoefficient.interpret_zero ctx\n\n/-- The actual acquired coefficient vector, not an advised semantic row, obeys its mask. -/\ntheorem recipe_coefficient_zero (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (row : Wire a)\n    (columns : List (Wire a)) (cache : SemiprimeD1PacketModeMask.Cache) (j : ℕ)\n    (hj : j<cache.items.length) (hn : j∉targetSet cache) :\n    (SemiprimeD1JetAffineCoefficient.rowValue ctx (recipe ctx z a i t row columns cache.items).value).coefficients.getD j 0=0 := by\n  have hf : (cache.items[j].inPacket && cache.items[j].targetHere)=false := by\n    apply Bool.eq_false_iff.mpr\n    intro he\n    apply hn\n    change targetEnabled cache.items j=true\n    simpa only [targetEnabled,List.getElem?_eq_getElem hj] using he\n  have hzero := coefficient_zero ctx z a i t row cache.items[j] hf\n  change ((coefficients ctx z a i t row cache.items).value.map (interpret ctx)).getD j 0=0\n  rw [coefficients_value,List.map_map]\n  rw [List.getD_eq_getElem _ _ (by simpa only [List.length_map] using hj),List.getElem_map]\n  exact hzero\n\n/-- The complete ACTUAL row polynomial has the support required by mode separation. -/\ntheorem packet_polynomial_on (ctx : Context) (z : SemiprimeD1JetAffineCoefficient.JetRun)\n    (a : ℕ) (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (columns rows : List (Wire a)) (cache : SemiprimeD1PacketModeMask.Cache) :\n    On (targetSet cache) (SemiprimeD1AffineCoefficient.polynomial cache.items.length\n      ((recipes ctx z a i t columns cache.items rows).value.map (SemiprimeD1JetAffineCoefficient.rowValue ctx))) := by\n  unfold SemiprimeD1AffineCoefficient.polynomial\n  apply on_list_prod\n  intro p hp\n  obtain ⟨row,hrow,rfl⟩ := List.mem_map.mp hp\n  apply rowPolynomial_on\n  intro j hj hn\n  rw [recipes_value,List.map_map] at hrow\n  obtain ⟨original,_,rfl⟩ := List.mem_map.mp hrow\n  exact recipe_coefficient_zero ctx z a i t original columns cache j hj hn\n\nend\nend RiemannGaussian.SemiprimeD1PacketPolynomialSupport\n","RiemannGaussian.SemiprimeD1PacketSourceClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketArithmeticClock\n\n/-! # Actual packet source-mode powers and ordered product clocks\nThe unchanged global beta is read by the executed finite scans. Its acquired\nnumeric cap bounds the actual power loops; no requested source value is given.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 140000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1PacketSourceClock\nopen SemiprimeD1JetAxes SemiprimeD1JetAffineCoefficient SemiprimeD1JetAffineCoefficientBounds\nopen SemiprimeD1PacketEntryBits SemiprimeD1PacketEntryInputs SemiprimeD1PacketArithmeticClock\n\n/-- A finite read of an acquired bounded exponent list is bounded, including default0. -/\ntheorem read_le (beta : List ℕ) (index B : ℕ) (hb : ∀b∈beta,b ≤ B) :\n    (SemiprimeD1AffineCoefficient.read 0 beta index).1 ≤ B := by\n  induction beta generalizing index with\n  | nil => exact Nat.zero_le _\n  | cons b beta ih =>\n    cases index with\n    | zero => exact hb _ List.mem_cons_self\n    | succ index => exact ih _ (fun x hx => hb _ (List.mem_cons_of_mem _ hx))\n\n/-- Whole actual finite multijet power loop. -/\ndef powerClock (ctx : Context) (B : ℕ) : ℕ := B*(mulClock ctx+3)+oneClock ctx\n\n/-- Actual power cost is monotone in its acquired exponent. -/\ntheorem power_clock (ctx : Context) (words : List (List Bool)) (hg : Good ctx words)\n    (b B : ℕ) (hb : b ≤ B) :\n    (SemiprimeD1JetPolynomialBits.power ctx words b).clock ≤ powerClock ctx B := by\n  have h := SemiprimeD1JetPolynomialBitsBounds.power_clock ctx words b ctx.precision le_rfl hg.1.le hg.2\n  have hm := Nat.mul_le_mul_right (mulClock ctx+3) hb\n  unfold powerClock\n  calc\n    _ ≤ b*(mulClock ctx+3)+9*ctx.precision+3*ctx.rank+8 := h\n    _ ≤ B*(mulClock ctx+3)+9*ctx.precision+3*ctx.rank+8 :=\n      Nat.add_le_add_right (Nat.add_le_add_right (Nat.add_le_add_right hm (9*ctx.precision)) (3*ctx.rank)) 8\n    _ = _ := by unfold oneClock;ring\n\n/-- Original index digits, literal scalar vector and actual finite power acquisition. -/\ndef sourceTermClock (ctx : Context) (a P : ℕ) : ℕ :=\n  10*ctx.precision+5+(3*ctx.precision+3*ctx.rank+4)+powerClock ctx P+\n    2^a+2^(a+1)+8+ctx.rank+1\n\n/-- Every source-column contribution derives current target shape and width. -/\ntheorem sourceTerm_good (ctx : Context) (a : ℕ) (i : Fin a)\n    (item : SemiprimeD1PacketModeMask.Item) (column : Wire a) :\n    Good ctx (sourceTerm ctx a i item column).words := by\n  dsimp only [sourceTerm]\n  split\n  · exact SemiprimeD1JetPolynomialBitsBounds.power_good _ _ _\n  · exact zero_good _\n\n/-- Every actually acquired source integer/power and literal zero branch is paid. -/\ntheorem sourceTerm_clock (ctx : Context) (a : ℕ) (i : Fin a)\n    (item : SemiprimeD1PacketModeMask.Item) (column : Wire a) (P : ℕ) (hp : item.mode.order ≤ P) :\n    (sourceTerm ctx a i item column).clock ≤ sourceTermClock ctx a P := by\n  let index := SemiprimeD1JetPolynomialBits.magnitude ctx.precision (column.slot.val/2^(i.val+1))\n  let scalar := SemiprimeD1JetPolynomialBits.scalar ctx index.bits\n  have hm := SemiprimeD1JetPolynomialBitsBounds.magnitude_clock ctx.precision (column.slot.val/2^(i.val+1))\n  have hw := SemiprimeD1JetPolynomialBitsBounds.magnitude_length ctx.precision (column.slot.val/2^(i.val+1))\n  have hs := SemiprimeD1JetPolynomialBitsBounds.scalar_clock ctx index.bits\n  have hg : Good ctx scalar.words :=\n    ⟨SemiprimeD1JetPolynomialBitsBounds.scalar_shape _ _,\n      SemiprimeD1JetPolynomialBitsBounds.scalar_bounded _ _ _ hw⟩\n  have hpower := power_clock ctx scalar.words hg _ P hp\n  have hslot : column.slot.val ≤ 2^a := column.slot.isLt.le\n  have htiles : 2^(i.val+1) ≤ (2:ℕ)^(a+1) := Nat.pow_le_pow_right (by decide) (Nat.add_le_add_right i.isLt.le 1)\n  have hw' : index.bits.length ≤ ctx.precision := hw\n  have hscalar : scalar.clock ≤ 3*ctx.precision+3*ctx.rank+4 := by\n    rw [SemiprimeD1JetPolynomialBitsBounds.scalar_clock]\n    exact Nat.add_le_add_right (Nat.add_le_add_right (Nat.mul_le_mul_left 3 hw') (3*ctx.rank)) 4\n  dsimp only [sourceTerm]\n  split\n  · change index.clock+scalar.clock+(SemiprimeD1JetPolynomialBits.power ctx scalar.words item.mode.order).clock+\n      column.slot.val+2^(i.val+1)+8 ≤ _\n    have hi : index.clock=10*ctx.precision+5 := hm\n    unfold sourceTermClock\n    omega\n  · change ctx.rank+1+column.slot.val+2^(i.val+1)+5 ≤ _\n    unfold sourceTermClock\n    omega\n\n/-- Actual source-column sum and unchanged global-beta finite power. -/\ndef sourceFactorClock (ctx : Context) (a C P B T : ℕ) : ℕ :=\n  3*T+1+C*(sourceTermClock ctx a P+addClock ctx+3)+ctx.rank+1+\n    powerClock ctx B+6+oneClock ctx+4\n\n/-- Both actual source-factor branches have derived current shape/width. -/\ntheorem sourceFactor_good (ctx : Context) (a : ℕ) (i : Fin a) (columns : List (Wire a))\n    (beta : List ℕ) (index : ℕ) (item : SemiprimeD1PacketModeMask.Item) :\n    Good ctx (sourceFactor ctx a i columns beta index item).words := by\n  dsimp only [sourceFactor]\n  split\n  · exact SemiprimeD1JetPolynomialBitsBounds.power_good _ _ _\n  · exact one_good _\n\n/-- Physical source-factor acquisition reads the ORIGINAL global exponent and\nretains every actual contributing column. -/\ntheorem sourceFactor_clock (ctx : Context) (a : ℕ) (i : Fin a) (columns : List (Wire a))\n    (beta : List ℕ) (index : ℕ) (item : SemiprimeD1PacketModeMask.Item) (P B : ℕ)\n    (hp : item.mode.order ≤ P) (hb : ∀b∈beta,b ≤ B) :\n    (sourceFactor ctx a i columns beta index item).clock ≤\n      sourceFactorClock ctx a columns.length P B beta.length := by\n  let base := sumRuns ctx (columns.map (sourceTerm ctx a i item))\n  have hread := SemiprimeD1AffineCoefficientBounds.read_work 0 beta index\n  have hexponent := read_le beta index B hb\n  have hsum := sumRuns_clock ctx (columns.map (sourceTerm ctx a i item)) (by\n    intro x hx\n    obtain ⟨column,_,rfl⟩ := List.mem_map.mp hx\n    exact sourceTerm_good ctx a i item column)\n  have hcallbacks : ((columns.map (sourceTerm ctx a i item)).map (fun x => x.clock)).sum ≤\n      columns.length*sourceTermClock ctx a P := by\n    clear hsum base\n    induction columns with\n    | nil => simp\n    | cons c cs ih =>\n      have hh := sourceTerm_clock ctx a i item c P hp\n      simp only [List.map_cons,List.sum_cons,List.length_cons,Nat.add_mul,Nat.one_mul]\n      omega\n  simp only [List.length_map] at hsum\n  have hbase : base.clock ≤ columns.length*(sourceTermClock ctx a P+addClock ctx+3)+ctx.rank+1 := by\n    have hh := Nat.add_le_add_right (Nat.add_le_add_right hcallbacks\n      (columns.length*(addBudget ctx ctx.precision+3))) (ctx.rank+1)\n    exact hsum.trans (by dsimp only [addClock];nlinarith)\n  have hpower := power_clock ctx base.words (sumRuns_good ctx _)\n    (SemiprimeD1AffineCoefficient.read 0 beta index).1 B hexponent\n  have hu := SemiprimeD1JetPolynomialBitsBounds.one_clock ctx\n  dsimp only [sourceFactor]\n  split\n  · change (SemiprimeD1AffineCoefficient.read 0 beta index).2+base.clock+\n      (SemiprimeD1JetPolynomialBits.power ctx base.words (SemiprimeD1AffineCoefficient.read 0 beta index).1).clock+6 ≤ _\n    unfold sourceFactorClock\n    omega\n  · change (one ctx).clock+4 ≤ _\n    unfold sourceFactorClock oneClock\n    omega\n\n/-- Every actual ordered source-product prefix has intrinsic target shape/width. -/\ntheorem sourceProduct_good (ctx : Context) (a : ℕ) (i : Fin a) (columns : List (Wire a))\n    (beta : List ℕ) (items : List SemiprimeD1PacketModeMask.Item) (index : ℕ) :\n    Good ctx (sourceProduct ctx a i columns beta items index).words := by\n  cases items with\n  | nil => exact one_good _\n  | cons item items => exact multiply_good _ _ _\n\n/-- All physical source factors and multiplication prefixes are retained. -/\ntheorem sourceProduct_clock (ctx : Context) (a : ℕ) (i : Fin a) (columns : List (Wire a))\n    (beta : List ℕ) (items : List SemiprimeD1PacketModeMask.Item) (index P B : ℕ)\n    (hp : ∀item∈items,item.mode.order ≤ P) (hb : ∀b∈beta,b ≤ B) :\n    (sourceProduct ctx a i columns beta items index).clock ≤\n      items.length*(sourceFactorClock ctx a columns.length P B beta.length+mulClock ctx+3)+oneClock ctx := by\n  induction items generalizing index with\n  | nil =>\n    simp only [sourceProduct,List.length_nil,Nat.zero_mul,Nat.zero_add]\n    exact SemiprimeD1JetPolynomialBitsBounds.one_clock ctx\n  | cons item items ih =>\n    have hh := sourceFactor_clock ctx a i columns beta index item P B (hp _ List.mem_cons_self) hb\n    have ht := ih (index+1) (fun x hx => hp x (List.mem_cons_of_mem _ hx))\n    have hm := multiply_clock ctx (sourceFactor ctx a i columns beta index item)\n      (sourceProduct ctx a i columns beta items (index+1))\n      (sourceFactor_good _ _ _ _ _ _ _) (sourceProduct_good _ _ _ _ _ _ _)\n    change (multiply ctx (sourceFactor ctx a i columns beta index item)\n      (sourceProduct ctx a i columns beta items (index+1))).clock ≤ _\n    simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\nend RiemannGaussian.SemiprimeD1PacketSourceClock\n","RiemannGaussian.SemiprimeD1ParentTagOrder":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ChildNetwork\nimport RiemannGaussian.SemiprimeD1ChildAssignmentEndpoint\n\n/-! # Exact original-tag order of actual cached parent tables\nThe original two-sided factor-major incidence stream is filtered by the actual\nold vertex. Its global occurrence identifiers agree in order with the literal\nparent ports; parallel occurrences and isolated vertices are retained.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 100000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1ParentTagOrder\nopen SemiprimeD1TensorNetwork\nopen SemiprimeD1ChildPortBijection (linkVertex)\n\n/-- Literal original endpoint tags at one unified old vertex. -/\ndef oldTags {n : ℕ} (rs : Rows n) (v : Fin (n+rs.length)) :=\n  ((incidences rs).product [true,false]).filter\n    (fun tag => decide (linkVertex (owner rs) tag=v))\n\n/-- The original occurrence identifier ignores only the distinct endpoint side. -/\ndef tagEdge {n : ℕ} (rs : Rows n) (tag : Incidence rs × Bool) : ℕ := edgeID rs tag.1\n\n/-- True endpoints belong precisely to their original left owner. -/\ntheorem link_left {n F : ℕ} {arity : Fin F→ℕ}\n    (own : ((e : Fin F)×Fin (arity e))→Fin n)\n    (i : (e : Fin F)×Fin (arity e)) (v : Fin n) :\n    linkVertex own (i,true)=Fin.castAdd F v ↔ own i=v := by\n  simp only [linkVertex,ite_true,Fin.ext_iff,Fin.val_castAdd]\n\n/-- False endpoints never belong to a left-namespace vertex. -/\ntheorem link_false_ne_left {n F : ℕ} {arity : Fin F→ℕ}\n    (own : ((e : Fin F)×Fin (arity e))→Fin n)\n    (i : (e : Fin F)×Fin (arity e)) (v : Fin n) :\n    linkVertex own (i,false)≠Fin.castAdd F v := by\n  intro h\n  have hv:=congrArg Fin.val h\n  change n+i.1.val=v.val at hv\n  omega\n\n/-- False endpoints belong precisely to their original right factor. -/\ntheorem link_right {n F : ℕ} {arity : Fin F→ℕ}\n    (own : ((e : Fin F)×Fin (arity e))→Fin n)\n    (i : (e : Fin F)×Fin (arity e)) (e : Fin F) :\n    linkVertex own (i,false)=Fin.natAdd n e ↔ i.1=e := by\n  simp only [linkVertex,Bool.false_eq_true,ite_false,Fin.ext_iff,Fin.val_natAdd]\n  omega\n\n/-- True endpoints never belong to a right-namespace vertex. -/\ntheorem link_true_ne_right {n F : ℕ} {arity : Fin F→ℕ}\n    (own : ((e : Fin F)×Fin (arity e))→Fin n)\n    (i : (e : Fin F)×Fin (arity e)) (e : Fin F) :\n    linkVertex own (i,true)≠Fin.natAdd n e := by\n  intro h\n  have hv:=congrArg Fin.val h\n  change (own i).val=n+e.val at hv\n  have hi:=(own i).isLt\n  omega\n\n/-- Filtering the literal two-sided stream by a left vertex preserves incidence order. -/\ntheorem left_filter {n F : ℕ} {arity : Fin F→ℕ}\n    (own : ((e : Fin F)×Fin (arity e))→Fin n)\n    (xs : List ((e : Fin F)×Fin (arity e))) (v : Fin n) :\n    ((xs.product [true,false]).filter\n      (fun t => decide (linkVertex own t=Fin.castAdd F v))).map Prod.fst=\n        xs.filter (fun i => decide (own i=v)) := by\n  induction xs with\n  | nil => rfl\n  | cons i xs ih =>\n    change (((i,true)::(i,false)::xs.product [true,false]).filter\n      (fun t => decide (linkVertex own t=Fin.castAdd F v))).map Prod.fst=_\n    by_cases h:own i=v <;> simp [link_left,link_false_ne_left,h,ih]\n\n/-- Filtering the literal two-sided stream by a right vertex preserves incidence order. -/\ntheorem right_filter {n F : ℕ} {arity : Fin F→ℕ}\n    (own : ((e : Fin F)×Fin (arity e))→Fin n)\n    (xs : List ((e : Fin F)×Fin (arity e))) (e : Fin F) :\n    ((xs.product [true,false]).filter\n      (fun t => decide (linkVertex own t=Fin.natAdd n e))).map Prod.fst=\n        xs.filter (fun i => decide (i.1=e)) := by\n  induction xs with\n  | nil => rfl\n  | cons i xs ih =>\n    change (((i,true)::(i,false)::xs.product [true,false]).filter\n      (fun t => decide (linkVertex own t=Fin.natAdd n e))).map Prod.fst=_\n    by_cases h:i.1=e <;> simp [link_right,link_true_ne_right,h,ih]\n\n/-- Exact ordered left ports, not merely cardinal or permutation agreement. -/\ntheorem oldTags_left {n : ℕ} (rs : Rows n) (v : Fin n) :\n    (oldTags rs (Fin.castAdd rs.length v)).map (tagEdge rs)=leftPorts rs v := by\n  change (oldTags rs (Fin.castAdd rs.length v)).map (fun t => edgeID rs t.1)=_\n  simpa only [oldTags,List.map_map,Function.comp_def,leftPorts] using\n    congrArg (List.map (edgeID rs)) (left_filter (owner rs) (incidences rs) v)\n\n/-- Exact ordered right ports, retaining parallel occurrences distinctly. -/\ntheorem oldTags_right {n : ℕ} (rs : Rows n) (e : Fin rs.length) :\n    (oldTags rs (Fin.natAdd n e)).map (tagEdge rs)=rightPorts rs e := by\n  change (oldTags rs (Fin.natAdd n e)).map (fun t => edgeID rs t.1)=_\n  simpa only [oldTags,List.map_map,Function.comp_def,rightPorts] using\n    congrArg (List.map (edgeID rs)) (right_filter (owner rs) (incidences rs) e)\n\n/-- Actual well-formed parent cache agrees with the original tag stream in exact order. -/\ntheorem oldTags_parent (net : Network) (hw : WellFormed net)\n    (v : Fin (net.leftCount+net.rows.length)) :\n    (oldTags net.rows v).map (tagEdge net.rows)=\n      (SemiprimeD1ChildNetwork.parentVertex net v).ports := by\n  refine Fin.addCases (fun u => ?_) (fun e => ?_) v\n  · rw [oldTags_left]\n    change leftPorts net.rows u=(net.left.toList++net.right.toList)[u.val].ports\n    rw [List.getElem_append_left (by simpa only [Vector.length_toList] using u.isLt),Vector.getElem_toList]\n    exact (hw.1 u).symm\n  · rw [oldTags_right]\n    change rightPorts net.rows e=(net.left.toList++net.right.toList)[net.leftCount+e.val].ports\n    rw [List.getElem_append_right (by simp only [Vector.length_toList];omega)]\n    simp only [Vector.length_toList,Nat.add_sub_cancel_left,Vector.getElem_toList]\n    exact (hw.2 e).symm\n/-- Fin-indexed reads enumerate an actual list in its literal order. -/\ntheorem map_fin_reads {A : Type} (xs : List A) :\n    (List.finRange xs.length).map (fun j => xs[j.val])=xs := by\n  simp only [List.finRange,List.map_ofFn]\n  exact List.ofFn_getElem\n\n/-- Actual factor-major incidence owners are exactly the flattened cached rows. -/\ntheorem incidence_owners {n : ℕ} (rs : Rows n) :\n    (incidences rs).map (owner rs)=rs.flatten := by\n  simp only [incidences,SemiprimeFiniteEnumerations.indexedIncidences,\n    SemiprimeFiniteEnumerations.sigma,SemiprimeFiniteEnumerations.fin,List.map_flatMap,List.map_map,\n    Function.comp_def]\n  have h (e : Fin rs.length) :\n      ((List.finRange (arity rs e)).map (fun j => owner rs ⟨e,j⟩))=rs[e.val] :=\n    map_fin_reads _\n  simp_rw [h]\n  rw [List.flatMap_def]\n  rw [map_fin_reads]\n\n/-- Canonical left port counts are actual flattened owner-fibre counts. -/\ntheorem leftPorts_length {n : ℕ} (rs : Rows n) (v : Fin n) :\n    (leftPorts rs v).length=(rs.flatten.filter (fun u => decide (u=v))).length := by\n  have h:=congrArg (fun xs : List (Fin n) => (xs.filter (fun u => decide (u=v))).length)\n    (incidence_owners rs)\n  simpa only [leftPorts,List.length_map,List.filter_map,Function.comp_def] using h\n\n/-- Actual original-input old-table order equals the literal two-sided row stream. -/\ntheorem acquired_old (net : Network) (r a : ℕ) (q : Fin a) (g : Fin r)\n    (v : Fin (net.leftCount+net.rows.length)) :\n    (SemiprimeD1ChildTableOrder.acquire (owner net.rows)\n      (SemiprimeD1ChildPortPullback.acquire net.leftCount net.rows.length r a\n        (arity net.rows) (owner net.rows) q g) v).old=oldTags net.rows v := by\n  change (((SemiprimeD1PacketReplayOriginal.acquire net.leftCount net.rows.length r a\n    (arity net.rows) (owner net.rows)).padding.source.selection.cache.data.metadata.incidences).product\n      [true,false] |>.filter (fun t => decide (linkVertex (owner net.rows) t=v)))=_\n  rw [SemiprimeD1ChildGraphSemantics.original_ports,\n    SemiprimeD1TensorNetworkLayout.original_ports]\n  rfl\n\n/-- Actual old-table tags read exactly the well-formed literal parent port ordering. -/\ntheorem acquired_old_parent (net : Network) (hw : WellFormed net) (r a : ℕ)\n    (q : Fin a) (g : Fin r) (v : Fin (net.leftCount+net.rows.length)) :\n    ((SemiprimeD1ChildTableOrder.acquire (owner net.rows)\n      (SemiprimeD1ChildPortPullback.acquire net.leftCount net.rows.length r a\n        (arity net.rows) (owner net.rows) q g) v).old).map (tagEdge net.rows)=\n      (SemiprimeD1ChildNetwork.parentVertex net v).ports := by\n  rw [acquired_old]\n  exact oldTags_parent net hw v\n\n/-- No degree advice is needed to align the actual acquired old table. -/\ntheorem acquired_old_length (net : Network) (hw : WellFormed net) (r a : ℕ)\n    (q : Fin a) (g : Fin r) (v : Fin (net.leftCount+net.rows.length)) :\n    (SemiprimeD1ChildTableOrder.acquire (owner net.rows)\n      (SemiprimeD1ChildPortPullback.acquire net.leftCount net.rows.length r a\n        (arity net.rows) (owner net.rows) q g) v).old.length=\n      (SemiprimeD1ChildNetwork.parentVertex net v).ports.length := by\n  have h:=congrArg List.length (acquired_old_parent net hw r a q g v)\n  simpa only [List.length_map] using h\nend RiemannGaussian.SemiprimeD1ParentTagOrder\n","RiemannGaussian.SemiprimeD1PortScopeEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortScopeRecords\n/-! # Literal original port/ID stream specification\nAll list constructors here are proof specifications. The fixed physical\nmachine parses the actual retained tapes and never consumes these lists as\nan advised enumeration or output answer.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1PortScopeEncoding\nopen SemiprimeSourceHistogramKeyBits (frame frame_length)\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeMacroGraph\n/-- The existing eight actually serialized original port fields. -/\nabbrev Port := Fin 8→List Bool\n/-- Literal eight-field input record, preserving empty first ordinal zero. -/\ndef portFrame (w:Port) (tail:List Bool) : List Bool :=\n  frame (w 0) (frame (w 1) (frame (w 2) (frame (w 3)\n    (frame (w 4) (frame (w 5) (frame (w 6) (frame (w 7) tail)))))))\n/-- Literal original port tape, without any extra record marker. -/\ndef portTape (ports:List Port) (tail:List Bool) : List Bool := ports.foldr portFrame tail\n/-- Actual scope ID precedes every unchanged original port field. -/\ndef scopeFrame (w:Port) (id tail:List Bool) : List Bool := frame id (portFrame w tail)\n/-- Exact physical cache after reading the eight port fields and one actual ID. -/\ndef cached (w:Port) (id:List Bool) (j:Fin 9) : List Bool :=\n  if h:j.val<8 then w ⟨j.val,h⟩ else id\n/-- The ID field in the real finite cache is exactly the parsed physical word. -/\ntheorem cached_id (w:Port) (id:List Bool) : cached w id 8=id := rfl\n/-- Every original port field remains byte-for-byte in its old cache position. -/\ntheorem cached_port (w:Port) (id:List Bool) (j:Fin 8) :\n    cached w id ⟨j.val,by omega⟩=w j := by simp [cached,j.isLt]\n/-- Exact zipped output, only asserted for equally long actual source streams. -/\ndef output : List Port→List (List Bool)→List Bool→List Bool\n  | w::ws,id::ids,tail => scopeFrame w id (output ws ids tail)\n  | _,_,tail => tail\n/-- The actual eight-field byte mass. -/\ndef portMass (w:Port) : ℕ :=\n  (w 0).length+(w 1).length+(w 2).length+(w 3).length+\n    (w 4).length+(w 5).length+(w 6).length+(w 7).length\n/-- Exact input bytes, including all eight physical terminators. -/\ntheorem portFrame_length (w:Port) (tail:List Bool) :\n    (portFrame w tail).length=2*portMass w+tail.length+8 := by\n  unfold portFrame portMass\n  simp only [frame_length]\n  omega\n/-- Appended port suffixes are preserved literally. -/\ntheorem portFrame_append (w:Port) (tail:List Bool) : portFrame w tail=portFrame w []++tail := by\n  unfold portFrame\n  rw [SemiprimeD1StackEdgeCatalogueEmit.frame_append (w 7) tail,\n    SemiprimeD1StackEdgeCatalogueEmit.frame_tail (w 6),SemiprimeD1StackEdgeCatalogueEmit.frame_tail (w 5),\n    SemiprimeD1StackEdgeCatalogueEmit.frame_tail (w 4),SemiprimeD1StackEdgeCatalogueEmit.frame_tail (w 3),\n    SemiprimeD1StackEdgeCatalogueEmit.frame_tail (w 2),SemiprimeD1StackEdgeCatalogueEmit.frame_tail (w 1),\n    SemiprimeD1StackEdgeCatalogueEmit.frame_tail (w 0)]\n/-- Scope-record framing preserves every actual tail bit. -/\ntheorem scopeFrame_append (w:Port) (id tail:List Bool) : scopeFrame w id tail=scopeFrame w id []++tail := by\n  unfold scopeFrame\n  rw [portFrame_append,SemiprimeD1StackEdgeCatalogueEmit.frame_tail]\n/-- Source tape concatenation is exactly list concatenation, including duplicates. -/\ntheorem portTape_append (xs ys:List Port) (tail:List Bool) :\n    portTape (xs++ys) tail=portTape xs (portTape ys tail) := by\n  simp only [portTape,List.foldr_append]\n/-- Literal fields physically emitted by the frozen original port loop. -/\ndef fields (words:SemiprimeD1EdgeCatalogueEncoding.Record) (n f slot:ℕ) : Port :=\n  SemiprimeD1StackPortCatalogueEmit.sourceField words (unary slot) (unary f) (unary n)\n/-- Existing original emission and the eight-field input format are identical. -/\ntheorem fields_frame (words:SemiprimeD1EdgeCatalogueEncoding.Record) (n f slot:ℕ) (tail:List Bool) :\n    portFrame (fields words n f slot) tail=\n      SemiprimeD1StackPortCatalogueEmit.record8 words (unary slot) (unary f) (unary n) tail := rfl\n/-- Actual local-slot/occurrence order, as mathematical records only. -/\ndef localPorts (words:SemiprimeD1EdgeCatalogueEncoding.Record) : ℕ→ℕ→ℕ→ℕ→List Port\n  | 0,_,_,_ => []\n  | fuel+1,n,f,slot => fields words n f slot::localPorts words fuel (n+1) f (slot+1)\n/-- Exact source occurrence count at every local-loop prefix. -/\ntheorem localPorts_length (words:SemiprimeD1EdgeCatalogueEncoding.Record) (fuel n f slot:ℕ) :\n    (localPorts words fuel n f slot).length=fuel := by\n  induction fuel generalizing n slot with\n  | zero => rfl\n  | succ fuel ih => simp only [localPorts,List.length_cons,ih]\n/-- The mathematical record list is the SAME actual old emitted tape, without an ordering assumption. -/\ntheorem localPorts_tape (words:SemiprimeD1EdgeCatalogueEncoding.Record) (fuel n f slot:ℕ) (tail:List Bool) :\n    portTape (localPorts words fuel n f slot) tail=\n      SemiprimeD1StackPortCatalogueLoop.records words fuel n f slot tail := by\n  induction fuel generalizing n slot with\n  | zero => rfl\n  | succ fuel ih =>\n    change portFrame (fields words n f slot) (portTape (localPorts words fuel (n+1) f (slot+1)) tail)=_\n    rw [ih,fields_frame]\n    rfl\n/-- Exact factor-major original port list, retaining zero-arity factors in its factor ordinal. -/\ndef ports {r t digits:ℕ} : List (SubdividedVertex r t digits)→ℕ→ℕ→List Port\n  | [],_,_ => []\n  | v::vs,f,n => localPorts (SemiprimeD1EdgeCatalogueEncoding.vertex v) (subdividedArity v) n f 0++\n      ports vs (f+1) (n+subdividedArity v)\n/-- Every actual original port occurs once in this exact ordered specification. -/\ntheorem ports_length {r t digits:ℕ} (vs:List (SubdividedVertex r t digits)) (f n:ℕ) :\n    (ports vs f n).length=SemiprimeD1StackPortCatalogueTransduction.count vs := by\n  induction vs generalizing f n with\n  | nil => rfl\n  | cons v vs ih => simp only [ports,List.length_append,localPorts_length,ih,\n      SemiprimeD1StackPortCatalogueTransduction.count,List.map_cons,List.sum_cons]\n/-- Full source tape is exactly the already-proved original factor-major physical output. -/\ntheorem ports_tape {r t digits:ℕ} (vs:List (SubdividedVertex r t digits)) (f n:ℕ) (tail:List Bool) :\n    portTape (ports vs f n) tail=SemiprimeD1StackPortCatalogueTransduction.output vs f n tail := by\n  induction vs generalizing f n with\n  | nil => rfl\n  | cons v vs ih => rw [ports,portTape_append,ih,localPorts_tape];rfl\nend RiemannGaussian.SemiprimeD1PortScopeEncoding\n","RiemannGaussian.SemiprimeD1RadixOperandBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeBitFermatArithmetic\n\n/-! # Physical radix assembly of the original operand digits\nThe actual output is assembled by Boolean shifts and ripple additions. Natural\nvalues and radix powers occur only in the correctness specification. The radix\nis a physical offset template; each shift traverses and charges that template.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 300000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1RadixOperandBits\nopen SemiprimeBitArithmetic SemiprimeBitFermatArithmetic\n\n/-- Actual assembled operand and its full physical shift/add report. -/\nstructure Run where\n  /-- Literal little-endian output bits. -/\n  bits : List Bool\n  /-- Every shift-template read/copy, ripple addition and recursion tag. -/\n  clock : ℕ\n\n/-- Little-endian Horner assembly from original physical digit words. -/\ndef run (radix : List Bool) : List (List Bool) → Run\n  | [] => ⟨[],1⟩\n  | digit::digits =>\n    let tail := run radix digits\n    let shifted := shiftTemplateBits radix tail.bits\n    let added := addBits digit shifted.bits false\n    ⟨added.bits,tail.clock+bitCost shifted+bitCost added+7⟩\n\n/-- Proof-only mathematical radix value of a literal list of digit words. -/\ndef value (base : ℕ) : List (List Bool) → ℕ\n  | [] => 0\n  | digit::digits => bitValue digit+base*value base digits\n\n/-- No natural multiplication computes the runtime operand; the actual Boolean\nresult has exactly the original radix value. -/\ntheorem run_value (radix : List Bool) (digits : List (List Bool)) :\n    bitValue (run radix digits).bits=value (2^radix.length) digits := by\n  induction digits with\n  | nil => rfl\n  | cons digit digits ih =>\n    change bitValue (addBits digit (shiftTemplateBits radix (run radix digits).bits).bits false).bits = _\n    rw [addBits_correct,(shiftTemplateBits_exact radix (run radix digits).bits).1,ih]\n    simp only [bitNat,Bool.false_eq_true,ite_false,Nat.add_zero,value]\n\n/-- The physical output remains polynomial in supplied digit count and widths,\nincluding carries and arbitrary zero padding. -/\ntheorem run_width (radix : List Bool) (digits : List (List Bool)) (W : ℕ)\n    (hw : ∀ digit ∈ digits,digit.length ≤ W) :\n    (run radix digits).bits.length ≤ digits.length*(radix.length+W+1) := by\n  induction digits with\n  | nil => simp only [run,List.length_nil,Nat.zero_mul,le_refl]\n  | cons digit digits ih =>\n    have hd := hw digit List.mem_cons_self\n    have ht := ih (fun row hr => hw row (List.mem_cons_of_mem digit hr))\n    have hs := (shiftTemplateBits_exact radix (run radix digits).bits).2.1\n    have ha := (addBits_counts digit (shiftTemplateBits radix (run radix digits).bits).bits false).2.2.2.2\n    change (addBits digit (shiftTemplateBits radix (run radix digits).bits).bits false).bits.length ≤ _\n    simp only [List.length_cons]\n    have hm : max digit.length (shiftTemplateBits radix (run radix digits).bits).bits.length ≤\n        radix.length+W+digits.length*(radix.length+W+1) := by omega\n    nlinarith\n\n/-- Complete shift/add clock is one fixed polynomial in the literal original\ndigit widths and count, without an operand-value or cost advice premise. -/\ntheorem run_clock (radix : List Bool) (digits : List (List Bool)) (W : ℕ)\n    (hw : ∀ digit ∈ digits,digit.length ≤ W) :\n    (run radix digits).clock ≤ 20*(digits.length+1)^2*(radix.length+W+1) := by\n  induction digits with\n  | nil => simp only [run,List.length_nil];nlinarith\n  | cons digit digits ih =>\n    have hd := hw digit List.mem_cons_self\n    have htail := fun row hr => hw row (List.mem_cons_of_mem digit hr)\n    have ht := ih htail\n    have hwidth := run_width radix digits W htail\n    have hs := shiftTemplateBits_exact radix (run radix digits).bits\n    have ha := addBits_cost digit (shiftTemplateBits radix (run radix digits).bits).bits false\n    have hm : max digit.length (shiftTemplateBits radix (run radix digits).bits).bits.length ≤\n        (digits.length+1)*(radix.length+W+1) := by\n      apply max_le\n      · nlinarith\n      · rw [hs.2.1]\n        nlinarith\n    change (run radix digits).clock+bitCost (shiftTemplateBits radix (run radix digits).bits)+\n      bitCost (addBits digit (shiftTemplateBits radix (run radix digits).bits).bits false)+7 ≤ _\n    simp only [List.length_cons]\n    nlinarith\n\n/-- Reindexing the proof-only Horner value yields precisely the public decoder's\nfinite original radix sum. Runtime still uses only the Boolean recursion above. -/\ntheorem value_range (base n : ℕ) (digit : ℕ → List Bool) :\n    value base ((List.range n).map digit) =\n      ∑ i ∈ Finset.range n,bitValue (digit i)*base^i := by\n  induction n generalizing digit with\n  | zero => simp only [List.range_zero,List.map_nil,value,Finset.sum_range_zero]\n  | succ n ih =>\n    rw [List.range_succ_eq_map,List.map_cons,List.map_map,value,ih]\n    rw [Finset.sum_range_succ']\n    simp only [Function.comp_def,Nat.succ_eq_add_one,pow_zero,Nat.mul_one,pow_succ]\n    rw [Finset.mul_sum]\n    have he : (∑i∈Finset.range n,base*bitValue (digit (i+1))*base^i)=\n        ∑i∈Finset.range n,bitValue (digit (i+1))*(base^i*base) := by\n      apply Finset.sum_congr rfl\n      intro i _\n      ring\n    simp_rw [←mul_assoc]\n    rw [he]\n    simp only [mul_assoc]\n    exact Nat.add_comm _ _\n\nend RiemannGaussian.SemiprimeD1RadixOperandBits\n","RiemannGaussian.SemiprimeD1RecoveryGridBitsBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecoveryGridBits\n\n/-! # Actual physical grid acquisition clocks\nEvery rational arithmetic stage invokes the Boolean/GCD/division primitive.\nNative typed input/index/valuation stages are explicitly retained separately.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1RecoveryGridBitsBounds\nopen SemiprimeRationalBits SemiprimeJetBits SemiprimeBitArithmetic\nopen SemiprimeD1RecoveryGridBits SemiprimeD1RecoveryWeightRun SemiprimeD1RecoveryScalarRun\nopen SemiprimeD1RecoveryPowerBits SemiprimeSourceMemoryBits\nopen SemiprimeD1WireKernelOriginal SemiprimeD1TaperedLoss\n\n/-- Actual physical grid traversal cost: no supplied arithmetic-operation budget. -/\ntheorem loop_clock (template : List Bool) (a h u t : ℕ) (g : Geometry)\n    (center alpha node : RationalWord) (qs : List ℕ)\n    (hW : a+2 ≤ template.length)\n    (hc : Width center template.length) (ha : Width alpha template.length) (hn : Width node template.length) :\n    (loop template a h u t g center alpha node qs).clock ≤ qs.length*frameBudget template.length (h*u)+4 := by\n  have ht : 0 < template.length := by omega\n  induction qs with\n  | nil => simp [loop]\n  | cons q qs ih =>\n    by_cases hs : q=g.center.natAbs ∨ q=t\n    · simp only [loop,hs,ite_true,List.length_cons,Nat.add_mul,Nat.one_mul]\n      have hp : 4 ≤ frameBudget template.length (h*u) := by\n        unfold frameBudget\n        have ha : 8 ≤ 2*(h*u)+8 := by omega\n        have hb : 1 ≤ 20000*(template.length+1)^3+8*template.length+50 := by omega\n        have hh:=Nat.mul_le_mul ha hb\n        norm_num only at hh\n        omega\n      omega\n    · let tail:=loop template a h u t g center alpha node qs\n      let m:=multiplicityRun g h u q\n      let negative:=executeOperation .neg (index a q).word (index a q).word template\n      let nb:=executeOperation .add center negative.word template\n      let db:=executeOperation .add node negative.word template\n      let np:=power template nb.word m.value\n      let dp:=power template db.word m.value\n      let inv:=executeOperation .inv db.word db.word template\n      let slope:=executeOperation .mul alpha inv.word template\n      let repeated:=copies slope.word m.value\n      let numerator:=executeOperation .mul np.word tail.numerator template\n      let denominator:=executeOperation .mul dp.word tail.denominator template\n      have qw:=index_width a q template.length hW\n      have nw:=operation_width .neg (index a q).word (index a q).word template\n      have nbw:=operation_width .add center negative.word template\n      have dbw:=operation_width .add node negative.word template\n      have npw:=power_width template nb.word m.value ht\n      have dpw:=power_width template db.word m.value ht\n      have iw:=operation_width .inv db.word db.word template\n      have sw:=operation_width .mul alpha inv.word template\n      have tw:=loop_width template a h u t g center alpha node qs ht\n      have cn:=executeOperation_cost .neg (index a q).word (index a q).word template qw qw le_rfl\n      have cnb:=executeOperation_cost .add center negative.word template hc nw le_rfl\n      have cdb:=executeOperation_cost .add node negative.word template hn nw le_rfl\n      have cnp:=power_clock template nb.word m.value ht nbw\n      have cdp:=power_clock template db.word m.value ht dbw\n      have ci:=executeOperation_cost .inv db.word db.word template dbw dbw le_rfl\n      have cs:=executeOperation_cost .mul alpha inv.word template ha iw le_rfl\n      have cr:=copies_clock slope.word m.value template.length sw\n      have cN:=executeOperation_cost .mul np.word tail.numerator template npw tw.1 le_rfl\n      have cD:=executeOperation_cost .mul dp.word tail.denominator template dpw tw.2.1 le_rfl\n      have hm:=SemiprimeD1RecoveryWeightRunBounds.multiplicity_value_le g h u q\n      have hf:=frame_envelope template.length m.value (h*u) hm\n      have hlen : repeated.words.length=m.value := by simp only [repeated,copies_words,List.length_replicate]\n      have visit : negative.clock+nb.clock+db.clock+np.clock+dp.clock+inv.clock+slope.clock+\n          repeated.clock+numerator.clock+denominator.clock+2*repeated.words.length+15 ≤\n          frameBudget template.length (h*u) := by\n        rw [hlen]\n        dsimp only [tail,m,negative,nb,db,np,dp,inv,slope,repeated,numerator,denominator] at *\n        simp only [Nat.mul_assoc] at hf\n        omega\n      simp only [loop,hs,ite_false]\n      change tail.clock+negative.clock+nb.clock+db.clock+np.clock+dp.clock+inv.clock+slope.clock+\n        repeated.clock+numerator.clock+denominator.clock+2*repeated.words.length+15 ≤ _\n      simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n      dsimp only [tail,m,negative,nb,db,np,dp,inv,slope,repeated,numerator,denominator] at *\n      omega\n\n/-- Every native index/valuation stage of the actual original grid is retained. -/\ntheorem loop_metadataWork (template : List Bool) (a h u t : ℕ) (g : Geometry)\n    (center alpha node : RationalWord) (qs : List ℕ) :\n    (loop template a h u t g center alpha node qs).metadataWork ≤\n      qs.length*(5*g.size+4*(a+2)+30)+1 := by\n  induction qs with\n  | nil => simp [loop]\n  | cons q qs ih =>\n    have hm:=SemiprimeD1RecoveryWeightRunBounds.multiplicity_work g h u q\n    have hi:=(SemiprimeEncodedRowSelection.encode_work (a+1) (q:ℤ)).1\n    simp only [loop]\n    split_ifs <;> dsimp only\n    · simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n      omega\n    · change _+(multiplicityRun g h u q).work+(index a q).work+10 ≤ _\n      change (index a q).work=4*(a+2)+4 at hi\n      simp only [List.length_cons,Nat.add_mul,Nat.one_mul,hi]\n      omega\n\n/-- Literal original-grid physical arithmetic budget. -/\ndef budget (a h u W : ℕ) : ℕ :=\n  (2*a+1)*(20000*(W+1)^3+4)+size a*frameBudget W (h*u)+6*(20000*(W+1)^3)+40\n\n/-- Actual original physical scalar/slopes/argument acquisition has a closed\nbit-arithmetic clock, not a count of unit native rational operations. -/\ntheorem acquire_clock (template : List Bool) (a M u : ℕ) (t : Fin (size a))\n    (hW : gridWidth a (height M u) u ≤ template.length) :\n    (acquire template a M u t).clock ≤ budget a (height M u) u template.length := by\n  let h:=height M u\n  let g:=geometry a t.val\n  let c:=power template twoWord a\n  let alpha:=power template twoWord (a+1)\n  let node:=index a t.val\n  let keys:=indices g.size\n  let grid:=loop template a h u t.val g c.word alpha.word node.word keys.value\n  let inverse:=executeOperation .inv grid.denominator grid.denominator template\n  let scalar:=executeOperation .mul grid.numerator inverse.word template\n  let neg:=executeOperation .neg node.word node.word template\n  let point:=executeOperation .add c.word neg.word template\n  let invAlpha:=executeOperation .inv alpha.word alpha.word template\n  let arg:=executeOperation .mul point.word invAlpha.word template\n  have caps:=gridWidth_caps a h u template.length hW\n  have two:=twoWord_width template.length (by omega)\n  have cw:=power_width template twoWord a caps.1\n  have aw:=power_width template twoWord (a+1) caps.1\n  have nw:=index_width a t.val template.length caps.2.1\n  have gw:=loop_width template a h u t.val g c.word alpha.word node.word keys.value caps.1\n  have iw:=operation_width .inv grid.denominator grid.denominator template\n  have negw:=operation_width .neg node.word node.word template\n  have pw:=operation_width .add c.word neg.word template\n  have iaw:=operation_width .inv alpha.word alpha.word template\n  have cc:=power_clock template twoWord a caps.1 two\n  have ca:=power_clock template twoWord (a+1) caps.1 two\n  have cg:=loop_clock template a h u t.val g c.word alpha.word node.word keys.value caps.2.1 cw aw nw\n  have ci:=executeOperation_cost .inv grid.denominator grid.denominator template gw.2.1 gw.2.1 le_rfl\n  have cs:=executeOperation_cost .mul grid.numerator inverse.word template gw.1 iw le_rfl\n  have cn:=executeOperation_cost .neg node.word node.word template nw nw le_rfl\n  have cp:=executeOperation_cost .add c.word neg.word template cw negw le_rfl\n  have cia:=executeOperation_cost .inv alpha.word alpha.word template aw aw le_rfl\n  have carg:=executeOperation_cost .mul point.word invAlpha.word template pw iaw le_rfl\n  have hlen : keys.value.length=size a := by simp [keys,indices_value,g,geometry_size]\n  rw [hlen] at cg\n  change c.clock+alpha.clock+grid.clock+inverse.clock+scalar.clock+neg.clock+point.clock+invAlpha.clock+arg.clock+30 ≤ _\n  unfold budget\n  simp only [Nat.add_mul,Nat.one_mul,Nat.mul_assoc]\n  dsimp only [c,alpha,node,keys,grid,inverse,scalar,neg,point,invAlpha,arg,g,h] at *\n  simp only [Nat.add_mul,Nat.one_mul] at *\n  omega\n\nend RiemannGaussian.SemiprimeD1RecoveryGridBitsBounds\n","RiemannGaussian.SemiprimeD1RecoveryPhysicalBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecoveryPhysicalRun\n\n/-! # Original-input physical recovery cache and arithmetic clocks -/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1RecoveryPhysicalBounds\nopen SemiprimeBitArithmetic SemiprimeRationalBits\nopen SemiprimeD1RecoveryPhysicalRun SemiprimeD1RecoveryIntegerBits\n\n/-- Original retained source rows carry bounded actual node/coordinate labels. -/\ntheorem row_labels (a M u : ℕ) (hM : u ≤ M)\n    (r : SemiprimeD1RecoveryRowsBits.Row)\n    (hr : r ∈ (SemiprimeD1RecoveryRowsBits.acquire a M u).rows) :\n    r.node < SemiprimeD1WireKernelOriginal.size a ∧ r.index < 4*M := by\n  have hm : SemiprimeD1RecoveryRowsRun.Row.mk r.node r.index\n      r.word.numerator.value (bitValue r.word.denominator) ∈\n      rowView (SemiprimeD1RecoveryRowsBits.acquire a M u).rows :=\n    List.mem_map.mpr ⟨r,hr,rfl⟩\n  rw [rowView_original a M u hM,SemiprimeD1RecoveryRowsRun.acquire_rows] at hm\n  simp only [SemiprimeD1RecoveryRowsRun.originalRows,List.mem_flatMap] at hm\n  obtain ⟨t,ht,hm⟩:=hm\n  split_ifs at hm with hs\n  · simp at hm\n  · obtain ⟨j,hj,hjr⟩:=List.mem_map.mp hm\n    have hn:=congrArg SemiprimeD1RecoveryRowsRun.Row.node hjr\n    have hi:=congrArg SemiprimeD1RecoveryRowsRun.Row.index hjr\n    change t=r.node at hn\n    change j=r.index at hi\n    have ht':t<SemiprimeD1WireKernelOriginal.size a:=List.mem_range.mp ht\n    have hj':j<(SemiprimeD1JetRecoveryWeights.acquire a\n      (SemiprimeD1TaperedLoss.height M u) u t).weights.size := List.mem_range.mp hj\n    rw [SemiprimeD1JetRecoveryWeights.acquire_weights_size] at hj'\n    exact ⟨hn ▸ ht',hi ▸ hj'.trans_le\n      (SemiprimeD1WeightPrecision.nodeMultiplicity_le a M u t hM)⟩\n\n/-- A literal cache read bound in its actual shape and address widths. -/\ndef readBudget (nodes rows P B : ℕ) : ℕ :=\n  (nodes+1)*(rows*(4*P+4)+15*B+40)+(rows+1)*(4*P+15*B+30)+4\n\n/-- Actual physical row/child assembly has one paid cache scan per source row. -/\ntheorem entries_clock (children : List (List (List Bool)))\n    (rs : List SemiprimeD1RecoveryRowsBits.Row) (A P B : ℕ)\n    (hB : 1 ≤ B)\n    (hc : ∀ row ∈ children, row.length ≤ A ∧ ∀ x ∈ row, x.length ≤ P)\n    (hr : ∀ r ∈ rs, r.node+1 ≤ B ∧ r.index+1 ≤ B) :\n    (entries children rs).clock ≤ rs.length*(readBudget children.length A P B+4)+1 := by\n  induction rs with\n  | nil => simp [entries]\n  | cons r rs ih =>\n    have hh:=hr r (by simp)\n    have hd:=SemiprimeD1RecoveryChildBits.read_clock children\n      (SemiprimeEncodedRowSelection.digits (r.node+1) r.node).bits\n      (SemiprimeEncodedRowSelection.digits (r.index+1) r.index).bits A P B hB\n      (by simpa only [SemiprimeEncodedRowSelection.digits_length] using hh.1)\n      (by simpa only [SemiprimeEncodedRowSelection.digits_length] using hh.2) hc\n    have ht:=ih (fun r hr' => hr r (by simp [hr']))\n    change _ + (entries children rs).clock + 4 ≤ _\n    simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n    dsimp only [readBudget] at *\n    omega\n\n/-- Physical assembly retains one child operand per actual source row. -/\ntheorem entries_length (children : List (List (List Bool)))\n    (rs : List SemiprimeD1RecoveryRowsBits.Row) :\n    (entries children rs).entries.length=rs.length := by\n  induction rs with\n  | nil => rfl\n  | cons r rs ih => simp only [entries,List.length_cons,ih]\n\n/-- Original source store widths and literal child precision bound every actual\noperand before arithmetic, not merely the requested final answer. -/\ntheorem entries_width (children : List (List (List Bool)))\n    (rs : List SemiprimeD1RecoveryRowsBits.Row) (W P : ℕ)\n    (hr : ∀ r ∈ rs, Width r.word W) (hP : P ≤ W)\n    (hc : ∀ row ∈ children, ∀ x ∈ row, x.length ≤ P) :\n    ∀ e ∈ (entries children rs).entries,\n      e.numerator.magnitude.length ≤ W ∧ e.denominator.length ≤ W ∧ e.child.length ≤ W := by\n  induction rs with\n  | nil => simp [entries]\n  | cons r rs ih =>\n    intro e he\n    simp only [entries,List.mem_cons] at he\n    rcases he with he|he\n    · subst e\n      exact ⟨(hr r (by simp)).1,(hr r (by simp)).2,\n        (child_read_length children _ _ P hc).trans hP⟩\n    · exact ih (fun r hr' => hr r (by simp [hr'])) e he\n\n/-- A conservative closed original-parameter physical recovery report.\nAll original producers are counted again whenever this run is repeated. -/\ndef budget (a M p P : ℕ) : ℕ :=\n  let N:=SemiprimeD1WireKernelOriginal.size a\n  let m:=4*M\n  let W:=width a M P\n  let K:=N*m\n  SemiprimeD1RecoveryRowsBits.budget a M+\n    (K*(readBudget N m P (N+m+1)+4)+1)+\n    (K*(40*(W+1)^2+23)+3)+(K*(300*(W+1)^2+100)+3)+\n    SemiprimeD1RecoveryStripBits.budget p W+3*W+10\n\n/-- The actual full original physical recovery report is bounded from original\nparameters and actual child-cache dimensions. No source/callback/output-height\nor Fits answer is admitted. Typed metadata remains separately scoped. -/\ntheorem run_clock (a M u p P : ℕ) (children : List (List (List Bool)))\n    (hM : u ≤ M) (hn : children.length ≤ SemiprimeD1WireKernelOriginal.size a)\n    (hc : ∀ row ∈ children, row.length ≤ 4*M ∧ ∀ x ∈ row, x.length ≤ P) :\n    (run a M u p P children).clock ≤ budget a M p P := by\n  let rows:=SemiprimeD1RecoveryRowsBits.acquire a M u\n  let es:=(entries children rows.rows).entries\n  let W:=width a M P\n  let N:=SemiprimeD1WireKernelOriginal.size a\n  let m:=4*M\n  let K:=N*m\n  let B:=N+m+1\n  let template:=List.replicate W false\n  have hWpos : 0 < W := by dsimp only [W,width]; omega\n  have hP : P ≤ W := by dsimp only [W,width]; omega\n  have hw : SemiprimeD1RecoveryNodeBits.width a M ≤ W := by dsimp only [W,width]; omega\n  have hg:=SemiprimeD1RecoveryRowsBits.acquire_good a M u hM\n  have hes : ∀ e ∈ es, e.numerator.magnitude.length ≤ W ∧\n      e.denominator.length ≤ W ∧ e.child.length ≤ W := by\n    apply entries_width children rows.rows W P _ hP (fun r hr x hx => (hc r hr).2 x hx)\n    intro r hr\n    exact ⟨(hg.2 r hr).1.trans hw,(hg.2 r hr).2.trans hw⟩\n  have hl : es.length ≤ K := by\n    rw [show es.length=rows.rows.length from entries_length _ _]\n    exact SemiprimeD1RecoveryRowsBits.acquire_length a M u hM\n  have hs:=SemiprimeD1RecoveryRowsBits.acquire_clock a M u hM\n  have he:=entries_clock children rows.rows m P B (by dsimp only [B]; omega) hc\n    (fun r hr => by\n      have hh:=row_labels a M u hM r hr\n      dsimp only [B,N,m]\n      omega)\n  have hread : readBudget children.length m P B ≤ readBudget N m P B := by\n    unfold readBudget\n    gcongr\n  have hrows : rows.rows.length ≤ K := SemiprimeD1RecoveryRowsBits.acquire_length a M u hM\n  have he' : (entries children rows.rows).clock ≤ K*(readBudget N m P B+4)+1 := by\n    exact he.trans (Nat.add_le_add_right (Nat.mul_le_mul hrows (Nat.add_le_add_right hread 4)) 1)\n  have hd:=denominator_clock template es (by simpa only [template,List.length_replicate] using hWpos)\n    (fun e he => by simpa only [template,List.length_replicate] using (hes e he).2.1)\n  have hdl:=denominator_length template es (by simpa only [template,List.length_replicate] using hWpos)\n  have ha:=accumulate_clock template (denominator template es).bits es hdl\n    (by simpa only [template,List.length_replicate] using hes)\n  have hnl:=accumulate_length template (denominator template es).bits es\n  have hf:=SemiprimeD1RecoveryStripBits.finish_clock p W\n    (accumulate template (denominator template es).bits es).word\n    (denominator template es).bits\n    (by simpa only [template,List.length_replicate] using hnl)\n    (by simpa only [template,List.length_replicate] using hdl)\n  simp only [template,List.length_replicate] at hd ha\n  have hd' : (denominator template es).clock ≤ K*(40*(W+1)^2+23)+3 :=\n    hd.trans (Nat.add_le_add_right (Nat.mul_le_mul_right _ hl) 3)\n  have ha' : (accumulate template (denominator template es).bits es).clock ≤\n      K*(300*(W+1)^2+100)+3 :=\n    ha.trans (Nat.add_le_add_right (Nat.mul_le_mul_right _ hl) 3)\n  simp only [run,widthRun_value,runAt,budget]\n  change rows.clock+(entries children rows.rows).clock+(denominator template es).clock+\n    (accumulate template (denominator template es).bits es).clock+\n    (SemiprimeD1RecoveryStripBits.finish p\n      (accumulate template (denominator template es).bits es).word\n      (denominator template es).bits).clock+3*W+10 ≤ _\n  change rows.clock ≤ SemiprimeD1RecoveryRowsBits.budget a M at hs\n  dsimp only [B,K,N,m,W] at he' hd' ha' hf ⊢\n  omega\n\n/-- The original physical replacement always returns compact precision-p data. -/\ntheorem run_good (a M u p P : ℕ) (children : List (List (List Bool))) :\n    (run a M u p P children).bits.length ≤ p ∧\n      SemiprimeSourceCompactBits.Compact (run a M u p P children).bits := by\n  rw [run_bits]\n  exact SemiprimeD1RecoveryStripBits.finish_good _ _ _\n\n/-- The two actual source label-to-address acquisitions per retained row are\nexplicit native metadata stages; their ledger is not silently dropped. -/\ntheorem entries_metadataWork (children : List (List (List Bool)))\n    (rs : List SemiprimeD1RecoveryRowsBits.Row) (B : ℕ)\n    (hr : ∀ r ∈ rs, r.node+1 ≤ B ∧ r.index+1 ≤ B) :\n    (entries children rs).metadataWork ≤ rs.length*(8*B+6)+1 := by\n  induction rs with\n  | nil => simp [entries]\n  | cons r rs ih =>\n    have hh:=hr r (by simp)\n    have ht:=ih (fun r hr' => hr r (by simp [hr']))\n    simp only [entries,SemiprimeEncodedRowSelection.digits_work,List.length_cons,\n      Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- Repeating the recovery for another old coordinate retains the entire\noriginal physical coefficient producer each time. -/\ntheorem run_retains_source (a M u p P : ℕ) (children : List (List (List Bool))) :\n    (SemiprimeD1RecoveryRowsBits.acquire a M u).clock ≤ (run a M u p P children).clock := by\n  simp only [run,runAt]\n  omega\n\nend RiemannGaussian.SemiprimeD1RecoveryPhysicalBounds\n","RiemannGaussian.SemiprimeD1RecursiveCallPath":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecursiveCallInventory\nimport RiemannGaussian.SemiprimeD1ChildStateResources\n\n/-! # Original-input bounds on every actual controller path\nReachability uses the controller's literal acquired child list. The global\nstored-degree cap, geometric edge decay and computed precision envelope are\ninherited by induction; no arbitrary edge history or accepted mode bound is\nsupplied. Root numerical premises concern only actual input dimensions.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 120000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1RecursiveCallPath\nopen SemiprimeD1JetAxes SemiprimeD1TensorNetwork SemiprimeD1RecursiveCounter\nopen SemiprimeD1RecursiveCallTree SemiprimeD1RecursiveCallState\nopen SemiprimeD1TensorNetworkRecursion SemiprimeD1Schedule SemiprimeD1PrecisionEnvelope\n\n/-- Every actual child preserves a stored degree cap that pays new packet scopes. -/\ntheorem mem_children_degree (s : ℕ) (parent next : Call) (hm : next ∈ children s parent)\n    (D : ℕ) (hw : WellFormed parent.net) (hd : DegreeBound parent.net D)\n    (hslots : 2*2^(exponent (SemiprimeD1PackingReady.logarithm s) parent.depth) ≤ D) :\n    DegreeBound next.net D := by\n  obtain ⟨_,t,ht⟩ := (mem_children s parent next).mp hm\n  obtain ⟨hi,beta,_,g,rfl⟩ := (mem_phaseChildren parent _ _ t next).mp ht\n  exact SemiprimeD1ChildStateResources.child_degree parent.net hw D _ _ hd hslots\n    _ g parent.ctx _ _ _ t beta\n\n/-- Exact child membership propagates the original computed precision cap. -/\ntheorem mem_children_precision_cap (s : ℕ) (parent next : Call)\n    (hm : next ∈ children s parent) (hM : edgeCount parent.net ≤ s)\n    (hp : parent.ctx.precision ≤ pathCap s (SemiprimeD1PackingReady.logarithm s)\n      parent.depth (previous (SemiprimeD1PackingReady.logarithm s) parent.depth)) :\n    next.ctx.precision ≤ pathCap s (SemiprimeD1PackingReady.logarithm s)\n      next.depth (previous (SemiprimeD1PackingReady.logarithm s) next.depth) := by\n  have hactive := (activeTest_correct _ _ _ _).mp ((mem_children s parent next).mp hm).1\n  obtain ⟨i,_,hi⟩ := mem_children_precision s parent next hm\n  rw [hi,mem_children_depth s parent next hm,previous_succ]\n  exact update_cap s _ parent.depth _ (edgeCount parent.net) _ _ i parent.ctx.precision\n    hM hactive.2.2 (exponent_le_lam _ _) (Nat.le_add_right _ _) hp\n\n/-- The scaled edge bound implies the unscaled bound without an input oracle. -/\ntheorem edges_le_of_scaled (s : ℕ) (call : Call) (h : edgeCount call.net*8^call.depth ≤ s) :\n    edgeCount call.net ≤ s := by\n  have hpow : 1 ≤ (8:ℕ)^call.depth := Nat.one_le_pow _ _ (by decide)\n  have hm : edgeCount call.net ≤ edgeCount call.net*8^call.depth := by\n    simpa only [Nat.mul_one] using Nat.mul_le_mul_left (edgeCount call.net) hpow\n  exact hm.trans h\n\n/-- ALL actual reachable calls inherit the original degree, scope-decay and\nworking-precision invariants. Only actual root dimensions and stored data are premises. -/\ntheorem eventually_reach_invariant : ∀ᶠ s : ℕ in Filter.atTop,\n    ∀ root next : Call, root.depth=0 → edgeCount root.net ≤ s → root.ctx.precision ≤ s →\n      root.ctx.Positive → WellFormed root.net → Good root.ctx root.net →\n      DegreeBound root.net (SemiprimeD1PackingReady.degreeCap s) → Reach s root next →\n      DegreeBound next.net (SemiprimeD1PackingReady.degreeCap s) ∧\n      edgeCount next.net*8^next.depth ≤ s ∧\n      next.ctx.precision ≤ pathCap s (SemiprimeD1PackingReady.logarithm s)\n        next.depth (previous (SemiprimeD1PackingReady.logarithm s) next.depth) := by\n  filter_upwards [SemiprimeD1PackingReady.eventually_all_depths,\n    eventually_mem_children_shrink] with s hs hshrink\n  intro root next hroot hM hp hpos hw hg hd hr\n  induction hr with\n  | root =>\n    refine ⟨hd,?_,?_⟩\n    · simpa only [hroot,pow_zero,Nat.mul_one] using hM\n    · simpa only [hroot,previous,Finset.sum_range_zero,Nat.mul_zero,root_cap] using hp\n  | @step parent next hr hm ih =>\n    have hshape := reach_shape s root parent hr hpos hw hg\n    have hactive := (activeTest_correct _ _ _ _).mp ((mem_children s parent next).mp hm).1\n    have hpacking := hs parent.depth (edgeCount parent.net) _ hactive le_rfl\n    have hslots := (le_max_right _ _).trans hpacking.2.2\n    have hdegree := mem_children_degree s parent next hm _ hshape.2.1 ih.1 hslots\n    have hsh := hshrink parent next hm hshape.2.1 ih.1\n    have hedge : edgeCount next.net*8^next.depth ≤ s := by\n      rw [mem_children_depth s parent next hm,pow_succ]\n      calc\n        _ = (edgeCount next.net*8)*8^parent.depth := by ring\n        _ ≤ edgeCount parent.net*8^parent.depth := Nat.mul_le_mul_right _ hsh\n        _ ≤ s := ih.2.1\n    exact ⟨hdegree,hedge,mem_children_precision_cap s parent next hm\n      (edges_le_of_scaled s parent ih.2.1) ih.2.2⟩\n\nend RiemannGaussian.SemiprimeD1RecursiveCallPath\n","RiemannGaussian.SemiprimeD1RecursiveCallState":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecursiveCallTree\n\n/-! # Inherited structural state of actual recursive calls\nAll membership premises refer to the literal child list of the closed\ncontroller. Fresh-axis positivity, original history precision and scope shrink\nare derived from that membership, not supplied as a child solution or label.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 100000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1RecursiveCallState\nopen SemiprimeD1JetAxes SemiprimeD1TensorNetwork SemiprimeD1RecursiveCounter\nopen SemiprimeD1RecursiveCallTree SemiprimeD1WireKernelOriginal\n\n/-- Actual positive active scope gives a positive original tapered height. -/\ntheorem height_positive (M u : ℕ) (hu : 0 < u) (huM : u ≤ M) :\n    0 < SemiprimeD1ModeRate.jetHeight M u := by\n  have hn : u ≤ 3*M+u-1 := by omega\n  have hd : 1 ≤ (3*M+u-1)/u :=\n    (Nat.le_div_iff_mul_le hu).mpr (by simpa only [one_mul] using hn)\n  exact lt_of_lt_of_le Nat.zero_lt_one hd\n\n/-- Every stored child preserves all old axes and adds one positive fresh axis. -/\ntheorem child_positive (parent : Call) (a u : ℕ) (t : Fin (size a)) (i : Fin a)\n    (beta : List ℕ) (g : Fin 64) (hp : parent.ctx.Positive)\n    (hq : 0 < SemiprimeD1ModeRate.jetHeight (edgeCount parent.net) u * (u-i.val)) :\n    (child parent a u t i beta g).ctx.Positive := by\n  intro k hk\n  rcases List.mem_cons.mp hk with rfl | hk\n  · exact hq\n  · exact hp k hk\n\n/-- Actual child scalar precision is the literal D.11 history update. -/\ntheorem child_precision (parent : Call) (a u : ℕ) (t : Fin (size a)) (i : Fin a)\n    (beta : List ℕ) (g : Fin 64) :\n    (child parent a u t i beta g).ctx.precision =\n      SemiprimeD1ModeRate.workingPrecision (edgeCount parent.net) u a i.val parent.ctx.precision := by\n  exact SemiprimeD1RecursivePhaseBounds.source_precision parent.net a u i.val parent.ctx.precision\n\n/-- Actual fromSource rows are precisely the original acquired child rows used\nby the already proved scope contraction theorem. -/\ntheorem child_rows (parent : Call) (a u : ℕ) (t : Fin (size a)) (i : Fin a)\n    (beta : List ℕ) (g : Fin 64) :\n    (child parent a u t i beta g).net.rows =\n      SemiprimeD1TensorNetworkRecursion.child parent.net a i g := by\n  change (SemiprimeD1ChildNetwork.fromSource _ _ _ _ _ _ _ _ _ _).network.rows = _\n  rw [SemiprimeD1ChildNetwork.fromSource_rows]\n  rfl\n\n/-- Both original degree guards imply actual child scope shrink; beta and the\nfresh words do not change the actually constructed child graph. -/\ntheorem child_shrink (parent : Call) (a u degree : ℕ) (t : Fin (size a)) (i : Fin a)\n    (beta : List ℕ) (g : Fin 64) (hw : WellFormed parent.net)\n    (hd : SemiprimeD1TensorNetworkRecursion.DegreeBound parent.net degree)\n    (hsmall : 2*(64^(2*a))^2*degree ≤ edgeCount parent.net) :\n    edgeCount (child parent a u t i beta g).net * 8 ≤ edgeCount parent.net := by\n  change scope (child parent a u t i beta g).net.rows * 8 ≤ _\n  rw [child_rows]\n  exact SemiprimeD1TensorNetworkRecursion.child_shrink_eight parent.net hw degree a hd hsmall i g\n\n/-- Every actual child has exactly the next schedule depth. -/\ntheorem mem_children_depth (s : ℕ) (parent next : Call) (hm : next ∈ children s parent) :\n    next.depth = parent.depth+1 := by\n  obtain ⟨_,t,ht⟩ := (mem_children s parent next).mp hm\n  obtain ⟨hi,beta,_,g,rfl⟩ := (mem_phaseChildren parent _ _ t next).mp ht\n  rfl\n\n/-- Actual child membership inherits positive axes, canonical original ports\nand actual canonical table data from the parent. -/\ntheorem mem_children_shape (s : ℕ) (parent next : Call) (hm : next ∈ children s parent)\n    (hp : parent.ctx.Positive) (hg : Good parent.ctx parent.net) :\n    next.ctx.Positive ∧ WellFormed next.net ∧ Good next.ctx next.net := by\n  obtain ⟨ha,t,ht⟩ := (mem_children s parent next).mp hm\n  obtain ⟨hi,beta,_,g,rfl⟩ := (mem_phaseChildren parent _ _ t next).mp ht\n  have hactive := (activeTest_correct _ _ _ _).mp ha\n  have hu := SemiprimeD1Schedule.active_positive _ _ _ _ hactive\n  have hh := height_positive _ _ hu hactive.2.2\n  have hq := Nat.mul_pos hh (Nat.sub_pos_of_lt hi.2.1)\n  exact ⟨child_positive parent _ _ t _ beta g hp hq,\n    child_wellFormed parent _ _ t _ beta g,child_good parent _ _ t _ beta g hg hq⟩\n\n/-- No reachable call needs a shape, positivity or well-formedness oracle. -/\ntheorem reach_shape (s : ℕ) (root next : Call) (hr : Reach s root next)\n    (hp : root.ctx.Positive) (hw : WellFormed root.net) (hg : Good root.ctx root.net) :\n    next.ctx.Positive ∧ WellFormed next.net ∧ Good next.ctx next.net := by\n  induction hr with\n  | root => exact ⟨hp,hw,hg⟩\n  | step hr hm ih => exact mem_children_shape s _ _ hm ih.1 ih.2.2\n\n/-- Every reachable depth is at least the literal root depth. -/\ntheorem reach_depth (s : ℕ) (root next : Call) (hr : Reach s root next) : root.depth ≤ next.depth := by\n  induction hr with\n  | root => exact le_rfl\n  | step hr hm ih => rw [mem_children_depth s _ _ hm];omega\n\n/-- Every actual child inherits a genuine original valuation level and the\nliteral D.11 update at that level. -/\ntheorem mem_children_precision (s : ℕ) (parent next : Call) (hm : next ∈ children s parent) :\n    ∃ i < SemiprimeD1Schedule.levels (SemiprimeD1PackingReady.logarithm s) parent.depth,\n    next.ctx.precision = SemiprimeD1ModeRate.workingPrecision (edgeCount parent.net)\n      (SemiprimeD1Schedule.levels (SemiprimeD1PackingReady.logarithm s) parent.depth)\n      (SemiprimeD1Schedule.exponent (SemiprimeD1PackingReady.logarithm s) parent.depth)\n      i parent.ctx.precision := by\n  obtain ⟨_,t,ht⟩ := (mem_children s parent next).mp hm\n  obtain ⟨hi,beta,_,g,rfl⟩ := (mem_phaseChildren parent _ _ t next).mp ht\n  exact ⟨_,hi.2.1,child_precision parent _ _ t _ beta g⟩\n\n/-- Uniform original-scale packing acceptance derives shrink on EVERY actual\nactive child, conditional only on the parent's actual stored degree cap. -/\ntheorem eventually_mem_children_shrink : ∀ᶠ s : ℕ in Filter.atTop,\n    ∀ parent next : Call, next ∈ children s parent → WellFormed parent.net →\n      SemiprimeD1TensorNetworkRecursion.DegreeBound parent.net (SemiprimeD1PackingReady.degreeCap s) →\n      edgeCount next.net*8 ≤ edgeCount parent.net := by\n  filter_upwards [SemiprimeD1PackingReady.eventually_all_depths] with s hs\n  intro parent next hm hw hd\n  obtain ⟨ha,t,ht⟩ := (mem_children s parent next).mp hm\n  obtain ⟨hi,beta,_,g,rfl⟩ := (mem_phaseChildren parent _ _ t next).mp ht\n  have hactive := (activeTest_correct _ _ _ _).mp ha\n  have hpacking := hs parent.depth (edgeCount parent.net) _ hactive le_rfl\n  exact child_shrink parent _ _ _ t _ beta g hw hd hpacking.1.le\n\nend RiemannGaussian.SemiprimeD1RecursiveCallState\n","RiemannGaussian.SemiprimeD1RecursiveLeafBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecursiveCallPath\nimport RiemannGaussian.SemiprimeD1LeafCounterResources\n\n/-! # Actual stopped calls have the original small-leaf scale\nFailed native schedule tests and fuel exhaustion at the original root fuel are\nboth covered. The eager leaf's literal report is bounded using its actual\nnetwork, with every stored scope bound derived from canonical well-formed ports.\nThese are component-report bounds, not a full primitive-machine simulation.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 300000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1RecursiveLeafBounds\nopen SemiprimeD1TensorNetwork SemiprimeD1TensorNetworkLayout SemiprimeD1JetAxes\nopen SemiprimeD1RecursiveCounter SemiprimeD1RecursiveCallTree\nopen SemiprimeD1Schedule SemiprimeD1LeafRate\n\n/-- No actual active branch exists beyond the original logarithmic fuel cap. -/\ntheorem activeTest_false_of_depth (s depth M : ℕ)\n    (hd : SemiprimeD1PackingReady.logarithm s < depth) :\n    activeTest s (SemiprimeD1PackingReady.logarithm s) depth M = false := by\n  apply Bool.eq_false_of_not_eq_true\n  intro ha\n  have hp := active_positive _ _ _ _ ((activeTest_correct _ _ _ _).mp ha)\n  exact (Nat.not_le_of_lt hd) (depth_le _ _ hp)\n\n/-- Fuel zero at a state whose remaining fuel covers the original cap implies\nthe same failed actual schedule test as an ordinary stopped call. -/\ntheorem zero_fuel_inactive (s depth : ℕ)\n    (hf : SemiprimeD1PackingReady.logarithm s+1 ≤ depth+0) (M : ℕ) :\n    activeTest s (SemiprimeD1PackingReady.logarithm s) depth M = false :=\n  activeTest_false_of_depth s depth M (by omega)\n\n/-- Failure of any literal test gives a genuinely small actual leaf. -/\ntheorem stopped_edges (s : ℕ) (call : Call)\n    (hr : RootReady s (SemiprimeD1PackingReady.logarithm s))\n    (hpath : edgeCount call.net*8^call.depth ≤ s)\n    (hstop : activeTest s (SemiprimeD1PackingReady.logarithm s)\n      call.depth (edgeCount call.net) = false) :\n    edgeCount call.net ≤ leafSize s (SemiprimeD1PackingReady.logarithm s) := by\n  apply inactive_leaf _ _ _ _ hr hpath\n  intro ha\n  have ht := (activeTest_correct _ _ _ _).mpr ha\n  rw [hstop] at ht\n  exact Bool.false_ne_true ht\n\n/-- The actual root fuel suffices to make every executed fuel-zero leaf small;\nno size promise about a stopped child is assumed. -/\ntheorem zero_fuel_edges (s : ℕ) (call : Call)\n    (hr : RootReady s (SemiprimeD1PackingReady.logarithm s))\n    (hpath : edgeCount call.net*8^call.depth ≤ s)\n    (hf : SemiprimeD1PackingReady.logarithm s+1 ≤ call.depth+0) :\n    edgeCount call.net ≤ leafSize s (SemiprimeD1PackingReady.logarithm s) :=\n  stopped_edges s call hr hpath (zero_fuel_inactive s call.depth hf (edgeCount call.net))\n\n/-- Canonical actual network ports give the full local-scope sum cap. -/\ntheorem scopeSize_le (net : Network) (hw : WellFormed net) :\n    SemiprimeD1LeafCounterBounds.scopeSize (vertices net) ≤\n      (vertices net).length*edgeCount net := by\n  have hcap : ∀v∈vertices net,v.ports.length ≤ edgeCount net := by\n    intro v hv\n    exact SemiprimeD1LeafCounterResources.scope_length_of_nodup (edgeCount net) v\n      (wellFormed_vertices net hw v hv) (vertex_ports_nodup net hw v hv)\n  generalize vertices net = xs at hcap ⊢\n  induction xs with\n  | nil => simp [SemiprimeD1LeafCounterBounds.scopeSize]\n  | cons v vs ih =>\n    have hh := hcap v List.mem_cons_self\n    have ht := ih (fun w hw => hcap w (List.mem_cons_of_mem v hw))\n    simp only [SemiprimeD1LeafCounterBounds.scopeSize] at ht\n    simp only [SemiprimeD1LeafCounterBounds.scopeSize,List.map_cons,List.sum_cons,\n      List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- A fixed actual-data size suffices for every argument of the leaf polynomial.\nThe definition contains neither a solved value nor an external work budget. -/\ndef cofactorSize (ctx : Context) (net : Network) : ℕ :=\n  ctx.axes.length+ctx.rank+ctx.precision+edgeCount net+\n    (edgeCount net+1)*((vertices net).length+1)+1\n\n/-- The entire eager leaf report has one fixed polynomial cofactor. -/\ntheorem leaf_clock (ctx : Context) (net : Network) (hw : WellFormed net)\n    (hg : Good ctx net) :\n    (leaf ctx net).clock ≤ 100000*(cofactorSize ctx net+1)^8*2^edgeCount net := by\n  have hscope := scopeSize_le net hw\n  have hv : (vertices net).length ≤ (edgeCount net+1)*((vertices net).length+1) := by\n    nlinarith\n  have hscope' : SemiprimeD1LeafCounterBounds.scopeSize (vertices net) ≤\n      (edgeCount net+1)*((vertices net).length+1) := by nlinarith\n  apply SemiprimeD1LeafCounterResources.run_clock_polynomial _ _ _ hg (cofactorSize ctx net)\n  all_goals unfold cofactorSize;omega\n\n/-- Both failed guards and exhausted original fuel obey the same full eager\nreport bound, whose exponential part is fixed by the actual original input. -/\ntheorem stopped_leaf_clock (s : ℕ) (call : Call)\n    (hr : RootReady s (SemiprimeD1PackingReady.logarithm s))\n    (hpath : edgeCount call.net*8^call.depth ≤ s)\n    (hstop : activeTest s (SemiprimeD1PackingReady.logarithm s)\n      call.depth (edgeCount call.net) = false)\n    (hw : WellFormed call.net) (hg : Good call.ctx call.net) :\n    (leaf call.ctx call.net).clock ≤\n      100000*(cofactorSize call.ctx call.net+1)^8*\n        2^leafSize s (SemiprimeD1PackingReady.logarithm s) := by\n  have hm := stopped_edges s call hr hpath hstop\n  exact (leaf_clock call.ctx call.net hw hg).trans (Nat.mul_le_mul_left _\n    (Nat.pow_le_pow_right (by decide : 0 < (2:ℕ)) hm))\n\n/-- The retained input and global output tables also obey the actual small-leaf\nscale. Native address cells are inventory here, not a tape-time claim. -/\ntheorem stopped_leaf_storage (s : ℕ) (call : Call)\n    (hr : RootReady s (SemiprimeD1PackingReady.logarithm s))\n    (hpath : edgeCount call.net*8^call.depth ≤ s)\n    (hstop : activeTest s (SemiprimeD1PackingReady.logarithm s)\n      call.depth (edgeCount call.net) = false)\n    (hw : WellFormed call.net) (hg : Good call.ctx call.net) :\n    SemiprimeD1LeafCounterResources.retainedStorage (edgeCount call.net) call.ctx (vertices call.net) ≤\n      SemiprimeD1LeafCounterBounds.scopeSize (vertices call.net)+\n        ((vertices call.net).length+2)*((call.ctx.rank*(3*call.ctx.precision+4)+3)*\n          2^leafSize s (SemiprimeD1PackingReady.logarithm s)) := by\n  have h := SemiprimeD1LeafCounterResources.retainedStorage_of_wellFormed\n    (edgeCount call.net) call.ctx (vertices call.net) hg (wellFormed_vertices call.net hw)\n    (vertex_ports_nodup call.net hw)\n  have hp := Nat.pow_le_pow_right (by decide : 0 < (2:ℕ)) (stopped_edges s call hr hpath hstop)\n  exact h.trans (by gcongr)\n\nend RiemannGaussian.SemiprimeD1RecursiveLeafBounds\n","RiemannGaussian.SemiprimeD1RootStateResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ChildStateResources\nimport RiemannGaussian.SemiprimeD1RootTensorTablesBounds\nimport RiemannGaussian.SemiprimeD1RootCoordinates\nimport RiemannGaussian.SemiprimeD1PublicPackingReady\nimport RiemannGaussian.SemiprimePublicBudgetDimensions\n\n/-! # Original-input root dimensions and literal table inventory\nAll root size and degree facts are derived from the actual acquired macro\nnetwork. Original configuration/descriptor native arithmetic remains a separate\nprimitive-lowering obligation, not hidden in this storage theorem.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1RootStateResources\nopen scoped BigOperators\nopen SemiprimePublicAcquiredExecution SemiprimeMacroParameters\nopen SemiprimeD1TensorNetwork SemiprimeD1TensorNetworkLayout\nopen SemiprimeD1NetworkStateResources SemiprimeD1TensorNetworkRecursion\nopen SemiprimeD1RootNetwork SemiprimeD1RootTensorTablesBounds\nattribute [local irreducible] SemiprimeD1RootTensorTables.acquirePositive\nattribute [local irreducible] wireCount factorCount indexedArity indexedCoordinate\n\n/-- The actual original-binary acquired root network. -/\nabbrev root (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool)) :=\n  (SemiprimeD1RootNetwork.acquirePositive N hN fixed).network\n\n/-- Canonical factor grouping preserves every acquired real occurrence. -/\ntheorem fromCache_edges {n F : ℕ} {arity : Fin F→ℕ}\n    (data : SemiprimeD1RootTensorTables.Acquired n F arity) :\n    edgeCount (fromCache data).network=data.records.length := by\n  change scope (rows data)=_\n  rw [←rows_flatten_length]\n  simpa only [List.length_map] using (SemiprimeD1RootPortCounts.rows_owner_perm data).length_eq\n\n/-- Root incidence count is twice the ACTUAL subdivided public Boolean wire count. -/\ntheorem root_edges (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool)) :\n    edgeCount (root N hN fixed)=2*wireCount N := by\n  rw [show root N hN fixed=(fromCache (SemiprimeD1RootTensorTables.acquirePositive N hN fixed)).network from rfl,\n    fromCache_edges,records_length,indexed_incidence_count N hN]\n\n/-- Both acquired original vertex families retain their literal declared counts. -/\ntheorem root_vertices (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool)) :\n    vertexCount (root N hN fixed)=wireCount N+factorCount N := by\n  change wireCount N+(rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed)).length=_\n  rw [rows_length]\n\n/-- Isolated root vertices are paid, using the actual original factor-count bound. -/\ntheorem root_vertices_le_edges (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool)) :\n    vertexCount (root N hN fixed)≤edgeCount (root N hN fixed) := by\n  rw [root_vertices,root_edges]\n  have h:=SemiprimePublicBudgetDimensions.factorCount_le N hN\n  omega\n\n/-- The fixed original public scale pays both copies of every actual occurrence. -/\ntheorem root_edges_le_scale (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool)) :\n    edgeCount (root N hN fixed)≤SemiprimeD1PublicPackingReady.scale (bitLength N) := by\n  rw [root_edges,wireCount_eq]\n  have h:=variableCount_le (bitLength_pos hN)\n  unfold SemiprimeD1PublicPackingReady.scale\n  norm_num\n  omega\n\n/-- The original uniform scope envelope includes the equality/copy scopes. -/\ntheorem two_le_scope (L : ℕ) : 2 ≤ scopeBound L := by\n  unfold scopeBound\n  nlinarith\n\n/-- Original root degree is bounded by its ACTUAL macro scope envelope. -/\ntheorem root_degree (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool)) :\n    DegreeBound (root N hN fixed) (scopeBound (bitLength N)) := by\n  apply SemiprimeD1ChildStateResources.canonical_degree _ (acquirePositive_wellFormed N hN fixed) _\n  · intro v\n    change Fin (wireCount N) at v\n    change (leftPorts (rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed)) v).length≤_\n    rw [SemiprimeD1RootPortCounts.original_owner_degree]\n    have h:=owner_degree_le N hN fixed v\n    simp only [SemiprimeD1RootTensorTables.ownerPorts,List.length_map] at h\n    exact h.trans (two_le_scope _)\n  · intro e\n    change Fin (rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed)).length at e\n    let original : Fin (factorCount N):=⟨e.val,lt_of_lt_of_eq e.isLt\n      (rows_length (SemiprimeD1RootTensorTables.acquirePositive N hN fixed))⟩\n    have he : SemiprimeD1RootEntrySemantics.factorIndex N hN fixed original=e:=Fin.ext rfl\n    change (rightPorts (rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed)) e).length≤_\n    rw [SemiprimeD1RootNetworkOrder.rightPorts_length]\n    have ha := (congrArg (arity (rows (SemiprimeD1RootTensorTables.acquirePositive N hN fixed))) he).symm.trans\n      (SemiprimeD1RootCoordinates.original_arity N hN fixed original)\n    exact ha.trans_le (indexedArity_le N original)\n\n/-- The actual root satisfies the ONE original-scale degree cap; no maximum\nscope answer is an input to recursive resource theorems. -/\ntheorem root_global_degree (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool)) :\n    DegreeBound (root N hN fixed)\n      (SemiprimeD1PackingReady.degreeCap (SemiprimeD1PublicPackingReady.scale (bitLength N))) := by\n  intro v hv\n  exact (root_degree N hN fixed v hv).trans\n    (SemiprimeD1PublicPackingReady.actual_scope _ (bitLength_pos hN))\n\n/-- Full actual root table/port/row data is bounded from N alone, including\nall eager2^scope entries, rather than treating acquired tables as free input. -/\ntheorem root_inventory (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool)) :\n    inventory (root N hN fixed)≤\n      (wireCount N+factorCount N)*(13*2^(scopeBound (bitLength N))+scopeBound (bitLength N))+\n      2*wireCount N+factorCount N+1 := by\n  have h:=inventory_bound SemiprimeD1RootOwnerTables.rootContext (root N hN fixed)\n    (scopeBound (bitLength N)) (acquirePositive_good N hN fixed) (root_degree N hN fixed)\n  rw [root_vertices,root_edges] at h\n  have hr : (root N hN fixed).rows.length=factorCount N:=rows_length _\n  simpa only [SemiprimeD1RootOwnerTables.rootContext,SemiprimeD1JetAxes.Context.rank,List.prod_nil,\n    Nat.mul_one,Nat.one_mul,hr] using h\n\nend RiemannGaussian.SemiprimeD1RootStateResources\n","RiemannGaussian.SemiprimeD1StackBinarySquareRootLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBinarySquareRootDecision\n/-! # Complete descending-power loop: exactly L+1 real binary candidate tests -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackBinarySquareRootLoop\nopen SemiprimeD1StackBinarySquareRoot SemiprimeD1StackBinarySquareRootEncoding\nopen SemiprimeD1StackBinarySquareRootPrimitives SemiprimeD1StackBinarySquareRootDecision\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackPackedRootMetadataEncoding (baseWord)\n/-- One extra zero bit at the low end is exactly the preceding binary power. -/\ntheorem base_succ (n : ℕ) : baseWord (n+1)=false::baseWord n := by\n  simp only [baseWord,List.replicate_succ,List.cons_append]\n/-- Actual one-cell power shift consumes the real bit and selects continue/finish. -/\ntheorem shift_run (bits p r : List Bool) (bit : Bool) :\n    Runs program 1 (ctl .shift) (idle bits (bit::p) r)\n      (if bit then ctl .reverse else ctl .rootCopy) (idle bits p r) := by\n  apply one_base program _ _ (.pop power (ctl .reverse) (ctl .rootCopy) (ctl .reverse)) _ _ rfl\n  · cases bit <;> rfl\n  · change Function.update (idle bits (bit::p) r) (metadata (M.aux .base)) p=idle bits p r\n    dsimp only [idle]\n    rw [bank_metadata,retained_update]\n/-- Exact actual instruction clock of the n+1 descending candidate-bit tests. -/\ndef loopTime (bits : List Bool) : ℕ→List Bool→ℕ\n  | 0,r => iterationTime bits (baseWord 0) r+1\n  | n+1,r => iterationTime bits (baseWord (n+1)) r+1+\n      loopTime bits n (E.nextWord bits r (baseWord (n+1)))\n/-- Whole literal loop from any actual descending-power boundary, all33 roles. -/\ntheorem loop_run (bits r : List Bool) (n : ℕ) :\n    Runs program (loopTime bits n r) (ctl .rootCopy) (idle bits (baseWord n) r)\n      (ctl .reverse) (idle bits [] (E.wordLoop bits n r)) := by\n  induction n generalizing r with\n  | zero =>\n    have h0:=iteration_run bits (baseWord 0) r\n    have h1:=shift_run bits [] (E.nextWord bits r (baseWord 0)) true\n    exact join h0 h1\n  | succ n ih =>\n    have h0:=iteration_run bits (baseWord (n+1)) r\n    have h1:=shift_run bits (baseWord n) (E.nextWord bits r (baseWord (n+1))) false\n    rw [←base_succ] at h1\n    exact join (join h0 h1) (ih (E.nextWord bits r (baseWord (n+1))))\nend RiemannGaussian.SemiprimeD1StackBinarySquareRootLoop\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketCleanup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketParse\n/-! # Complete paid per-incidence raw-field erasure\nEvery parsed field is physically drained through its actual EOF instruction.\nThe five finite positions are already literal source labels, not input counts.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketCleanup\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint)\nopen SemiprimeD1StackProcedureTrace\n/-- The exact five actual raw-field roles. -/\ndef role:Fin 5→Stack\n  | 0=>aux .ownerKey\n  | 1=>aux .sourceKey\n  | 2=>aux .slotWord\n  | 3=>aux .edgeWord\n  | 4=>aux .sideWord\n/-- Exact words acquired by the preceding actual parser. -/\ndef word (f:Endpoint):Fin 5→List Bool\n  | 0=>f.vertex\n  | 1=>f.packet\n  | 2=>f.slot\n  | 3=>f.edge\n  | 4=>f.side\n/-- Actual fixed cleanup sites, ending at the real endpoint-reader loop. -/\ndef pc:Fin 6→Label\n  | 0=>(.local 7 31)\n  | 1=>(.local 8 0)\n  | 2=>(.local 8 1)\n  | 3=>(.local 8 2)\n  | 4=>(.local 8 3)\n  | 5=>(.local 6 23)\n/-- Complete physical effect; every other115-role word is retained. -/\ndef result (before:Stack→List Bool):Stack→List Bool:=\n  Function.update (Function.update (Function.update (Function.update (Function.update before\n    (aux .ownerKey) []) (aux .sourceKey) []) (aux .slotWord) []) (aux .edgeWord) []) (aux .sideWord) []\n/-- Every actual field pop and every actual EOF pop is paid. -/\ndef timeBound (f:Endpoint):Nat:=f.vertex.length+f.packet.length+f.slot.length+f.edge.length+f.side.length+5\n/-- Complete actual physical cleanup between two bucket endpoint visits. -/\ntheorem source_trace (before:Stack→List Bool) (f:Endpoint)\n    (hread:∀i,before (role i)=word f i):\n    Runs program (timeBound f) (pc 0) before (pc 5) (result before):=by\n  have hx0:before (aux .ownerKey)=f.vertex:=hread 0\n  have hx1:before (aux .sourceKey)=f.packet:=hread 1\n  have hx2:before (aux .slotWord)=f.slot:=hread 2\n  have hx3:before (aux .edgeWord)=f.edge:=hread 3\n  have hx4:before (aux .sideWord)=f.side:=hread 4\n  simp only [aux] at hx0 hx1 hx2 hx3 hx4\n  let b0:=before\n  let b1:Stack→List Bool:=Function.update b0 (aux .ownerKey) []\n  have h0:Runs program (f.vertex.length+1) (pc 0) b0 (pc 1) b1:=\n    drain_loop (pc 0) (pc 1) (aux .ownerKey) rfl b0 f.vertex (by simp [b0,aux,hx0])\n  let b2:Stack→List Bool:=Function.update b1 (aux .sourceKey) []\n  have h1:Runs program (f.packet.length+1) (pc 1) b1 (pc 2) b2:=\n    drain_loop (pc 1) (pc 2) (aux .sourceKey) rfl b1 f.packet (by simp [b0,b1,aux,hx1])\n  let b3:Stack→List Bool:=Function.update b2 (aux .slotWord) []\n  have h2:Runs program (f.slot.length+1) (pc 2) b2 (pc 3) b3:=\n    drain_loop (pc 2) (pc 3) (aux .slotWord) rfl b2 f.slot (by simp [b0,b1,b2,aux,hx2])\n  let b4:Stack→List Bool:=Function.update b3 (aux .edgeWord) []\n  have h3:Runs program (f.edge.length+1) (pc 3) b3 (pc 4) b4:=\n    drain_loop (pc 3) (pc 4) (aux .edgeWord) rfl b3 f.edge (by simp [b0,b1,b2,b3,aux,hx3])\n  let b5:Stack→List Bool:=Function.update b4 (aux .sideWord) []\n  have h4:Runs program (f.side.length+1) (pc 4) b4 (pc 5) b5:=\n    drain_loop (pc 4) (pc 5) (aux .sideWord) rfl b4 f.side (by simp [b0,b1,b2,b3,b4,aux,hx4])\n  have hwhole:=join h0 (join h1 (join h2 (join h3 h4)))\n  have ht:(f.vertex.length+1)+(f.packet.length+1)+(f.slot.length+1)+(f.edge.length+1)+(f.side.length+1)=timeBound f:=by dsimp only [timeBound];omega\n  simpa only [←ht,Nat.add_assoc,result,b0,b1,b2,b3,b4,b5] using hwhole\n/-- Every actual raw-field tape is empty at the next endpoint visit. -/\ntheorem result_role (before:Stack→List Bool) (i:Fin 5):result before (role i)=[]:=by fin_cases i <;> rfl\n/-- All roles outside these five tapes retain their actual bytes. -/\ntheorem result_other (before:Stack→List Bool) (k:Stack) (h:∀i,role i≠k):result before k=before k:=by\n  have h0:=Ne.symm (h 0)\n  have h1:=Ne.symm (h 1)\n  have h2:=Ne.symm (h 2)\n  have h3:=Ne.symm (h 3)\n  have h4:=Ne.symm (h 4)\n  simp only [role] at h0 h1 h2 h3 h4\n  simp only [result,Function.update_of_ne h4,Function.update_of_ne h3,\n    Function.update_of_ne h2,Function.update_of_ne h1,Function.update_of_ne h0]\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketCleanup\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketConvertView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketConvert\n/-! # Exact postconversion reuse boundary and retained physical source caches -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketConvertView\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryBucketConvert\nnamespace Reuse\nexport SemiprimeD1StackChildGroupFactoryBucketReuse (role result_role result_other)\nend Reuse\n/-- The actual twelve converter words are among the actual fifteen erased roles. -/\ndef ordinalIndex:O.Stack→Fin 15\n  | .bank=>3 | .reader=>4 | .word=>5 | .fieldScratch=>6 | .valid=>7 | .copyScratch=>8\n  | .digits=>9 | .unaryScratch=>10 | .unary=>11 | .logScratch=>12 | .history=>13 | .output=>14\n/-- Exact literal role identity, not a supplied mapping between input records. -/\ntheorem ordinalIndex_role (k:O.Stack):Reuse.role (ordinalIndex k)=ordinal k:=by cases k <;> rfl\n/-- Complete actual conversion retains every physical word outside its twelve-role bank. -/\ntheorem converted_other (before:Stack→List Bool) (words:List (List Bool)) (k:Stack)\n    (h:∀j,ordinal j≠k):converted before words k=before k:=by\n  rw [converted, (SemiprimeD1StackChildGroupFactoryCalls.withOrdinal_rel _ _).2 k h]\n  exact Function.update_of_ne (Ne.symm (h .bank)) _ _\n/-- Every explicitly erased packet/converter role is physically empty. -/\ntheorem result_role (before:Stack→List Bool) (packet children:List Bool) (words:List (List Bool)) (j:Fin 15):\n    result before packet children words (Reuse.role j)=[]:=Reuse.result_role _ _\n/-- All caller words outside the fifteen actually drained roles and the actual bucket log are retained. -/\ntheorem result_other (before:Stack→List Bool) (packet children:List Bool) (words:List (List Bool)) (k:Stack)\n    (hf:∀j,Reuse.role j≠k) (hh:k≠aux .factorHistory):result before packet children words k=before k:=by\n  rw [result,Reuse.result_other _ _ hf,logged,Function.update_of_ne hh]\n  exact converted_other _ _ k (by intro j;rw [←ordinalIndex_role j];exact hf _)\n/-- All twelve actual converter tapes are really empty, including retained bank and unary output. -/\ntheorem result_ordinal (before:Stack→List Bool) (packet children:List Bool) (words:List (List Bool)) (k:O.Stack):\n    result before packet children words (ordinal k)=[]:=by\n  rw [←ordinalIndex_role k]\n  exact result_role _ _ _ _ _\n/-- Exact actual bucket record in newest-first physical history, with all previous buckets retained. -/\ntheorem result_factorHistory (before:Stack→List Bool) (packet children:List Bool) (words:List (List Bool)):\n    result before packet children words (aux .factorHistory)=\n      (Record.row packet children (Ordinal.result words)).reverse++before (aux .factorHistory):=by\n  rw [result,Reuse.result_other _ _ (by intro j;fin_cases j <;> decide),logged,Function.update_self]\n  rw [converted_other _ _ _ (by intro k;cases k <;> decide)]\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketConvertView\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketEmit":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketParse\n/-! # Actual selected bucket record and fresh-global port emission\nThe six-field child record preserves all five original raw fields and appends\nits actual current binary child-global position. Both histories are physical.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketEmit\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Actual child endpoint: original five raw fields plus fresh binary global ID. -/\ndef payload (e:Endpoint) (position:List Bool):List Bool:=\n  frame e.vertex (frame e.packet (frame e.slot (frame e.edge (frame e.side (frame position [])))))\n/-- Actual child endpoint vector record. -/\ndef row (e:Endpoint) (position:List Bool):List Bool:=true::frame (payload e position) []\n/-- Actual binary port record, to be fed to the real ordinal converter later. -/\ndef portRow (position:List Bool):List Bool:=true::frame position []\n/-- Complete actual postbank, preserving all raw source fields. -/\ndef result (before:Stack→List Bool) (e:Endpoint) (position:List Bool):Stack→List Bool:=\n  Function.update (Function.update before (aux .bucketHistory) ((row e position).reverse++before (aux .bucketHistory)))\n    (aux .portHistory) ((portRow position).reverse++before (aux .portHistory))\n/-- Every preserving frame, real tag/reversal and actual temporary-payload drain. -/\ndef timeBound (e:Endpoint) (position:List Bool):Nat:=\n  (6*position.length+5)+(6*e.side.length+5)+(6*e.edge.length+5)+(6*e.slot.length+5)+\n  (6*e.packet.length+5)+(6*e.vertex.length+5)+(6*(payload e position).length+5)+1+\n  (2*(row e position).length+3)+((payload e position).length+1)+\n  (6*position.length+5)+1+(2*(portRow position).length+3)\n/-- The actual matched branch emits bytes and a port; no row builder is a runtime operation. -/\ntheorem source_trace (before:Stack→List Bool) (e:Endpoint) (position:List Bool)\n    (hv:before (aux .ownerKey)=e.vertex) (hp:before (aux .sourceKey)=e.packet)\n    (hs:before (aux .slotWord)=e.slot) (he:before (aux .edgeWord)=e.edge)\n    (hside:before (aux .sideWord)=e.side) (hpos:before (aux .globalPosition)=position)\n    (hr:before (aux .rowBuffer)=[]) (hb:before (aux .frameBuffer)=[])\n    (hc:before (aux .copyScratch)=[]):\n    Runs program (timeBound e position) (.local 7 12) before (.local 7 25) (result before e position):=by\n  simp only [aux] at hv hp hs he hside hpos hr hb hc\n  let b0:=before\n  let b1:Stack→List Bool:=Function.update b0 (aux .rowBuffer) (frame position [])\n  have h0:Runs program (6*(position).length+5) (.local 7 12) b0 (.local 7 13) b1:=\n    frame_call 10 (.local 7 12) (.local 7 13) rfl b0 position [] (by simp [b0,aux,frameStack,framePorts,hpos]) (by simp [b0,aux,frameStack,framePorts,hr]) (by simp [b0,aux,frameStack,hc])\n  let b2:Stack→List Bool:=Function.update b1 (aux .rowBuffer) (frame e.side (frame position []))\n  have h1:Runs program (6*(e.side).length+5) (.local 7 13) b1 (.local 7 14) b2:=\n    frame_call 3 (.local 7 13) (.local 7 14) rfl b1 e.side (frame position []) (by simp [b0,b1,aux,frameStack,framePorts,hside]) (by simp [b0,b1,aux,frameStack,framePorts]) (by simp [b0,b1,aux,frameStack,hc])\n  let b3:Stack→List Bool:=Function.update b2 (aux .rowBuffer) (frame e.edge (frame e.side (frame position [])))\n  have h2:Runs program (6*(e.edge).length+5) (.local 7 14) b2 (.local 7 15) b3:=\n    frame_call 4 (.local 7 14) (.local 7 15) rfl b2 e.edge (frame e.side (frame position [])) (by simp [b0,b1,b2,aux,frameStack,framePorts,he]) (by simp [b0,b1,b2,aux,frameStack,framePorts]) (by simp [b0,b1,b2,aux,frameStack,hc])\n  let b4:Stack→List Bool:=Function.update b3 (aux .rowBuffer) (frame e.slot (frame e.edge (frame e.side (frame position []))))\n  have h3:Runs program (6*(e.slot).length+5) (.local 7 15) b3 (.local 7 16) b4:=\n    frame_call 7 (.local 7 15) (.local 7 16) rfl b3 e.slot (frame e.edge (frame e.side (frame position []))) (by simp [b0,b1,b2,b3,aux,frameStack,framePorts,hs]) (by simp [b0,b1,b2,b3,aux,frameStack,framePorts]) (by simp [b0,b1,b2,b3,aux,frameStack,hc])\n  let b5:Stack→List Bool:=Function.update b4 (aux .rowBuffer) (frame e.packet (frame e.slot (frame e.edge (frame e.side (frame position [])))))\n  have h4:Runs program (6*(e.packet).length+5) (.local 7 16) b4 (.local 7 17) b5:=\n    frame_call 11 (.local 7 16) (.local 7 17) rfl b4 e.packet (frame e.slot (frame e.edge (frame e.side (frame position [])))) (by simp [b0,b1,b2,b3,b4,aux,frameStack,framePorts,hp]) (by simp [b0,b1,b2,b3,b4,aux,frameStack,framePorts]) (by simp [b0,b1,b2,b3,b4,aux,frameStack,hc])\n  let b6:Stack→List Bool:=Function.update b5 (aux .rowBuffer) (frame e.vertex (frame e.packet (frame e.slot (frame e.edge (frame e.side (frame position []))))))\n  have h5:Runs program (6*(e.vertex).length+5) (.local 7 17) b5 (.local 7 18) b6:=\n    frame_call 5 (.local 7 17) (.local 7 18) rfl b5 e.vertex (frame e.packet (frame e.slot (frame e.edge (frame e.side (frame position []))))) (by simp [b0,b1,b2,b3,b4,b5,aux,frameStack,framePorts,hv]) (by simp [b0,b1,b2,b3,b4,b5,aux,frameStack,framePorts]) (by simp [b0,b1,b2,b3,b4,b5,aux,frameStack,hc])\n  let b7:Stack→List Bool:=Function.update b6 (aux .frameBuffer) (frame (frame e.vertex (frame e.packet (frame e.slot (frame e.edge (frame e.side (frame position [])))))) [])\n  have h6:Runs program (6*((frame e.vertex (frame e.packet (frame e.slot (frame e.edge (frame e.side (frame position []))))))).length+5) (.local 7 18) b6 (.local 7 19) b7:=\n    frame_call 6 (.local 7 18) (.local 7 19) rfl b6 (frame e.vertex (frame e.packet (frame e.slot (frame e.edge (frame e.side (frame position [])))))) [] (by simp [b0,b1,b2,b3,b4,b5,b6,aux,frameStack,framePorts]) (by simp [b0,b1,b2,b3,b4,b5,b6,aux,frameStack,framePorts,hb]) (by simp [b0,b1,b2,b3,b4,b5,b6,aux,frameStack,hc])\n  let b8:Stack→List Bool:=Function.update b7 (aux .frameBuffer) (true::(frame (frame e.vertex (frame e.packet (frame e.slot (frame e.edge (frame e.side (frame position [])))))) []))\n  have h7p:b7 (aux .frameBuffer)=(frame (frame e.vertex (frame e.packet (frame e.slot (frame e.edge (frame e.side (frame position [])))))) []):=(by simp [b0,b1,b2,b3,b4,b5,b6,b7,aux])\n  have h7a:=push_run (.local 7 19) (.local 7 20) (aux .frameBuffer) true b7 rfl\n  have h7:Runs program 1 (.local 7 19) b7 (.local 7 20) b8:=by simpa only [h7p,b8] using h7a\n  let b9:Stack→List Bool:=Function.update (Function.update b8 (aux .frameBuffer) []) (aux .bucketHistory) ((row e position).reverse++(before (aux .bucketHistory)))\n  have h8:Runs program (2*(row e position).length+3) (.local 7 20) b8 (.local 7 21) b9:=\n    reverse_call 5 (.local 7 20) (.local 7 21) rfl b8 (row e position) (before (aux .bucketHistory)) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,payload,row,aux,reverseStack,reversePorts]) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,aux,reverseStack,reversePorts])\n  let b10:Stack→List Bool:=Function.update b9 (aux .rowBuffer) []\n  have h9:Runs program ((payload e position).length+1) (.local 7 21) b9 (.local 7 22) b10:=\n    drain_loop (.local 7 21) (.local 7 22) (aux .rowBuffer) rfl b9 (payload e position) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,payload,row,aux])\n  let b11:Stack→List Bool:=Function.update b10 (aux .frameBuffer) (frame position [])\n  have h10:Runs program (6*(position).length+5) (.local 7 22) b10 (.local 7 23) b11:=\n    frame_call 12 (.local 7 22) (.local 7 23) rfl b10 position [] (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,payload,row,aux,frameStack,framePorts,hpos]) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,payload,row,aux,frameStack,framePorts]) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,payload,row,aux,frameStack,hc])\n  let b12:Stack→List Bool:=Function.update b11 (aux .frameBuffer) (true::(frame position []))\n  have h11p:b11 (aux .frameBuffer)=(frame position []):=(by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,payload,row,aux])\n  have h11a:=push_run (.local 7 23) (.local 7 24) (aux .frameBuffer) true b11 rfl\n  have h11:Runs program 1 (.local 7 23) b11 (.local 7 24) b12:=by simpa only [h11p,b12] using h11a\n  let b13:Stack→List Bool:=Function.update (Function.update b12 (aux .frameBuffer) []) (aux .portHistory) ((portRow position).reverse++(before (aux .portHistory)))\n  have h12:Runs program (2*(portRow position).length+3) (.local 7 24) b12 (.local 7 25) b13:=\n    reverse_call 6 (.local 7 24) (.local 7 25) rfl b12 (portRow position) (before (aux .portHistory)) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,payload,row,portRow,aux,reverseStack,reversePorts]) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,payload,row,aux,reverseStack,reversePorts])\n  have hout:b13=result before e position:=by\n    funext k\n    rcases k with k|k|k|k|k|k\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,payload,row,portRow,aux,result]\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,payload,row,portRow,aux,result]\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,payload,row,portRow,aux,result]\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,payload,row,portRow,aux,result]\n    · simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,payload,row,portRow,aux,result]\n    · cases k <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,payload,row,portRow,aux,hv,hp,hs,he,hside,hpos,hr,hb,hc,result]\n  have hwhole:=join h0 (join h1 (join h2 (join h3 (join h4 (join h5 (join h6 (join h7 (join h8 (join h9 (join h10 (join h11 (h12))))))))))))\n  rw [hout] at hwhole\n  simpa only [timeBound,payload,row,portRow,Nat.add_assoc] using hwhole\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketEmit\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryPrimitives\n/-! # Actual included source calls with complete115-word postconditions\nThe bank constructors describe physical postconditions only. They are not\ninstructions, input suppliers, or operations in the fixed program control.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryCalls\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryWiringFacts SemiprimeD1StackProcedureTrace\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel)\nend Link\n/-- Complete actual lookup subbank, preserving every other physical word. -/\ndef withLookup (before:Stack→List Bool) (d:L.Stack→List Bool):Stack→List Bool\n  | .inl k=>d k\n  | k=>before k\n/-- Exact included subbank and all untouched115-role cells. -/\ntheorem withLookup_rel (before:Stack→List Bool) (d:L.Stack→List Bool):\n    Link.DataRel lookup before d (withLookup before d):=by\n  constructor\n  · intro k;rfl\n  · intro k hk\n    rcases k with k|k\n    · exact False.elim ((hk k) rfl)\n    · rfl\n/-- Complete actual rows subbank, preserving every other physical word. -/\ndef withRows (before:Stack→List Bool) (d:R.Stack→List Bool):Stack→List Bool\n  | .inr (.inl k)=>d k\n  | k=>before k\n/-- Exact included subbank and all untouched115-role cells. -/\ntheorem withRows_rel (before:Stack→List Bool) (d:R.Stack→List Bool):\n    Link.DataRel rows before d (withRows before d):=by\n  constructor\n  · intro k;rfl\n  · intro k hk\n    rcases k with k|k|k\n    · rfl\n    · exact False.elim ((hk k) rfl)\n    · rfl\n/-- Complete actual arithmetic subbank, preserving every other physical word. -/\ndef withArithmetic (before:Stack→List Bool) (d:A.Stack→List Bool):Stack→List Bool\n  | .inr (.inr (.inl k))=>d k\n  | k=>before k\n/-- Exact included subbank and all untouched115-role cells. -/\ntheorem withArithmetic_rel (before:Stack→List Bool) (d:A.Stack→List Bool):\n    Link.DataRel arithmetic before d (withArithmetic before d):=by\n  constructor\n  · intro k;rfl\n  · intro k hk\n    rcases k with k|k|k|k\n    · rfl\n    · rfl\n    · exact False.elim ((hk k) rfl)\n    · rfl\n/-- Complete actual ordinal subbank, preserving every other physical word. -/\ndef withOrdinal (before:Stack→List Bool) (d:O.Stack→List Bool):Stack→List Bool\n  | .inr (.inr (.inr (.inr (.inl k))))=>d k\n  | k=>before k\n/-- Exact included subbank and all untouched115-role cells. -/\ntheorem withOrdinal_rel (before:Stack→List Bool) (d:O.Stack→List Bool):\n    Link.DataRel ordinal before d (withOrdinal before d):=by\n  constructor\n  · intro k;rfl\n  · intro k hk\n    rcases k with k|k|k|k|k|k\n    · rfl\n    · rfl\n    · rfl\n    · rfl\n    · exact False.elim ((hk k) rfl)\n    · rfl\n/-- Whole physical first-match lookup; the returned value is computed from acquired rows. -/\ntheorem lookup_call (pc next:Label) (hc:program pc=.call (.lookup .loop) next)\n    (before:Stack→List Bool) (query:List Bool) (entries:List (List Bool×List Bool)) (tail:List Bool)\n    (hp:∀k,before (lookup k)=(SemiprimeD1StackOwnerLookup.initial query\n      (SemiprimeD1StackOwnerLookup.records entries tail)).data k):\n    Runs program (SemiprimeD1StackOwnerLookupExecution.loopTime query entries+2) pc before next\n      (withLookup before (SemiprimeD1StackOwnerLookup.done query entries tail).data):=by\n  have h:=SemiprimeD1StackProcedureCallsTrace.included_call program lookup Label.lookup lookup_injective\n    L.program .loop (fun _=>rfl) pc next hc _ _ _ before _ rfl rfl rfl rfl\n    (SemiprimeD1StackOwnerLookupExecution.source_run query entries tail)\n    ⟨hp,fun _ _=>rfl⟩ (withLookup_rel before _)\n  simpa only [Nat.add_assoc] using h\n/-- Both catalogue rows are acquired by the real nineteen-role paired-row source. -/\ntheorem rows_call (pc next:Label) (hc:program pc=.call (.rows (.local .start)) next)\n    (before:Stack→List Bool) (owner factor:List Bool) (entries:List (List Bool×List Bool))\n    (left right:List (List Bool))\n    (hl:SemiprimeD1StackPacketRowsEncoding.present owner entries=true)\n    (hr:SemiprimeD1StackPacketRowsEncoding.present factor entries=true)\n    (hleft:SemiprimeD1StackPacketRowsAcquire.payload owner entries=SemiprimeD1PacketRows.serialize left)\n    (hright:SemiprimeD1StackPacketRowsAcquire.payload factor entries=SemiprimeD1PacketRows.serialize right)\n    (hlen:left.length=right.length)\n    (hp:∀k,before (rows k)=(SemiprimeD1StackPacketRows.initial\n      (SemiprimeSourceHistogramKeyBits.frame owner factor)\n      (SemiprimeD1StackOwnerLookup.records entries [])).data k):\n    ∃t≤SemiprimeD1StackPacketRowsExecution.timeBound owner factor entries left right+1,\n      Runs program t pc before next (withRows before (SemiprimeD1StackPacketRowsExecution.result\n        (SemiprimeSourceHistogramKeyBits.frame owner factor)\n        (SemiprimeD1StackOwnerLookup.records entries []) left right)):=by\n  obtain ⟨t,ht,hs⟩:=SemiprimeD1StackPacketRowsExecution.source_run owner factor entries left right\n    hl hr hleft hright hlen\n  refine ⟨t+1,by omega,?_⟩\n  exact SemiprimeD1StackProcedureCallsTrace.included_call program rows Label.rows rows_injective\n    R.program (.local .start) (fun _=>rfl) pc next hc t _ _ before _ rfl rfl rfl rfl hs\n    ⟨hp,fun _ _=>rfl⟩ (withRows_rel before _)\n/-- Real numeric equality consumes both padded operands and physically cleans its workspace. -/\ntheorem equal_call (pc next:Label) (hc:program pc=.call (.equal .loop) next)\n    (before:Stack→List Bool) (left right:List Bool)\n    (hp:∀k,before (arithmetic k)=SemiprimeD1StackAdder.store left right [] [] k):\n    Runs program (SemiprimeD1StackWordEqualExecution.executionTime left right+1) pc before next\n      (withArithmetic before (SemiprimeD1StackAdder.store [] [] []\n        [decide (SemiprimeBitArithmetic.bitValue left=SemiprimeBitArithmetic.bitValue right)])):=by\n  exact included_call program arithmetic Label.equal arithmetic_injective E.code .loop\n    (fun _=>rfl) pc next hc _ _ _ before _ rfl rfl\n    (SemiprimeD1StackWordEqualExecution.source_run left right none)\n    ⟨hp,fun _ _=>rfl⟩ (withArithmetic_rel before _)\n/-- Real full binary addition; no unary materialization of a binary counter value. -/\ntheorem add_call (pc next:Label) (hc:program pc=.call (.add (.start false)) next)\n    (before:Stack→List Bool) (left right:List Bool)\n    (hp:∀k,before (arithmetic k)=SemiprimeD1StackAdder.store left right [] [] k):\n    Runs program (3*(max left.length right.length+1)+\n      2*(SemiprimeBitArithmetic.addBits left right false).bits.length+3) pc before next\n      (withArithmetic before (SemiprimeD1StackAdder.store [] [] []\n        (SemiprimeBitArithmetic.addBits left right false).bits)):=by\n  have h:=included_call program arithmetic Label.add arithmetic_injective A.code (.start false)\n    (fun _=>rfl) pc next hc _ _ _ before _ rfl rfl\n    (SemiprimeD1StackAdderExecution.source_run left right false)\n    ⟨hp,fun _ _=>rfl⟩ (withArithmetic_rel before _)\n  simpa [Nat.add_assoc,SemiprimeD1StackAdder.state] using h\n/-- Actual binary-port to unary-port stream, with its value-sensitive own clock. -/\ntheorem ordinal_call (pc next:Label) (hc:program pc=.call (.ordinal (.control .start)) next)\n    (before:Stack→List Bool) (words:List (List Bool))\n    (hp:∀k,before (ordinal k)=(SemiprimeD1StackPortOrdinalStream.initial\n      (SemiprimeD1TensorTapeCodec.vectorBits words)).data k):\n    ∃t≤SemiprimeD1StackPortOrdinalStreamExecution.timeBound words+1,\n      Runs program t pc before next (withOrdinal before\n        (SemiprimeD1StackPortOrdinalStreamExecution.done words).data):=by\n  obtain ⟨t,ht,hs⟩:=SemiprimeD1StackPortOrdinalStreamExecution.source_run words\n  refine ⟨t+1,by omega,?_⟩\n  exact SemiprimeD1StackProcedureCallsTrace.included_call program ordinal Label.ordinal ordinal_injective\n    O.program (.control .start) (fun _=>rfl) pc next hc t _ _ before _ rfl rfl rfl rfl hs\n    ⟨hp,fun _ _=>rfl⟩ (withOrdinal_rel before _)\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryCalls\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointOperationBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryAcquisitionByteBounds\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationMapBounds\n/-! # Own endpoint parser/logger/map-lookup clocks from actual acquired bytes\nBoth possible physical endpoint sides are accounted for, including inactive\nlookups and full eleven-role cleanup. No native reader clock is transported.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointOperationBounds\nnamespace P\nexport SemiprimeD1StackChildGroupFactoryEndpointParse (Fields payload timeBound)\nend P\nnamespace Raw\nexport SemiprimeD1StackChildGroupFactoryAcquisitionByteBounds (fieldBytes)\nend Raw\nnamespace Old\nexport SemiprimeD1StackChildGroupFactoryEndpointOldLog (oldPoint row timeBound)\nend Old\nnamespace Emit\nexport SemiprimeD1StackChildGroupFactoryEndpointEmit (endpoint row timeBound)\nend Emit\nnamespace Test\nexport SemiprimeD1StackChildGroupFactoryEndpointFlag (timeBound)\nend Test\nnamespace Side\nexport SemiprimeD1StackChildGroupFactoryEndpointSide (timeBound)\nend Side\nnamespace Occ\nexport SemiprimeD1StackChildGroupFactoryEndpointOccurrence (timeBound)\nend Occ\nnamespace Map\nexport SemiprimeD1StackOwnerLookup (records)\nend Map\n/-- All actual paired Field calls, validity pops and complete current payload have a linear byte cost. -/\ntheorem parse_time (f:P.Fields):P.timeBound f≤1000*Raw.fieldBytes f:=by\n  simp only [P.timeBound,P.payload,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil,\n    List.length_cons,Raw.fieldBytes]\n  omega\n/-- Every old endpoint is physically logged, including inactive and isolated-side metadata. -/\ntheorem old_log_time (owner:Bool) (v edge:List Bool):Old.timeBound owner v edge≤1000*(v.length+edge.length+1):=by\n  simp only [Old.timeBound,Old.oldPoint,Old.row,SemiprimeSourceHistogramKeyBits.frame_length,\n    List.length_nil,List.length_cons]\n  omega\n/-- An active endpoint's actual five-field row logger is linear in the retained source fields. -/\ntheorem emit_time (owner:Bool) (v packet slot edge:List Bool):\n    Emit.timeBound owner v packet slot edge≤1000*(v.length+packet.length+slot.length+edge.length+1):=by\n  simp only [Emit.timeBound,Emit.endpoint,Emit.row,SemiprimeSourceHistogramKeyBits.frame_length,\n    List.length_nil,List.length_cons]\n  omega\n/-- Actual numeric lookup, both copies and full eleven-role cleanup have a physical-byte product bound. -/\ntheorem lookup_time (query:List Bool) (entries:List (List Bool×List Bool)) (unread:List Bool)\n    (hu:unread.length≤(Map.records entries []).length):\n    Test.timeBound query (Map.records entries []) entries unread≤\n      1000*(query.length+1)*((Map.records entries []).length+1):=by\n  have ht:=SemiprimeD1StackOwnerLookupBounds.time_le query entries\n  dsimp only [SemiprimeD1StackOwnerLookupBounds.runBound] at ht\n  dsimp only [Test.timeBound]\n  nlinarith\n/-- The actual tested side is covered regardless of its computed activation branch. -/\ntheorem side_time (owner flag:Bool) (v packet slot edge:List Bool)\n    (entries:List (List Bool×List Bool)) (unread:List Bool)\n    (hu:unread.length≤(Map.records entries []).length):\n    Side.timeBound owner flag v packet slot edge (Map.records entries []) unread entries≤\n      10000*(v.length+packet.length+slot.length+edge.length+1)*((Map.records entries []).length+1):=by\n  have ho:=old_log_time owner v edge\n  have he:=emit_time owner v packet slot edge\n  have ht:=lookup_time v entries unread hu\n  cases flag <;> simp only [Side.timeBound,Bool.false_eq_true,ite_false,ite_true] <;> nlinarith\n/-- Complete original occurrence acquisition pays BOTH actual endpoint lookups, possible logs and raw drains. -/\ntheorem occurrence_time (ownerFlag factorFlag:Bool) (f:P.Fields) (entries:List (List Bool×List Bool))\n    (ownerUnread factorUnread:List Bool)\n    (ho:ownerUnread.length≤(Map.records entries []).length)\n    (hf:factorUnread.length≤(Map.records entries []).length):\n    Occ.timeBound ownerFlag factorFlag f (Map.records entries []) ownerUnread factorUnread entries≤\n      100000*Raw.fieldBytes f*((Map.records entries []).length+1):=by\n  have hp:=parse_time f\n  have hl:=side_time true ownerFlag f.owner f.packet f.slot f.edge entries ownerUnread ho\n  have hr:=side_time false factorFlag f.factor f.packet f.slot f.edge entries factorUnread hf\n  dsimp only [Occ.timeBound,Raw.fieldBytes,SemiprimeD1StackChildGroupFactoryEndpointCleanup.timeBound] at hp ⊢\n  nlinarith\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryEndpointOperationBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryForwardBucketsBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryInputCapacities\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketsBounds\n/-! # Whole actual activation/endpoint/bucket prefix has one fixed quartic rate\nThis entire prefix is acquired once by its literal source. Its stopped physical\nbank is bounded from that SAME trace, rather than from any recursive child's\nruntime or a native acquisition report clock.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryForwardBucketsBounds\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackProcedureTrace\nnamespace F\nexport SemiprimeD1StackChildGroupFactoryForwardBucketsSource (endpoints result timeBound source_trace)\nend F\nnamespace Cap\nexport SemiprimeD1StackChildGroupFactoryInputCapacities\n  (endpoint_bytes endpoints_count packets_count packet_bytes packet_tape)\nexport SemiprimeD1StackChildGroupFactoryForwardBounds (capacity)\nexport SemiprimeD1StackChildGroupFactoryTraceBounds (Valid inputBytes input_word_le)\nend Cap\nnamespace P\nexport SemiprimeD1StackChildGroupFactoryEndpointParse (Fields)\nend P\n/-- Actual global-zero bucket source has a fixed quartic bound even for repeated prepared packets. -/\ntheorem bucket_time (before:Stack→List Bool) (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool))\n    (fields:List P.Fields) (hv:Cap.Valid i a coordinate ids packets fields):\n    SemiprimeD1StackChildGroupFactoryBucketsSource.timeBound before packets (F.endpoints i a coordinate ids fields) []≤\n      1000000000000*(Cap.capacity i+1)^4:=by\n  let S:=Cap.capacity i\n  let es:=F.endpoints i a coordinate ids fields\n  have he:es.length≤S:=Cap.endpoints_count i a coordinate ids packets fields hv\n  have hk:packets.length≤S:=Cap.packets_count i a coordinate ids packets fields hv\n  have htape:(SemiprimeD1TensorTapeCodec.vectorBits packets).length≤S:=Cap.packet_tape i a coordinate ids packets fields hv\n  have hm:packets.length*es.length≤S*S:=Nat.mul_le_mul hk he\n  have h:=SemiprimeD1StackChildGroupFactoryBucketsBounds.source_time before packets es [] S S\n    (2*(packets.length*es.length)) (packets.length*es.length)\n    (Cap.endpoint_bytes i a coordinate ids packets fields hv) (Cap.packet_bytes i a coordinate ids packets fields hv)\n    (by simp only [List.length_nil,Nat.zero_add,le_refl])\n    (by simp only [SemiprimeBitArithmetic.bitValue,Nat.zero_add,le_refl])\n  have hsize:S+S+2*(packets.length*es.length)+packets.length*es.length+\n      (SemiprimeD1TensorTapeCodec.vectorBits packets).length+1≤10*(S+1)^2:=by nlinarith\n  have hmajor:1000000000*(S+S+2*(packets.length*es.length)+packets.length*es.length+\n      (SemiprimeD1TensorTapeCodec.vectorBits packets).length+1)*(es.length+1)*(packets.length+1)≤\n      1000000000*(10*(S+1)^2)*(S+1)*(S+1):=by gcongr\n  have heq:1000000000*(10*(S+1)^2)*(S+1)*(S+1)=10000000000*(S+1)^4:=by ring\n  change SemiprimeD1StackChildGroupFactoryBucketsSource.timeBound before packets es []≤_\n  rw [heq] at hmajor\n  nlinarith\n/-- Whole actual frontdoor through chronological buckets has fixed coefficient/degree before every input. -/\ntheorem timeBound_le (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List P.Fields)\n    (hv:Cap.Valid i a coordinate ids packets fields):\n    F.timeBound i a coordinate ids packets fields≤10000000000000*(Cap.capacity i+1)^4:=by\n  have hforward:=SemiprimeD1StackChildGroupFactoryForwardBounds.timeBound_le i a coordinate ids fields\n    hv.id_members hv.environment hv.catalogue hv.colour hv.count hv.pairs hv.placements hv.domain\n  have hb:=bucket_time (SemiprimeD1StackChildGroupFactoryForwardSource.result i a coordinate ids fields)\n    i a coordinate ids packets fields hv\n  dsimp only [F.timeBound]\n  nlinarith\n/-- ALL115 actually stopped words are bounded from this SAME successful prefix, paid once. -/\ntheorem result_word_le (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List P.Fields)\n    (hv:Cap.Valid i a coordinate ids packets fields):\n    ∀k,(F.result i a coordinate ids packets fields k).length≤100000000000000*(Cap.capacity i+1)^4:=by\n  obtain ⟨t,ht,hr⟩:=F.source_trace i a coordinate ids packets fields hv.id_members hv.environment\n    hv.catalogue hv.colour hv.count hv.pairs hv.placements hv.domain hv.packet_tape\n  obtain ⟨finish,hfinish,hat⟩:=hr [] (initial i) ⟨rfl,rfl,rfl⟩\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program t (Cap.inputBytes i) (initial i) finish\n    (Cap.input_word_le i) hfinish\n  rw [hat.2.1] at hd\n  have hc:=timeBound_le i a coordinate ids packets fields hv\n  have hi:Cap.inputBytes i≤Cap.capacity i:=by dsimp only [Cap.capacity];omega\n  intro k\n  have h:=hd k\n  have hp:Cap.capacity i≤(Cap.capacity i+1)^4:=\n    (Nat.le_succ _).trans (Nat.le_pow (by decide:0<(4:Nat)))\n  nlinarith\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryForwardBucketsBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryInputCapacities":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryForwardBounds\n/-! # One actual thirteen-input capacity bounds all acquired structural counts\nThis is a proof estimate only. No bound, count, key, mode or decoded record\nenters the finite controller. All source high-zero padding is charged in its\nliteral tape lengths; original numeric N never enters this metadata domain.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryInputCapacities\nopen SemiprimeD1StackChildGroupFactory\nnamespace V\nexport SemiprimeD1StackChildGroupFactoryTraceBounds (Valid inputBytes)\nend V\nnamespace S\nexport SemiprimeD1StackChildGroupFactoryForwardBounds (capacity)\nend S\nnamespace F\nexport SemiprimeD1StackChildGroupFactoryForwardSource (rows)\nexport SemiprimeD1StackChildGroupFactoryForwardBucketsSource (endpoints)\nend F\nnamespace Raw\nexport SemiprimeD1StackChildGroupFactoryAcquisitionByteBounds\n  (fieldBytes field_le_tapes fields_count packet_count packet_word selected_count selected_bytes old_count)\nend Raw\nnamespace P\nexport SemiprimeD1StackChildGroupFactoryEndpointParse (Fields)\nend P\nnamespace Code\nexport SemiprimeD1StackChildGroupFactoryCatalogueCodecs (oldPoints)\nend Code\n/-- The positive common byte capacity is fixed by the actual physical input lengths. -/\ntheorem capacity_pos (i:Inputs):1≤S.capacity i:=by dsimp only [S.capacity];omega\n/-- Original owner/factor markers, including isolated vertices, are physically charged. -/\ntheorem vertices (i:Inputs):i.owners.length+i.factors.length≤S.capacity i:=by\n  dsimp only [S.capacity,V.inputBytes];omega\n/-- Every decoded occurrence field is charged by its two actual retained source tapes. -/\ntheorem field_bytes (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List P.Fields)\n    (hv:V.Valid i a coordinate ids packets fields):∀f∈fields,Raw.fieldBytes f≤V.inputBytes i:=by\n  intro f hf\n  have h:=Raw.field_le_tapes fields f hf\n  rw [←hv.pairs,←hv.placements] at h\n  dsimp only [V.inputBytes]\n  omega\n/-- The actual paired source cannot encode more original occurrences than its physical tape bytes. -/\ntheorem occurrences (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List P.Fields)\n    (hv:V.Valid i a coordinate ids packets fields):fields.length≤V.inputBytes i:=by\n  have h:=Raw.fields_count fields\n  rw [←hv.pairs] at h\n  dsimp only [V.inputBytes];omega\n/-- True computed endpoint count permits both sides and is paid before any packet duplication. -/\ntheorem endpoints_count (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List P.Fields)\n    (hv:V.Valid i a coordinate ids packets fields):(F.endpoints i a coordinate ids fields).length≤S.capacity i:=by\n  have h:=Raw.selected_count (F.rows i a coordinate ids fields)\n  have hc:=occurrences i a coordinate ids packets fields hv\n  simp only [F.rows,List.length_map] at h\n  change (F.endpoints i a coordinate ids fields).length≤_ at h\n  dsimp only [S.capacity]\n  omega\n/-- Every actually emitted endpoint preserves raw binary/source padding from real acquired fields. -/\ntheorem endpoint_bytes (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List P.Fields)\n    (hv:V.Valid i a coordinate ids packets fields):∀e∈F.endpoints i a coordinate ids fields,\n      SemiprimeD1StackChildGroupFactoryOperationBounds.endpointBytes e≤S.capacity i:=by\n  have hc:∀r∈F.rows i a coordinate ids fields,Raw.fieldBytes r.fields≤V.inputBytes i:=by\n    intro r hr\n    obtain ⟨f,hf,rfl⟩:=List.mem_map.mp hr\n    exact field_bytes i a coordinate ids packets fields hv f hf\n  have h:=Raw.selected_bytes (F.rows i a coordinate ids fields) (V.inputBytes i) hc\n  intro e he\n  have he':=h e he\n  dsimp only [S.capacity];omega\n/-- Every original old-side point remains present even if no activation side was selected. -/\ntheorem old_points (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List P.Fields)\n    (hv:V.Valid i a coordinate ids packets fields):\n    (Code.oldPoints (F.rows i a coordinate ids fields)).length≤S.capacity i:=by\n  rw [Raw.old_count]\n  have hc:=occurrences i a coordinate ids packets fields hv\n  simp only [F.rows,List.length_map]\n  dsimp only [S.capacity];omega\n/-- Actual packet records, including empty/repeated raw words, are charged to their original vector. -/\ntheorem packets_count (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List P.Fields)\n    (hv:V.Valid i a coordinate ids packets fields):packets.length≤S.capacity i:=by\n  have h:=Raw.packet_count packets\n  rw [←hv.packet_tape] at h\n  dsimp only [S.capacity,V.inputBytes];omega\n/-- Every retained raw packet word is physically present and paid; no literal-byte aliases are conflated. -/\ntheorem packet_bytes (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List P.Fields)\n    (hv:V.Valid i a coordinate ids packets fields):∀packet∈packets,packet.length≤S.capacity i:=by\n  intro packet hp\n  have h:=Raw.packet_word packets packet hp\n  rw [←hv.packet_tape] at h\n  dsimp only [S.capacity,V.inputBytes];omega\n/-- The one actual packet-vector copy is included in the same physical capacity. -/\ntheorem packet_tape (i:Inputs) (a coordinate:Nat) (ids packets:List (List Bool)) (fields:List P.Fields)\n    (hv:V.Valid i a coordinate ids packets fields):\n    (SemiprimeD1TensorTapeCodec.vectorBits packets).length≤S.capacity i:=by\n  rw [←hv.packet_tape]\n  dsimp only [S.capacity,V.inputBytes];omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryInputCapacities\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsInner\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketHeader\n/-! # Entire actual nested bucket filter for one old vertex\nEvery actual bucket header and child vector is scanned in exact packet-major\norder. Empty buckets remain real parsed records. No adjacency/order is supplied.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsLoop\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\nnamespace Inner\nexport SemiprimeD1StackChildGroupFactoryLeftPortsInner\n  (Child records portWords result timeBound source_trace result_reader result_other result_clean result_portHistory)\nend Inner\nnamespace Parse\nexport SemiprimeD1StackChildGroupFactoryChildParse (cleanRoles)\nend Parse\nnamespace Cleanup\nexport SemiprimeD1StackChildGroupFactoryChildCleanup (role)\nend Cleanup\nnamespace Header\nexport SemiprimeD1StackChildGroupFactoryBucketHeader (pc cleanRoles result timeBound source_trace)\nend Header\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Proof interpretation of an actual parsed three-field bucket, never an input host structure. -/\nstructure Bucket where\n  /-- Whole observed raw packet key, retaining its padding. -/\n  packet:List Bool\n  /-- Actual ordered acquired children of this packet. -/\n  children:List Inner.Child\n  /-- Actual unary canonical right-port tape. -/\n  ports:List Bool\n/-- Exact actual nested bucket payload. -/\ndef payload (b:Bucket):List Bool:=\n  SemiprimeD1StackChildGroupFactoryBucketRecord.payload b.packet (Inner.records b.children) b.ports\n/-- Actual outer bucket-vector grammar. -/\ndef records:List Bucket→List Bool\n  | []=>[false]\n  | b::bs=>true::frame (payload b) (records bs)\n/-- Exact actual left-port words in packet-major child order, retaining repeated prepared buckets. -/\ndef portWords:List Bucket→List Bool→List (List Bool)\n  | [],_=>[]\n  | b::bs,target=>Inner.portWords b.children target++portWords bs target\n/-- Actual parsed header boundary, before reading the child vector. -/\ndef head (before:Stack→List Bool) (b:Bucket) (tail:List Bool):Stack→List Bool:=\n  Header.result before (Inner.records b.children) tail\n/-- Complete actual one-bucket scan boundary. -/\ndef step (before:Stack→List Bool) (b:Bucket) (tail target:List Bool):Stack→List Bool:=\n  Inner.result b.children (head before b tail) target\n/-- Literal header parse/drains and the entire actual child scan. -/\ndef stepTime (b:Bucket) (target:List Bool):Nat:=\n  Header.timeBound b.packet (Inner.records b.children) b.ports+Inner.timeBound b.children target\n/-- Actual one-bucket source path including empty observed buckets. -/\ntheorem step_trace (before:Stack→List Bool) (b:Bucket) (tail target:List Bool)\n    (hi:before (aux .outerReader)=true::frame (payload b) tail)\n    (hh:∀k∈Header.cleanRoles,before k=[]) (hz:∀k∈Parse.cleanRoles,before k=[])\n    (ht:before (aux .vertexKey)=target) (hb:before (aux .frameBuffer)=[])\n    (hc:before (aux .copyScratch)=[]) (ha:∀k,before (arithmetic k)=[]):\n    Runs program (stepTime b target) (.local 9 7) before (.local 9 7) (step before b tail target):=by\n  have h0:=Header.source_trace false before b.packet (Inner.records b.children) b.ports tail hi hh\n  change Runs program _ (.local 9 7) before (.local 9 20) (head before b tail) at h0\n  have h1:=Inner.source_trace b.children (head before b tail) target rfl\n    (by simpa [head,Header.result,Parse.cleanRoles,aux,field] using hz)\n    (by simpa [head,Header.result,aux] using ht) (by simpa [head,Header.result,aux] using hb)\n    (by simpa [head,Header.result,aux] using hc) (by intro k;simpa [head,Header.result,aux,arithmetic] using ha k)\n  exact join h0 h1\n/-- Complete actual per-bucket retention outside real child fields, both readers and the port log. -/\ntheorem step_other (before:Stack→List Bool) (b:Bucket) (tail target:List Bool) (k:Stack)\n    (hf:∀j,Cleanup.role j≠k) (he:k≠aux .endpointReader) (ho:k≠aux .outerReader) (hp:k≠aux .portHistory):\n    step before b tail target k=before k:=by\n  rw [step,Inner.result_other _ _ _ k hf he hp]\n  simp only [head,Header.result,Function.update_of_ne he,Function.update_of_ne ho]\n/-- Actual outer suffix is retained during the complete child scan. -/\ntheorem step_outerReader (before:Stack→List Bool) (b:Bucket) (tail target:List Bool):\n    step before b tail target (aux .outerReader)=tail:=by\n  rw [step,Inner.result_other _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide)]\n  rfl\n/-- Actual child reader is empty at the next bucket. -/\ntheorem step_endpointReader (before:Stack→List Bool) (b:Bucket) (tail target:List Bool):\n    step before b tail target (aux .endpointReader)=[]:=Inner.result_reader _ _ _\n/-- Every child parser/private role is restored at the per-bucket boundary. -/\ntheorem step_clean (before:Stack→List Bool) (b:Bucket) (tail target:List Bool)\n    (hz:∀k∈Parse.cleanRoles,before k=[]):∀k∈Parse.cleanRoles,step before b tail target k=[]:=by\n  apply Inner.result_clean\n  simpa [head,Header.result,Parse.cleanRoles,aux,field] using hz\n/-- Every actual header destination/parser role is ready for the next outer bucket. -/\ntheorem step_headerClean (before:Stack→List Bool) (b:Bucket) (tail target:List Bool)\n    (hh:∀k∈Header.cleanRoles,before k=[]):∀k∈Header.cleanRoles,step before b tail target k=[]:=by\n  intro k hk\n  simp only [Header.cleanRoles,List.mem_cons,List.not_mem_nil,or_false] at hk\n  rcases hk with rfl|rfl|rfl|rfl|rfl|rfl\n  · exact (step_other _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)).trans\n      (hh _ (by simp [Header.cleanRoles]))\n  · exact (step_other _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)).trans\n      (hh _ (by simp [Header.cleanRoles]))\n  · exact step_endpointReader _ _ _ _\n  all_goals\n    exact (step_other _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)).trans\n      (hh _ (by simp [Header.cleanRoles]))\n/-- Physical outer EOF consumes the actual FALSE before its final EOF peek. -/\ndef atEOF (before:Stack→List Bool):Stack→List Bool:=Function.update before (aux .outerReader) []\n/-- Entire actual nested scan bank. -/\ndef result:List Bucket→(Stack→List Bool)→List Bool→Stack→List Bool\n  | [],before,_=>atEOF before\n  | b::bs,before,target=>result bs (step before b (records bs) target) target\n/-- Whole actual header and child-source clock, including real final EOF instructions. -/\ndef timeBound:List Bucket→List Bool→Nat\n  | [],_=>2\n  | b::bs,target=>stepTime b target+timeBound bs target\n/-- Exact two actual EOF instructions at the outer bucket boundary. -/\ntheorem eof_run (before:Stack→List Bool) (ho:before (aux .outerReader)=[false]):\n    Runs program 2 (.local 9 7) before (.local 10 18) (atEOF before):=by\n  have h0:=pop_run (.local 9 7) abort (.local 9 8) (.local 9 9) (aux .outerReader) before [false] rfl ho\n  simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n  have h1:=peek_run (.local 9 8) (.local 10 18) abort abort (aux .outerReader) (atEOF before) [] rfl\n    (Function.update_self _ _ _)\n  simp only [List.head?_nil,SemiprimeD1StackBytecode.choose] at h1\n  exact join h0 h1\n/-- Entire actual nested scan, with every header/child call, cleanup and real return counted. -/\ntheorem source_trace (buckets:List Bucket) (before:Stack→List Bool) (target:List Bool)\n    (hi:before (aux .outerReader)=records buckets)\n    (hh:∀k∈Header.cleanRoles,before k=[]) (hz:∀k∈Parse.cleanRoles,before k=[])\n    (ht:before (aux .vertexKey)=target) (hb:before (aux .frameBuffer)=[])\n    (hc:before (aux .copyScratch)=[]) (ha:∀k,before (arithmetic k)=[]):\n    Runs program (timeBound buckets target) (.local 9 7) before (.local 10 18) (result buckets before target):=by\n  induction buckets generalizing before with\n  | nil=>exact eof_run before hi\n  | cons b bs ih=>\n    have h0:=step_trace before b (records bs) target hi hh hz ht hb hc ha\n    let after:=step before b (records bs) target\n    have hi':after (aux .outerReader)=records bs:=step_outerReader _ _ _ _\n    have hh':∀k∈Header.cleanRoles,after k=[]:=step_headerClean _ _ _ _ hh\n    have hz':∀k∈Parse.cleanRoles,after k=[]:=step_clean _ _ _ _ hz\n    have ht':after (aux .vertexKey)=target:=\n      (step_other _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)).trans ht\n    have hb':after (aux .frameBuffer)=[]:=\n      (step_other _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)).trans hb\n    have hc':after (aux .copyScratch)=[]:=\n      (step_other _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)).trans hc\n    have ha':∀k,after (arithmetic k)=[]:=by\n      intro k\n      exact (step_other _ _ _ _ _ (by intro j;fin_cases j <;> simp [Cleanup.role,arithmetic,aux])\n        (by simp [arithmetic,aux]) (by simp [arithmetic,aux]) (by simp [arithmetic,aux])).trans (ha k)\n    exact join h0 (ih after hi' hh' hz' ht' hb' hc' ha')\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsLoop\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeFields":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeActivation\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectOccurrences\nimport RiemannGaussian.SemiprimeD1StackPacketInventoryEncoding\nimport RiemannGaussian.SemiprimeD1ChildPullbackBudget\n/-! # Exact physically parsed fields from original occurrence and placement tapes\nThe proof interpretation is derived from the real original two-source zip. Its\nlength, validity, key ranges and byte layouts are proved from the original\nacquired metadata; no decoded field list or zip/permutation is a runtime input.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeFields\nnamespace Parse\nexport SemiprimeD1StackChildGroupFactoryEndpointParse (Fields payload)\nend Parse\nnamespace K\nexport SemiprimeD1StackChildGroupFactoryEndpointKeys (pairs placements)\nend K\nnamespace Key\nexport SemiprimeSourceHistogramHeadRefinement (numberKey numberKey_value)\nend Key\nnamespace Native\nexport SemiprimeD1PacketInventory (Placement)\nexport SemiprimeD1PacketReplayOriginal (acquire placement_valid)\nend Native\n/-- Exactly the seven actual words supplied by the two real parsers. -/\ndef ofPair (keys:List Bool×List Bool) (out:Native.Placement):Parse.Fields:=\n  ⟨keys.1,keys.2,out.source,out.padding,out.packet,out.slot,out.edge⟩\n/-- No first-source record is dropped when the original acquired lengths match. -/\ntheorem pairs_zip (keys:List (List Bool×List Bool)) (placements:List Native.Placement)\n    (hl:keys.length=placements.length):\n    K.pairs ((keys.zip placements).map (fun p=>ofPair p.1 p.2))=\n      SemiprimeD1StackOwnerLookup.records keys []:=by\n  induction keys generalizing placements with\n  | nil=>cases placements <;> simp_all [K.pairs,SemiprimeD1StackOwnerLookup.records]\n  | cons key keys ih=>\n    cases placements with\n    | nil=>simp only [List.length_cons,List.length_nil] at hl;omega\n    | cons out outs=>\n      have ht:keys.length=outs.length:=by simp only [List.length_cons] at hl;omega\n      change true::SemiprimeSourceHistogramKeyBits.frame key.1\n        (SemiprimeSourceHistogramKeyBits.frame key.2 (K.pairs ((keys.zip outs).map (fun p=>ofPair p.1 p.2))))=_\n      rw [ih outs ht]\n      rfl\n/-- No second-source byte is invented: every real valid placement has its exact six-field payload. -/\ntheorem placements_zip (keys:List (List Bool×List Bool)) (placements:List Native.Placement)\n    (hl:keys.length=placements.length) (hv:∀p∈placements,p.valid=true):\n    K.placements ((keys.zip placements).map (fun p=>ofPair p.1 p.2))=\n      SemiprimeD1TensorTapeCodec.vectorBits (placements.map SemiprimeD1StackPacketInventoryEncoding.placementBytes):=by\n  induction keys generalizing placements with\n  | nil=>cases placements <;> simp_all [K.placements,SemiprimeD1TensorTapeCodec.vectorBits]\n  | cons key keys ih=>\n    cases placements with\n    | nil=>simp only [List.length_cons,List.length_nil] at hl;omega\n    | cons out outs=>\n      have ht:keys.length=outs.length:=by simp only [List.length_cons] at hl;omega\n      have hvalid:=hv out List.mem_cons_self\n      have hrest:=ih outs ht (fun p hp=>hv p (List.mem_cons_of_mem out hp))\n      have hbytes:Parse.payload (ofPair key out)=SemiprimeD1StackPacketInventoryEncoding.placementBytes out:=by\n        simp only [ofPair,Parse.payload,SemiprimeD1StackPacketInventoryEncoding.placementBytes,hvalid]\n      change true::SemiprimeSourceHistogramKeyBits.frame (Parse.payload (ofPair key out))\n        (K.placements ((keys.zip outs).map (fun p=>ofPair p.1 p.2)))=_\n      rw [hbytes,hrest]\n      rfl\n/-- Original acquired source, reused only as erased mathematical notation. -/\ndef source (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):=\n  Native.acquire n F 64 a arity owner\n/-- Exact already acquired original ordered key-pair list. -/\ndef keys (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):=\n  SemiprimeD1StackSourceIncidenceSelectMeaning.originalKeys n F a arity owner\n/-- Actual seven-field interpretation of the two physical source tapes. -/\ndef fields (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):List Parse.Fields:=\n  ((keys n F a arity owner).zip (source n F a arity owner).placements).map (fun p=>ofPair p.1 p.2)\n/-- Original source keys and real replay placements have the SAME derived original occurrence count. -/\ntheorem lengths (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):\n    (keys n F a arity owner).length=(source n F a arity owner).placements.length:=by\n  have hp:=SemiprimeD1ChildPullbackBudget.placements_length n F 64 a arity owner\n  have hm:=(SemiprimeSourceHistogramMetadata.sizes n F a arity).2.2.1\n  dsimp only [keys,SemiprimeD1StackSourceIncidenceSelectMeaning.originalKeys]\n  rw [List.length_map,hm]\n  exact hp.symm\n/-- First actual input tape is exactly the full original compact pair tape, in original order. -/\ntheorem pairs_original (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):\n    K.pairs (fields n F a arity owner)=SemiprimeD1StackOwnerLookup.records (keys n F a arity owner) []:=\n  pairs_zip _ _ (lengths n F a arity owner)\n/-- Second actual input tape is exactly the real acquired placements, with validity derived internally. -/\ntheorem placements_original (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):\n    K.placements (fields n F a arity owner)=SemiprimeD1TensorTapeCodec.vectorBits\n      ((source n F a arity owner).placements.map SemiprimeD1StackPacketInventoryEncoding.placementBytes):=\n  placements_zip _ _ (lengths n F a arity owner)\n    (fun p hp=>(Native.placement_valid n F 64 a arity owner p hp).1)\n/-- Every parsed original owner/factor key lies in the original combined vertex namespace. -/\ntheorem domains (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n):\n    ∀f∈fields n F a arity owner,SemiprimeBitArithmetic.bitValue f.owner<n+F ∧\n      SemiprimeBitArithmetic.bitValue f.factor<n+F:=by\n  intro f hf\n  obtain ⟨p,hp,rfl⟩:=List.mem_map.mp hf\n  have hkey:p.1∈keys n F a arity owner:=(List.of_mem_zip hp).1\n  exact SemiprimeD1StackSourceIncidenceSelectOccurrences.original_key_ranges n F a arity owner p.1 hkey\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeFields\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeTagOrder":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeScopes\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeTagResolution\n/-! # Exact native per-vertex tag order read by the actual first-index source\nThe actual raw edge/side stream has the same order and byte identity as the\nnative resolved tag stream. This proves lookup positions, including EOF misses,\nwithout a supplied permutation, tag map, or equality/count answer.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeTagOrder\nopen SemiprimeD1StackChildGroupFactory (Inputs)\nopen SemiprimeBitArithmetic (bitValue)\nnamespace I\nexport SemiprimeD1StackChildGroupFactoryLeftPortsInner (Child)\nend I\nnamespace B\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket)\nend B\nnamespace M\nexport SemiprimeD1StackChildGroupFactoryTagIndexMeaning (tags allTags outer_value)\nend M\nnamespace Tag\nexport SemiprimeD1StackChildGroupFactoryTagVisit (candidate)\nend Tag\nnamespace N\nexport SemiprimeD1StackChildGroupFactoryNativeEndpoints (encode)\nexport SemiprimeD1StackChildGroupFactoryNativeBuckets (numbering_original)\nexport SemiprimeD1StackChildGroupFactoryNativeTagResolution (tags_with_vertices idxOf_map)\nend N\nnamespace Raw\nexport SemiprimeD1StackChildGroupFactoryNativeTags (rawTag rawTag_injective)\nend Raw\nnamespace Native\nexport SemiprimeD1ChildAssignmentEquiv (tags acquired Tag)\nend Native\nnamespace Fld\nexport SemiprimeD1StackChildGroupFactoryNativeFields (source fields)\nend Fld\nnamespace Act\nexport SemiprimeD1StackChildGroupFactoryNativeActivation (originalIDs)\nend Act\nnamespace Forward\nexport SemiprimeD1StackChildGroupFactoryForwardBucketsSource (endpoints)\nend Forward\nnamespace Code\nexport SemiprimeD1StackChildGroupFactoryCatalogueCodecs (buckets)\nend Code\n/-- Actual inner tag bytes are read from precisely the matching original raw endpoints. -/\ntheorem inner_tags (children:List I.Child) (target:List Bool):M.tags children target=\n    (((children.map Prod.fst).filter (fun e=>decide (bitValue e.vertex=bitValue target))).map Tag.candidate):=by\n  induction children with\n  | nil=>rfl\n  | cons p ps ih=>\n    by_cases h:bitValue p.1.vertex=bitValue target <;>\n      simp only [M.tags,List.map_cons,List.filter_cons,h,ite_true,ite_false,decide_true,decide_false,\n        Bool.false_eq_true,ih]\n/-- Complete actual packet-major tag bytes retain exact vertex-filtered endpoint order. -/\ntheorem all_tags_fields (buckets:List B.Bucket) (target:List Bool):M.allTags buckets target=\n    ((((buckets.flatMap (fun b=>b.children)).map Prod.fst).filter\n      (fun e=>decide (bitValue e.vertex=bitValue target))).map Tag.candidate):=by\n  induction buckets with\n  | nil=>rfl\n  | cons b bs ih=>\n    change M.tags b.children target++M.allTags bs target=_\n    rw [inner_tags,ih]\n    simp only [List.flatMap_cons,List.map_append,List.filter_append]\n/-- Actual complete computed bucket view; only proof notation, not an additional runtime input. -/\nabbrev buckets (i:Inputs) (n F a:Nat) (arity:Fin F→Nat) (owner:((e:Fin F)×Fin (arity e))→Fin n)\n    (q:Fin a):List B.Bucket:=Code.buckets (Fld.source n F a arity owner).state.packets\n      (Forward.endpoints i a q.val (Act.originalIDs n F a arity owner) (Fld.fields n F a arity owner)) []\n/-- The actual query's WHOLE raw-tag stream is exactly the encoded acquired native local tag order. -/\ntheorem all_tags_original (i:Inputs) (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (q:Fin a) (g:Fin 64)\n    (hg:bitValue i.group=g.val) (v:Fin (n+F)) (target:List Bool) (ht:bitValue target=v.val):\n    M.allTags (buckets i n F a arity owner q) target=\n      (SemiprimeD1ChildTableOrder.acquire owner (Native.acquired n F 64 a arity owner q g) v).child.map\n        (Raw.rawTag n F a arity owner):=by\n  have hn:=congrArg (List.map Prod.fst) (N.numbering_original i n F a arity owner q g hg)\n  have hfields:((buckets i n F a arity owner q).flatMap (fun b=>b.children)).map Prod.fst=\n      (SemiprimeD1ChildGraph.acquire n F 64 a arity owner q g).factors.flatten.map N.encode:=by\n    simpa only [List.map_map,Function.comp_def,List.zipIdx_map_fst] using hn\n  have htags:=congrArg (fun xs:List (Fin (n+F)×List Bool)=>\n      (xs.filter (fun p=>decide (p.1=v))).map Prod.snd) (N.tags_with_vertices n F a arity owner q g)\n  simp only [List.filter_map,List.map_map,Function.comp_def] at htags\n  rw [all_tags_fields,hfields]\n  change _=((Native.tags n F 64 a arity owner q g).filter\n    (fun t=>decide (SemiprimeD1ChildPortBijection.linkVertex owner t=v))).map (Raw.rawTag n F a arity owner)\n  rw [htags]\n  simp only [List.filter_map,List.map_map,Function.comp_def,N.encode,Tag.candidate,\n    SemiprimeD1StackChildGroupFactoryTagBuild.rawTag,SemiprimeSourceHistogramHeadRefinement.numberKey_value,ht,Fin.ext_iff]\n  rfl\n/-- Exact actual binary first-index result equals native child.idxOf for EVERY original typed tag. -/\ntheorem query_value_original (i:Inputs) (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (q:Fin a) (g:Fin 64)\n    (hg:bitValue i.group=g.val) (v:Fin (n+F)) (target:List Bool) (ht:bitValue target=v.val)\n    (tag:Native.Tag arity):\n    bitValue (SemiprimeD1StackChildGroupFactoryTagLoopView.finalPosition (buckets i n F a arity owner q) target\n      (Raw.rawTag n F a arity owner tag) [])=\n      (SemiprimeD1ChildTableOrder.acquire owner (Native.acquired n F 64 a arity owner q g) v).child.idxOf tag:=by\n  rw [M.outer_value,SemiprimeBitArithmetic.bitValue,Nat.zero_add,\n    all_tags_original i n F a arity owner q g hg v target ht]\n  exact N.idxOf_map _ (Raw.rawTag_injective n F a arity owner q g) _ _\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeTagOrder\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryRowByteBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryUnaryScopeBounds\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOrderBounds\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexBodyView\n/-! # Uniform actual per-old-vertex scope/order row bytes\nAll port words come from actual generated global IDs and all order words from\nactual first-idx queries. A repeated prepared packet may repeat incidences;\nthe derived bound remains quartic in paid input counts and applies uniformly\nto every numeric old vertex, including isolated/inactive vertices.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryRowByteBounds\nnamespace Inner\nexport SemiprimeD1StackChildGroupFactoryLeftPortsInner (portWords)\nend Inner\nnamespace B\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket portWords)\nend B\nnamespace E\nexport SemiprimeD1StackChildGroupFactoryBucketParse (Endpoint)\nend E\nnamespace P\nexport SemiprimeD1StackChildGroupFactoryOldPortParse (Point)\nend P\nnamespace Old\nexport SemiprimeD1StackChildGroupFactoryOldPortsLoop (orderWords)\nend Old\nnamespace O\nexport SemiprimeD1StackPortOrdinalStream (result)\nend O\nnamespace Code\nexport SemiprimeD1StackChildGroupFactoryCatalogueCodecs (buckets)\nend Code\nopen SemiprimeBitArithmetic (bitValue)\n/-- Real numeric-vertex filtering never adds an occurrence to a child vector. -/\ntheorem inner_count (children:List (E.Endpoint×List Bool)) (target:List Bool):\n    (Inner.portWords children target).length≤children.length:=by\n  induction children with\n  | nil=>exact le_rfl\n  | cons p ps ih=>\n    by_cases h:bitValue p.1.vertex=bitValue target <;>\n      simp only [Inner.portWords,h,ite_true,ite_false,List.length_cons] <;> omega\n/-- Every output ID word is an actually emitted child's raw binary global-ID word. -/\ntheorem inner_word (children:List (E.Endpoint×List Bool)) (target word:List Bool)\n    (hw:word∈Inner.portWords children target):∃p∈children,p.2=word:=by\n  induction children with\n  | nil=>simp only [Inner.portWords,List.not_mem_nil] at hw\n  | cons p ps ih=>\n    by_cases h:bitValue p.1.vertex=bitValue target\n    · simp only [Inner.portWords,h,ite_true,List.mem_cons] at hw\n      rcases hw with rfl|hw\n      · exact ⟨p,List.mem_cons_self,rfl⟩\n      · obtain ⟨q,hq,he⟩:=ih hw;exact ⟨q,List.mem_cons_of_mem p hq,he⟩\n    · obtain ⟨q,hq,he⟩:=ih (by simpa only [Inner.portWords,h,ite_false] using hw)\n      exact ⟨q,List.mem_cons_of_mem p hq,he⟩\n/-- Whole packet-major left-scope filter visits only actual emitted children. -/\ntheorem scope_count (buckets:List B.Bucket) (target:List Bool):\n    (B.portWords buckets target).length≤(buckets.flatMap (fun b=>b.children)).length:=by\n  induction buckets with\n  | nil=>exact le_rfl\n  | cons b bs ih=>\n    have hh:=inner_count b.children target\n    simp only [B.portWords,List.length_append,List.flatMap_cons] at ih ⊢\n    omega\n/-- Exact physical global-ID lineage through all numeric-vertex filters. -/\ntheorem scope_word (buckets:List B.Bucket) (target word:List Bool)\n    (hw:word∈B.portWords buckets target):∃p∈buckets.flatMap (fun b=>b.children),p.2=word:=by\n  induction buckets with\n  | nil=>simp only [B.portWords,List.not_mem_nil] at hw\n  | cons b bs ih=>\n    simp only [B.portWords,List.mem_append] at hw\n    rcases hw with hw|hw\n    · obtain ⟨p,hp,he⟩:=inner_word b.children target word hw\n      exact ⟨p,by simp only [List.flatMap_cons,List.mem_append];exact Or.inl hp,he⟩\n    · obtain ⟨p,hp,he⟩:=ih hw\n      exact ⟨p,by simp only [List.flatMap_cons,List.mem_append];exact Or.inr hp,he⟩\n/-- Actual converted left-scope bytes are paid by actual child count and derived global-ID values. -/\ntheorem scope_unary_length (buckets:List B.Bucket) (target:List Bool) (cap:Nat)\n    (hv:∀p∈buckets.flatMap (fun b=>b.children),bitValue p.2≤cap):\n    (O.result (B.portWords buckets target)).length≤\n      (buckets.flatMap (fun b=>b.children)).length*(2*cap+2)+1:=by\n  have h:=SemiprimeD1StackChildGroupFactoryUnaryScopeBounds.unary_length (B.portWords buckets target) cap (by\n    intro w hw;obtain ⟨p,hp,rfl⟩:=scope_word buckets target w hw;exact hv p hp)\n  have hc:=scope_count buckets target\n  nlinarith\n/-- Actual converted original-port order bytes are paid by the original list and actual child count. -/\ntheorem order_unary_length (buckets:List B.Bucket) (points:List P.Point) (target:List Bool):\n    (O.result (Old.orderWords buckets points target)).length≤\n      points.length*(2*(buckets.flatMap (fun b=>b.children)).length+2)+1:=by\n  have h:=SemiprimeD1StackChildGroupFactoryUnaryScopeBounds.unary_length (Old.orderWords buckets points target)\n    ((buckets.flatMap (fun b=>b.children)).length)\n    (fun w hw=>(SemiprimeD1StackChildGroupFactoryOrderBounds.order_word_bounds buckets points target w hw).2)\n  have hc:=SemiprimeD1StackChildGroupFactoryOrderBounds.order_count buckets points target\n  nlinarith\n/-- Per-vertex actual scope/order row allowance is uniformly quartic, even with duplicate packet vectors. -/\ntheorem generated_rows_quartic (packets:List (List Bool)) (es:List E.Endpoint) (points:List P.Point)\n    (target:List Bool) (S:Nat) (hk:packets.length≤S) (he:es.length≤S) (hp:points.length≤S):\n    (SemiprimeD1StackChildGroupFactoryWordLog.row (O.result (B.portWords (Code.buckets packets es []) target))).length+\n      (SemiprimeD1StackChildGroupFactoryWordLog.row (O.result (Old.orderWords (Code.buckets packets es []) points target))).length+2≤\n        100*(S+1)^4:=by\n  have hscope:=scope_unary_length (Code.buckets packets es []) target (packets.length*es.length)\n    (SemiprimeD1StackChildGroupFactoryCounterBounds.generated_value packets es)\n  have horder:=order_unary_length (Code.buckets packets es []) points target\n  have hc:=SemiprimeD1StackChildGroupFactoryCounterBounds.catalogue_count packets es []\n  have hm:packets.length*es.length≤S*S:=Nat.mul_le_mul hk he\n  have hs:(S*S)^2≤(S+1)^4:=by nlinarith\n  have hc2:((Code.buckets packets es []).flatMap (fun b=>b.children)).length≤S*S:=hc.trans hm\n  have hscope':(O.result (B.portWords (Code.buckets packets es []) target)).length≤(S*S)*(2*(S*S)+2)+1:=by\n    nlinarith\n  have horder':(O.result (Old.orderWords (Code.buckets packets es []) points target)).length≤S*(2*(S*S)+2)+1:=by\n    nlinarith\n  simp only [SemiprimeD1StackChildGroupFactoryWordLog.row,List.length_cons,\n    SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n  nlinarith\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryRowByteBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexBody":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsSourceView\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsSourceView\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexIncrement\n/-! # Complete actual per-old-vertex left-scope and original-order acquisition\nBoth whole physical sources execute before one real binary old-vertex increment.\nEvery original vertex, including isolated vertices, uses the same literal path.\nNo tensor/coefficient/table/decoded colour or supplied scope/order is an input.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexBody\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\nnamespace Left\nexport SemiprimeD1StackChildGroupFactoryLeftPortsSource (result timeBound source_trace drained)\nend Left\nnamespace LV\nexport SemiprimeD1StackChildGroupFactoryLeftPortsSourceView (FreshExceptGlobal drained_fresh result_other result_fresh result_ordinal)\nend LV\nnamespace Old\nexport SemiprimeD1StackChildGroupFactoryOldPortsSource (result timeBound source_trace)\nend Old\nnamespace OV\nexport SemiprimeD1StackChildGroupFactoryOldPortsSourceView (result_other result_fresh result_ordinal)\nend OV\nnamespace Inc\nexport SemiprimeD1StackChildGroupFactoryVertexIncrement (successor timeBound source_trace)\nend Inc\nnamespace Work\nexport SemiprimeD1StackChildGroupFactoryOldPortsLoop (Fresh freshRole headerFresh childFresh)\nend Work\nnamespace Header\nexport SemiprimeD1StackChildGroupFactoryBucketHeader (cleanRoles)\nend Header\nnamespace Child\nexport SemiprimeD1StackChildGroupFactoryChildParse (cleanRoles)\nend Child\nnamespace Raw\nexport SemiprimeD1StackChildGroupFactoryChildCleanup (role)\nend Raw\nnamespace Early\nexport SemiprimeD1StackChildGroupFactoryTagEarlyClear (role)\nend Early\nnamespace Reuse\nexport SemiprimeD1StackChildGroupFactoryPortReuse (role bankRole)\nend Reuse\nnamespace Points\nexport SemiprimeD1StackChildGroupFactoryOldPortParse (Point records)\nend Points\nnamespace Buckets\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket records)\nend Buckets\n/-- Actual data-only readiness; the saved global word may be nonempty before its real drain. -/\nstructure Ready (before:Stack→List Bool):Prop where\n  work:LV.FreshExceptGlobal before\n  arithmetic_clean:∀k,before (arithmetic k)=[]\n  ordinal_clean:∀k,before (ordinal k)=[]\n  oldReader_empty:before (aux .oldReader)=[]\n  portBank_empty:before (aux .portBank)=[]\n  portHistory_empty:before (aux .portHistory)=[]\n  orderBank_empty:before (aux .orderBank)=[]\n  orderHistory_empty:before (aux .orderHistory)=[]\n/-- The actual left-scope source retains the separate four arithmetic tapes. -/\ntheorem left_arithmetic (before:Stack→List Bool) (buckets:List Buckets.Bucket) (target:List Bool)\n    (ha:∀k,before (arithmetic k)=[]):∀k,Left.result before buckets target (arithmetic k)=[]:=by\n  intro k\n  exact (LV.result_other _ _ _ _ (by intro j;fin_cases j <;> simp [Raw.role,arithmetic,aux])\n    (by simp [arithmetic,aux]) (by simp [arithmetic,aux]) (by simp [arithmetic,aux])\n    (by intro j;fin_cases j <;> simp [Reuse.role,Reuse.bankRole,ordinal,arithmetic,aux])\n    (by simp [arithmetic,aux])).trans (ha k)\n/-- The whole old-port source retains those same four actual arithmetic tapes. -/\ntheorem old_arithmetic (before:Stack→List Bool) (points:List Points.Point) (buckets:List Buckets.Bucket) (target:List Bool)\n    (ha:∀k,before (arithmetic k)=[]):∀k,Old.result before points buckets target (arithmetic k)=[]:=by\n  intro k\n  exact (OV.result_other _ _ _ _ _ (by intro j;fin_cases j <;> simp [Early.role,arithmetic,aux])\n    (by simp [arithmetic,aux]) (by simp [arithmetic,aux]) (by simp [arithmetic,aux])\n    (by simp [arithmetic,aux]) (by simp [arithmetic,aux])\n    (by intro j;fin_cases j <;> simp [Reuse.role,Reuse.bankRole,ordinal,arithmetic,aux])\n    (by simp [arithmetic,aux])).trans (ha k)\n/-- Complete actual bank after both whole sources and the physically executed binary increment. -/\ndef result (before:Stack→List Bool) (points:List Points.Point) (buckets:List Buckets.Bucket) (target:List Bool):Stack→List Bool:=\n  Function.update (Old.result (Left.result before buckets target) points buckets target)\n    (aux .vertexKey) (Inc.successor target)\n/-- Sum of SAME actual whole left/old sources and the real final increment. -/\ndef timeBound (before:Stack→List Bool) (points:List Points.Point) (buckets:List Buckets.Bucket) (target:List Bool):Nat:=\n  Left.timeBound before buckets target+Old.timeBound (Left.result before buckets target) points buckets target+Inc.timeBound target\n/-- One COMPLETE real old-vertex iteration, including isolated vertices and every actual source/return. -/\ntheorem source_trace (before:Stack→List Bool) (points:List Points.Point) (buckets:List Buckets.Bucket) (target:List Bool)\n    (hp:before (aux .oldEndpoints)=Points.records points) (hb:before (aux .buckets)=Buckets.records buckets)\n    (ht:before (aux .vertexKey)=target) (hr:Ready before):\n    ∃t≤timeBound before points buckets target,\n      Runs program t (.local 9 5) before (.local 9 4) (result before points buckets target):=by\n  have hd:=LV.drained_fresh before hr.work\n  have hh:∀k∈Header.cleanRoles,before k=[]:=by\n    simpa [Left.drained,Header.cleanRoles,aux,field] using Work.headerFresh (Left.drained before) hd\n  have hz:∀k∈Child.cleanRoles,k≠aux .globalPosition→before k=[]:=by\n    intro k hk hn\n    have h:=Work.childFresh (Left.drained before) hd k hk\n    simpa only [Left.drained,Function.update_of_ne hn] using h\n  obtain ⟨x,hx,h0⟩:=Left.source_trace before buckets target hb (hr.work 0 (by decide)) hh hz ht\n    (hr.work 18 (by decide)) (hr.work 19 (by decide)) hr.arithmetic_clean hr.ordinal_clean hr.portHistory_empty hr.portBank_empty\n  let leftState:=Left.result before buckets target\n  have hp':leftState (aux .oldEndpoints)=Points.records points:=\n    (LV.result_other _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)\n      (by intro j;fin_cases j <;> decide) (by decide)).trans hp\n  have hb':leftState (aux .buckets)=Buckets.records buckets:=\n    (LV.result_other _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)\n      (by intro j;fin_cases j <;> decide) (by decide)).trans hb\n  have ht':leftState (aux .vertexKey)=target:=\n    (LV.result_other _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)\n      (by intro j;fin_cases j <;> decide) (by decide)).trans ht\n  have hold:leftState (aux .oldReader)=[]:=\n    (LV.result_other _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)\n      (by intro j;fin_cases j <;> decide) (by decide)).trans hr.oldReader_empty\n  have horderBank:leftState (aux .orderBank)=[]:=\n    (LV.result_other _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)\n      (by intro j;fin_cases j <;> decide) (by decide)).trans hr.orderBank_empty\n  have horderHistory:leftState (aux .orderHistory)=[]:=\n    (LV.result_other _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide) (by decide)\n      (by intro j;fin_cases j <;> decide) (by decide)).trans hr.orderHistory_empty\n  have hwork:Work.Fresh leftState:=LV.result_fresh _ _ _ hr.work\n  have ha:∀k,leftState (arithmetic k)=[]:=left_arithmetic _ _ _ hr.arithmetic_clean\n  obtain ⟨y,hy,h1⟩:=Old.source_trace leftState points buckets target hp' hold hb' ht' hwork ha\n    (LV.result_ordinal _ _ _) horderHistory horderBank\n  let oldState:=Old.result leftState points buckets target\n  have hkey:oldState (aux .vertexKey)=target:=\n    (OV.result_other _ _ _ _ _ (by intro j;fin_cases j <;> decide)\n      (by decide) (by decide) (by decide) (by decide) (by decide)\n      (by intro j;fin_cases j <;> decide) (by decide)).trans ht'\n  have hclean:Work.Fresh oldState:=OV.result_fresh _ _ _ _ hwork\n  have h2:=Inc.source_trace oldState target hkey (hclean 19) (old_arithmetic _ _ _ _ ha)\n  refine ⟨x+y+Inc.timeBound target,?_,?_⟩\n  · dsimp only [timeBound,leftState] at hy ⊢\n    omega\n  · have hwhole:=join h0 (join h1 h2)\n    simpa only [result,Nat.add_assoc] using hwhole\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexBody\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryWiring":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryRoles\n/-! # Fixed literal primitive wiring for the complete child group factory\nPages/offsets and site labels are fixed finite program locations only. They do\nnot encode any acquired vertex, colour coordinate, jet dimension or answer.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactoryRoles\n/-- All38 actual fixed copy operand pairs, determined before every input. -/\ndef copyPorts (site:Fin 38):Stack×Stack:=match site.val with\n  | 0=>(aux .owners,aux .vertexTodo)\n  | 1=>(aux .factors,aux .vertexTodo)\n  | 2=>(aux .vertexKey,lookup (.inr .query))\n  | 3=>(aux .environment,lookup (.inr .reader))\n  | 4=>(lookup (.inr .output),aux .selectedID)\n  | 5=>(aux .selectedID,aux .jointKey)\n  | 6=>(aux .jointKey,rows (.inr .key))\n  | 7=>(aux .catalogue,rows (.inr .catalogue))\n  | 8=>(rows (.inr .leftOutput),aux .colourReader)\n  | 9=>(aux .colourIndex,aux .colourCursor)\n  | 10=>(aux .colourWord,arithmetic .left)\n  | 11=>(aux .group,arithmetic .right)\n  | 12=>(aux .vertexKey,arithmetic .left)\n  | 13=>(arithmetic .output,aux .vertexKey)\n  | 14=>(aux .occurrences,aux .pairReader)\n  | 15=>(aux .placements,aux .placementReader)\n  | 16=>(aux .ownerKey,lookup (.inr .query))\n  | 17=>(aux .activationMap,lookup (.inr .reader))\n  | 18=>(aux .factorKey,lookup (.inr .query))\n  | 19=>(aux .packets,aux .packetReader)\n  | 20=>(aux .endpoints,aux .endpointReader)\n  | 21=>(aux .sourceKey,arithmetic .left)\n  | 22=>(aux .packetKey,arithmetic .right)\n  | 23=>(aux .globalPosition,arithmetic .left)\n  | 24=>(arithmetic .output,aux .globalPosition)\n  | 25=>(aux .portBank,ordinal .bank)\n  | 26=>(aux .buckets,aux .outerReader)\n  | 27=>(aux .ownerKey,arithmetic .left)\n  | 28=>(aux .vertexKey,arithmetic .right)\n  | 29=>(aux .oldEndpoints,aux .oldReader)\n  | 30=>(aux .sideWord,aux .tagWord)\n  | 31=>(aux .sideWord,aux .candidateTag)\n  | 32=>(aux .tagWord,arithmetic .left)\n  | 33=>(aux .candidateTag,arithmetic .right)\n  | 34=>(aux .localPosition,arithmetic .left)\n  | 35=>(arithmetic .output,aux .localPosition)\n  | 36=>(aux .localPosition,aux .answerPosition)\n  | 37=>(aux .orderBank,ordinal .bank)\n  | _=>(aux .owners,aux .vertexTodo)\n/-- All25 actual fixed frame operand pairs, determined before every input. -/\ndef framePorts (site:Fin 25):Stack×Stack:=match site.val with\n  | 0=>(aux .selectedID,aux .jointKey)\n  | 1=>(aux .flagScratch,aux .activationMap)\n  | 2=>(aux .vertexKey,aux .activationMap)\n  | 3=>(aux .sideWord,aux .rowBuffer)\n  | 4=>(aux .edgeWord,aux .rowBuffer)\n  | 5=>(aux .ownerKey,aux .rowBuffer)\n  | 6=>(aux .rowBuffer,aux .frameBuffer)\n  | 7=>(aux .slotWord,aux .rowBuffer)\n  | 8=>(aux .packetKey,aux .rowBuffer)\n  | 9=>(aux .factorKey,aux .rowBuffer)\n  | 10=>(aux .globalPosition,aux .rowBuffer)\n  | 11=>(aux .sourceKey,aux .rowBuffer)\n  | 12=>(aux .globalPosition,aux .frameBuffer)\n  | 13=>(ordinal .output,aux .rowBuffer)\n  | 14=>(aux .jointKey,aux .rowBuffer)\n  | 15=>(ordinal .output,aux .frameBuffer)\n  | 16=>(aux .edgeWord,aux .tagWord)\n  | 17=>(aux .edgeWord,aux .candidateTag)\n  | 18=>(aux .answerPosition,aux .frameBuffer)\n  | 19=>(aux .oldEndpoints,aux .output)\n  | 20=>(aux .orders,aux .output)\n  | 21=>(aux .leftPorts,aux .output)\n  | 22=>(aux .buckets,aux .output)\n  | 23=>(aux .endpoints,aux .output)\n  | 24=>(aux .activation,aux .output)\n  | _=>(aux .selectedID,aux .jointKey)\n/-- All16 actual fixed reverse operand pairs, determined before every input. -/\ndef reversePorts (site:Fin 16):Stack×Stack:=match site.val with\n  | 0=>(aux .activationHistory,aux .activation)\n  | 1=>(aux .frameBuffer,aux .oldHistory)\n  | 2=>(aux .frameBuffer,aux .endpointHistory)\n  | 3=>(aux .endpointHistory,aux .endpoints)\n  | 4=>(aux .oldHistory,aux .oldEndpoints)\n  | 5=>(aux .frameBuffer,aux .bucketHistory)\n  | 6=>(aux .frameBuffer,aux .portHistory)\n  | 7=>(aux .bucketHistory,aux .jointKey)\n  | 8=>(aux .portHistory,aux .portBank)\n  | 9=>(aux .frameBuffer,aux .factorHistory)\n  | 10=>(aux .factorHistory,aux .buckets)\n  | 11=>(aux .frameBuffer,aux .vertexHistory)\n  | 12=>(aux .frameBuffer,aux .orderHistory)\n  | 13=>(aux .orderHistory,aux .orderBank)\n  | 14=>(aux .vertexHistory,aux .leftPorts)\n  | 15=>(aux .factorHistory,aux .orders)\n  | _=>(aux .activationHistory,aux .activation)\n/-- All21 actual fixed field operand pairs, determined before every input. -/\ndef fieldPorts (site:Fin 21):Stack×Stack:=match site.val with\n  | 0=>(aux .colourReader,aux .colourWord)\n  | 1=>(aux .pairReader,aux .ownerKey)\n  | 2=>(aux .pairReader,aux .factorKey)\n  | 3=>(aux .placementReader,aux .childReader)\n  | 4=>(aux .childReader,aux .sourceKey)\n  | 5=>(aux .childReader,aux .paddingKey)\n  | 6=>(aux .childReader,aux .packetKey)\n  | 7=>(aux .childReader,aux .slotWord)\n  | 8=>(aux .childReader,aux .edgeWord)\n  | 9=>(aux .childReader,aux .validWord)\n  | 10=>(aux .packetReader,aux .packetKey)\n  | 11=>(aux .endpointReader,aux .rowBuffer)\n  | 12=>(aux .rowBuffer,aux .ownerKey)\n  | 13=>(aux .rowBuffer,aux .sourceKey)\n  | 14=>(aux .rowBuffer,aux .slotWord)\n  | 15=>(aux .rowBuffer,aux .edgeWord)\n  | 16=>(aux .rowBuffer,aux .sideWord)\n  | 17=>(aux .outerReader,aux .childReader)\n  | 18=>(aux .childReader,aux .endpointReader)\n  | 19=>(aux .rowBuffer,aux .globalPosition)\n  | 20=>(aux .oldReader,aux .rowBuffer)\n  | _=>(aux .colourReader,aux .colourWord)\n/-- Every actual preserving copy restores its disjoint scratch. -/\ndef copyStack (site:Fin 38) (k:Fin 3):Stack:=\n  if k=0 then (copyPorts site).1 else if k=1 then (copyPorts site).2 else aux .copyScratch\n/-- Each physical preserving field-frame appends to its actual destination. -/\ndef frameStack (site:Fin 25) (k:Fin 3):Stack:=\n  if k=0 then (framePorts site).1 else if k=1 then (framePorts site).2 else aux .copyScratch\n/-- Every genuine reversal consumes its actual source. -/\ndef reverseStack (site:Fin 16) (k:Fin 2):Stack:=\n  if k=0 then (reversePorts site).1 else (reversePorts site).2\n/-- Redirected actual parser input/output leave both unused allocations counted. -/\ndef fieldStack (site:Fin 21):F.Stack→Stack\n  | .inl .input=>(fieldPorts site).1\n  | .inl .output=>(fieldPorts site).2\n  | .inl .scratch=>field (.inl .scratch)\n  | .inr () =>field (.inr ())\n/-- Finite literal location and included procedure labels, independent of all words. -/\ninductive Label where\n  | local (page:Fin 16) (offset:Fin 32)\n  | clear (aborted:Bool) (part:Fin 115)\n  | lookup (pc:L.Label) | rows (pc:R.Label) | add (pc:A.Label) | equal (pc:E.Label)\n  | field (site:Fin 21) (pc:F.Label)\n  | ordinal (pc:O.Label)\n  | copy (site:Fin 38) (pc:Fin 9)\n  | frame (site:Fin 25) (pc:Fin 11)\n  | reverse (site:Fin 16) (pc:Fin 4)\n  deriving Fintype\n/-- Actual fixed source entry. -/\ndef entry:Label:=(.local 0 0)\n/-- Actual fixed successful status stage, reached only after physical cleanup. -/\ndef accept:Label:=(.local 15 15)\n/-- Actual fixed rejection status stage, reached only after physical cleanup. -/\ndef reject:Label:=(.local 15 16)\n/-- Actual failure target before the complete physical cleanup. -/\ndef abort:Label:=(.local 15 14)\n/-- Cleanup advances only a bounded fixed port label; no data counter is inspected. -/\ndef nextClear (aborted:Bool) (part:Fin 115):Label:=\n  if h:part.val+1<115 then .clear aborted ⟨part.val+1,h⟩ else if aborted then reject else accept\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryWiring\n","RiemannGaussian.SemiprimeD1StackDescriptorRecordLoad":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackDescriptorRecordPrimitives\nimport RiemannGaussian.SemiprimeD1StackDescriptorRecordLoadView\nimport RiemannGaussian.SemiprimeD1StackProcedureReturns\n/-! # Actual complete physical descriptor-to-template load and real return -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackDescriptorRecordLoad\nopen SemiprimeD1StackDescriptorRecord SemiprimeD1StackDescriptorRecordPrimitives\nopen SemiprimeD1StackDescriptorRecordLoadView SemiprimeD1StackProcedureTrace SemiprimeD1StackProcedureReturns\nvariable {K L : Type} [DecidableEq K] [Fintype K] (s : T.Static K L) (sourceMap : K→Option (Fin 6))\n/-- Every target payload, real EOF, selected copy and call/return is paid. -/\ndef loadUnit (d : Stack K→List Bool) : Nat :=6*inventory d+5\n/-- Each field is physically drained before a selected preserving copy, while\nunselected fields remain physically empty without a replacement data write. -/\ntheorem field_run (d : Stack K→List Bool) (hs : d scratch=[]) (p : Fin s.roles.length) :\n    ∃t≤loadUnit d,Runs (program s sourceMap) t (.inl (.load ⟨p.val,by omega⟩))\n      (loadPrefix s sourceMap d p.val) (loadNext s p) (loadPrefix s sourceMap d (p.val+1)) := by\n  let before:=loadPrefix s sourceMap d p.val\n  let target:=templateStack (T.role s p)\n  let cleared:=Function.update before target []\n  have h0:=drain s sourceMap (.inl (.load ⟨p.val,by omega⟩)) (.inl (.copy p)) target\n    (by simp only [program,dite_eq_left p.isLt];rfl) before\n  obtain ⟨u,hu,h1⟩ : ∃u≤5*inventory d+4,Runs (program s sourceMap) u (.inl (.copy p))\n      cleared (loadNext s p) (loadPrefix s sourceMap d (p.val+1)) := by\n    cases hm:sourceMap (T.role s p) with\n    | none=>\n      have hstep:cleared=loadPrefix s sourceMap d (p.val+1):=by\n        simpa only [selected,hm,Option.elim_none] using loadPrefix_step s sourceMap d p\n      refine ⟨1,by omega,?_⟩\n      rw [←hstep]\n      apply one_base (program s sourceMap) (.inl (.copy p)) (loadNext s p)\n        (.jump (loadNext s p)) cleared cleared (by simp only [program,hm]) <;> rfl\n    | some i=>\n      have hcall:program s sourceMap (.inl (.copy p))=.call (copyLabel p 0) (loadNext s p):=by\n        simp only [program,hm]\n      have h1:=copy_call s sourceMap p (.inl (.copy p)) (loadNext s p) hcall cleared\n        (by change (Function.update before target []) target=[];exact Function.update_self _ _ _)\n        (by\n          change (Function.update before target []) scratch=[]\n          rw [Function.update_of_ne (by simp [target,scratch,templateStack,recordStack,R.tableStack,T.template])]\n          exact hs)\n      have hword:cleared (copyStack s sourceMap p 0)=d (source i):=by\n        change (Function.update before target []) (source ((sourceMap (T.role s p)).getD 0))=_\n        rw [Function.update_of_ne (by simp [target,source,templateStack,recordStack,R.tableStack,T.template])]\n        simp only [hm,Option.getD_some]\n        rfl\n      rw [hword] at h1\n      have hstep:Function.update cleared (copyStack s sourceMap p 1) (d (source i))=\n          loadPrefix s sourceMap d (p.val+1):=by\n        change Function.update (Function.update before target []) target (d (source i))=_\n        rw [Function.update_idem]\n        simpa only [selected,hm,Option.elim_some] using loadPrefix_step s sourceMap d p\n      rw [hstep] at h1\n      exact ⟨5*(d (source i)).length+4,by have h:=cell_le d (source i);omega,h1⟩\n  have hr:=runs_trans (program s sourceMap) _ _ _ _ _ _ _ _ h0 h1\n  refine ⟨_,?_,hr⟩\n  have ht:=prefix_cell_le s sourceMap d p.val (T.role s p)\n  change (before target).length+1+u≤_\n  change (before target).length≤ inventory d at ht\n  unfold loadUnit\n  omega\n/-- Every literal checker-template position is physically visited, retaining\nall source words, checker banks, scope bytes and caller accumulators. -/\ntheorem load_runs (d : Stack K→List Bool) (hs : d scratch=[]) (n left : Nat)\n    (h : n+left=s.roles.length) :\n    ∃t≤left*loadUnit d,Runs (program s sourceMap) t (.inl (.load ⟨n,by omega⟩))\n      (loadPrefix s sourceMap d n) (.inl (.load ⟨s.roles.length,by omega⟩)) (loaded sourceMap d) := by\n  induction left generalizing n with\n  | zero=>\n    have hn:n=s.roles.length:=by omega\n    subst n\n    rw [loadPrefix_full]\n    exact ⟨0,by omega,runs_refl (program s sourceMap) _ _⟩\n  | succ left ih=>\n    let p : Fin s.roles.length:=⟨n,by omega⟩\n    obtain ⟨a,ha,h0⟩:=field_run s sourceMap d hs p\n    obtain ⟨t,ht,h1⟩:=ih (n+1) (by omega)\n    have hr:=runs_trans (program s sourceMap) _ _ _ _ _ _ _ _ h0 h1\n    refine ⟨a+t,?_,hr⟩\n    rw [Nat.succ_mul]\n    omega\n/-- One real return follows the complete physical load; outer frames survive. -/\ntheorem load_returns (d : Stack K→List Bool) (hs : d scratch=[]) :\n    ∃t≤ s.roles.length*loadUnit d+1,\n      Returns (program s sourceMap) t (.inl (.load 0)) d (loaded sourceMap d) := by\n  obtain ⟨t,ht,hr⟩:=load_runs s sourceMap d hs 0 s.roles.length (by omega)\n  rw [loadPrefix_zero] at hr\n  refine ⟨t+1,by omega,?_⟩\n  exact of_runs (program s sourceMap) t (.inl (.load 0)) (.inl (.load ⟨s.roles.length,by omega⟩)) _ _ hr\n    (by simp only [program,dite_eq_right (Nat.lt_irrefl _)])\nend RiemannGaussian.SemiprimeD1StackDescriptorRecordLoad\n","RiemannGaussian.SemiprimeD1StackDigitCountBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackDigitCountExecution\nimport RiemannGaussian.SemiprimeD1BinaryPublicAcquisitionBounds\n\n/-! # Actual cache-counter storage and original digitCount correspondence\nThe original-cache identity is derived from frozen real public acquisition,\nnot from a supplied quotient/count answer. N-only caller composition is a\nseparate following module; this scanner itself consumes physical cache bytes.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackDigitCountBounds\nopen SemiprimeD1StackDigitCount SemiprimeD1StackDigitCountExecution\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n\n/-- Every actually reached word is bounded by source bytes plus executed instructions. -/\ntheorem prefix_data_bound (bank:List Bool) (fuel:ℕ) (out:C.State Stack Label)\n    (hr:C.run program fuel (initial bank)=some out) : ∀k,(out.data k).length≤bank.length+fuel := by\n  apply SemiprimeD1StackReturnLink.run_data_bound program fuel bank.length _ out ?_ hr\n  intro k\n  cases k <;> simp [initial,data]\n\n/-- A proved stopped count cannot execute extra successful steps. -/\ntheorem run_halted (n:ℕ) (state:C.State Stack Label) (hp:state.pc=none) : C.run program (n+1) state=none := by\n  unfold C.run\n  rw [Function.iterate_succ_apply]\n  have hs:C.step program state=none:=by simp [C.step,SemiprimeD1StackCalls.step,hp]\n  simp only [Option.bind_some,hs]\n  exact Function.iterate_fixed rfl n\n\n/-- Every machine prefix counts all seven Boolean roles and the actual return frames. -/\ntheorem machine_space (words:List (List Bool)) (fuel:ℕ) (cfg:machine.Cfg)\n    (hr:(fun cfg=>cfg.bind machine.step)^[fuel] (some (Turing.initList machine (vectorBits words)))=some cfg) :\n    (cfg.stk (some Stack.bank)).length+(cfg.stk (some Stack.reader)).length+\n      (cfg.stk (some Stack.count)).length+(cfg.stk (some Stack.word)).length+\n      (cfg.stk (some Stack.fieldScratch)).length+(cfg.stk (some Stack.valid)).length+\n      (cfg.stk (some Stack.copyScratch)).length+(cfg.stk none).length≤100*((vectorBits words).length+1) := by\n  rw [initial_eq] at hr\n  let state:=initial (vectorBits words)\n  change (fun cfg=>cfg.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration state))=some cfg at hr\n  have he:=SemiprimeD1StackCalls.run_correct Stack.bank Stack.count (.inl .main) program fuel state\n  change (C.run program fuel state).map SemiprimeD1StackCalls.configuration=\n    (fun cfg=>cfg.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration state)) at he\n  cases hc:C.run program fuel state with\n  | none => rw [hc,hr] at he;cases he\n  | some out =>\n    rw [hc,hr] at he\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj he\n    rw [←hcfg]\n    have ht:fuel≤totalTime words:=by\n      by_contra hn\n      have ht:fuel=totalTime words+((fuel-totalTime words-1)+1):=by omega\n      rw [ht,SemiprimeD1StackReturnLink.run_add,acquire_run words,Option.bind_some,\n        run_halted _ (done words) rfl] at hc\n      cases hc\n    have htime:=totalTime_le words\n    have hb:=prefix_data_bound (vectorBits words) fuel out hc\n    have h0:=hb Stack.bank\n    have h1:=hb Stack.reader\n    have h2:=hb Stack.count\n    have h3:=hb Stack.word\n    have h4:=hb Stack.fieldScratch\n    have h5:=hb Stack.valid\n    have h6:=hb Stack.copyScratch\n    have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel state out hc\n    change out.frames.length≤0+fuel at hf\n    change (out.data Stack.bank).length+(out.data Stack.reader).length+(out.data Stack.count).length+\n      (out.data Stack.word).length+(out.data Stack.fieldScratch).length+(out.data Stack.valid).length+\n      (out.data Stack.copyScratch).length+out.frames.length≤_\n    omega\n\n/-- Actual original metadata/cache source for the physical count scanner. -/\ndef originalWords (bits:List Bool) : List (List Bool) :=\n  SemiprimeD1StackDigitBankSpec.blocks (SemiprimeD1BinaryDigitAcquisitionComponents.radix bits) bits.length bits\n/-- Fixed actual retained bank stack of the N-only public acquisition machine. -/\ndef bankRole : SemiprimeD1BinaryPublicAcquisition.Stack :=\n  SemiprimeD1BinaryPublicAcquisition.digitStack\n    (SemiprimeD1BinaryDigitAcquisition.bankStack SemiprimeD1StackDigitBank.output)\n\n/-- The actual acquired cache, not a count answer, is the physical scanner input. -/\ntheorem original_cache_run (bits:List Bool) :\n    C.run program (totalTime (originalWords bits))\n      (initial (SemiprimeD1BinaryPublicAcquisitionComponents.result bits bankRole))=\n      some (done (originalWords bits)) := by\n  change C.run program (totalTime (originalWords bits)) (initial (vectorBits (originalWords bits)))=_\n  exact acquire_run _\n\n/-- The counted physical marker word equals ORIGINAL digitCount, derived from the acquired cache. -/\ntheorem original_count (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0<SemiprimeBitArithmetic.bitValue bits) :\n    ((done (originalWords bits)).data Stack.count).length=\n      SemiprimeMacroParameters.digitCount (SemiprimeMacroParameters.bitLength (SemiprimeBitArithmetic.bitValue bits)) := by\n  change (List.replicate (originalWords bits).length true).length=_\n  rw [List.length_replicate]\n  exact SemiprimeD1BinaryPublicAcquisitionBounds.original_count bits hc hN\nend RiemannGaussian.SemiprimeD1StackDigitCountBounds\n","RiemannGaussian.SemiprimeD1StackDotEvaluate":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackExprDotBounds\nimport RiemannGaussian.SemiprimeD1StackExprBounds\n\n/-! # Actual dot-source construction joined directly to numerical execution\nThe acquired syntax stack IS the evaluator's code stack. Both whole programs\nexecute through real finite-label calls; no AST, getter, exponent or evaluator\nis supplied. Inputs remain physical prepared caches and the binary modulus.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackDotEvaluate\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace D\nexport SemiprimeD1StackExprDot (Stack Label Cache Work program bank initial)\nend D\nnamespace E\nexport SemiprimeD1StackExpr (Stack Label program bank input initial)\nend E\n\n/-- Ninety-seven fixed Boolean data roles; the unused private code role stays empty. -/\nabbrev Stack := D.Stack⊕E.Stack\n/-- Actual shared source-output/evaluator-input stack. -/\ndef code : Stack := .inl .output\n/-- Retained physical binary modulus, with no conversion to a unary value. -/\ndef modulus : Stack := .inr .modulus\n/-- Whole original numerical dot output. -/\ndef output : Stack := .inr .result\n/-- Direct physical wiring: no code copying or native source transport. -/\ndef expressionStack : E.Stack→Stack\n  | .code => code\n  | k => .inr k\n/-- Fixed component entry, real continuation and nested control locations. -/\ninductive Label where\n  | start | evaluate | done\n  | source (pc : D.Label) | expression (pc : E.Label)\n  deriving Fintype\n/-- ONE actual source-and-evaluation instruction program. -/\ndef program : Label→C.Instruction Stack Label\n  | .start => .call (.source (.control .start)) .evaluate\n  | .evaluate => .call (.expression .start) .done\n  | .done => .base .halt\n  | .source pc => SemiprimeD1StackValidationLink.instruction Sum.inl Label.source (D.program pc)\n  | .expression pc => SemiprimeD1StackValidationLink.instruction expressionStack Label.expression (E.program pc)\n/-- Reached physical data view, with the actual shared code as the left output. -/\ndef store (c : D.Cache) (codeWord : List Bool) (expr : E.Stack→List Bool) : Stack→List Bool :=\n  Sum.elim (D.bank c {output:=codeWord}) expr\n/-- Input contains only prepared physical argument tapes, modulus and suffix. -/\ndef initial (c : D.Cache) (cached tail : List Bool) : C.State Stack Label :=\n  ⟨some .start,none,none,store c tail (E.input [] cached),[]⟩\n/-- Direct-code inclusion has no overlapping evaluator roles. -/\ntheorem expressionStack_injective : Function.Injective expressionStack := by\n  intro i j h\n  cases i <;> cases j <;> simp_all [expressionStack,code]\n/-- Actual finite bit machine for the SAME two executed programs. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine (.inl .base) output .start program\n/-- Data and return-tag alphabets are fixed and finite before every input. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite (.inl .base) output Label.start program\n/-- Internal control carries no input-sized integer, list, expression or closure. -/\ntheorem control_finite : Finite machine.σ :=\n  SemiprimeD1StackCalls.control_finite (.inl .base) output Label.start program\n/-- Every Boolean register is included in subsequent prefix storage bounds. -/\ntheorem stack_card : Fintype.card Stack=97 := by decide\n\nend RiemannGaussian.SemiprimeD1StackDotEvaluate\n","RiemannGaussian.SemiprimeD1StackEuclidGCDPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackEuclidGCD\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n/-! # Actual preserving copies, byte loops, reversals and compact trims -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackEuclidGCDPrimitives\nopen SemiprimeD1StackEuclidGCD SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Exact chronological source-fragment composition preserves every real outer return. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Actual complete preserving copy, including both restoration loops and its real caller return. -/\ntheorem copy_call (what:Copy) (pc next:Label)\n    (hc:program pc=.call (.copier what 0) next) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copyStack what 0)=xs) (hy:before (copyStack what 1)=ys) (hs:before (copyStack what 2)=[]) :\n    Runs program (5*xs.length+4) pc before next\n      (Function.update before (copyStack what 1) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack what) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack what) (copy_injective what) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack what) (Label.copier what) (copy_injective what) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) pc next hc (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\n/-- Every initial-divisor/remainder/final reversal consumes its real source and pays all bytes and return cells. -/\ntheorem reverse_call (part:Reverse) (pc next:Label)\n    (hc:program pc=.call (.reversal part 0) next) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (reverseStack part 0)=xs) (hy:before (reverseStack part 1)=ys) :\n    Runs program (2*xs.length+3) pc before next\n      (Function.update (Function.update before (reverseStack part 0) []) (reverseStack part 1) (xs.reverse++ys)) :=by\n  let start:=SemiprimeD1StackReverseWord.state none xs ys\n  let stop:=SemiprimeD1StackReverseWord.done (xs.reverse++ys)\n  have hi:Link.DataRel (reverseStack part) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n    · intro k _;rfl\n  have h0:=Link.data_update (reverseStack part) (reverse_injective part) before start.store before hi (0:Fin 2) []\n  have h1:=Link.data_update (reverseStack part) (reverse_injective part) before _ _ h0 (1:Fin 2) (xs.reverse++ys)\n  have he:Function.update (Function.update start.store 0 []) 1 (xs.reverse++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at h1\n  exact included_call program (reverseStack part) (Label.reversal part) (reverse_injective part)\n    SemiprimeD1StackReverseWord.code 0 (fun _=>rfl) pc next hc (2*xs.length+2) start stop before _ rfl rfl\n    (SemiprimeD1StackReverseWord.reverse_run xs ys none) hi h1\n/-- Actual high-zero stripping/reversal, with both other reducer operands physically empty. -/\ntheorem trim_call (part:Trim) (pc next:Label)\n    (hc:program pc=.call (.reducer part .trim) next) (before:Stack→List Bool) (xs ys:List Bool)\n    (hl:before (trimStack part .left)=[]) (hr:before (trimStack part .right)=[])\n    (hs:before (trimStack part .scratch)=xs) (ho:before (trimStack part .output)=ys) :\n    Runs program (SemiprimeD1StackReduceExecution.trimTime xs+1) pc before next\n      (Function.update (Function.update before (trimStack part .scratch) []) (trimStack part .output)\n        (SemiprimeD1StackReduceExecution.trimReverse xs++ys)) :=by\n  let start:=SemiprimeD1StackReduce.state (some .trim) none [] [] xs ys\n  let stop:=SemiprimeD1StackReduce.state none none [] [] [] (SemiprimeD1StackReduceExecution.trimReverse xs++ys)\n  have hi:Link.DataRel (trimStack part) before start.store before:=by\n    constructor\n    · intro k;cases k\n      · exact hl\n      · exact hr\n      · exact hs\n      · exact ho\n    · intro k _;rfl\n  have h0:=Link.data_update (trimStack part) (trim_injective part) before start.store before hi .scratch []\n  have h1:=Link.data_update (trimStack part) (trim_injective part) before _ _ h0 .output\n    (SemiprimeD1StackReduceExecution.trimReverse xs++ys)\n  have he:Function.update (Function.update start.store .scratch []) .output\n      (SemiprimeD1StackReduceExecution.trimReverse xs++ys)=stop.store:=by funext k;cases k <;> rfl\n  rw [he] at h1\n  exact included_call program (trimStack part) (Label.reducer part) (trim_injective part) R.code .trim (fun _=>rfl)\n    pc next hc (SemiprimeD1StackReduceExecution.trimTime xs) start stop before _ rfl rfl\n    (SemiprimeD1StackReduceExecution.trim_run xs ys none) hi h1\n/-- One literal local push preserves the entire other physical bank and all real outer returns. -/\ntheorem push_run (pc:Label) (next:Label) (k:Stack) (b:Bool) (before:Stack→List Bool)\n    (hc:program pc=.base (.push k b next)) :\n    Runs program 1 pc before next (Function.update before k (b::before k)) :=\n  one_base program _ _ _ _ _ hc rfl rfl\n/-- One literal local pop consumes only the actual physical Boolean head. -/\ntheorem pop_run (pc:Label) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.pop k empty low high)) (hx:before k=xs) :\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) (Function.update before k xs.tail) :=by\n  apply one_base program pc _ (.pop k empty low high) before _ hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n/-- Real divisor peek preserves every actual byte while selecting zero versus positive work. -/\ntheorem peek_run (pc:Label) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.peek k empty low high)) (hx:before k=xs) :\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) before :=by\n  apply one_base program pc _ (.peek k empty low high) before before hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · rfl\n/-- Every quotient/backup/fuel cleanup actually visits every byte and its final empty branch. -/\ntheorem drain_loop (pc:Label) (next:Label) (k:Stack)\n    (hc:program pc=.base (.pop k next pc pc)) (before:Stack→List Bool) (xs:List Bool) (hx:before k=xs) :\n    Runs program (xs.length+1) pc before next (Function.update before k []) :=by\n  induction xs generalizing before with\n  | nil=>exact pop_run pc next pc pc k before [] hc hx\n  | cons b xs ih=>\n    have h0:=pop_run pc next pc pc k before (b::xs) hc hx\n    have h1:=ih (Function.update before k xs) (Function.update_self _ _ _)\n    have hh:=join (by cases b <;> exact h0) h1\n    simpa only [List.length_cons,Function.update_idem,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using hh\nend RiemannGaussian.SemiprimeD1StackEuclidGCDPrimitives\n","RiemannGaussian.SemiprimeD1StackExprArithmetic":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackExprWiring\n/-! # The complete evaluator's actual arithmetic procedure calls\nThese traces require only actual operand/cache bytes, not a result, height,\ncanonicality or clock supplier. Original canonicality is used later for meaning.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option synthInstance.maxSize 4096\nnamespace RiemannGaussian.SemiprimeD1StackExprArithmetic\nopen SemiprimeD1StackExpr SemiprimeD1StackExprWiring SemiprimeD1StackProcedureTrace\n\n/-- Actual complete add call; both operator inputs are consumed and all private work clears. -/\ntheorem add_call (code cached saved left right : List Bool) :\n    Runs program (SemiprimeD1StackResidueAddExecution.totalTime left right cached+1)\n      (.applyOp .add) (bank code cached saved [] left right [] []) .returnPC\n      (bank code cached saved (SemiprimeD1StackResidueAddExecution.residue left right cached) [] [] [] []) := by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program addStack Label.addition add_injective\n    Add.program .start (fun _=>rfl) (.applyOp .add) .returnPC rfl\n    (SemiprimeD1StackResidueAddExecution.totalTime left right cached)\n    (Add.initial left right cached) (SemiprimeD1StackResidueAddExecution.done left right cached) _ _ rfl rfl rfl rfl\n    (SemiprimeD1StackResidueAddExecution.source_run left right cached)\n  · constructor\n    · intro k\n      rcases k with k|k\n      · cases k <;> rfl\n      · rcases k with k|k\n        · rcases k with k|k <;> cases k <;> rfl\n        · cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k\n      rcases k with k|k\n      · cases k <;> rfl\n      · rcases k with k|k\n        · rcases k with k|k <;> cases k <;> rfl\n        · cases k <;> rfl\n    · intro k hk\n      cases k <;> first | rfl | exact (hk addLeft rfl).elim | exact (hk addRight rfl).elim | exact (hk Add.output rfl).elim\n\n/-- Actual complete sub call; both operator inputs are consumed and all private work clears. -/\ntheorem sub_call (code cached saved left right : List Bool) :\n    Runs program (SemiprimeD1StackResidueSubExecution.totalTime left right cached+1)\n      (.applyOp .sub) (bank code cached saved [] left right [] []) .returnPC\n      (bank code cached saved (SemiprimeD1StackResidueSubExecution.residue left right cached) [] [] [] []) := by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program subStack Label.subtraction sub_injective\n    Sub.program .start (fun _=>rfl) (.applyOp .sub) .returnPC rfl\n    (SemiprimeD1StackResidueSubExecution.totalTime left right cached)\n    (Sub.initial left right cached) (SemiprimeD1StackResidueSubExecution.done left right cached) _ _ rfl rfl rfl rfl\n    (SemiprimeD1StackResidueSubExecution.source_run left right cached)\n  · constructor\n    · intro k\n      rcases k with k|k\n      · cases k <;> rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · rcases k with k|k\n          · rcases k with k|k <;> cases k <;> rfl\n          · cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k\n      rcases k with k|k\n      · cases k <;> rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · rcases k with k|k\n          · rcases k with k|k <;> cases k <;> rfl\n          · cases k <;> rfl\n    · intro k hk\n      cases k <;> first | rfl | exact (hk subLeft rfl).elim | exact (hk subRight rfl).elim | exact (hk Sub.output rfl).elim\n\n/-- Actual complete mul call; both operator inputs are consumed and all private work clears. -/\ntheorem mul_call (code cached saved left right : List Bool) :\n    Runs program (SemiprimeD1StackResidueMulExecution.totalTime left right cached+1)\n      (.applyOp .mul) (bank code cached saved [] left right [] []) .returnPC\n      (bank code cached saved (SemiprimeD1StackResidueMulExecution.residue left right cached) [] [] [] []) := by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program mulStack Label.multiplication mul_injective\n    Mul.program .start (fun _=>rfl) (.applyOp .mul) .returnPC rfl\n    (SemiprimeD1StackResidueMulExecution.totalTime left right cached)\n    (Mul.initial left right cached) (SemiprimeD1StackResidueMulExecution.done left right cached) _ _ rfl rfl rfl rfl\n    (SemiprimeD1StackResidueMulExecution.source_run left right cached)\n  · constructor\n    · intro k\n      rcases k with k|k\n      · rcases k with k|k\n        · cases k <;> rfl\n        · rcases k with k|k\n          · fin_cases k <;> rfl\n          · cases k <;> rfl\n      · rcases k with k|k\n        · rcases k with k|k <;> cases k <;> rfl\n        · cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k\n      rcases k with k|k\n      · rcases k with k|k\n        · cases k <;> rfl\n        · rcases k with k|k\n          · fin_cases k <;> rfl\n          · cases k <;> rfl\n      · rcases k with k|k\n        · rcases k with k|k <;> cases k <;> rfl\n        · cases k <;> rfl\n    · intro k hk\n      cases k <;> first | rfl | exact (hk mulLeft rfl).elim | exact (hk mulRight rfl).elim | exact (hk Mul.output rfl).elim\n\n/-- Actual executed arithmetic word, as a proof-side specification of returned cells. -/\ndef word : Op→List Bool→List Bool→List Bool→List Bool\n  | .add,left,right,cached=>SemiprimeD1StackResidueAddExecution.residue left right cached\n  | .sub,left,right,cached=>SemiprimeD1StackResidueSubExecution.residue left right cached\n  | .mul,left,right,cached=>SemiprimeD1StackResidueMulExecution.residue left right cached\n/-- Actual complete component trace length, never used by the instruction table. -/\ndef time : Op→List Bool→List Bool→List Bool→ℕ\n  | .add,left,right,cached=>SemiprimeD1StackResidueAddExecution.totalTime left right cached\n  | .sub,left,right,cached=>SemiprimeD1StackResidueSubExecution.totalTime left right cached\n  | .mul,left,right,cached=>SemiprimeD1StackResidueMulExecution.totalTime left right cached\n\n/-- Every operator uses its own literal complete physical arithmetic trace. -/\ntheorem arithmetic_call (op : Op) (code cached saved left right : List Bool) :\n    Runs program (time op left right cached+1) (.applyOp op)\n      (bank code cached saved [] left right [] []) .returnPC\n      (bank code cached saved (word op left right cached) [] [] [] []) := by\n  cases op\n  · exact add_call code cached saved left right\n  · exact sub_call code cached saved left right\n  · exact mul_call code cached saved left right\nend RiemannGaussian.SemiprimeD1StackExprArithmetic\n","RiemannGaussian.SemiprimeD1StackExprLiteralBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackExprLiteralExecution\n\n/-! # Literal expression actual machine cost and public semantics\nAll parsed/fitted bits come from the physical syntax and cached template. The\nsuffix is retained and its storage counted; acquiring syntax/cache is caller work.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 900000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackExprLiteralBounds\nopen SemiprimeD1StackExprLiteral SemiprimeD1StackExprLiteralExecution\n\n/-- Every constructor read, actual parser/fitter call and cleanup is paid. -/\ntheorem totalTime_le (word cached : List Bool) :\n    totalTime word cached ≤ 9*word.length+10*cached.length+20 := by\n  have hf:=SemiprimeD1StackWordFitBounds.totalTime_le word cached\n  unfold totalTime readyTime\n  omega\n\n/-- Exact source certificate for the literal encoded in the physical syntax. -/\ndef sourceLiteral (word tail cached : List Bool) :\n    StateTransition.EvalsToInTime (C.step program)\n      (initial (SemiprimeD1StackExprCodec.encode (.literal word) tail) cached)\n      (some (done word tail cached)) (9*word.length+10*cached.length+20) :=\n  ⟨⟨_,source_run word tail cached⟩,totalTime_le word cached⟩\n\n/-- Genuine fixed finite-machine literal execution; no AST/value/width answer input. -/\ndef machineLiteral (word tail cached : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration\n        (initial (SemiprimeD1StackExprCodec.encode (.literal word) tail) cached))\n      (some (SemiprimeD1StackCalls.configuration (done word tail cached)))\n      (9*word.length+10*cached.length+20) :=\n  SemiprimeD1StackCalls.evalsCorrect inputCode output (ctl .start) program\n    _ _ _ (sourceLiteral word tail cached)\n\n/-- Exact original public arithmetic interpreter literal bytes. -/\ntheorem literal_original (word tail cached : List Bool) :\n    (done word tail cached).data output=\n      (SemiprimeMacroEntryBitPrimitives.execute cached (.literal word)).bits := rfl\n/-- The physically unconsumed expression suffix remains available for recursive parsing. -/\ntheorem retained_suffix (word tail cached : List Bool) :\n    (done word tail cached).data inputCode=tail := rfl\n/-- The binary modulus/template cache survives the actual complete literal trace. -/\ntheorem retained_template (word tail cached : List Bool) :\n    (done word tail cached).data (.inl Fit.template)=cached := rfl\n/-- The result has the SAME physical modulus width used by the original checker. -/\ntheorem output_length (word tail cached : List Bool) :\n    ((done word tail cached).data output).length=cached.length :=\n  SemiprimeD1StackWordFitExecution.result_length word cached\n\n/-- Successful source prefixes cannot pass the real complete halt. -/\ntheorem prefix_fuel_le (word tail cached : List Bool) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel\n      (initial (SemiprimeD1StackExprCodec.encode (.literal word) tail) cached)=some out) :\n    fuel ≤ 9*word.length+10*cached.length+20 := by\n  have hf : fuel ≤ totalTime word cached := by\n    by_contra hn\n    have he : fuel=totalTime word cached+(1+(fuel-(totalTime word cached+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,source_run,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add] at hr\n    have hz : C.run program 1 (done word tail cached)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans (totalTime_le word cached)\n\n/-- ALL seven Boolean data stacks, the complete retained suffix and every real\nreturn tag are included at every actual prefix. No live-inventory premise. -/\ntheorem prefix_cells (word tail cached : List Bool) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel\n      (initial (SemiprimeD1StackExprCodec.encode (.literal word) tail) cached)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length ≤ 200*(word.length+tail.length+cached.length+1) := by\n  let code:=SemiprimeD1StackExprCodec.encode (.literal word) tail\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (code.length+cached.length) _ out (by\n    intro k\n    rcases k with k|k\n    · fin_cases k <;> simp [initial,input,store,Fit.store,code]\n    · rcases k with k|k <;> cases k <;> simp [initial,input,store,code]) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length ≤ 0+fuel at hf\n  have hs : (∑k : Stack,(out.data k).length) ≤ 7*(code.length+cached.length+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(code.length+cached.length+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by\n        have hc : Fintype.card Stack=7 := by decide\n        simp only [Finset.sum_const,Finset.card_univ,hc,smul_eq_mul]\n  have hcode : code.length=2*word.length+3+tail.length := by\n    exact SemiprimeD1StackExprCodec.encode_length (.literal word) tail\n  have ht:=prefix_fuel_le word tail cached fuel out hr\n  omega\n\n/-- Every reached compiled-machine prefix has the SAME complete linear storage cap. -/\ntheorem machine_prefix_cells (word tail cached : List Bool) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration\n        (initial (SemiprimeD1StackExprCodec.encode (.literal word) tail) cached)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      200*(word.length+tail.length+cached.length+1) := by\n  have he:=SemiprimeD1StackCalls.run_correct inputCode output (ctl .start) program fuel\n    (initial (SemiprimeD1StackExprCodec.encode (.literal word) tail) cached)\n  change (C.run program fuel (initial (SemiprimeD1StackExprCodec.encode (.literal word) tail) cached)).map\n      SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration\n        (initial (SemiprimeD1StackExprCodec.encode (.literal word) tail) cached))) at he\n  have hh:=he.trans hr\n  cases hc:C.run program fuel (initial (SemiprimeD1StackExprCodec.encode (.literal word) tail) cached) with\n  | none => rw [hc] at hh;cases hh\n  | some out =>\n    rw [hc] at hh\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells word tail cached fuel out hc\n\nend RiemannGaussian.SemiprimeD1StackExprLiteralBounds\n","RiemannGaussian.SemiprimeD1StackFactorScopePairScan":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFactorScopePairEmit\n/-! # Exact EOF-controlled all-row projection in unchanged factor-major order -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackFactorScopePairScan\nopen SemiprimeD1StackFactorScopePairs SemiprimeD1FactorScopePairEncoding\nopen SemiprimeD1StackFactorScopePairView SemiprimeD1StackFactorScopePairEmit SemiprimeD1StackFactorScopePairPrimitives\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\n/-- Actual row clock includes nine parses, two frames and every cache erasure. -/\ndef rowTime (w : Record) : Nat :=9*mass w+10*((w 2).length+(w 0).length)+103\n/-- Every input row is processed once, including its initial physical peek. -/\ntheorem row_run (base : S.Stack→List Bool) (w : Record) (tail raw : List Bool) :\n    Runs program (rowTime w) (.local .loop) (clean base (record w tail) (fun _=>[]) raw)\n      (.local .loop) (clean base tail (fun _=>[]) ((row w).reverse++raw)) := by\n  have hp:Runs program 1 (.local .loop) (clean base (record w tail) (fun _=>[]) raw)\n      (.local (.field 0)) (clean base (record w tail) (fun _=>[]) raw) := by\n    apply one_base program (.local .loop) (.local (.field 0))\n      (.peek (aux .reader) (.local .finish) (.local (.field 0)) (.local (.field 0))) _ _ rfl\n    · change some (SemiprimeD1StackBytecode.choose _ _ _ (record w tail).head?)=_\n      rw [show record w tail=SemiprimeSourceHistogramKeyBits.frame (w 0) (suffix w 1 tail) from suffix_step w 0 tail]\n      cases w 0 <;> rfl\n    · rfl\n  have h:=hp.trans ((SemiprimeD1StackFactorScopePairParse.all_fields base w tail raw).trans\n    ((SemiprimeD1StackFactorScopePairEmit.row_run base tail w raw).trans\n      (all_clear base tail w ((row w).reverse++raw))))\n  simpa only [rowTime,show 1+((8*mass w+72)+((10*((w 2).length+(w 0).length)+21)+(mass w+9)))=\n      9*mass w+10*((w 2).length+(w 0).length)+103 by omega] using h\n/-- Exact source loop clock, ending at the physical EOF branch. -/\ndef loopTime : List Record→Nat\n  | []=>1\n  | w::ws=>rowTime w+loopTime ws\n/-- No record list is runtime advice: this theorem describes the actual EOF loop. -/\ntheorem loop_run (rows : List Record) (base : S.Stack→List Bool) (old : List Bool) :\n    Runs program (loopTime rows) (.local .loop) (clean base (stream rows []) (fun _=>[]) old)\n      (.local .finish) (clean base [] (fun _=>[]) ((raw rows).reverse++old)) := by\n  induction rows generalizing old with\n  | nil=>\n    apply one_base program (.local .loop) (.local .finish)\n      (.peek (aux .reader) (.local .finish) (.local (.field 0)) (.local (.field 0))) _ _ rfl\n    · rfl\n    · rfl\n  | cons w ws ih=>\n    have h:=(row_run base w (stream ws []) old).trans (ih ((row w).reverse++old))\n    simpa only [loopTime,stream,List.foldr_cons,raw,List.reverse_append,List.append_assoc] using h\n/-- Real EOF tag push and final physical reversal, preserving every old source role. -/\ntheorem finish_run (base : S.Stack→List Bool) (rows : List Record) :\n    Runs program (2*(raw rows).length+6) (.local .finish)\n      (clean base [] (fun _=>[]) (raw rows).reverse) (.local .done)\n      (data base [] (fun _=>[]) [] [] (SemiprimeD1StackOwnerFibre.records (rows.map pair) []) []) := by\n  have ht:Runs program 1 (.local .finish) (clean base [] (fun _=>[]) (raw rows).reverse)\n      (.local .finalReverse) (clean base [] (fun _=>[]) (false::(raw rows).reverse)) := by\n    apply one_base program (.local .finish) (.local .finalReverse)\n      (.push (aux .reversed) false (.local .finalReverse)) _ _ rfl\n    · rfl\n    · exact update_raw _ _ _ _ _ _ _ _\n  have hr:=reverse_call true (clean base [] (fun _=>[]) (false::(raw rows).reverse))\n    (.local .finalReverse) (.local .done) rfl\n  change Runs program (2*(false::(raw rows).reverse).length+3) _ _ _\n    (Function.update (Function.update (data base [] (fun _=>[]) (false::(raw rows).reverse) [] [] [])\n      (aux .reversed) []) (aux .output) ((false::(raw rows).reverse).reverse++[])) at hr\n  rw [update_raw,update_output] at hr\n  have h:=ht.trans hr\n  simpa only [List.length_cons,List.length_reverse,List.reverse_cons,List.reverse_reverse,List.append_nil,\n    raw_records,show 1+(2*((raw rows).length+1)+3)=2*(raw rows).length+6 by omega] using h\n/-- Complete actual projection time, including final literal halt. -/\ndef totalTime (rows : List Record) : Nat :=loopTime rows+2*(raw rows).length+7\n/-- Whole fixed source scan; every acquired field is consumed and every output bit written. -/\ntheorem scan_run (base : S.Stack→List Bool) (rows : List Record) :\n    C.run program (totalTime rows)\n      ⟨some (.local .loop),none,none,clean base (stream rows []) (fun _=>[]) [],[]⟩=\n      some ⟨none,none,none,data base [] (fun _=>[]) [] [] (SemiprimeD1StackOwnerFibre.records (rows.map pair) []) [],[]⟩ := by\n  have hl:=loop_run rows base []\n  simp only [List.append_nil] at hl\n  have h:=hl.trans (finish_run base rows)\n  obtain ⟨finish,hr,hAt⟩:=h [] (⟨some (.local .loop),none,none,clean base (stream rows []) (fun _=>[]) [],[]⟩ : C.State Stack Label) ⟨rfl,rfl,rfl⟩\n  have he:=SemiprimeD1StackProcedureTrace.halt_run program (.local .done) rfl\n    (data base [] (fun _=>[]) [] [] (SemiprimeD1StackOwnerFibre.records (rows.map pair) []) []) [] finish hAt\n  rw [show totalTime rows=(loopTime rows+(2*(raw rows).length+6))+1 by unfold totalTime;omega,\n    SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some,he]\nend RiemannGaussian.SemiprimeD1StackFactorScopePairScan\n","RiemannGaussian.SemiprimeD1StackHeapReadBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackHeapReadExecution\n\n/-! # Actual allocator-history heap dereference resources\nOriginal record bytes and unary references determine the executed scan. The\nproof derives field validity from allocator writes, and actual transition and\nprefix-space bounds from the literal linked program, without a read oracle.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackHeapReadBounds\nopen SemiprimeD1StackHeapRead SemiprimeD1StackHeapReadExecution\n\n/-- Proof-side total record payload, used only to bound actual serialized bytes. -/\ndef wordMass (records:List (List Bool)) : ℕ := (records.map List.length).sum\n\n/-- Every allocator frame contributes its literal tags, data and delimiter. -/\ntheorem heap_length (records:List (List Bool)) :\n    (SemiprimeD1StackHeapAllocate.heapBytes records).length=2*wordMass records+records.length := by\n  have h (records:List (List Bool)) (tail:List Bool) :\n      (records.foldl (fun bytes record=>SemiprimeSourceHistogramKeyBits.frame record bytes) tail).length=\n        tail.length+2*wordMass records+records.length := by\n    induction records generalizing tail with\n    | nil => simp [wordMass]\n    | cons word records ih =>\n      rw [List.foldl_cons,ih,SemiprimeSourceHistogramKeyBits.frame_length]\n      simp only [wordMass,List.map_cons,List.sum_cons,List.length_cons]\n      omega\n  simpa only [SemiprimeD1StackHeapAllocate.heapBytes,List.length_nil,Nat.zero_add] using h records []\n\n/-- Reversing actual record order preserves total physical data length. -/\ntheorem wordMass_reverse (records:List (List Bool)) : wordMass records.reverse=wordMass records := by\n  simp [wordMass]\n\n/-- The actual skip-loop transition count includes every parsed/copied/cleared bit. -/\ntheorem scanTime_eq (records:List (List Bool)) :\n    scanTime records=9*wordMass records+10*records.length+1 := by\n  induction records with\n  | nil => rfl\n  | cons word records ih =>\n    simp only [scanTime,wordMass,List.map_cons,List.sum_cons,List.length_cons] at ih ⊢\n    omega\n\n/-- Actual full dereference time is linear in heap, counter and reference lengths. -/\ntheorem readTime_le (before:List (List Bool)) (word:List Bool) (after:List (List Bool)) :\n    readTime before word after ≤\n      25*((SemiprimeD1StackHeapAllocate.heapBytes (before++word::after)).length+\n        (before++word::after).length+before.length+1) := by\n  have hm:wordMass (before++word::after)=wordMass before+word.length+wordMass after:=by\n    simp only [wordMass,List.map_append,List.map_cons,List.sum_append,List.sum_cons]\n    omega\n  unfold readTime\n  rw [scanTime_eq,wordMass_reverse,List.length_reverse]\n  simp only [heap_length,hm,List.length_append,List.length_cons]\n  omega\n\n/-- Finite original reference split; its record is read from the original store, not an answer parameter. -/\ntheorem split_at (records:List (List Bool)) (i:Fin records.length) :\n    records.take i.val++records[i.val]::records.drop (i.val+1)=records := by\n  rw [←List.drop_eq_getElem_cons i.isLt,List.take_append_drop]\n\n/-- Actual exact transition count at a finite allocator-issued ordinal. -/\ndef readTimeAt (records:List (List Bool)) (i:Fin records.length) : ℕ :=\n  readTime (records.take i.val) records[i.val] (records.drop (i.val+1))\n\n/-- Whole fixed program returns the actual indexed record and preserves the original heap. -/\ntheorem read_run (records:List (List Bool)) (i:Fin records.length) :\n    C.run program (readTimeAt records i)\n      (initial (SemiprimeD1StackHeapAllocate.heapBytes records) (List.replicate records.length true)\n        (List.replicate i.val true))=\n      some (done (SemiprimeD1StackHeapAllocate.heapBytes records) (List.replicate records.length true)\n        (List.replicate i.val true) records[i.val]) := by\n  have h:=read_split (records.take i.val) records[i.val] (records.drop (i.val+1))\n  have ht:(records.take i.val).length=i.val:=by\n    simp only [List.length_take,Nat.min_eq_left (Nat.le_of_lt i.isLt)]\n  rw [split_at records i,ht] at h\n  exact h\n\n/-- Closed actual transition cap, with no supplied getter or cost estimate. -/\ntheorem readTimeAt_le (records:List (List Bool)) (i:Fin records.length) :\n    readTimeAt records i ≤25*((SemiprimeD1StackHeapAllocate.heapBytes records).length+records.length+i.val+1) := by\n  have h:=readTime_le (records.take i.val) records[i.val] (records.drop (i.val+1))\n  have ht:(records.take i.val).length=i.val:=by\n    simp only [List.length_take,Nat.min_eq_left (Nat.le_of_lt i.isLt)]\n  rw [split_at records i,ht] at h\n  exact h\n\n/-- Genuine finite-machine heap read, from actual physical allocator data. -/\ndef readInTime (records:List (List Bool)) (i:Fin records.length) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration\n        (initial (SemiprimeD1StackHeapAllocate.heapBytes records) (List.replicate records.length true)\n          (List.replicate i.val true)))\n      (some (SemiprimeD1StackCalls.configuration\n        (done (SemiprimeD1StackHeapAllocate.heapBytes records) (List.replicate records.length true)\n          (List.replicate i.val true) records[i.val])))\n      (25*((SemiprimeD1StackHeapAllocate.heapBytes records).length+records.length+i.val+1)) := by\n  apply SemiprimeD1StackCalls.evalsCorrect Stack.heap Stack.output (.inl .start) program\n  exact ⟨⟨readTimeAt records i,read_run records i⟩,readTimeAt_le records i⟩\n\n/-- An actual allocation history starts empty and records real allocator transitions. -/\ninductive History : List (List Bool)→List Bool→List Bool→Prop where\n  /-- Empty physical heap and counter require no constructor advice. -/\n  | empty : History [] [] []\n  /-- The successor heap/counter are read from an actual executed allocator result. -/\n  | step {records:List (List Bool)} {heap counter:List Bool} (prev:History records heap counter)\n      (word:List Bool) (out:SemiprimeD1StackBytecode.State (Fin 6) (Fin 22))\n      (executed:SemiprimeD1StackBytecode.run SemiprimeD1StackHeapAllocate.code\n        (5*counter.length+6*word.length+7)\n        (SemiprimeD1StackHeapAllocate.state 0 none word heap [] counter [] [])=some out) :\n      History (records++[word]) (out.store 1) (out.store 3)\n\n/-- Well-formed framing and exact unary counter are derived from the executed allocation history. -/\ntheorem History.fields {records:List (List Bool)} {heap counter:List Bool} (h:History records heap counter) :\n    heap=SemiprimeD1StackHeapAllocate.heapBytes records ∧ counter=List.replicate records.length true := by\n  induction h with\n  | empty => exact ⟨rfl,rfl⟩\n  | @step records heap counter prev word out executed ih =>\n    have hr:=SemiprimeD1StackHeapAllocate.allocate_run word heap counter none\n    have hout:out=SemiprimeD1StackHeapAllocate.done word (SemiprimeSourceHistogramKeyBits.frame word heap)\n        (true::counter) counter:=Option.some.inj (executed.symm.trans hr)\n    subst out\n    simp only [SemiprimeD1StackHeapAllocate.done,SemiprimeD1StackHeapAllocate.payload,\n      show (1:Fin 6)≠0 by decide,ite_false,ite_true,\n      show (3:Fin 6)≠0 by decide,show (3:Fin 6)≠1 by decide,show (3:Fin 6)≠2 by decide]\n    rw [ih.1,ih.2,SemiprimeD1StackHeapAllocate.heapBytes_append]\n    simp only [List.length_append,List.length_cons,List.length_nil,List.replicate_succ,and_self]\n\n/-- History extension itself is acquired by the actual allocator, rather than assumed heap values. -/\ntheorem History.allocate {records:List (List Bool)} {heap counter:List Bool}\n    (h:History records heap counter) (word:List Bool) :\n    History (records++[word]) (SemiprimeSourceHistogramKeyBits.frame word heap) (true::counter) := by\n  exact History.step h word _ (SemiprimeD1StackHeapAllocate.allocate_run word heap counter none)\n\n/-- Original-history endpoint derives all framing/count facts before the actual read. -/\ndef readHistoryInTime {records:List (List Bool)} {heap counter:List Bool}\n    (history:History records heap counter) (i:Fin records.length) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial heap counter (List.replicate i.val true)))\n      (some (SemiprimeD1StackCalls.configuration (done heap counter (List.replicate i.val true) records[i.val])))\n      (25*(heap.length+counter.length+i.val+1)) := by\n  obtain ⟨rfl,rfl⟩:=history.fields\n  simpa only [List.length_replicate] using readInTime records i\n/-- Every literal-program prefix bounds each real Boolean data stack. -/\ntheorem prefix_data_bound (heap counter reference:List Bool) (fuel:ℕ) (out:C.State Stack Label)\n    (hr:C.run program fuel (initial heap counter reference)=some out) :\n    ∀k,(out.data k).length ≤ heap.length+counter.length+reference.length+fuel := by\n  apply SemiprimeD1StackReturnLink.run_data_bound program fuel\n    (heap.length+counter.length+reference.length) _ out ?_ hr\n  intro k\n  cases k <;> simp [initial,input] <;> omega\n\n/-- Count every actual Boolean data and fixed-alphabet return-frame cell at every prefix. -/\ntheorem prefix_cells (heap counter reference:List Bool) (fuel:ℕ) (out:C.State Stack Label)\n    (hr:C.run program fuel (initial heap counter reference)=some out) :\n    (out.data .heap).length+(out.data .counter).length+(out.data .reference).length+\n      (out.data .reader).length+(out.data .depth).length+(out.data .referenceWork).length+\n      (out.data .temporary).length+(out.data .fieldScratch).length+(out.data .output).length+\n      (out.data .valid).length+out.frames.length ≤11*(heap.length+counter.length+reference.length+fuel) := by\n  have h:=prefix_data_bound heap counter reference fuel out hr\n  have h0:=h .heap\n  have h1:=h .counter\n  have h2:=h .reference\n  have h3:=h .reader\n  have h4:=h .depth\n  have h5:=h .referenceWork\n  have h6:=h .temporary\n  have h7:=h .fieldScratch\n  have h8:=h .output\n  have h9:=h .valid\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel (initial heap counter reference) out hr\n  change out.frames.length ≤ 0+fuel at hf\n  omega\n\n/-- Actual successful execution cannot resume after a halted state. -/\ntheorem run_halted (n:ℕ) (state:C.State Stack Label) (hpc:state.pc=none) :\n    C.run program (n+1) state=none := by\n  unfold C.run\n  rw [Function.iterate_succ_apply]\n  have hs:C.step program state=none:=by simp [C.step,SemiprimeD1StackCalls.step,hpc]\n  simp only [Option.bind_some,hs]\n  exact Function.iterate_fixed rfl n\n\n/-- A successful actual prefix cannot extend past a proved actual halt. -/\ntheorem fuel_le_halt (time fuel:ℕ) (state finish out:C.State Stack Label)\n    (hh:C.run program time state=some finish) (hp:finish.pc=none)\n    (hr:C.run program fuel state=some out) : fuel ≤ time := by\n  by_contra h\n  have ht:fuel=time+((fuel-time-1)+1):=by omega\n  rw [ht,SemiprimeD1StackReturnLink.run_add,hh,Option.bind_some,run_halted _ finish hp] at hr\n  cases hr\n\n/-- The actual well-formed heap-read machine has linear all-visited storage, including return frames. -/\ntheorem machine_space (records:List (List Bool)) (i:Fin records.length) (fuel:ℕ) (cfg:machine.Cfg)\n    (hr:(fun cfg=>cfg.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration\n        (initial (SemiprimeD1StackHeapAllocate.heapBytes records) (List.replicate records.length true)\n          (List.replicate i.val true))))=some cfg) :\n    (cfg.stk (some Stack.heap)).length+(cfg.stk (some Stack.counter)).length+\n      (cfg.stk (some Stack.reference)).length+(cfg.stk (some Stack.reader)).length+\n      (cfg.stk (some Stack.depth)).length+(cfg.stk (some Stack.referenceWork)).length+\n      (cfg.stk (some Stack.temporary)).length+(cfg.stk (some Stack.fieldScratch)).length+\n      (cfg.stk (some Stack.output)).length+(cfg.stk (some Stack.valid)).length+(cfg.stk none).length ≤\n      286*((SemiprimeD1StackHeapAllocate.heapBytes records).length+records.length+i.val+1) := by\n  let state:=initial (SemiprimeD1StackHeapAllocate.heapBytes records) (List.replicate records.length true)\n    (List.replicate i.val true)\n  have he:=SemiprimeD1StackCalls.run_correct Stack.heap Stack.output (.inl .start) program fuel state\n  change (C.run program fuel state).map SemiprimeD1StackCalls.configuration=\n    (fun cfg=>cfg.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration state)) at he\n  cases hc:C.run program fuel state with\n  | none => rw [hc,hr] at he;cases he\n  | some out =>\n    rw [hc,hr] at he\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj he\n    rw [←hcfg]\n    have hspace:=prefix_cells (SemiprimeD1StackHeapAllocate.heapBytes records)\n      (List.replicate records.length true) (List.replicate i.val true) fuel out hc\n    have hf:=fuel_le_halt (readTimeAt records i) fuel state _ out (read_run records i) rfl hc\n    have ht:=readTimeAt_le records i\n    simp only [List.length_replicate] at hspace\n    change (out.data .heap).length+(out.data .counter).length+(out.data .reference).length+\n      (out.data .reader).length+(out.data .depth).length+(out.data .referenceWork).length+\n      (out.data .temporary).length+(out.data .fieldScratch).length+(out.data .output).length+\n      (out.data .valid).length+out.frames.length ≤ _\n    omega\n\n/-- Issued references originate in an actual allocator result, then persist across appends. -/\ninductive Issued : List (List Bool)→List Bool→Prop where\n  /-- The reference bytes are read from the actual allocator's returned pointer stack. -/\n  | fresh {records:List (List Bool)} {heap counter:List Bool} (prev:History records heap counter)\n      (word:List Bool) (out:SemiprimeD1StackBytecode.State (Fin 6) (Fin 22))\n      (executed:SemiprimeD1StackBytecode.run SemiprimeD1StackHeapAllocate.code\n        (5*counter.length+6*word.length+7)\n        (SemiprimeD1StackHeapAllocate.state 0 none word heap [] counter [] [])=some out) :\n      Issued (records++[word]) (out.store 4)\n  /-- The actual append-only allocator preserves every previously issued reference. -/\n  | keep {records:List (List Bool)} {reference:List Bool} (prev:Issued records reference)\n      (word:List Bool) : Issued (records++[word]) reference\n\n/-- Unary form and index validity are derived from actual reference issuance. -/\ntheorem Issued.valid {records:List (List Bool)} {reference:List Bool} (h:Issued records reference) :\n    reference=List.replicate reference.length true ∧ reference.length < records.length := by\n  induction h with\n  | @fresh records heap counter prev word out executed =>\n    have hr:=SemiprimeD1StackHeapAllocate.allocate_run word heap counter none\n    have hout:out=SemiprimeD1StackHeapAllocate.done word (SemiprimeSourceHistogramKeyBits.frame word heap)\n        (true::counter) counter:=Option.some.inj (executed.symm.trans hr)\n    subst out\n    have hc:=prev.fields.2\n    simp only [SemiprimeD1StackHeapAllocate.done,SemiprimeD1StackHeapAllocate.payload,\n      show (4:Fin 6)≠0 by decide,show (4:Fin 6)≠1 by decide,show (4:Fin 6)≠2 by decide,\n      show (4:Fin 6)≠3 by decide,ite_false,ite_true]\n    rw [hc]\n    simp only [List.length_replicate,List.length_append,List.length_cons,List.length_nil]\n    exact ⟨trivial,by omega⟩\n  | @keep records reference prev word ih =>\n    refine ⟨ih.1,?_⟩\n    simp only [List.length_append,List.length_cons,List.length_nil]\n    omega\n\n/-- Final original-history/issued-reference endpoint: no desired record or validity answer input. -/\ndef readIssuedInTime {records:List (List Bool)} {heap counter reference:List Bool}\n    (history:History records heap counter) (issued:Issued records reference) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial heap counter reference))\n      (some (SemiprimeD1StackCalls.configuration\n        (done heap counter reference (records.get ⟨reference.length,issued.valid.2⟩))))\n      (25*(heap.length+counter.length+reference.length+1)) := by\n  have href:=issued.valid.1\n  have h:=readHistoryInTime history (⟨reference.length,issued.valid.2⟩:Fin records.length)\n  simpa only [←href,List.get_eq_getElem] using h\n/-- Actual allocator histories and issued bytes close the all-visited memory bound directly. -/\ntheorem machine_history_space {records:List (List Bool)} {heap counter reference:List Bool}\n    (history:History records heap counter) (issued:Issued records reference)\n    (fuel:ℕ) (cfg:machine.Cfg)\n    (hr:(fun cfg=>cfg.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial heap counter reference)))=some cfg) :\n    (cfg.stk (some Stack.heap)).length+(cfg.stk (some Stack.counter)).length+\n      (cfg.stk (some Stack.reference)).length+(cfg.stk (some Stack.reader)).length+\n      (cfg.stk (some Stack.depth)).length+(cfg.stk (some Stack.referenceWork)).length+\n      (cfg.stk (some Stack.temporary)).length+(cfg.stk (some Stack.fieldScratch)).length+\n      (cfg.stk (some Stack.output)).length+(cfg.stk (some Stack.valid)).length+(cfg.stk none).length ≤\n      286*(heap.length+counter.length+reference.length+1) := by\n  obtain ⟨rfl,rfl⟩:=history.fields\n  have href:=issued.valid.1\n  have h:=machine_space records (⟨reference.length,issued.valid.2⟩:Fin records.length) fuel cfg\n    (by simpa only [←href] using hr)\n  simpa only [List.length_replicate] using h\nend RiemannGaussian.SemiprimeD1StackHeapReadBounds\n","RiemannGaussian.SemiprimeD1StackInputWidth":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackUnaryProductRaw\nimport RiemannGaussian.SemiprimeD1StackProcedureTrace\nimport RiemannGaussian.SemiprimeD1StackPhysicalLoops\n\n/-! # Actual active-digit bound from acquired physical counters\nThe public caller shares its actually acquired original bitwidth/radix caches\nand actual descriptor index. Real copies and the frozen physical product\nacquire i*B; literal paired pops compute min(B,ell-i*B), and actual bit pushes\nconstruct its power-of-two bound. No width, bound, comparison or work answer\nis supplied; all caches are preserved, all workspace is actually cleared.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 4096\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackInputWidth\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace U\nexport SemiprimeD1StackUnaryProduct (Stack Label code entry)\nend U\n/-- Nine fixed Boolean roles, before all original inputs and indices. -/\ninductive Stack where\n  | widthCache | radixCache | indexCache | remaining | multiplier | scratch | skip | limit | output\n  deriving DecidableEq,Repr\ninstance : Fintype Stack := Fintype.ofList\n  [.widthCache,.radixCache,.indexCache,.remaining,.multiplier,.scratch,.skip,.limit,.output]\n  (by intro k;cases k <;> simp)\n/-- Physical source cache view; list lengths occur only in proofs. -/\nstructure Cache where\n  /-- Original bitwidth markers produced by preprocessing. -/\n  width : List Bool\n  /-- Actual radix markers produced by preprocessing. -/\n  radix : List Bool\n  /-- Actual descriptor index markers, supplied by the upstream parser. -/\n  index : List Bool\n/-- Every preserving copy uses the same restored scratch, never a native copy. -/\ndef copyStack (kind : Fin 3) (k : Fin 3) : Stack :=\n  if k=0 then (if kind=0 then .widthCache else if kind=1 then .indexCache else .radixCache)\n  else if k=1 then (if kind=0 then .remaining else if kind=1 then .multiplier else .limit)\n  else .scratch\n/-- Real product registers directly share the actual retained radix cache. -/\ndef productStack : U.Stack→Stack\n  | .multiplier=>.multiplier\n  | .multiplicand=>.radixCache\n  | .scratch=>.scratch\n  | .product=>.skip\n/-- Fixed local and included procedure labels, with no arithmetic payload. -/\ninductive Label where\n  | start | copyIndex | multiply | skipLoop | dropWidth | clearSkip | copyLimit | initBound\n  | minLoop | minWidth | grow | clearRemaining | clearLimit | done\n  | copy (kind : Fin 3) (pc : Fin 9) | product (pc : U.Label)\n  deriving Fintype\n/-- ONE literal instruction table. Every read and cleanup byte is executed. -/\ndef program : Label→C.Instruction Stack Label\n  | .start=>.call (.copy 0 0) .copyIndex\n  | .copyIndex=>.call (.copy 1 0) .multiply\n  | .multiply=>.call (.product U.entry) .skipLoop\n  | .skipLoop=>.base (.pop .skip .copyLimit .dropWidth .dropWidth)\n  | .dropWidth=>.base (.pop .remaining .clearSkip .skipLoop .skipLoop)\n  | .clearSkip=>.base (.pop .skip .copyLimit .clearSkip .clearSkip)\n  | .copyLimit=>.call (.copy 2 0) .initBound\n  | .initBound=>.base (.push .output true .minLoop)\n  | .minLoop=>.base (.pop .limit .clearRemaining .minWidth .minWidth)\n  | .minWidth=>.base (.pop .remaining .clearLimit .grow .grow)\n  | .grow=>.base (.push .output false .minLoop)\n  | .clearRemaining=>.base (.pop .remaining .done .clearRemaining .clearRemaining)\n  | .clearLimit=>.base (.pop .limit .done .clearLimit .clearLimit)\n  | .done=>.base .halt\n  | .copy kind pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack kind) (Label.copy kind)\n      (SemiprimeD1StackCopy.code pc)\n  | .product pc=>SemiprimeD1StackMultiplierLink.instruction productStack Label.product (U.code pc)\n/-- Physical state view at actual procedure boundaries; scratch is empty there. -/\ndef store (c : Cache) (remaining multiplier skip limit output : List Bool) : Stack→List Bool\n  | .widthCache=>c.width\n  | .radixCache=>c.radix\n  | .indexCache=>c.index\n  | .remaining=>remaining\n  | .multiplier=>multiplier\n  | .scratch=>[]\n  | .skip=>skip\n  | .limit=>limit\n  | .output=>output\n/-- Initial source contains ONLY the three actual retained physical caches. -/\ndef initial (c : Cache) : C.State Stack Label := ⟨some .start,none,none,store c [] [] [] [] [],[]⟩\n/-- The THREE preserving copy-register inclusions are all physically injective. -/\ntheorem copy_injective (kind : Fin 3) : Function.Injective (copyStack kind) := by fin_cases kind <;> decide\n/-- The real product shares the radix, while all four of its roles stay distinct. -/\ntheorem product_injective : Function.Injective productStack := by decide\n/-- Actual fixed finite-alphabet machine, not a width/bound evaluator. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine .widthCache .output .start program\n/-- All actual data/return alphabets are fixed and finite before all caches. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite .widthCache .output Label.start program\n/-- No integer, list, width, bound or elapsed-count value occurs in control. -/\ntheorem control_finite : Finite machine.σ := SemiprimeD1StackCalls.control_finite .widthCache .output Label.start program\n/-- Exact physical data-role inventory, including shared restoration scratch. -/\ntheorem stack_card : Fintype.card Stack=9 := by decide\nend RiemannGaussian.SemiprimeD1StackInputWidth\n","RiemannGaussian.SemiprimeD1StackInputWidthBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackInputWidthExecution\nimport RiemannGaussian.SemiprimeD1StackFermatWords\n\n/-! # Actual active-digit acquisition: bit-time, space and strict-bound value -/\nset_option autoImplicit false\nset_option synthInstance.maxSize 4096\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1StackInputWidthBounds\nopen SemiprimeD1StackInputWidth SemiprimeD1StackInputWidthExecution\n\n/-- Physical cache cells are the only initial resource. -/\ndef inputSize (c : Cache) : ℕ := c.width.length+c.radix.length+c.index.length\n/-- One fixed quadratic allowance, before every cache value and index. -/\ndef runBound (c : Cache) : ℕ := 1000*(inputSize c+1)^2\n/-- Actual offset acquisition remains polynomial in the original physical\ncache lengths; the numerical power-of-two bound is NEVER counted in unary. -/\ntheorem timeBound_le (c : Cache) : timeBound c≤runBound c := by\n  let I:=inputSize c\n  have hi : c.index.length≤I+1 := by dsimp [I,inputSize];omega\n  have hb : c.radix.length≤I+1 := by dsimp [I,inputSize];omega\n  have hp : c.index.length*c.radix.length≤(I+1)^2 := by\n    simpa only [pow_two] using Nat.mul_le_mul hi hb\n  have hI : I+1≤(I+1)^2 := by\n    simpa only [pow_one] using Nat.pow_le_pow_right (by omega : 1≤I+1) (by decide : 1≤2)\n  change 100*(I+c.index.length*c.radix.length+1)≤1000*(I+1)^2\n  omega\n/-- Whole actual source with no supplied elapsed count or bound word. -/\ntheorem source_run_bounded (c : Cache) :\n    ∃t≤runBound c,C.run program t (initial c)=some (done c) := by\n  obtain ⟨t,ht,hr⟩:=source_run c\n  exact ⟨t,ht.trans (timeBound_le c),hr⟩\n/-- Proof-side choice of a real proved trace, never a clock opcode. -/\nnoncomputable def sourceBound (c : Cache) :\n    StateTransition.EvalsToInTime (C.step program) (initial c) (some (done c)) (runBound c) := by\n  let h:=source_run_bounded c\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Genuine fixed finite machine for the exact literal acquisition program. -/\nnoncomputable def boundInTime (c : Cache) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial c))\n      (some (SemiprimeD1StackCalls.configuration (done c))) (runBound c) :=\n  SemiprimeD1StackCalls.evalsCorrect Stack.widthCache Stack.output Label.start program _ _ _ (sourceBound c)\n/-- The acquired bound has linearly many binary cells even at zero width. -/\ntheorem bound_length (c : Cache) : (bound c).length=width c+1 := by\n  simp only [bound,List.length_append,List.length_replicate,List.length_singleton]\n/-- The physically constructed word is exactly the needed strict integer bound. -/\ntheorem bound_value (c : Cache) : SemiprimeBitArithmetic.bitValue (bound c)=2^width c := by\n  rw [bound,SemiprimeD1StackFermatWords.zeros_value]\n  simp only [SemiprimeBitArithmetic.bitValue,SemiprimeBitArithmetic.bitNat,ite_true,Nat.mul_zero,Nat.add_zero,Nat.mul_one]\n/-- A real low-bit peek detects positive active width, without a size/arity or\ndigit-count comparison oracle; zero width has the actual singleton-one bound. -/\ntheorem bound_head (c : Cache) :\n    (bound c).head?=some (if width c=0 then true else false) := by\n  cases hw:width c with\n  | zero=>simp only [bound,hw,ite_true,List.replicate_zero,List.nil_append,List.head?_cons]\n  | succ n=>simp only [bound,hw,Nat.succ_ne_zero,ite_false,List.replicate_succ,List.cons_append,List.head?_cons]\n/-- The width is paid from actual radix cells and can never exceed them. -/\ntheorem width_le_radix (c : Cache) : width c≤c.radix.length := Nat.min_le_left _ _\n/-- No successful actual source prefix extends beyond the complete proved halt. -/\ntheorem prefix_fuel_le (c : Cache) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial c)=some out) : fuel≤runBound c := by\n  obtain ⟨t,ht,hh⟩:=source_run_bounded c\n  have hf : fuel≤t := by\n    by_contra hn\n    have he : fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hh,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz : C.run program 1 (done c)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- EVERY prefix counts all nine data stacks and all actual return-label cells,\nincluding product/copy workspace, all retained caches and the binary output. -/\ntheorem prefix_cells (c : Cache) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial c)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤20000*(inputSize c+1)^2 := by\n  let I:=inputSize c\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel I _ out (by\n    intro k;cases k <;> simp [initial,store,I,inputSize] <;> omega) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs : (∑k : Stack,(out.data k).length)≤9*(I+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(I+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le c fuel out hr\n  change fuel≤1000*(I+1)^2 at ht\n  have hI : I≤(I+1)^2 := by\n    have h:=Nat.pow_le_pow_right (by omega : 1≤I+1) (by decide : 1≤2)\n    simp only [pow_one] at h\n    omega\n  change _≤20000*(I+1)^2\n  omega\n/-- Same complete storage theorem for actual compiled finite-machine prefixes. -/\ntheorem machine_prefix_cells (c : Cache) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial c)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤20000*(inputSize c+1)^2 := by\n  have he:=SemiprimeD1StackCalls.run_correct Stack.widthCache Stack.output Label.start program fuel (initial c)\n  change (C.run program fuel (initial c)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial c))) at he\n  have hh:=he.trans hr\n  cases hc:C.run program fuel (initial c) with\n  | none=>rw [hc] at hh;cases hh\n  | some out=>\n    rw [hc] at hh\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells c fuel out hc\nend RiemannGaussian.SemiprimeD1StackInputWidthBounds\n","RiemannGaussian.SemiprimeD1StackJetBlocksEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetBlocks\nimport RiemannGaussian.SemiprimeD1StackNetworkRowsEncoding\n/-! # Exact contiguous blocks and original offset-read interpretation\nThe lists and natural indices below specify physically streamed coefficient\nbytes. None occurs in the source instruction table or finite control.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackJetBlocksEncoding\nnamespace Codec\nexport SemiprimeD1StackNetworkRowsEncoding (payload payload_vector payload_length chunk chunk_length)\nend Codec\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- Sequentially read exactly rank actual/default-empty coefficient words. -/\ndef padded :Nat→List (List Bool)→List (List Bool)\n  | 0,_=>[]\n  | rank+1,words=>words.headD []::padded rank words.tail\n/-- Exactly one real/default coefficient field per actual rank marker. -/\ntheorem padded_length (rank:Nat) (words:List (List Bool)) :(padded rank words).length=rank :=by\n  induction rank generalizing words with\n  | zero=>rfl\n  | succ rank ih=>simp only [padded,List.length_cons,ih]\n/-- Actual EOF padding preserves the original empty-word zero convention, without trimming any input coefficient. -/\ntheorem padded_nil (rank:Nat) :padded rank []=List.replicate rank [] :=by\n  induction rank with\n  | zero=>rfl\n  | succ rank ih=>simp only [padded,List.headD_nil,List.tail_nil,ih,List.replicate_succ]\n/-- Literal sequential reads equal all original offset-free finite reads/defaults. -/\ntheorem padded_range (rank:Nat) (words:List (List Bool)) :\n    padded rank words=(List.range rank).map (fun i=>(words[i]?).getD []) :=by\n  induction rank generalizing words with\n  | zero=>rfl\n  | succ rank ih=>\n    rw [padded,List.range_succ_eq_map,List.map_cons,List.map_map]\n    congr 1\n    · cases words <;> rfl\n    · rw [ih]\n      apply List.map_congr_left\n      intro i _\n      cases words <;> rfl\n/-- Sequential whole-block bytes are EXACTthe original JetBlockBits.extract cached-offset reads. -/\ntheorem padded_native (old:SemiprimeD1JetAxes.Context) (j:Nat) (words:List (List Bool)) :\n    padded old.rank (words.drop (j*old.rank))=(SemiprimeD1JetBlockBits.extract old j words).words :=by\n  rw [padded_range]\n  simp only [SemiprimeD1JetBlockBits.extract,List.map_map,Function.comp_def,\n    SemiprimeD1JetBlockBits.readCopy_bits,List.getElem?_drop]\n/-- Actual chronological block list, consuming each earlier field only once. -/\ndef chunks (rank:Nat) :Nat→List (List Bool)→List (List (List Bool))\n  | 0,_=>[]\n  | q+1,words=>padded rank words::chunks rank q (words.drop rank)\n/-- The number of actual emitted blocks is the actual q marker count, even with source EOF. -/\ntheorem chunks_length (rank q:Nat) (words:List (List Bool)) :(chunks rank q words).length=q :=by\n  induction q generalizing words with\n  | zero=>rfl\n  | succ q ih=>simp only [chunks,List.length_cons,ih]\n/-- Complete sequential traversal matches all original ascending block offsets. -/\ntheorem chunks_range (rank q:Nat) (words:List (List Bool)) :\n    chunks rank q words=(List.range q).map (fun j=>padded rank (words.drop (j*rank))) :=by\n  induction q generalizing words with\n  | zero=>rfl\n  | succ q ih=>\n    rw [chunks,List.range_succ_eq_map,List.map_cons,List.map_map,ih]\n    simp only [Nat.zero_mul,List.drop_zero]\n    congr 1\n    apply List.map_congr_left\n    intro j _\n    rw [List.drop_drop]\n    congr 2\n    rw [Nat.succ_mul]\n    omega\n/-- Exact original native phase-block order and every unchanged raw binary coefficient word. -/\ntheorem chunks_native (old:SemiprimeD1JetAxes.Context) (q:Nat) (words:List (List Bool)) :\n    chunks old.rank q words=(List.range q).map (fun j=>(SemiprimeD1JetBlockBits.extract old j words).words) :=by\n  rw [chunks_range]\n  apply List.map_congr_left\n  intro j _\n  exact padded_native old j words\n/-- Literal nested block output ABI, with actual coefficient padding and block order preserved. -/\ndef tape (rank q:Nat) (words:List (List Bool)) :List Bool :=vectorBits ((chunks rank q words).map vectorBits)\nend RiemannGaussian.SemiprimeD1StackJetBlocksEncoding\n","RiemannGaussian.SemiprimeD1StackJetBlocksReady":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetBlocksFinish\n/-! # Same literal block program on the caller's actually acquired old context\nThe context argument describes the entire existing physical cache. Its rank\nword is read by real copies; no rank number occurs in runtime control.+-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackJetBlocksReady\nopen SemiprimeD1StackJetBlocks SemiprimeD1StackJetBlocksPrimitives SemiprimeD1StackJetBlocksView\nopen SemiprimeD1StackJetBlocksEncoding SemiprimeD1StackJetBlocksInner SemiprimeD1StackJetBlocksLoop\nopen SemiprimeD1StackJetBlocksFinish SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nlocal notation \"ctl\" => Label.local\n/-- Existing context bank, actual q markers and actual physical coefficient vector. -/\ndef ready (context:X.Stack→List Bool) (q:Nat) (words:List (List Bool)) :C.State Stack Label :=\n  ⟨some (ctl .ready),none,none,data context (vectorBits words) (List.replicate q true) [] [] [] [] [] [] [],[]⟩\n/-- Whole clean halt, preserving every actual context/source/q word. -/\ndef done (context:X.Stack→List Bool) (rank q:Nat) (words:List (List Bool)) :C.State Stack Label :=\n  ⟨none,none,none,result context (vectorBits words) (List.replicate q true) (tape rank q words),[]⟩\n/-- Own literal ready-source allowance, including all copy/loop/output/trailing-drain/halt work. -/\ndef readyBound (rank q:Nat) (words:List (List Bool)) :Nat :=\n  5*q+5*(vectorBits words).length+8+loopBudget rank q words+\n    2*(Codec.payload ((chunks rank q words).map vectorBits)).length+\n    (vectorBits (words.drop (q*rank))).length+6\n/-- Both actual inputs are copied once, preserving them for the complete caller. -/\ntheorem setup_trace (context:X.Stack→List Bool) (q:Nat) (words:List (List Bool)) :\n    Runs program (5*q+5*(vectorBits words).length+8) (ctl .ready) (ready context q words).data\n      (ctl .outer) (data context (vectorBits words) (List.replicate q true) (List.replicate q true)\n        (vectorBits words) [] [] [] [] []) :=by\n  have h0:=copy_call .blocks .ready .copyVector rfl (ready context q words).data\n    (List.replicate q true) [] rfl rfl rfl\n  simp only [List.length_replicate,List.append_nil] at h0\n  change Runs program (5*q+4) _ _ _ (Function.update\n    (data context (vectorBits words) (List.replicate q true) [] [] [] [] [] [] []) (aux .todo) (List.replicate q true)) at h0\n  rw [data_todo] at h0\n  have h1:=copy_call .vector .copyVector .outer rfl\n    (data context (vectorBits words) (List.replicate q true) (List.replicate q true) [] [] [] [] [] [])\n    (vectorBits words) [] rfl rfl rfl\n  simp only [List.append_nil] at h1\n  change Runs program (5*(vectorBits words).length+4) _ _ _ (Function.update\n    (data context (vectorBits words) (List.replicate q true) (List.replicate q true) [] [] [] [] [] [])\n    (aux .reader) (vectorBits words)) at h1\n  rw [data_reader] at h1\n  have h:=join h0 h1\n  convert h using 1\n  omega\n/-- All actual ready-entry work, through physical cleanup and immediately before the real halt. -/\ntheorem ready_trace (context:X.Stack→List Bool) (rank q:Nat)\n    (hr:context X.rankCache=List.replicate rank true) (words:List (List Bool)) :\n    ∃t,t+1≤readyBound rank q words ∧ Runs program t (ctl .ready) (ready context q words).data\n      (ctl .done) (done context rank q words).data :=by\n  have h0:=setup_trace context q words\n  obtain ⟨a,ha,h1⟩:=blocks_run context (vectorBits words) (List.replicate q true) [] rank q hr words\n  simp only [List.append_nil] at h1\n  have h2:=finish_run context (vectorBits words) (List.replicate q true)\n    (vectorBits (words.drop (q*rank))) (Codec.payload ((chunks rank q words).map vectorBits)).reverse\n  simp only [List.length_reverse,List.reverse_reverse,Codec.payload_vector] at h2\n  have h:=join (join h0 h1) h2\n  refine ⟨(5*q+5*(vectorBits words).length+8)+a+\n      (2*(Codec.payload ((chunks rank q words).map vectorBits)).length+\n        (vectorBits (words.drop (q*rank))).length+5),?_,h⟩\n  unfold readyBound\n  omega\n/-- The SAMEliteral ready program halts at the EXACTnative ascending block vector. -/\ntheorem ready_run (context:X.Stack→List Bool) (rank q:Nat)\n    (hr:context X.rankCache=List.replicate rank true) (words:List (List Bool)) :\n    ∃t≤readyBound rank q words,SemiprimeD1StackCalls.run program t (ready context q words)=\n      some (done context rank q words) :=by\n  obtain ⟨t,ht,h⟩:=ready_trace context rank q hr words\n  obtain ⟨out,ho,ha⟩:=h [] (ready context q words) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl (done context rank q words).data [] out ha\n  exact ⟨t+1,ht,by rw [SemiprimeD1StackReturnLink.run_add,ho,Option.bind_some];exact hh⟩\nend RiemannGaussian.SemiprimeD1StackJetBlocksReady\n","RiemannGaussian.SemiprimeD1StackJetFoldPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetFoldState\n/-! # Paid literal copy/parser/frame/return traces for the same ordered fold -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackJetFoldPrimitives\nopen SemiprimeD1StackJetFold SemiprimeD1StackJetFoldState SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\" => Label.local\n/-- Actual traces concatenate without introducing any extra source operation. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after):\n    Runs program (m+n) pc before next after:=runs_trans program m n pc mid next before between after h g\n/-- Literal source slot for each real preserving-copy site. -/\ndef copyFrom:Copy→Slot | .children=>.children | .sum=>.sum | .product=>.result\n/-- Literal target slot for each real preserving-copy site. -/\ndef copyTo:Copy→Slot | .children=>.modes | .sum=>.tailSum | .product=>.product\n/-- Static source/target addresses stay separate at all three actual sites. -/\ntheorem copy_ne (site:Copy):address (copyFrom site)≠address (copyTo site):=by cases site <;> decide\n/-- Restoring-copy work is separate from each physical destination. -/\ntheorem copy_work_ne (site:Copy):aux .copyScratch≠address (copyTo site):=by cases site <;> decide\n/-- Every preserving copy includes its actual call and physical return. -/\ntheorem copy_view (site:Copy) (pc next:Control) (v:Values)\n    (hc:program (ctl pc)=.call (.copy site 0) (ctl next)):\n    Runs program (5*(v (copyFrom site)).length+4) (ctl pc) (data v) (ctl next)\n      (data (Function.update v (copyTo site) (v (copyFrom site)++v (copyTo site)))):=by\n  rw [data_update]\n  apply included_call program (copyStack site) (Label.copy site) (copy_injective site)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) (ctl pc) (ctl next) hc (5*(v (copyFrom site)).length+3)\n    (SemiprimeD1StackCopy.state 0 none (v (copyFrom site)) (v (copyTo site)) [])\n    (SemiprimeD1StackCopy.done (v (copyFrom site)) (v (copyFrom site)++v (copyTo site))) _ _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words _ _ none)\n  · constructor\n    · intro k;fin_cases k\n      · change data v (copyStack site 0)=v (copyFrom site)\n        cases site with\n        | children=>exact data_get v .children\n        | sum=>exact data_get v .sum\n        | product=>exact data_get v .result\n      · change data v (copyStack site 1)=v (copyTo site)\n        cases site with\n        | children=>exact data_get v .modes\n        | sum=>exact data_get v .tailSum\n        | product=>exact data_get v .product\n      · exact copy_scratch_empty v\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · change Function.update (data v) (address (copyTo site)) _ (copyStack site 0)=v (copyFrom site)\n        have he:copyStack site 0=address (copyFrom site):=by cases site <;> rfl\n        rw [he,Function.update_of_ne (copy_ne site),data_get]\n      · have he:copyStack site 1=address (copyTo site):=by cases site <;> rfl\n        change Function.update (data v) (address (copyTo site)) _ (copyStack site 1)=_\n        rw [he,Function.update_self]\n        rfl\n      · change Function.update (data v) (address (copyTo site)) _ (aux .copyScratch)=[]\n        rw [Function.update_of_ne (copy_work_ne site),copy_scratch_empty]\n    · intro k hk\n      exact Function.update_of_ne (fun he=>hk 1 (by cases site <;> exact he.symm)) _ _\n/-- Literal saved-head source slot; the target is the one real framed activation word. -/\ndef savedFrom (child:Bool):Slot:=if child then .left else .group\n/-- Each real saved-head frame has separate source and destination. -/\ntheorem save_ne (child:Bool):address (savedFrom child)≠address .frames:=by cases child <;> decide\n/-- Every head is physically framed before the tail call, including the real call/return cost. -/\ntheorem save_view (child:Bool) (pc next:Control) (v:Values)\n    (hc:program (ctl pc)=.call (.save child 0) (ctl next)):\n    Runs program (6*(v (savedFrom child)).length+5) (ctl pc) (data v) (ctl next)\n      (data (Function.update v .frames (frame (v (savedFrom child)) (v .frames)))):=by\n  rw [data_update]\n  apply included_call program (saveStack child) (Label.save child) (save_injective child)\n    SemiprimeD1StackFrame.code 0 (fun _=>rfl) (ctl pc) (ctl next) hc (6*(v (savedFrom child)).length+4)\n    (SemiprimeD1StackFrame.state 0 none (v (savedFrom child)) (v .frames) [])\n    (SemiprimeD1StackFrame.done (v (savedFrom child)) (frame (v (savedFrom child)) (v .frames))) _ _ rfl rfl\n    (SemiprimeD1StackFrame.frame_words _ _ none)\n  · constructor\n    · intro k;fin_cases k\n      · change data v (saveStack child 0)=v (savedFrom child)\n        cases child with\n        | false=>exact data_get v .group\n        | true=>exact data_get v .left\n      · exact data_get v .frames\n      · exact frame_scratch_empty v\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · change Function.update (data v) (address .frames) _ (saveStack child 0)=v (savedFrom child)\n        have he:saveStack child 0=address (savedFrom child):=by cases child <;> rfl\n        rw [he,Function.update_of_ne (save_ne child),data_get]\n      · exact Function.update_self _ _ _\n      · change Function.update (data v) (address .frames) _ (aux .frameScratch)=[]\n        rw [Function.update_of_ne (by decide:aux .frameScratch≠address .frames),frame_scratch_empty]\n    · intro k hk\n      exact Function.update_of_ne (fun he=>hk 1 he.symm) _ _\n/-- Literal reader slot for each real input/saved-head field parser. -/\ndef readFrom:Parse→Slot | .mode=>.modes | .child=>.group | .restoreMode|.restoreChild=>.frames\n/-- Literal output slot for each actual parsed/restored head. -/\ndef readTo:Parse→Slot | .mode|.restoreMode=>.group | .child|.restoreChild=>.left\n/-- Every parser executes the immutable field decoder and writes its true validity marker. -/\ntheorem field_view (site:Parse) (pc next:Control) (v:Values) (word tail:List Bool)\n    (hc:program (ctl pc)=.call (.field site (F.active .tagPop (none,false))) (ctl next))\n    (hi:v (readFrom site)=frame word tail) (ho:v (readTo site)=[]) (hv:v .valid=[]):\n    Runs program (8*word.length+7) (ctl pc) (data v) (ctl next)\n      (data (Function.update (Function.update (Function.update v (readFrom site) tail) (readTo site) word) .valid [true])):=by\n  let before:=SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) []\n  let after:SemiprimeD1StackBytecode.State F.Stack F.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩\n  have hin:SemiprimeD1StackMultiplierLink.DataRel (fieldStack site) (data v) before.store (data v):=by\n    constructor\n    · intro k\n      rcases k with k|k\n      · cases k\n        · have he:fieldStack site (.inl .input)=address (readFrom site):=by cases site <;> rfl\n          change data v (fieldStack site (.inl .input))=frame word tail\n          rw [he,data_get,hi]\n        · exact field_scratch_empty v\n        · have he:fieldStack site (.inl .output)=address (readTo site):=by cases site <;> rfl\n          change data v (fieldStack site (.inl .output))=[]\n          rw [he,data_get,ho]\n      · cases k\n        change data v (address .valid)=[]\n        rw [data_get,hv]\n    · intro k _;rfl\n  apply included_call program (fieldStack site) (Label.field site) (field_injective site) F.code\n    (F.active .tagPop (none,false)) (fun _=>rfl) (ctl pc) (ctl next) hc (8*word.length+6)\n    before after _ _ rfl rfl (SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []) hin\n  have h0:=SemiprimeD1StackMultiplierLink.data_update (fieldStack site) (field_injective site) (data v) before.store (data v) hin (.inl .input) tail\n  have h1:=SemiprimeD1StackMultiplierLink.data_update (fieldStack site) (field_injective site) (data v) _ _ h0 (.inl .output) word\n  have h2:=SemiprimeD1StackMultiplierLink.data_update (fieldStack site) (field_injective site) (data v) _ _ h1 (.inr ()) [true]\n  have he:Function.update (Function.update (Function.update before.store (.inl .input) tail) (.inl .output) word) (.inr ()) [true]=after.store:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h2\n  have hreader:fieldStack site (.inl .input)=address (readFrom site):=by cases site <;> rfl\n  have hword:fieldStack site (.inl .output)=address (readTo site):=by cases site <;> rfl\n  have hvalid:fieldStack site (.inr ())=address .valid:=rfl\n  rw [hreader,hword,hvalid,←data_update,←data_update,←data_update] at h2\n  exact h2\n/-- One literal physical push, with the exact live-word update. -/\ntheorem push_view (pc next:Control) (s:Slot) (b:Bool) (v:Values)\n    (hc:program (ctl pc)=.base (.push (address s) b (ctl next))):\n    Runs program 1 (ctl pc) (data v) (ctl next) (data (Function.update v s (b::v s))):=by\n  rw [data_update]\n  exact one_base program _ _ _ _ _ hc rfl (by rw [←data_get v s];rfl)\n/-- One literal physical pop; its branch depends only on the actual leading Boolean cell. -/\ntheorem pop_view (pc empty low high:Control) (s:Slot) (v:Values) (word:List Bool)\n    (hc:program (ctl pc)=.base (.pop (address s) (ctl empty) (ctl low) (ctl high))) (hx:v s=word):\n    Runs program 1 (ctl pc) (data v)\n      (SemiprimeD1StackBytecode.choose (ctl empty) (ctl low) (ctl high) word.head?)\n      (data (Function.update v s word.tail)):=by\n  rw [data_update]\n  apply one_base program _ _ _ _ _ hc\n  · simp only [SemiprimeD1StackBytecode.execute,data_get,hx]\n  · simp only [SemiprimeD1StackBytecode.execute,data_get,hx]\n/-- Every actual cleanup bit and its final EOF are counted. -/\ntheorem drain_view (pc next:Control) (s:Slot) (v:Values)\n    (hc:program (ctl pc)=.base (.pop (address s) (ctl next) (ctl pc) (ctl pc))):\n    Runs program ((v s).length+1) (ctl pc) (data v) (ctl next) (data (Function.update v s [])):=by\n  generalize hw:v s=word\n  induction word generalizing v with\n  | nil=>simpa only [hw,List.length_nil,Nat.zero_add,List.head?_nil,List.tail_nil,SemiprimeD1StackBytecode.choose]\n      using pop_view pc next pc pc s v [] hc hw\n  | cons b word ih=>\n    have h0:=pop_view pc next pc pc s v (b::word) hc hw\n    have h1:=ih (Function.update v s word) (Function.update_self _ _ _)\n    have h:=join (by cases b <;> exact h0) h1\n    simpa only [hw,Function.update_idem,List.length_cons,Nat.add_comm,Nat.add_left_comm,Nat.add_assoc] using h\n/-- Actual recursion pushes and later pops a real fixed-label return symbol, preserving all outer frames. -/\ntheorem recursive_call (pc entry next:Control) (before after:Stack→List Bool) (time:Nat)\n    (hc:program (ctl pc)=.call (ctl entry) (ctl next))\n    (hr:Runs program time (ctl entry) before (ctl .returning) after):\n    Runs program (time+2) (ctl pc) before (ctl next) after:=by\n  intro frames target h\n  rcases h with ⟨hp,hd,hf⟩\n  let mid:=SemiprimeD1StackCalls.execute (.call (ctl entry) (ctl next)) target\n  have hm:SemiprimeD1StackCalls.run program 1 target=some mid:=by\n    change SemiprimeD1StackCalls.step program target=some mid\n    simp only [SemiprimeD1StackCalls.step,hp,Option.map_some,hc,mid]\n  obtain ⟨finish,hRun,hAt⟩:=hr ((ctl next)::frames) mid (by\n    simp only [At,mid,SemiprimeD1StackCalls.execute,hd,hf,and_self])\n  let last:=SemiprimeD1StackCalls.execute .ret finish\n  have hl:SemiprimeD1StackCalls.run program 1 finish=some last:=by\n    change SemiprimeD1StackCalls.step program finish=some last\n    simp only [SemiprimeD1StackCalls.step,hAt.1,Option.map_some,program,last]\n  refine ⟨last,?_,?_,?_,?_⟩\n  · rw [show time+2=1+(time+1) by omega,SemiprimeD1StackReturnLink.run_add,hm,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add,hRun,Option.bind_some]\n    exact hl\n  · simp only [last,SemiprimeD1StackCalls.execute,hAt.2.2]\n  · simpa only [last,SemiprimeD1StackCalls.execute,hAt.2.2] using hAt.2.1\n  · simp only [last,SemiprimeD1StackCalls.execute,hAt.2.2]\nend RiemannGaussian.SemiprimeD1StackJetFoldPrimitives\n","RiemannGaussian.SemiprimeD1StackJetFoldSpec":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetFoldOperators\n/-! # Actual header/recursive boundaries and own literal fold allowances\nThe allowances sum actual frozen operator caps and literal parser/frame/copy/\ndrain/return costs. Native JetRun clocks are never used as a physical clock.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackJetFoldSpec\nopen SemiprimeD1StackJetFold SemiprimeD1StackJetFoldState SemiprimeD1StackJetFoldWords\nopen SemiprimeD1StackJetFoldOperators\nopen SemiprimeD1JetAxes (Context)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\n/-- Actual original inputs and actually acquired metadata at a real fold boundary. -/\nstructure Header where\n  /-- Original physical unary-axis header. -/\n  axes:List Bool\n  /-- Original binary precision word. -/\n  precision:List Bool\n  /-- Actual prepared nested child-result vector, retained without recoding its coefficients. -/\n  children:List Bool\n  /-- Actual physically acquired unary rank counter. -/\n  rank:List Bool\n  /-- Actual physically acquired unary precision count. -/\n  width:List Bool\n/-- The acquired physical context agrees with its native proof-side interpretation. -/\nstructure Matches (ctx:Context) (h:Header):Prop where\n  /-- Actual positive-axis encoding. -/\n  axes:h.axes=vectorBits (ctx.axes.map unary)\n  /-- Actual unary precision width. -/\n  width:h.width.length=ctx.precision\n  /-- Actual unary rank word. -/\n  rank:h.rank=unary ctx.rank\n/-- All physical caller/operator boundary words with a fixed actually acquired context. -/\ndef bank (h:Header) (modes group frames left product result tailSum sum valid:List Bool):Values:=\n  values h.axes h.precision h.children h.rank h.width modes group frames left product result tailSum sum valid\n/-- Actual product entry; remaining modes and the caller's saved sum words are untouched. -/\ndef productNode (h:Header) (modes tailSum sum:List Bool) (children:Group) (frames:List Bool):Values:=\n  bank h modes (groupTape children) frames [] [] [] tailSum sum []\n/-- Actual product return boundary after its complete input vector and temporary operands were consumed. -/\ndef productOut (h:Header) (modes tailSum sum:List Bool) (answer:Jet) (frames:List Bool):Values:=\n  bank h modes [] frames [] (jetTape answer) [] tailSum sum []\n/-- Actual complete sum entry, with one real saved activation suffix. -/\ndef sumNode (h:Header) (modes:Modes) (frames:List Bool):Values:=\n  bank h (modeTape modes) [] frames [] [] [] [] [] []\n/-- Actual complete sum return boundary, retaining all context and original child inputs. -/\ndef sumOut (h:Header) (answer:Jet) (frames:List Bool):Values:=\n  bank h [] [] frames [] [] [] [] (jetTape answer) []\n/-- The real adder computes dense zero from two physically seeded empty-vector markers. -/\ntheorem add_empty_zero (ctx:Context):\n    (SemiprimeD1JetRingBits.add ctx [] []).words=(SemiprimeD1JetAffineCoefficient.zero ctx).words:=by\n  have hz:(SemiprimeD1JetScalarBits.add ctx.precision [] []).bits=[]:=by\n    cases ctx.precision <;> simp [SemiprimeD1JetScalarBits.add,SemiprimeBitArithmetic.addBits,\n      SemiprimeD1JetScalarBits.reduce,SemiprimeD1JetScalarBits.takeBits,SemiprimeSourceCompactBits.trim]\n  simp only [SemiprimeD1JetRingBits.add,List.map_map,Function.comp_def,\n    SemiprimeD1JetRingBits.addAt,SemiprimeD1JetRingBits.read,SemiprimeD1JetAffineCoefficient.zero]\n  rw [hz,List.map_const',List.length_range]\n/-- Frozen actual multiplication cap on the two currently restored binary vectors. -/\ndef multiplyCost (ctx:Context) (h:Header) (a b:Jet):Nat:=\n  mulBound ctx (bank h [] [] [] (jetTape a) (jetTape b) [] [] [] [])\n/-- Exact frozen actual dense-addition time plus its physical caller transition. -/\ndef addCost (h:Header) (a b:Jet):Nat:=SemiprimeD1StackJetAddExecution.totalTime h.width h.rank a b+1\n/-- Actual per-product-node allowance includes every saved/read/copied/drained payload bit. -/\ndef productEdge (ctx:Context) (h:Header) (x:Jet) (xs:Group):Nat:=\n  multiplyCost ctx h x (productWords ctx xs)+100*((jetTape x).length+\n    (jetTape (productWords ctx xs)).length+(jetTape (productWords ctx (x::xs))).length+1)\n/-- Own actual primitive-derived right-product allowance. -/\ndef productBudget (ctx:Context) (h:Header):Group→Nat\n  | []=>SemiprimeD1StackJetUnitExecution.totalTime h.width h.rank+2\n  | x::xs=>productBudget ctx h xs+productEdge ctx h x xs\n/-- Actual per-mode allowance includes the entire real saved head group and saved tail-sum bytes. -/\ndef sumEdge (ctx:Context) (h:Header) (x:Group) (xs:Modes):Nat:=\n  addCost h (productWords ctx x) (sumWords ctx xs)+100*((groupTape x).length+(jetTape (sumWords ctx xs)).length+1)\n/-- Own actual primitive-derived right-mode-sum allowance, including every complete head product. -/\ndef sumBudget (ctx:Context) (h:Header):Modes→Nat\n  | []=>SemiprimeD1StackJetAddExecution.totalTime h.width h.rank [] []+4\n  | x::xs=>sumBudget ctx h xs+productBudget ctx h x+sumEdge ctx h x xs\nend RiemannGaussian.SemiprimeD1StackJetFoldSpec\n","RiemannGaussian.SemiprimeD1StackJetPointBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetPointCorrectness\n/-! # Actual convolution-point polynomial transition bounds\nOnly physical input inventory and original context dimensions enter this bound.\nAll read lengths, partial sums and included component clocks are derived.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 4096\nset_option maxRecDepth 8192\nset_option maxHeartbeats 1500000\nnamespace RiemannGaussian.SemiprimeD1StackJetPointBounds\nopen SemiprimeD1StackJetPoint SemiprimeD1StackJetPointExecution SemiprimeD1StackJetPointLoops\nopen SemiprimeD1StackJetPointTerm SemiprimeD1StackJetPointRead\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeD1JetAxes (Context)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n\n/-- Literal physical inventories and original scalar dimensions; no output,\nintermediate fit, operation-cost or callback bound occurs in these caps. -/\nstructure Caps (ctx : Context) (c : Cache) (a b : List (List Bool)) (S : ℕ) : Prop where\n  rank : ctx.rank ≤ S\n  precision : ctx.precision ≤ S\n  axes : ctx.axes.length ≤ S\n  width : c.width.length ≤ S\n  axisTape : c.axes.length ≤ S\n  rankTape : c.rank.length ≤ S\n  target : c.target.length ≤ S\n  left : (vectorBits a).length ≤ S\n  right : (vectorBits b).length ≤ S\n\n/-- Every actual cached coefficient is shorter than its original encoded tape. -/\ntheorem coefficient_length (words : List (List Bool)) (i : ℕ) :\n    ((words[i]?).getD []).length ≤ (vectorBits words).length := by\n  induction words generalizing i with\n  | nil => simp [vectorBits]\n  | cons w ws ih =>\n    cases i with\n    | zero => simp only [List.getElem?_cons_zero,Option.getD_some,vectorBits,List.length_cons,\n        SemiprimeSourceHistogramKeyBits.frame_length]; omega\n    | succ i =>\n      have hh:=ih i\n      simp only [List.getElem?_cons_succ]\n      simp only [vectorBits,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length]\n      omega\n\n/-- Pure fixed polynomial monotonicity, separated from all program semantics. -/\ntheorem pipelineBudget_mono {n m c p N M C P : ℕ} (hn : n ≤ N) (hm : m ≤ M) (hc : c ≤ C) (hp : p ≤ P) :\n    pipelineBudget n m c p ≤ pipelineBudget N M C P := by\n  unfold pipelineBudget\n  gcongr\n\n/-- Uniform explicit cubic bound for one actual physical pair visit. -/\ndef pairBound (S : ℕ) : ℕ :=\n  23*S+25+20000*(S+1)^2*(3*S+1)+(10*S+8)+(60*(2*S+2)+2)+pipelineBudget S S S S\n\n/-- Every possible per-pair intermediate has a derived precision width. -/\ntheorem pairStep_length (ctx : Context) (a b : List (List Bool)) (k i j : ℕ) (acc : List Bool)\n    (ha : acc.length ≤ ctx.precision) :\n    (SemiprimeD1StackJetPointOrder.pairStep ctx a b k (i,j) acc).length ≤ ctx.precision := by\n  unfold SemiprimeD1StackJetPointOrder.pairStep\n  split_ifs\n  · exact SemiprimeD1JetScalarBits.add_length _ _ _\n  · exact ha\n\n/-- All literal per-pair calls have the cubic original-inventory cap. -/\ntheorem pairBudget_le (ctx : Context) (c : Cache) (a b : List (List Bool)) (S i j : ℕ) (acc : List Bool)\n    (h : Caps ctx c a b S) (hi : i ≤ S) (hj : j ≤ S) (ha : acc.length ≤ ctx.precision) :\n    pairBudget ctx c i j acc a b ≤ pairBound S := by\n  have hac : acc.length ≤ S := ha.trans h.precision\n  have hl:= (coefficient_length a i).trans h.left\n  have hr:= (coefficient_length b j).trans h.right\n  have hp:=pipelineTime_le ((a[i]?).getD []) ((b[j]?).getD []) acc c.width\n  have hd:=pipelineBudget_mono hl hr hac h.width\n  have hpipe:=hp.trans hd\n  have hleft:=SemiprimeD1StackJetReadExecution.totalTime_le (unary i) a\n  have hright:=SemiprimeD1StackJetReadExecution.totalTime_le (unary j) b\n  unfold SemiprimeD1StackJetReadExecution.timeBound at hleft hright\n  simp only [unary,List.length_replicate] at hleft hright\n  have hread : readPipelineTime c.width (unary i) (unary j) acc a b ≤\n      (10*S+8)+(60*(2*S+2)+2)+pipelineBudget S S S S := by\n    dsimp only [readPipelineTime]\n    simp only [unary,List.length_replicate]\n    have hA:=h.left\n    have hB:=h.right\n    omega\n  have hroute : SemiprimeD1StackJetRouteExecution.budget ctx.axes i j ≤\n      20000*(S+1)^2*(3*S+1) := by\n    unfold SemiprimeD1StackJetRouteExecution.budget\n    have hprod : ctx.axes.prod ≤ S := h.rank\n    gcongr\n    · exact h.axes\n    · omega\n  have hax:=h.axisTape\n  have htarget:=h.target\n  unfold pairBudget pairBound\n  omega\n\n/-- Every executed inner prefix preserves the derived scalar precision cap. -/\ntheorem innerValue_length (ctx : Context) (a b : List (List Bool)) (k i n : ℕ) (acc : List Bool)\n    (ha : acc.length ≤ ctx.precision) :\n    (innerValue ctx a b k i n acc).length ≤ ctx.precision := by\n  rw [innerValue_eq]\n  exact SemiprimeD1StackJetPointOrder.accumulate_length _ _ _ _ _ _ ha\n\n/-- The actual inner-loop report is linear in its physical iteration count. -/\ntheorem innerClock_le (ctx : Context) (c : Cache) (a b : List (List Bool)) (S k i n : ℕ) (acc : List Bool)\n    (h : Caps ctx c a b S) (hi : i ≤ S) (hn : n ≤ S) (ha : acc.length ≤ ctx.precision) :\n    innerClock ctx c a b k i n acc ≤ (n+1)*(pairBound S+2) := by\n  induction n generalizing acc with\n  | zero => simp only [innerClock,Nat.zero_add,Nat.one_mul]; omega\n  | succ n ih =>\n    have hn' : n ≤ S := by omega\n    have hp:=pairBudget_le ctx c a b S i n acc h hi hn' ha\n    have hs:=pairStep_length ctx a b k i n acc ha\n    have hc:=ih _ hn' hs\n    change 1+pairBudget ctx c i n acc a b+\n      innerClock ctx c a b k i n (SemiprimeD1StackJetPointOrder.pairStep ctx a b k (i,n) acc) ≤ _\n    nlinarith\n\n/-- Uniform explicit quartic per-row bound. -/\ndef rowBound (S : ℕ) : ℕ := (5*S+4)+(S+1)*(pairBound S+2)+2\n\n/-- The actual outer-loop report is linear in its physical row count. -/\ntheorem outerClock_le (ctx : Context) (c : Cache) (a b : List (List Bool)) (S k rank n : ℕ) (acc : List Bool)\n    (h : Caps ctx c a b S) (hr : rank ≤ S) (hn : n ≤ S) (ha : acc.length ≤ ctx.precision) :\n    outerClock ctx c a b k rank n acc ≤ (n+1)*rowBound S := by\n  induction n generalizing acc with\n  | zero => simp only [outerClock,Nat.zero_add,Nat.one_mul]; unfold rowBound; omega\n  | succ n ih =>\n    have hn' : n ≤ S := by omega\n    have hinner:=innerClock_le ctx c a b S k n rank acc h hn' hr ha\n    have hscale:=Nat.mul_le_mul_right (pairBound S+2) (Nat.add_le_add_right hr 1)\n    have hs:=innerValue_length ctx a b k n rank acc ha\n    have hout:=ih _ hn' hs\n    have hrt:=h.rankTape\n    change 1+(5*c.rank.length+4)+innerClock ctx c a b k n rank acc+\n      outerClock ctx c a b k rank n (innerValue ctx a b k n rank acc) ≤ _\n    unfold rowBound at *\n    nlinarith\n\n/-- Fixed degree-five transition polynomial, without coefficients chosen from data. -/\ndef budget (S : ℕ) : ℕ := 5*S+5+(S+1)*rowBound S\n\n/-- The whole actual coefficient execution has the fixed polynomial envelope. -/\ntheorem totalClock_le (ctx : Context) (c : Cache) (a b : List (List Bool)) (S k : ℕ)\n    (h : Caps ctx c a b S) :\n    SemiprimeD1StackJetPointCorrectness.totalClock ctx c a b k ≤ budget S := by\n  have ho:=outerClock_le ctx c a b S k ctx.rank ctx.rank [] h h.rank h.rank (by simp)\n  have hr:=h.rankTape\n  unfold SemiprimeD1StackJetPointCorrectness.totalClock budget\n  have hs:=Nat.mul_le_mul_right (rowBound S) (Nat.add_le_add_right h.rank 1)\n  omega\n\n/-- The explicit transition envelope is bounded by one fixed monomial. -/\ntheorem budget_le_power (S : ℕ) : budget S ≤ 1000000*(S+1)^5 := by\n  unfold budget rowBound pairBound pipelineBudget\n  nlinarith [Nat.zero_le (S^2),Nat.zero_le (S^3),Nat.zero_le (S^4),Nat.zero_le (S^5)]\n\n/-- Actual prepared input inventory and original context dimensions. -/\ndef inputSize (ctx : Context) (c : Cache) : ℕ :=\n  ctx.rank+ctx.precision+ctx.axes.length+c.width.length+c.axes.length+c.rank.length+\n    c.target.length+c.a.length+c.b.length+1\n\n/-- Actual encoded inputs discharge all resource caps internally. -/\ntheorem caps_of_inputs (ctx : Context) (c : Cache) (a b : List (List Bool))\n    (ha : c.a=vectorBits a) (hb : c.b=vectorBits b) : Caps ctx c a b (inputSize ctx c) := by\n  constructor\n  · unfold inputSize; omega\n  · unfold inputSize; omega\n  · unfold inputSize; omega\n  · unfold inputSize; omega\n  · unfold inputSize; omega\n  · unfold inputSize; omega\n  · unfold inputSize; omega\n  · rw [←ha]; unfold inputSize; omega\n  · rw [←hb]; unfold inputSize; omega\n\n/-- Closed original-input polynomial time, not a supplied operation-cost cap. -/\ntheorem source_run_polynomial (ctx : Context) (hp : ctx.Positive) (c : Cache) (a b : List (List Bool)) (k : ℕ)\n    (ha : c.a=vectorBits a) (hb : c.b=vectorBits b)\n    (haxes : c.axes=vectorBits (ctx.axes.map unary))\n    (hwidth : c.width.length=ctx.precision) (htarget : c.target.length=k) (hrank : c.rank=unary ctx.rank) :\n    ∃ m ≤ 1000000*(inputSize ctx c+1)^5,\n      SemiprimeD1StackCalls.run program m (initial c.a c.b c.axes c.width c.rank c.target)=\n        some (⟨none,none,none,resting c [] [] (SemiprimeD1JetRingBits.mulAt ctx a b k).bits,[]⟩:\n          SemiprimeD1StackCalls.State Stack Label) := by\n  obtain ⟨m,hm,hr⟩:=SemiprimeD1StackJetPointCorrectness.source_run ctx hp c a b k ha hb haxes hwidth htarget hrank\n  exact ⟨m,hm.trans ((totalClock_le ctx c a b (inputSize ctx c) k (caps_of_inputs ctx c a b ha hb)).trans\n    (budget_le_power _)),hr⟩\n\n/-- Genuine compiled finite-machine coefficient execution in a fixed degree-five\npolynomial of original inventory, rank, precision and physical target length. -/\nnoncomputable def machinePointPolynomial (ctx : Context) (hp : ctx.Positive) (c : Cache)\n    (a b : List (List Bool)) (k : ℕ) (ha : c.a=vectorBits a) (hb : c.b=vectorBits b)\n    (haxes : c.axes=vectorBits (ctx.axes.map unary))\n    (hwidth : c.width.length=ctx.precision) (htarget : c.target.length=k) (hrank : c.rank=unary ctx.rank) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial c.a c.b c.axes c.width c.rank c.target))\n      (some (SemiprimeD1StackCalls.configuration\n        (⟨none,none,none,resting c [] [] (SemiprimeD1JetRingBits.mulAt ctx a b k).bits,[]⟩:\n          SemiprimeD1StackCalls.State Stack Label))) (1000000*(inputSize ctx c+1)^5) := by\n  let h:=source_run_polynomial ctx hp c a b k ha hb haxes hwidth htarget hrank\n  let m:=Classical.choose h\n  have hm:=Classical.choose_spec h\n  apply SemiprimeD1StackCalls.evalsCorrect (aux .a) (aux .acc) Label.start program\n  exact ⟨⟨m,hm.2⟩,hm.1⟩\n\n/-- Every actual original successful prefix ends no later than the proved halt. -/\ntheorem prefix_fuel_le (ctx : Context) (hp : ctx.Positive) (c : Cache) (a b : List (List Bool)) (k : ℕ)\n    (ha : c.a=vectorBits a) (hb : c.b=vectorBits b)\n    (haxes : c.axes=vectorBits (ctx.axes.map unary))\n    (hwidth : c.width.length=ctx.precision) (htarget : c.target.length=k) (hrank : c.rank=unary ctx.rank)\n    (fuel : ℕ) (out : SemiprimeD1StackCalls.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial c.a c.b c.axes c.width c.rank c.target)=some out) :\n    fuel ≤ 1000000*(inputSize ctx c+1)^5 := by\n  obtain ⟨m,hm,hstop⟩:=source_run_polynomial ctx hp c a b k ha hb haxes hwidth htarget hrank\n  by_contra hn\n  have he : fuel=m+(1+(fuel-(m+1))) := by omega\n  rw [he,SemiprimeD1StackReturnLink.run_add,hstop,Option.bind_some,\n    SemiprimeD1StackReturnLink.run_add] at hr\n  have hh : SemiprimeD1StackCalls.run program 1\n      (⟨none,none,none,resting c [] [] (SemiprimeD1JetRingBits.mulAt ctx a b k).bits,[]⟩:\n        SemiprimeD1StackCalls.State Stack Label)=none := rfl\n  rw [hh,Option.bind_none] at hr\n  cases hr\n\n/-- Every original physical stack word is initially bounded by input inventory. -/\ntheorem initial_length (ctx : Context) (c : Cache) (k : Stack) :\n    ((initial c.a c.b c.axes c.width c.rank c.target).data k).length ≤ inputSize ctx c := by\n  rw [SemiprimeD1StackJetPointCorrectness.initial_data]\n  rcases k with k|k\n  · simp [resting,inputSize]\n  · rcases k with k|k\n    · rcases k with k|k\n      · simp [resting,inputSize]\n      · cases k <;> simp [resting,inputSize]; omega\n    · rcases k with k|k\n      · simp [resting,inputSize]\n      · cases k <;> simp [resting,inputSize] <;> omega\n\n/-- All successful prefixes retain only polynomial Boolean data and real return cells. -/\ntheorem prefix_cells (ctx : Context) (hp : ctx.Positive) (c : Cache) (a b : List (List Bool)) (k : ℕ)\n    (ha : c.a=vectorBits a) (hb : c.b=vectorBits b)\n    (haxes : c.axes=vectorBits (ctx.axes.map unary))\n    (hwidth : c.width.length=ctx.precision) (htarget : c.target.length=k) (hrank : c.rank=unary ctx.rank)\n    (fuel : ℕ) (out : SemiprimeD1StackCalls.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel (initial c.a c.b c.axes c.width c.rank c.target)=some out) :\n    (∑s:Stack,(out.data s).length)+out.frames.length ≤\n      54*(inputSize ctx c+1000000*(inputSize ctx c+1)^5+1) := by\n  have hf:=prefix_fuel_le ctx hp c a b k ha hb haxes hwidth htarget hrank fuel out hr\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (inputSize ctx c) _ out\n    (initial_length ctx c) hr\n  have hframes:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length ≤ 0+fuel at hframes\n  have hs : (∑s:Stack,(out.data s).length) ≤ 53*(inputSize ctx c+fuel) := by\n    calc\n      _ ≤ ∑_s:Stack,(inputSize ctx c+fuel) := Finset.sum_le_sum (fun s _=>hd s)\n      _ = 53*(inputSize ctx c+fuel) := by\n        have hc : Fintype.card Stack=53 := by decide\n        simp [hc]\n  omega\n\n/-- The same polynomial storage bound applies to every compiled-machine prefix. -/\ntheorem machine_prefix_cells (ctx : Context) (hp : ctx.Positive) (c : Cache) (a b : List (List Bool)) (k : ℕ)\n    (ha : c.a=vectorBits a) (hb : c.b=vectorBits b)\n    (haxes : c.axes=vectorBits (ctx.axes.map unary))\n    (hwidth : c.width.length=ctx.precision) (htarget : c.target.length=k) (hrank : c.rank=unary ctx.rank)\n    (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial c.a c.b c.axes c.width c.rank c.target)))=some cfg) :\n    (∑s:Stack,(cfg.stk (some s)).length)+(cfg.stk none).length ≤\n      54*(inputSize ctx c+1000000*(inputSize ctx c+1)^5+1) := by\n  let start:=initial c.a c.b c.axes c.width c.rank c.target\n  have he:=SemiprimeD1StackCalls.run_correct (aux .a) (aux .acc) Label.start program fuel start\n  change (SemiprimeD1StackCalls.run program fuel start).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel] (some (SemiprimeD1StackCalls.configuration start)) at he\n  cases hc:SemiprimeD1StackCalls.run program fuel start with\n  | none => rw [hc,hr] at he; cases he\n  | some out =>\n    rw [hc,hr] at he\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj he\n    rw [←hcfg]\n    exact prefix_cells ctx hp c a b k ha hb haxes hwidth htarget hrank fuel out hc\n\nend RiemannGaussian.SemiprimeD1StackJetPointBounds\n","RiemannGaussian.SemiprimeD1StackJetRouteFields":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetRouteCalls\n/-! # Physical parsing of internally acquired radix records -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackJetRouteFields\nopen SemiprimeD1StackJetRoute SemiprimeD1StackJetRouteCalls\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\" => SemiprimeD1StackJetRoute.control\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\n\ntheorem field_injective (b : Bool) : Function.Injective (fieldStack b) := by\n  intro x y h\n  cases b <;> cases x with\n  | inl x => cases x <;> cases y with\n    | inl y => cases y <;> simp_all [fieldStack]\n    | inr y => cases y; simp_all [fieldStack]\n  | inr x => cases x; cases y with\n    | inl y => cases y <;> simp_all [fieldStack]\n    | inr y => cases y; rfl\n\n/-- The internally acquired axis field is parsed by the actual finite field procedure. -/\ntheorem read_axis (word tail left right result : List Bool) :\n    Trace.Runs code (8*word.length+7) (ctl .readQ)\n      (bank [] (frame word tail) left right result [] [] [] [] [] [] [] []) (ctl .qDone) (bank [] tail left right result [] word [] [] [] [] [] [true]) := by\n  have hr := SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []\n  apply Trace.included_call code (fieldStack false) fieldQLabel (field_injective false) F.code\n    (F.active .tagPop (none,false)) (fun _=>rfl) (ctl .readQ) (ctl .qDone) rfl\n    (8*word.length+6) _ _ _ _ rfl rfl hr\n  · constructor\n    · intro k; cases k with\n      | inl k=>cases k <;> rfl\n      | inr k=>cases k; rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k; cases k with\n      | inl k=>cases k <;> rfl\n      | inr k=>cases k; rfl\n    · intro k hk\n      cases k <;> first | rfl | exact (hk (.inl .input) rfl).elim | exact (hk (.inl .output) rfl).elim | exact (hk (.inr ()) rfl).elim\n\n/-- The internally acquired denominator field is parsed by the actual finite field procedure. -/\ntheorem read_denominator (word tail left right result q : List Bool) :\n    Trace.Runs code (8*word.length+7) (ctl .readD)\n      (bank [] (frame word tail) left right result [] q [] [] [] [] [] []) (ctl .dDone) (bank [] tail left right result [] q word [] [] [] [] [true]) := by\n  have hr := SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []\n  apply Trace.included_call code (fieldStack true) fieldDLabel (field_injective true) F.code\n    (F.active .tagPop (none,false)) (fun _=>rfl) (ctl .readD) (ctl .dDone) rfl\n    (8*word.length+6) _ _ _ _ rfl rfl hr\n  · constructor\n    · intro k; cases k with\n      | inl k=>cases k <;> rfl\n      | inr k=>cases k; rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k; cases k with\n      | inl k=>cases k <;> rfl\n      | inr k=>cases k; rfl\n    · intro k hk\n      cases k <;> first | rfl | exact (hk (.inl .input) rfl).elim | exact (hk (.inl .output) rfl).elim | exact (hk (.inr ()) rfl).elim\n\nend RiemannGaussian.SemiprimeD1StackJetRouteFields\n","RiemannGaussian.SemiprimeD1StackJetRouteStep":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetRouteFailure\n/-! # Actual successful mixed-radix record traversal -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackJetRouteStep\nopen SemiprimeD1StackJetRoute SemiprimeD1StackJetRouteCalls SemiprimeD1StackJetRouteFields\nopen SemiprimeD1StackJetRouteDigits SemiprimeD1StackJetRouteControl\nopen SemiprimeD1StackJetRouteFailure (compose)\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\" => SemiprimeD1StackJetRoute.control\n\ntheorem flag_true (pc next : Label)\n    (hcode : code pc=.base (.pop .valid (ctl (.fail 0)) (ctl (.fail 0)) next))\n    (axes records left right result radix q d quotLeft remLeft quotRight remRight : List Bool) :\n    Trace.Runs code 1 pc (bank axes records left right result radix q d quotLeft remLeft quotRight remRight [true])\n      next (bank axes records left right result radix q d quotLeft remLeft quotRight remRight []) := by\n  apply Trace.one_base code pc next (.pop .valid (ctl (.fail 0)) (ctl (.fail 0)) next) _ _ hcode\n  · simp [SemiprimeD1StackBytecode.execute,SemiprimeD1StackBytecode.choose]\n  · simp [SemiprimeD1StackBytecode.execute]\n\ntheorem peek_record (word tail left right result : List Bool) :\n    Trace.Runs code 1 (ctl .recordPeek)\n      (bank [] (frame word tail) left right result [] [] [] [] [] [] [] [])\n      (ctl .readQ) (bank [] (frame word tail) left right result [] [] [] [] [] [] [] []) := by\n  apply Trace.one_base code (ctl .recordPeek) (ctl .readQ)\n    (.peek .records (ctl .baseLeft) (ctl .readQ) (ctl .readQ)) _ _ rfl\n  · cases word <;> simp [SemiprimeD1StackBytecode.execute,SemiprimeD1StackBytecode.choose,frame]\n  · rfl\n\n/-- A compatible original radix record is parsed, divided, physically compared,\ncleared, and replaced by the actually executed remainder counters. -/\ntheorem compatible_step (q d i j : ℕ) (ha : i/d+j/d<q) (tail result : List Bool) :\n    ∃m≤2000*(q+d+i+j+1),Trace.Runs code m (ctl .recordPeek)\n      (bank [] (frame (unary q) (frame (unary d) tail)) (unary i) (unary j) result [] [] [] [] [] [] [] [])\n      (ctl .recordPeek) (bank [] tail (unary (i%d)) (unary (j%d)) result [] [] [] [] [] [] [] []) := by\n  have h1 := peek_record (unary q) (frame (unary d) tail) (unary i) (unary j) result\n  have h2 := read_axis (unary q) (frame (unary d) tail) (unary i) (unary j) result\n  have h3 := flag_true (ctl .qDone) (ctl .readD) rfl [] (frame (unary d) tail)\n    (unary i) (unary j) result [] (unary q) [] [] [] [] []\n  have h4 := read_denominator (unary d) tail (unary i) (unary j) result (unary q)\n  have h5 := flag_true (ctl .dDone) (ctl .divideLeft) rfl [] tail\n    (unary i) (unary j) result [] (unary q) (unary d) [] [] [] []\n  obtain ⟨a,haClock,h6⟩ := divide_left i j d tail result (unary q)\n  obtain ⟨b,hbClock,h7⟩ := divide_right j d tail result (unary q) (unary (i/d)) (unary (i%d))\n  obtain ⟨c,hcClock,h8⟩ := compare_digits (i/d) (j/d) q tail result (unary d) (unary (i%d)) (unary (j%d))\n  simp only [ha,decide_true] at h8\n  have h9 := flag_true (ctl .compareDone) (ctl .clearD) rfl [] tail [] [] result [] []\n    (unary d) [] (unary (i%d)) [] (unary (j%d))\n  have h10 := clear_denominator tail result (unary d) (unary (i%d)) (unary (j%d))\n  have h11 := move_left (i%d) tail result (unary (j%d))\n  have h12 := move_right (j%d) tail result (unary (i%d))\n  have h := compose h1 (compose h2 (compose h3 (compose h4 (compose h5 (compose h6\n    (compose h7 (compose h8 (compose h9 (compose h10 (compose h11 h12))))))))))\n  refine ⟨_,?_,h⟩\n  simp only [SemiprimeD1StackUnaryDivmod.unary,List.length_replicate]\n  have hi := Nat.div_le_self i d\n  have hj := Nat.div_le_self j d\n  have hri := Nat.mod_le i d\n  have hrj := Nat.mod_le j d\n  omega\n\n/-- Every live byte of the fixed routing bank is included in this literal width. -/\ntheorem bank_width (axes records left right result radix q d qi ri qj rj valid : List Bool) :\n    ∀k,(bank axes records left right result radix q d qi ri qj rj valid k).length≤\n      axes.length+records.length+left.length+right.length+result.length+radix.length+\n        q.length+d.length+qi.length+ri.length+qj.length+rj.length+valid.length := by\n  intro k; cases k <;> simp only [bank,List.length_nil] <;> omega\n\n/-- Incompatible digits actually enter and execute full physical cleanup. -/\ntheorem incompatible_step (q d i j : ℕ) (ha : ¬i/d+j/d<q) (tail result : List Bool) :\n    ∃m≤2000*(q+d+i+j+tail.length+result.length+1),Trace.Runs code m (ctl .recordPeek)\n      (bank [] (frame (unary q) (frame (unary d) tail)) (unary i) (unary j) result [] [] [] [] [] [] [] [])\n      (ctl .halt) (bank [] [] [] [] [] [] [] [] [] [] [] [] [false]) := by\n  have h1 := peek_record (unary q) (frame (unary d) tail) (unary i) (unary j) result\n  have h2 := read_axis (unary q) (frame (unary d) tail) (unary i) (unary j) result\n  have h3 := flag_true (ctl .qDone) (ctl .readD) rfl [] (frame (unary d) tail)\n    (unary i) (unary j) result [] (unary q) [] [] [] [] []\n  have h4 := read_denominator (unary d) tail (unary i) (unary j) result (unary q)\n  have h5 := flag_true (ctl .dDone) (ctl .divideLeft) rfl [] tail\n    (unary i) (unary j) result [] (unary q) (unary d) [] [] [] []\n  obtain ⟨a,haClock,h6⟩ := divide_left i j d tail result (unary q)\n  obtain ⟨b,hbClock,h7⟩ := divide_right j d tail result (unary q) (unary (i/d)) (unary (i%d))\n  obtain ⟨c,hcClock,h8⟩ := compare_digits (i/d) (j/d) q tail result (unary d) (unary (i%d)) (unary (j%d))\n  simp only [ha,decide_false] at h8\n  have h9 : Trace.Runs code 1 (ctl .compareDone)\n      (bank [] tail [] [] result [] [] (unary d) [] (unary (i%d)) [] (unary (j%d)) [false])\n      (ctl (.fail 0)) (bank [] tail [] [] result [] [] (unary d) [] (unary (i%d)) [] (unary (j%d)) []) := by\n    apply Trace.one_base code (ctl .compareDone) (ctl (.fail 0))\n      (.pop .valid (ctl (.fail 0)) (ctl (.fail 0)) (ctl .clearD)) _ _ rfl\n    · simp [SemiprimeD1StackBytecode.execute,SemiprimeD1StackBytecode.choose]\n    · simp [SemiprimeD1StackBytecode.execute]\n  have hw := bank_width [] tail [] [] result [] [] (unary d) [] (unary (i%d)) [] (unary (j%d)) []\n  simp only [List.length_nil,SemiprimeD1StackUnaryDivmod.unary,List.length_replicate,Nat.zero_add,Nat.add_zero] at hw\n  obtain ⟨z,hz,h10⟩ := SemiprimeD1StackJetRouteFailure.reject_clean _ _ hw\n  have h := compose h1 (compose h2 (compose h3 (compose h4 (compose h5 (compose h6\n    (compose h7 (compose h8 (compose h9 h10))))))))\n  refine ⟨_,?_,h⟩\n  simp only [SemiprimeD1StackUnaryDivmod.unary,List.length_replicate]\n  have hi := Nat.div_le_self i d\n  have hj := Nat.div_le_self j d\n  have hri := Nat.mod_le i d\n  have hrj := Nat.mod_le j d\n  omega\n\nend RiemannGaussian.SemiprimeD1StackJetRouteStep\n","RiemannGaussian.SemiprimeD1StackJetScalarMul":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackValidationLink\nimport RiemannGaussian.SemiprimeD1StackMultiplierExecution\nimport RiemannGaussian.SemiprimeD1StackProcedureTrace\nimport RiemannGaussian.SemiprimeD1StackReduceExecution\n\n/-! # Actual canonical modular scalar multiplication\nThe real fixed multiplier is included as a nested-call procedure. Its binary\nproduct is directly consumed by the real reducer using a copied precision cache.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1StackJetScalarMul\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace M\nexport SemiprimeD1StackMultiplier (Stack Label code payload input factor)\nend M\n\n/-- Eleven fixed Boolean data stacks, including cached precision and copy work. -/\nabbrev Stack := M.Stack ⊕ Bool\n\n/-- Actual reducer inclusion consumes the product accumulator directly. -/\ndef reduceStack : SemiprimeD1StackAdder.Stack → Stack\n  | .left => .inl (.inl .right)\n  | .right => .inl (.inl .left)\n  | .scratch => .inl (.inl .scratch)\n  | .output => .inl (.inl .output)\n\n/-- Precision is physically copied into the reducer counter input. -/\ndef copyStack (k : Fin 3) : Stack :=\n  if k=0 then .inr false else if k=1 then reduceStack .right else .inr true\n\n/-- Distinct literal reducer operands. -/\ntheorem reduceStack_injective : Function.Injective reduceStack := by decide\n\n/-- Distinct literal precision-copy operands. -/\ntheorem copyStack_injective : Function.Injective copyStack := by decide\n\n/-- Fixed calls and finite component labels, independent of all input lengths/values. -/\ninductive Label where\n  | start | copyPrecision | callReduce | done\n  | multiply (pc : M.Label)\n  | copy (pc : Fin 9)\n  | reduce (pc : SemiprimeD1StackReduce.Label)\n  deriving DecidableEq,Fintype,Repr\n\n/-- Actual fixed multiplier/copy/reducer caller with real nested return frames. -/\ndef program : Label → C.Instruction Stack Label\n  | .start => .call (.multiply (.control .start)) .copyPrecision\n  | .copyPrecision => .call (.copy 0) .callReduce\n  | .callReduce => .call (.reduce .take) .done\n  | .done => .base .halt\n  | .multiply pc => SemiprimeD1StackValidationLink.instruction Sum.inl Label.multiply (M.code pc)\n  | .copy pc => SemiprimeD1StackMultiplierLink.instruction copyStack Label.copy (SemiprimeD1StackCopy.code pc)\n  | .reduce pc => SemiprimeD1StackMultiplierLink.instruction reduceStack Label.reduce (SemiprimeD1StackReduce.code pc)\n\n/-- Literal multiplier input/work/result bank and retained physical precision cache. -/\ndef store (xs ys ds left acc scratch output cp cs width work : List Bool) : Stack → List Bool\n  | .inl k => M.payload xs ys ds left acc scratch output cp cs k\n  | .inr false => width\n  | .inr true => work\n\n/-- Actual concrete source configuration, without preloaded return-frame advice. -/\ndef state (pc : Option Label) (flag : Option Bool) (returned : Option Label)\n    (xs ys ds left acc scratch output cp cs width work : List Bool) : C.State Stack Label :=\n  ⟨pc,flag,returned,store xs ys ds left acc scratch output cp cs width work,[]⟩\n\n/-- Actual fixed finite-stack machine; original coefficients and precision are physical payload. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine\n  (Sum.inl M.input) (reduceStack .output) Label.start program\n\nend RiemannGaussian.SemiprimeD1StackJetScalarMul\n","RiemannGaussian.SemiprimeD1StackKernelLinearCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackKernelLinearPrimitives\n/-! # Actual five-field fitting and eleven-field restoring-division calls -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackKernelLinearCalls\nopen SemiprimeD1StackKernelLinear SemiprimeD1StackKernelLinearPrimitives\nopen SemiprimeD1StackProcedureTrace\n/-- Exact real fit clock includes its actual caller return. -/\ndef fitTime (word template:List Bool):Nat:=SemiprimeD1StackWordFitExecution.totalTime word template+1\n/-- A complete actual fit changes only its consumed operand and fresh result. -/\ntheorem fit_call (second:Bool) (pc next:Label) (hc:program pc=.call (.fit second .start) next)\n    (before:Stack→List Bool) (word template:List Bool)\n    (hi:∀r,before (fitStack second r)=SemiprimeD1StackWordFit.store word template [] [] [] r):\n    Runs program (fitTime word template) pc before next\n      (Function.update (Function.update before (fitStack second 0) []) (fitStack second 4)\n        (SemiprimeD1StackWordFitExecution.result word template)):=by\n  let source:=SemiprimeD1StackWordFit.initial word template\n  let stop:=SemiprimeD1StackWordFitExecution.done word template\n  have hin:Link.DataRel (fitStack second) before source.data before:=⟨hi,fun _ _=>rfl⟩\n  have h0:=Link.data_update (fitStack second) (fit_injective second) before source.data before hin (0:Fin 5) []\n  have h1:=Link.data_update (fitStack second) (fit_injective second) before\n    (Function.update source.data 0 []) (Function.update before (fitStack second 0) []) h0 (4:Fin 5)\n    (SemiprimeD1StackWordFitExecution.result word template)\n  have he:Function.update (Function.update source.data 0 []) 4 (SemiprimeD1StackWordFitExecution.result word template)=stop.data:=by\n    funext r;fin_cases r <;> rfl\n  rw [he] at h1\n  exact SemiprimeD1StackProcedureCallsTrace.included_call program (fitStack second) (Label.fit second)\n    (fit_injective second) F.program .start (fun _=>rfl) pc next hc _ source stop before _ rfl rfl rfl rfl\n    (SemiprimeD1StackWordFitExecution.source_run word template) hin h1\n/-- Division entry consumes copied operands, preserving every eighteen-role source/cache word. -/\ntheorem divide_call (pc next:Label) (hc:program pc=.call (.divide (.control .start)) next)\n    (u:Aux→List Bool) (xs ys:List Bool):\n    Runs program (SemiprimeD1StackDividerExecution.executionTime xs ys+1) pc\n      (Sum.elim (SemiprimeD1StackDivider.payload xs ys [] [] [] [] [] [] [] [] []) u) next\n      (Sum.elim (SemiprimeD1StackDivider.payload [] [] [] [] [] [] []\n        (SemiprimeBitDivision.divideLoop xs ys).remainder (SemiprimeBitDivision.divideLoop xs ys).quotient [] []) u):=by\n  let source:=SemiprimeD1StackDivider.state (some (.control .start)) none none xs ys [] [] [] [] [] [] [] [] []\n  let stop:=SemiprimeD1StackDivider.state none none none [] [] [] [] [] [] []\n    (SemiprimeBitDivision.divideLoop xs ys).remainder (SemiprimeBitDivision.divideLoop xs ys).quotient [] []\n  have hi:Link.DataRel divider (Sum.elim source.data u) source.data (Sum.elim source.data u):=⟨fun _=>rfl,fun _ _=>rfl⟩\n  have ho:Link.DataRel divider (Sum.elim source.data u) stop.data (Sum.elim stop.data u):=by\n    constructor\n    · intro r;rfl\n    · intro r hr\n      rcases r with r|r\n      · exact False.elim (hr r rfl)\n      · rfl\n  exact SemiprimeD1StackProcedureCallsTrace.included_call program divider Label.divide Sum.inl_injective\n    D.code (.control .start) (fun _=>rfl) pc next hc _ source stop _ _ rfl rfl rfl rfl\n    (SemiprimeD1StackDividerExecution.source_run xs ys) hi ho\nend RiemannGaussian.SemiprimeD1StackKernelLinearCalls\n","RiemannGaussian.SemiprimeD1StackKernelLinearMeaning":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackKernelLinearNormalize\n/-! # Byte-exact original normalized-factor identification\nNo old report clock is used. The signed constant, dyadic content and quotient\nare identified individually before any interpreted integer equality.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackKernelLinearMeaning\nopen SemiprimeD1StackKernelLinearView\nopen SemiprimeBitArithmetic SemiprimeBitDivision SemiprimeBitIndexClipping\nopen SemiprimeD1RecoveryIntegerBits\nnamespace Spec\nexport SemiprimeD1StackKernelLinearSpec\n  (factor magnitude negative odd power difference_word strip_bytes content_positive quotient_bytes odd_empty_iff negative_zero)\nend Spec\nnamespace Norm\nexport SemiprimeD1StackKernelLinearNormalize (Clean result mag signed scanned zeroed prepared divided)\nend Norm\n/-- Physical nonzero testing is fixed by the actual stripped suffix, not supplied advice. -/\ntheorem nonzero_of_suffix (xs:List Bool) (h:Spec.odd xs≠[]):(nonzeroBits xs).nonzero=true:=by\n  apply (nonzeroBits_correct xs).mpr\n  have hn:bitValue xs≠0:=fun hz=>h ((Spec.odd_empty_iff xs).mpr hz)\n  omega\n/-- Physical all-zero testing sees every original padding bit. -/\ntheorem zero_of_suffix (xs:List Bool) (h:Spec.odd xs=[]):(nonzeroBits xs).nonzero=false:=by\n  have hz:bitValue xs=0:=(Spec.odd_empty_iff xs).mp h\n  cases hn:(nonzeroBits xs).nonzero with\n  | false=>rfl\n  | true=>have hp:=(nonzeroBits_correct xs).mp hn;omega\n/-- Literal original zero-normalization branch, including exact signed zero and ONE slope. -/\ntheorem native_zero (exponent:Nat) (j d:List Bool) (hz:Spec.odd (Spec.magnitude j d)=[]):\n    (Spec.factor exponent j d).content=(SemiprimeD1NormalizedLinearBits.alpha exponent).bits ∧\n    (Spec.factor exponent j d).constant=positive [] ∧ (Spec.factor exponent j d).slope=[true]:=by\n  have ht:=zero_of_suffix (Spec.magnitude j d) hz\n  dsimp only [Spec.factor,SemiprimeD1NormalizedLinearBits.acquire]\n  rw [Spec.difference_word]\n  simp only [ht,Bool.false_eq_true,ite_false,and_self]\n/-- Literal original nonzero branch retains the exact padded odd suffix and full quotient. -/\ntheorem native_nonzero (exponent:Nat) (j d:List Bool) (hn:Spec.odd (Spec.magnitude j d)≠[]):\n    (Spec.factor exponent j d).content=Spec.power (SemiprimeD1StackKernelLinearSpec.leading (Spec.magnitude j d)) ∧\n    (Spec.factor exponent j d).constant=⟨Spec.negative j d,Spec.odd (Spec.magnitude j d)⟩ ∧\n    (Spec.factor exponent j d).slope=\n      (divideLoop (SemiprimeD1NormalizedLinearBits.alpha exponent).bits\n        (Spec.power (SemiprimeD1StackKernelLinearSpec.leading (Spec.magnitude j d)))).quotient:=by\n  have ht:=nonzero_of_suffix (Spec.magnitude j d) hn\n  have hc:=Spec.content_positive (Spec.magnitude j d)\n  have hd:=Spec.quotient_bytes (SemiprimeD1NormalizedLinearBits.alpha exponent).bits\n    (SemiprimeD1RecoveryStripBits.acquire (Spec.magnitude j d)).content hc\n  dsimp only [Spec.factor,SemiprimeD1NormalizedLinearBits.acquire]\n  rw [Spec.difference_word]\n  simp only [ht,ite_true]\n  rw [hd,(Spec.strip_bytes (Spec.magnitude j d)).1,(Spec.strip_bytes (Spec.magnitude j d)).2]\n  exact ⟨rfl,rfl,rfl⟩\n/-- All four observed raw factor fields agree with the original acquire routine.\nThe only alpha premise describes the actual acquired binary shifted-one cache. -/\ntheorem factor_fields (w:Words) (hc:Norm.Clean w) (exponent:Nat)\n    (ha:w.alpha=(SemiprimeD1NormalizedLinearBits.alpha exponent).bits):\n    (Norm.result w).content=(Spec.factor exponent w.j w.displacement).content ∧\n    (Norm.result w).sign=[(Spec.factor exponent w.j w.displacement).constant.negative] ∧\n    (Norm.result w).constant=(Spec.factor exponent w.j w.displacement).constant.magnitude ∧\n    (Norm.result w).slope=(Spec.factor exponent w.j w.displacement).slope:=by\n  have hconstant:w.constant=[]:=hc .constant (by simp)\n  by_cases hz:Spec.odd (Norm.mag w)=[]\n  · have hf:=native_zero exponent w.j w.displacement hz\n    have hs:=Spec.negative_zero w.j w.displacement ((Spec.odd_empty_iff (Norm.mag w)).mp hz)\n    simp only [Norm.result,hz,ite_true]\n    rw [hf.1,hf.2.1,hf.2.2]\n    simp only [Norm.zeroed,Norm.scanned,Norm.signed,SemiprimeD1StackKernelLinearScan.result,\n      SemiprimeD1StackKernelLinearFinish.result,Norm.mag,hs,hconstant,positive,ha,and_self]\n  · have hf:=native_nonzero exponent w.j w.displacement hz\n    simp only [Norm.result,hz,ite_false]\n    rw [hf.1,hf.2.1,hf.2.2]\n    simp only [Norm.divided,Norm.prepared,Norm.scanned,Norm.signed,SemiprimeD1StackKernelLinearScan.result,\n      SemiprimeD1StackKernelLinearFinish.result,SemiprimeD1StackKernelLinearTail.quotient,Norm.mag,ha,and_self]\nend RiemannGaussian.SemiprimeD1StackKernelLinearMeaning\n","RiemannGaussian.SemiprimeD1StackLeaf":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexProductExecution\nimport RiemannGaussian.SemiprimeD1StackAssignmentEnumerationBounds\n/-! # Fixed physical original-header eager leaf contraction\nThe literal procedure acquires rank and precision, acquires the assignment width\nfrom its binary word, materializes its actual assignment catalogue, and parses\nthat catalogue. Every assignment executes the actual parsed vertex product and\nactual dense addition. No leaf, assignment, tensor entry or coefficient callback\noccurs in the executed instruction table.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 131072\nset_option maxRecDepth 131072\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeD1StackLeaf\nnamespace P\nexport SemiprimeD1StackVertexProduct (Stack Label program main contextStack axes rank width product aux)\nend P\nnamespace A\nexport SemiprimeD1StackJetAdd (Stack Label program Aux)\nend A\nnamespace E\nexport SemiprimeD1StackAssignmentLoop (Stack Label code control)\nend E\nnamespace U\nexport SemiprimeD1StackAdder (Stack)\nexport SemiprimeD1StackUnaryCounter (Label code)\nend U\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\n\n/-- Literal outer-loop data roles; each is an actual Boolean stack. -/\ninductive Aux where\n  | widthBits | catalogue | sum | sumResult | valid | fieldScratch | copyWork\n  deriving DecidableEq,Repr\ninstance : Fintype Aux := Fintype.ofList\n  [.widthBits,.catalogue,.sum,.sumResult,.valid,.fieldScratch,.copyWork]\n  (by intro k; cases k <;> simp)\n\n/-- Fixed component banks, independent of every numeric input. -/\nabbrev Stack := P.Stack ⊕ (A.Stack ⊕ (E.Stack ⊕ (U.Stack ⊕ Aux)))\n/-- Physical embedding of the whole literal product procedure. -/\ndef productStack : P.Stack→Stack := Sum.inl\n/-- Unaliased dense-sum work bank. -/\ndef addWork (k : A.Stack) : Stack := .inr (.inl k)\n/-- Unaliased assignment-enumeration work bank. -/\ndef enumerationWork (k : E.Stack) : Stack := .inr (.inr (.inl k))\n/-- Actual binary-to-unary assignment-width work bank. -/\ndef unaryStack (k : U.Stack) : Stack := .inr (.inr (.inr (.inl k)))\n/-- Literal caller storage. -/\ndef aux (k : Aux) : Stack := .inr (.inr (.inr (.inr k)))\n/-- Original encoded axes, retained by the actual context and product calls. -/\ndef axes : Stack := productStack P.axes\n/-- Original binary precision, retained by the actual context acquisition. -/\ndef precisionBits : Stack := productStack (P.aux .precisionBits)\n/-- Original literal vertex-record tape, retained by every product call. -/\ndef vertices : Stack := productStack (P.aux .verticesCache)\n/-- Current actual assignment field, cleared between catalogue records. -/\ndef assignment : Stack := productStack (P.aux .assignment)\n/-- Physical context acquisition shares the product's actual rank/precision caches. -/\ndef contextStack (k : SemiprimeD1StackJetContext.Stack) : Stack := productStack (P.contextStack k)\n/-- Actual dense-adder operands are the product and reached sum buffers. -/\ndef addStack (k : A.Stack) : Stack :=\n  if k=SemiprimeD1StackJetUnit.widthCache then productStack P.width\n  else if k=SemiprimeD1StackJetUnit.rankCache then productStack P.rank\n  else if k=.inr .leftTape then productStack P.product\n  else if k=.inr .rightTape then aux .sum\n  else if k=.inr .output then aux .sumResult else addWork k\n/-- The real enumeration output is the catalogue consumed by the outer loop. -/\ndef enumerationStack : E.Stack→Stack\n  | .output => aux .catalogue\n  | k => enumerationWork k\n/-- Real parser reads the acquired catalogue directly into the product assignment. -/\ndef fieldStack : F.Stack→Stack\n  | .inl .input => aux .catalogue\n  | .inl .scratch => aux .fieldScratch\n  | .inl .output => assignment\n  | .inr _ => aux .valid\n/-- Two literal physical copies: binary width to its acquisition procedure, and\nactual newly computed sum to the next reached accumulator. -/\ndef copyStack (sum : Bool) (k : Fin 3) : Stack :=\n  if k=0 then (if sum then aux .sumResult else aux .widthBits)\n  else if k=1 then (if sum then aux .sum else unaryStack .left)\n  else aux .copyWork\n\n/-- Finite caller labels and literal included procedures. -/\ninductive Label where\n  | start | widthCopy | widthUnary | makeZero | pushZero | initializeSum\n  | enumerate | catalogueTag | parse | parsed | callProduct | callAdd\n  | copySum | clearSumResult | clearAssignment | done | abort\n  | context (pc : SemiprimeD1StackJetContext.Label)\n  | unary (pc : U.Label)\n  | enumeration (pc : E.Label)\n  | product (pc : P.Label)\n  | add (pc : A.Label)\n  | field (pc : F.Label)\n  | copy (sum : Bool) (pc : Fin 9)\n  deriving DecidableEq,Fintype\n\n/-- Actual closed leaf program. Every variable-sized loop is driven by physical\ninput/counter/field bytes and actual included calls with real return frames. -/\ndef program : Label→SemiprimeD1StackCalls.Instruction Stack Label\n  | .start => .call (.context .start) .widthCopy\n  | .widthCopy => .call (.copy false 0) .widthUnary\n  | .widthUnary => .call (.unary .reverse) .makeZero\n  | .makeZero => .base (.pop (unaryStack .output) .initializeSum .pushZero .pushZero)\n  | .pushZero => .base (.push (enumerationWork .word) false .makeZero)\n  | .initializeSum => .base (.push (aux .sum) false .enumerate)\n  | .enumerate => .call (.enumeration (E.control .bodyCall)) .catalogueTag\n  | .catalogueTag => .base (.pop (aux .catalogue) .done .done .parse)\n  | .parse => .call (.field (F.active .tagPop (none,false))) .parsed\n  | .parsed => .base (.pop (aux .valid) .abort .abort .callProduct)\n  | .callProduct => .call (.product .prepared) .callAdd\n  | .callAdd => .call (.add .start) .copySum\n  | .copySum => .call (.copy true 0) .clearSumResult\n  | .clearSumResult => .base (.pop (aux .sumResult) .clearAssignment .clearSumResult .clearSumResult)\n  | .clearAssignment => .base (.pop assignment .catalogueTag .clearAssignment .clearAssignment)\n  | .done | .abort => .base .halt\n  | .context pc => SemiprimeD1StackValidationLink.instruction contextStack Label.context (SemiprimeD1StackJetContext.program pc)\n  | .unary pc => SemiprimeD1StackMultiplierLink.instruction unaryStack Label.unary (U.code pc)\n  | .enumeration pc => SemiprimeD1StackValidationLink.instruction enumerationStack Label.enumeration (E.code pc)\n  | .product pc => SemiprimeD1StackValidationLink.instruction productStack Label.product (P.program pc)\n  | .add pc => SemiprimeD1StackValidationLink.instruction addStack Label.add (A.program pc)\n  | .field pc => SemiprimeD1StackMultiplierLink.instruction fieldStack Label.field (F.code pc)\n  | .copy sum pc => SemiprimeD1StackMultiplierLink.instruction (copyStack sum) (Label.copy sum)\n      (SemiprimeD1StackCopy.code pc)\n\n/-- Original headers and literal records are the only initially live data. -/\ndef inputData (axisTape pBits widthBits vertexTape : List Bool) : Stack→List Bool :=\n  Function.update (Function.update (Function.update (Function.update (fun _=>[]) axes axisTape)\n    precisionBits pBits) (aux .widthBits) widthBits) vertices vertexTape\n/-- Closed physical start has no supplied assignment, rank, tensor entry or sum. -/\ndef initial (axisTape pBits widthBits vertexTape : List Bool) : SemiprimeD1StackCalls.State Stack Label :=\n  ⟨some .start,none,none,inputData axisTape pBits widthBits vertexTape,[]⟩\n/-- Fixed finite-stack leaf machine; its entire output is the canonical sum vector. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine vertices (aux .sum) Label.start program\n\n/-- Context components retain distinct actual registers. -/\ntheorem contextStack_injective : Function.Injective contextStack := by decide\n/-- Actual sum operands/cache/work registers are distinct. -/\ntheorem addStack_injective : Function.Injective addStack := by decide\n/-- Enumeration bank has no physical aliases. -/\ntheorem enumerationStack_injective : Function.Injective enumerationStack := by decide\n/-- Catalogue field parser has distinct input/work/output/flag registers. -/\ntheorem fieldStack_injective : Function.Injective fieldStack := by decide\n/-- Both copy inclusions have distinct source/target/work registers. -/\ntheorem copyStack_injective (sum : Bool) : Function.Injective (copyStack sum) := by cases sum <;> decide\n\nend RiemannGaussian.SemiprimeD1StackLeaf\n","RiemannGaussian.SemiprimeD1StackLeafRound":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackLeafMoves\n/-! # One actual assignment-product and dense-sum round -/\nset_option autoImplicit false\nset_option synthInstance.maxSize 131072\nset_option maxRecDepth 131072\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeD1StackLeafRound\nopen SemiprimeD1StackLeaf SemiprimeD1StackLeafState SemiprimeD1StackLeafMoves\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\n\n/-- Derived sum of the actual parser, product, adder, copy and cleanup costs. -/\ndef roundBudget (ctx : SemiprimeD1JetAxes.Context) (vertices : List SemiprimeD1LeafCounter.Vertex)\n    (p : PS.Values) (word : List Bool) (acc : List (List Bool)) : ℕ :=\n  let entry:=(SemiprimeD1TensorTapeLeaf.evaluateAssignment ctx vertices word).words\n  let out:=vectorBits (SemiprimeD1JetRingBits.add ctx entry acc).words\n  8*word.length+8+(SemiprimeD1StackVertexProductExecution.preparedBudget ctx vertices\n    (Function.update p .assignment word)+2)+\n  (SemiprimeD1StackJetAddExecution.totalTime (p .width) (p .rank) entry acc+1)+\n  (5*out.length+4)+(out.length+1)+(word.length+1)\n\n/-- One real assignment record is parsed, its literal vertex tables multiplied,\nand its result added to the actual reached sum. No semantic answer is an input. -/\ntheorem round_run (ctx : SemiprimeD1JetAxes.Context) (hp : ctx.Positive)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) (p : PS.Values) (v : Values)\n    (word tail : List Bool) (acc : List (List Bool))\n    (hcatalogue : v .catalogue=SemiprimeSourceHistogramKeyBits.frame word tail)\n    (hvertices : p .vertices=SemiprimeD1StackVertexProduct.records vertices)\n    (hreader : p .reader=[]) (hleft : p .left=[]) (hprod : p .product=[])\n    (hports : p .ports=[]) (htable : p .table=[]) (hvalid : p .valid=[]) (hout : p .result=[])\n    (hassignment : p .assignment=[]) (hflag : v .valid=[]) (hsum : v .sum=vectorBits acc)\n    (hsout : v .sumResult=[]) (haxes : p .axes=vectorBits (ctx.axes.map unary))\n    (hw : (p .width).length=ctx.precision) (hr : p .rank=unary ctx.rank) :\n    ∃ m ≤ roundBudget ctx vertices p word acc, Runs program m .parse (data p v) .catalogueTag\n      (data p (Function.update (Function.update v .catalogue tail) .sum\n        (vectorBits (SemiprimeD1JetRingBits.add ctx\n          (SemiprimeD1TensorTapeLeaf.evaluateAssignment ctx vertices word).words acc).words))) := by\n  let p1:=Function.update p .assignment word\n  let v1:=Function.update (Function.update v .catalogue tail) .valid [true]\n  let v2:=Function.update v1 .valid []\n  let entry:=(SemiprimeD1TensorTapeLeaf.evaluateAssignment ctx vertices word).words\n  let p2:=Function.update p1 .product (vectorBits entry)\n  let p3:=Function.update p2 .product []\n  let out:=vectorBits (SemiprimeD1JetRingBits.add ctx entry acc).words\n  let v3:=Function.update (Function.update v2 .sum []) .sumResult out\n  let v4:=Function.update v3 .sum out\n  let v5:=Function.update v4 .sumResult []\n  have h1:=field_call p v word tail hcatalogue hassignment hflag\n  have h2 : Runs program 1 .parsed (data p1 v1) .callProduct (data p1 v2) := by\n    simpa only [v1,v2,Function.update_idem] using field_flag p1 (Function.update v .catalogue tail)\n  obtain ⟨m3,hm3,h3⟩:=SemiprimeD1StackLeafProduct.product_call ctx hp vertices p1 v2\n    (by simpa [p1] using hvertices) (by simpa [p1] using hreader) (by simpa [p1] using hleft)\n    (by simpa [p1] using hprod) (by simpa [p1] using hports) (by simpa [p1] using htable)\n    (by simpa [p1] using hvalid) (by simpa [p1] using hout) (by simpa [p1] using haxes)\n    (by simpa [p1] using hw) (by simpa [p1] using hr)\n  have h3' : Runs program m3 .callProduct (data p1 v2) .callAdd (data p2 v2) := by\n    simpa [p2,entry,p1] using h3\n  have h4 : Runs program (SemiprimeD1StackJetAddExecution.totalTime (p .width) (p .rank) entry acc+1)\n      .callAdd (data p2 v2) .copySum (data p3 v3) := by\n    apply SemiprimeD1StackLeafAddition.add_call ctx p2 v2 entry acc (by simp [p2])\n      (by simpa [v2,v1] using hsum) (by simpa [v2,v1] using hsout)\n      (by simpa [p2,p1] using hw) (by simp [p2,p1,hr,unary])\n  have h5 : Runs program (5*out.length+4) .copySum (data p3 v3) .clearSumResult (data p3 v4) := by\n    simpa [v4,v3] using copy_sum p3 v3\n  have h6:=clear_sum p3 v4\n  have h7:=clear_assignment p3 v5\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ h1 h2\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h3'\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h4\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h5\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h6\n  have hc:=runs_trans program _ _ _ _ _ _ _ _ hc h7\n  refine ⟨8*word.length+7+1+m3+\n    (SemiprimeD1StackJetAddExecution.totalTime (p .width) (p .rank) entry acc+1)+\n    (5*out.length+4)+((v4 .sumResult).length+1)+((p3 .assignment).length+1),?_,?_⟩\n  · simp only [roundBudget]\n    simp only [v4,v3,p3,p2,p1,Function.update_of_ne (by decide : Slot.sumResult ≠ .sum),\n      Function.update_self,Function.update_of_ne (by decide : SemiprimeD1StackVertexProductState.Slot.assignment ≠ .product)]\n    dsimp only [p1] at hm3\n    dsimp only [entry,out]\n    omega\n  · convert hc using 1\n    have hp3 : Function.update p3 .assignment []=p := by\n      funext s\n      cases s <;> simp_all [p3,p2,p1]\n    rw [hp3]\n    apply congrArg (data p)\n    funext s\n    cases s <;> simp_all [v5,v4,v3,v2,v1,out,entry]\n\nend RiemannGaussian.SemiprimeD1StackLeafRound\n","RiemannGaussian.SemiprimeD1StackMarkedPublicInputCompact":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedPublicInputOriginal\nimport RiemannGaussian.SemiprimeD1StackReduceExecution\nimport RiemannGaussian.SemiprimeD1StackReverseWord\n/-! # Actual compact coefficient wrapper around the frozen marked input source\nAll66 physical roles are reused. Only after the real source halts is its empty\ntemplate shadow used for reverse/trim; it is empty again at the wrapper halt.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackMarkedPublicInputCompact\nnamespace M\nexport SemiprimeD1StackMarkedPublicInput (Stack Label program initial checker word aux)\nend M\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\n/-- The actual marked source's fixed66-role bank, with no extra allocation. -/\nabbrev Stack := M.Stack\n/-- Complete finite wrapper stages. -/\ninductive Control where | start | reverse | trim | done deriving DecidableEq, Repr\n/-- Literal complete stage inventory. -/\ninstance : Fintype Control := Fintype.ofList [.start,.reverse,.trim,.done] (by intro k;cases k <;> simp)\n/-- Actual source labels, finite reverse labels and finite trim labels. -/\nabbrev Label := Control ⊕ (M.Label ⊕ (Fin 4 ⊕ SemiprimeD1StackReduce.Label))\n/-- Fixed local stage. -/\ndef ctl : Control → Label := Sum.inl\n/-- Fixed source-label inclusion. -/\ndef sourceLabel : M.Label → Label := fun k => .inr (.inl k)\n/-- Fixed consuming-reverse inclusion. -/\ndef reverseLabel : Fin 4 → Label := fun k => .inr (.inr (.inl k))\n/-- Fixed high-zero-trim inclusion. -/\ndef trimLabel : SemiprimeD1StackReduce.Label → Label := fun k => .inr (.inr (.inr k))\n/-- Reversal borrows only an actually empty unused shadow after source completion. -/\ndef reverseStack (k : Fin 2) : Stack := if k=0 then M.aux .output else M.word 1\n/-- All four trim roles are distinct and actually empty except the reversed word. -/\ndef trimStack : SemiprimeD1StackAdder.Stack → Stack\n  | .left => M.word 0\n  | .right => M.word 3\n  | .scratch => M.word 1\n  | .output => M.aux .output\n/-- Parameterless literal source→paidreverse→paidtrim→halt. -/\ndef program : Label → C.Instruction Stack Label\n  | .inl .start => .call (sourceLabel (SemiprimeD1StackMarkedPublicInput.ctl .start)) (ctl .reverse)\n  | .inl .reverse => .call (reverseLabel 0) (ctl .trim)\n  | .inl .trim => .call (trimLabel .trim) (ctl .done)\n  | .inl .done => .base .halt\n  | .inr (.inl k) => SemiprimeD1StackValidationLink.instruction id sourceLabel (M.program k)\n  | .inr (.inr (.inl k)) => SemiprimeD1StackMultiplierLink.instruction reverseStack reverseLabel (SemiprimeD1StackReverseWord.code k)\n  | .inr (.inr (.inr k)) => SemiprimeD1StackMultiplierLink.instruction trimStack trimLabel (SemiprimeD1StackReduce.code k)\n/-- Exactly the same four original physical words as the immutable marked source. -/\ndef initial (bits raw indexWord : List Bool) (side : Bool) : C.State Stack Label :=\n  ⟨some (ctl .start),none,none,(M.initial bits raw indexWord [side]).data,[]⟩\n/-- Compact actual output specification; no word is supplied to runtime. -/\ndef coefficient (bits raw indexWord : List Bool) (side : Bool) : List Bool :=\n  SemiprimeD1StackReduceExecution.trimReverse\n    (SemiprimeD1StackMarkedPublicInputEncoding.coefficient bits raw indexWord side).reverse\n/-- The exact retained66-role bank changes only the actual coefficient output. -/\ndef result (bits raw indexWord : List Bool) (side : Bool) : Stack → List Bool :=\n  Function.update (SemiprimeD1StackMarkedPublicInputEncoding.result bits raw indexWord side)\n    (M.aux .output) (coefficient bits raw indexWord side)\n/-- Actual compact wrapper halt. -/\ndef done (bits raw indexWord : List Bool) (side : Bool) : C.State Stack Label :=\n  ⟨none,none,none,result bits raw indexWord side,[]⟩\n/-- Real reverse operands are distinct. -/\ntheorem reverse_injective : Function.Injective reverseStack := by decide\n/-- Real trim operands do not alias any two physical roles. -/\ntheorem trim_injective : Function.Injective trimStack := by decide\n/-- Genuine fixed finite bit machine. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine\n  (M.checker (.inl SemiprimeD1StackPublicInputWidth.original)) (M.aux .output) (ctl .start) program\n/-- Every original data role, including the temporarily borrowed shadow, is counted. -/\ntheorem stack_card : Fintype.card Stack=66 := SemiprimeD1StackMarkedPublicInput.stack_card\nend RiemannGaussian.SemiprimeD1StackMarkedPublicInputCompact\n\n","RiemannGaussian.SemiprimeD1StackMarkedPublicInputCompactBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedPublicInputCompactExecution\n/-! # Exact compact coefficients and the wrapper's own quadratic allowance -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackMarkedPublicInputCompactBounds\nopen SemiprimeD1StackMarkedPublicInputCompact SemiprimeD1StackMarkedPublicInputCompactExecution\nopen SemiprimeD1StackMarkedPublicInputCost (inputSize)\nopen SemiprimeBitArithmetic\n/-- Physically removing high zero padding never enlarges the actual word. -/\ntheorem trim_length (xs : List Bool) :\n    (SemiprimeD1StackReduceExecution.trimReverse xs).length ≤ xs.length := by\n  induction xs with\n  | nil => rfl\n  | cons b xs ih =>\n    cases b <;> simp only [SemiprimeD1StackReduceExecution.trimReverse,List.length_cons,List.length_reverse]\n    · omega\n    · rfl\n/-- Actual wrapper coefficient is compact, including zero as the empty word. -/\ntheorem coefficient_compact (bits raw indexWord : List Bool) (side : Bool) :\n    SemiprimeSourceCompactBits.Compact (coefficient bits raw indexWord side) :=\n  SemiprimeD1StackReduceExecution.trimReverse_compact _\n/-- The paid trim preserves the entire original NONNEGATIVE integer value. -/\ntheorem coefficient_value (bits raw indexWord : List Bool) (side : Bool) :\n    bitValue (coefficient bits raw indexWord side)=\n      bitValue (SemiprimeD1StackMarkedPublicInputEncoding.coefficient bits raw indexWord side) := by\n  rw [coefficient,SemiprimeD1StackReduceExecution.trimReverse_value,List.reverse_reverse]\n/-- Compact words fit the actually acquired root precision without any lost integer information. -/\ntheorem coefficient_length (bits raw indexWord : List Bool) (side : Bool) :\n    (coefficient bits raw indexWord side).length ≤ 2*bits.length := by\n  have h := trim_length (SemiprimeD1StackMarkedPublicInputEncoding.coefficient bits raw indexWord side).reverse\n  simpa only [coefficient,List.length_reverse,SemiprimeD1StackMarkedPublicInputMetadata.coefficient_length] using h\n/-- Own fixed wrapper allowance, including real66 source, reverse, trim and all returns. -/\ndef polynomial (bits raw indexWord : List Bool) : Nat :=\n  10000000000000000*(inputSize bits raw indexWord)^2\n/-- This wrapper's whole bound is derived from actual executed component caps. -/\ntheorem runBound_le (bits raw indexWord : List Bool) (side : Bool) :\n    runBound bits raw indexWord side ≤ polynomial bits raw indexWord := by\n  have ht := SemiprimeD1StackReduceExecution.trimTime_le\n    (SemiprimeD1StackMarkedPublicInputEncoding.coefficient bits raw indexWord side).reverse\n  rw [List.length_reverse,SemiprimeD1StackMarkedPublicInputMetadata.coefficient_length] at ht\n  have hs : 2 ≤ inputSize bits raw indexWord := by unfold inputSize;omega\n  have he : bits.length ≤ inputSize bits raw indexWord := by unfold inputSize;omega\n  unfold runBound polynomial SemiprimeD1StackMarkedPublicInputCost.polynomial\n  rw [SemiprimeD1StackMarkedPublicInputMetadata.coefficient_length]\n  nlinarith\n/-- Actual compact word-source trace, with no decoded coefficient or clock supplier. -/\ntheorem source_run_bounded (bits raw indexWord : List Bool) (side : Bool) (hb : bits≠[]) :\n    ∃ t ≤ polynomial bits raw indexWord,\n      C.run program t (initial bits raw indexWord side)=some (done bits raw indexWord side) := by\n  obtain ⟨t,ht,hr⟩ := source_run bits raw indexWord side hb\n  exact ⟨t,ht.trans (runBound_le bits raw indexWord side),hr⟩\nend RiemannGaussian.SemiprimeD1StackMarkedPublicInputCompactBounds\n\n","RiemannGaussian.SemiprimeD1StackMarkedRootRecordsLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecordsRows\n/-! # Complete real paired-record sweep, including the two distinct physical EOFs -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackMarkedRootRecordsLoop\nopen SemiprimeD1StackMarkedRootRecords SemiprimeD1StackMarkedRootRecordsView\nopen SemiprimeD1StackMarkedRootRecordsRowView SemiprimeD1StackMarkedRootRecordsEncoding\nopen SemiprimeD1StackMarkedRootRecordsRows SemiprimeD1StackMarkedRootRecordsFields\nopen SemiprimeD1StackMarkedRootRecordsPrimitives SemiprimeD1StackProcedureTrace\n/-- One actual FALSE pop, then real record EOF and independent EMPTY descriptor EOF checks. -/\ntheorem end_run (r : R.Stack → List Bool) (v : V.Stack → List Bool) (bits hist out : List Bool) :\n    Runs program 3 (ctl .rowTag) (view r v bits {} {records := [false],history := hist,output := out})\n      (ctl .reverseFactors) (view r v bits {} {history := hist,output := out}) := by\n  have h0 := record_end (view r v bits {} {records := [false],history := hist,output := out}) rfl\n  rw [set_records] at h0\n  have h1 : Runs program 1 (ctl .recordEOF) (view r v bits {} {history := hist,output := out})\n      (ctl .descriptorEOF) (view r v bits {} {history := hist,output := out}) := by\n    apply one_base program _ _ (.peek (aux .recordReader) (ctl .descriptorEOF) (ctl .abort) (ctl .abort)) _ _ rfl\n    · rfl\n    · rfl\n  have h2 : Runs program 1 (ctl .descriptorEOF) (view r v bits {} {history := hist,output := out})\n      (ctl .reverseFactors) (view r v bits {} {history := hist,output := out}) := by\n    apply one_base program _ _ (.peek (aux .descriptorReader) (ctl .reverseFactors) (ctl .abort) (ctl .abort)) _ _ rfl\n    · rfl\n    · rfl\n  exact join (join h0 h1) h2\n/-- Fixed sum of the SAME program's real row caps plus physical completion checks. -/\ndef loopBudget (bits : List Bool) (rows : List Row) : Nat := (rows.map (rowBudget bits)).sum+3\n/-- All original paired rows are consumed in forward order, preserving both actual source banks. -/\ntheorem loop_run (r : R.Stack → List Bool) (v : V.Stack → List Bool) (bits : List Bool)\n    (rows : List Row) (hist out : List Bool) (hn : r R.originalInput=bits) (hb : bits≠[]) :\n    ∃ t ≤ loopBudget bits rows, Runs program t (ctl .rowTag)\n      (view r v bits {} {records := oldRecords rows,descriptors := descriptors rows,history := hist,output := out})\n      (ctl .reverseFactors) (view r v bits {} {history := (payload bits rows).reverse++hist,output := out}) := by\n  induction rows generalizing hist with\n  | nil =>\n    refine ⟨3,by simp only [loopBudget,List.map_nil,List.sum_nil];omega,?_⟩\n    exact end_run r v bits hist out\n  | cons row rows ih =>\n    obtain ⟨a,ha,h0⟩ := row_run r v bits row (oldRecords rows) (descriptors rows) hist out hn hb\n    obtain ⟨b,hb0,h1⟩ := ih ((newRow bits row).reverse++hist)\n    refine ⟨a+b,?_,?_⟩\n    · simp only [loopBudget,List.map_cons,List.sum_cons] at hb0 ⊢\n      omega\n    · simpa only [oldRecords,descriptors,payload,List.foldr_cons,List.reverse_append,List.append_assoc]\n        using join h0 h1\nend RiemannGaussian.SemiprimeD1StackMarkedRootRecordsLoop\n","RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexExecution\n/-! # Uniform quadratic physical owner-index acquisition and all-prefix storage\nThe record tape and acquired unary count pay for all seventeen physical words,\nevery parsed tensor byte, the emitted index and every real return cell. The\nnative bound is attached to this actual complete fixed source, not another\nsemantic implementation or an uncharged graph/owner oracle.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexBounds\nopen SemiprimeD1StackNetworkOwnerIndex SemiprimeD1StackNetworkOwnerIndexLoop\nopen SemiprimeD1StackNetworkOwnerIndexExecution SemiprimeD1StackNetworkOwnerIndexFinish\nopen SemiprimeD1StackCalls (run configuration)\nlocal notation \"ctl\" => Label.local\n/-- Actual total record/count input bytes plus one; the count is paid in its actual unary representation. -/\ndef inputSize (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :Nat :=\n  (inputTape owners suffix).length+owners.length+1\n/-- Fixed whole-source quadratic clock before all physical original/current network inputs. -/\ndef polynomial (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :Nat :=10000*(inputSize owners suffix)^2\n/-- Owner record bytes form a prefix of the actual physically supplied record tape. -/\ntheorem vertex_prefix_le (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :\n    (vertexPrefix owners).length ≤(inputTape owners suffix).length :=by\n  simp only [inputTape,List.length_append]\n  omega\n/-- Actual per-record primitive allowances sum to a fixed quadratic whole input-byte clock. -/\ntheorem timeBound_le (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :\n    timeBound owners suffix ≤polynomial owners suffix :=by\n  have hs: (owners.map (rowBudget owners.length)).sum ≤\n      1000*(owners.length+2)*(inputTape owners suffix).length:=\n    (sumBudget_le owners.length owners).trans\n      (Nat.mul_le_mul_left (1000*(owners.length+2)) (vertex_prefix_le owners suffix))\n  unfold timeBound prefixBudget polynomial inputSize\n  nlinarith only [hs,Nat.zero_le ((inputTape owners suffix).length^2),Nat.zero_le (owners.length^2),\n    Nat.zero_le (owners.length*(inputTape owners suffix).length)]\n/-- Same actual complete source executes within its fixed quadratic physical-input cap. -/\ntheorem source_run_bounded (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :\n    ∃q ≤polynomial owners suffix,run program q (source owners suffix)=some (done owners suffix) :=by\n  obtain ⟨q,hq,hr⟩:=source_run owners suffix\n  exact ⟨q,hq.trans (timeBound_le owners suffix),hr⟩\n/-- Every actually initialized source word is paid by the actual two supplied tape lengths. -/\ntheorem source_initial_bound (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) (k:Stack) :\n    ((source owners suffix).data k).length ≤ inputSize owners suffix :=by\n  have h:=initial_length (inputTape owners suffix) (List.replicate owners.length true) k\n  simp only [List.length_replicate] at h\n  unfold inputSize\n  exact h.trans (Nat.le_succ _)\n/-- A successful actual source prefix cannot pass this same fixed program's genuine final halt. -/\ntheorem prefix_fuel (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool)\n    (fuel:Nat) (out:C.State Stack Label) (hr:run program fuel (source owners suffix)=some out) :\n    fuel ≤polynomial owners suffix :=by\n  obtain ⟨q,hq,he⟩:=source_run_bounded owners suffix\n  have hh:run program 1 (done owners suffix)=none:=rfl\n  have hf:fuel ≤q:=by\n    by_contra hn\n    have h:fuel=q+(1+(fuel-(q+1))):=by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add,hh,Option.bind_none] at hr\n    cases hr\n  exact hf.trans hq\n/-- Abstract finite-bank sum avoids evaluating any current network or encoded record during elaboration. -/\ntheorem word_sum_le {K:Type} [Fintype K] (words:K→List Bool) (B:Nat)\n    (h:∀k,(words k).length ≤B) :(∑k:K,(words k).length) ≤Fintype.card K*B :=by\n  calc\n    _ ≤∑_k:K,B:=Finset.sum_le_sum (fun k _=>h k)\n    _= _:=by simp only [Finset.sum_const,Finset.card_univ,smul_eq_mul]\n/-- Every reached actual prefix counts all seventeen data words and every real return-frame cell. -/\ntheorem prefix_cells (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool)\n    (fuel:Nat) (out:C.State Stack Label) (hr:run program fuel (source owners suffix)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤200000*(inputSize owners suffix)^2 :=by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (inputSize owners suffix)\n    (source owners suffix) out (source_initial_bound owners suffix) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel (source owners suffix) out hr\n  change out.frames.length ≤0+fuel at hf\n  have hs:=word_sum_le out.data (inputSize owners suffix+fuel) hd\n  rw [stack_card] at hs\n  have ht:=prefix_fuel owners suffix fuel out hr\n  unfold polynomial at ht\n  have hp:inputSize owners suffix ≤(inputSize owners suffix)^2:=Nat.le_pow (by decide:0<(2:Nat))\n  omega\n/-- Genuine prepared finite-machine source certificate charges the same whole quadratic physical clock. -/\nnoncomputable def machineBounded (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :\n    StateTransition.EvalsToInTime machine.step (configuration (source owners suffix))\n      (some (configuration (done owners suffix))) (polynomial owners suffix) :=by\n  apply SemiprimeD1StackCalls.evalsCorrect Stack.vertices Stack.output (ctl .start) program\n  let h:=source_run_bounded owners suffix\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Complete compiled prefix storage includes all seventeen actual role tapes and fixed-alphabet return symbols. -/\ntheorem machine_prefix_cells (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (configuration (source owners suffix)))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤200000*(inputSize owners suffix)^2 :=by\n  have he:=SemiprimeD1StackCalls.run_correct Stack.vertices Stack.output (ctl .start) program fuel (source owners suffix)\n  have hh:=he.trans hr\n  cases hout:run program fuel (source owners suffix) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells owners suffix fuel out hout\n/-- Each actual source transition expands to at most four fundamental fixed-machine commands. -/\ntheorem compile_depth (pc:Label) :SemiprimeD1StackBytecode.statementDepth (machine.m pc) ≤4 :=\n  SemiprimeD1StackCalls.compile_depth (ctl .start) (program pc)\nend RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexBounds\n","RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexLoop\nimport RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexFinish\n/-! # Whole physical record-to-owner-index acquisition with its own charged clock\nThe final-history length is bounded by the SAME executed source prefix. Every\nrecord copy, count traversal, ports/table parse, table cleanup, pair write,\nbinary counter update, final reverse and actual halt is included.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexExecution\nopen SemiprimeD1StackNetworkOwnerIndex SemiprimeD1StackNetworkOwnerIndexPrimitives\nopen SemiprimeD1StackNetworkOwnerIndexSetup SemiprimeD1StackNetworkOwnerIndexEncoding\nopen SemiprimeD1StackNetworkOwnerIndexLoop SemiprimeD1StackNetworkOwnerIndexFinish\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- Physical initial record tape: owner records followed by the unconsumed actual factor suffix. -/\ndef inputTape (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :List Bool :=vertexPrefix owners++suffix\n/-- Exact original chronological pair list; it is specification data, never a runtime getter. -/\ndef pairs (owners:List SemiprimeD1LeafCounter.Vertex) :List (List Bool×List Bool) :=ownerPairs owners.length 0 owners\n/-- Exact actual source input has only the record tape and physically acquired unary owner count. -/\ndef source (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :C.State Stack Label :=\n  initial (inputTape owners suffix) (List.replicate owners.length true)\n/-- Actual reverse history produced by this source's paid pair writes. -/\ndef history (owners:List SemiprimeD1LeafCounter.Vertex) :List Bool :=(payload (pairs owners)).reverse\n/-- All actual work is clear when the owner loop reaches the final reversal phase. -/\ndef preData (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :Stack→List Bool :=\n  view (inputTape owners suffix) (List.replicate owners.length true) suffix [] []\n    (ownerWord owners.length owners.length) (history owners)\n/-- Exact physical final source store; original tapes and the entire factor suffix remain. -/\ndef result (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :Stack→List Bool :=\n  Function.update (view (inputTape owners suffix) (List.replicate owners.length true) suffix [] []\n    (ownerWord owners.length owners.length) []) .output (payload (pairs owners)++[false])\n/-- Genuine clean halt after the actual two-input source and sole final reversal. -/\ndef done (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :C.State Stack Label :=\n  ⟨none,none,none,result owners suffix,[]⟩\n/-- Own prefix cap sums actual setup and per-record primitive execution caps only. -/\ndef prefixBudget (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :Nat :=\n  5*(inputTape owners suffix).length+12*owners.length+14+(owners.map (rowBudget owners.length)).sum+1\n/-- Whole actual clock pays its prefix plus its own trace-derived history reverse and halt. -/\ndef timeBound (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :Nat :=\n  3*prefixBudget owners suffix+2*((inputTape owners suffix).length+owners.length)+7\n/-- Entire actual setup/owner loop, with no output-size advice or native graph callback. -/\ntheorem pre_trace (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :\n    ∃q ≤ prefixBudget owners suffix,Runs program q (ctl .start) (source owners suffix).data\n      (ctl .finish) (preData owners suffix) :=by\n  have h0:=setup_trace (inputTape owners suffix) owners.length\n  rw [←ownerWord_zero owners.length] at h0\n  obtain ⟨q,hq,h1⟩:=owners_loop (inputTape owners suffix) (List.replicate owners.length true) suffix []\n    owners.length 0 owners (by omega)\n  simp only [Nat.zero_add,List.append_nil] at h1\n  refine ⟨(5*(inputTape owners suffix).length+12*owners.length+14)+q,?_,?_⟩\n  · unfold prefixBudget\n    omega\n  · exact join h0 h1\n/-- Whole same-program trace has paid for every output byte before its final real halt. -/\ntheorem source_trace (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :\n    ∃q,q+1 ≤ timeBound owners suffix ∧ Runs program q (ctl .start) (source owners suffix).data\n      (ctl .done) (result owners suffix) :=by\n  obtain ⟨q,hq,hpre⟩:=pre_trace owners suffix\n  obtain ⟨temp,ht,hAt⟩:=hpre [] (source owners suffix) ⟨rfl,rfl,rfl⟩\n  have hh:=history_length (inputTape owners suffix) (List.replicate owners.length true) q temp ht\n  rw [hAt.2.1] at hh\n  change (history owners).length ≤(inputTape owners suffix).length+(List.replicate owners.length true).length+q at hh\n  simp only [List.length_replicate] at hh\n  have hf:=finish_trace (preData owners suffix) (history owners) rfl rfl\n  have he:Function.update (Function.update (preData owners suffix) .history []) .output\n      ((history owners).reverse++[false])=result owners suffix :=by\n    unfold preData result\n    rw [view_history]\n    simp only [history,List.reverse_reverse]\n  rw [he] at hf\n  refine ⟨q+(2*(history owners).length+6),?_,join hpre hf⟩\n  unfold timeBound\n  omega\n/-- Complete real source starts with physical record/count words ONLY and executes its actual final halt. -/\ntheorem source_run (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :\n    ∃q ≤ timeBound owners suffix,SemiprimeD1StackCalls.run program q (source owners suffix)=some (done owners suffix) :=by\n  obtain ⟨q,hq,hr⟩:=source_trace owners suffix\n  obtain ⟨finish,hf,hAt⟩:=hr [] (source owners suffix) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl (result owners suffix) [] finish hAt\n  exact ⟨q+1,hq,by rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some];exact hh⟩\n/-- Exact old generic lookup/fibre catalogue bytes, including the single false terminal. -/\ntheorem output_records (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :\n    (done owners suffix).data .output=SemiprimeD1StackOwnerLookup.records (pairs owners) [] :=by\n  change payload (pairs owners)++[false]=_\n  exact (records_payload (pairs owners) []).symm\n/-- Every original complete record bit survives acquisition literally. -/\ntheorem original_retained (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :\n    (done owners suffix).data .vertices=inputTape owners suffix :=by\n  change result owners suffix Stack.vertices=_\n  unfold result\n  rw [Function.update_of_ne (by decide:Stack.vertices≠.output)]\n  rfl\n/-- The acquired unary count survives, including isolated owners that emitted no port pairs. -/\ntheorem count_retained (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :\n    (done owners suffix).data .leftCount=List.replicate owners.length true :=by\n  change result owners suffix Stack.leftCount=_\n  unfold result\n  rw [Function.update_of_ne (by decide:Stack.leftCount≠.output)]\n  rfl\n/-- The factor-record suffix is still physically available for the next actual graph-row acquisition stage. -/\ntheorem suffix_retained (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :\n    (done owners suffix).data .reader=suffix :=by\n  change result owners suffix Stack.reader=_\n  unfold result\n  rw [Function.update_of_ne (by decide:Stack.reader≠.output)]\n  rfl\n/-- Genuine fixed finite-machine source certificate, charging this SAME literal program's own total clock. -/\nnoncomputable def ownerIndexInTime (owners:List SemiprimeD1LeafCounter.Vertex) (suffix:List Bool) :\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (source owners suffix))\n      (some (SemiprimeD1StackCalls.configuration (done owners suffix))) (timeBound owners suffix) :=by\n  apply SemiprimeD1StackCalls.evalsCorrect Stack.vertices Stack.output (ctl .start) program\n  let h:=source_run owners suffix\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexExecution\n","RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexRows\nimport RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexFinish\nimport RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexPorts\n/-! # Complete actual left-owner loop with physical factor-suffix retention\nEach vertex consumes one actual todo marker, physically parses/drains both full\nrecord fields, emits all occurrence pairs, and physically increments/transfers\nits binary owner counter. The native sum below sums ONLY actual primitive caps.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexLoop\nopen SemiprimeD1StackNetworkOwnerIndex SemiprimeD1StackNetworkOwnerIndexPrimitives\nopen SemiprimeD1StackNetworkOwnerIndexSetup SemiprimeD1StackNetworkOwnerIndexOperations\nopen SemiprimeD1StackNetworkOwnerIndexEncoding SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\" => Label.local\n/-- Exact original vertex-record bytes before its unconsumed following records. -/\ndef vertexBytes (v:SemiprimeD1LeafCounter.Vertex) :List Bool :=\n  true::frame (SemiprimeD1StackVertexReadExecution.portTape v.ports)\n    (frame (SemiprimeD1TensorTapeCodec.tape v.table) [])\n/-- Complete remaining left-record prefix, with no false vector terminator inserted before factors. -/\ndef vertexPrefix (vertices:List SemiprimeD1LeafCounter.Vertex) :List Bool :=\n  vertices.foldr (fun v tail=>vertexBytes v++tail) []\n/-- Both actual record fields preserve the literal following factor/vertex bytes. -/\ntheorem vertexBytes_append (v:SemiprimeD1LeafCounter.Vertex) (tail:List Bool) :\n    vertexBytes v++tail=true::frame (SemiprimeD1StackVertexReadExecution.portTape v.ports)\n      (frame (SemiprimeD1TensorTapeCodec.tape v.table) tail) :=by\n  unfold vertexBytes\n  rw [List.cons_append,SemiprimeD1TensorTapeCodec.frame_append,SemiprimeD1TensorTapeCodec.frame_append,List.nil_append]\n/-- Actual two-field byte inventory, including every literal constructor and delimiter. -/\ntheorem vertexBytes_length (v:SemiprimeD1LeafCounter.Vertex) :\n    (vertexBytes v).length=2*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length+\n      2*(SemiprimeD1TensorTapeCodec.tape v.table).length+3 :=by\n  simp only [vertexBytes,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n  omega\n/-- Literal actual source-record split retains the complete factor-record suffix, including its terminator. -/\ntheorem records_split (left right:List SemiprimeD1LeafCounter.Vertex) :\n    SemiprimeD1StackVertexProduct.records (left++right)=vertexPrefix left++SemiprimeD1StackVertexProduct.records right :=by\n  induction left with\n  | nil=>rfl\n  | cons v left ih=>\n    change true::frame (SemiprimeD1StackVertexReadExecution.portTape v.ports)\n      (frame (SemiprimeD1TensorTapeCodec.tape v.table) (SemiprimeD1StackVertexProduct.records (left++right)))=\n      (vertexBytes v++vertexPrefix left)++SemiprimeD1StackVertexProduct.records right\n    rw [List.append_assoc,vertexBytes_append,ih]\n/-- Conservative actual row cap: todo pop +paid fields/table drain +paid port loop +real binary increment/transfer. -/\ndef rowBudget (n:Nat) (v:SemiprimeD1LeafCounter.Vertex) :Nat :=\n  100*(n+2)*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length+\n  8*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length+\n  9*(SemiprimeD1TensorTapeCodec.tape v.table).length+14*(n+1)+42\n/-- Actual binary increment changes only the owner's physical word at a clean boundary. -/\ntheorem increment_view (vertices count reader todo ports hist:List Bool) (n start:Nat) (hs:start<n) :\n    ∃q≤ 14*(n+1)+23,Runs program q (ctl .increment)\n      (view vertices count reader todo ports (ownerWord n start) hist) (ctl .owners)\n      (view vertices count reader todo ports (ownerWord n (start+1)) hist) :=by\n  obtain ⟨q,hq,hr⟩:=increment_transfer (view vertices count reader todo ports (ownerWord n start) hist)\n    n start hs rfl rfl rfl\n  rw [view_owner] at hr\n  exact ⟨q,hq,hr⟩\n/-- One actual left vertex executes all record/port/table/counter work and retains its raw following suffix. -/\ntheorem owner_step (vertices count suffix todo hist:List Bool) (n start:Nat) (v:SemiprimeD1LeafCounter.Vertex)\n    (hs:start<n) :\n    ∃q≤ rowBudget n v,Runs program q (ctl .owners)\n      (view vertices count (vertexBytes v++suffix) (true::todo) [] (ownerWord n start) hist) (ctl .owners)\n      (view vertices count suffix todo [] (ownerWord n (start+1))\n        ((payload (portPairs n start v.ports)).reverse++hist)) :=by\n  have h0:=pop_run .owners (ctl .finish) (ctl .abort) (ctl .vertexTag) .todo\n    (view vertices count (vertexBytes v++suffix) (true::todo) [] (ownerWord n start) hist) (true::todo) rfl rfl\n  change Runs program 1 (ctl .owners) _ (ctl .vertexTag)\n    (Function.update (view vertices count (vertexBytes v++suffix) (true::todo) [] (ownerWord n start) hist) .todo todo) at h0\n  rw [view_todo] at h0\n  have h1:=SemiprimeD1StackNetworkOwnerIndexRows.vertex_fields vertices count todo (ownerWord n start) hist\n    (SemiprimeD1StackVertexReadExecution.portTape v.ports) (SemiprimeD1TensorTapeCodec.tape v.table) suffix\n  rw [←vertexBytes_append] at h1\n  have h2:=SemiprimeD1StackNetworkOwnerIndexPorts.ports_run vertices count suffix todo (ownerWord n start) hist\n    (v.ports.map SemiprimeD1StackUnaryDivmod.unary)\n  rw [SemiprimeD1StackNetworkOwnerIndexPorts.rows_unary] at h2\n  obtain ⟨b,hb,h3⟩:=increment_view vertices count suffix todo []\n    ((payload (portPairs n start v.ports)).reverse++hist) n start hs\n  have hh:=join (join (join h0 h1) h2) h3\n  have hp:=SemiprimeD1StackNetworkOwnerIndexPorts.portClock_le (ownerWord n start)\n    (v.ports.map SemiprimeD1StackUnaryDivmod.unary)\n  rw [ownerWord_length n start (by omega)] at hp\n  change SemiprimeD1StackNetworkOwnerIndexPorts.portClock (ownerWord n start) (v.ports.map SemiprimeD1StackUnaryDivmod.unary)≤\n    100*((n+1)+1)*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length at hp\n  refine ⟨1+(8*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length+\n    9*(SemiprimeD1TensorTapeCodec.tape v.table).length+18)+\n    SemiprimeD1StackNetworkOwnerIndexPorts.portClock (ownerWord n start) (v.ports.map SemiprimeD1StackUnaryDivmod.unary)+b,?_,hh⟩\n  have hsimpl:(n+1)+1=n+2:=by omega\n  rw [hsimpl] at hp\n  unfold rowBudget\n  omega\n/-- One real emptytodo pop ends ONLYthe owner prefix, leaving every following factor byte untouched. -/\ntheorem owners_end (vertices count suffix owner hist:List Bool) :\n    Runs program 1 (ctl .owners) (view vertices count suffix [] [] owner hist) (ctl .finish)\n      (view vertices count suffix [] [] owner hist) :=by\n  have h:=pop_run .owners (ctl .finish) (ctl .abort) (ctl .vertexTag) .todo\n    (view vertices count suffix [] [] owner hist) [] rfl rfl\n  rw [view_todo] at h\n  exact h\n/-- Whole actual left-owner loop; native cost is ONLYthe sum of ACTUALrow primitive caps plus emptytodo. -/\ntheorem owners_loop (vertices count suffix hist:List Bool) (n start:Nat)\n    (left:List SemiprimeD1LeafCounter.Vertex) (hn:start+left.length≤ n) :\n    ∃q≤(left.map (rowBudget n)).sum+1,Runs program q (ctl .owners)\n      (view vertices count (vertexPrefix left++suffix) (List.replicate left.length true) [] (ownerWord n start) hist)\n      (ctl .finish)\n      (view vertices count suffix [] [] (ownerWord n (start+left.length))\n        ((payload (ownerPairs n start left)).reverse++hist)) :=by\n  induction left generalizing start hist with\n  | nil=>\n    refine ⟨1,by simp,?_⟩\n    exact owners_end vertices count suffix (ownerWord n start) hist\n  | cons v left ih=>\n    have hs:start<n:=by simp only [List.length_cons] at hn;omega\n    obtain ⟨b,hb,h0⟩:=owner_step vertices count (vertexPrefix left++suffix) (List.replicate left.length true) hist n start v hs\n    obtain ⟨c,hc,h1⟩:=ih ((payload (portPairs n start v.ports)).reverse++hist) (start+1) (by\n      simp only [List.length_cons] at hn\n      omega)\n    have hh:=join h0 h1\n    refine ⟨b+c,?_,?_⟩\n    · simp only [List.map_cons,List.sum_cons]\n      omega\n    · have he:start+1+left.length=start+(left.length+1):=by omega\n      simpa only [vertexPrefix,List.foldr_cons,List.append_assoc,List.length_cons,List.replicate_succ,\n        ownerPairs,payload_append,List.reverse_append,he] using hh\n/-- Actual row caps are paid by the actual physical vertex bytes and acquired counter width. -/\ntheorem rowBudget_le (n:Nat) (v:SemiprimeD1LeafCounter.Vertex) :\n    rowBudget n v≤ 1000*(n+2)*(vertexBytes v).length :=by\n  rw [vertexBytes_length]\n  unfold rowBudget\n  nlinarith [Nat.zero_le (n*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length),\n    Nat.zero_le (n*(SemiprimeD1TensorTapeCodec.tape v.table).length)]\n/-- Sum of ACTUALrow primitive caps is linear in actual prefix bytes at fixed acquired counter width. -/\ntheorem sumBudget_le (n:Nat) (left:List SemiprimeD1LeafCounter.Vertex) :\n    (left.map (rowBudget n)).sum≤ 1000*(n+2)*(vertexPrefix left).length :=by\n  induction left with\n  | nil=>simp only [List.map_nil,List.sum_nil,vertexPrefix,List.foldr_nil,List.length_nil,Nat.mul_zero,Nat.le_refl]\n  | cons v left ih=>\n    have hv:=rowBudget_le n v\n    change rowBudget n v+(left.map (rowBudget n)).sum≤ 1000*(n+2)*(vertexBytes v++vertexPrefix left).length\n    rw [List.length_append,Nat.mul_add]\n    exact Nat.add_le_add hv ih\nend RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexLoop\n","RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexBounds\n/-! # Original network records supply their exact actual owner-index catalogue\nThe only runtime inputs are the literal complete vertex records and the actual\nunary left count. Exact singleton owner lookup is derived for EVERY original\nwell-formed network and occurrence. No owner/arity function is an operand.\nThe remaining right-row/packing consumer must physically parse the retained\nfactor suffix and use this actual catalogue; full factoring remains open.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexOriginal\nopen SemiprimeD1StackNetworkOwnerIndex SemiprimeD1StackNetworkOwnerIndexEncoding\nopen SemiprimeD1StackNetworkOwnerIndexExecution SemiprimeD1StackNetworkOwnerIndexBounds\nnamespace Net\nexport SemiprimeD1TensorNetwork (Network WellFormed vertices scope)\nexport SemiprimeD1TensorNetworkLayout (leftGroup)\nend Net\nnamespace R\nexport SemiprimeD1StackVertexProduct (records)\nend R\n/-- Literal physical input is the old complete original cached network tape, owners before factors. -/\ntheorem input_original (net:Net.Network) :\n    inputTape net.left.toList (R.records net.right.toList)=R.records (Net.vertices net) :=\n  (SemiprimeD1StackNetworkOwnerIndexLoop.records_split net.left.toList net.right.toList).symm\n/-- Exact same two-input entry, with the bounded original left count and no derived graph/lookup answer. -/\ntheorem initial_original (net:Net.Network) :\n    source net.left.toList (R.records net.right.toList)=\n      initial (R.records (Net.vertices net)) (List.replicate net.leftCount true) :=by\n  unfold source\n  rw [input_original,Vector.length_toList]\n/-- Actual catalogue retains the exact original left-vertex and local-port order for the whole network. -/\ntheorem output_original (net:Net.Network) :\n    (done net.left.toList (R.records net.right.toList)).data .output=\n      SemiprimeD1StackOwnerLookup.records (ownerPairs net.leftCount 0 net.left.toList) [] :=by\n  rw [output_records]\n  simp only [pairs,Vector.length_toList]\n/-- The exact physically acquired catalogue has ONE matching original owner at every original occurrence. -/\ntheorem original_owner_fibre (net:Net.Network) (hw:Net.WellFormed net) (p:Fin (Net.scope net.rows)) :\n    SemiprimeD1StackOwnerFibre.values (SemiprimeD1StackUnaryDivmod.unary p.val)\n      (pairs net.left.toList)=[ownerWord net.leftCount (Net.leftGroup net.rows p).val] :=by\n  simpa only [pairs,Vector.length_toList] using original_fibre net hw p\n/-- Exact first-match owner readout also follows from the same original acquired catalogue. -/\ntheorem original_owner_lookup (net:Net.Network) (hw:Net.WellFormed net) (p:Fin (Net.scope net.rows)) :\n    (SemiprimeD1StackOwnerLookup.result (SemiprimeD1StackUnaryDivmod.unary p.val)\n      (pairs net.left.toList) []).1=ownerWord net.leftCount (Net.leftGroup net.rows p).val :=by\n  simpa only [pairs,Vector.length_toList] using original_lookup net hw p []\n/-- One uniform actual source bound before ALL original network record tapes and left counts. -/\ntheorem source_original (net:Net.Network) :\n    ∃q ≤10000*((R.records (Net.vertices net)).length+net.leftCount+1)^2,\n      SemiprimeD1StackCalls.run program q\n        (initial (R.records (Net.vertices net)) (List.replicate net.leftCount true))=\n          some (done net.left.toList (R.records net.right.toList)) ∧\n      (done net.left.toList (R.records net.right.toList)).data .output=\n        SemiprimeD1StackOwnerLookup.records (ownerPairs net.leftCount 0 net.left.toList) [] ∧\n      (done net.left.toList (R.records net.right.toList)).data .reader=R.records net.right.toList :=by\n  obtain ⟨q,hq,hr⟩:=source_run_bounded net.left.toList (R.records net.right.toList)\n  refine ⟨q,?_,?_,output_original net,suffix_retained _ _⟩\n  · simpa only [polynomial,inputSize,input_original,Vector.length_toList] using hq\n  · simpa only [initial_original] using hr\n/-- The real complete factor suffix survives for a subsequent physical factor-row producer. -/\ntheorem factors_retained (net:Net.Network) :\n    (done net.left.toList (R.records net.right.toList)).data .reader=R.records net.right.toList :=\n  suffix_retained _ _\n/-- Original physical record/count configuration has a genuine fixed finite-machine time certificate. -/\nnoncomputable def originalInTime (net:Net.Network) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration\n        (initial (R.records (Net.vertices net)) (List.replicate net.leftCount true)))\n      (some (SemiprimeD1StackCalls.configuration (done net.left.toList (R.records net.right.toList))))\n      (polynomial net.left.toList (R.records net.right.toList)) :=by\n  rw [←initial_original]\n  exact machineBounded _ _\nend RiemannGaussian.SemiprimeD1StackNetworkOwnerIndexOriginal\n","RiemannGaussian.SemiprimeD1StackNormalizedInverseRegisterClear":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseCleanup\n/-! # Real six-field pair and eight-field coefficient cache drains -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNormalizedInverseRegisterClear\nopen SemiprimeD1StackNormalizedInverse SemiprimeD1StackNormalizedInverseView\nopen SemiprimeD1StackNormalizedInverseCalls SemiprimeD1StackNormalizedInverseCleanup\nopen SemiprimeD1StackProcedureTrace\n/-- Exactly the six actual parsed/product fields, retaining the suffix accumulator. -/\ndef pairSlot (i : Fin 6) : Stack := regRole ⟨i.val,by omega⟩\n/-- Physical cache state after the six actual drains. -/\ndef pairClear (w : Words) : Words :=\n  {w with registers:=fun k=>if k.1=.acc then w.registers k else []}\n/-- Exact literal six-slot inventory, independently of all runtime words. -/\ntheorem pair_roles : roles pairSlot=[reg .left false,reg .left true,reg .right false,reg .right true,reg .product false,reg .product true] := by decide\n/-- The physical sweep preserves all52 other fields literally. -/\ntheorem pair_cleared (w : Words) : cleared pairSlot (store w) 6=store (pairClear w) := by\n  classical\n  funext k\n  rw [cleared_full,pair_roles]\n  rcases k with k|k\n  · simp [reg,store,bank,pairClear]\n  · rcases k with ⟨r,den⟩|k\n    · cases r <;> cases den <;> simp [reg,store,bank,pairClear]\n    · simp [reg,store,bank,pairClear]\n/-- Six REAL drains count every old field byte and six actual EOF branches. -/\ntheorem pair_run (w : Words) :\n    ∃q≤6*(mass (store w)+1),Runs program q (ctl (.clearPair 0)) (store w)\n      (ctl .decrementA) (store (pairClear w)) := by\n  have hc : ∀i:Fin 6,program (ctl (.clearPair i))=.base\n      (.pop (pairSlot i) (next (fun j=>ctl (.clearPair j)) (ctl .decrementA) i)\n        (ctl (.clearPair i)) (ctl (.clearPair i))) := by\n    intro i\n    have hh:i.val+1<6 ↔ i.val<6-1 := by omega\n    simp only [program,ctl,pairSlot,pairNext,next,hh]\n  obtain ⟨q,hq,hr⟩:=sweep (by decide:0<6) pairSlot (fun j=>ctl (.clearPair j)) (ctl .decrementA) hc 5 0 rfl (store w)\n  refine ⟨q,by omega,?_⟩\n  simpa only [cleared_zero,pair_cleared,show (⟨0,by decide⟩:Fin 6)=0 from Fin.ext rfl] using hr\n/-- Every eight-field cache address is a literal static word. -/\ntheorem all_roles : roles regRole=[reg .left false,reg .left true,reg .right false,reg .right true,\n    reg .product false,reg .product true,reg .acc false,reg .acc true] := by decide\n/-- Actual whole-register cleanup retains W, array, counters, built prefix and output. -/\ntheorem registers_cleared (w : Words) : cleared regRole (store w) 8=store {w with registers:=fun _=>[]} := by\n  classical\n  funext k\n  rw [cleared_full,all_roles]\n  rcases k with k|k\n  · simp [reg,store,bank]\n  · rcases k with ⟨r,den⟩|k\n    · cases r <;> cases den <;> simp [reg,store,bank]\n    · simp [reg,store,bank]\n/-- All eight coefficient field drains are actual instructions before the acquired prefix count increases. -/\ntheorem registers_run (w : Words) :\n    ∃q≤8*(mass (store w)+1),Runs program q (ctl (.clearCoefficient 0)) (store w)\n      (ctl .bump) (store {w with registers:=fun _=>[]}) := by\n  have hc : ∀i:Fin 8,program (ctl (.clearCoefficient i))=.base\n      (.pop (regRole i) (next (fun j=>ctl (.clearCoefficient j)) (ctl .bump) i)\n        (ctl (.clearCoefficient i)) (ctl (.clearCoefficient i))) := by\n    intro i\n    have hh:i.val+1<8 ↔ i.val<8-1 := by omega\n    simp only [program,ctl,coefficientNext,next,hh]\n  obtain ⟨q,hq,hr⟩:=sweep (by decide:0<8) regRole (fun j=>ctl (.clearCoefficient j)) (ctl .bump) hc 7 0 rfl (store w)\n  refine ⟨q,by omega,?_⟩\n  simpa only [cleared_zero,registers_cleared,show (⟨0,by decide⟩:Fin 8)=0 from Fin.ext rfl] using hr\nend RiemannGaussian.SemiprimeD1StackNormalizedInverseRegisterClear\n","RiemannGaussian.SemiprimeD1StackOldVertexStream":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOldVertexStreamRoles\nimport RiemannGaussian.SemiprimeD1StackChildVertexChoiceOriginal\n/-! # Physical chronological zip of every original child vertex\nParent record fields, activity bits and the acquired scope/order vectors are\nread in lockstep. Each real whole vertex call is followed by one EOF splice\nand a complete physical workspace sweep. The history is reversed only once.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOldVertexStream\nopen SemiprimeD1StackOldVertexStreamRoles\nnamespace X\nexport SemiprimeD1StackChildVertexChoice (Label program output activity)\nend X\nnamespace P\nexport SemiprimeD1TensorTapeFieldBytecode (Label code active)\nend P\nnamespace S\nexport SemiprimeD1StackVertexRecordSplice (Label program)\nend S\nnamespace C\nexport SemiprimeD1StackCalls (State Instruction)\nend C\n/-- Four physically preserved input streams, each copied exactly once. -/\ninductive Copy where | records | activation | scopes | orders deriving DecidableEq\n/-- Exactly the four fixed initial copy sites. -/\ninstance copyFintype : Fintype Copy:=Fintype.ofList [.records,.activation,.scopes,.orders] (by intro k;cases k <;> simp)\n/-- Four literal parser sites; acquired port numbers never become instruction labels. -/\ninductive Field where | ports | table | scope | order deriving DecidableEq\n/-- Exactly the four literal field-parser sites. -/\ninstance fieldFintype : Fintype Field:=Fintype.ofList [.ports,.table,.scope,.order] (by intro k;cases k <;> simp)\n/-- Fixed caller stages, including every one of the169 physical cleanup sites. -/\ninductive Control where\n  | start | copyActivation | copyScopes | copyOrders | recordTag\n  | ports | portsValid | table | tableValid | scopeTag | scope | scopeValid\n  | orderTag | order | orderValid | activity | setActivity (bit : Bool)\n  | vertex | splice | clearPorts | clearWork (position : Fin 169)\n  | checkRecordEnd | checkActivationEnd | scopeEnd | checkScopeEnd\n  | orderEnd | checkOrderEnd | seed | reverse | success | done | abort\n  deriving DecidableEq, Fintype\n/-- All labels are finite literal source/copy/parser sites. -/\ninductive Label where\n  | local (pc : Control) | copy (site : Copy) (pc : Fin 9)\n  | field (site : Field) (pc : P.Label) | vertex (pc : X.Label)\n  | splice (pc : S.Label) | reverse (pc : Fin 4)\n  deriving Fintype\n/-- Actual old parent table retained by the active source template. -/\ndef parentRole : ChoiceStack:=.inl (A.table (V.template (E.aux .parentTable)))\n/-- Actual acquired canonical order, read by that same template. -/\ndef orderRole : ChoiceStack:=.inl (A.table (V.template (E.aux .order)))\n/-- Actual acquired child scope, read by the same source's physical dimension counter. -/\ndef scopeRole : ChoiceStack:=.inl (A.table (V.counter .bank))\n/-- Each parser consumes its current physical reader. -/\ndef fieldInput : Field→Stack\n  | .ports|.table=>aux .recordsReader | .scope=>aux .scopesReader | .order=>aux .ordersReader\n/-- Parsed words enter the real vertex-source operands directly. -/\ndef fieldOutput : Field→Stack\n  | .ports=>aux .oldPorts | .table=>choice parentRole\n  | .scope=>choice scopeRole | .order=>choice orderRole\n/-- All four parser roles, including real scratch and validity. -/\ndef fieldStack (site : Field) : F.Stack→Stack\n  | .inl .input=>fieldInput site | .inl .output=>fieldOutput site\n  | .inl .scratch=>fieldWork (.inl .scratch) | .inr ()=>fieldWork (.inr ())\n/-- Literal source and destination addresses for each of the four initial copies. -/\ndef copyEnds : Copy→Aux×Aux\n  | .records=>(.records,.recordsReader) | .activation=>(.activation,.activationReader)\n  | .scopes=>(.scopes,.scopesReader) | .orders=>(.orders,.ordersReader)\n/-- Preserving copies share one scratch word; the source and reader remain distinct. -/\ndef copyStack (site : Copy) (pc : Fin 3) : Stack:=\n  if pc=0 then aux (copyEnds site).1 else if pc=1 then aux (copyEnds site).2 else aux .copyScratch\n/-- Only the newly acquired singleton and accumulated history are visited by the splicer. -/\ndef spliceStack (pc : Fin 2) : Stack:=if pc=0 then choice X.output else aux .history\n/-- A single final consuming reversal restores chronological output order. -/\ndef reverseStack (pc : Fin 2) : Stack:=if pc=0 then aux .history else aux .output\n/-- Literal source: actual stream parsing, real whole169 call, linear splice and complete cleanup. -/\ndef program : Label→C.Instruction Stack Label\n  | .local .start=>.call (.copy .records 0) (.local .copyActivation)\n  | .local .copyActivation=>.call (.copy .activation 0) (.local .copyScopes)\n  | .local .copyScopes=>.call (.copy .scopes 0) (.local .copyOrders)\n  | .local .copyOrders=>.call (.copy .orders 0) (.local .recordTag)\n  | .local .recordTag=>.base (.pop (aux .recordsReader) (.local .abort) (.local .checkRecordEnd) (.local .ports))\n  | .local .ports=>.call (.field .ports (P.active .tagPop (none,false))) (.local .portsValid)\n  | .local .portsValid=>.base (.pop (fieldWork (.inr ())) (.local .abort) (.local .abort) (.local .table))\n  | .local .table=>.call (.field .table (P.active .tagPop (none,false))) (.local .tableValid)\n  | .local .tableValid=>.base (.pop (fieldWork (.inr ())) (.local .abort) (.local .abort) (.local .scopeTag))\n  | .local .scopeTag=>.base (.pop (aux .scopesReader) (.local .abort) (.local .abort) (.local .scope))\n  | .local .scope=>.call (.field .scope (P.active .tagPop (none,false))) (.local .scopeValid)\n  | .local .scopeValid=>.base (.pop (fieldWork (.inr ())) (.local .abort) (.local .abort) (.local .orderTag))\n  | .local .orderTag=>.base (.pop (aux .ordersReader) (.local .abort) (.local .abort) (.local .order))\n  | .local .order=>.call (.field .order (P.active .tagPop (none,false))) (.local .orderValid)\n  | .local .orderValid=>.base (.pop (fieldWork (.inr ())) (.local .abort) (.local .abort) (.local .activity))\n  | .local .activity=>.base (.pop (aux .activationReader) (.local .abort) (.local (.setActivity false)) (.local (.setActivity true)))\n  | .local (.setActivity bit)=>.base (.push (choice X.activity) bit (.local .vertex))\n  | .local .vertex=>.call (.vertex (.local .start)) (.local .splice)\n  | .local .splice=>.call (.splice (.local .start)) (.local .clearPorts)\n  | .local .clearPorts=>.base (.pop (aux .oldPorts) (.local (.clearWork 0)) (.local .clearPorts) (.local .clearPorts))\n  | .local (.clearWork i)=>.base (.pop (work (role i))\n      (if h:i.val<168 then .local (.clearWork ⟨i.val+1,by omega⟩) else .local .recordTag)\n      (.local (.clearWork i)) (.local (.clearWork i)))\n  | .local .checkRecordEnd=>.base (.pop (aux .recordsReader) (.local .checkActivationEnd) (.local .abort) (.local .abort))\n  | .local .checkActivationEnd=>.base (.pop (aux .activationReader) (.local .scopeEnd) (.local .abort) (.local .abort))\n  | .local .scopeEnd=>.base (.pop (aux .scopesReader) (.local .abort) (.local .checkScopeEnd) (.local .abort))\n  | .local .checkScopeEnd=>.base (.pop (aux .scopesReader) (.local .orderEnd) (.local .abort) (.local .abort))\n  | .local .orderEnd=>.base (.pop (aux .ordersReader) (.local .abort) (.local .checkOrderEnd) (.local .abort))\n  | .local .checkOrderEnd=>.base (.pop (aux .ordersReader) (.local .seed) (.local .abort) (.local .abort))\n  | .local .seed=>.base (.push (aux .output) false (.local .reverse))\n  | .local .reverse=>.call (.reverse 0) (.local .success)\n  | .local .success=>.base (.push (aux .success) true (.local .done))\n  | .local .done|.local .abort=>.base .halt\n  | .copy site pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack site) (Label.copy site) (SemiprimeD1StackCopy.code pc)\n  | .field site pc=>SemiprimeD1StackMultiplierLink.instruction (fieldStack site) (Label.field site) (P.code pc)\n  | .vertex pc=>SemiprimeD1StackValidationLink.instruction choice Label.vertex (X.program pc)\n  | .splice pc=>SemiprimeD1StackValidationLink.instruction spliceStack Label.splice (S.program pc)\n  | .reverse pc=>SemiprimeD1StackMultiplierLink.instruction reverseStack Label.reverse (SemiprimeD1StackReverseWord.code pc)\n/-- Eight genuine physical words: current parent records, three acquired streams and distinct headers. -/\nstructure Inputs where\n  /-- Complete original current parent record tape. -/\n  records : List Bool\n  /-- Entire acquired owner-first activity mask. -/\n  activation : List Bool\n  /-- Acquired framed vector of actual scope rows. -/\n  scopes : List Bool\n  /-- Acquired framed vector of actual canonical order rows. -/\n  orders : List Bool\n  /-- Actual old axis-vector header. -/\n  oldAxes : List Bool\n  /-- Actual old binary tensor precision. -/\n  oldPrecision : List Bool\n  /-- Appended new axis-vector header. -/\n  newAxes : List Bool\n  /-- Actual new binary tensor precision. -/\n  newPrecision : List Bool\n/-- Initial input bank; every reader, helper, history and displaced shadow starts empty. -/\ndef inputData (i : Inputs) : Stack→List Bool:=Sum.elim (fun _=>[]) (Sum.elim (fun _=>[]) (fun k=>match k with\n  | .records=>i.records | .activation=>i.activation | .scopes=>i.scopes | .orders=>i.orders\n  | .oldAxes=>i.oldAxes | .oldPrecision=>i.oldPrecision | .newAxes=>i.newAxes | .newPrecision=>i.newPrecision\n  | _=>[]))\n/-- Same literal enclosing source starts from only its eight physical operands. -/\ndef initial (i : Inputs) : C.State Stack Label:=⟨some (.local .start),none,none,inputData i,[]⟩\n/-- Actual fixed190-role compiled Boolean machine. -/\ndef machine : Turing.FinTM2:=SemiprimeD1StackCalls.machine (aux .records) (aux .output) (.local .start) program\n/-- Each parser has four distinct source/output/scratch/validity addresses. -/\ntheorem field_injective (site : Field) : Function.Injective (fieldStack site):=by cases site <;> decide\n/-- Each physical preserving copy uses three distinct actual words. -/\ntheorem copy_injective (site : Copy) : Function.Injective (copyStack site):=by cases site <;> decide\n/-- The exact two-word splicer changes no source metadata/header location. -/\ntheorem splice_injective : Function.Injective spliceStack:=by decide\n/-- The final reversal has distinct history and output addresses. -/\ntheorem reverse_injective : Function.Injective reverseStack:=by decide\n/-- All control labels are fixed finite before any graph, word, coefficient or dimension. -/\ntheorem control_finite : Finite machine.σ:=SemiprimeD1StackCalls.control_finite _ _ _ _\nend RiemannGaussian.SemiprimeD1StackOldVertexStream\n","RiemannGaussian.SemiprimeD1StackOldVertexStreamView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOldVertexStreamPrimitives\n/-! # Complete stream banks with four physically immutable header aliases\nAll functions below describe exact finite stores. They are erased proof views;\nthe literal program obtains every current operand through physical parsing.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOldVertexStreamView\nopen SemiprimeD1StackOldVertexStream SemiprimeD1StackOldVertexStreamRoles\n/-- Exactly the four displaced header allocations. -/\ndef Header (k : ChoiceStack) : Prop:=\n  k=axesRole false ∨ k=precisionRole false ∨ k=axesRole true ∨ k=precisionRole true\n/-- The header-alias predicate concerns only fixed decidable role names. -/\ninstance headerDecidable (k : ChoiceStack) : Decidable (Header k):=\n  inferInstanceAs (Decidable (_ ∨ _ ∨ _ ∨ _))\n/-- Physical raw header shadows are empty, although all169 words remain allocated. -/\ndef mask (source : ChoiceStack→List Bool) (k : ChoiceStack) : List Bool:=if Header k then [] else source k\n/-- Included source reads the immutable caller headers through four literal aliases. -/\ndef materialize (i : Inputs) (source : ChoiceStack→List Bool) (k : ChoiceStack) : List Bool:=\n  if k=axesRole false then i.oldAxes else if k=precisionRole false then i.oldPrecision\n  else if k=axesRole true then i.newAxes else if k=precisionRole true then i.newPrecision else source k\n/-- All changing words at a stable parser/call boundary. -/\nstructure Words where\n  /-- Entire actual source bank; its four header shadows are masked physically. -/\n  source : ChoiceStack→List Bool\n  /-- Actual unconsumed parent record suffix. -/\n  records : List Bool\n  /-- Actual unconsumed activity suffix. -/\n  activation : List Bool\n  /-- Actual unconsumed canonical scope vector suffix. -/\n  scopes : List Bool\n  /-- Actual unconsumed canonical order vector suffix. -/\n  orders : List Bool\n  /-- Acquired old ports, physically disposed after this iteration. -/\n  oldPorts : List Bool\n  /-- Reversed output row history, without any list EOF. -/\n  history : List Bool\n  /-- Final chronological record word. -/\n  output : List Bool\n  /-- Actual final success word. -/\n  success : List Bool\n/-- Complete17-word caller bank, including unchanged eight inputs and copy scratch. -/\ndef auxData (i : Inputs) (w : Words) : Aux→List Bool\n  | .records=>i.records | .activation=>i.activation | .scopes=>i.scopes | .orders=>i.orders\n  | .oldAxes=>i.oldAxes | .oldPrecision=>i.oldPrecision | .newAxes=>i.newAxes | .newPrecision=>i.newPrecision\n  | .recordsReader=>w.records | .activationReader=>w.activation | .scopesReader=>w.scopes | .ordersReader=>w.orders\n  | .oldPorts=>w.oldPorts | .history=>w.history | .output=>w.output | .success=>w.success | .copyScratch=>[]\n/-- Complete190-word stable store: all parser/scratch words and header shadows are present. -/\ndef data (i : Inputs) (w : Words) : Stack→List Bool:=Sum.elim (mask w.source) (Sum.elim (fun _=>[]) (auxData i w))\n/-- No work, reader, history, output or status is supplied at entry. -/\ndef empty : Words:=⟨fun _=>[],[],[],[],[],[],[],[],[]⟩\n/-- The declared eight-input frontdoor is exactly the full stable empty-work bank. -/\ntheorem initial_data (i : Inputs) : inputData i=data i empty:=by\n  funext k\n  rcases k with k|k\n  · change []=(if Header k then [] else [])\n    split <;> rfl\n  · rcases k with k|k\n    · rfl\n    · cases k <;> rfl\n/-- Every included word reads precisely its actual alias/header or raw work tape. -/\ntheorem project (i : Inputs) (w : Words) (k : ChoiceStack) : data i w (choice k)=materialize i w.source k:=by\n  by_cases h0 : k=axesRole false\n  · subst k;rfl\n  by_cases h1 : k=precisionRole false\n  · subst k;rfl\n  by_cases h2 : k=axesRole true\n  · subst k;rfl\n  by_cases h3 : k=precisionRole true\n  · subst k;rfl\n  simp only [choice,h0,h1,h2,h3,ite_false,data,work,Sum.elim_inl,mask,Header,\n    or_self,materialize]\n/-- Raw shadows themselves stay physically empty in every stable bank. -/\ntheorem shadow_empty (i : Inputs) (w : Words) (k : ChoiceStack) (hk : Header k) : data i w (work k)=[]:=ite_eq_left hk\n/-- Updating an ordinary source word commutes with masking the four other literal roles. -/\ntheorem mask_update (source : ChoiceStack→List Bool) (k : ChoiceStack) (word : List Bool) (hk : ¬Header k) :\n    mask (Function.update source k word)=Function.update (mask source) k word:=by\n  funext j\n  by_cases he : j=k\n  · subst j\n    simp only [mask,hk,ite_false,Function.update_self]\n  · simp only [mask,Function.update_of_ne he]\n/-- Parsing directly into a source operand changes no caller input or shadow. -/\ntheorem update_source (i : Inputs) (w : Words) (k : ChoiceStack) (word : List Bool) (hk : ¬Header k) :\n    Function.update (data i w) (choice k) word=data i {w with source:=Function.update w.source k word}:=by\n  have h0 : k≠axesRole false:=fun h=>hk (Or.inl h)\n  have h1 : k≠precisionRole false:=fun h=>hk (Or.inr (Or.inl h))\n  have h2 : k≠axesRole true:=fun h=>hk (Or.inr (Or.inr (Or.inl h)))\n  have h3 : k≠precisionRole true:=fun h=>hk (Or.inr (Or.inr (Or.inr h)))\n  simp only [choice,h0,h1,h2,h3,ite_false,data,mask_update _ _ _ hk,work]\n  exact (SemiprimeD1StackRename.payload_update _ _ k word).symm\n/-- Actual parent table, ordinal order, child scope and singleton activity are work operands. -/\ntheorem operand_not_header : ¬Header parentRole ∧ ¬Header orderRole ∧ ¬Header scopeRole ∧ ¬Header X.activity:=by decide\n/-- Physical record-reader update is an exact whole-bank update. -/\ntheorem update_records (i : Inputs) (w : Words) (word : List Bool) :\n    Function.update (data i w) (aux .recordsReader) word=data i {w with records:=word}:=by\n  funext k;rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · cases k <;> rfl\n/-- Physical activity-reader update is an exact whole-bank update. -/\ntheorem update_activation (i : Inputs) (w : Words) (word : List Bool) :\n    Function.update (data i w) (aux .activationReader) word=data i {w with activation:=word}:=by\n  funext k;rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · cases k <;> rfl\n/-- Physical scope-reader update is an exact whole-bank update. -/\ntheorem update_scopes (i : Inputs) (w : Words) (word : List Bool) :\n    Function.update (data i w) (aux .scopesReader) word=data i {w with scopes:=word}:=by\n  funext k;rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · cases k <;> rfl\n/-- Physical order-reader update is an exact whole-bank update. -/\ntheorem update_orders (i : Inputs) (w : Words) (word : List Bool) :\n    Function.update (data i w) (aux .ordersReader) word=data i {w with orders:=word}:=by\n  funext k;rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · cases k <;> rfl\n/-- Physical disposal-buffer update is an exact whole-bank update. -/\ntheorem update_ports (i : Inputs) (w : Words) (word : List Bool) :\n    Function.update (data i w) (aux .oldPorts) word=data i {w with oldPorts:=word}:=by\n  funext k;rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · cases k <;> rfl\n/-- The growing history is changed only by actual row splicing or final reversal. -/\ntheorem update_history (i : Inputs) (w : Words) (word : List Bool) :\n    Function.update (data i w) (aux .history) word=data i {w with history:=word}:=by\n  funext k;rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackOldVertexStreamView\n","RiemannGaussian.SemiprimeD1StackOwnerCatalogueOriginalIds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerCatalogueLoop\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackOwnerCatalogueOriginalIds\nopen SemiprimePublicAcquiredExecution\nopen SemiprimeD1StackOwnerCatalogueLoop\nopen SemiprimeD1OrdinalBankSpec (words idAt)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Original E edges paired with the FIRST E words from the actual acquired 2E bank.\nThis list is a proof description of physical parser results, never a machine input. -/\ndef pairs (N:Nat) : List (PublicEdge N×List Bool) :=\n  List.ofFn (fun i:Fin (wireCount N)=>((edgeEnumeration N).equivFin i,idAt (2*wireCount N) i.val))\n/-- Actual unused M-E bank suffix after precisely E wire-owner words have been read. -/\ndef unused (N:Nat) : List Bool := vectorBits ((words (2*wireCount N)).drop (wireCount N))\n/-- The actual edge projection is exactly the ORIGINAL constructor enumeration in order. -/\ntheorem pairs_edges (N:Nat) : (pairs N).map Prod.fst=(edgeEnumeration N).values := by\n  simp only [pairs,List.map_ofFn]\n  change (List.ofFn (fun i:Fin (edgeEnumeration N).values.length=>(edgeEnumeration N).values[i.val]))=_\n  exact List.ofFn_getElem\n/-- Exactly E bank words are read, with their original 2E-bit padding retained. -/\ntheorem pairs_ids (N:Nat) : (pairs N).map Prod.snd=(words (2*wireCount N)).take (wireCount N) := by\n  apply List.ext_getElem\n  · simp only [pairs,List.length_map,List.length_ofFn,List.length_take,SemiprimeD1OrdinalBankSpec.length]\n    omega\n  · intro i hi hj\n    have hiE:i<wireCount N:=by simpa only [pairs,List.length_map,List.length_ofFn] using hi\n    have hiM:i<(words (2*wireCount N)).length:=by rw [SemiprimeD1OrdinalBankSpec.length];omega\n    simp only [pairs,List.getElem_map,List.getElem_ofFn,List.getElem_take]\n    unfold idAt\n    rw [List.getElem?_eq_getElem hiM,Option.getD_some]\n/-- Actual six-field tape reconstruction agrees with the original edge projection. -/\ntheorem edges_map {r t digits:Nat} (ps:List (Pair r t digits)) :\n    edgeTapeOf ps=(ps.map Prod.fst).foldr SemiprimeD1EdgeCatalogueEncoding.edge [] := by\n  simp only [edgeTapeOf,List.foldr_map]\n/-- Actual ID-prefix framing agrees with the retained acquired bank suffix. -/\ntheorem ids_map {r t digits:Nat} (ps:List (Pair r t digits)) (tail:List Bool) :\n    idTapeOf ps tail=(ps.map Prod.snd).foldr (fun w rest=>true::frame w rest) tail := by\n  simp only [idTapeOf,List.foldr_map]\n/-- The ID parser's untouched suffix is physically present in the same acquired bank. -/\ntheorem vector_append (xs ys:List (List Bool)) :\n    xs.foldr (fun w rest=>true::frame w rest) (vectorBits ys)=vectorBits (xs++ys) := by\n  induction xs with\n  | nil=>rfl\n  | cons w xs ih=>simp only [List.foldr_cons,List.cons_append,vectorBits,ih]\n/-- Complete parser-entry edge reader, without a supplied order premise. -/\ntheorem original_edges (N:Nat) :\n    edgeTapeOf (pairs N)=(edgeEnumeration N).values.foldr SemiprimeD1EdgeCatalogueEncoding.edge [] := by\n  rw [edges_map,pairs_edges]\n/-- Complete parser-entry ID reader is the ACTUAL entire M bank, even though only E words are read. -/\ntheorem original_ids (N:Nat) : idTapeOf (pairs N) (unused N)=vectorBits (words (2*wireCount N)) := by\n  rw [ids_map,pairs_ids]\n  unfold unused\n  rw [vector_append,List.take_append_drop]\nend RiemannGaussian.SemiprimeD1StackOwnerCatalogueOriginalIds\n","RiemannGaussian.SemiprimeD1StackOwnerCatalogueOriginalMetadata":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerCatalogueSource\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRecipeOriginal\nimport RiemannGaussian.SemiprimeD1StackRootScopeBankOriginal\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackOwnerCatalogueOriginalMetadata\nopen SemiprimeD1StackOwnerCatalogue SemiprimeD1StackOwnerCatalogueSource\nopen SemiprimeMacroParameters SemiprimePublicAcquiredExecution\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeBitArithmetic (bitValue)\n/-- Exact original r/t/digits associated with original binary N, solely a proof specification. -/\ndef originalDimension (N:ℕ) (part:Fin 3) : ℕ :=\n  if part=0 then firstAxis (bitLength N) else if part=1 then secondAxis (bitLength N) else digitCount (bitLength N)\n/-- Actual retained dimension words already present after the N-only acquisition prefix. -/\ntheorem dimensions_raw (bits:List Bool) (part:Fin 3) : ready bits (dimension part)=unary\n    (if part=0 then firstAxis bits.length else if part=1 then secondAxis bits.length\n      else SemiprimeD1StackVertexCatalogueCaches.digitCountValue bits) := by\n  fin_cases part <;> rfl\n/-- ALL original parameter-word bindings follow from binary N and actual acquisition, not metadata advice. -/\ntheorem dimensions_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0<bitValue bits) (part:Fin 3) :\n    ready bits (dimension part)=unary (originalDimension (bitValue bits) part) := by\n  have hw:bits.length=bitLength (bitValue bits):=SemiprimeD1BinaryBootstrap.canonical_width bits hc\n  have hb:bits≠[]:=by intro h;subst bits;simp [bitValue] at hN\n  rw [dimensions_raw,SemiprimeD1StackVertexCatalogueTags.digitCount_raw bits hb,hw]\n  rfl\n/-- The actually copied edge reader is the complete original E-wire tape in exact original order. -/\ntheorem edges_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    edges bits=(edgeEnumeration (bitValue bits)).values.foldr SemiprimeD1EdgeCatalogueEncoding.edge [] := by\n  exact SemiprimeD1StackEdgeCatalogueExecution.original_edges bits hc hN\n/-- Same physically acquired bytes in the parser's literal six-field record grammar. -/\ntheorem edge_reader_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ready bits (aux .readerEdges)=SemiprimeD1StackEdgeCount.tape\n      ((edgeEnumeration (bitValue bits)).values.map SemiprimeD1StackEdgeCount.edgeFields) [] := by\n  change edges bits=_\n  rw [SemiprimeD1StackEdgeCount.original_tape]\n  exact edges_original bits hc hN\n/-- The actual ordinal engine receives M=2E from TWO real counter pushes per original edge. -/\ntheorem occurrences_original (bits:List Bool) :\n    SemiprimeD1StackRootScopeBankExecution.occurrenceCount bits=2*wireCount (bitValue bits) :=\n  congrArg (2*·) (SemiprimeD1StackRootScopeBankOriginal.wire_count bits)\n/-- The actual private ID reader contains the physically generated padded M-bank, never an E-bank substitute. -/\ntheorem id_reader_original (bits:List Bool) :\n    ready bits (aux .readerIds)=SemiprimeD1TensorTapeCodec.vectorBits\n      (SemiprimeD1OrdinalBankSpec.words (2*wireCount (bitValue bits))) := by\n  calc\n    ready bits (aux .readerIds)=ids bits:=rfl\n    _=SemiprimeD1TensorTapeCodec.vectorBits\n        (SemiprimeD1OrdinalBankSpec.words (SemiprimeD1StackRootScopeBankExecution.occurrenceCount bits)):=\n      SemiprimeD1StackRootScopeBankExecution.result_ids bits\n    _=_:=congrArg (fun n=>SemiprimeD1TensorTapeCodec.vectorBits (SemiprimeD1OrdinalBankSpec.words n))\n      (occurrences_original bits)\n/-- Every original E-wire ordinal is legitimately in the acquired M-bank's first E entries. -/\ntheorem owner_id_value (bits:List Bool) (wire:Fin (wireCount (bitValue bits))) :\n    bitValue (SemiprimeD1OrdinalBankSpec.idAt (2*wireCount (bitValue bits)) wire.val)=wire.val :=\n  SemiprimeD1OrdinalBankSpec.id_value _ _ (by have hi:=wire.isLt;omega)\n/-- Both original namespaces use actual M-bit payloads, while this owner ID's value lies in Fin E. -/\ntheorem owner_id_width (bits:List Bool) (wire:Fin (wireCount (bitValue bits))) :\n    (SemiprimeD1OrdinalBankSpec.idAt (2*wireCount (bitValue bits)) wire.val).length=2*wireCount (bitValue bits) :=\n  SemiprimeD1OrdinalBankSpec.id_length _ _ (by have hi:=wire.isLt;omega)\nend RiemannGaussian.SemiprimeD1StackOwnerCatalogueOriginalMetadata\n","RiemannGaussian.SemiprimeD1StackOwnerCatalogueRow":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerCatalogueCacheClear\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackOwnerCatalogueRow\nopen SemiprimeD1StackOwnerCatalogue SemiprimeD1StackOwnerCatalogueSource\nopen SemiprimeD1StackOwnerCatalogueFields SemiprimeD1StackOwnerCatalogueParse\nopen SemiprimeD1StackOwnerCatalogueRecord SemiprimeD1StackOwnerCatalogueCalls\nopen SemiprimeD1StackOwnerCatalogueEmit SemiprimeD1StackOwnerCatalogueClear\nopen SemiprimeD1StackOwnerCatalogueCacheClear\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\nnamespace P\nexport SemiprimeD1StackPortOwnerRecipeSpec (Counters words)\nexport SemiprimeD1StackPortOwnerRecipe (Tag)\nexport SemiprimeD1StackPortOwnerRecipeDecision (tagCode)\nend P\n/-- Exact actual recipe-work payload after its real complete call. -/\ndef recipeWork (c:P.Counters) (tag:P.Tag) : RecipeWork→List Bool :=\n  fun k=>(SemiprimeD1StackPortOwnerRecipeExecution.done c tag).data (.inr k)\n/-- Physically computed arithmetic output bytes, used only to describe the execution result. -/\ndef arithmeticBytes (c:P.Counters) (tag:P.Tag) : List Bool := recipeWork c tag (.inr .output)\n/-- Equality key consists of the actually framed record and the actually copied true sentinel. -/\ndef equalityBytes (p:Fin 7→List Bool) : List Bool := edgeRest p 0 []++[true]\n/-- Actual rows emitted for both endpoints, retaining the SAME next acquired ID word. -/\ndef emitted (p:Fin 7→List Bool) (c:P.Counters) (tag:P.Tag) : List Bool :=\n  rowBytes (arithmeticBytes c tag) (p 6)++rowBytes (equalityBytes p) (p 6)\n/-- Actual cleanup payloads: seven parsed words, rebuilt record and sentinel-copy key. -/\ndef rowPacket (p:Fin 7→List Bool) : Packet :=\n  fun i=>if h:i.val<7 then p ⟨i.val,h⟩ else if i=7 then edgeRest p 0 [] else equalityBytes p\n/-- Sum of the SAME physical row parser, builder, arithmetic, emitter and cleanup source bounds. -/\ndef budget (p:Fin 7→List Bool) (c:P.Counters) (tag:P.Tag) : Nat :=\n  (1+edgeTime p 6+(8*(p 6).length+9))+recordTime p 6+\n  (5*(edgeRest p 0 []).length+7)+(SemiprimeD1StackPortOwnerRecipeExecution.budget c tag+1)+\n  (10*(arithmeticBytes c tag).length+10*(equalityBytes p).length+20*(p 6).length+42)+\n  workTime (recipeWork c tag) 47+cacheTime (rowPacket p) 9\n/-- All actual recipe inputs avoid private outer builder/collector scratch. -/\ntheorem input_aux (s:S.Stack→List Bool) (f:Fin 7→List Bool) (a b:Aux→List Bool) (i:R.Input) :\n    data s (fun _=>[]) f a (recipeStack (.inl i))=\n      data s (fun _=>[]) f b (recipeStack (.inl i)) := by cases i <;> rfl\n/-- A complete SAME-source iteration: parse one real edge and next ID, compute both keys,\nemit both rows, physically erase all 56 row/work roles and return to the edge-tape loop.\nThe counter interpretation is proof-only; every runtime operand comes from acquired tapes. -/\ntheorem row_run (s:S.Stack→List Bool) (p:Fin 7→List Bool) (c:P.Counters) (tag:P.Tag)\n    (ht:c.tag=(P.tagCode tag).val) (hd:0<c.digits) (edges ids collector:List Bool)\n    (hi:∀i:R.Input,data s (fun _=>[]) p (rowAux edges ids collector) (recipeStack (.inl i))=P.words c i) :\n    ∃time≤budget p c tag,Runs program time (.local .parse)\n      (data s (fun _=>[]) (parsed p 0) (parseAux p 0 edges ids collector))\n      (.local .parse) (data s (fun _=>[]) (fun _=>[])\n        (rowAux edges ids ((emitted p c tag).reverse++collector))) := by\n  let a0:=rowAux edges ids collector\n  let a1:=Function.update a0 .record (edgeRest p 0 [])\n  let a2:=Function.update a1 .equalityKey (equalityBytes p)\n  let a3:=Function.update a2 .reversed ((emitted p c tag).reverse++collector)\n  have hread:=row_read s (fun _=>[]) p edges ids collector\n  have hrecord:=record_run s (fun _=>[]) p edges ids collector\n  change Runs program _ _ _ _ (data s (fun _=>[]) p a1) at hrecord\n  have heq:=equality_call (data s (fun _=>[]) p a1)\n    (by change a1 .equalityKey=[];exact Function.update_of_ne (by decide) _ _)\n    (by change a1 .equalityScratch=[];exact Function.update_of_ne (by decide) _ _)\n  have hrec:data s (fun _=>[]) p a1 (aux .record)=edgeRest p 0 []:=by\n    change a1 .record=_;exact Function.update_same _ _ _\n  rw [hrec,update_aux] at heq\n  change Runs program _ _ _ _ (data s (fun _=>[]) p a2) at heq\n  obtain ⟨t,htime,hrecipe⟩:=recipe_call s p a2 c tag ht hd (fun i=>by\n    rw [input_aux s p a2 a0 i];exact hi i)\n  change Runs program _ _ _ _ (data s (recipeWork c tag) p a2) at hrecipe\n  have hem:=emit_both s (recipeWork c tag) p a2\n    (by simp only [a2,a1,Function.update_of_ne (by decide : Aux.frameBuffer≠.equalityKey),\n      Function.update_of_ne (by decide : Aux.frameBuffer≠.record)];rfl)\n    (by simp only [a2,a1,Function.update_of_ne (by decide : Aux.frameScratch≠.equalityKey),\n      Function.update_of_ne (by decide : Aux.frameScratch≠.record)];rfl)\n  have hkey:data s (recipeWork c tag) p a2 (keySource false)=arithmeticBytes c tag:=rfl\n  have hekey:a2 .equalityKey=equalityBytes p:=Function.update_same _ _ _\n  have hcol:a2 .reversed=collector:=by\n    simp only [a2,a1,Function.update_of_ne (by decide : Aux.reversed≠.equalityKey),\n      Function.update_of_ne (by decide : Aux.reversed≠.record)];rfl\n  rw [hkey,hekey,hcol] at hem\n  change Runs program _ _ _ _ (data s (recipeWork c tag) p a3) at hem\n  have hw:=work_run s (recipeWork c tag) p a3\n  have hp:data s (fun _=>[]) p a3=\n      packet s (rowPacket p) edges ids ((emitted p c tag).reverse++collector):=by\n    funext k;rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · change p k=rowPacket p ⟨k.val,by omega⟩\n          simp only [rowPacket,k.isLt,dite_eq_left]\n        · cases k <;> simp only [packet,data,a3,a2,a1,a0,rowPacket,equalityBytes] <;> rfl\n  rw [hp] at hw\n  have hc:=cache_run s (rowPacket p) edges ids ((emitted p c tag).reverse++collector)\n  have h:=runs_trans program _ _ _ _ _ _ _ _ hread\n    (runs_trans program _ _ _ _ _ _ _ _ hrecord\n      (runs_trans program _ _ _ _ _ _ _ _ heq\n        (runs_trans program _ _ _ _ _ _ _ _ hrecipe\n          (runs_trans program _ _ _ _ _ _ _ _ hem (runs_trans program _ _ _ _ _ _ _ _ hw hc)))))\n  refine ⟨_,?_,h⟩\n  unfold budget\n  omega\nend RiemannGaussian.SemiprimeD1StackOwnerCatalogueRow\n","RiemannGaussian.SemiprimeD1StackOwnerPrefixComponents":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerPrefix\n/-! # Literal parser/copy/binary-equality calls in the owner-prefix source -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeD1StackOwnerPrefixComponents\nopen SemiprimeD1StackOwnerPrefix SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\n\n/-- Real framed-key parse pays every tag, key bit, restoration and validity bit. -/\ntheorem field_call (low high : Bool) (query key tail : List Bool) :\n    Runs program (8*key.length+7) (.parse low high)\n      (data query (frame key tail) [] [] [] [] []) (.parsed low high)\n      (data query tail key [] [] [true] []) := by\n  apply included_call program fieldStack (Label.field low high) field_injective F.code\n    (F.active .tagPop (none,false)) (fun _=>rfl) (.parse low high) (.parsed low high) rfl\n    (8*key.length+6) (SemiprimeD1TensorTapeFieldBytecode.initial (frame key tail) [])\n    (⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] key) (fun _=>[true])⟩:\n      SemiprimeD1StackBytecode.State F.Stack F.Label)\n  · rfl\n  · rfl\n  · exact SemiprimeD1TensorTapeFieldBytecode.framed_run key tail []\n  · constructor\n    · intro k;rcases k with k|k <;> cases k <;> rfl\n    · intro k hk;rfl\n  · constructor\n    · intro k;rcases k with k|k <;> cases k <;> rfl\n    · intro k hk\n      rcases k with k|k\n      · cases k <;> first | rfl | exact (hk (.inl .output) rfl).elim\n      · cases k <;> first | rfl | exact (hk (.inl .input) rfl).elim | exact (hk (.inr ()) rfl).elim\n\n/-- Actual preserving query copy: no equality operand is supplied by a getter. -/\ntheorem copy_call (low high : Bool) (query reader key : List Bool) :\n    Runs program (5*query.length+4) (.copyKey low high) (data query reader key [] [] [] [])\n      (.compare low high) (data query reader key query [] [] []) := by\n  apply included_call program copyStack (Label.copy low high) copy_injective SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (.copyKey low high) (.compare low high) rfl (5*query.length+3)\n    (SemiprimeD1StackCopy.state 0 none query [] []) (SemiprimeD1StackCopy.done query query)\n  · rfl\n  · rfl\n  · simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words query [] none\n  · constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k hk;rfl\n  · constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k hk\n      rcases k with k|k\n      · cases k <;> first | rfl | exact (hk 1 rfl).elim\n      · cases k <;> rfl\n\n/-- Literal binary numeric equality physically consumes both actual key words.\nPadding differences remain valid; original wire identity is proved separately. -/\ntheorem equal_call (low high : Bool) (query reader key : List Bool) :\n    Runs program (SemiprimeD1StackWordEqualExecution.executionTime key query+1) (.compare low high)\n      (data query reader key query [] [] []) (.matched low high)\n      (data query reader [] [] [decide (SemiprimeBitArithmetic.bitValue key=SemiprimeBitArithmetic.bitValue query)] [] []) := by\n  apply included_call program Sum.inl (Label.equal low high) Sum.inl_injective E.code .loop\n    (fun _=>rfl) (.compare low high) (.matched low high) rfl _\n    (SemiprimeD1StackWordEqual.state (some .loop) none key query [])\n    (SemiprimeD1StackWordEqual.state none none [] []\n      [decide (SemiprimeBitArithmetic.bitValue key=SemiprimeBitArithmetic.bitValue query)])\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackWordEqualExecution.source_run key query none\n  · constructor\n    · intro k;rfl\n    · intro k hk;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · exact (hk k rfl).elim\n      · cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackOwnerPrefixComponents\n","RiemannGaussian.SemiprimeD1StackOwnerTableComponents":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerTable\nimport RiemannGaussian.SemiprimeD1StackProcedureInclusion\n/-! # Actual counting, complete prefix scan and literal owner-table source calls -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeD1StackOwnerTableComponents\nopen SemiprimeD1StackOwnerTable SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1OwnerPrefixBits (records scan)\n\n/-- ONE real scope scan physically acquires degree from every scope-ID record. -/\ntheorem count_call (key prefixBytes : List Bool) (scopeWords : List (List Bool)) :\n    Runs program (SemiprimeD1StackDigitCountExecution.totalTime scopeWords+1) .start\n      (data key prefixBytes (vectorBits scopeWords) [] [] []) .count0\n      (data key prefixBytes (vectorBits scopeWords) (List.replicate scopeWords.length true) [] []) := by\n  apply SemiprimeD1StackProcedureInclusion.included_call program countStack Label.count count_injective\n    D.program (.inl .main) (fun _=>rfl) .start .count0 rfl _\n    (SemiprimeD1StackDigitCountExecution.initial (vectorBits scopeWords))\n    (SemiprimeD1StackDigitCountExecution.done scopeWords)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackDigitCountExecution.acquire_run scopeWords\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k hk;rfl\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · exact (hk k rfl).elim\n        · cases k;rfl\n/-- The full actual prefix scanner computes both flags from original records.\nNo allowed-pair result is supplied to the count/table program. -/\ntheorem prefix_call (degree : Fin 3) (key : List Bool) (rows : List (List Bool×Bool))\n    (tail scopeBytes : List Bool) :\n    Runs program (SemiprimeD1StackOwnerPrefixExecution.loopTime key rows+2) (.scan degree)\n      (data key (records rows tail) scopeBytes [] [] []) (.low degree)\n      (data key tail scopeBytes [] [(scan key rows true true).1,(scan key rows true true).2] []) := by\n  apply SemiprimeD1StackProcedureInclusion.included_call program Sum.inl Label.prefixScan Sum.inl_injective\n    P.program (.loop true true) (fun _=>rfl) (.scan degree) (.low degree) rfl _\n    (SemiprimeD1StackOwnerPrefix.initial key (records rows tail))\n    (SemiprimeD1StackOwnerPrefix.done key rows tail)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackOwnerPrefixExecution.source_run key rows tail\n  · constructor\n    · intro k;rfl\n    · intro k hk;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · exact (hk k rfl).elim\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k;rfl\n/-- Empty-data finite palette code writes every literal byte through real pushes. -/\ntheorem palette_call (degree : Fin 3) (low high : Bool) (key tail scopeBytes : List Bool) :\n    Runs program ((SemiprimeD1OwnerTablePalette.bytes degree low high).length+2) (.emit degree low high)\n      (data key tail scopeBytes [] [] []) .done\n      (data key tail scopeBytes [] [] (SemiprimeD1OwnerTablePalette.bytes degree low high)) := by\n  apply included_call program (fun _ : Unit=>output) Label.palette\n    (by intro a b h;cases a;cases b;rfl) T.code ((degree,low,high),0)\n    (fun _=>rfl) (.emit degree low high) .done rfl _\n    (SemiprimeD1StackOwnerPaletteSource.initial (degree,low,high))\n    (SemiprimeD1StackOwnerPaletteSource.done (degree,low,high))\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackOwnerPaletteSource.source_run (degree,low,high)\n  · constructor\n    · intro k;cases k;rfl\n    · intro k hk;rfl\n  · constructor\n    · intro k;cases k;rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k;exact (hk () rfl).elim\nend RiemannGaussian.SemiprimeD1StackOwnerTableComponents\n","RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedFactorRecovery\n/-! # Complete physical recovery views and exact binary stage words -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryEncoding\nopen SemiprimeD1StackPackedFactorRecovery SemiprimeBitArithmetic SemiprimeBitDivision\n/-- All four additional words, with no discarded scratch. -/\ndef words (small large status scratch : List Bool) : Aux→List Bool\n  | .small=>small | .large=>large | .status=>status | .scratch=>scratch\n/-- Full readout, metadata, arithmetic and factor bank at every stage. -/\ndef view (r : R.Stack→List Bool) (m : SemiprimeD1StackBinarySquareRoot.M.Stack→List Bool)\n    (a : A.Stack→List Bool) (x : X.Stack→List Bool) (w : W.Stack→List Bool)\n    (v : SemiprimeD1StackBinarySquareRoot.Aux→List Bool) (u : Aux→List Bool) : Stack→List Bool :=\n  bank r (SemiprimeD1StackBinarySquareRoot.bank m a x w v) u\n/-- Literal raw square word emitted by the actual multiplier. -/\ndef squareWord (s : List Bool) : List Bool := (mulBits s s).bits\n/-- Two physically pushed low FALSE bits implement multiplication by four. -/\ndef fourWord (n : List Bool) : List Bool := false::false::n\n/-- Exact actual subtraction report, including the physical underflow bit. -/\ndef discriminantReport (n s : List Bool) : SubReport := subBits (squareWord s) (fourWord n) false\n/-- Binary discriminant bytes, never expanded into unary. -/\ndef discriminant (n s : List Bool) : List Bool := (discriminantReport n s).result.bits\n/-- Actual frozen whole square-root output on the acquired discriminant. -/\ndef rootWord (n s : List Bool) : List Bool :=\n  SemiprimeD1StackBinarySquareRootArithmetic.output (discriminant n s)\n/-- Exact actual lower-numerator report, including the physical borrow. -/\ndef minusReport (s root : List Bool) : SubReport := subBits s root false\n/-- Exact actual upper numerator, emitted by the real binary adder. -/\ndef plusWord (s root : List Bool) : List Bool := (addBits s root false).bits\n/-- Real reversal and trim compact precisely the physically popped low-bit tail. -/\ndef halfWord (numerator : List Bool) : List Bool :=\n  SemiprimeD1StackReduceExecution.trimReverse numerator.tail.reverse\n/-- Exact update of one actual retained readout role. -/\ntheorem bank_readout (r : R.Stack→List Bool) (s : S.Stack→List Bool) (u : Aux→List Bool)\n    (k : R.Stack) (xs : List Bool) :\n    Function.update (bank r s u) (readout k) xs=bank (Function.update r k xs) s u :=\n  Sum.update_elim_inl\n/-- Exact update of one actual square-root-bank role. -/\ntheorem bank_squareRoot (r : R.Stack→List Bool) (s : S.Stack→List Bool) (u : Aux→List Bool)\n    (k : S.Stack) (xs : List Bool) :\n    Function.update (bank r s u) (squareRoot k) xs=bank r (Function.update s k xs) u := by\n  dsimp only [bank,squareRoot]\n  rw [Sum.update_elim_inr,Sum.update_elim_inl]\n/-- Exact update of one dedicated factor/status/scratch role. -/\ntheorem bank_aux (r : R.Stack→List Bool) (s : S.Stack→List Bool) (u : Aux→List Bool)\n    (k : Aux) (xs : List Bool) :\n    Function.update (bank r s u) (aux k) xs=bank r s (Function.update u k xs) := by\n  dsimp only [bank,aux]\n  rw [Sum.update_elim_inr,Sum.update_elim_inr]\n/-- Each dedicated-word update retains the other three physical words. -/\ntheorem words_update (small large status scratch xs : List Bool) (k : Aux) :\n    Function.update (words small large status scratch) k xs=\n      words (if k=.small then xs else small) (if k=.large then xs else large)\n        (if k=.status then xs else status) (if k=.scratch then xs else scratch) := by\n  funext q;cases k <;> cases q <;> rfl\n/-- A real shared-adder update preserves every foreign bank. -/\ntheorem view_adder (r m a x w v u) (k : A.Stack) (xs : List Bool) :\n    Function.update (view r m a x w v u) (adder k) xs=view r m (Function.update a k xs) x w v u := by\n  change Function.update (bank r _ u) (squareRoot (S.adder k)) xs=_\n  rw [bank_squareRoot,SemiprimeD1StackBinarySquareRootEncoding.bank_adder]\n  rfl\n/-- A real shared-multiplier update preserves every foreign bank. -/\ntheorem view_multiply (r m a x w v u) (k : X.Stack) (xs : List Bool) :\n    Function.update (view r m a x w v u) (multiply k) xs=view r m a (Function.update x k xs) w v u := by\n  change Function.update (bank r _ u) (squareRoot (S.multiply k)) xs=_\n  rw [bank_squareRoot,SemiprimeD1StackBinarySquareRootEncoding.bank_multiply]\n  rfl\n/-- A real shared-comparison update preserves every foreign bank. -/\ntheorem view_compare (r m a x w v u) (k : W.Stack) (xs : List Bool) :\n    Function.update (view r m a x w v u) (compare k) xs=view r m a x (Function.update w k xs) v u := by\n  change Function.update (bank r _ u) (squareRoot (S.compare k)) xs=_\n  rw [bank_squareRoot,SemiprimeD1StackBinarySquareRootEncoding.bank_compare]\n  rfl\n/-- A real retained-metadata update preserves all arithmetic and output words. -/\ntheorem view_metadata (r m a x w v u) (k : SemiprimeD1StackBinarySquareRoot.M.Stack) (xs : List Bool) :\n    Function.update (view r m a x w v u) (squareRoot (SemiprimeD1StackBinarySquareRoot.metadata k)) xs=\n      view r (Function.update m k xs) a x w v u := by\n  change Function.update (bank r _ u) (squareRoot _) xs=_\n  rw [bank_squareRoot,SemiprimeD1StackBinarySquareRootEncoding.bank_metadata]\n  rfl\n/-- A dedicated output update preserves all55 included physical words. -/\ntheorem view_aux (r m a x w v u) (k : Aux) (xs : List Bool) :\n    Function.update (view r m a x w v u) (aux k) xs=view r m a x w v (Function.update u k xs) :=\n  bank_aux r _ u k xs\n/-- Both final factor encodings are compact after the actual reversal/trim. -/\ntheorem halfWord_compact (numerator : List Bool) : SemiprimeSourceCompactBits.Compact (halfWord numerator) :=\n  SemiprimeD1StackReduceExecution.trimReverse_compact _\n/-- Physical compaction preserves the actual low-bit-pop quotient. -/\ntheorem halfWord_value (numerator : List Bool) : bitValue (halfWord numerator)=bitValue numerator.tail := by\n  rw [halfWord,SemiprimeD1StackReduceExecution.trimReverse_value,List.reverse_reverse]\nend RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryEncoding\n","RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryHalves":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryCopies\nimport RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryCompaction\n/-! # Physical S-minus-root and S-plus-root halves, including borrow/parity pops -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryHalves\nopen SemiprimeD1StackPackedFactorRecovery SemiprimeD1StackPackedFactorRecoveryEncoding\nopen SemiprimeD1StackPackedFactorRecoveryPrimitives SemiprimeD1StackProcedureTrace\nnamespace P\nexport SemiprimeD1StackPackedFactorRecoveryCopies (adder_left adder_right)\nend P\n/-- All acquired metadata and root output are retained throughout both real numerators. -/\ndef phase (r : R.Stack→List Bool) (m : SemiprimeD1StackPackedRootMetadata.Stack→List Bool)\n    (root small large : List Bool) (a : A.Stack→List Bool) : Stack→List Bool :=\n  view r m a (fun _=>[]) (fun _=>[]) (SemiprimeD1StackBinarySquareRootEncoding.words [] root)\n    (words small large [] [])\n/-- The actual frozen square-root halt is exactly this clean retained-root phase. -/\ntheorem phase_result (r : R.Stack→List Bool) (d : List Bool) :\n    phase r (SemiprimeD1StackBinarySquareRootEncoding.retained d [])\n      (SemiprimeD1StackBinarySquareRootArithmetic.output d) [] [] (A.store [] [] [] [])=\n      bank r (SemiprimeD1StackBinarySquareRootEncoding.result d) (words [] [] [] []) := by\n  funext k\n  rcases k with k|k|k\n  · rfl\n  · rcases k with k|k|k|k|k\n    · rfl\n    · cases k <;> rfl\n    · rfl\n    · rfl\n    · rfl\n  · rfl\n/-- Own exact lower-half cost, including both actual FALSE pops and output drain. -/\ndef minusTime (s root lo : List Bool) : ℕ :=\n  (5*s.length+4)+(5*root.length+4)+subtractTime s root+1+1+(5*lo.length+4)+(lo.length+1)\n/-- Actual lower numerator, borrow read, parity pop, copy and drain retain every cache. -/\ntheorem minus_run (r : R.Stack→List Bool) (m : SemiprimeD1StackPackedRootMetadata.Stack→List Bool)\n    (s root lo : List Bool) (hs : r (R.aux .sum)=s)\n    (hb : (minusReport s root).borrow=false) (hn : (minusReport s root).result.bits=false::lo) :\n    Runs program (minusTime s root lo) (ctl (.copy .minusLeft)) (phase r m root [] [] (A.store [] [] [] []))\n      (ctl (.copy .plusLeft)) (phase r m root lo [] (A.store [] [] [] [])) := by\n  let x : X.Stack→List Bool:=fun _=>[]\n  let w : W.Stack→List Bool:=fun _=>[]\n  let v:=SemiprimeD1StackBinarySquareRootEncoding.words [] root\n  let u:=words [] [] [] []\n  have h0:=P.adder_left .minusLeft (ctl (.copy .minusLeft)) (ctl (.copy .minusRight))\n    r m x w v u [] [] [] [] s rfl rfl hs rfl\n  simp only [List.append_nil] at h0\n  have h1:=P.adder_right .minusRight (ctl (.copy .minusRight)) (ctl .minus)\n    r m x w v u s [] [] [] root rfl rfl rfl rfl\n  simp only [List.append_nil] at h1\n  have h2:=subtract_call r m x w v u s root (ctl .minus) (ctl .minusBorrow) rfl\n  change Runs program _ _ _ _ (phase r m root [] [] (A.store [] [] [] ((minusReport s root).borrow::(minusReport s root).result.bits))) at h2\n  rw [hb,hn] at h2\n  have h3:=pop_false (ctl .minusBorrow) (ctl .minusParity) (ctl (.abort 0)) (ctl (.abort 0))\n    (adder .output) (phase r m root [] [] (A.store [] [] [] (false::false::lo))) (false::lo) rfl rfl\n  rw [phase,view_adder,SemiprimeD1StackAdder.store_output] at h3\n  have h4:=pop_false (ctl .minusParity) (ctl (.copy .small)) (ctl (.abort 0)) (ctl (.abort 0))\n    (adder .output) (phase r m root [] [] (A.store [] [] [] (false::lo))) lo rfl rfl\n  rw [phase,view_adder,SemiprimeD1StackAdder.store_output] at h4\n  have h5:=copy_call .small (ctl (.copy .small)) (ctl .clearMinus) rfl\n    (phase r m root [] [] (A.store [] [] [] lo)) lo [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update _ (aux .small) (lo++[])) at h5\n  rw [List.append_nil,phase,view_aux,words_update] at h5\n  have h6:=drain_call (ctl .clearMinus) (ctl (.copy .plusLeft)) (adder .output)\n    (phase r m root lo [] (A.store [] [] [] lo)) lo rfl rfl\n  rw [phase,view_adder,SemiprimeD1StackAdder.store_output] at h6\n  exact join (join (join (join (join (join h0 h1) h2) h3) h4) h5) h6\n/-- Own exact upper-half cost includes its actual parity pop and every cleanup cell. -/\ndef plusTime (s root hi : List Bool) : ℕ :=\n  (5*s.length+4)+(5*root.length+4)+addTime s root+1+(5*hi.length+4)+(hi.length+1)\n/-- Actual upper numerator and low-bit pop, preserving the already acquired lower half. -/\ntheorem plus_run (r : R.Stack→List Bool) (m : SemiprimeD1StackPackedRootMetadata.Stack→List Bool)\n    (s root lo hi : List Bool) (hs : r (R.aux .sum)=s) (hn : plusWord s root=false::hi) :\n    Runs program (plusTime s root hi) (ctl (.copy .plusLeft)) (phase r m root lo [] (A.store [] [] [] []))\n      (ctl (.reverse false)) (phase r m root lo hi (A.store [] [] [] [])) := by\n  let x : X.Stack→List Bool:=fun _=>[]\n  let w : W.Stack→List Bool:=fun _=>[]\n  let v:=SemiprimeD1StackBinarySquareRootEncoding.words [] root\n  let u:=words lo [] [] []\n  have h0:=P.adder_left .plusLeft (ctl (.copy .plusLeft)) (ctl (.copy .plusRight))\n    r m x w v u [] [] [] [] s rfl rfl hs rfl\n  simp only [List.append_nil] at h0\n  have h1:=P.adder_right .plusRight (ctl (.copy .plusRight)) (ctl .plus)\n    r m x w v u s [] [] [] root rfl rfl rfl rfl\n  simp only [List.append_nil] at h1\n  have h2:=add_call r m x w v u s root (ctl .plus) (ctl .plusParity) rfl\n  change Runs program _ _ _ _ (phase r m root lo [] (A.store [] [] [] (plusWord s root))) at h2\n  rw [hn] at h2\n  have h3:=pop_false (ctl .plusParity) (ctl (.copy .large)) (ctl (.abort 0)) (ctl (.abort 0))\n    (adder .output) (phase r m root lo [] (A.store [] [] [] (false::hi))) hi rfl rfl\n  rw [phase,view_adder,SemiprimeD1StackAdder.store_output] at h3\n  have h4:=copy_call .large (ctl (.copy .large)) (ctl .clearPlus) rfl\n    (phase r m root lo [] (A.store [] [] [] hi)) hi [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update _ (aux .large) (hi++[])) at h4\n  rw [List.append_nil,phase,view_aux,words_update] at h4\n  have h5:=drain_call (ctl .clearPlus) (ctl (.reverse false)) (adder .output)\n    (phase r m root lo hi (A.store [] [] [] hi)) hi rfl rfl\n  rw [phase,view_adder,SemiprimeD1StackAdder.store_output] at h5\n  exact join (join (join (join (join h0 h1) h2) h3) h4) h5\n/-- Both physically obtained halves are actually compacted before validation. -/\ntheorem compact_run (r : R.Stack→List Bool) (m : SemiprimeD1StackPackedRootMetadata.Stack→List Bool)\n    (root lo hi : List Bool) (hp : m (SemiprimeD1StackPackedRootMetadata.aux .base)=[]) :\n    Runs program (SemiprimeD1StackPackedFactorRecoveryCompaction.time lo+SemiprimeD1StackPackedFactorRecoveryCompaction.time hi)\n      (ctl (.reverse false)) (phase r m root lo hi (A.store [] [] [] []))\n      (ctl (.copy .checkSmall))\n      (phase r m root (SemiprimeD1StackReduceExecution.trimReverse lo.reverse)\n        (SemiprimeD1StackReduceExecution.trimReverse hi.reverse) (A.store [] [] [] [])) := by\n  have h0:=SemiprimeD1StackPackedFactorRecoveryCompaction.compact_call false\n    (phase r m root lo hi (A.store [] [] [] [])) lo rfl hp rfl rfl\n  change Runs program _ _ _ _ (Function.update _ (aux .small) _) at h0\n  rw [phase,view_aux,words_update] at h0\n  have h1:=SemiprimeD1StackPackedFactorRecoveryCompaction.compact_call true\n    (phase r m root (SemiprimeD1StackReduceExecution.trimReverse lo.reverse) hi (A.store [] [] [] [])) hi rfl hp rfl rfl\n  change Runs program _ _ _ _ (Function.update _ (aux .large) _) at h1\n  rw [phase,view_aux,words_update] at h1\n  exact join h0 h1\nend RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryHalves\n","RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryMeaning":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryExecution\n/-! # Every semiprime discharges the actual recovery branches and physical checks\nThe prime factors occur only in proofs connecting the actual packed scalar\nand actual output words. The runtime ABI remains original binary N plus V.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryMeaning\nopen SemiprimeD1StackPackedFactorRecovery SemiprimeD1StackPackedFactorRecoveryEncoding\nopen SemiprimeD1StackPackedFactorRecoveryExecution SemiprimeD1StackPackedFactorRecoveryArithmetic\nopen SemiprimeBitArithmetic SemiprimeSourceCompactBits\nnamespace O\nexport SemiprimeD1StackPackedMomentReadoutOriginal (semiprime_values semiprime_count_bytes)\nend O\n/-- Proof-only physical count-word case; the program executes its own byte parser. -/\nabbrev squareCase (bits scalar : List Bool) : Prop := (retained bits scalar) (R.aux .count)=[true]\n/-- The lower raw half is the actual physical low-bit-pop tail. -/\ndef lowerTail (bits scalar : List Bool) : List Bool :=\n  (minusReport (sumWord bits scalar) (rootWord bits (sumWord bits scalar))).result.bits.tail\n/-- The upper raw half is the actual physical low-bit-pop tail. -/\ndef upperTail (bits scalar : List Bool) : List Bool :=\n  (plusWord (sumWord bits scalar) (rootWord bits (sumWord bits scalar))).tail\n/-- Exact source result is specified from the actual readout/arithmetic words only. -/\ndef result (bits scalar : List Bool) : Stack→List Bool :=\n  if squareCase bits scalar then squareResult bits scalar else distinctResult bits scalar (lowerTail bits scalar) (upperTail bits scalar)\n/-- Own complete source bound uses the SAME actual branch's computed word lengths. -/\ndef timeBound (bits scalar : List Bool) : ℕ :=\n  if squareCase bits scalar then squareBound bits scalar else distinctBound bits scalar (lowerTail bits scalar) (upperTail bits scalar)\n/-- Full actual halt specification, with no erased foreign bank or saved return. -/\ndef done (bits scalar : List Bool) : C.State Stack Label := stopped (result bits scalar)\n/-- Actual output bytes are compact in both source branches. -/\ntheorem outputs_compact (bits scalar : List Bool) :\n    Compact ((done bits scalar).data (aux .small)) ∧ Compact ((done bits scalar).data (aux .large)) := by\n  unfold done result\n  split_ifs\n  · exact ⟨SemiprimeD1StackPackedMomentReadoutEncoding.moment_compact bits scalar true,\n      SemiprimeD1StackPackedMomentReadoutEncoding.moment_compact bits scalar true⟩\n  · exact ⟨SemiprimeD1StackReduceExecution.trimReverse_compact _,SemiprimeD1StackReduceExecution.trimReverse_compact _⟩\n/-- Every readout word, including all actual metadata/scalar/count/sum and six empty radix roles, is retained. -/\ntheorem readout_retained (bits scalar : List Bool) (k : R.Stack) :\n    (done bits scalar).data (readout k)=retained bits scalar k := by unfold done result;split_ifs <;> rfl\n/-- The actual TRUE singleton is written only after the real common validation path. -/\ntheorem status_true (bits scalar : List Bool) : (done bits scalar).data (aux .status)=[true] := by\n  unfold done result;split_ifs <;> rfl\n/-- Complete SAME source computes the ordered two factors for EVERY ordered semiprime pair. -/\ntheorem source_ordered (bits scalar : List Bool) (hc : Compact bits) (p q : ℕ)\n    (hp : Nat.Prime p) (hq : Nat.Prime q) (hpq : p≤q) (hN : bitValue bits=p*q)\n    (hscalar : bitValue scalar=SemiprimeD1PackedMomentSemiprime.packedValue (p*q) (Nat.mul_pos hp.pos hq.pos)) :\n    ∃t ≤ timeBound bits scalar,\n      SemiprimeD1StackCalls.run program t (initial bits scalar)=some (done bits scalar) ∧\n      bitValue ((done bits scalar).data (aux .small))=p ∧ bitValue ((done bits scalar).data (aux .large))=q := by\n  have hcount:=O.semiprime_count_bytes bits scalar hc p q hp hq hN hscalar\n  have hsum:=(O.semiprime_values bits scalar hc p q hp hq hN hscalar).2\n  change bitValue (sumWord bits scalar)=(if p=q then p else p+q) at hsum\n  change (retained bits scalar) (R.aux .count)=(if p=q then [true] else [false,true]) at hcount\n  by_cases he:p=q\n  · subst q\n    rw [ite_eq_left rfl] at hcount hsum\n    obtain ⟨t,ht,hr⟩:=square_run bits scalar hcount (by rw [hsum];exact hp.two_le) (by rw [hsum,hN])\n    have hsquare : squareCase bits scalar := hcount\n    refine ⟨t,?_,?_,?_,?_⟩\n    · simpa only [timeBound,ite_eq_left hsquare] using ht\n    · simpa only [done,result,ite_eq_left hsquare] using hr\n    · change bitValue ((if squareCase bits scalar then squareResult bits scalar else _) (aux .small))=p\n      rw [ite_eq_left hsquare]\n      exact hsum\n    · change bitValue ((if squareCase bits scalar then squareResult bits scalar else _) (aux .large))=p\n      rw [ite_eq_left hsquare]\n      exact hsum\n  · rw [ite_eq_right he] at hcount hsum\n    have hsquare : ¬squareCase bits scalar := by\n      intro h\n      have hh:=h.symm.trans hcount\n      cases hh\n    let s:=sumWord bits scalar\n    let root:=rootWord bits s\n    have hd:=discriminant_borrow bits s p q hN hsum\n    have hroot:=rootWord_value bits s p q hN hsum hpq\n    obtain ⟨hm,⟨lo,hlo⟩,hvlo⟩:=minus_exact s root p q hp.pos hpq hsum hroot\n    obtain ⟨⟨hi,hhi⟩,hvhi⟩:=plus_exact s root p q hq.pos hpq hsum hroot\n    have hsmall : bitValue (SemiprimeD1StackReduceExecution.trimReverse lo.reverse)=p := by\n      simpa only [halfWord,hlo,List.tail_cons] using hvlo\n    have hlarge : bitValue (SemiprimeD1StackReduceExecution.trimReverse hi.reverse)=q := by\n      simpa only [halfWord,hhi,List.tail_cons] using hvhi\n    have hlower : lowerTail bits scalar=lo := by change (minusReport s root).result.bits.tail=lo;rw [hlo];rfl\n    have hupper : upperTail bits scalar=hi := by change (plusWord s root).tail=hi;rw [hhi];rfl\n    obtain ⟨t,ht,hr⟩:=distinct_run bits scalar lo hi hcount hd hm hlo hhi\n      (by rw [hsmall];exact hp.two_le) (by rw [hlarge];exact hq.two_le) (by rw [hsmall,hlarge,hN])\n    refine ⟨t,?_,?_,?_,?_⟩\n    · simpa only [timeBound,ite_eq_right hsquare,hlower,hupper] using ht\n    · simpa only [done,result,ite_eq_right hsquare,hlower,hupper] using hr\n    · change bitValue ((if squareCase bits scalar then _ else distinctResult bits scalar (lowerTail bits scalar) (upperTail bits scalar)) (aux .small))=p\n      rw [ite_eq_right hsquare,hlower,hupper]\n      exact hsmall\n    · change bitValue ((if squareCase bits scalar then _ else distinctResult bits scalar (lowerTail bits scalar) (upperTail bits scalar)) (aux .large))=q\n      rw [ite_eq_right hsquare,hlower,hupper]\n      exact hlarge\nend RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryMeaning\n","RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryViews":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryHalves\nimport RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryValidation\n/-! # Clean actual source-cache boundaries, without concrete graph unfolding -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryViews\nopen SemiprimeD1StackPackedFactorRecovery SemiprimeD1StackPackedFactorRecoveryEncoding\n/-- The four real adder words are all physically empty at a clean boundary. -/\ntheorem empty_adder : A.store [] [] [] []=(fun _=>[]) := by funext k;cases k <;> rfl\n/-- The nine real multiplier words are all physically empty at a clean boundary. -/\ntheorem empty_multiply : X.payload [] [] [] [] [] [] [] [] []=(fun _=>[]) := by\n  funext k\n  rcases k with k|k|k\n  · cases k <;> rfl\n  · fin_cases k <;> rfl\n  · cases k <;> rfl\n/-- The five comparison words are all physically empty after consuming the answer. -/\ntheorem empty_compare : W.store [] [] [] [] []=(fun _=>[]) := by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k;rfl\n/-- The standard boundary retains every source cache and exposes all temporary words as EMPTY. -/\ndef clean (r : R.Stack→List Bool) (m : SemiprimeD1StackPackedRootMetadata.Stack→List Bool)\n    (v : SemiprimeD1StackBinarySquareRoot.Aux→List Bool) (u : Aux→List Bool) : Stack→List Bool :=\n  view r m (fun _=>[]) (fun _=>[]) (fun _=>[]) v u\n/-- A wholly unused square-root bank is exactly the physical zero bank. -/\ntheorem clean_zero (r : R.Stack→List Bool) (u : Aux→List Bool) :\n    clean r (fun _=>[]) (fun _=>[]) u=bank r (fun _=>[]) u := by\n  funext k\n  rcases k with k|k|k\n  · rfl\n  · rcases k with k|k|k|k|k <;> rfl\n  · rfl\n/-- The full frozen SQ halt provides the exact acquired clean bank with every metadata word retained. -/\ntheorem squareRoot_clean (r : R.Stack→List Bool) (d : List Bool) (u : Aux→List Bool) :\n    bank r (SemiprimeD1StackBinarySquareRootEncoding.result d) u=\n      clean r (SemiprimeD1StackBinarySquareRootEncoding.retained d [])\n        (SemiprimeD1StackBinarySquareRootEncoding.words [] (SemiprimeD1StackBinarySquareRootArithmetic.output d)) u := rfl\n/-- Both numerator paths have exactly this physically empty arithmetic bank. -/\ntheorem phase_clean (r m root small large) :\n    SemiprimeD1StackPackedFactorRecoveryHalves.phase r m root small large (A.store [] [] [] [])=\n      clean r m (SemiprimeD1StackBinarySquareRootEncoding.words [] root) (words small large [] []) := by\n  rw [SemiprimeD1StackPackedFactorRecoveryHalves.phase,empty_adder]\n  rfl\n/-- The common validation entry has the same complete clean source-cache projection. -/\ntheorem validation_clean (r m v small large) :\n    SemiprimeD1StackPackedFactorRecoveryFactorChecks.work r m v small large\n      (X.payload [] [] [] [] [] [] [] [] []) (W.store [] [] [] [] [])=\n      clean r m v (words small large [] []) := by\n  rw [SemiprimeD1StackPackedFactorRecoveryFactorChecks.work,empty_adder,empty_multiply,empty_compare]\n  rfl\n/-- Common validation success retains every source word and only fills physical status TRUE. -/\ntheorem result_clean (r m v small large) :\n    SemiprimeD1StackPackedFactorRecoveryValidation.result r m v small large=\n      clean r m v (words small large [true] []) := by\n  rw [SemiprimeD1StackPackedFactorRecoveryValidation.result,empty_adder,empty_multiply,empty_compare]\n  rfl\nend RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryViews\n","RiemannGaussian.SemiprimeD1StackPackedRootContextExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedRootContextCalls\n/-! # Complete actual original-N root context source and own bit-time bounds -/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPackedRootContextExecution\nopen SemiprimeD1StackPackedRootContext SemiprimeD1StackPackedRootContextEncoding\nopen SemiprimeD1StackPackedRootContextPrimitives SemiprimeD1StackPackedRootContextCalls\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\n/-- SAME actual metadata-ready continuation pays the copy, literal header,\nentire context source and true final halt, with precision VALUE included. -/\ndef readyBound (bits : List Bool) : ℕ :=\n  (5*(M.precisionWord bits.length).length+4)+1+\n    (SemiprimeD1StackJetContextCorrectness.budget [] (M.precisionWord bits.length)+1)+1\n/-- Whole original-input clock adds the ONE actually executed metadata call. -/\ndef runBound (bits : List Bool) : ℕ :=\n  SemiprimeD1StackPackedRootMetadataExecution.polynomial bits+1+readyBound bits\n/-- Complete acquired-cache path performs the REAL handoff, header seed and\ncontext source, with every metadata word and real caller return preserved. -/\ntheorem ready_trace (bits : List Bool) :\n    ∃t,t+1 ≤ readyBound bits ∧ Runs program t (ctl .copyPrecision) (ready bits).data (ctl .done) (result bits) := by\n  have h0 := copy_call (ready bits).data (M.precisionWord bits.length) [] rfl rfl rfl\n  rw [List.append_nil] at h0\n  change Runs program _ _ _ _ (Function.update (ready bits).data (context J.precisionBits) (M.precisionWord bits.length)) at h0\n  have he0 : Function.update (ready bits).data (context J.precisionBits) (M.precisionWord bits.length)=copied bits := by\n    change Function.update (data (M.result bits) (fun _ => [])) (context J.precisionBits) (M.precisionWord bits.length)=\n      data (M.result bits) (J.initial [] (M.precisionWord bits.length)).data\n    rw [←empty_context,data_context,context_precision]\n  rw [he0] at h0\n  have h1 := axes_seed (copied bits)\n  change Runs program 1 _ _ _ (Function.update (copied bits) (context J.axesCache) [false]) at h1\n  have he1 : Function.update (copied bits) (context J.axesCache) [false]=prepared bits := by\n    unfold copied prepared\n    rw [data_context,context_axes]\n  rw [he1] at h1\n  obtain ⟨t,ht,h2⟩ := context_call (M.result bits) (M.precisionWord bits.length)\n  have h := join (join h0 h1) h2\n  refine ⟨_,?_,h⟩\n  unfold readyBound\n  omega\n/-- Whole N-only path executes the actual metadata source ONCE, then the SAME\nproved cache-ready continuation; no word equality transports a native clock. -/\ntheorem source_trace (bits : List Bool) :\n    ∃t,t+1 ≤ runBound bits ∧ Runs program t (ctl .start) (input bits) (ctl .done) (result bits) := by\n  obtain ⟨tm,hm,h0⟩ := metadata_call bits\n  obtain ⟨tc,hc,h1⟩ := ready_trace bits\n  exact ⟨tm+tc,by unfold runBound;omega,join h0 h1⟩\n/-- Complete source halts with all real outputs, both flags cleared and no extra frame. -/\ntheorem source_run (bits : List Bool) :\n    ∃t ≤ runBound bits,SemiprimeD1StackCalls.run program t (initial bits)=some (done bits) := by\n  obtain ⟨t,ht,h⟩ := source_trace bits\n  obtain ⟨out,he,ha⟩ := h [] (initial bits) ⟨rfl,rfl,rfl⟩\n  have hh := halt_run program (ctl .done) rfl (result bits) [] out ha\n  exact ⟨t+1,ht,by rw [SemiprimeD1StackReturnLink.run_add,he,Option.bind_some];exact hh⟩\n/-- SAME actual metadata-ready continuation also has a clean real halt. -/\ntheorem ready_run (bits : List Bool) :\n    ∃t ≤ readyBound bits,SemiprimeD1StackCalls.run program t (ready bits)=some (done bits) := by\n  obtain ⟨t,ht,h⟩ := ready_trace bits\n  obtain ⟨out,he,ha⟩ := h [] (ready bits) ⟨rfl,rfl,rfl⟩\n  have hh := halt_run program (ctl .done) rfl (result bits) [] out ha\n  exact ⟨t+1,ht,by rw [SemiprimeD1StackReturnLink.run_add,he,Option.bind_some];exact hh⟩\n/-- Fixed whole-source quadratic is chosen before every N. -/\ndef polynomial (bits : List Bool) : ℕ := 2000*(bits.length+1)^2\n/-- Actual cached-metadata reuse needs only a fixed linear clock. -/\ndef readyPolynomial (bits : List Bool) : ℕ := 1000*(bits.length+1)\n/-- All ready operations, including acquired TRUE-width VALUE, have a linear cap. -/\ntheorem readyBound_le (bits : List Bool) : readyBound bits ≤ 62*bits.length+229 := by\n  have h0 := context_budget bits\n  have h1 := SemiprimeD1StackPackedRootMetadataEncoding.precision_length bits.length\n  unfold readyBound\n  omega\n/-- Complete N-only source is quadratic, with neither rank nor width advice. -/\ntheorem runBound_le (bits : List Bool) : runBound bits ≤ polynomial bits := by\n  have h := readyBound_le bits\n  unfold runBound polynomial SemiprimeD1StackPackedRootMetadataExecution.polynomial\n  nlinarith only [h]\n/-- The ready entry's OWN physical bound is linear in original input size. -/\ntheorem readyBound_le_polynomial (bits : List Bool) : readyBound bits ≤ readyPolynomial bits := by\n  have h := readyBound_le bits\n  unfold readyPolynomial\n  omega\n/-- Whole actual source and its OWN fixed quadratic time. -/\ntheorem source_run_bounded (bits : List Bool) :\n    ∃t ≤ polynomial bits,SemiprimeD1StackCalls.run program t (initial bits)=some (done bits) := by\n  obtain ⟨t,ht,h⟩ := source_run bits\n  exact ⟨t,ht.trans (runBound_le bits),h⟩\n/-- SAME program, ACTUALLY acquired metadata cache, and OWN linear time. -/\ntheorem ready_run_bounded (bits : List Bool) :\n    ∃t ≤ readyPolynomial bits,SemiprimeD1StackCalls.run program t (ready bits)=some (done bits) := by\n  obtain ⟨t,ht,h⟩ := ready_run bits\n  exact ⟨t,ht.trans (readyBound_le_polynomial bits),h⟩\nend RiemannGaussian.SemiprimeD1StackPackedRootContextExecution\n","RiemannGaussian.SemiprimeD1StackPackedRootInputPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedRootInputView\n/-! # Real original-input handoff, with its exact preserving-copy trace -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPackedRootInputPrimitives\nopen SemiprimeD1StackPackedRootInput SemiprimeD1StackPackedRootInputEncoding\nopen SemiprimeD1StackProcedureTrace\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Actual component fragments concatenate with all external real return frames retained. -/\ntheorem join {m n : ℕ} {pc mid next : Label} {before between after : Stack→List Bool}\n    (h : Runs program m pc before mid between) (g : Runs program n mid between next after) :\n    Runs program (m+n) pc before next after := runs_trans program m n pc mid next before between after h g\n/-- One literal restoring copy, without an operand getter or supplied context word. -/\ntheorem copy_call (before : Stack→List Bool) (xs ys : List Bool)\n    (hx : before originalInput=xs) (hy : before (contextStack J.originalInput)=ys)\n    (hs : before (rootStack R.copyScratch)=[]) :\n    Runs program (5*xs.length+4) (.local .copyNumber) before (.local .context)\n      (Function.update before (contextStack J.originalInput) (xs++ys)) := by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi : Link.DataRel copyStack before start.store before := by\n    constructor\n    · intro k\n      fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _\n      rfl\n  have ho:=Link.data_update copyStack copy_injective before start.store before hi (1 : Fin 3) (xs++ys)\n  have he : Function.update start.store 1 (xs++ys)=stop.store := by\n    funext k\n    fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program copyStack Label.copy copy_injective SemiprimeD1StackCopy.code 0\n    (fun _ => rfl) (.local .copyNumber) (.local .context) rfl (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\n/-- The actual retained N, actual empty target and actual empty scratch discharge all copy premises. -/\ntheorem copy_N (bits : List Bool) (hN : 0<SemiprimeBitArithmetic.bitValue bits) :\n    Runs program (5*bits.length+4) (.local .copyNumber) (markedReady bits hN)\n      (.local .context) (contextReady bits hN) := by\n  have h:=copy_call (markedReady bits hN) bits [] (marked_N bits hN) rfl (marked_scratch bits hN)\n  simpa only [List.append_nil,contextReady_copy] using h\nend RiemannGaussian.SemiprimeD1StackPackedRootInputPrimitives\n","RiemannGaussian.SemiprimeD1StackPacketModeAcquireCount":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketModeAcquireEncoding\nimport RiemannGaussian.SemiprimeD1StackPacketModeAcquirePrimitives\n/-! # Actual packet fields acquire the real catalogue packet-count operand\nEmpty raw packet keys still have actual vector entries and are counted once.\nEvery field byte, parser-valid pop, payload drain and count push is paid.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketModeAcquireCount\nopen SemiprimeD1StackPacketModeAcquire SemiprimeD1StackPacketModeAcquireEncoding\nopen SemiprimeD1StackPacketModeAcquirePrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\"=>Label.local\n/-- Full actual counting boundary; the natural count only describes physically pushed true markers. -/\ndef words (original order precision reader:List Bool) (count:Nat):Words:=\n  {modes:=M.input (List.replicate count true) [] precision,packets:=original,order:=order,reader:=reader}\n/-- One real vector entry parses and drains its raw field, then pushes exactly one packet marker. -/\ntheorem row_run (original order precision word:List Bool) (rest:List (List Bool)) (count:Nat) :\n    Runs program (9*word.length+11) (ctl .packetTag)\n      (bank (words original order precision (vectorBits (word::rest)) count)) (ctl .packetTag)\n      (bank (words original order precision (vectorBits rest) (count+1))) :=by\n  let w0:=words original order precision (vectorBits (word::rest)) count\n  let w1:=words original order precision (frame word (vectorBits rest)) count\n  have h0:=pop_run .packetTag (ctl .abort) (ctl .packetEnd) (ctl .field) (aux .reader)\n    (bank w0) (true::frame word (vectorBits rest)) rfl rfl\n  simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n  rw [update_reader] at h0\n  have h1:=field_call .field .valid rfl (bank w1) word (vectorBits rest) rfl rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update (Function.update (Function.update (bank w1)\n    (aux .reader) (vectorBits rest)) (aux .payload) word) (aux .valid) [true]) at h1\n  rw [update_reader,update_payload,update_valid] at h1\n  let w2:Words:={w1 with reader:=vectorBits rest,payload:=word,valid:=[true]}\n  have h2:=pop_run .valid (ctl .abort) (ctl .abort) (ctl .clearPayload) (aux .valid)\n    (bank w2) [true] rfl rfl\n  simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h2\n  rw [update_valid] at h2\n  let w3:Words:={w2 with valid:=[]}\n  have h3:=drain_loop .clearPayload (ctl .countPacket) (aux .payload) rfl (bank w3) word rfl\n  rw [update_payload] at h3\n  change Runs program _ _ _ _ (bank (words original order precision (vectorBits rest) count)) at h3\n  have h4:=push_run .countPacket (ctl .packetTag) packetCount true\n    (bank (words original order precision (vectorBits rest) count)) rfl\n  rw [show packetCount=modeStack packetRole from rfl,update_mode] at h4\n  dsimp only [words] at h4\n  rw [input_packet] at h4\n  change Runs program 1 _ _ _ (bank (words original order precision (vectorBits rest) (count+1))) at h4\n  have h:=join (join (join (join h0 h1) h2) h3) h4\n  convert h using 1\n  omega\n/-- The actual final false vector tag and actual EOF peek are both executed. -/\ntheorem nil_run (original order precision:List Bool) (count:Nat) :\n    Runs program 2 (ctl .packetTag) (bank (words original order precision [false] count))\n      (ctl .copyOrder) (bank (words original order precision [] count)) :=by\n  have h0:=pop_run .packetTag (ctl .abort) (ctl .packetEnd) (ctl .field) (aux .reader)\n    (bank (words original order precision [false] count)) [false] rfl rfl\n  simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n  rw [update_reader] at h0\n  have h1:=peek_run .packetEnd (ctl .copyOrder) (ctl .abort) (ctl .abort) (aux .reader)\n    (bank (words original order precision [] count)) [] rfl rfl\n  exact join h0 h1\n/-- Exact actually executed packet-parser loop clock. -/\ndef countTime (packets:List (List Bool)):Nat:=(packets.map (fun word=>9*word.length+11)).sum+2\n/-- Actual complete count loop preserves the original packets/order/WIDTH and acquires the real unary packet count. -/\ntheorem count_run (packets:List (List Bool)) (original order precision:List Bool) (count:Nat) :\n    Runs program (countTime packets) (ctl .packetTag)\n      (bank (words original order precision (vectorBits packets) count)) (ctl .copyOrder)\n      (bank (words original order precision [] (count+packets.length))) :=by\n  induction packets generalizing count with\n  | nil=>simpa only [countTime,vectorBits,List.map_nil,List.sum_nil,List.length_nil,Nat.add_zero,Nat.zero_add] using\n      nil_run original order precision count\n  | cons word packets ih=>\n    have h0:=row_run original order precision word packets count\n    have h1:=ih (count+1)\n    have h:=join h0 h1\n    have he:count+1+packets.length=count+(word::packets).length:=by simp only [List.length_cons];omega\n    rw [he] at h\n    convert h using 1\n    simp only [countTime,List.map_cons,List.sum_cons]\n    omega\n/-- First physical input copy is preserving, and every actual copied vector byte is charged. -/\ntheorem copy_input_run (packets order precision:List Bool) :\n    Runs program (5*packets.length+4) (ctl .start) (initial packets order precision).data\n      (ctl .packetTag) (bank (words packets order precision packets 0)) :=by\n  rw [initial_bank]\n  have h:=copy_call .packets .start .packetTag rfl\n    (bank {modes:=M.input [] [] precision,packets:=packets,order:=order}) packets [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update (bank _ ) (aux .reader) (packets++[])) at h\n  rw [List.append_nil,update_reader] at h\n  exact h\n/-- Packet-vector acquisition and all real parser/count steps form one paid source prefix. -/\ntheorem source_count_run (packets:List (List Bool)) (order precision:List Bool) :\n    Runs program (5*(vectorBits packets).length+4+countTime packets) (ctl .start)\n      (initial (vectorBits packets) order precision).data (ctl .copyOrder)\n      (bank (words (vectorBits packets) order precision [] packets.length)) :=by\n  have h0:=copy_input_run (vectorBits packets) order precision\n  have h1:=count_run packets (vectorBits packets) order precision 0\n  simpa only [Nat.zero_add] using join h0 h1\nend RiemannGaussian.SemiprimeD1StackPacketModeAcquireCount\n","RiemannGaussian.SemiprimeD1StackPacketRowsLog":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketRowsRowView\nimport RiemannGaussian.SemiprimeD1StackPacketRowsEncoding\n/-! # One actual colour field parse and chronological reverse-row log\nThe field's physical false delimiter is read even for colour zero. Every field,\nvalid byte, row tag, preserving Frame, reversal and temporary-colour erase is\npaid; no native append/reversal or supplied coefficient field is executed.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketRowsLog\nopen SemiprimeD1StackPacketRows SemiprimeD1StackPacketRowsPrimitives SemiprimeD1StackPacketRowsRowView\nopen SemiprimeD1StackPacketRowsEncoding (row)\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\" => Label.local\n/-- A complete real colour-field source step, including its actual word cleanup and byte-order-correct row log. -/\ntheorem colour_run (side:Bool) (key catalogue:List Bool) (streams histories outputs:Bool→List Bool)\n    (word tail:List Bool) (hi:streams side=frame word tail) :\n    Runs program (19*word.length+20) (ctl (.parseColour side))\n      (rowView key catalogue streams (fun _=>[]) histories outputs [])\n      (ctl (if side then .leftEOF else .parseColour true))\n      (rowView key catalogue (Function.update streams side tail) (fun _=>[])\n        (Function.update histories side ((row word).reverse++histories side)) outputs []) :=by\n  let rest:=Function.update streams side tail\n  let words:=Function.update (fun _ :Bool=>[]) side word\n  let tagged:=Function.update histories side (true::histories side)\n  have hinput:rowView key catalogue streams (fun _=>[]) histories outputs []\n      (fieldStack (.colour side) (.inl .input))=frame word tail:=by\n    exact (stream_get key catalogue streams (fun _=>[]) histories outputs [] side).trans hi\n  have hout:rowView key catalogue streams (fun _=>[]) histories outputs []\n      (fieldStack (.colour side) (.inl .output))=[]:=by cases side <;> rfl\n  have h0:=field_valid (.colour side) (.parseColour side) (.colourValid side) (ctl (.tagHistory side)) rfl rfl\n    (rowView key catalogue streams (fun _=>[]) histories outputs []) word tail hinput hout rfl rfl\n  change Runs program _ _ _ _ (Function.update (Function.update\n    (rowView key catalogue streams (fun _=>[]) histories outputs []) (rowBytes side) tail) (colourWord side) word) at h0\n  rw [update_streams,update_words] at h0\n  have h1:=push_run (.tagHistory side) (ctl (.frameColour side)) (history side) true\n    (rowView key catalogue rest words histories outputs []) rfl\n  rw [history_get] at h1\n  change Runs program 1 _ _ _ (Function.update (rowView key catalogue rest words histories outputs [])\n    (history side) (true::histories side)) at h1\n  rw [update_histories] at h1\n  have hw:rowView key catalogue rest words tagged outputs [] (frameStack side 0)=word:=by cases side <;> rfl\n  have h2:=frame_call side (.frameColour side) (.reverseColour side) rfl\n    (rowView key catalogue rest words tagged outputs []) word [] hw rfl rfl\n  change Runs program _ _ _ _ (Function.update (rowView key catalogue rest words tagged outputs []) frameBuffer (frame word [])) at h2\n  rw [update_buffer] at h2\n  have hy:rowView key catalogue rest words tagged outputs (frame word []) (reverseStack (.colour side) 1)=\n      true::histories side:=by cases side <;> rfl\n  have h3:=reverse_call (.colour side) (.reverseColour side) (.clearColour side) rfl\n    (rowView key catalogue rest words tagged outputs (frame word [])) (frame word []) (true::histories side) rfl hy\n  change Runs program _ _ _ _ (Function.update (Function.update\n    (rowView key catalogue rest words tagged outputs (frame word [])) frameBuffer []) (history side)\n      ((frame word []).reverse++(true::histories side))) at h3\n  rw [update_buffer,update_histories] at h3\n  have he:Function.update tagged side ((frame word []).reverse++(true::histories side))=\n      Function.update histories side ((row word).reverse++histories side):=by\n    dsimp only [tagged]\n    rw [Function.update_idem]\n    congr 1\n    simp only [row,List.reverse_cons,List.append_assoc,List.singleton_append]\n  rw [he] at h3\n  have h4:=drain_loop (.clearColour side) (ctl (if side then .leftEOF else .parseColour true)) (colourWord side) rfl\n    (rowView key catalogue rest words (Function.update histories side ((row word).reverse++histories side)) outputs []) word\n    (by cases side <;> rfl)\n  rw [update_words] at h4\n  have hz:Function.update words side []=(fun _ :Bool=>[]) :=by\n    dsimp only [words]\n    rw [Function.update_idem]\n    exact Function.update_eq_self side (fun _ :Bool=>[])\n  rw [hz] at h4\n  have h:=join (join (join (join h0 h1) h2) h3) h4\n  have ht:(8*word.length+8)+1+(6*word.length+5)+(2*(frame word []).length+3)+(word.length+1)=\n      19*word.length+20:=by\n    rw [SemiprimeSourceHistogramKeyBits.frame_length]\n    simp only [List.length_nil]\n    omega\n  simpa only [ht] using h\nend RiemannGaussian.SemiprimeD1StackPacketRowsLog\n","RiemannGaussian.SemiprimeD1StackPhaseCacheFreshOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseCacheFreshBounds\n/-! # Exact original fresh generator from actual serialized phase-cache bytes\nThe caller supplies physical allocator/header words only. These proofs identify\nthe actual selected record as a stopped P48 cache and conclude exact original\nfresh coefficient/context output on the SAME literal restore→Fresh program.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPhaseCacheFreshOriginal\nopen SemiprimeD1StackPhaseCacheFresh SemiprimeD1StackPhaseCacheFreshComponents\nopen SemiprimeD1StackPhaseCacheFreshExecution\nopen SemiprimeBitArithmetic\nnamespace Old\nexport SemiprimeD1StackPhaseChildContextFreshOriginal (freshWords output_original one_axis_zero rejected_output output_phase_original)\nexport SemiprimeD1StackPhaseChildContextArithmetic (good)\nend Old\n/-- All85 actually USED Fresh role projections equal the exact actual frozen ready-source result. -/\ntheorem fresh_result (banks:List (P.Stack→List Bool)) (i:Fin banks.length)\n    (a u edges:Nat) (t p:List Bool) (axes:List Nat) (k:F.Stack) :\n    (done banks i a u edges t p axes).data (freshStack k)=\n      SemiprimeD1StackPhaseChildContextFreshComponents.result a u edges t p axes k :=fresh_data _ _ k\n/-- The restored complete48-role phase bank is retained, with no extra physical cache copy. -/\ntheorem phase_retained (banks:List (P.Stack→List Bool)) (i:Fin banks.length)\n    (a u edges:Nat) (t p:List Bool) (axes:List Nat) (hbank:banks[i.val]=phase a u edges t p) (k:P.Stack) :\n    (done banks i a u edges t p axes).data (restoreStack (R.phaseStack k))=banks[i.val] k :=by\n  rw [hbank]\n  rfl\n/-- Every actual heap/count/reference word survives, and ALL10reader work/output/flags are clear. -/\ntheorem heap_retained (banks:List (P.Stack→List Bool)) (i:Fin banks.length)\n    (a u edges:Nat) (t p:List Bool) (axes:List Nat) (k:Heap.Stack) :\n    (done banks i a u edges t p axes).data (restoreStack (R.heapStack k))=\n      Heap.input (heap banks) (List.replicate banks.length true) (List.replicate i.val true) k :=rfl\n/-- ALL48allocated private P48 shadow words remain EMPTY; the actualbank is directly shared. -/\ntheorem shadows_empty (banks:List (P.Stack→List Bool)) (i:Fin banks.length)\n    (a u edges:Nat) (t p:List Bool) (axes:List Nat) (k:P.Stack) :\n    (done banks i a u edges t p axes).data (.inr (F.contextStack (H.phaseStack k)))=[] :=rfl\n/-- Entire original acquireFresh coefficient vector and codec, not merely a context header. -/\ntheorem output_original (banks:List (P.Stack→List Bool)) (i:Fin banks.length)\n    (a u edges:Nat) (t p:List Bool) (axes:List Nat) (hg:Old.good a u edges t=true) :\n    (done banks i a u edges t p axes).data output=\n      SemiprimeD1TensorTapeCodec.vectorBits (Old.freshWords a u edges t p axes) :=by\n  rw [show output=freshStack (F.aux .output) from rfl,fresh_result]\n  exact Old.output_original a u edges t p axes hg\n/-- Exact q=1 edge case physically emits oldrank zero coefficients and no out-of-range unit. -/\ntheorem one_axis_zero (banks:List (P.Stack→List Bool)) (i:Fin banks.length)\n    (a u edges:Nat) (t p:List Bool) (axes:List Nat) (hg:Old.good a u edges t=true)\n    (hq:SemiprimeD1StackPhaseChildContextPrimitives.count a u edges t=1) :\n    (done banks i a u edges t p axes).data output=\n      SemiprimeD1TensorTapeCodec.vectorBits (List.replicate axes.prod []) :=by\n  rw [show output=freshStack (F.aux .output) from rfl,fresh_result]\n  exact Old.one_axis_zero a u edges t p axes hg hq\n/-- Precision-zero scalar reduction is exact: every actual coefficient word is EMPTY. -/\ntheorem precision_zero (banks:List (P.Stack→List Bool)) (i:Fin banks.length)\n    (a u edges:Nat) (t p:List Bool) (axes:List Nat) (hg:Old.good a u edges t=true)\n    (hP:bitValue (SemiprimeD1StackPhaseChildContextPrimitives.precision a u edges t p)=0) :\n    (done banks i a u edges t p axes).data output=\n      SemiprimeD1TensorTapeCodec.vectorBits\n        (List.replicate (SemiprimeD1StackPhaseChildContextFreshComponents.rank a u edges t axes) []) :=by\n  rw [output_original banks i a u edges t p axes hg]\n  unfold Old.freshWords\n  rw [hP]\n  simp only [SemiprimeD1FreshJetBits.acquireFresh,show (SemiprimeD1JetScalarBits.reduce 0 [true]).bits=[] from rfl,\n    ite_self,List.map_const',List.length_range]\n  rfl\n/-- Physical verdict/q rejection produces an EMPTY vector and no fresh allocation/context work. -/\ntheorem rejected_output (banks:List (P.Stack→List Bool)) (i:Fin banks.length)\n    (a u edges:Nat) (t p:List Bool) (axes:List Nat) (hg:Old.good a u edges t=false) :\n    (done banks i a u edges t p axes).data output=[] :=by\n  rw [show output=freshStack (F.aux .output) from rfl,fresh_result]\n  exact Old.rejected_output a u edges t p axes hg\n/-- All actual context/header/rank/P48/original-binary-precision caches are retained identically. -/\ntheorem context_retained (banks:List (P.Stack→List Bool)) (i:Fin banks.length)\n    (a u edges:Nat) (t p:List Bool) (axes:List Nat) (k:H.Stack) :\n    (done banks i a u edges t p axes).data (freshStack (F.contextStack k))=\n      SemiprimeD1StackPhaseChildContextFreshComponents.cache a u edges t p axes k :=by\n  rw [fresh_result]\n  rfl\n/-- Exact original workingPrecision/orderFuel/q family on the complete same-program vector output. -/\ntheorem output_phase_original (banks:List (P.Stack→List Bool)) (i:Fin banks.length)\n    (a u edges:Nat) (t p:List Bool) (axes:List Nat) (ht:bitValue t<2^(a+1)) (hu:u≤ edges)\n    (h:SemiprimeD1StackPhaseGeometryGuardOriginal.originalGuard a u t) :\n    (done banks i a u edges t p axes).data output=SemiprimeD1TensorTapeCodec.vectorBits\n      (SemiprimeD1FreshJetBits.acquireFresh (SemiprimeD1StackPhaseChildContextOriginal.oldContext axes p)\n        (SemiprimeD1ModeRate.jetHeight edges u*(u-SemiprimeD1StackPhaseWorkingPrecisionOriginal.originalOrder a t))\n        (SemiprimeD1ModeRate.workingPrecision edges u a (SemiprimeD1StackPhaseWorkingPrecisionOriginal.originalOrder a t) (bitValue p))).words :=by\n  rw [show output=freshStack (F.aux .output) from rfl,fresh_result]\n  exact Old.output_phase_original a u edges t p axes ht hu h\n/-- Full SAME actual consumer starts with heap/count/reference/header ONLY and emits the entire fresh vector. -/\ntheorem source_run_original (banks:List (P.Stack→List Bool)) (i:Fin banks.length)\n    (a u edges:Nat) (t p:List Bool) (axes:List Nat) (hp:∀x∈axes,0<x)\n    (hbank:banks[i.val]=phase a u edges t p) (hg:Old.good a u edges t=true) :\n    ∃q≤ 1000000000000*(SemiprimeD1StackPhaseCacheFreshBounds.resource banks i a u edges t p axes+1)^2,\n      SemiprimeD1StackCalls.run program q (source banks i axes)=some (done banks i a u edges t p axes) ∧\n      (done banks i a u edges t p axes).data output=SemiprimeD1TensorTapeCodec.vectorBits (Old.freshWords a u edges t p axes) ∧\n      (∀k,(done banks i a u edges t p axes).data (restoreStack (R.phaseStack k))=banks[i.val] k) ∧\n      (∀k,(done banks i a u edges t p axes).data (.inr (F.contextStack (H.phaseStack k)))=[]) :=by\n  obtain ⟨q,hq,hr⟩:=source_run banks i a u edges t p axes hp hbank\n  exact ⟨q,hq.trans (SemiprimeD1StackPhaseCacheFreshBounds.run_polynomial banks i a u edges t p axes hp),hr,\n    output_original banks i a u edges t p axes hg,phase_retained banks i a u edges t p axes hbank,fun _=>rfl⟩\nend RiemannGaussian.SemiprimeD1StackPhaseCacheFreshOriginal\n","RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionMetadataStages":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionMetadataProducts\n/-! # Complete physically acquired h/q/r/delta phase metadata, without binary-P advice -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2200000\nnamespace RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionMetadataStages\nopen SemiprimeD1StackPhaseWorkingPrecisionMetadata SemiprimeD1StackPhaseWorkingPrecisionMetadataPrimitives\nopen SemiprimeD1StackPhaseWorkingPrecisionMetadataArithmetic SemiprimeD1StackPhaseWorkingPrecisionMetadataProducts\nopen SemiprimeD1StackProcedureTrace\n/-- Complete bounded metadata for the NEXT actual binary shift/add stage. -/\ndef completed (a u M : Nat) (t : List Bool) : Counts :=\n  {height:=height M u,q:=blocks a u M t,r:=M*(a+1),delta:=a-order a t}\n/-- Actual q/r/delta program uses only the acquired h/i cache and original a/u/M. -/\ntheorem source_run (a u M : Nat) (t p : List Bool) (ha : order a t<a) (hu : order a t<u) :\n    ∃q≤1000*(M+a+u+1)^2,Runs program q .qCopyU\n      (context a u M t p (SemiprimeD1StackPhaseWorkingPrecisionMetadataHeight.heightCounts M u))\n      .done (context a u M t p (completed a u M t)) :=by\n  let c0:=SemiprimeD1StackPhaseWorkingPrecisionMetadataHeight.heightCounts M u\n  have h0:=copy_context a u M t p 3 c0 .qCopyU (.subtractCopy false) rfl\n  change Runs program (5*u+4) _ _ _ (context a u M t p (subCounts false c0 u 0)) at h0\n  have h1:=copy_subtract false a u M t p c0 u hu.le\n  let c1:=subCounts false c0 (u-order a t) 0\n  have h2:=copy_context a u M t p 5 c1 .qCopyH (.product false) rfl\n  let c2:Counts:={c1 with multiplier:=height M u}\n  change Runs program (5*height M u+4) _ _ _ (context a u M t p c2) at h2\n  obtain ⟨b,hb,h3⟩:=product_run false a u M t p c2 rfl\n  let c3:=productCounts false c2\n  have h4:=clear_multiplicity false a u M t p c3\n  let c4:Counts:={c3 with multiplicand:=0}\n  have h5:=copy_context a u M t p 6 c4 .rCopyM .rCopyA rfl\n  let c5:Counts:={c4 with multiplier:=M}\n  change Runs program (5*M+4) _ _ _ (context a u M t p c5) at h5\n  have h6:=copy_context a u M t p 7 c5 .rCopyA .plusOne rfl\n  let c6:Counts:={c5 with multiplicand:=a}\n  change Runs program (5*a+4) _ _ _ (context a u M t p c6) at h6\n  have h7:=plus_one a u M t p c6\n  let c7:Counts:={c6 with multiplicand:=a+1}\n  obtain ⟨d,hd,h8⟩:=product_run true a u M t p c7 rfl\n  let c8:=productCounts true c7\n  have h9:=clear_multiplicity true a u M t p c8\n  let c9:Counts:={c8 with multiplicand:=0}\n  have h10:=copy_context a u M t p 8 c9 .deltaCopyA (.subtractCopy true) rfl\n  change Runs program (5*a+4) _ _ _ (context a u M t p (subCounts true c9 a 0)) at h10\n  have h11:=copy_subtract true a u M t p c9 a ha.le\n  have hh:=join (join (join (join (join (join (join (join (join (join (join h0 h1) h2) h3) h4) h5) h6) h7) h8) h9) h10) h11\n  change Runs program ((5*u+4)+(7*order a t+5)+(5*height M u+4)+b+\n    (u-order a t+1)+(5*M+4)+(5*a+4)+1+d+(a+1+1)+(5*a+4)+(7*order a t+5))\n    .qCopyU _ .done (context a u M t p (completed a u M t)) at hh\n  refine ⟨_,?_,hh⟩\n  change b≤5*(height M u*(2*(u-order a t)+3)+1)+1 at hb\n  change d≤5*(M*(2*(a+1)+3)+1)+1 at hd\n  let I:=M+a+u+1\n  have hI:1≤ I:=by dsimp [I];omega\n  have hM:M≤ I:=by dsimp [I];omega\n  have haI:a≤ I:=by dsimp [I];omega\n  have huI:u≤ I:=by dsimp [I];omega\n  have hiI:order a t≤ I:=ha.le.trans haI\n  have hHeight:height M u≤4*I:=by have h:=height_le M u;dsimp [I];omega\n  have hpart:2*(u-order a t)+3≤5*I:=by omega\n  have hprod:height M u*(2*(u-order a t)+3)≤20*I^2:=by\n    calc\n      _≤(4*I)*(5*I):=Nat.mul_le_mul hHeight hpart\n      _=_:=by ring\n  have hpart2:2*(a+1)+3≤7*I:=by omega\n  have hprod2:M*(2*(a+1)+3)≤7*I^2:=by\n    calc\n      _≤ I*(7*I):=Nat.mul_le_mul hM hpart2\n      _=_:=by ring\n  have hb':b≤100*I^2+6:=by omega\n  have hd':d≤35*I^2+6:=by omega\n  have hsq:I≤ I^2:=by nlinarith\n  change _≤1000*I^2\n  omega\nend RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionMetadataStages\n","RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionBounds\n/-! # Exact original BINARY workingPrecision and D on the actual whole source\nOriginal a/u/M and BINARY t/p alone initialize the program. The acquired h/q,\norder/guard/cache, BINARY D and BINARY precision are all retained literally.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionOriginal\nopen SemiprimeD1StackPhaseWorkingPrecision SemiprimeD1StackPhaseWorkingPrecisionArithmetic\nopen SemiprimeD1StackPhaseWorkingPrecisionComponents SemiprimeD1StackPhaseWorkingPrecisionExecution\nopen SemiprimeBitArithmetic\nnamespace Old\nexport SemiprimeD1StackPhaseGeometryGuardOriginal (originalGuard accepted_true order_original)\nend Old\n/-- Exact original acquired i from the original finite-fuel recovery loop. -/\ndef originalOrder (a : Nat) (t : List Bool) : Nat :=\n  (SemiprimeD1RecoveryScalarRun.orderFuel (SemiprimeD1RecoveryWeightRun.geometry a (bitValue t)).size\n    (SemiprimeD1RecoveryWeightRun.geometry a (bitValue t)).point.natAbs).value\n/-- ENTIRE actual37-role metadata/geometry/guard bank survives EVERY binary operation. -/\ntheorem metadata_retained (a u edges : Nat) (t p : List Bool) (j : M.Stack) :\n    result a u edges t p (metadataStack j)=old a u edges t p j :=rfl\n/-- Original arbitrary-precision p is retained as the IDENTICAL BINARY input word. -/\ntheorem original_precision_retained (a u edges : Nat) (t p : List Bool) :\n    result a u edges t p (metadataStack (M.aux .precision))=p :=rfl\n/-- Exact physical branch agrees with the original whole phase's conjunction. -/\ntheorem accepted_original (a u : Nat) (t : List Bool) (ht : bitValue t<2^(a+1)) :\n    accepted a u t=true ↔ Old.originalGuard a u t :=Old.accepted_true a u t ht\n/-- Exact acquired i agrees with original orderFuel on EVERY original grid word. -/\ntheorem order_original (a : Nat) (t : List Bool) (ht : bitValue t<2^(a+1)) :\n    order a t=originalOrder a t :=Old.order_original a t ht\n/-- Exact BINARY D=2^(a-i), with NO numeric power-to-unary conversion. -/\ntheorem power_original (a u edges : Nat) (t p : List Bool) (ht : bitValue t<2^(a+1))\n    (h : Old.originalGuard a u t) :\n    bitValue (result a u edges t p (aux .power))=2^(a-originalOrder a t) :=by\n  have hacc:accepted a u t=true:=(accepted_original a u t ht).mpr h\n  simp only [result,hacc,ite_true]\n  change bitValue (shift (delta a t) [true])=_\n  have ho:=order_original a t ht\n  have hd:delta a t=a-originalOrder a t:=by unfold delta;rw [ho]\n  calc\n    _=2^(delta a t)*1:=shift_value (delta a t) [true]\n    _=2^(delta a t):=Nat.mul_one _\n    _=_:=by rw [hd]\n/-- Exact original workingPrecision from the WHOLE real binary shift/add source.\nP and original p NEVER become unary numerical precision counters. -/\ntheorem precision_original (a u edges : Nat) (t p : List Bool) (ht : bitValue t<2^(a+1))\n    (h : Old.originalGuard a u t) :\n    bitValue (result a u edges t p (aux .output))=\n      SemiprimeD1ModeRate.workingPrecision edges u a (originalOrder a t) (bitValue p) :=by\n  have hacc:accepted a u t=true:=(accepted_original a u t ht).mpr h\n  simp only [result,hacc,ite_true]\n  change bitValue (precisionWord (height edges u) (product a edges) (delta a t) p)=_\n  rw [precisionWord_value]\n  have ho:=order_original a t ht\n  change bitValue p+8*SemiprimeD1ModeRate.jetHeight edges u*2^(a-order a t)+8*(edges*(a+1))=\n    bitValue p+8*SemiprimeD1ModeRate.jetHeight edges u*2^(a-originalOrder a t)+8*edges*(a+1)\n  rw [ho,Nat.mul_assoc 8 edges (a+1)]\n/-- Exact original acquired height remains physically present after the binary P source. -/\ntheorem height_retained (a u edges : Nat) (t p : List Bool) (ht : bitValue t<2^(a+1))\n    (h : Old.originalGuard a u t) :\n    result a u edges t p (metadataStack (M.divStack .quotient))=\n      List.replicate (SemiprimeD1ModeRate.jetHeight edges u) true :=\n  SemiprimeD1StackPhaseWorkingPrecisionMetadataOriginal.height_original_word a u edges t p ht h\n/-- Exact original q=h*(u-i) remains physically present with the BINARY P/D outputs. -/\ntheorem blocks_retained (a u edges : Nat) (t p : List Bool) (ht : bitValue t<2^(a+1))\n    (h : Old.originalGuard a u t) :\n    result a u edges t p (metadataStack (M.aux .q))=\n      List.replicate (SemiprimeD1ModeRate.jetHeight edges u*(u-originalOrder a t)) true :=\n  SemiprimeD1StackPhaseWorkingPrecisionMetadataOriginal.blocks_original_word a u edges t p ht h\n/-- Original rejected phase leaves NEW binary P/D empty, without any conversion/adder stage. -/\ntheorem rejected_outputs (a u edges : Nat) (t p : List Bool) (ht : bitValue t<2^(a+1))\n    (h : ¬Old.originalGuard a u t) :\n    result a u edges t p (aux .output)=[] ∧ result a u edges t p (aux .power)=[] :=by\n  have hacc:accepted a u t=false:=Bool.eq_false_of_not_eq_true (by intro hh;exact h ((accepted_original a u t ht).mp hh))\n  simp only [result,hacc,Bool.false_eq_true,ite_false]\n  exact ⟨rfl,rfl⟩\n/-- Every binary accumulator, counter, copy, allocation and shift work word is physically clear. -/\ntheorem binary_work_clear (a u edges : Nat) (t p : List Bool) :\n    result a u edges t p (aux .left)=[] ∧ result a u edges t p (aux .right)=[] ∧\n    result a u edges t p (aux .scratch)=[] ∧ result a u edges t p (aux .counter)=[] ∧\n    result a u edges t p (aux .next)=[] ∧ result a u edges t p (aux .todo)=[] ∧\n    result a u edges t p (aux .zeroTodo)=[] ∧ result a u edges t p (aux .shiftTodo)=[] ∧\n    result a u edges t p (aux .copyScratch)=[] :=⟨rfl,rfl,rfl,rfl,rfl,rfl,rfl,rfl,rfl⟩\n/-- SAME actual whole source and exact original P/D/h/q hold together for ALL original active nodes. -/\ntheorem source_run_original (a u edges : Nat) (t p : List Bool) (ht : bitValue t<2^(a+1))\n    (h : Old.originalGuard a u t) :\n    ∃q≤1000000000000*(edges+a+u+t.length+p.length+1)^4,\n      SemiprimeD1StackCalls.run program q (initial a u edges t p)=some (done a u edges t p) ∧\n      bitValue ((done a u edges t p).data (aux .output))=\n        SemiprimeD1ModeRate.workingPrecision edges u a (originalOrder a t) (bitValue p) ∧\n      bitValue ((done a u edges t p).data (aux .power))=2^(a-originalOrder a t) ∧\n      (done a u edges t p).data (metadataStack (M.divStack .quotient))=\n        List.replicate (SemiprimeD1ModeRate.jetHeight edges u) true ∧\n      (done a u edges t p).data (metadataStack (M.aux .q))=\n        List.replicate (SemiprimeD1ModeRate.jetHeight edges u*(u-originalOrder a t)) true :=by\n  obtain ⟨q,hq,hr⟩:=source_run a u edges t p\n  exact ⟨q,hq,hr,precision_original a u edges t p ht h,power_original a u edges t p ht h,\n    height_retained a u edges t p ht h,blocks_retained a u edges t p ht h⟩\n/-- SAME whole source also closes every original rejected phase with EMPTY new outputs. -/\ntheorem source_run_rejected (a u edges : Nat) (t p : List Bool) (ht : bitValue t<2^(a+1))\n    (h : ¬Old.originalGuard a u t) :\n    ∃q≤1000000000000*(edges+a+u+t.length+p.length+1)^4,\n      SemiprimeD1StackCalls.run program q (initial a u edges t p)=some (done a u edges t p) ∧\n      (done a u edges t p).data (aux .output)=[] ∧ (done a u edges t p).data (aux .power)=[] :=by\n  obtain ⟨q,hq,hr⟩:=source_run a u edges t p\n  exact ⟨q,hq,hr,(rejected_outputs a u edges t p ht h).1,(rejected_outputs a u edges t p ht h).2⟩\nend RiemannGaussian.SemiprimeD1StackPhaseWorkingPrecisionOriginal\n","RiemannGaussian.SemiprimeD1StackPortCataloguePolynomial":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortCatalogueExecution\nimport RiemannGaussian.SemiprimeD1StackPortCatalogueLoopBounds\n/-! # Uniform fixed-polynomial control bounds from actual original descriptors -/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPortCataloguePolynomial\nopen SemiprimeD1StackPortCatalogueTransduction SemiprimeD1StackPortCatalogueLoop\nopen SemiprimeD1StackPortCatalogueLoopBounds\nopen SemiprimeD1EdgeCatalogueEncoding (Record vertex tape)\nopen SemiprimeD1StackEdgeCatalogueParse (wordMass)\nopen SemiprimeMacroGraph\n/-- Actual parsed index together with the four retained source counters. -/\ndef dimension {r t digits:ℕ} (v:SubdividedVertex r t digits) : ℕ :=\n  SemiprimeD1StackVertexArityOriginal.indexValue v+(r*t+1)+r+t+digits+1\n/-- A finite descriptor cap, only used internally before actual original-input substitution. -/\ndef Bounded {r t digits:ℕ} (X:ℕ) (vs:List (SubdividedVertex r t digits)) : Prop :=\n  ∀v∈vs,wordMass (vertex v)≤X ∧ dimension v≤X\n/-- Actual arity is a consequence of the original parsed dimensions. -/\ntheorem arity_le {r t digits:ℕ} (v:SubdividedVertex r t digits) (X:ℕ) (hd:dimension v≤X) :\n    subdividedArity v≤10*X^2 := by\n  exact (original_arity_le v).trans (Nat.mul_le_mul_left 10 (Nat.pow_le_pow_left hd 2))\n/-- Pure scalar bound for the actual retained per-record clock expression. -/\ntheorem recordTime_le {r t digits:ℕ} (v:SubdividedVertex r t digits) (X n f:ℕ)\n    (hX:1≤X) (hm:wordMass (vertex v)≤X) (hd:dimension v≤X)\n    (hn:n≤10*X^3) (hf:f≤X) :\n    SemiprimeD1StackPortCatalogueScan.recordTime v n f≤10000*X^5 := by\n  have ha:=arity_le v X hd\n  have hl:=loopTime_le (vertex v) (subdividedArity v) n f 0\n  have h2:X≤X^2:=Nat.le_pow (by omega)\n  have h3:X^2≤X^3:=Nat.pow_le_pow_right hX (by omega)\n  have h5:X^3≤X^5:=Nat.pow_le_pow_right hX (by omega)\n  have hq:10*(n+f+0+2*subdividedArity v+wordMass (vertex v))+83≤403*X^3:=by\n    nlinarith\n  have hmul:subdividedArity v*(10*(n+f+0+2*subdividedArity v+wordMass (vertex v))+83)≤\n      (10*X^2)*(403*X^3):=Nat.mul_le_mul ha hq\n  have hr:SemiprimeD1StackVertexArityRecipes.recipeBudget\n      (SemiprimeD1StackVertexArityOriginal.indexValue v) (r*t+1) r t digits≤100*X^2+100:=by\n    unfold SemiprimeD1StackVertexArityRecipes.recipeBudget SemiprimeD1StackVertexArityRecipes.dimensionSum\n    exact Nat.add_le_add_right (Nat.mul_le_mul_left 100 (Nat.pow_le_pow_left hd 2)) 100\n  unfold SemiprimeD1StackPortCatalogueScan.recordTime\n  nlinarith\n/-- Every original parsed word mass is bounded by the actual acquired descriptor tape. -/\ntheorem mass_mem {r t digits:ℕ} (vs:List (SubdividedVertex r t digits))\n    (v:SubdividedVertex r t digits) (hv:v∈vs) :\n    wordMass (vertex v)≤(tape (vs.map vertex) []).length := by\n  induction vs with\n  | nil => simp at hv\n  | cons w vs ih =>\n    simp only [List.mem_cons] at hv\n    change wordMass (vertex v)≤(SemiprimeD1EdgeCatalogueEncoding.record (vertex w) (tape (vs.map vertex) [])).length\n    rw [SemiprimeD1StackEdgeCatalogueScan.record_length]\n    rcases hv with he|hv\n    · subst w;omega\n    · have h:=ih hv;omega\n/-- Every original factor occupies at least its five delimiters on the actual source tape. -/\ntheorem vertices_le_tape {r t digits:ℕ} (vs:List (SubdividedVertex r t digits)) :\n    vs.length≤(tape (vs.map vertex) []).length := by\n  induction vs with\n  | nil => simp [tape]\n  | cons v vs ih =>\n    change vs.length+1≤(SemiprimeD1EdgeCatalogueEncoding.record (vertex v) (tape (vs.map vertex) [])).length\n    rw [SemiprimeD1StackEdgeCatalogueScan.record_length]\n    omega\n/-- Actual parsed index is one of the five physically stored words. -/\ntheorem index_le_mass {r t digits:ℕ} (v:SubdividedVertex r t digits) :\n    SemiprimeD1StackVertexArityOriginal.indexValue v≤wordMass (vertex v) := by\n  unfold SemiprimeD1StackVertexArityOriginal.indexValue wordMass\n  omega\n/-- One concrete original dimension/tape size controls every actual parsed descriptor. -/\ndef size {r t digits:ℕ} (vs:List (SubdividedVertex r t digits)) : ℕ :=\n  (tape (vs.map vertex) []).length+(r*t+1)+r+t+digits+1\n/-- The original acquired source proves the descriptor invariant, rather than asking for it. -/\ntheorem original_bounded {r t digits:ℕ} (vs:List (SubdividedVertex r t digits)) : Bounded (size vs) vs := by\n  intro v hv\n  have hm:=mass_mem vs v hv\n  have hi:=index_le_mass v\n  constructor\n  · unfold size;omega\n  · unfold dimension size;omega\n/-- All actual occurrence counts have the fixed-polynomial bound derived from the parsed descriptors. -/\ntheorem count_le {r t digits:ℕ} (vs:List (SubdividedVertex r t digits)) (X:ℕ)\n    (hb:Bounded X vs) : count vs≤vs.length*(10*X^2) := by\n  induction vs with\n  | nil => simp [count]\n  | cons v vs ih =>\n    have ha:=arity_le v X (hb v (by simp)).2\n    have hr:=ih (by intro w hw;exact hb w (by simp [hw]))\n    simp only [count,List.map_cons,List.sum_cons,List.length_cons] at *\n    nlinarith\n/-- Whole actual scan time, uniformly for all reached factor/occurrence counters. -/\ntheorem scanTime_le {r t digits:ℕ} (vs:List (SubdividedVertex r t digits)) (X f n:ℕ)\n    (hX:1≤X) (hb:Bounded X vs) (hf:f+vs.length≤X) (hn:n+count vs≤10*X^3) :\n    scanTime vs f n≤vs.length*(10000*X^5) := by\n  induction vs generalizing f n with\n  | nil => simp [scanTime]\n  | cons v vs ih =>\n    have hv:=hb v (by simp)\n    have h0:=recordTime_le v X n f hX hv.1 hv.2 (by omega) (by simp only [List.length_cons] at hf;omega)\n    have hbn:Bounded X vs:=by intro w hw;exact hb w (by simp [hw])\n    have hfn:f+1+vs.length≤X:=by simp only [List.length_cons] at hf;omega\n    have hnn:n+subdividedArity v+count vs≤10*X^3:=by\n      simpa only [count,List.map_cons,List.sum_cons,Nat.add_assoc] using hn\n    have hr:=ih (f+1) (n+subdividedArity v) hbn hfn hnn\n    simp only [scanTime,List.length_cons]\n    nlinarith\n/-- Literal output bytes are polynomial in actual occurrence mass, never a completion catalogue. -/\ntheorem output_length_le {r t digits:ℕ} (vs:List (SubdividedVertex r t digits)) (X f n:ℕ)\n    (_hX:1≤X) (hb:Bounded X vs) (hf:f+vs.length≤X) (hn:n+count vs≤10*X^3) :\n    (output vs f n []).length≤count vs*(100*X^3) := by\n  induction vs generalizing f n with\n  | nil => simp [output,count]\n  | cons v vs ih =>\n    have hv:=hb v (by simp)\n    have hbn:Bounded X vs:=by intro w hw;exact hb w (by simp [hw])\n    have hfn:f+1+vs.length≤X:=by simp only [List.length_cons] at hf;omega\n    have hnn:n+subdividedArity v+count vs≤10*X^3:=by\n      simpa only [count,List.map_cons,List.sum_cons,Nat.add_assoc] using hn\n    have hr:=ih (f+1) (n+subdividedArity v) hbn hfn hnn\n    have hl:=records_length_le (vertex v) (subdividedArity v) n f 0\n      (output vs (f+1) (n+subdividedArity v) [])\n    have hc:subdividedArity v≤count (v::vs):=by simp only [count,List.map_cons,List.sum_cons];omega\n    have h3:X≤X^3:=Nat.le_pow (by omega)\n    have hq:2*(n+f+0+2*subdividedArity v+wordMass (vertex v))+8≤100*X^3:=by\n      simp only [List.length_cons] at hf\n      nlinarith only [hn,hc,hv.1,hf,h3,_hX]\n    have hm:=Nat.mul_le_mul_left (subdividedArity v) hq\n    change (records (vertex v) (subdividedArity v) n f 0\n      (output vs (f+1) (n+subdividedArity v) [])).length≤_\n    simp only [count,List.map_cons,List.sum_cons] at *\n    nlinarith only [hl,hr,hm]\n/-- Literal actual-family scan and byte bounds, with no resource premise at the original endpoint. -/\ntheorem original_resources {r t digits:ℕ} (vs:List (SubdividedVertex r t digits)) :\n    scanTime vs 0 0≤10000*(size vs)^6 ∧\n      (output vs 0 0 []).length≤1000*(size vs)^6 := by\n  let X:=size vs\n  have hX:1≤X:=by unfold X size;omega\n  have hv:vs.length≤X:=(vertices_le_tape vs).trans (by unfold X size;omega)\n  have hb:=original_bounded vs\n  have hc:count vs≤10*X^3:=by\n    have h:=count_le vs X hb\n    have hm:=Nat.mul_le_mul_right (10*X^2) hv\n    nlinarith only [h,hm]\n  have hs:=scanTime_le vs X 0 0 hX hb (by omega) (by omega)\n  have ho:=output_length_le vs X 0 0 hX hb (by omega) (by omega)\n  have hm:=Nat.mul_le_mul_right (10000*X^5) hv\n  have hn:=Nat.mul_le_mul_right (100*X^3) hc\n  constructor <;> nlinarith only [hs,ho,hm,hn]\nend RiemannGaussian.SemiprimeD1StackPortCataloguePolynomial\n","RiemannGaussian.SemiprimeD1StackPortOwnerRecipeAcquisition":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRecipePrepare\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRecipeModes\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nnamespace RiemannGaussian.SemiprimeD1StackPortOwnerRecipeAcquisition\nopen SemiprimeD1StackPortOwnerRecipe SemiprimeD1StackPortOwnerRecipeSpec\nopen SemiprimeD1StackPortOwnerRecipePrepare SemiprimeD1StackPortOwnerRecipeModes\nopen SemiprimeD1StackProcedureTrace (Runs runs_refl runs_trans)\n/-- Static preparation continuation used only in the trace proof. -/\ndef entry (count:ℕ) : Label :=\n  if h:count<41 then .local (.prepare ⟨count,h⟩) else .local (.classify 0)\n/-- The chronological sum of ACTUAL primitive call bounds, never a source operand. -/\ndef remainingBudget (p:Counters) : ℕ→ℕ→ℕ\n  | 0,_=>0\n  | fuel+1,count=>if h:count<41 then stepTime p ⟨count,h⟩+remainingBudget p fuel (count+1) else 0\n/-- Every real preparation stage executes from its exact acquired predecessor store. -/\ntheorem suffix_run (p:Counters) (fuel count:ℕ) (hc:count+fuel=41) :\n    ∃time≤remainingBudget p fuel count,Runs program time (entry count) (atStage p count)\n      (.local (.classify 0)) (prepared p) := by\n  induction fuel generalizing count with\n  | zero=>\n    have he:count=41:=by omega\n    subst count\n    exact ⟨0,le_rfl,runs_refl program _ _⟩\n  | succ fuel ih=>\n    have hcount:count<41:=by omega\n    have hn:count+1+fuel=41:=by omega\n    obtain ⟨time,ht,hr⟩:=ih (count+1) hn\n    let j:Fin 41:=⟨count,hcount⟩\n    obtain ⟨stepTime,hstepTime,hstep⟩:=prepare_step p j\n    have hnext:nextPrepare j=entry (count+1):=by\n      by_cases hh:count<40\n      · have hsucc:count+1<41:=by omega\n        simp [nextPrepare,entry,j,hh,hsucc]\n      · have he:count=40:=by omega\n        subst count\n        rfl\n    rw [hnext] at hstep\n    have h:=runs_trans program _ _ _ _ _ _ _ _ hstep hr\n    refine ⟨stepTime+time,?_,?_⟩\n    · simp only [remainingBudget,dite_eq_left hcount]\n      exact Nat.add_le_add hstepTime ht\n    · have hentry:entry count=.local (.prepare j):=by simp [entry,hcount,j]\n      rw [hentry]\n      exact h\n/-- ACTUAL original-counter literal-tag/arithmetic acquisition, including every included call. -/\ntheorem acquisition_run (p:Counters) :\n    ∃time≤406+remainingBudget p 41 0,Runs program time (.local .start) (input (words p))\n      (.local (.classify 0)) (prepared p) := by\n  obtain ⟨m,hm,hr⟩:=modes_run p\n  obtain ⟨n,hn,hs⟩:=suffix_run p 41 0 rfl\n  change Runs program n (.local (.prepare 0)) (atStage p 0) (.local (.classify 0)) (prepared p) at hs\n  exact ⟨m+n,Nat.add_le_add hm hn,runs_trans program _ _ _ _ _ _ _ _ hr hs⟩\nend RiemannGaussian.SemiprimeD1StackPortOwnerRecipeAcquisition\n","RiemannGaussian.SemiprimeD1StackPortOwnerRoutingRow":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRoutingParse\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRoutingClear\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPortOwnerRoutingRow\nopen SemiprimeD1StackPortOwnerRouting SemiprimeD1StackPortOwnerRoutingAcquisition\nopen SemiprimeD1StackPortOwnerRoutingView\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\n/-- Exact actually reached all-role lookup store after matching this port's computed compact key. -/\ndef lookupDone (map:List (List Bool×List Bool)) (w:Fin 9→List Bool) : Lookup.Stack→List Bool :=\n  (SemiprimeD1StackOwnerLookup.done (SemiprimeD1PortOwnerRoutingSpec.query w) map []).data\n/-- Exact emitted owner/scope bytes, including their physically pushed row tag. -/\ndef row (map:List (List Bool×List Bool)) (w:Fin 9→List Bool) : List Bool :=\n  SemiprimeD1StackPortOwnerRoutingEmit.row (lookupDone map w (.inr .output)) (w 0)\n/-- SAME actual parse, key framing, whole map copy, numeric lookup, emission and ALL cleanup clocks. -/\ndef budget (map:List (List Bool×List Bool)) (w:Fin 9→List Bool) : Nat :=\n  (1+SemiprimeD1StackPortOwnerRoutingParse.time w 9)+(6*SemiprimeD1StackPortOwnerRoutingKey.mass w+31)+\n  (5*(SemiprimeD1StackOwnerLookup.records map []).length+\n    SemiprimeD1StackOwnerLookupBounds.runBound (SemiprimeD1PortOwnerRoutingSpec.query w) map+5)+\n  (10*(lookupDone map w (.inr .output)).length+10*(w 0).length+21)+\n  SemiprimeD1StackPortOwnerRoutingClear.time (SemiprimeD1StackPortOwnerRoutingClear.bank (lookupDone map w) w) 20\n/-- COMPLETE physical factor-major routing iteration returns to its SAME scoped-reader loop.\nAll nine fields are parsed; the key is framed; the actual retained E-map is copied and scanned;\nowner/scope bytes are emitted; and all eleven lookup/nine parsed words are physically drained. -/\ntheorem row_run (m:Map.Stack→List Bool) (s:Scope.Stack→List Bool)\n    (map:List (List Bool×List Bool))\n    (hm:m (SemiprimeD1StackOwnerCatalogue.aux .output)=SemiprimeD1StackOwnerLookup.records map [])\n    (w:Fin 9→List Bool) (tail raw:List Bool) :\n    ∃time≤budget map w,Runs program time (.local .parse)\n      (data m s (fun _=>[]) (fun _=>[]) (rowAux (SemiprimeD1FactorScopePairEncoding.record w tail) raw))\n      (.local .parse) (data m s (fun _=>[]) (fun _=>[]) (rowAux tail ((row map w).reverse++raw))) := by\n  let a:=rowAux tail raw\n  let a':=Function.update a .reversed ((row map w).reverse++raw)\n  have hp:=SemiprimeD1StackPortOwnerRoutingParse.parse_run m s (fun _=>[]) w tail raw\n  have hk:=SemiprimeD1StackPortOwnerRoutingKey.key_run m s w a rfl\n  obtain ⟨t,ht,hl⟩:=SemiprimeD1StackPortOwnerRoutingLookup.copy_lookup_run m s w a rfl map hm\n  change Runs program t _ _ _ (data m s (lookupDone map w) w a) at hl\n  have he:=SemiprimeD1StackPortOwnerRoutingEmit.row_run m s (lookupDone map w) w a rfl rfl\n  change Runs program _ _ _ _ (data m s (lookupDone map w) w a') at he\n  have hc:=SemiprimeD1StackPortOwnerRoutingClear.clear_run m s (lookupDone map w) w a'\n  have ha:a'=rowAux tail ((row map w).reverse++raw):=by funext k;cases k <;> rfl\n  rw [ha] at he hc\n  have h:=runs_trans program _ _ _ _ _ _ _ _ hp (runs_trans program _ _ _ _ _ _ _ _ hk\n    (runs_trans program _ _ _ _ _ _ _ _ hl (runs_trans program _ _ _ _ _ _ _ _ he hc)))\n  refine ⟨_,?_,h⟩\n  unfold budget\n  omega\n/-- Actual routed row equals the computed-owner/unchanged-scope pair used by the authoritative typed bridge. -/\ntheorem row_pair (map:List (List Bool×List Bool)) (w:Fin 9→List Bool) :\n    row map w=SemiprimeD1StackPortOwnerRoutingEmit.row (SemiprimeD1PortOwnerRoutingSpec.pair map w).1\n      (SemiprimeD1PortOwnerRoutingSpec.pair map w).2 := rfl\nend RiemannGaussian.SemiprimeD1StackPortOwnerRoutingRow\n","RiemannGaussian.SemiprimeD1StackProductRecord":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProductTableBounds\nimport RiemannGaussian.SemiprimeD1StackPortOrdinalStreamOriginal\nimport RiemannGaussian.SemiprimeD1StackVertexRecordStream\n/-! # Actual product table, acquired scope conversion and original record logging\nThe original binary N and an acquired binary occurrence-ID vector are the only\nsource fields. The two acquired outputs are the logger's actual operands.\nScope routing remains the caller's acquisition work.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackProductRecord\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace Z\nexport SemiprimeD1StackProductTable (Stack Label program initial)\nexport SemiprimeD1StackProductTableExecution (done)\n/-- Retained original binary N role inside the actual table acquirer. -/\ndef original : Stack := .inr .source\n/-- Actual complete product-table output, directly consumed by the logger. -/\ndef output : Stack := .inr .output\nend Z\nnamespace S\nexport SemiprimeD1StackPortOrdinalStream (Stack Label program initial result)\nend S\nnamespace R\nexport SemiprimeD1StackVertexRecordStream (Stack Label code data row recordTime)\nend R\n/-- All ninety-nine physical roles, including the two unused alias shadows. -/\nabbrev Stack := Z.Stack ⊕ (S.Stack ⊕ R.Stack)\n/-- Actual N-only table source's checker and private work registers. -/\ndef tableStack (k : Z.Stack) : Stack := .inl k\n/-- Actual preserving binary-ID serializer's private registers and bank. -/\ndef scopeStack (k : S.Stack) : Stack := .inr (.inl k)\n/-- Direct operands: neither acquired answer is copied or recoded. -/\ndef recordStack : R.Stack → Stack\n  | .ports => scopeStack .output\n  | .table => tableStack Z.output\n  | k => .inr (.inr k)\n/-- Original binary N's physical input role. -/\ndef original : Stack := tableStack Z.original\n/-- The actual caller's accumulated reverse row log. -/\ndef history : Stack := recordStack .history\n/-- The actual caller's retained final output accumulator. -/\ndef output : Stack := recordStack .output\n/-- Four finite local controls, independent of every input value. -/\ninductive Control where | start | scope | record | done\n  deriving DecidableEq\ninstance : Fintype Control := Fintype.ofList [.start,.scope,.record,.done] (by intro k;cases k <;> simp)\n/-- All real component labels, with no decoded identifier in control. -/\nabbrev Label := Control ⊕ (Z.Label ⊕ (S.Label ⊕ R.Label))\n/-- Literal whole-table acquisition procedure inclusion. -/\ndef tableLabel (pc : Z.Label) : Label := .inr (.inl pc)\n/-- Literal binary ordinal serialization procedure inclusion. -/\ndef scopeLabel (pc : S.Label) : Label := .inr (.inr (.inl pc))\n/-- Literal physical frame logger inclusion. -/\ndef recordLabel (pc : R.Label) : Label := .inr (.inr (.inr pc))\n/-- The actual three calls; the logger consumes both acquired outputs directly. -/\ndef program : Label → C.Instruction Stack Label\n  | .inl .start => .call (tableLabel .start) (.inl .scope)\n  | .inl .scope => .call (scopeLabel (.control .start)) (.inl .record)\n  | .inl .record => .call (recordLabel .record) (.inl .done)\n  | .inl .done => .base .halt\n  | .inr (.inl pc) => SemiprimeD1StackValidationLink.instruction tableStack tableLabel (Z.program pc)\n  | .inr (.inr (.inl pc)) => SemiprimeD1StackValidationLink.instruction scopeStack scopeLabel (S.program pc)\n  | .inr (.inr (.inr pc)) => SemiprimeD1StackMultiplierLink.instruction recordStack recordLabel (R.code pc)\n/-- Entire physical inventory; both unused alias shadows stay empty. -/\ndef data (z : Z.Stack → List Bool) (s : S.Stack → List Bool) (hist out : List Bool) : Stack → List Bool :=\n  Sum.elim z (Sum.elim s (R.data [] [] hist out))\n/-- Only original binary N, acquired binary scope bytes and caller accumulators. -/\ndef initial (bits bank hist out : List Bool) : C.State Stack Label :=\n  ⟨some (.inl .start),none,none,data (Z.initial bits).data (S.initial bank).data hist out,[]⟩\n/-- Proof-side exact acquired product-table bytes, never a runtime input. -/\ndef table (bits : List Bool) : List Bool := (Z.done bits).data Z.output\n/-- Both acquired fields are consumed; original N, acquired depth and binary bank remain. -/\ndef done (bits : List Bool) (words : List (List Bool)) (hist out : List Bool) : C.State Stack Label :=\n  ⟨none,none,none,data (Function.update (Z.done bits).data Z.output [])\n    (Function.update (SemiprimeD1StackPortOrdinalStreamExecution.done words).data (SemiprimeD1StackPortOrdinalStream.Stack.output) [])\n    ((R.row (S.result words) (table bits)).reverse++hist) out,[]⟩\n/-- Genuine fixed finite procedure machine, including the actual return alphabet. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine original output (.inl .start) program\n/-- Every original metadata, private scratch and unused alias role is counted. -/\ntheorem stack_card : Fintype.card Stack=99 := by decide\n/-- The logger's two shared operands and its own accumulators are distinct. -/\ntheorem recordStack_injective : Function.Injective recordStack := by decide\n/-- The actual original binary N survives the complete record acquisition. -/\ntheorem retained_N (bits : List Bool) (words : List (List Bool)) (hist out : List Bool) :\n    (done bits words hist out).data (tableStack (.inr .source))=bits := rfl\n/-- The actual physically acquired unary table depth survives logging. -/\ntheorem retained_depth (bits : List Bool) (words : List (List Bool)) (hist out : List Bool) :\n    (done bits words hist out).data (tableStack (.inr .depth))=\n      SemiprimeD1StackUnaryDivmod.unary (SemiprimeD1StackProductTableSpec.arity bits) := rfl\n/-- The original binary occurrence-ID bank is preserved byte for byte. -/\ntheorem retained_bank (bits : List Bool) (words : List (List Bool)) (hist out : List Bool) :\n    (done bits words hist out).data (scopeStack .bank)=SemiprimeD1TensorTapeCodec.vectorBits words := rfl\n/-- Appending a row leaves the caller's final output accumulator intact. -/\ntheorem retained_output (bits : List Bool) (words : List (List Bool)) (hist out : List Bool) :\n    (done bits words hist out).data output=out := rfl\nend RiemannGaussian.SemiprimeD1StackProductRecord\n","RiemannGaussian.SemiprimeD1StackProductTableDFSParts":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProductTableState\n/-! # Literal product-table DFS transitions preserving exact local-port order -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackProductTableDFSParts\nopen SemiprimeD1StackProductTable SemiprimeD1StackProductTableState SemiprimeD1StackProcedureTrace\n/-- Actual depth EOF enters the real leaf checker procedure. -/\ntheorem visit_zero (bits front hist : List Bool) :\n    Runs program 1 .visit (data bits 0 front hist) .leaf (data bits 0 front hist) := by\n  apply one_base program .visit .leaf (.pop (.inr .depth) .leaf .fork .fork) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>cases k <;> rfl\n/-- One actual acquired depth marker is popped at an internal node. -/\ntheorem visit_succ (bits : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs program 1 .visit (data bits (n+1) front hist) .fork (data bits n front hist) := by\n  apply one_base program .visit .fork (.pop (.inr .depth) .leaf .fork .fork) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>cases k <;> rfl\n/-- The physical old-codec fork tag is written before either child. -/\ntheorem fork_push (bits : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs program 1 .fork (data bits n front hist) .low (data bits n front (true::hist)) := by\n  apply one_base program .fork .low (.push (.inr .reversed) true .low) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>cases k <;> rfl\n/-- FALSE is physically prepended to the reverse-prefix before the first child. -/\ntheorem low_push (bits : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs program 1 .low (data bits n front hist) .high (data bits n (false::front) hist) := by\n  apply one_base program .low .high (.push (.inr .prefix) false .high) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>cases k <;> rfl\n/-- The first child's physical prefix bit is consumed after its real return. -/\ntheorem low_pop (bits : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs program 1 .afterLow (data bits n (false::front) hist) .copySource (data bits n front hist) := by\n  apply one_base program .afterLow .copySource (.pop (.inr .prefix) .bad .copySource .copySource) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>cases k <;> rfl\n/-- TRUE is physically prepended before the second child, in old table order. -/\ntheorem high_push (bits : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs program 1 .copySource (data bits n front hist) .afterHigh (data bits n (true::front) hist) := by\n  apply one_base program .copySource .afterHigh (.push (.inr .prefix) true .afterHigh) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>cases k <;> rfl\n/-- The second child's actual prefix bit is popped after its real return. -/\ntheorem high_pop (bits : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs program 1 .restore (data bits n (true::front) hist) .returnDone (data bits n front hist) := by\n  apply one_base program .restore .returnDone (.pop (.inr .prefix) .bad .returnDone .returnDone) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>cases k <;> rfl\n/-- The original acquired depth marker is physically restored before return. -/\ntheorem depth_restore (bits : List Bool) (n : ℕ) (front hist : List Bool) :\n    Runs program 1 .returnDone (data bits n front hist) .leafReturn (data bits (n+1) front hist) := by\n  apply one_base program .returnDone .leafReturn (.push (.inr .depth) true .leafReturn) _ _ rfl\n  · rfl\n  · funext k;cases k with\n    | inl k=>rfl\n    | inr k=>cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackProductTableDFSParts\n","RiemannGaussian.SemiprimeD1StackPublicCarryOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicCarryExecution\nimport RiemannGaussian.SemiprimeD1StackRootSourceOriginal\n/-! # Integer semantics of the acquired public carry computation -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option synthInstance.maxSize 4096\nnamespace RiemannGaussian.SemiprimeD1StackPublicCarryOriginal\nopen SemiprimeD1StackPublicCarry SemiprimeD1StackPublicCarryState\nopen SemiprimeD1StackPublicCarryExecution SemiprimeBitArithmetic SemiprimeMacroParameters\n/-- Every computed branch bit is characterized by the actual integer operands.\nThis theorem assumes neither guards nor their answers. -/\ntheorem answer_true (context : T.Stack→List Bool) (raw : List Bool) :\n    answer context raw=true ↔\n      bitValue (coefficient context raw)<bitValue (width context) ∧\n      bitValue (previous context raw)<bitValue (boundWord context) ∧\n      bitValue (next context raw)<bitValue (boundWord context) ∧\n      bitValue (coefficient context raw)+bitValue (previous context raw)=\n        bitValue (target context)+2^(radix context).length*bitValue (next context raw) := by\n  simp only [answer,Bool.and_eq_true,guardAnswer,guardBound,word,Fin.reduceEq,\n    ite_true,ite_false,SemiprimeD1StackWordLessExecution.answer_true,\n    equationAnswer,SemiprimeD1StackCarryEquationExecution.answer,\n    SemiprimeMacroEntryBitPrimitives.carryEquationBits_correct]\n/-- Actual acquired modulus width, without a supplied size answer. -/\ntheorem acquired_width_length (bits index : List Bool) :\n    (width (actualContext bits index)).length=SemiprimeMacroParameters.transformLength bits.length+1 := by\n  exact SemiprimeD1StackRootSourceOriginal.modulus_length bits\n/-- Actual radix cache has the original physically acquired template length. -/\ntheorem acquired_radix_length (bits index : List Bool) :\n    (radix (actualContext bits index)).length=SemiprimeMacroParameters.radixBits bits.length := by\n  change (List.replicate (SemiprimeMacroParameters.radixBits bits.length) true).length=_\n  exact List.length_replicate\n/-- The actual low-bit-replaced modulus word represents the strict carry bound. -/\ntheorem acquired_bound_value (bits index : List Bool) :\n    bitValue (boundWord (actualContext bits index))=2^SemiprimeMacroParameters.transformLength bits.length := by\n  let n:=SemiprimeMacroParameters.transformLength bits.length\n  have hn : 0<n := by unfold n SemiprimeMacroParameters.transformLength;positivity\n  change bitValue (false::(List.replicate (n-1) false++[true]))=2^n\n  rw [bitValue,SemiprimeD1StackFermatWords.zeros_value]\n  simp only [bitNat,Bool.false_eq_true,ite_false,Nat.zero_add]\n  have he : n-1+1=n := by omega\n  simp only [bitValue,bitNat,ite_true,Nat.mul_zero,Nat.add_zero,Nat.mul_one]\n  rw [Nat.mul_comm,←Nat.pow_succ]\n  congr 1\n/-- Actual modulus value, acquired by the original binary preprocessing. -/\ntheorem acquired_modulus_value (bits index : List Bool) :\n    bitValue (width (actualContext bits index))=2^SemiprimeMacroParameters.transformLength bits.length+1 := by\n  change bitValue (SemiprimeD1StackFermatWords.modulusWord (SemiprimeMacroParameters.transformLength bits.length))=_\n  exact SemiprimeD1StackFermatWords.modulus_value _ (by unfold SemiprimeMacroParameters.transformLength;positivity)\n/-- Original public carry semantics after ACTUAL target acquisition, for every\nraw assignment (including incomplete/padded ones). No guard truth is assumed. -/\ntheorem acquired_carry (bits raw index : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) :\n    answer (actualContext bits index) raw=\n      (SemiprimeMacroEntryBitCheck.carryRun (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN)\n        (target (actualContext bits index)) (coefficient (actualContext bits index) raw)\n        (previous (actualContext bits index) raw) (next (actualContext bits index) raw)).accepted := by\n  apply Bool.eq_iff_iff.mpr\n  rw [answer_true,SemiprimeMacroEntryBitCheck.carryRun_correct,\n    acquired_modulus_value,acquired_bound_value,acquired_radix_length]\n  have hw:=SemiprimeD1BinaryDigitAcquisitionBounds.canonical_width bits hc\n  rw [hw]\n  simp only [SemiprimePublicFactorCount.publicConfig,SemiprimeMacroParameters.axes_product]\n/-- An old target WORD need not have identical zero padding: the physical\nINTEGER verdict depends on its value, not its byte representation. -/\ntheorem acquired_target_carry (bits raw index : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (k : Fin (SemiprimeMacroParameters.firstAxis (bitLength (bitValue bits))*\n      SemiprimeMacroParameters.secondAxis (bitLength (bitValue bits)))) (hi : index.length=k.val) :\n    answer (actualContext bits index) raw=\n      (SemiprimeMacroEntryBitCheck.carryRun (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN)\n        ((SemiprimeMacroEntryBitCheck.configTargets (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN)).words k)\n        (coefficient (actualContext bits index) raw) (previous (actualContext bits index) raw)\n        (next (actualContext bits index) raw)).accepted := by\n  rw [acquired_carry bits raw index hc hN]\n  apply Bool.eq_iff_iff.mpr\n  rw [SemiprimeMacroEntryBitCheck.carryRun_correct,SemiprimeMacroEntryBitCheck.carryRun_correct]\n  have ht:=SemiprimeD1StackPublicTargetExecution.target_original bits index hc hN\n  change bitValue (target (actualContext bits index))=_ at ht\n  have hv : bitValue ((SemiprimeMacroEntryBitCheck.configTargets\n      (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN)).words k)=\n      targetDigit (bitLength (bitValue bits)) (bitValue bits) k.val :=\n    (SemiprimeMacroEntryBitCheck.configTargets (SemiprimePublicFactorCount.publicConfig (bitValue bits) hN)).value k\n  rw [ht,hi,hv]\nend RiemannGaussian.SemiprimeD1StackPublicCarryOriginal\n","RiemannGaussian.SemiprimeD1StackPublicInputExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicInputBranches\n/-! # Closed actual source execution of the whole PublicInput52 checker\nOnly original bits/raw/index and bits≠[] enter the final endpoint. Every bound,\nword, guard, test and flag is acquired by the literal Core52 procedures.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 8192\nset_option maxHeartbeats 2200000\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackPublicInputExecution\nopen SemiprimeD1StackPublicInput SemiprimeD1StackPublicInputState\nopen SemiprimeD1StackPublicInputComponents SemiprimeD1StackPublicInputControl SemiprimeD1StackPublicInputBranches\nopen SemiprimeD1StackProcedureFragments (Runs)\n/-- Generous derived local bound; no component-cost answer is an input. -/\ndef bodyBound (bits raw indexWord : List Bool) : ℕ :=\n  100*((M.word bits raw).length+(M.actualBound bits indexWord).length+3)\n/-- Complete actual source budget: H37 ONCE, raw Copy, WordBlock, all concrete\ncomparison/flag branches and cleanup, their actual calls/returns and final halt. -/\ndef timeBound (bits raw indexWord : List Bool) : ℕ :=\n  (SemiprimeD1StackPublicInputWidthExecution.timeBound bits indexWord+1)+(5*raw.length+4)+\n    (SemiprimeD1StackWordBlockExecution.totalTime (M.cached bits)+1)+bodyBound bits raw indexWord+1\n/-- Actual active/inactive execution, closed under all computed branch values;\nnone is supplied as a runtime operand, truth advice or cost premise. -/\ntheorem body_run (bits raw indexWord : List Bool) :\n    ∃t≤bodyBound bits raw indexWord,Runs program t .activity\n      (store (header bits indexWord (M.actualBound bits indexWord)) raw (suffix bits raw) (M.word bits raw) [] [] [])\n      .done (store (header bits indexWord []) raw (suffix bits raw) [] [] [] [M.expected bits raw indexWord]) := by\n  have hactivity:=activity_peek bits indexWord raw (suffix bits raw) (M.word bits raw)\n  by_cases ha:0<SemiprimeD1StackInputWidthExecution.width (SemiprimeD1StackPublicInputWidthExecution.cache bits indexWord)\n  · have h0 : Runs program 1 .activity\n        (store (header bits indexWord (M.actualBound bits indexWord)) raw (suffix bits raw) (M.word bits raw) [] [] [])\n        .guardCopy (store (header bits indexWord (M.actualBound bits indexWord)) raw (suffix bits raw) (M.word bits raw) [] [] []) := by\n      simpa only [ha,ite_true] using hactivity\n    have h1:=copy_word_call .guardCopy .guard rfl (header bits indexWord (M.actualBound bits indexWord))\n      raw (suffix bits raw) (M.word bits raw)\n    have h2:=less_call .guard .readGuard rfl bits indexWord raw (suffix bits raw) (M.word bits raw)\n      (M.word bits raw) (M.actualBound bits indexWord)\n    have h3:=read_comparison .readGuard .bad (fun b=>if b then Label.indexCase else .write false) rfl\n      (header bits indexWord []) raw (suffix bits raw) (M.word bits raw)\n      (SemiprimeD1StackWordLessExecution.answer (M.word bits raw) (M.actualBound bits indexWord))\n    have hp:=SemiprimeD1StackProcedureFragments.Runs.trans h0\n      (SemiprimeD1StackProcedureFragments.Runs.trans h1\n        (SemiprimeD1StackProcedureFragments.Runs.trans h2 h3))\n    have hl:=SemiprimeD1StackWordLessExecution.totalTime_le (M.word bits raw) (M.actualBound bits indexWord)\n    by_cases hg:SemiprimeD1StackWordLessExecution.answer (M.word bits raw) (M.actualBound bits indexWord)=true\n    · have hprefix : Runs program (1+((5*(M.word bits raw).length+4)+\n          ((SemiprimeD1StackWordLessExecution.totalTime (M.word bits raw) (M.actualBound bits indexWord)+1)+1)))\n          .activity (store (header bits indexWord (M.actualBound bits indexWord)) raw (suffix bits raw) (M.word bits raw) [] [] [])\n          .indexCase (store (header bits indexWord []) raw (suffix bits raw) (M.word bits raw) [] [] []) := by\n        simpa only [hg,ite_true] using hp\n      obtain ⟨t,ht,hrest⟩:=index_tail bits raw indexWord\n      have hh:=hprefix.trans hrest\n      refine ⟨(1+((5*(M.word bits raw).length+4)+\n        ((SemiprimeD1StackWordLessExecution.totalTime (M.word bits raw) (M.actualBound bits indexWord)+1)+1)))+t,?_,?_⟩\n      · unfold bodyBound\n        omega\n      · have hv : flagRule bits raw indexWord=M.expected bits raw indexWord := by\n          simp only [SemiprimeD1StackPublicInputMeaning.expected,ha,ite_true,hg,Bool.true_and,flagRule]\n        rw [←hv]\n        exact hh\n    · have hn:SemiprimeD1StackWordLessExecution.answer (M.word bits raw) (M.actualBound bits indexWord)=false :=\n        by cases h:SemiprimeD1StackWordLessExecution.answer (M.word bits raw) (M.actualBound bits indexWord) <;> simp_all\n      have hprefix : Runs program (1+((5*(M.word bits raw).length+4)+\n          ((SemiprimeD1StackWordLessExecution.totalTime (M.word bits raw) (M.actualBound bits indexWord)+1)+1)))\n          .activity (store (header bits indexWord (M.actualBound bits indexWord)) raw (suffix bits raw) (M.word bits raw) [] [] [])\n          (.write false) (store (header bits indexWord []) raw (suffix bits raw) (M.word bits raw) [] [] []) := by\n        simpa only [hn,Bool.false_eq_true,ite_false] using hp\n      have hrest:=write_finish bits indexWord [] raw (suffix bits raw) (M.word bits raw) false\n      have hh:=hprefix.trans hrest\n      refine ⟨(1+((5*(M.word bits raw).length+4)+\n        ((SemiprimeD1StackWordLessExecution.totalTime (M.word bits raw) (M.actualBound bits indexWord)+1)+1)))+\n        ((M.word bits raw).length+0+3),?_,?_⟩\n      · unfold bodyBound\n        omega\n      · have hv : false=M.expected bits raw indexWord := by\n          simp only [SemiprimeD1StackPublicInputMeaning.expected,ha,ite_true,hn,Bool.false_and]\n        rw [←hv]\n        exact hh\n  · have h0 : Runs program 1 .activity\n        (store (header bits indexWord (M.actualBound bits indexWord)) raw (suffix bits raw) (M.word bits raw) [] [] [])\n        .zero (store (header bits indexWord (M.actualBound bits indexWord)) raw (suffix bits raw) (M.word bits raw) [] [] []) := by\n      simpa only [ha,ite_false] using hactivity\n    have h1:=equal_call .zero .readZero rfl (header bits indexWord (M.actualBound bits indexWord))\n      raw (suffix bits raw) (M.word bits raw)\n    have h2:=zero_finish bits indexWord (M.actualBound bits indexWord) raw (suffix bits raw)\n      (decide (SemiprimeBitArithmetic.bitValue (M.word bits raw)=0))\n    have hh:=SemiprimeD1StackProcedureFragments.Runs.trans h0\n      (SemiprimeD1StackProcedureFragments.Runs.trans h1 h2)\n    refine ⟨1+((SemiprimeD1StackWordEqualExecution.executionTime (M.word bits raw) []+1)+\n      ((M.actualBound bits indexWord).length+4)),?_,?_⟩\n    · have he:=SemiprimeD1StackWordEqualExecution.executionTime_le (M.word bits raw) []\n      simp only [List.length_nil] at he\n      unfold bodyBound\n      omega\n    · have hv : decide (SemiprimeBitArithmetic.bitValue (M.word bits raw)=0)=M.expected bits raw indexWord := by\n        simp only [SemiprimeD1StackPublicInputMeaning.expected,ha,ite_false]\n      rw [←hv]\n      exact hh\n\n/-- WHOLE closed actual checker. No computed width/word/guard/verdict/clock\npremise is admitted; every source and comparison executes inside this code. -/\ntheorem source_run (bits raw indexWord : List Bool) (hb : bits≠[]) :\n    ∃t≤timeBound bits raw indexWord,C.run program t (initial bits raw indexWord)=\n      some (SemiprimeD1StackPublicInputState.done bits raw indexWord) := by\n  obtain ⟨a,ha,h0⟩:=acquire_call bits raw indexWord hb\n  have h1:=copy_raw_call bits raw indexWord\n  have h2:=block_call bits raw indexWord\n  obtain ⟨b,hbTime,hbody⟩:=body_run bits raw indexWord\n  have h3 : Runs program b .activity (afterBlock bits raw indexWord) .done\n      (SemiprimeD1StackPublicInputState.done bits raw indexWord).data := by\n    simpa only [afterBlock,header_acquired,SemiprimeD1StackPublicInputState.done] using hbody\n  have hh:=SemiprimeD1StackProcedureFragments.Runs.trans h0\n    (SemiprimeD1StackProcedureFragments.Runs.trans h1\n      (SemiprimeD1StackProcedureFragments.Runs.trans h2 h3))\n  obtain ⟨finish,hfinish,hAt⟩:=hh [] (initial bits raw indexWord) ⟨rfl,rfl,rfl⟩\n  refine ⟨(a+1)+((5*raw.length+4)+((SemiprimeD1StackWordBlockExecution.totalTime (M.cached bits)+1)+b))+1,?_,?_⟩\n  · unfold timeBound\n    omega\n  · rw [SemiprimeD1StackReturnLink.run_add,hfinish,Option.bind_some]\n    rcases hAt with ⟨hpc,hd,hframes⟩\n    change C.step program finish=some (SemiprimeD1StackPublicInputState.done bits raw indexWord)\n    simp [C.step,SemiprimeD1StackCalls.step,hpc,program,C.execute,SemiprimeD1StackCalls.execute,hd,hframes,\n      SemiprimeD1StackPublicInputState.done]\nend RiemannGaussian.SemiprimeD1StackPublicInputExecution\n","RiemannGaussian.SemiprimeD1StackPublicInputTableTrace":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicInputTable\nimport RiemannGaussian.SemiprimeD1StackStaticTableSpec\n/-! # Concrete complete trace contract from the frozen actual input checker\nThere is no unknown checker/acquisition supplier in this instance. The entire\nliteral52-role source executes for every leaf, with its own proved bit clock.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicInputTableTrace\nopen SemiprimeD1StackPublicInputTable SemiprimeD1StackStaticTableSpec\n/-- Postcondition of actual original-N/index arithmetic, never a runtime operand. -/\ndef answer (bits indexWord raw : List Bool) : Bool :=\n  SemiprimeD1StackPublicInputMeaning.expected bits raw indexWord\n/-- The frozen actual checker's full original-input quadratic bit allowance. -/\ndef budget (bits indexWord : List Bool) (width : Nat) : Nat :=\n  1000000000000*(bits.length+width+indexWord.length+2)^2\n/-- Physical template copy and raw reversal match the SAME frozen source input. -/\ntheorem initial_eq (bits raw indexWord : List Bool) :\n    checkerInitial static (inputTemplate bits indexWord) raw=P.initial bits raw indexWord := by\n  apply congrArg (fun d=>(⟨some .start,none,none,d,[]⟩:SemiprimeD1StackCalls.State P.Stack P.Label))\n    (template_raw_update bits raw indexWord)\n/-- The concrete compiler's checker contract is DISCHARGED by the frozen real\nsource_run_bounded, including active/inactive/first/nonfirst arithmetic cases. -/\ntheorem actual_trace (bits indexWord : List Bool) (hb : bits≠[]) :\n    CheckerTrace static (inputTemplate bits indexWord) (answer bits indexWord) (budget bits indexWord) := by\n  intro raw\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackPublicInputBounds.source_run_bounded bits raw indexWord hb\n  refine ⟨t,ht,SemiprimeD1StackPublicInputState.done bits raw indexWord,rfl,rfl,?_,rfl⟩\n  rw [initial_eq]\n  exact hr\n/-- Every initialized template field is paid by original N and actual index markers. -/\ntheorem template_cell_le (bits indexWord : List Bool) (k : P.Stack) :\n    (inputTemplate bits indexWord k).length≤ bits.length+indexWord.length := by\n  change ((P.initial bits [] indexWord).data k).length≤ bits.length+indexWord.length\n  simpa only [List.length_nil,Nat.add_zero] using\n    SemiprimeD1StackPublicInputBounds.initial_length bits [] indexWord k\n/-- The frozen public initializer has ONLY its one original N input word. -/\ntheorem public_input_only (bits : List Bool) (k : SemiprimeD1BinaryPublicAcquisition.Stack) :\n    SemiprimeD1BinaryPublicAcquisition.input bits k=\n      if k=SemiprimeD1BinaryPublicAcquisition.digitStack\n        (SemiprimeD1BinaryPublicAcquisition.Digits.metaStack .input) then bits else [] := by\n  have hi:=SemiprimeD1StackCalls.initial_correct\n    (SemiprimeD1BinaryPublicAcquisition.digitStack (SemiprimeD1BinaryPublicAcquisition.Digits.metaStack .input))\n    (SemiprimeD1BinaryPublicAcquisition.digitStack\n      (SemiprimeD1BinaryPublicAcquisition.Digits.bankStack SemiprimeD1StackDigitBank.output))\n    (SemiprimeD1BinaryPublicAcquisition.mainLabel .start) SemiprimeD1BinaryPublicAcquisition.program bits\n  have he:=hi.trans (SemiprimeD1BinaryPublicAcquisitionExecution.initial_configuration bits).symm\n  have hd:=congrArg (fun cfg:SemiprimeD1BinaryPublicAcquisition.machine.Cfg=>cfg.stk (some k)) he\n  exact hd.symm\n/-- Exact physical template shape: binary N and descriptor index markers ONLY.\nEvery raw/result/arithmetic/cache/private/shadow role is initially empty. -/\ntheorem template_only (bits indexWord : List Bool) (k : P.Stack) :\n    inputTemplate bits indexWord k=\n      if k=.inl SemiprimeD1StackPublicInput.H.original then bits else if k=P.index then indexWord else [] := by\n  rcases k with k|k\n  · rcases k with k|k\n    · change SemiprimeD1BinaryPublicAcquisition.input bits k=\n        if (Sum.inl (Sum.inl k):P.Stack)=.inl SemiprimeD1StackPublicInput.H.original then bits\n        else if (Sum.inl (Sum.inl k):P.Stack)=P.index then indexWord else []\n      rw [public_input_only]\n      simp only [SemiprimeD1StackPublicInputWidth.original,SemiprimeD1StackPublicInput.index,\n        Sum.inl.injEq,Sum.inl_ne_inr,ite_false]\n    · change (if k=SemiprimeD1StackInputWidth.Stack.indexCache then indexWord else [])=\n        if (Sum.inl (Sum.inr k):P.Stack)=.inl SemiprimeD1StackPublicInput.H.original then bits\n        else if (Sum.inl (Sum.inr k):P.Stack)=P.index then indexWord else []\n      simp only [SemiprimeD1StackPublicInputWidth.original,SemiprimeD1StackPublicInput.index,\n        Sum.inl.injEq,Sum.inr_ne_inl,Sum.inr.injEq,ite_false]\n  · rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · cases k;rfl\nend RiemannGaussian.SemiprimeD1StackPublicInputTableTrace\n","RiemannGaussian.SemiprimeD1StackPublicProductBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicProductExecution\nimport RiemannGaussian.SemiprimeD1StackRootSourceOriginal\n\n/-! # Whole original-input public product clock and every-prefix inventory -/\nset_option autoImplicit false\nset_option synthInstance.maxSize 4096\nset_option maxHeartbeats 1200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPublicProductBounds\nopen SemiprimeD1StackPublicProduct SemiprimeD1StackPublicProductExecution\n/-- Exact actual modulus word width from the original preprocessing trace. -/\ntheorem cached_length (bits : List Bool) :\n    (cached bits).length=SemiprimeMacroParameters.transformLength bits.length+1 :=\n  SemiprimeD1StackRootSourceOriginal.modulus_length bits\n/-- The actual cached modulus has linearly many cells in ORIGINAL binary N. -/\ntheorem cached_length_le (bits : List Bool) : (cached bits).length≤66*(bits.length+1) := by\n  rw [cached_length]\n  have h:=(SemiprimeD1StackTransformArithmetic.prefix_powers bits.length _ le_rfl).1\n  change SemiprimeMacroParameters.transformLength bits.length≤64*bits.length+1 at h\n  omega\n/-- A fixed original-input cubic allowance for the complete actual program. -/\ndef runBound (bits raw : List Bool) : ℕ := 1000000000000*(bits.length+raw.length+2)^3\n/-- Acquisition and arithmetic are charged on this SAME program and original\nphysical input; no mixed/native report or supplied-size transport is used. -/\ntheorem timeBound_le (bits raw : List Bool) : timeBound bits raw≤runBound bits raw := by\n  let I:=bits.length+raw.length+2\n  have hI : 1≤I := by dsimp [I];omega\n  have hc:=cached_length_le bits\n  have hp : raw.length+(cached bits).length+3≤70*I := by dsimp [I];omega\n  have hProd : SemiprimeD1StackProductCheckBounds.runBound raw (cached bits)≤343000000000*I^3 := by\n    unfold SemiprimeD1StackProductCheckBounds.runBound\n    calc\n      _ ≤ 1000000*(70*I)^3 := Nat.mul_le_mul_left _ (Nat.pow_le_pow_left hp 3)\n      _ = _ := by ring\n  have hAcq : (bits.length+1)^2≤I^3 :=\n    (Nat.pow_le_pow_left (by dsimp [I];omega) 2).trans (Nat.pow_le_pow_right hI (by decide : 2≤3))\n  have hpos : 0<I^3 := Nat.pow_pos (by omega)\n  change _≤1000000000000*I^3\n  unfold timeBound SemiprimeD1BinaryPublicAcquisitionExecution.timeBound\n  omega\n/-- Complete actual source with its original-input cubic clock. -/\ntheorem source_run_bounded (bits raw : List Bool) (hb : bits≠[]) :\n    ∃t≤runBound bits raw,C.run program t (initial bits raw)=some (done bits raw) := by\n  obtain ⟨t,ht,hr⟩:=source_run bits raw hb\n  exact ⟨t,ht.trans (timeBound_le bits raw),hr⟩\n/-- Proof-side trace choice, never a runtime result or clock opcode. -/\nnoncomputable def sourceCheck (bits raw : List Bool) (hb : bits≠[]) :\n    StateTransition.EvalsToInTime (C.step program) (initial bits raw) (some (done bits raw)) (runBound bits raw) := by\n  let h:=source_run_bounded bits raw hb\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Genuine finite-machine original N+raw assignment certificate. -/\nnoncomputable def machineCheck (bits raw : List Bool) (hb : bits≠[]) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial bits raw))\n      (some (SemiprimeD1StackCalls.configuration (done bits raw))) (runBound bits raw) :=\n  SemiprimeD1StackCalls.evalsCorrect original output Label.start program _ _ _ (sourceCheck bits raw hb)\n/-- No successful execution prefix continues beyond its bounded complete halt. -/\ntheorem prefix_fuel_le (bits raw : List Bool) (hb : bits≠[]) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial bits raw)=some out) : fuel≤runBound bits raw := by\n  obtain ⟨t,ht,hh⟩:=source_run_bounded bits raw hb\n  have hf : fuel≤t := by\n    by_contra hn\n    have he : fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hh,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz : C.run program 1 (done bits raw)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- Initial inputs consist of actual original N and actual assignment bytes. -/\ntheorem initial_length (bits raw : List Bool) (k : Stack) :\n    ((initial bits raw).data k).length≤bits.length+raw.length := by\n  rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k\n      · cases k <;> simp only [initial,input,P.input,SemiprimeD1BinaryPublicAcquisition.store,\n          SemiprimeD1BinaryPublicAcquisition.Digits.input,SemiprimeD1BinaryDigitAcquisition.store,\n          SemiprimeD1StackTransform.input,Sum.elim_inl,List.length_nil] <;> omega\n      · rcases k with k|k <;> exact Nat.zero_le _\n    · rcases k with k|k <;> exact Nat.zero_le _\n  · change (V.input raw [] k).length≤bits.length+raw.length\n    unfold SemiprimeD1StackProductCheck.input\n    split\n    · omega\n    · split <;> exact Nat.zero_le _\n/-- EVERY prefix counts ALL76 physical Boolean stack roles, retained caches,\nunused shadows, parse/arithmetic workspace AND actual return-label cells. -/\ntheorem prefix_cells (bits raw : List Bool) (hb : bits≠[]) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial bits raw)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤\n      100000000000000*(bits.length+raw.length+2)^3 := by\n  let I:=bits.length+raw.length\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel I _ out (initial_length bits raw) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs : (∑k : Stack,(out.data k).length)≤76*(I+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(I+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le bits raw hb fuel out hr\n  change fuel≤1000000000000*(I+2)^3 at ht\n  have hI : I≤(I+2)^3 := by\n    have h:=Nat.pow_le_pow_right (by omega : 1≤I+2) (by decide : 1≤3)\n    simp only [pow_one] at h\n    omega\n  change _≤100000000000000*(I+2)^3\n  omega\n/-- Identical all-prefix inventory for the SAME genuine finite machine. -/\ntheorem machine_prefix_cells (bits raw : List Bool) (hb : bits≠[]) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits raw)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      100000000000000*(bits.length+raw.length+2)^3 := by\n  have he:=SemiprimeD1StackCalls.run_correct original output Label.start program fuel (initial bits raw)\n  change (C.run program fuel (initial bits raw)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits raw))) at he\n  have hh:=he.trans hr\n  cases hc:C.run program fuel (initial bits raw) with\n  | none => rw [hc] at hh;cases hh\n  | some out =>\n    rw [hc] at hh\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits raw hb fuel out hc\nend RiemannGaussian.SemiprimeD1StackPublicProductBounds\n","RiemannGaussian.SemiprimeD1StackPublicScaleRecordClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicScaleRecordBounds\nimport RiemannGaussian.SemiprimeD1StackStaticRecordClock\n/-! # Closed concrete actual scale-record clock from physical scope metadata -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 100000\nset_option maxHeartbeats 1200000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicScaleRecordClock\nopen SemiprimeD1StackPublicScaleRecord SemiprimeD1StackPublicScaleRecordExecution\n/-- Fixed degree-sixteen polynomial per physically acquired scalar, plus paid\nbinary-to-unary ordinal conversion and every original tensor framing byte. -/\ndef runBound (bits stride frequency : List Bool) (_inverse : Bool) (words : List (List Bool)) (M : Nat) : Nat :=\n  SemiprimeD1StackPublicScaleTableBounds.runBound bits stride frequency words+\n    110*(words.length+1)*(M+1)+21*2^words.length+20\n/-- The complete actual own source clock, without native report transport. -/\ntheorem timeBound_le (bits stride frequency : List Bool) (inverse : Bool) (words : List (List Bool)) (M : Nat)\n    (hl : ∀w∈words,w.length≤M) (hv : ∀w∈words,SemiprimeBitArithmetic.bitValue w≤M) :\n    timeBound bits stride frequency inverse words≤runBound bits stride frequency inverse words M := by\n  have h:=SemiprimeD1StackStaticRecordClock.timeBound_le I.static (I.inputTemplate bits stride frequency inverse)\n    words (T.answer bits stride frequency inverse) (T.budget bits stride frequency) M hl hv\n  have ht:=SemiprimeD1StackPublicScaleTableBounds.timeBound_le bits stride frequency inverse words\n  change SemiprimeD1StackStaticTableBounds.runBound I.static (I.inputTemplate bits stride frequency inverse)\n    words (T.budget bits stride frequency)≤_ at ht\n  change timeBound bits stride frequency inverse words≤_ at h\n  unfold runBound\n  omega\n/-- Every real static-table/scoping/logging transition obeys this closed bound. -/\ntheorem source_run_bounded (bits stride frequency : List Bool) (inverse : Bool) (hj : stride=SemiprimeD1StackUnaryDivmod.unary stride.length)\n    (hk : frequency=SemiprimeD1StackUnaryDivmod.unary frequency.length)\n    (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<SemiprimeBitArithmetic.bitValue bits) (words : List (List Bool))\n    (M : Nat) (hl : ∀w∈words,w.length≤M) (hv : ∀w∈words,SemiprimeBitArithmetic.bitValue w≤M)\n    (hist out : List Bool) :\n    ∃t≤runBound bits stride frequency inverse words M,SemiprimeD1StackCalls.run program t\n      (initial bits stride frequency inverse (SemiprimeD1TensorTapeCodec.vectorBits words) hist out)=\n      some (done bits stride frequency inverse words hist out) := by\n  obtain ⟨t,ht,hr⟩:=source_run bits stride frequency inverse hj hk hc hN words hist out\n  exact ⟨t,ht.trans (timeBound_le bits stride frequency inverse words M hl hv),hr⟩\nend RiemannGaussian.SemiprimeD1StackPublicScaleRecordClock\n","RiemannGaussian.SemiprimeD1StackPublicTransformLoopState":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicTransformGuards\n/-! # Actual loop cache invariants, with physical frequency/remaining counters\nEvery Nat below indexes a correctness specification of unary stack data; no Nat,\nword-list, source AST or callback is a register or executing loop argument.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicTransformLoopState\nopen SemiprimeD1StackPublicTransform SemiprimeD1StackPublicTransformState\nopen SemiprimeD1StackPublicTransformWords SemiprimeD1StackPublicTransformGuards\nopen SemiprimeD1StackPublicTransformMetadata\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- Actual retained dot arguments, populated by original acquisition/copies.\nFrequency here is a proof-side unary counter specification, not native control. -/\ndef queryCache (bits raw : List Bool) (second inverse : Bool) (frequency : ℕ) : SemiprimeD1StackExprDot.Cache :=\n  ⟨baseCode bits inverse,stride bits second,unary frequency,count bits second,\n    vectorBits (inputs (rootData bits) raw second)⟩\n/-- Actual reached accepted-frontend cache image, before output iteration. -/\ndef baseParts (bits raw : List Bool) (second inverse : Bool) : Parts := loopReady (rootData bits) raw second inverse\n/-- Literal remaining/frequency counter values in an otherwise retained cache.\nOnly a proof view; the executed loop manipulates these markers by pop/copy. -/\ndef steady (bits raw : List Bool) (second inverse : Bool) (remaining frequency : ℕ) : Parts :=\n  set (set (baseParts bits raw second inverse) (.dot (.inl .frequency)) (unary frequency)) (.aux .remaining) (unary remaining)\n/-- Exact two physical updates defining the loop-state image. -/\ntheorem steady_data (bits raw : List Bool) (second inverse : Bool) (remaining frequency : ℕ) :\n    data (steady bits raw second inverse remaining frequency)=\n      Function.update (Function.update (data (baseParts bits raw second inverse)) (.dot (.inl .frequency)) (unary frequency))\n        (.aux .remaining) (unary remaining) := by rw [steady,data_set,data_set]\n/-- Actual output counter is exactly its physically acquired/copied unary cache. -/\ntheorem remaining_value (bits raw : List Bool) (second inverse : Bool) (remaining frequency : ℕ) :\n    data (steady bits raw second inverse remaining frequency) (.aux .remaining)=unary remaining := by\n  rw [steady_data,Function.update_same]\n/-- Actual frequency markers are physically stored, not a native index getter. -/\ntheorem frequency_value (bits raw : List Bool) (second inverse : Bool) (remaining frequency : ℕ) :\n    data (steady bits raw second inverse remaining frequency) (.dot (.inl .frequency))=unary frequency := by\n  rw [steady_data,Function.update_of_ne (by decide : Stack.dot (.inl .frequency)≠.aux .remaining),Function.update_same]\n/-- Replacing an actual remaining counter preserves all cache/source bytes. -/\ntheorem remaining_update (bits raw : List Bool) (second inverse : Bool) (remaining frequency next : ℕ) :\n    Function.update (data (steady bits raw second inverse remaining frequency)) (.aux .remaining) (unary next)=\n      data (steady bits raw second inverse next frequency) := by\n  rw [steady_data,Function.update_idem,steady_data]\n/-- Replacing actual frequency markers preserves every other physical role. -/\ntheorem frequency_update (bits raw : List Bool) (second inverse : Bool) (remaining frequency next : ℕ) :\n    Function.update (data (steady bits raw second inverse remaining frequency)) (.dot (.inl .frequency)) (unary next)=\n      data (steady bits raw second inverse remaining next) := by\n  rw [steady_data,steady_data]\n  rw [Function.update_comm (by decide : Stack.aux .remaining≠.dot (.inl .frequency)),Function.update_idem]\n/-- The ACTUAL ready frontend is exactly the initial loop image with acquired n\nand zero frequency, without a supplied count/stride answer. -/\ntheorem loop_initial (bits raw : List Bool) (second inverse : Bool) :\n    data (steady bits raw second inverse (size bits second) 0)=data (baseParts bits raw second inverse) := by\n  rw [steady_data]\n  have hf : data (baseParts bits raw second inverse) (.dot (.inl .frequency))=[] := rfl\n  have hr : data (baseParts bits raw second inverse) (.aux .remaining)=unary (size bits second) := count_unary bits second\n  change Function.update (Function.update (data (baseParts bits raw second inverse)) (.dot (.inl .frequency)) [])\n    (.aux .remaining) (unary (size bits second))=_\n  rw [←hf,Function.update_eq_self,←hr,Function.update_eq_self]\n/-- Actual dot input/cache/modulus state at each physical frequency. -/\ntheorem steady_dot (bits raw : List Bool) (second inverse : Bool) (remaining frequency : ℕ) :\n    (steady bits raw second inverse remaining frequency).dot=\n      (D.initial (queryCache bits raw second inverse frequency) (cached bits) []).data := by\n  funext k;rcases k with k|k <;> cases k <;> rfl\n/-- Actual multiplier remains fresh between queries with acquired M preserved. -/\ntheorem steady_multiply (bits raw : List Bool) (second inverse : Bool) (remaining frequency : ℕ) :\n    (steady bits raw second inverse remaining frequency).multiplication=(M.initial [] [] (cached bits)).data := by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k\n    · cases k <;> rfl\n    · rcases k with k|k\n      · fin_cases k <;> rfl\n      · cases k <;> rfl\n  · rcases k with k|k\n    · rcases k with k|k <;> cases k <;> rfl\n    · cases k <;> rfl\n/-- Output reader cache contains the actual produced vector, all query/work empty. -/\ntheorem steady_reader (bits raw : List Bool) (second inverse : Bool) (remaining frequency : ℕ) :\n    (steady bits raw second inverse remaining frequency).reader=\n      SemiprimeD1StackJetRead.store (vectorBits (outputs (rootData bits) raw second)) [] [] [] [] [] [] [] := by\n  funext k;cases k <;> rfl\n/-- Streaming equality has no stale operand or returned truth between queries. -/\ntheorem steady_equal (bits raw : List Bool) (second inverse : Bool) (remaining frequency : ℕ) :\n    (steady bits raw second inverse remaining frequency).equality=SemiprimeD1StackAdder.store [] [] [] [] := by\n  funext k;cases k <;> rfl\n/-- The original normalizer copy is retained at every actual loop state. -/\ntheorem steady_normalizer (bits raw : List Bool) (second inverse : Bool) (remaining frequency : ℕ) :\n    data (steady bits raw second inverse remaining frequency) (.aux .normalizer)=normalizer bits second inverse := rfl\n/-- Actual inter-component copy scratch is empty between queries. -/\ntheorem steady_scratch (bits raw : List Bool) (second inverse : Bool) (remaining frequency : ℕ) :\n    data (steady bits raw second inverse remaining frequency) (.aux .scratch)=[] := rfl\nend RiemannGaussian.SemiprimeD1StackPublicTransformLoopState\n","RiemannGaussian.SemiprimeD1StackRationalNormalizeSetup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRationalNormalizeCalls\n/-! # Paid two-word sign acquisition and actual total denominator guard -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRationalNormalizeSetup\nopen SemiprimeD1StackRationalNormalize SemiprimeD1StackRationalNormalizeEncoding SemiprimeD1StackRationalNormalizeCalls\nopen SemiprimeD1StackProcedureTrace\n/-- The actual OR scan consumes every copied denominator byte, including high-zero padding. -/\ntheorem scan_run (seen:Bool) (w:Words) (xs:List Bool) :\n    Runs program (xs.length+1) (.scan seen) (bank {w with scan:=xs})\n      (if seen||(SemiprimeBitDivision.nonzeroBits xs).nonzero then .gcdCall else .zeroClearSign)\n      (bank {w with scan:=[]}) :=by\n  induction xs generalizing seen with\n  | nil=>\n    have h:=P.pop_run (.scan seen) (if seen then .gcdCall else .zeroClearSign) (.scan seen) (.scan true)\n      scan (bank {w with scan:=[]}) [] rfl rfl\n    change Runs _ _ _ _ _ (Function.update (bank _) (gcdStack (SemiprimeD1StackEuclidGCD.aux .scan)) []) at h\n    rw [update_scan] at h\n    change Runs program 1 (.scan seen) (bank {w with scan:=[]})\n      (if seen then .gcdCall else .zeroClearSign) (bank {w with scan:=[]}) at h\n    simpa only [SemiprimeBitDivision.nonzeroBits,Bool.or_false,List.length_nil,Nat.zero_add] using h\n  | cons b xs ih=>\n    have h0:=P.pop_run (.scan seen) (if seen then .gcdCall else .zeroClearSign) (.scan seen) (.scan true)\n      scan (bank {w with scan:=b::xs}) (b::xs) rfl rfl\n    change Runs _ _ _ _ _ (Function.update (bank _) (gcdStack (SemiprimeD1StackEuclidGCD.aux .scan)) xs) at h0\n    rw [update_scan] at h0\n    cases b with\n    | false=>\n      have h:=P.join h0 (ih seen)\n      simpa only [List.length_cons,SemiprimeBitDivision.nonzeroBits,Bool.false_or,Nat.add_comm] using h\n    | true=>\n      have h:=P.join h0 (ih true)\n      simpa only [List.length_cons,SemiprimeBitDivision.nonzeroBits,Bool.true_or,Bool.or_true,Nat.add_comm] using h\n/-- Exact actual clock for preserving-copy/sign-pop/sign-push plus preserving-copy/full denominator scan. -/\ndef setupTime (num den:List Bool) :Nat:=(5*(num.length+1)+4)+1+1+(5*den.length+4)+(den.length+1)\n/-- Original signed word and denominator are the ONLY two initialized operands; magnitude/sign are acquired by real instructions. -/\ntheorem setup_run (negative:Bool) (num den:List Bool) :\n    Runs program (setupTime num den) .start (input (negative::num) den)\n      (if (SemiprimeBitDivision.nonzeroBits den).nonzero then .gcdCall else .zeroClearSign)\n      (bank (parsed negative num den)) :=by\n  rw [initial_bank]\n  have h0:=P.copy_call .signedInput .start .parseSign rfl\n    (bank {originalSigned:=negative::num,originalRight:=den}) (negative::num) [] rfl rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (gcdStack (SemiprimeD1StackEuclidGCD.aux .left)) ((negative::num)++[])) at h0\n  rw [List.append_nil,update_originalLeft] at h0\n  have h1:=P.pop_run .parseSign .abort (.initializeSign false) (.initializeSign true) numerator\n    (bank {originalSigned:=negative::num,originalRight:=den,originalLeft:=negative::num}) (negative::num) rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (gcdStack (SemiprimeD1StackEuclidGCD.aux .left)) num) at h1\n  rw [update_originalLeft] at h1\n  have he:SemiprimeD1StackBytecode.choose Label.abort (.initializeSign false) (.initializeSign true) (negative::num).head?=\n      .initializeSign negative:=by cases negative <;> rfl\n  rw [he] at h1\n  have h2:=P.push_run (.initializeSign negative) .guardDen (aux .signOutput) negative\n    (bank {originalSigned:=negative::num,originalRight:=den,originalLeft:=num}) rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (aux .signOutput) [negative]) at h2\n  rw [update_signOutput] at h2\n  have h3:=P.copy_call .guard .guardDen (.scan false) rfl (bank (parsed negative num den)) den [] rfl rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (gcdStack (SemiprimeD1StackEuclidGCD.aux .scan)) (den++[])) at h3\n  rw [List.append_nil,update_scan] at h3\n  have h4:=scan_run false (parsed negative num den) den\n  have h:=P.join (P.join (P.join (P.join h0 h1) h2) h3) h4\n  simpa only [setupTime,List.length_cons,Bool.false_or,parsed] using h\n/-- A numeric-zero physical denominator takes the literal legacy zero branch, clearing its acquired sign and magnitude. -/\ntheorem zero_run (negative:Bool) (num den:List Bool) :\n    Runs program (2+1+1+(num.length+1)) .zeroClearSign (bank (parsed negative num den)) .done\n      (bank {originalSigned:=negative::num,originalRight:=den,signOutput:=[false],denominatorOutput:=[true]}) :=by\n  have h0:=P.drain_loop .zeroClearSign .zeroSign (aux .signOutput) rfl (bank (parsed negative num den)) [negative] rfl\n  rw [update_signOutput] at h0\n  have h1:=P.push_run .zeroSign .zeroDen (aux .signOutput) false\n    (bank {originalSigned:=negative::num,originalRight:=den,originalLeft:=num}) rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (aux .signOutput) [false]) at h1\n  rw [update_signOutput] at h1\n  have h2:=P.push_run .zeroDen .clearMagnitude (aux .denominatorOutput) true\n    (bank {originalSigned:=negative::num,originalRight:=den,originalLeft:=num,signOutput:=[false]}) rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (aux .denominatorOutput) [true]) at h2\n  rw [update_denominatorOutput] at h2\n  have h3:=P.drain_loop .clearMagnitude .done numerator rfl\n    (bank {originalSigned:=negative::num,originalRight:=den,originalLeft:=num,signOutput:=[false],denominatorOutput:=[true]}) num rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (gcdStack (SemiprimeD1StackEuclidGCD.aux .left)) []) at h3\n  rw [update_originalLeft] at h3\n  exact P.join (P.join (P.join h0 h1) h2) h3\nend RiemannGaussian.SemiprimeD1StackRationalNormalizeSetup\n","RiemannGaussian.SemiprimeD1StackRationalOperationAdd":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRationalOperationCalls\n/-! # Literal signed addition, borrow-driven operand reversal and exact cancellation sign -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRationalOperationAdd\nopen SemiprimeD1StackRationalOperation SemiprimeD1StackRationalOperationEncoding\nopen SemiprimeD1StackRationalOperationCalls SemiprimeD1StackProcedureTrace\nopen SemiprimeBitArithmetic (addBits)\nopen SemiprimeBitDivision (subBits)\n/-- Both actual cross-products, in the subtraction orientation selected by real borrow. -/\ndef left (w:Words) (rev:Bool) :List Bool:=if rev then w.output else w.originalLeft\n/-- The other actual cross-product, preserving legacy operand order. -/\ndef right (w:Words) (rev:Bool) :List Bool:=if rev then w.originalLeft else w.output\n/-- Both acquired cross-products are physically copied into the actual ripple inputs. -/\ntheorem prepare_run (rev:Bool) (op:Op) (sx sy:Bool) (w:Words) (hs:w.copyScratch=[]) :\n    Runs program ((5*(left w rev).length+4)+(5*(right w rev).length+4))\n      (localLabel (.addLeft rev) op sx sy) (bank (rippleReady w [] []))\n      (localLabel (.combine rev) op sx sy) (bank (rippleReady w (left w rev) (right w rev))):=by\n  have h0:=P.copy_call (.addLeft rev) (localLabel (.addLeft rev) op sx sy) (localLabel (.addRight rev) op sx sy) rfl\n    (bank (rippleReady w [] [])) (left w rev) [] (by cases rev <;> rfl) rfl hs\n  change Runs _ _ _ _ _ (Function.update (bank _) (adderStack .left) ((left w rev)++[])) at h0\n  rw [List.append_nil,adderStack,update_left] at h0\n  change Runs program _ _ _ _ (bank (rippleReady w (left w rev) [])) at h0\n  have h1:=P.copy_call (.addRight rev) (localLabel (.addRight rev) op sx sy) (localLabel (.combine rev) op sx sy) rfl\n    (bank (rippleReady w (left w rev) [])) (right w rev) [] (by cases rev <;> rfl) rfl hs\n  change Runs _ _ _ _ _ (Function.update (bank _) (adderStack .right) ((right w rev)++[])) at h1\n  rw [List.append_nil,adderStack,update_right] at h1\n  exact P.join h0 h1\n/-- Exact raw output copy and actual complete ripple-output drain. -/\ndef saveTime (bits:List Bool) :Nat:=(5*bits.length+4)+(bits.length+1)\n/-- The acquired raw numerator is copied before the consumed difference is physically erased. -/\ntheorem save_run (negative:Bool) (op:Op) (sx sy:Bool) (w:Words) (bits:List Bool)\n    (hs:w.copyScratch=[]) (hz:w.originalSigned=[]) :\n    Runs program (saveTime bits) (localLabel (.addSave negative) op sx sy)\n      (bank (rippleDone w bits)) (localLabel (.rawSign negative) op sx sy)\n      (bank (rippleDone {w with originalSigned:=bits} [])):=by\n  have h0:=P.copy_call .addSave (localLabel (.addSave negative) op sx sy) (localLabel (.clearDifference negative) op sx sy) rfl\n    (bank (rippleDone w bits)) bits [] rfl hz hs\n  change Runs _ _ _ _ _ (Function.update (bank _) (normalizeStack (SemiprimeD1StackRationalNormalize.aux .originalSigned)) (bits++[])) at h0\n  rw [List.append_nil,update_originalSigned] at h0\n  have h1:=P.drain_loop (localLabel (.clearDifference negative) op sx sy) (localLabel (.rawSign negative) op sx sy)\n    (adderStack .output) rfl (bank {rippleDone w bits with originalSigned:=bits}) bits rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (normalizeStack (SemiprimeD1StackRationalNormalize.dividerStack (.inl .output))) []) at h1\n  rw [update_difference] at h1\n  exact P.join h0 h1\n/-- Actual same-sign full adder time, including real caller return. -/\ndef addTime (xs ys:List Bool) :Nat:=3*(max xs.length ys.length+1)+2*(addBits xs ys false).bits.length+2+1\n/-- Actual full subtractor time, including borrow byte and real caller return. -/\ndef subtractTime (xs ys:List Bool) :Nat:=3*(max xs.length ys.length+1)+2*(subBits xs ys false).result.bits.length+3+1\n/-- Both preserving cross-product copies are paid in their real physical orientation. -/\ndef prepareTime (xs ys:List Bool) :Nat:=(5*xs.length+4)+(5*ys.length+4)\n/-- Own complete signed-add trace clock, selected only by actual signs/borrow bits. -/\ndef sumTime (sx:Bool) (xs:List Bool) (sy:Bool) (ys:List Bool) :Nat:=\n  prepareTime xs ys+\n    (if sx=sy then addTime xs ys+saveTime (addBits xs ys false).bits\n    else subtractTime xs ys+1+\n      (if (subBits xs ys false).borrow then\n        ((subBits xs ys false).result.bits.length+1)+prepareTime ys xs+subtractTime ys xs+1+\n          saveTime (subBits ys xs false).result.bits\n      else saveTime (subBits xs ys false).result.bits))\n/-- The actual borrow byte is popped, retaining only actual difference bytes and every other caller word. -/\ntheorem borrow_run (rev:Bool) (op:Op) (sx sy:Bool) (w:Words) (b:Bool) (bits:List Bool) :\n    Runs program 1 (localLabel (.borrow rev) op sx sy) (bank (rippleDone w (b::bits)))\n      (localLabel (if b then (if rev then .addSave sy else .discardDifference) else .addSave (if rev then sy else sx)) op sx sy)\n      (bank (rippleDone w bits)):=by\n  have h:=P.pop_run (localLabel (.borrow rev) op sx sy) (localLabel .abort op sx sy)\n    (localLabel (.addSave (if rev then sy else sx)) op sx sy)\n    (if rev then localLabel (.addSave sy) op sx sy else localLabel .discardDifference op sx sy)\n    (adderStack .output) (bank (rippleDone w (b::bits))) (b::bits) rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (normalizeStack (SemiprimeD1StackRationalNormalize.dividerStack (.inl .output))) bits) at h\n  rw [update_difference] at h\n  cases b <;> cases rev <;> exact h\n/-- The physically rejected wrapped difference is actually consumed before reversed subtraction. -/\ntheorem discard_run (op:Op) (sx sy:Bool) (w:Words) (bits:List Bool) :\n    Runs program (bits.length+1) (localLabel .discardDifference op sx sy) (bank (rippleDone w bits))\n      (localLabel (.addLeft true) op sx sy) (bank (rippleReady w [] [])):=by\n  have h:=P.drain_loop (localLabel .discardDifference op sx sy) (localLabel (.addLeft true) op sx sy)\n    (adderStack .output) rfl (bank (rippleDone w bits)) bits rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (normalizeStack (SemiprimeD1StackRationalNormalize.dividerStack (.inl .output))) []) at h\n  rw [update_difference] at h\n  exact h\n/-- Exact legacy signed-sum bytes and tie sign are acquired by real ripple calls and actual borrow branching. -/\ntheorem sum_run (op:Op) (sx sy:Bool) (w:Words) (hs:w.copyScratch=[]) (hz:w.originalSigned=[]) :\n    let result:SemiprimeBitIndexClipping.SignedWord:=\n      (SemiprimeBitIndexClipping.addSignedBits ⟨sx,w.originalLeft⟩ ⟨sy,w.output⟩).word\n    Runs program (sumTime sx w.originalLeft sy w.output) (localLabel (.addLeft false) op sx sy)\n      (bank (rippleReady w [] [])) (localLabel (.rawSign result.negative) op sx sy)\n      (bank (rippleDone {w with originalSigned:=result.magnitude} [])):=by\n  dsimp only\n  have h0:=prepare_run false op sx sy w hs\n  by_cases he:sx=sy\n  · have h1:=adder_call w w.originalLeft w.output (localLabel (.combine false) op sx sy) (localLabel (.addSave sx) op sx sy)\n      (by simp only [program,localLabel,he,ite_true])\n    have h2:=save_run sx op sx sy w (addBits w.originalLeft w.output false).bits hs hz\n    have h:=P.join h0 (P.join h1 h2)\n    simpa only [left,right,Bool.false_eq_true,ite_false,ite_true,Nat.add_assoc,sumTime,prepareTime,addTime,SemiprimeBitIndexClipping.addSignedBits,he,ite_true] using h\n  · have h1:=subtractor_call w w.originalLeft w.output (localLabel (.combine false) op sx sy) (localLabel (.borrow false) op sx sy)\n      (by simp only [program,localLabel,he,ite_false])\n    have h2:=borrow_run false op sx sy w (subBits w.originalLeft w.output false).borrow (subBits w.originalLeft w.output false).result.bits\n    cases hb:(subBits w.originalLeft w.output false).borrow with\n    | false=>\n      rw [hb] at h1 h2\n      have h3:=save_run sx op sx sy w (subBits w.originalLeft w.output false).result.bits hs hz\n      have h:=P.join h0 (P.join (P.join h1 h2) h3)\n      simpa only [left,right,Bool.false_eq_true,ite_false,ite_true,Nat.add_assoc,sumTime,prepareTime,subtractTime,SemiprimeBitIndexClipping.addSignedBits,he,hb,\n        Bool.false_eq_true,ite_false] using h\n    | true=>\n      rw [hb] at h1 h2\n      have h3:=discard_run op sx sy w (subBits w.originalLeft w.output false).result.bits\n      have h4:=prepare_run true op sx sy w hs\n      have h5:=subtractor_call w w.output w.originalLeft (localLabel (.combine true) op sx sy) (localLabel (.borrow true) op sx sy)\n        (by simp only [program,localLabel,he,ite_false])\n      have h6:=borrow_run true op sx sy w (subBits w.output w.originalLeft false).borrow (subBits w.output w.originalLeft false).result.bits\n      have hx:(if (subBits w.output w.originalLeft false).borrow then (if true then Phase.addSave sy else .discardDifference)\n          else .addSave (if true then sy else sx))=Phase.addSave sy:=by\n        cases (subBits w.output w.originalLeft false).borrow <;> rfl\n      rw [hx] at h6\n      have h7:=save_run sy op sx sy w (subBits w.output w.originalLeft false).result.bits hs hz\n      have h:=P.join h0 (P.join (P.join h1 h2) (P.join h3 (P.join h4 (P.join (P.join h5 h6) h7))))\n      simpa only [left,right,Bool.false_eq_true,ite_false,ite_true,Nat.add_assoc,sumTime,prepareTime,subtractTime,SemiprimeBitIndexClipping.addSignedBits,he,hb,ite_true] using h\nend RiemannGaussian.SemiprimeD1StackRationalOperationAdd\n","RiemannGaussian.SemiprimeD1StackRationalOperationBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRationalOperationExecution\nimport RiemannGaussian.SemiprimeD1StackWordFitBounds\n/-! # Own fixed polynomial in the five actual input byte lengths\nThe template width is paid by its actual cells. Numeric numerator and\ndenominator values stay binary; every raw-product padding and quotient width\nis bounded before real normalization and both physical fits are charged.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRationalOperationBounds\nopen SemiprimeD1StackRationalOperation SemiprimeD1StackRationalOperationEncoding\nopen SemiprimeD1StackRationalOperationCalls SemiprimeD1StackRationalOperationSetup\nopen SemiprimeD1StackRationalOperationProduct SemiprimeD1StackRationalOperationAdd\nopen SemiprimeD1StackRationalOperationRaw SemiprimeD1StackRationalOperationFinish\nopen SemiprimeD1StackRationalOperationExecution\nopen SemiprimeBitArithmetic (mulBits addBits)\nopen SemiprimeBitDivision (subBits)\n/-- SAME real multiplier trace and copies/drain, bounded from original physical operand lengths. -/\ntheorem productTime_le (xs ys:List Bool) (s:Nat) (hs:1 ≤ s) (hx:xs.length ≤ s) (hy:ys.length ≤ s) :\n    productTime xs ys ≤ 3000*s^3:=by\n  have ht:=SemiprimeD1StackMultiplierExecution.source_time xs ys\n  have hm:=SemiprimeBitArithmetic.mulBits_length xs ys\n  have hmul:xs.length*(ys.length+2) ≤ s*(s+2):=Nat.mul_le_mul hx (by omega)\n  have hprod:(xs.length+1)*(xs.length*(ys.length+2)+ys.length+3) ≤ (s+1)*(s*(s+2)+s+3):=\n    Nat.mul_le_mul (by omega) (by omega)\n  have hs1:s ≤ s^3:=Nat.le_pow (by decide:0<3)\n  have hs2:s^2 ≤ s^3:=Nat.pow_le_pow_right hs (by decide:2 ≤ 3)\n  unfold productTime SemiprimeD1StackMultiplierExecution.timeBound at *\n  nlinarith\n/-- Real signed-add copies, both possible subtractors, actual borrow reads and cleanup are linear in actual cross-product bytes. -/\ntheorem sumTime_le (sx:Bool) (xs:List Bool) (sy:Bool) (ys:List Bool) (s:Nat)\n    (hs:1 ≤ s) (hx:xs.length ≤ s) (hy:ys.length ≤ s) :sumTime sx xs sy ys ≤1000*s:=by\n  have ha:=(SemiprimeBitArithmetic.addBits_counts xs ys false).2.2.2.2\n  have hl:=(SemiprimeBitDivision.subBits_counts xs ys false).2.2.2.2\n  have hr:=(SemiprimeBitDivision.subBits_counts ys xs false).2.2.2.2\n  have hm:max xs.length ys.length ≤ s:=max_le hx hy\n  have hm':max ys.length xs.length ≤ s:=max_le hy hx\n  unfold sumTime prepareTime addTime subtractTime saveTime\n  split\n  · omega\n  · split <;> omega\n/-- The actual raw result has linear physical width even when input words carry high zero padding. -/\ntheorem raw_width (op:Op) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd:List Bool)\n    (s:Nat) (hxn:xn.length ≤ s) (hxd:xd.length ≤ s) (hyn:yn.length ≤ s) (hyd:yd.length ≤ s) :\n    (rawWord op sx xn xd sy yn yd).numerator.magnitude.length ≤3*s+1 ∧\n    (rawWord op sx xn xd sy yn yd).denominator.length ≤3*s+1:=by\n  rw [rawWord_legacy]\n  exact (SemiprimeRationalBits.rawOperation_cost_width (operation op) _ _ ⟨hxn,hxd⟩ ⟨hyn,hyd⟩).2\n/-- All four actual raw-operation branches have a fixed cubic clock in their input bytes. -/\ntheorem rawTime_le (op:Op) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd:List Bool)\n    (s:Nat) (hs:1 ≤ s) (hxn:xn.length ≤ s) (hxd:xd.length ≤ s) (hyn:yn.length ≤ s) (hyd:yd.length ≤ s) :\n    rawTime op sx xn xd sy yn yd ≤1000000*s^3:=by\n  have h0:=productTime_le xn yd s hs hxn hyd\n  have h1:=productTime_le yn xd s hs hyn hxd\n  have h2:=productTime_le xn yn s hs hxn hyn\n  have h3:=productTime_le xd yd s hs hxd hyd\n  have hl: (mulBits xn yd).bits.length ≤3*s:=by have h:=SemiprimeBitArithmetic.mulBits_length xn yd;omega\n  have hr: (mulBits yn xd).bits.length ≤3*s:=by have h:=SemiprimeBitArithmetic.mulBits_length yn xd;omega\n  have ha:=sumTime_le sx (mulBits xn yd).bits sy (mulBits yn xd).bits (3*s) (by omega) hl hr\n  have hs1:s ≤ s^3:=Nat.le_pow (by decide:0<3)\n  cases op <;> dsimp only [rawTime] <;> omega\n/-- Every actual cleanup byte, including the two raw cross-product caches, is linearly paid. -/\ntheorem cleanupTime_le (op:Op) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd template:List Bool)\n    (s:Nat) (hs:1 ≤ s) (hxn:xn.length ≤ s) (hxd:xd.length ≤ s) (hyn:yn.length ≤ s) (hyd:yd.length ≤ s) :\n    cleanupTime (rawResult op sx xn xd sy yn yd template) ≤20*s:=by\n  have hl:=SemiprimeBitArithmetic.mulBits_length xn yd\n  have hr:=SemiprimeBitArithmetic.mulBits_length yn xd\n  cases op <;> simp only [cleanupTime,rawResult,ready,leftReady,binary,List.length_nil,ite_true,ite_false,\n    reduceCtorEq] <;> omega\n/-- Exact raw normalized quotient lengths remain bounded by their actual original widths, including zero-denominator totalization. -/\ntheorem normalized_width (negative:Bool) (num den:List Bool) :\n    (normalized negative num den).numerator.magnitude.length ≤ num.length ∧\n    (normalized negative num den).denominator.length ≤ den.length+1:=by\n  unfold normalized SemiprimeD1StackRationalNormalizeSpec.word\n  split\n  · exact ⟨by simp [SemiprimeRationalBits.zeroWord],by simp [SemiprimeRationalBits.zeroWord]⟩\n  · exact ⟨(SemiprimeD1StackRationalNormalizeSpec.numerator_length num den).le,\n      (SemiprimeD1StackRationalNormalizeSpec.denominator_length num den).le.trans (by omega)⟩\n/-- SAME actual normalizer source and BOTH full WordFit calls have quartic cost in raw bytes plus actual template cells. -/\ntheorem finishTime_le (num den template:List Bool) (s:Nat) (hs:1 ≤ s)\n    (hn:num.length ≤4*s) (hd:den.length ≤4*s) (hw:template.length ≤ s) :\n    finishTime num den template ≤1000000000000000*s^4:=by\n  have hN:=SemiprimeD1StackRationalNormalizeBounds.runBound_le num den\n  have hi:SemiprimeD1StackRationalNormalizeEncoding.inputSize num den ≤10*s:=by\n    unfold SemiprimeD1StackRationalNormalizeEncoding.inputSize;omega\n  have hp: (SemiprimeD1StackRationalNormalizeEncoding.inputSize num den)^4 ≤ (10*s)^4:=Nat.pow_le_pow_left hi 4\n  have hq:=normalized_width false num den\n  have hf0:=SemiprimeD1StackWordFitBounds.totalTime_le (normalized false num den).numerator.magnitude template\n  have hf1:=SemiprimeD1StackWordFitBounds.totalTime_le (normalized false num den).denominator template\n  have hs1:s ≤ s^4:=Nat.le_pow (by decide:0<4)\n  unfold SemiprimeD1StackRationalNormalizeBounds.polynomial at hN\n  unfold finishTime\n  nlinarith only [hN,hp,hq.1,hq.2,hf0,hf1,hn,hd,hw,hs,hs1]\n/-- Coefficient/degree are fixed before the five original inputs; template VALUE-width is physically paid. -/\ndef polynomial (ls ld rs rd template:List Bool) :Nat:=100000000000000000000*(inputSize ls ld rs rd template)^6\n/-- Whole literal operation source has its OWN fixed original-byte polynomial clock; no legacy report clock is transported. -/\ntheorem runBound_le (op:Op) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd template:List Bool) :\n    runBound op sx xn xd sy yn yd template ≤ polynomial (sx::xn) xd (sy::yn) yd template:=by\n  let s:=inputSize (sx::xn) xd (sy::yn) yd template\n  have hs:1 ≤ s:=by dsimp [s,inputSize];omega\n  have hxn:xn.length ≤ s:=by dsimp [s,inputSize];omega\n  have hxd:xd.length ≤ s:=by dsimp [s,inputSize];omega\n  have hyn:yn.length ≤ s:=by dsimp [s,inputSize];omega\n  have hyd:yd.length ≤ s:=by dsimp [s,inputSize];omega\n  have hw:template.length ≤ s:=by dsimp [s,inputSize];omega\n  have hs0:setupTime op xn yn ≤30*s:=by\n    cases op <;> simp only [setupTime,binary,ite_true,Bool.false_eq_true,ite_false] <;> omega\n  have hr:=rawTime_le op sx xn xd sy yn yd s hs hxn hxd hyn hyd\n  have hc:=cleanupTime_le op sx xn xd sy yn yd template s hs hxn hxd hyn hyd\n  have hb:=raw_width op sx xn xd sy yn yd s hxn hxd hyn hyd\n  have hf:=finishTime_le (rawWord op sx xn xd sy yn yd).numerator.magnitude\n    (rawWord op sx xn xd sy yn yd).denominator template s hs (by omega) (by omega) hw\n  have hs1:s ≤ s^6:=Nat.le_pow (by decide:0<6)\n  have hs3:s^3 ≤ s^6:=Nat.pow_le_pow_right hs (by decide:3 ≤ 6)\n  have hs4:s^4 ≤ s^6:=Nat.pow_le_pow_right hs (by decide:4 ≤ 6)\n  change runBound op sx xn xd sy yn yd template ≤100000000000000000000*s^6\n  dsimp only [runBound]\n  nlinarith only [hs0,hr,hc,hf,hs,hs1,hs3,hs4]\n/-- Exact legacy fitted result from the honest five physical input words within its fixed polynomial. -/\ntheorem source_run_bounded (op:Op) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd template:List Bool) :\n    ∃q ≤ polynomial (sx::xn) xd (sy::yn) yd template,SemiprimeD1StackCalls.run program q\n      (initial op (sx::xn) xd (sy::yn) yd template)=some (done op sx xn xd sy yn yd template):=\n  ⟨runBound op sx xn xd sy yn yd template,runBound_le op sx xn xd sy yn yd template,source_run op sx xn xd sy yn yd template⟩\n/-- SAME compiled finite36-role machine uses the whole five-input own polynomial. -/\nnoncomputable def machineSource (op:Op) (sx:Bool) (xn xd:List Bool) (sy:Bool) (yn yd template:List Bool) :\n    StateTransition.EvalsToInTime (machine op).step\n      (SemiprimeD1StackCalls.configuration (initial op (sx::xn) xd (sy::yn) yd template))\n      (some (SemiprimeD1StackCalls.configuration (done op sx xn xd sy yn yd template)))\n      (polynomial (sx::xn) xd (sy::yn) yd template):=by\n  apply SemiprimeD1StackCalls.evalsCorrect (aux .leftSigned) (aux .numeratorOutput) (localLabel .start op false false) program\n  exact ⟨⟨_,source_run op sx xn xd sy yn yd template⟩,runBound_le op sx xn xd sy yn yd template⟩\nend RiemannGaussian.SemiprimeD1StackRationalOperationBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineCoefficientBuffers":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineOperationOutput\n/-! # Exact physical descending coefficient framing buffers and restored dot suffix cache -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineCoefficientBuffers\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineView\n/-- Only actual forward remaining and next-row output change during slope acquisition. -/\ndef buffers (w:Words) (remaining next:List Bool):Words:=\n  {w with added:=fun slot=>if slot=.remaining then remaining else if slot=.nextArray then next else w.added slot}\n/-- A real remaining write preserves the entire original bank and every accumulated next row. -/\ntheorem update_remaining (w:Words) (remaining next xs:List Bool):\n    Function.update (bank (buffers w remaining next)) (aux .remaining) xs=bank (buffers w xs next):=by\n  rw [update_added]\n  congr 1\n  congr 1\n  funext slot\n  cases slot <;> simp [buffers]\n/-- A real frame/tag write preserves the unread forward suffix and every other110 word. -/\ntheorem update_next (w:Words) (remaining next xs:List Bool):\n    Function.update (bank (buffers w remaining next)) (aux .nextArray) xs=bank (buffers w remaining xs):=by\n  rw [update_added]\n  congr 1\n  congr 1\n  funext slot\n  cases slot <;> simp [buffers]\n/-- Acquired scalar caches and added physical row buffers are disjoint actual data roles. -/\ntheorem put_buffers (w:Words) (r:SemiprimeD1StackRecoveryGrid.Reg) (x:SemiprimeRationalBits.RationalWord) (remaining next:List Bool):\n    putReg (buffers w remaining next) r x=buffers (putReg w r x) remaining next:=rfl\n/-- Both literal signed/denominator drains restore the original EMPTY slope cache, including W0. -/\ntheorem erase_put (w:Words) (x:SemiprimeRationalBits.RationalWord)\n    (hn:w.registers (.denPower,false)=[]) (hd:w.registers (.denPower,true)=[]):\n    SemiprimeD1StackRecoveryAffineOperationOutput.emptyReg (putReg w .denPower x) .denPower=w:=by\n  dsimp only [SemiprimeD1StackRecoveryAffineOperationOutput.emptyReg,putReg]\n  congr 1\n  congr 1\n  funext slot\n  rcases slot with ⟨r,b⟩\n  cases r <;> cases b <;> simp [hn,hd]\n/-- The two row buffers initially equal their actual existing physical words. -/\ntheorem buffers_self (w:Words):buffers w (w.added .remaining) (w.added .nextArray)=w:=by\n  unfold buffers\n  congr 1\n  funext slot\n  cases slot <;> rfl\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineCoefficientBuffers\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopeFrame":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopeParse\n/-! # Actual two-frame row prepending and both scalar-cache drains -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopeFrame\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineView\nopen SemiprimeD1StackRecoveryAffineSlopeBuffers SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace T\nexport SemiprimeD1StackRecoveryAffinePrimitives (join frame_call push_run drain_loop)\nend T\n/-- Denominator then signed numerator then TRUE tag prepend one exact row without recopying its tail. -/\ntheorem frame_run (w:Words) (x:SemiprimeRationalBits.RationalWord) (reader reversed:List Bool)\n    (hs:w.auxiliary .frameScratch=[]) :\n    Runs program ((6*x.denominator.length+5)+(6*(signed x).length+5)+1)\n      (.local (.frame (.slope true))) (bank (putReg (buffers w reader reversed) .slope x))\n      (.local (.clearSlope false false))\n      (bank (putReg (buffers w reader (SemiprimeD1StackRecoveryGridView.slopeRow x reversed)) .slope x)):=by\n  let start:=putReg w .slope x\n  rw [put_buffers]\n  have h0:=T.frame_call (.slope true) (.local (.frame (.slope true))) (.local (.frame (.slope false))) rfl\n    (bank (buffers start reader reversed)) x.denominator reversed (putReg_fields w .slope x).2 rfl hs\n  change Runs program _ _ _ _ (Function.update (bank (buffers start reader reversed))\n    (aux .reverseSlopes) (frame x.denominator reversed)) at h0\n  rw [update_reversed] at h0\n  have h1:=T.frame_call (.slope false) (.local (.frame (.slope false))) (.local .slopeTag) rfl\n    (bank (buffers start reader (frame x.denominator reversed))) (signed x) (frame x.denominator reversed)\n    (putReg_fields w .slope x).1 rfl hs\n  change Runs program _ _ _ _ (Function.update (bank (buffers start reader (frame x.denominator reversed)))\n    (aux .reverseSlopes) (frame (signed x) (frame x.denominator reversed))) at h1\n  rw [update_reversed] at h1\n  have h2:=T.push_run (.local .slopeTag) (.local (.clearSlope false false)) (aux .reverseSlopes) true\n    (bank (buffers start reader (frame (signed x) (frame x.denominator reversed)))) rfl\n  change Runs program _ _ _ _ (Function.update (bank (buffers start reader (frame (signed x) (frame x.denominator reversed))))\n    (aux .reverseSlopes) (SemiprimeD1StackRecoveryGridView.slopeRow x reversed)) at h2\n  rw [update_reversed] at h2\n  simpa only [put_buffers,start] using T.join (T.join h0 h1) h2\n/-- The two real signed/denominator drains restore the EMPTY physical scalar cache. -/\ntheorem clear_run (w:Words) (x:SemiprimeRationalBits.RationalWord) (reader reversed:List Bool)\n    (hn:w.registers (.slope,false)=[]) (hd:w.registers (.slope,true)=[]):\n    Runs program ((signed x).length+1+x.denominator.length+1)\n      (.local (.clearSlope false false)) (bank (putReg (buffers w reader reversed) .slope x))\n      (.local .reverseLoop) (bank (buffers w reader reversed)):=by\n  let start:=putReg (buffers w reader reversed) .slope x\n  let first:Words:={start with registers:=Function.update start.registers (.slope,false) []}\n  have h0:=T.drain_loop (.local (.clearSlope false false)) (.local (.clearSlope false true)) (reg .slope false) rfl\n    (bank start) (signed x) (putReg_fields (buffers w reader reversed) .slope x).1\n  rw [update_register] at h0\n  change Runs program _ _ _ _ (bank first) at h0\n  have hx:first.registers (.slope,true)=x.denominator:=by\n    change Function.update start.registers (.slope,false) [] (.slope,true)=_\n    simp only [Function.update_of_ne (show ((.slope,true):SemiprimeD1StackRecoveryGrid.Reg×Bool)≠(.slope,false) from by decide)]\n    exact (putReg_fields (buffers w reader reversed) .slope x).2\n  have h1:=T.drain_loop (.local (.clearSlope false true)) (.local .reverseLoop) (reg .slope true) rfl\n    (bank first) x.denominator hx\n  rw [update_register] at h1\n  have he:{first with registers:=Function.update first.registers (.slope,true) []}=buffers w reader reversed:=by\n    exact erase_put (buffers w reader reversed) x hn hd\n  rw [he] at h1\n  simpa only [Nat.add_assoc] using T.join h0 h1\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineSlopeFrame\n","RiemannGaussian.SemiprimeD1StackRecoveryCoordinateBlocks":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryCoordinateBlock\n/-! # Whole physical block-vector column loop\nA real final row-history reverse restores ascending block order. Empty phases\nstill acquire the literal empty vector and will be logged by the outer loop.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryCoordinateBlocks\nopen SemiprimeD1StackRecoveryCoordinate SemiprimeD1StackRecoveryCoordinateState\nopen SemiprimeD1StackRecoveryCoordinatePrimitives SemiprimeD1StackRecoveryCoordinateLogger\nopen SemiprimeD1StackRecoveryCoordinateBlock SemiprimeD1StackRecoveryCoordinateEncoding\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- Exact same-program block-loop clock, including its single final real row reverse. -/\ndef budget (key:List Bool):List (List (List Bool))→List Bool→Nat\n  | [],h=>1+(2*h.length+3)\n  | block::rest,h=>blockTime key block+budget key rest ((chunk (coefficient key block)).reverse++h)\n/-- The entire actual block scan acquires the defaulting column without an upstream coordinate-cache input. -/\ntheorem blocks_run (key original outerReader rowOutput history out:List Bool)\n    (blocks:List (List (List Bool))) (rowHistory:List Bool):\n    Runs program (budget key blocks rowHistory) (.local .blockLoop)\n      (data key (words {phases:=original,reader:=outerReader,blocks:=vectorBits (blocks.map vectorBits),rowHistory:=rowHistory,rowOutput:=rowOutput,history:=history,output:=out})) (.local .phaseFrame)\n      (data key (words {phases:=original,reader:=outerReader,rowOutput:=rowHistory.reverse++chunks (row key blocks)++rowOutput,history:=history,output:=out})):=by\n  induction blocks generalizing rowHistory with\n  | nil=>\n    rw [budget]\n    let v:Words:={phases:=original,reader:=outerReader,blocks:=[false],rowHistory:=rowHistory,rowOutput:=rowOutput,history:=history,output:=out}\n    have h0:=pop_run (.local .blockLoop) (.local .abort) (.local .rowReverse) (.local .blockField)\n      .blocks key (words v) [false] rfl rfl\n    change Runs program 1 (.local .blockLoop) (data key (words v)) (.local .rowReverse)\n      (data key (Function.update (words v) .blocks [])) at h0\n    rw [words_update] at h0\n    have h1:=reverse_call 1 (.local .rowReverse) (.local .phaseFrame) key\n      (words {v with blocks:=[]}) rfl\n    change Runs program (2*rowHistory.length+3) (.local .rowReverse)\n      (data key (words {v with blocks:=[]})) (.local .phaseFrame)\n      (data key (Function.update (Function.update (words {v with blocks:=[]}) .rowHistory []) .rowOutput (rowHistory.reverse++rowOutput))) at h1\n    simp only [words_update,setWord] at h1\n    have h:=join h0 h1\n    simpa only [v,row,List.map_nil,chunks,List.foldr_nil,List.append_nil,vectorBits] using h\n  | cons block blocks ih=>\n    rw [budget]\n    have h0:=block_run key original outerReader rowHistory rowOutput history out block blocks\n    have h1:=ih ((chunk (coefficient key block)).reverse++rowHistory)\n    have h:=join h0 h1\n    simpa only [row,List.map_cons,chunks,List.foldr_cons,coefficient,List.reverse_append,List.reverse_reverse,List.append_assoc] using h\nend RiemannGaussian.SemiprimeD1StackRecoveryCoordinateBlocks\n","RiemannGaussian.SemiprimeD1StackRecoveryCoordinateEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryCoordinate\nimport RiemannGaussian.SemiprimeD1TensorTapeCodec\n/-! # Actual phase/block/word input ABI and original-order column output\nThese lists describe literal bytes in proofs only. The runtime program has\nexactly two words and never receives these lists or a coordinate-cache answer.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryCoordinateEncoding\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeSourceHistogramKeyBits (frame)\nopen SemiprimeBitArithmetic (bitValue)\n/-- Proof-side actual original-order phase/block/word inventory. -/\nabbrev Phases:=List (List (List (List Bool)))\n/-- Each actual CachePhase block tape is one framed outer payload, including empty rejected phases. -/\ndef tape (phases:Phases):List Bool:=vectorBits (phases.map (fun blocks=>vectorBits (blocks.map vectorBits)))\n/-- Defaulting literal column of one phase, without changing coefficient padding. -/\ndef row (key:List Bool) (blocks:List (List (List Bool))):List (List Bool):=\n  blocks.map (fun words=>(words[bitValue key]?).getD [])\n/-- Original phase/block order is preserved, including every empty/rejected row. -/\ndef columns (phases:Phases) (key:List Bool):List (List (List Bool)):=phases.map (row key)\n/-- Exact two-level child tape consumed by the frozen RecoveryEntries source. -/\ndef result (phases:Phases) (key:List Bool):List Bool:=vectorBits ((columns phases key).map vectorBits)\n/-- One actual vector element chunk, before any output sentinel. -/\ndef chunk (word:List Bool):List Bool:=true::frame word []\n/-- Original-order vector prefix without its one final false sentinel. -/\ndef chunks (words:List (List Bool)):List Bool:=words.foldr (fun word rest=>chunk word++rest) []\n/-- Actual frame composition, retaining all payload bytes. -/\ntheorem frame_append (word left right:List Bool):frame word left++right=frame word (left++right):=by\n  induction word with\n  | nil=>rfl\n  | cons b word ih=>change (true::b::frame word left)++right=true::b::frame word (left++right);rw [List.cons_append,List.cons_append,ih]\n/-- Chunk sequence plus one physical false is the exact vector codec. -/\ntheorem chunks_vector (words:List (List Bool)):chunks words++[false]=vectorBits words:=by\n  induction words with\n  | nil=>rfl\n  | cons word words ih=>\n    change (chunk word++chunks words)++[false]=true::frame word (vectorBits words)\n    rw [List.append_assoc,ih]\n    change (true::frame word [])++vectorBits words=_\n    rw [List.cons_append,frame_append,List.nil_append]\nend RiemannGaussian.SemiprimeD1StackRecoveryCoordinateEncoding\n","RiemannGaussian.SemiprimeD1StackRecoveryCoordinateOriginalCaps":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryCoordinateOriginalRows\nimport RiemannGaussian.SemiprimeD1StackRecoveryCoordinateSemanticCaps\nimport RiemannGaussian.SemiprimeD1PhysicalRecursiveBounds\n/-! # Original retained-phase byte caps from semantic shape and working precision\nOnly native semantic phase/block/old-rank/word-width facts are used. No native\nclock or polynomial of the recursive continuation's runtime enters any bound.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryCoordinateOriginalCaps\nopen SemiprimeD1StackRecoveryCoordinateOriginalRows SemiprimeD1StackRecoveryCoordinateSemanticCaps\nopen SemiprimeD1StackRecoveryCoordinateEncoding\nopen SemiprimeD1JetAxes SemiprimeD1TensorNetwork\nnamespace V\nexport SemiprimeD1RecursiveRecovery (retained)\nend V\nnamespace B\nexport SemiprimeD1PhysicalRecursiveBounds (phase_blocks_size)\nend B\n/-- Original actual phase-bank count is the complete original grid, including rejected phases. -/\ntheorem retained_count (next:Context→Network→SemiprimeD1JetAffineCoefficient.JetRun)\n    (ctx:Context) (net:Network) (a u:Nat):\n    (originalPhases (V.retained next ctx net a u)).length=SemiprimeD1WireKernelOriginal.size a:=by\n  rw [original_count]\n  simp only [V.retained,List.size_toArray,List.length_map,List.length_finRange]\n/-- Every actual retained phase derives its block count, old rank and child working-precision cap. -/\ntheorem retained_shape (next:Context→Network→SemiprimeD1JetAffineCoefficient.JetRun)\n    (ctx:Context) (net:Network) (a u:Nat) (hu:u ≤edgeCount net):\n    ∀blocks∈originalPhases (V.retained next ctx net a u),blocks.length ≤4*edgeCount net ∧\n      ∀words∈blocks,words.length=ctx.rank ∧∀word∈words,word.length ≤\n        SemiprimeD1ModeRate.workingPrecision (edgeCount net) u a 0 ctx.precision:=by\n  intro blocks hb\n  obtain ⟨point,hpoint,rfl⟩:=List.mem_map.mp hb\n  have hp:point∈V.retained next ctx net a u:=by simpa using hpoint\n  rw [V.retained,List.mem_toArray] at hp\n  obtain ⟨t,_,rfl⟩:=List.mem_map.mp hp\n  constructor\n  · simpa only [phaseWords,Array.length_toList] using B.phase_blocks_size next ctx net a u t hu\n  · intro words hw\n    have hm:words∈(SemiprimeD1RecursiveCounter.phase next ctx net a u t).blocks:=by simpa only [phaseWords,Array.mem_toList_iff] using hw\n    constructor\n    · exact (SemiprimeD1RecursivePhaseBounds.phase_blocks_good next ctx net a u t words hm).1\n    · intro word hword\n      exact SemiprimeD1RecursivePhaseBounds.phase_word_bound next ctx net a u t words hm word hword\n/-- Source-derived input phase-bank byte cap: old rank and child working precision remain distinct. -/\ntheorem original_bank_bytes (next:Context→Network→SemiprimeD1JetAffineCoefficient.JetRun)\n    (ctx:Context) (net:Network) (a u:Nat) (hu:u ≤edgeCount net):\n    (originalTape (V.retained next ctx net a u)).length ≤bankByteBound\n      (SemiprimeD1WireKernelOriginal.size a) (4*edgeCount net) ctx.rank\n      (SemiprimeD1ModeRate.workingPrecision (edgeCount net) u a 0 ctx.precision):=by\n  have hs:=retained_shape next ctx net a u hu\n  exact bank_bytes _ _ _ _ _ (retained_count next ctx net a u).le\n    (fun blocks hb=>(hs blocks hb).1) (fun blocks hb words hw=>((hs blocks hb).2 words hw).1.le)\n    (fun blocks hb words hw=>((hs blocks hb).2 words hw).2)\n/-- Original acquired child-coordinate output has its semantic byte cap without any subtree runtime. -/\ntheorem original_result_bytes (next:Context→Network→SemiprimeD1JetAffineCoefficient.JetRun)\n    (ctx:Context) (net:Network) (a u:Nat) (hu:u ≤edgeCount net) (key:List Bool):\n    (result (originalPhases (V.retained next ctx net a u)) key).length ≤\n      4*SemiprimeD1WireKernelOriginal.size a*(4*edgeCount net)*\n        (SemiprimeD1ModeRate.workingPrecision (edgeCount net) u a 0 ctx.precision+1)+\n          4*SemiprimeD1WireKernelOriginal.size a+1:=by\n  have hs:=retained_shape next ctx net a u hu\n  exact result_bytes _ key _ _ _ (retained_count next ctx net a u).le\n    (fun blocks hb=>(hs blocks hb).1) (fun blocks hb words hw=>((hs blocks hb).2 words hw).2)\nend RiemannGaussian.SemiprimeD1StackRecoveryCoordinateOriginalCaps\n","RiemannGaussian.SemiprimeD1StackRecoveryDenominatorFields":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryDenominatorPrimitives\nimport RiemannGaussian.SemiprimeD1StackRecoveryDenominatorEncoding\n/-! # Five actual framed row fields, including every discarded byte\nThe source parses and drains the first four fields, then physically parses the\nactual denominator into the real multiplier's first operand. No selected word\nor denominator list is provided separately from the actual row tape.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryDenominatorFields\nopen SemiprimeD1StackRecoveryDenominator SemiprimeD1StackRecoveryDenominatorState\nopen SemiprimeD1StackRecoveryDenominatorPrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackRecoveryDenominatorEncoding (Row fields)\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Actual live word receiving a physical field parse. -/\ndef target (part:Fin 5):Slot:=if part=4 then .mul M.input else .aux .discard\n/-- Parser output is exactly its declared live address. -/\ntheorem target_address (part:Fin 5):fieldTarget part=address (target part):=by fin_cases part <;> rfl\n/-- One real field call includes every parse/reverse bit and its actual return symbol. -/\ntheorem field_call (part:Fin 5) (v:Values) (word tail:List Bool)\n    (hi:v (.aux .reader)=frame word tail) (ho:v (target part)=[])\n    (hs:v (.mul M.copyScratch)=[]) (hv:v (.aux .valid)=[]):\n    Runs program (8*word.length+7) (.local (.field part)) (data v) (.local (.valid part))\n      (data (Function.update (Function.update (Function.update v (.aux .reader) tail) (target part) word) (.aux .valid) [true])):=by\n  let before:=SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) []\n  let after:SemiprimeD1StackBytecode.State Field.Stack Field.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩\n  have hin:Link.DataRel (fieldStack part) (data v) before.store (data v):=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k with\n        | input=>exact (data_get v (.aux .reader)).trans hi\n        | scratch=>exact (data_get v (.mul M.copyScratch)).trans hs\n        | output=>change data v (fieldTarget part)=[];rw [target_address,data_get,ho]\n      · cases k;exact (data_get v (.aux .valid)).trans hv\n    · intro k _;rfl\n  simp only [data_update]\n  apply included_call program (fieldStack part) (Label.field part) (field_injective part) Field.code\n    (Field.active .tagPop (none,false)) (fun _=>rfl) (.local (.field part)) (.local (.valid part))\n    rfl (8*word.length+6) before after _ _ rfl rfl\n    (SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []) hin\n  have h0:=Link.data_update (fieldStack part) (field_injective part) (data v) before.store (data v) hin (.inl .input) tail\n  have h1:=Link.data_update (fieldStack part) (field_injective part) (data v) _ _ h0 (.inl .output) word\n  have h2:=Link.data_update (fieldStack part) (field_injective part) (data v) _ _ h1 (.inr ()) [true]\n  have he:Function.update (Function.update (Function.update before.store (.inl .input) tail)\n      (.inl .output) word) (.inr ()) [true]=after.store:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  simpa only [he,fieldStack,target_address,address] using h2\n/-- Restoring the actually popped valid field returns the original live state outside parsed words. -/\ntheorem valid_restore (v:Values) (part:Fin 5) (word tail:List Bool) (hv:v (.aux .valid)=[]):\n    Function.update (Function.update (Function.update (Function.update v (.aux .reader) tail)\n      (target part) word) (.aux .valid) [true]) (.aux .valid) []=\n        Function.update (Function.update v (.aux .reader) tail) (target part) word:=by\n  rw [Function.update_idem]\n  have hn:target part≠.aux .valid:=by fin_cases part <;> decide\n  rw [Function.update_comm hn,Function.update_comm (by decide:Slot.aux Aux.reader≠.aux .valid)]\n  have he:Function.update v (.aux .valid) []=v:=by rw [←hv];exact Function.update_eq_self _ _\n  rw [he]\n/-- One actual validity pop consumes its physically produced true bit. -/\ntheorem valid_call (part:Fin 5) (v:Values) (word tail:List Bool) (hv:v (.aux .valid)=[]):\n    Runs program 1 (.local (.valid part))\n      (data (Function.update (Function.update (Function.update v (.aux .reader) tail) (target part) word) (.aux .valid) [true]))\n      (if part=4 then .local .multiply else .local (.clearField part))\n      (data (Function.update (Function.update v (.aux .reader) tail) (target part) word)):=by\n  have h:=pop_view (.local (.valid part)) (.local .abort) (.local .abort)\n    (if part=4 then .local .multiply else .local (.clearField part)) (.aux .valid)\n    (Function.update (Function.update (Function.update v (.aux .reader) tail) (target part) word) (.aux .valid) [true]) [true] rfl\n    (Function.update_self _ _ _)\n  simpa only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose,valid_restore v part word tail hv] using h\n/-- Static actual next-field suffix. -/\ndef suffix (r:Row) (n:Nat) (tail:List Bool):List Bool:=\n  if n=0 then fields r tail else if n=1 then frame (r 1) (frame (r 2) (frame (r 3) (frame (r 4) tail)))\n  else if n=2 then frame (r 2) (frame (r 3) (frame (r 4) tail))\n  else if n=3 then frame (r 3) (frame (r 4) tail) else if n=4 then frame (r 4) tail else tail\n/-- Every actual field frame starts at exactly the next physical payload. -/\ntheorem suffix_step (r:Row) (part:Fin 5) (tail:List Bool):\n    suffix r part.val tail=frame (r part) (suffix r (part.val+1) tail):=by fin_cases part <;> rfl\n/-- First four field parses and physical drains leave only their actual unread suffix. -/\ntheorem discard_call (part:Fin 4) (v:Values) (word tail:List Bool)\n    (hi:v (.aux .reader)=frame word tail) (ho:v (.aux .discard)=[])\n    (hs:v (.mul M.copyScratch)=[]) (hv:v (.aux .valid)=[]):\n    Runs program (9*word.length+9) (.local (.field part.castSucc)) (data v)\n      (.local (.field ⟨part.val+1,by omega⟩)) (data (Function.update v (.aux .reader) tail)):=by\n  have ht:target part.castSucc=.aux .discard:=by fin_cases part <;> rfl\n  have hp:part.castSucc≠(4:Fin 5):=by fin_cases part <;> decide\n  have h0:=field_call part.castSucc v word tail hi (by rw [ht];exact ho) hs hv\n  rw [ht] at h0\n  have h1:=valid_call part.castSucc v word tail hv\n  rw [ite_eq_right hp,ht] at h1\n  let w:=Function.update (Function.update v (.aux .reader) tail) (.aux .discard) word\n  have h2:=drain_view (.local (.clearField part.castSucc)) (nextField part.castSucc) (.aux .discard) w rfl\n  have hw:w (.aux .discard)=word:=Function.update_self _ _ _\n  rw [hw] at h2\n  have he:Function.update w (.aux .discard) []=Function.update v (.aux .reader) tail:=by\n    dsimp [w]\n    rw [Function.update_idem,Function.update_comm (by decide:Slot.aux Aux.reader≠.aux .discard)]\n    have hh:Function.update v (.aux .discard) []=v:=by rw [←ho];exact Function.update_eq_self _ _\n    rw [hh]\n  rw [he] at h2\n  have hn:nextField part.castSucc=.local (.field ⟨part.val+1,by omega⟩):=by fin_cases part <;> rfl\n  rw [hn] at h2\n  have h:=(join (join h0 h1) h2)\n  simpa only [show (8*word.length+7+1)+(word.length+1)=9*word.length+9 by omega] using h\n/-- Final actual denominator parse reaches the real multiplier's first input. -/\ntheorem denominator_call (v:Values) (word tail:List Bool)\n    (hi:v (.aux .reader)=frame word tail) (ho:v (.mul M.input)=[])\n    (hs:v (.mul M.copyScratch)=[]) (hv:v (.aux .valid)=[]):\n    Runs program (8*word.length+8) (.local (.field 4)) (data v) (.local .multiply)\n      (data (Function.update (Function.update v (.aux .reader) tail) (.mul M.input) word)):=by\n  have h0:=field_call 4 v word tail hi ho hs hv\n  have h1:=valid_call 4 v word tail hv\n  have h:=join h0 h1\n  simpa only [target,ite_true,show (8*word.length+7)+1=8*word.length+8 by omega] using h\n/-- Paid complete parser/drain clock for all five physical fields of one row. -/\ndef time (r:Row):Nat:=9*((r 0).length+(r 1).length+(r 2).length+(r 3).length)+8*(r 4).length+44\n/-- Complete actual five-field acquisition, retaining no discarded answer or metadata field. -/\ntheorem parse_run (v:Values) (r:Row) (tail:List Bool)\n    (hi:v (.aux .reader)=fields r tail) (hd:v (.aux .discard)=[])\n    (hm:v (.mul M.input)=[]) (hs:v (.mul M.copyScratch)=[]) (hv:v (.aux .valid)=[]):\n    Runs program (time r) (.local (.field 0)) (data v) (.local .multiply)\n      (data (Function.update (Function.update v (.aux .reader) tail) (.mul M.input) (r 4))):=by\n  let view (n:Nat):Values:=Function.update v (.aux .reader) (suffix r n tail)\n  have h0:=discard_call 0 v (r 0) (suffix r 1 tail) hi hd hs hv\n  have h1:=discard_call 1 (view 1) (r 1) (suffix r 2 tail) rfl hd hs hv\n  have h2:=discard_call 2 (view 2) (r 2) (suffix r 3 tail) rfl hd hs hv\n  have h3:=discard_call 3 (view 3) (r 3) (suffix r 4 tail) rfl hd hs hv\n  have h4:=denominator_call (view 4) (r 4) tail rfl hm hs hv\n  simp only [view,Function.update_idem] at h1 h2 h3 h4\n  have h:=join h0 (join h1 (join h2 (join h3 h4)))\n  convert h using 1 <;> first | rfl | (unfold time;omega)\nend RiemannGaussian.SemiprimeD1StackRecoveryDenominatorFields\n","RiemannGaussian.SemiprimeD1StackRecoveryEntriesBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesExecution\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesCapacities\n/-! # Own complete two-tape recovery-entry source polynomial\nEvery actual indexed read, metadata scan, copied byte, framed entry, cleanup,\nreal return and the final physical history reverse belongs to the SAME clock.\nChild byte estimates here and in the original cap never use subtree runtimes.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryEntriesBounds\nopen SemiprimeD1StackRecoveryEntries SemiprimeD1StackRecoveryEntriesExecution\nopen SemiprimeD1StackRecoveryEntriesLoop SemiprimeD1StackRecoveryEntriesOrder\nopen SemiprimeD1StackRecoveryEntriesEncoding (childTape selectedChild)\nopen SemiprimeD1StackRecoveryDenominatorEncoding (Row tape)\nopen SemiprimeD1StackRecoveryDenominatorCapacities (fieldMass field_mass_le payload_le_tape rows_length)\nnamespace B\nexport SemiprimeD1StackRecoveryEntriesCapacities (row_time chunk_bound)\nend B\n/-- Actual sum of row-step clocks, each independent of prior history length. -/\ndef rowSum (children:List (List (List Bool))) (rows:List Row):Nat:=(rows.map (SemiprimeD1StackRecoveryEntriesLoop.rowTime children)).sum\n/-- Exact actual loop clock decomposes into row work plus ONE final history-byte reverse. -/\ntheorem budget_eq (children:List (List (List Bool))) (rows:List Row) (history:List Bool):\n    budget children rows history=rowSum children rows+2*(chunks children rows).length+2*history.length+4:=by\n  induction rows generalizing history with\n  | nil=>\n    simp only [budget,rowSum,List.map_nil,List.sum_nil,chunks,List.length_nil,Nat.mul_zero,Nat.zero_add]\n    omega\n  | cons r rows ih=>\n    rw [budget,ih]\n    simp only [rowSum,List.map_cons,List.sum_cons,chunks,List.length_append,List.length_reverse]\n    omega\n/-- Every actual row source clock is paid by its actual source/child bytes, not any child execution budget. -/\ntheorem row_sum_bound (children:List (List (List Bool))) (rows:List Row) (L:Nat)\n    (hr:∀r∈rows,fieldMass r ≤L):\n    rowSum children rows ≤10000000*rows.length*((childTape children).length+L+1)^2:=by\n  induction rows with\n  | nil=>simp only [rowSum,List.map_nil,List.sum_nil,List.length_nil,Nat.mul_zero,Nat.zero_mul,Nat.le_refl]\n  | cons r rows ih=>\n    have hr0:=hr r (List.mem_cons_self)\n    have h0:SemiprimeD1StackRecoveryEntriesLoop.rowTime children r ≤10000000*((childTape children).length+L+1)^2:=\n      (B.row_time children r).trans (Nat.mul_le_mul_left 10000000 (Nat.pow_le_pow_left (by omega:(childTape children).length+fieldMass r+1 ≤(childTape children).length+L+1) 2))\n    have h1:=ih (fun s hs=>hr s (List.mem_cons_of_mem r hs))\n    dsimp only [rowSum] at h1 ⊢\n    simp only [List.map_cons,List.sum_cons,List.length_cons,Nat.mul_add,Nat.mul_one,Nat.add_mul]\n    omega\n/-- Actual logged bytes grow only by the actually framed new entries. -/\ntheorem chunks_bound (children:List (List (List Bool))) (rows:List Row) (L:Nat)\n    (hr:∀r∈rows,fieldMass r ≤L):\n    (chunks children rows).length ≤5*rows.length*((childTape children).length+L+1):=by\n  induction rows with\n  | nil=>simp only [chunks,List.length_nil,Nat.mul_zero,Nat.zero_mul,Nat.le_refl]\n  | cons r rows ih=>\n    have hr0:=hr r (List.mem_cons_self)\n    have h0:(SemiprimeD1StackRecoveryEntriesLogger.chunk r (selectedChild children (r 0) (r 1))).length ≤5*((childTape children).length+L+1):=by\n      have h:=B.chunk_bound children r\n      have hm:=Nat.mul_le_mul_left 5 (by omega:(childTape children).length+fieldMass r+1 ≤(childTape children).length+L+1)\n      exact h.trans hm\n    have h1:=ih (fun s hs=>hr s (List.mem_cons_of_mem r hs))\n    simp only [chunks,List.length_append,List.length_cons]\n    nlinarith only [h0,h1]\n/-- Only the actual two physical input byte lengths form the whole-source resource. -/\ndef resource (rows:List Row) (children:List (List (List Bool))):Nat:=(tape rows).length+(childTape children).length\n/-- Fixed coefficient/degree precede every actual row tape, child cache and binary address family. -/\ndef runBound (rows:List Row) (children:List (List (List Bool))):Nat:=1000000000000*(resource rows children+1)^4\n/-- SAME actual two-tape source has one fixed quartic bound, with all final history work included once. -/\ntheorem timeBound_le (rows:List Row) (children:List (List (List Bool))):timeBound rows children ≤runBound rows children:=by\n  let rowBytes:=(tape rows).length\n  let S:=resource rows children+1\n  have hr:∀r∈rows,fieldMass r ≤rowBytes:=fun r he=>(field_mass_le rows r he).trans (payload_le_tape rows)\n  have ht:=row_sum_bound children rows rowBytes hr\n  have hc:=chunks_bound children rows rowBytes hr\n  have hn:=rows_length rows\n  have hnS:rows.length ≤S:=by dsimp [S,resource,rowBytes];omega\n  have hS:(childTape children).length+rowBytes+1=S:=by dsimp [S,resource,rowBytes];omega\n  rw [hS] at ht hc\n  have ht':rowSum children rows ≤10000000*S^3:=by\n    calc\n      _ ≤10000000*rows.length*S^2:=ht\n      _ ≤10000000*S*S^2:=Nat.mul_le_mul_right _ (Nat.mul_le_mul_left 10000000 hnS)\n      _=10000000*S^3:=by ring\n  have hc':(chunks children rows).length ≤5*S^2:=by\n    calc\n      _ ≤5*rows.length*S:=hc\n      _ ≤5*S*S:=Nat.mul_le_mul_right _ (Nat.mul_le_mul_left 5 hnS)\n      _=5*S^2:=by ring\n  have hpos:1 ≤S:=by dsimp [S];omega\n  have h2:S^2 ≤S^4:=Nat.pow_le_pow_right hpos (by decide)\n  have h3:S^3 ≤S^4:=Nat.pow_le_pow_right hpos (by decide)\n  have h1:S ≤S^4:=by simpa only [pow_one] using Nat.pow_le_pow_right hpos (by decide:1 ≤4)\n  have hrt:rowSum children rows ≤10000000*S^4:=ht'.trans (Nat.mul_le_mul_left 10000000 h3)\n  have hrc:(chunks children rows).length ≤5*S^4:=hc'.trans (Nat.mul_le_mul_left 5 h2)\n  have hrb:rowBytes+1 ≤S:=by dsimp [S,resource,rowBytes];omega\n  unfold timeBound bodyTime\n  change 5*rowBytes+5+budget children rows []+1 ≤1000000000000*S^4\n  rw [budget_eq]\n  simp only [List.length_nil,Nat.mul_zero,Nat.add_zero]\n  omega\n/-- Actual source trace bounded by its own fixed whole-program input-byte polynomial. -/\ntheorem source_run_bounded (rows:List Row) (children:List (List (List Bool))):\n    ∃q ≤runBound rows children,SemiprimeD1StackCalls.run program q (initial (tape rows) (childTape children))=some (done rows children):=\n  ⟨timeBound rows children,timeBound_le rows children,source_run rows children⟩\nend RiemannGaussian.SemiprimeD1StackRecoveryEntriesBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexed":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWordEqualExecution\nimport RiemannGaussian.SemiprimeD1StackAdderExecution\nimport RiemannGaussian.SemiprimeD1TensorTapeFieldBytecode\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n/-! # Actual binary-index vector reader for the recovery-entry source\nOnly an actual framed vector and actual binary query are supplied. Each actual\nvector tag drives one real numeric WordEqual against an acquired BINARY ordinal.\nA real full adder increments it after each skipped field. Every loop stops at\nactual vector EOF, so numeric address magnitude never drives unary work.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexed\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace A\nexport SemiprimeD1StackAdder (Stack Label code store state)\nend A\nnamespace E\nexport SemiprimeD1StackWordEqual (Label code state)\nend E\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\n/-- Eight fixed source/query/scan roles beside the real shared four-role arithmetic bank. -/\ninductive Aux where\n  | cache | query | counter | reader | parser | value | valid | copy\n  deriving DecidableEq,Repr\ninstance :Fintype Aux:=Fintype.ofList [.cache,.query,.counter,.reader,.parser,.value,.valid,.copy]\n  (by intro k;cases k <;> simp)\n/-- All12 physical roles; equality and increment use the SAME four actual arithmetic tapes. -/\nabbrev Stack:=A.Stack⊕Aux\n/-- Actual arithmetic tape. -/\ndef arithmetic:A.Stack → Stack:=Sum.inl\n/-- Actual input/query/parser/scan tape. -/\ndef aux:Aux → Stack:=Sum.inr\n/-- Five literal preserving-copy sites, fixed before every address and vector. -/\ninductive Copy where\n  | cache | query | ordinal | increment | result\n  deriving DecidableEq,Repr\ninstance :Fintype Copy:=Fintype.ofList [.cache,.query,.ordinal,.increment,.result]\n  (by intro k;cases k <;> simp)\n/-- Actual source of a paid preserving copy. -/\ndef copySource:Copy → Stack\n  | .cache=>aux .cache | .query=>aux .query | .ordinal|.increment=>aux .counter | .result=>arithmetic .output\n/-- Actual target of a paid preserving copy. -/\ndef copyTarget:Copy → Stack\n  | .cache=>aux .reader | .query|.increment=>arithmetic .left | .ordinal=>arithmetic .right | .result=>aux .counter\n/-- Actual restoring copy workspace, independent of address values. -/\ndef copyStack (site:Copy) (k:Fin 3):Stack:=if k=0 then copySource site else if k=1 then copyTarget site else aux .copy\n/-- Actual vector Field parser materializes both selected and discarded words. -/\ndef fieldStack:F.Stack → Stack\n  | .inl .input=>aux .reader | .inl .scratch=>aux .parser | .inl .output=>aux .value | .inr () =>aux .valid\n/-- Fixed finite scan/parse/arithmetic/cleanup control. -/\ninductive Control where\n  | start | loop | query | ordinal | compare | compared | field (take:Bool) | parsed (take:Bool)\n  | clearValue | increment | clearCounterForAdd | seed | add | result | clearResult\n  | clearReader | clearCounter | done | abort\n  deriving DecidableEq,Fintype,Repr\n/-- All real included component labels and finite return cells. -/\ninductive Label where\n  | local (pc:Control) | copy (site:Copy) (pc:Fin 9) | field (pc:F.Label)\n  | equal (pc:E.Label) | add (pc:A.Label)\n  deriving DecidableEq,Fintype,Repr\nlocal notation \"ctl\"=>Label.local\n/-- The ONE finite binary-index reader; no address is decoded or materialized as unary. -/\ndef program:Label → C.Instruction Stack Label\n  | .local .start=>.call (.copy .cache 0) (ctl .loop)\n  | .local .loop=>.base (.pop (aux .reader) (ctl .clearCounter) (ctl .clearReader) (ctl .query))\n  | .local .query=>.call (.copy .query 0) (ctl .ordinal)\n  | .local .ordinal=>.call (.copy .ordinal 0) (ctl .compare)\n  | .local .compare=>.call (.equal .loop) (ctl .compared)\n  | .local .compared=>.base (.pop (arithmetic .output) (ctl .abort) (ctl (.field false)) (ctl (.field true)))\n  | .local (.field take)=>.call (.field (F.active .tagPop (none,false))) (ctl (.parsed take))\n  | .local (.parsed take)=>.base (.pop (aux .valid) (ctl .abort) (ctl .abort)\n      (if take then ctl .clearReader else ctl .clearValue))\n  | .local .clearValue=>.base (.pop (aux .value) (ctl .increment) (ctl .clearValue) (ctl .clearValue))\n  | .local .increment=>.call (.copy .increment 0) (ctl .clearCounterForAdd)\n  | .local .clearCounterForAdd=>.base (.pop (aux .counter) (ctl .seed) (ctl .clearCounterForAdd) (ctl .clearCounterForAdd))\n  | .local .seed=>.base (.push (arithmetic .right) true (ctl .add))\n  | .local .add=>.call (.add (.start false)) (ctl .result)\n  | .local .result=>.call (.copy .result 0) (ctl .clearResult)\n  | .local .clearResult=>.base (.pop (arithmetic .output) (ctl .loop) (ctl .clearResult) (ctl .clearResult))\n  | .local .clearReader=>.base (.pop (aux .reader) (ctl .clearCounter) (ctl .clearReader) (ctl .clearReader))\n  | .local .clearCounter=>.base (.pop (aux .counter) (ctl .done) (ctl .clearCounter) (ctl .clearCounter))\n  | .local .done|.local .abort=>.base .halt\n  | .copy site pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack site) (Label.copy site) (SemiprimeD1StackCopy.code pc)\n  | .field pc=>SemiprimeD1StackMultiplierLink.instruction fieldStack Label.field (F.code pc)\n  | .equal pc=>SemiprimeD1StackMultiplierLink.instruction arithmetic Label.equal (E.code pc)\n  | .add pc=>SemiprimeD1StackMultiplierLink.instruction arithmetic Label.add (A.code pc)\n/-- Honest actual vector/query entry, without an ordinal count or selected word. -/\ndef input (cache query:List Bool):Stack → List Bool:=\n  Function.update (Function.update (fun _=>[]) (aux .cache) cache) (aux .query) query\n/-- Actual initial source state, empty real returns and every private field clear. -/\ndef initial (cache query:List Bool):C.State Stack Label:=⟨some (ctl .start),none,none,input cache query,[]⟩\n/-- One fixed finite actual vector/query source. -/\ndef machine:Turing.FinTM2:=SemiprimeD1StackCalls.machine (aux .cache) (aux .value) (ctl .start) program\n/-- All12 tapes are counted, including equality's unused scratch during comparison. -/\ntheorem stack_card:Fintype.card Stack=12:=by decide\n/-- Every real copy has three distinct physical roles. -/\ntheorem copy_injective (site:Copy):Function.Injective (copyStack site):=by cases site <;> decide\n/-- The real parser has four distinct physical roles. -/\ntheorem field_injective:Function.Injective fieldStack:=by decide\n/-- All data and real return alphabets are finite before all addresses. -/\ntheorem alphabets_finite:∀k,Finite (machine.Γ k):=\n  SemiprimeD1StackCalls.all_alphabets_finite (aux .cache) (aux .value) (ctl .start) program\n/-- Transient control contains no address, word, count, getter or evaluator. -/\ntheorem control_finite:Finite machine.σ:=\n  SemiprimeD1StackCalls.control_finite (aux .cache) (aux .value) (ctl .start) program\nend RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexed\n","RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedState":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexed\n/-! # Literal all12-word boundaries for binary-index acquisition -/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedState\nopen SemiprimeD1StackRecoveryEntriesIndexed\n/-- Full physical word bank; all addresses remain fixed finite. -/\ndef store (left right work sum cache query counter reader parser value valid copy:List Bool):Stack → List Bool\n  | .inl k=>A.store left right work sum k\n  | .inr .cache=>cache | .inr .query=>query | .inr .counter=>counter | .inr .reader=>reader\n  | .inr .parser=>parser | .inr .value=>value | .inr .valid=>valid | .inr .copy=>copy\n/-- Real scan boundary has every arithmetic/parser/copy work field empty. -/\ndef view (cache query counter reader value:List Bool):Stack → List Bool:=store [] [] [] [] cache query counter reader [] value [] []\n/-- Literal physical left word update. -/\ntheorem update_left (left right work sum cache query counter reader parser value valid copy word:List Bool):\n    Function.update (store left right work sum cache query counter reader parser value valid copy) (.inl .left:Stack) word=store word right work sum cache query counter reader parser value valid copy:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- Literal physical right word update. -/\ntheorem update_right (left right work sum cache query counter reader parser value valid copy word:List Bool):\n    Function.update (store left right work sum cache query counter reader parser value valid copy) (.inl .right:Stack) word=store left word work sum cache query counter reader parser value valid copy:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- Literal physical work word update. -/\ntheorem update_work (left right work sum cache query counter reader parser value valid copy word:List Bool):\n    Function.update (store left right work sum cache query counter reader parser value valid copy) (.inl .scratch:Stack) word=store left right word sum cache query counter reader parser value valid copy:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- Literal physical sum word update. -/\ntheorem update_sum (left right work sum cache query counter reader parser value valid copy word:List Bool):\n    Function.update (store left right work sum cache query counter reader parser value valid copy) (.inl .output:Stack) word=store left right work word cache query counter reader parser value valid copy:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- Literal physical cache word update. -/\ntheorem update_cache (left right work sum cache query counter reader parser value valid copy word:List Bool):\n    Function.update (store left right work sum cache query counter reader parser value valid copy) (.inr .cache:Stack) word=store left right work sum word query counter reader parser value valid copy:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- Literal physical query word update. -/\ntheorem update_query (left right work sum cache query counter reader parser value valid copy word:List Bool):\n    Function.update (store left right work sum cache query counter reader parser value valid copy) (.inr .query:Stack) word=store left right work sum cache word counter reader parser value valid copy:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- Literal physical counter word update. -/\ntheorem update_counter (left right work sum cache query counter reader parser value valid copy word:List Bool):\n    Function.update (store left right work sum cache query counter reader parser value valid copy) (.inr .counter:Stack) word=store left right work sum cache query word reader parser value valid copy:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- Literal physical reader word update. -/\ntheorem update_reader (left right work sum cache query counter reader parser value valid copy word:List Bool):\n    Function.update (store left right work sum cache query counter reader parser value valid copy) (.inr .reader:Stack) word=store left right work sum cache query counter word parser value valid copy:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- Literal physical parser word update. -/\ntheorem update_parser (left right work sum cache query counter reader parser value valid copy word:List Bool):\n    Function.update (store left right work sum cache query counter reader parser value valid copy) (.inr .parser:Stack) word=store left right work sum cache query counter reader word value valid copy:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- Literal physical value word update. -/\ntheorem update_value (left right work sum cache query counter reader parser value valid copy word:List Bool):\n    Function.update (store left right work sum cache query counter reader parser value valid copy) (.inr .value:Stack) word=store left right work sum cache query counter reader parser word valid copy:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- Literal physical valid word update. -/\ntheorem update_valid (left right work sum cache query counter reader parser value valid copy word:List Bool):\n    Function.update (store left right work sum cache query counter reader parser value valid copy) (.inr .valid:Stack) word=store left right work sum cache query counter reader parser value word copy:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- Literal physical copy word update. -/\ntheorem update_copy (left right work sum cache query counter reader parser value valid copy word:List Bool):\n    Function.update (store left right work sum cache query counter reader parser value valid copy) (.inr .copy:Stack) word=store left right work sum cache query counter reader parser value valid word:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\n/-- Honest prepared two-input bank contains no supplied ordinal or answer. -/\ntheorem initial_store (cache query:List Bool):(initial cache query).data=view cache query [] [] []:=by\n  funext k\n  rcases k with k|k\n  · cases k <;> rfl\n  · cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedState\n","RiemannGaussian.SemiprimeD1StackRecoveryFinishCleanup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishPrimitives\n/-! # All sixteen actual recovery-helper drains and real returns\nEvery allocated helper/cache is physically emptied after the final product.\nThe three original operands and the actual final scalar output are retained.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinishCleanup\nopen SemiprimeD1StackRecoveryFinish SemiprimeD1StackRecoveryFinishState\nopen SemiprimeD1StackRecoveryFinishPrimitives SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\"=>Label.local\n/-- Exactly sixteen actual helper/cache words are physically drained. -/\ntheorem cleanup_length:cleanup.length=16:=rfl\n/-- No helper/cache address is duplicated. -/\ntheorem cleanup_nodup:cleanup.Nodup:=by decide\n/-- Precisely the two actual original binary source operands are excluded from helper draining. -/\ntheorem cleanup_mem (a:Aux):a∈cleanup ↔a≠.numerator ∧a≠.denominator:=by cases a <;> simp [cleanup]\n/-- Exact full bank after the fixed prefix of actual helper drains. -/\ndef partialBank (v:Values) (n:Nat):Values\n  | .aux a=>if a∈cleanup.take n then [] else v (.aux a)\n  | s=>v s\n/-- Final full35-role bank preserves actual input/cache/result addresses and clears all sixteen helper fields. -/\ndef cleared (v:Values):Values\n  | .aux .numerator=>v (.aux .numerator) | .aux .denominator=>v (.aux .denominator)\n  | .aux _=>[] | s=>v s\n/-- Only proof indices describe the fixed finite source position; the actual code has sixteen static sites. -/\ndef labelAt (n:Nat):Label:=if h:n<16 then ctl (.clear ⟨n,h⟩) else ctl .done\n/-- Actual remaining physical word-byte mass, not a native recovery report. -/\ndef mass (v:Values) (n:Nat):Nat:=((cleanup.drop n).map (fun a=>(v (.aux a)).length)).sum\n/-- Initially no helper was drained by an advised operation. -/\ntheorem partial_zero (v:Values):partialBank v 0=v:=by\n  funext s;cases s with\n  | aux a=>simp [partialBank]\n  | _=>rfl\n/-- Complete actual fixed inventory empties every helper field, including copy workspace. -/\ntheorem partial_full (v:Values):partialBank v 16=cleared v:=by\n  funext s;cases s with\n  | aux a=>cases a <;> simp [partialBank,cleared,cleanup]\n  | _=>rfl\n/-- No helper remains after the actual complete fixed inventory. -/\ntheorem mass_full (v:Values):mass v 16=0:=by\n  unfold mass\n  rw [←cleanup_length,List.drop_length]\n  rfl\n/-- The next actual helper has not appeared in any earlier fixed drain site. -/\ntheorem fresh (n:Nat) (hn:n<16):(cleanup[n]'(by simpa only [cleanup_length] using hn))∉cleanup.take n:=by\n  have hl:n<cleanup.length:=by simpa only [cleanup_length] using hn\n  have hd:List.Disjoint (cleanup.take n) (cleanup.drop n):=List.disjoint_of_nodup_append (by\n    rw [List.take_append_drop]\n    exact cleanup_nodup)\n  have hm:(cleanup[n]'(by simpa only [cleanup_length] using hn))∈cleanup.drop n:=by rw [List.drop_eq_getElem_cons hl];exact List.mem_cons_self\n  exact fun h=>(List.disjoint_left.mp hd) h hm\n/-- Every actual drain sees exactly the original remaining physical helper bytes. -/\ntheorem partial_next (v:Values) (n:Nat) (hn:n<16):partialBank v n (.aux (cleanup[n]'(by simpa only [cleanup_length] using hn)))=v (.aux (cleanup[n]'(by simpa only [cleanup_length] using hn))):=by\n  simp only [partialBank,fresh n hn,ite_false]\n/-- One actual helper emptying is exactly the next partialBank physical bank. -/\ntheorem partial_update (v:Values) (n:Nat) (hn:n<16):\n    Function.update (partialBank v n) (.aux (cleanup[n]'(by simpa only [cleanup_length] using hn))) []=partialBank v (n+1):=by\n  have hl:n<cleanup.length:=by simpa only [cleanup_length] using hn\n  have ht:=List.take_succ_eq_append_getElem hl\n  funext s\n  cases s with\n  | aux a=>\n    by_cases ha:a=(cleanup[n]'(by simpa only [cleanup_length] using hn))\n    · subst a\n      simp only [Function.update_same,partialBank,ht,List.mem_append,List.mem_singleton_self,or_true,ite_true]\n    · rw [Function.update_of_ne (show Slot.aux a≠Slot.aux (cleanup[n]'(by simpa only [cleanup_length] using hn)) by intro h;exact ha (Slot.aux.inj h))]\n      simp only [partialBank,ht,List.mem_append,List.mem_singleton,ha,or_false]\n  | _=>rfl\n/-- Exact remaining mass decreases by precisely the actual word consumed at this real drain site. -/\ntheorem mass_step (v:Values) (n:Nat) (hn:n<16):mass v n=(v (.aux (cleanup[n]'(by simpa only [cleanup_length] using hn)))).length+mass v (n+1):=by\n  have hl:n<cleanup.length:=by simpa only [cleanup_length] using hn\n  unfold mass\n  rw [List.drop_eq_getElem_cons hl]\n  rfl\n/-- Literal next finite code site matches the proof-side successor index. -/\ntheorem code_at (n:Nat) (hn:n<16):\n    program (labelAt n)=.call (.drain (address (.aux (cleanup[n]'(by simpa only [cleanup_length] using hn))))) (labelAt (n+1)):=by\n  have hrole:cleanupRole ⟨n,hn⟩=address (.aux (cleanup[n]'(by simpa only [cleanup_length] using hn))):=rfl\n  rw [labelAt,dite_eq_left hn,program,hrole]\n  by_cases h:n<15\n  · have hs:n+1<16:=by omega\n    simp only [h,hs,dite_eq_left,labelAt]\n  · have hs:¬n+1<16:=by omega\n    simp only [h,hs,labelAt]\n/-- Full actual cleanup loop pays each helper byte and every real drain call/return. -/\ntheorem loop (v:Values) (n r:Nat) (hnr:n+r=16):\n    Runs program (mass v n+3*r) (labelAt n) (data (partialBank v n)) (ctl .done) (data (cleared v)):=by\n  induction r generalizing n with\n  | zero=>\n    have hn:n=16:=by omega\n    subst n\n    simp only [mass_full,Nat.mul_zero,Nat.zero_add,partial_full]\n    exact runs_refl program (ctl .done) (data (cleared v))\n  | succ r ih=>\n    have hn:n<16:=by omega\n    have h0:=drain_call (labelAt n) (labelAt (n+1)) (.aux (cleanup[n]'(by simpa only [cleanup_length] using hn))) (partialBank v n) (code_at n hn)\n    rw [partial_next v n hn,partial_update v n hn] at h0\n    have h1:=ih (n+1) (by omega)\n    have h:=join h0 h1\n    have hm:=mass_step v n hn\n    convert h using 1\n    omega\n/-- Complete actual sixteen-helper cleanup, immediately before the real final halt. -/\ntheorem source_run (v:Values):\n    Runs program (mass v 0+48) (ctl (.clear 0)) (data v) (ctl .done) (data (cleared v)):=by\n  have h:=loop v 0 16 (by omega)\n  rw [partial_zero] at h\n  exact h\nend RiemannGaussian.SemiprimeD1StackRecoveryFinishCleanup\n","RiemannGaussian.SemiprimeD1StackRecoveryFinishNewtonOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishNewton\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishPreparation\n/-! # Exact original inverse bytes from the real precision-marker Newton loop\nThe actual loop repeats the literal old step in its exact word order. Native\nfunctions below describe results only; every actual step was physically joined\nfrom the existing real scalar programs and paid restoring copies.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinishNewtonOriginal\nopen SemiprimeD1StackRecoveryFinish SemiprimeD1StackRecoveryFinishState\nopen SemiprimeD1StackRecoveryFinishWords SemiprimeD1StackRecoveryFinishNewton SemiprimeD1StackProcedureTrace\nopen SemiprimeBitIndexClipping (SignedWord)\nnamespace P\nexport SemiprimeD1StackRecoveryFinishPreparation (result source_prepared time)\nend P\nlocal notation \"ctl\"=>Label.local\n/-- Every non-stage, non-counter field is retained across an actual marker and complete actual stage. -/\ntheorem advance_preserved (v:Values) (s:Slot) (hs:Stable s) (ht:s≠.aux .todo):advance v s=v s:=by\n  rw [advance,step_preserved _ s hs,Function.update_of_ne ht]\n/-- The literal old step word is acquired on every actual marker. -/\ntheorem advance_current (v:Values):advance v (.aux .current)=\n    (SemiprimeD1OddInverseBits.step (v .width).length (v (.aux .inverseInput))\n      (v (.aux .negative)) (v (.aux .two)) (v (.aux .current))).bits:=by\n  rw [advance,step_current]\n  rfl\n/-- Every retained original/source/precision/scalar cache field survives the entire actual marker traversal. -/\ntheorem states_preserved (n:Nat) (v:Values) (s:Slot) (hs:Stable s) (ht:s≠.aux .todo):states n v s=v s:=by\n  induction n generalizing v with\n  | zero=>rfl\n  | succ n ih=>rw [states,ih,advance_preserved v s hs ht]\n/-- All real operator/copy workspace stays clean at the complete loop boundary. -/\ntheorem states_clean (n:Nat) (v:Values) (hc:Clean v):Clean (states n v):=by\n  induction n generalizing v with\n  | zero=>exact hc\n  | succ n ih=>exact ih (advance v) (clean_advance v hc)\n/-- Actual marker count entails literal empty todo tape at the loop exit, with no counter answer supplied. -/\ntheorem states_todo (n:Nat) (v:Values) (ht:v (.aux .todo)=List.replicate n true):states n v (.aux .todo)=[]:=by\n  induction n generalizing v with\n  | zero=>exact ht\n  | succ n ih=>\n    apply ih\n    rw [advance,step_preserved _ (.aux .todo) (by simp [Stable]),Function.update_same,ht]\n    rfl\n/-- Proof-side literal word iteration in the actual source's tail order; not an instruction or input function. -/\ndef iterateWord (p:Nat) (a negative two current:List Bool):Nat→List Bool\n  | 0=>current\n  | n+1=>iterateWord p a negative two (SemiprimeD1OddInverseBits.step p a negative two current).bits n\n/-- Exact actual current word after all actual source stages, preserving all native padding/circuit order. -/\ntheorem states_current (n:Nat) (v:Values):states n v (.aux .current)=\n    iterateWord (v .width).length (v (.aux .inverseInput)) (v (.aux .negative)) (v (.aux .two)) (v (.aux .current)) n:=by\n  induction n generalizing v with\n  | zero=>rfl\n  | succ n ih=>\n    have hw:=advance_preserved v .width (by simp [Stable]) (by decide)\n    have ha:=advance_preserved v (.aux .inverseInput) (by simp [Stable]) (by decide)\n    have hn:=advance_preserved v (.aux .negative) (by simp [Stable]) (by decide)\n    have ht:=advance_preserved v (.aux .two) (by simp [Stable]) (by decide)\n    rw [states,ih,iterateWord,hw,ha,hn,ht,advance_current]\n/-- Literal tail iteration is repeated composition of the exact same scalar-word step. -/\ntheorem iterateWord_iterate (p:Nat) (a negative two current:List Bool) (n:Nat):\n    iterateWord p a negative two current n=(fun x=>(SemiprimeD1OddInverseBits.step p a negative two x).bits)^[n] current:=by\n  induction n generalizing current with\n  | zero=>rfl\n  | succ n ih=>rw [iterateWord,Function.iterate_succ_apply,ih]\n/-- The original inverse report loop has exactly the same repeated scalar-word step composition. -/\ntheorem native_iterate (p:Nat) (a negative two:List Bool) (n:Nat):\n    (SemiprimeD1OddInverseBits.loop p a negative two n).bits=\n      (fun x=>(SemiprimeD1OddInverseBits.step p a negative two x).bits)^[n]\n        (SemiprimeD1JetScalarBits.reduce p [true]).bits:=by\n  induction n with\n  | zero=>rfl\n  | succ n ih=>\n    simpa only [SemiprimeD1OddInverseBits.loop,Function.iterate_succ_apply'] using\n      congrArg (fun x=>(SemiprimeD1OddInverseBits.step p a negative two x).bits) ih\n/-- The actual loop seeded by real reduced one agrees with the exact original inverse loop BYTES. -/\ntheorem iterateWord_native (p:Nat) (a negative two:List Bool) (n:Nat):\n    iterateWord p a negative two (SemiprimeD1JetScalarBits.reduce p [true]).bits n=\n      (SemiprimeD1OddInverseBits.loop p a negative two n).bits:=by\n  rw [iterateWord_iterate,native_iterate]\n/-- Entire actually prepared real scalar bank satisfies the actual operator cleanup invariant. -/\ntheorem prepared_clean (n:SignedWord) (d w:List Bool):Clean (P.result n d w):=\n  ⟨⟨rfl,rfl,rfl,rfl,rfl⟩,⟨rfl,rfl,rfl⟩,rfl⟩\n/-- Actual WIDTH copied into the physical marker tape, not supplied as a decoded count. -/\ntheorem prepared_todo (n:SignedWord) (d w:List Bool):P.result n d w (.aux .todo)=w:=rfl\n/-- Actual physically supplied precision cache is retained in all scalar calls. -/\ntheorem prepared_width (n:SignedWord) (d w:List Bool):P.result n d w .width=w:=rfl\n/-- Exact odd-input scalar bytes physically acquired by the actual reducer. -/\ntheorem prepared_a (n:SignedWord) (d w:List Bool):P.result n d w (.aux .inverseInput)=\n    (SemiprimeD1JetScalarBits.reduce w.length (odd d)).bits:=rfl\n/-- Exact negative-one word physically acquired by real WIDTH copy. -/\ntheorem prepared_negative (n:SignedWord) (d w:List Bool):P.result n d w (.aux .negative)=w:=rfl\n/-- Exact two word physically acquired by constant pushes and real reduction. -/\ntheorem prepared_two (n:SignedWord) (d w:List Bool):P.result n d w (.aux .two)=\n    (SemiprimeD1JetScalarBits.reduce w.length [false,true]).bits:=rfl\n/-- Exact one seed physically acquired by its actual constant push and reduction. -/\ntheorem prepared_one (n:SignedWord) (d w:List Bool):P.result n d w (.aux .current)=\n    (SemiprimeD1JetScalarBits.reduce w.length [true]).bits:=rfl\n/-- Actual current cache after exactly the physically present WIDTH markers is the ORIGINAL inverse word, without any inverse oracle. -/\ntheorem inverse_original (n:SignedWord) (d:List Bool) (p:Nat):\n    states p (P.result n d (List.replicate p true)) (.aux .current)=\n      (SemiprimeD1OddInverseBits.inverse p (odd d)).bits:=by\n  rw [states_current,prepared_width,prepared_a,prepared_negative,prepared_two,prepared_one]\n  simp only [List.length_replicate]\n  exact iterateWord_native p _ _ _ p\n/-- SAME original three-input program physically reaches the sign/final-product stage with its whole actual inverse loop paid. -/\ntheorem source_inverse (n:SignedWord) (d:List Bool) (hd:0<SemiprimeBitArithmetic.bitValue d) (p:Nat):\n    Runs program (SemiprimeD1StackRecoveryFinishFloor.floorTime n d+P.time n d (List.replicate p true)+\n      budget p (P.result n d (List.replicate p true))) (ctl .start)\n      (initial (SemiprimeD1StackRecoveryFinishSetup.signedTape n) d (List.replicate p true)).data\n      (ctl .signChoice) (data (states p (P.result n d (List.replicate p true)))):=\n  SemiprimeD1StackRecoveryFinishPrimitives.join (P.source_prepared n d hd (List.replicate p true))\n    (loop_run p (P.result n d (List.replicate p true)) (prepared_clean n d _) rfl)\nend RiemannGaussian.SemiprimeD1StackRecoveryFinishNewtonOriginal\n","RiemannGaussian.SemiprimeD1StackRecoveryGridFrontBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridStateCaps\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridModelBounds\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridPowerBounds\nimport RiemannGaussian.SemiprimeD1StackWordFitBounds\n/-! # Actual original-input frontend clock and semantic physical boundary caps -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridFrontBounds\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView\nnamespace F\nexport SemiprimeD1StackRecoveryGridFront (result clean centered decremented sizeWord runBound)\nend F\nnamespace Model\nexport SemiprimeD1StackRecoveryGridModel (view one front_eq)\nend Model\nnamespace R\nexport SemiprimeD1StackRecoveryGridResource (resource gridSize cacheWidth dataWidth resource_pos a_le M_le u_le t_le width_le grid_le index_le cache_le width_cache cache_data counts_data small_le_cubic)\nend R\nnamespace Caps\nexport SemiprimeD1StackRecoveryGridWordCaps (Registers Data mass_le put_registers put_data power_width)\nend Caps\n/-- All actual first-row register/data words satisfy their semantic caps. -/\ntheorem result_caps (a M u:Nat) (t width:List Bool) :\n    Caps.Registers (F.result a M u t width) (R.cacheWidth a width) ∧\n    Caps.Data (F.result a M u t width) (R.dataWidth a M u t width):=by\n  have hp:=SemiprimeD1StackRecoveryGridPayloadBounds.one_bounded width (SemiprimeD1TaperedLoss.height M u*u)\n  have hq:(SemiprimeD1StackRecoveryGridDecrement.difference (F.sizeWord a)).length≤a+2:=by\n    exact le_of_eq (SemiprimeD1StackRecoveryGridFront.q_width a M u t width)\n  have hr:=SemiprimeD1StackRecoveryGridModelBounds.registers_le a M u (R.gridSize a) 0 t (SemiprimeD1StackRecoveryGridDecrement.difference (F.sizeWord a)) width Model.one hp\n  have hd:=SemiprimeD1StackRecoveryGridModelBounds.data_le a M u (R.gridSize a) 0 t (SemiprimeD1StackRecoveryGridDecrement.difference (F.sizeWord a)) width Model.one hp (by omega) hq\n  constructor\n  · intro r b\n    change (bank (F.result a M u t width) (reg r b)).length≤_\n    rw [Model.front_eq]\n    exact hr r b\n  · intro k\n    rw [Model.front_eq]\n    exact hd k\n/-- Before center/alpha construction, those two caches are EMPTY and every other actual word already equals the final frontend bank. -/\ntheorem clean_word (a M u:Nat) (t width:List Bool) (k:Stack) :\n    (bank (F.clean a M u t width) k).length≤(bank (F.result a M u t width) k).length:=by\n  rcases k with k|k\n  · rfl\n  · rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · rcases k with k|k\n          · rcases k with ⟨r,b⟩\n            cases r <;> cases b <;> first | exact le_refl _ | exact Nat.zero_le _\n          · rfl\n/-- Actual clean pre-power source words use the same physical caps. -/\ntheorem clean_caps (a M u:Nat) (t width:List Bool) :\n    Caps.Registers (F.clean a M u t width) (R.cacheWidth a width) ∧\n    Caps.Data (F.clean a M u t width) (R.dataWidth a M u t width):=by\n  obtain ⟨hr,hd⟩:=result_caps a M u t width\n  exact ⟨fun r b=>(clean_word a M u t width (reg r b)).trans (hr r b),fun k=>(clean_word a M u t width k).trans (hd k)⟩\n/-- The actual acquired initial geometry fields have the same physical linear source cap. -/\ntheorem geometry_le (a M u:Nat) (t width:List Bool) (k:G.Aux) :\n    ((F.decremented a M u t width).geometry k).length≤20000*(a+t.length+1):=by\n  have h:=SemiprimeD1StackRecoveryGridStateCaps.geometry_word (List.replicate a true) t (.inr k)\n  rw [List.length_replicate] at h\n  cases k <;> first | exact Nat.zero_le _ | exact h\n/-- All acquired metadata and both counted displaced shadows fit the global actual-word cap before their real drains. -/\ntheorem decremented_data (a M u:Nat) (t width:List Bool) :Caps.Data (F.decremented a M u t width) (R.dataWidth a M u t width):=by\n  have hd:=(clean_caps a M u t width).2\n  have ha:=R.a_le a M u t width\n  have ht:=R.t_le a M u t width\n  have hR:=R.resource_pos a M u t width\n  have hg:20000*(a+t.length+1)≤R.dataWidth a M u t width:=\n    R.small_le_cubic _ _ hR (by omega)\n  intro k\n  rcases k with k|k\n  · exact hd (rationalStack k)\n  · rcases k with k|k\n    · exact (geometry_le a M u t width k).trans hg\n    · rcases k with k|k\n      · exact hd (divisionStack k)\n      · rcases k with k|k\n        · exact hd (productStack k)\n        · rcases k with k|k\n          · exact hd (reg k.1 k.2)\n          · exact hd (aux k)\n/-- The same actual original-input acquisition pays every literal, VALUE doubling, height division, index fit and geometry call. -/\ntheorem acquisition_le (a M u:Nat) (t width:List Bool) :\n    SemiprimeD1StackRecoveryGridAcquisition.runBound a M u t width≤10000*(R.resource a M u t width)^2:=by\n  have hR:=R.resource_pos a M u t width\n  have ha:=R.a_le a M u t width\n  have hM:=R.M_le a M u t width\n  have hu:=R.u_le a M u t width\n  have ht:=R.t_le a M u t width\n  have hN:=R.grid_le a M u t width\n  have hi:=R.index_le a M u t width\n  have hs:=SemiprimeD1StackRecoveryGridSetup.runBound_le a\n  have hf:=SemiprimeD1StackWordFitBounds.totalTime_le t (List.replicate (a+2) false)\n  rw [List.length_replicate] at hf\n  have hmag:=SemiprimeD1StackPhaseGeometryArithmetic.magnitude_length a t\n  have hm:(SemiprimeD1StackPhaseGeometryArithmetic.magnitude a t).length≤2*R.resource a M u t width:=by rw [hmag];omega\n  unfold SemiprimeD1StackRecoveryGridAcquisition.runBound SemiprimeD1StackRecoveryGridNode.runBound SemiprimeD1StackPhaseGeometryComponents.runBound\n  rw [List.length_replicate]\n  change SemiprimeD1StackRecoveryGridSetup.runBound a+1000*(M+u+1)+(5*t.length+4+SemiprimeD1StackWordFitExecution.totalTime t (List.replicate (a+2) false)+1+2)+(5*t.length+4)+(1000*(a+t.length+1)+1+(SemiprimeD1StackPhaseGeometryArithmetic.magnitude a t).length+1)≤_\n  have hp:=Nat.mul_le_mul hi (show 2^(a+1)+1≤2*R.resource a M u t width by change R.gridSize a+1≤_;omega)\n  nlinarith\n/-- The initial real binary decrement is paid by its actual true-size/raw-index words. -/\ntheorem decrement_le (a M u:Nat) (t width:List Bool) :\n    SemiprimeD1StackRecoveryGridDecrement.runBound (F.sizeWord a) t≤300*(R.resource a M u t width):=by\n  have h:=SemiprimeD1StackRecoveryGridDecrement.runBound_le (F.sizeWord a) t\n  have hl:(F.sizeWord a).length=a+2:=by rw [F.sizeWord,SemiprimeD1StackPhaseGeometryArithmetic.powerWord_length]\n  have hi:=R.index_le a M u t width\n  have ht:=R.t_le a M u t width\n  have hR:=R.resource_pos a M u t width\n  rw [hl] at h\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryGridFrontBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryGridRowBases":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridSite\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridPowerSource\n/-! # Actual original-grid row differences and both oriented powers -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridRowBases\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView SemiprimeD1StackRecoveryGridCalls\nopen SemiprimeD1StackRecoveryGridOperationInput SemiprimeD1StackRecoveryGridRegisters\nopen SemiprimeD1StackProcedureTrace\nnamespace Call\nexport SemiprimeD1StackRecoveryGridSite (result runBound site_call nonempty_preserved written_nonempty signed_getReg)\nend Call\nnamespace Power\nexport SemiprimeD1StackRecoveryGridPowerSource (power_source_run runBound)\nend Power\n/-- Actual signed grid-index negation. -/\ndef negative (w:Words) (width:List Bool) :Words:=Call.result .negativeIndex w width\n/-- Actual fitted center-minus-index word. -/\ndef numerator (w:Words) (width:List Bool) :Words:=Call.result .numeratorBase (negative w width) width\n/-- Actual fitted node-minus-index word, acquired before both power loops. -/\ndef result (w:Words) (width:List Bool) :Words:=Call.result .denominatorBase (numerator w width) width\n/-- Own actual three-operation row-base clock. -/\ndef runBound (w:Words) (width:List Bool) :Nat:=Call.runBound .negativeIndex w width+\n  Call.runBound .numeratorBase (negative w width) width+Call.runBound .denominatorBase (numerator w width) width\nattribute [local irreducible] runBound Call.runBound\n/-- Three real normalized/twice-fitted operations acquire both exact oriented row difference bases. -/\ntheorem bases_run (w:Words) (width:List Bool)\n    (hr:w.rational=emptyRational width) (hs:w.auxiliary .copyScratch=[])\n    (hi:w.registers (.index,false)≠[]) (hc:w.registers (.center,false)≠[]) (hn:w.registers (.node,false)≠[]) :\n    ∃q≤runBound w width,Runs program q (.local .negative) (bank w) (.local (.powerCount .numerator)) (bank (result w width)):=by\n  obtain ⟨t0,ht0,h0⟩:=Call.site_call .negativeIndex (.local .negative) (.local .numeratorBase) w width rfl hr hs hi hi\n  have hc1:=Call.nonempty_preserved .negativeIndex w width .center hc\n  have hneg1:=Call.written_nonempty .negativeIndex w width\n  obtain ⟨t1,ht1,h1⟩:=Call.site_call .numeratorBase (.local .numeratorBase) (.local .denominatorBase)\n    (negative w width) width rfl hr hs hc1 hneg1\n  have hn1:=Call.nonempty_preserved .negativeIndex w width .node hn\n  have hn2:=Call.nonempty_preserved .numeratorBase (negative w width) width .node hn1\n  have hneg2:=Call.nonempty_preserved .numeratorBase (negative w width) width .negative hneg1\n  obtain ⟨t2,ht2,h2⟩:=Call.site_call .denominatorBase (.local .denominatorBase) (.local (.powerCount .numerator))\n    (numerator w width) width rfl hr hs hn2 hneg2\n  change Runs program t0 _ _ _ (bank (negative w width)) at h0\n  change Runs program t1 _ _ _ (bank (numerator w width)) at h1\n  change Runs program t2 _ _ _ (bank (result w width)) at h2\n  refine ⟨t0+t1+t2,?_,PTrace.join (PTrace.join h0 h1) h2⟩\n  unfold runBound\n  omega\n/-- The actual numerator base has its sign byte after both subsequent acquisitions. -/\ntheorem numerator_nonempty (w:Words) (width:List Bool) :(result w width).registers (.numBase,false)≠[]:=\n  Call.nonempty_preserved .denominatorBase (numerator w width) width .numBase\n    (Call.written_nonempty .numeratorBase (negative w width) width)\n/-- The actual denominator base has its sign byte even for W0. -/\ntheorem denominator_nonempty (w:Words) (width:List Bool) :(result w width).registers (.denBase,false)≠[]:=\n  Call.written_nonempty .denominatorBase (numerator w width) width\n/-- Exact actual numerator-power cache, including the literal oneWord at zero multiplicity. -/\ndef numeratorPower (w:Words) (width:List Bool) (m:Nat) :Words:=\n  putReg w .numPower (SemiprimeD1RecoveryPowerBits.power width (getReg w .numBase) m).word\n/-- Exact actual denominator-power cache, preserving the numerator-power result and both bases. -/\ndef powersResult (w:Words) (width:List Bool) (m:Nat) :Words:=\n  let ready:=numeratorPower w width m\n  putReg ready .denPower (SemiprimeD1RecoveryPowerBits.power width (getReg ready .denBase) m).word\n/-- Own actual clocks of both paid multiplicity copies and complete oriented power-source calls. -/\ndef powersBound (w:Words) (width:List Bool) (m:Nat) :Nat:=\n  Power.runBound .numerator w width (getReg w .numBase) m+\n    Power.runBound .denominator (numeratorPower w width m) width (getReg (numeratorPower w width m) .denBase) m\nattribute [local irreducible] powersBound Power.runBound\n/-- Both row powers consume physical copies of the same actual acquired multiplicity, with accumulator FIRST and base SECOND. -/\ntheorem powers_run (w:Words) (width:List Bool) (m:Nat)\n    (hr:w.rational=emptyRational width) (hs:w.auxiliary .copyScratch=[])\n    (hz:w.auxiliary .powerTodo=[]) (hm:w.product .product=List.replicate m true)\n    (hn:w.registers (.numBase,false)≠[]) (hd:w.registers (.denBase,false)≠[]) :\n    ∃q≤powersBound w width m,Runs program q (.local (.powerCount .numerator)) (bank w) (.local .reciprocal)\n      (bank (powersResult w width m)):=by\n  obtain ⟨p,hp,h0⟩:=Power.power_source_run .numerator w width (getReg w .numBase) m hr hs hz hm\n    (Call.signed_getReg w .numBase hn) rfl\n  change Runs program p _ _ _ (bank (numeratorPower w width m)) at h0\n  have hd1:(numeratorPower w width m).registers (.denBase,false)≠[]:=by\n    rw [show (numeratorPower w width m).registers (.denBase,false)=w.registers (.denBase,false) from\n      putReg_other w .numPower .denBase _ false (by decide)]\n    exact hd\n  obtain ⟨q,hq,h1⟩:=Power.power_source_run .denominator (numeratorPower w width m) width\n    (getReg (numeratorPower w width m) .denBase) m hr hs hz hm\n    (Call.signed_getReg _ .denBase hd1) rfl\n  change Runs program q _ _ _ (bank (powersResult w width m)) at h1\n  refine ⟨p+q,?_,PTrace.join h0 h1⟩\n  unfold powersBound\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryGridRowBases\n","RiemannGaussian.SemiprimeD1StackRecoveryGridRowSlopes":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridSite\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridRepeats\n/-! # Actual slope acquisition, chronological occurrence framing and oriented row folds -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridRowSlopes\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView SemiprimeD1StackRecoveryGridCalls\nopen SemiprimeD1StackRecoveryGridOperationInput\nopen SemiprimeD1StackProcedureTrace\nnamespace Call\nexport SemiprimeD1StackRecoveryGridSite (result runBound site_call nonempty_preserved written_nonempty signed_getReg)\nend Call\nnamespace Repeat\nexport SemiprimeD1StackRecoveryGridRepeats (buffers repeats_run rows)\nend Repeat\n/-- Actual reciprocal of the fitted node-minus-q word. -/\ndef reciprocal (w:Words) (width:List Bool) :Words:=Call.result .reciprocal w width\n/-- Actual original slope alpha/(node-q), normalized and twice physically fitted. -/\ndef slope (w:Words) (width:List Bool) :Words:=Call.result .slope (reciprocal w width) width\n/-- Own clock of the two actual slope operations. -/\ndef slopeBound (w:Words) (width:List Bool) :Nat:=\n  Call.runBound .reciprocal w width+Call.runBound .slope (reciprocal w width) width\nattribute [local irreducible] slopeBound Call.runBound\n/-- Whole actual slope acquisition uses only actual retained bases and alpha. -/\ntheorem slope_run (w:Words) (width:List Bool)\n    (hr:w.rational=emptyRational width) (hs:w.auxiliary .copyScratch=[])\n    (hd:w.registers (.denBase,false)≠[]) (ha:w.registers (.alpha,false)≠[]) :\n    ∃q≤ slopeBound w width,Runs program q (.local .reciprocal) (bank w) (.local .repeat) (bank (slope w width)):=by\n  obtain ⟨p,hp,h0⟩:=Call.site_call .reciprocal (.local .reciprocal) (.local .slope) w width rfl hr hs hd hd\n  have ha1:=Call.nonempty_preserved .reciprocal w width .alpha ha\n  have hr1:=Call.written_nonempty .reciprocal w width\n  obtain ⟨q,hq,h1⟩:=Call.site_call .slope (.local .slope) (.local .repeat) (reciprocal w width) width rfl hr hs ha1 hr1\n  change Runs program p _ _ _ (bank (reciprocal w width)) at h0\n  change Runs program q _ _ _ (bank (slope w width)) at h1\n  refine ⟨p+q,?_,PTrace.join h0 h1⟩\n  unfold slopeBound\n  omega\n/-- Exact newly framed chronological repeated slopes, preserving the existing physical tail without recopying it. -/\ndef repeated (w:Words) (word:SemiprimeRationalBits.RationalWord) (m:Nat) :Words:=\n  {w with auxiliary:=Function.update w.auxiliary .slopes (Repeat.rows word m (w.auxiliary .slopes))}\n/-- Whole repetition clock pays the actual m-marker copy and every two-Frame occurrence. -/\ndef repeatBound (word:SemiprimeRationalBits.RationalWord) (m:Nat) :Nat:=\n  (5*m+4)+(m*(6*((signed word).length+word.denominator.length)+12)+1)\n/-- The actual m-copy and physical framing loop acquire every slope occurrence exactly once. -/\ntheorem repeat_run (w:Words) (word:SemiprimeRationalBits.RationalWord) (m:Nat)\n    (hm:w.product .product=List.replicate m true) (hz:w.auxiliary .repeatTodo=[])\n    (hs:w.auxiliary .copyScratch=[]) (hf:w.auxiliary .frameScratch=[])\n    (hn:w.registers (.slope,false)=signed word) (hd:w.registers (.slope,true)=word.denominator) :\n    Runs program (repeatBound word m) (.local .repeat) (bank w) (.local .numeratorFold) (bank (repeated w word m)):=by\n  have h0:=PTrace.copy_call .repeat (.local .repeat) (.local .repeats) rfl (bank w) (List.replicate m true) [] hm hz hs\n  change Runs program _ _ _ _ (Function.update (bank w) (aux .repeatTodo) (List.replicate m true++[])) at h0\n  rw [List.append_nil,update_auxiliary] at h0\n  have he:Repeat.buffers w (List.replicate m true) (w.auxiliary .slopes)=\n      {w with auxiliary:=Function.update w.auxiliary .repeatTodo (List.replicate m true)}:=by\n    dsimp only [Repeat.buffers,SemiprimeD1StackRecoveryGridRepeats.buffers]\n    congr 1\n    funext k\n    cases k <;> rfl\n  rw [←he] at h0\n  have h1:=Repeat.repeats_run w word m (w.auxiliary .slopes) hn hd hf\n  have hf:Repeat.buffers w [] (Repeat.rows word m (w.auxiliary .slopes))=repeated w word m:=by\n    dsimp only [Repeat.buffers,SemiprimeD1StackRecoveryGridRepeats.buffers,repeated]\n    congr 1\n    funext k\n    cases k <;> first | rfl | exact hz.symm\n  rw [hf] at h1\n  simpa only [repeatBound,List.length_replicate] using PTrace.join h0 h1\n/-- Actual numerator fold uses power FIRST and previously acquired tail SECOND. -/\ndef numerator (w:Words) (width:List Bool) :Words:=Call.result .numeratorFold w width\n/-- Actual denominator fold uses power FIRST and previously acquired tail SECOND. -/\ndef folded (w:Words) (width:List Bool) :Words:=Call.result .denominatorFold (numerator w width) width\n/-- Own exact pair of actual row-fold clocks. -/\ndef foldBound (w:Words) (width:List Bool) :Nat:=\n  Call.runBound .numeratorFold w width+Call.runBound .denominatorFold (numerator w width) width\nattribute [local irreducible] foldBound\n/-- Both true original right-fold multiplications run even when actual multiplicity is zero. -/\ntheorem fold_run (w:Words) (width:List Bool)\n    (hr:w.rational=emptyRational width) (hs:w.auxiliary .copyScratch=[])\n    (hn:w.registers (.numPower,false)≠[]) (hgn:w.registers (.gridNum,false)≠[])\n    (hd:w.registers (.denPower,false)≠[]) (hgd:w.registers (.gridDen,false)≠[]) :\n    ∃q≤ foldBound w width,Runs program q (.local .numeratorFold) (bank w)\n      (.local (.clearTransient false 0)) (bank (folded w width)):=by\n  obtain ⟨p,hp,h0⟩:=Call.site_call .numeratorFold (.local .numeratorFold) (.local .denominatorFold) w width rfl hr hs hn hgn\n  have hd1:=Call.nonempty_preserved .numeratorFold w width .denPower hd\n  have hgd1:=Call.nonempty_preserved .numeratorFold w width .gridDen hgd\n  obtain ⟨q,hq,h1⟩:=Call.site_call .denominatorFold (.local .denominatorFold) (.local (.clearTransient false 0))\n    (numerator w width) width rfl hr hs hd1 hgd1\n  change Runs program p _ _ _ (bank (numerator w width)) at h0\n  change Runs program q _ _ _ (bank (folded w width)) at h1\n  refine ⟨p+q,?_,PTrace.join h0 h1⟩\n  unfold foldBound\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryGridRowSlopes\n","RiemannGaussian.SemiprimeD1StackRecoveryGridStateCaps":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridWordCaps\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridGeometry\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridSite\n/-! # Actual arithmetic/geometry boundary word-cap preservation -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridStateCaps\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView\nnamespace Caps\nexport SemiprimeD1StackRecoveryGridWordCaps (Registers Data put_registers put_data)\nend Caps\nnamespace Site\nexport SemiprimeD1StackRecoveryGridSite (answer result)\nend Site\nnamespace Geometry\nexport SemiprimeD1StackRecoveryGridGeometry (result)\nend Geometry\n/-- Both actual site outputs have exactly W bytes; the sign is one separate actual byte. -/\ntheorem answer_width (site:SemiprimeD1StackRecoveryGrid.Site) (w:Words) (width:List Bool) :\n    (Site.answer site w width).numerator.magnitude.length=width.length ∧(Site.answer site w width).denominator.length=width.length:=\n  SemiprimeD1StackRecoveryGridByteBounds.operation_lengths _ _ _ width\n/-- Actual whole-operation cache writes retain a semantic register-width cap. -/\ntheorem site_registers (site:SemiprimeD1StackRecoveryGrid.Site) (w:Words) (width:List Bool) (B:Nat)\n    (hw:Caps.Registers w B) (hW:width.length+1≤ B) :Caps.Registers (Site.result site w width) B:=by\n  have h:=answer_width site w width\n  exact Caps.put_registers w _ _ B hw (by omega) (by omega)\n/-- Actual whole-operation cache writes leave foreign data words untouched and preserve their physical cap. -/\ntheorem site_data (site:SemiprimeD1StackRecoveryGrid.Site) (w:Words) (width:List Bool) (L:Nat)\n    (hw:Caps.Data w L) (hW:width.length+1≤ L) :Caps.Data (Site.result site w width) L:=by\n  have h:=answer_width site w width\n  exact Caps.put_data w _ _ L hw (by omega) (by omega)\n/-- SAME closed actual fourteen-role source bounds every acquired geometry word; no legacy metadata-work clock is used. -/\ntheorem geometry_word (a q:List Bool) (k:G.Stack) :\n    (SemiprimeD1StackPhaseGeometryComponents.result a q k).length≤20000*(a.length+q.length+1):=by\n  obtain ⟨s,_,hr⟩:=SemiprimeD1StackPhaseGeometryExecution.source_run a q\n  have hc:=SemiprimeD1StackPhaseGeometryBounds.prefix_cells a q s (SemiprimeD1StackPhaseGeometryExecution.done a q) hr\n  have hs:(SemiprimeD1StackPhaseGeometryComponents.result a q k).length≤\n      ∑j:G.Stack,(SemiprimeD1StackPhaseGeometryComponents.result a q j).length:=\n    Finset.single_le_sum (f:=fun j:G.Stack=>(SemiprimeD1StackPhaseGeometryComponents.result a q j).length) (fun _ _=>Nat.zero_le _) (Finset.mem_univ k)\n  change (∑j:G.Stack,(SemiprimeD1StackPhaseGeometryComponents.result a q j).length)+0≤_ at hc\n  omega\n/-- Real geometry output/drain does not alter rational cache registers. -/\ntheorem geometry_registers (w:Words) (a q:List Bool) (B:Nat) (hw:Caps.Registers w B) :Caps.Registers (Geometry.result w a q) B:=hw\n/-- Exactly the acquired physical geometry words change; both displaced original shadows and all other100 roles retain their actual caps. -/\ntheorem geometry_data (w:Words) (a q:List Bool) (L:Nat) (hw:Caps.Data w L)\n    (hg:20000*(a.length+q.length+1)≤ L) :Caps.Data (Geometry.result w a q) L:=by\n  intro k\n  rcases k with k|k\n  · exact hw (rationalStack k)\n  · rcases k with k|k\n    · change (if k=.exponent ∨k=.index then w.geometry k else SemiprimeD1StackPhaseGeometryComponents.result a q (.inr k)).length≤ L\n      split\n      · exact hw (geometryAux k)\n      · exact (geometry_word a q (.inr k)).trans hg\n    · rcases k with k|k\n      · exact hw (divisionStack k)\n      · rcases k with k|k\n        · exact hw (productStack k)\n        · rcases k with k|k\n          · exact hw (reg k.1 k.2)\n          · exact hw (aux k)\nend RiemannGaussian.SemiprimeD1StackRecoveryGridStateCaps\n","RiemannGaussian.SemiprimeD1StackRecoveryGridWorkBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridStageBounds\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridRowWork\n/-! # Own whole row-body clock from semantic fitted widths and actual emitted bytes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridWorkBounds\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView\nnamespace Caps\nexport SemiprimeD1StackRecoveryGridWordCaps (Registers Data auxiliary_data)\nexport SemiprimeD1StackRecoveryGridBoundaryCaps (metadata_data powers_registers powers_data)\nend Caps\nnamespace S\nexport SemiprimeD1StackRecoveryGridStageBounds (siteCap powerCap bases_caps bases_le powers_le slopes_caps slopes_le folds_caps folds_le cleanup_le)\nend S\nnamespace W\nexport SemiprimeD1StackRecoveryGridRowWork (metadata bases powers tailSlope tailFramed tailFolded tailBound runBound)\nend W\nnamespace Slopes\nexport SemiprimeD1StackRecoveryGridRowSlopes (slope repeated repeatBound)\nend Slopes\n/-- Physical Frame/tag row length, including every zero/sign/terminator byte. -/\ntheorem rows_length (x:SemiprimeRationalBits.RationalWord) (m:Nat) (tail:List Bool) :\n    (SemiprimeD1StackRecoveryGridRepeats.rows x m tail).length=m*(2*(x.numerator.magnitude.length+x.denominator.length)+5)+tail.length:=by\n  induction m generalizing tail with\n  | zero=>simp only [SemiprimeD1StackRecoveryGridRepeats.rows,Nat.zero_mul,Nat.zero_add]\n  | succ m ih=>\n    rw [SemiprimeD1StackRecoveryGridRepeats.rows,ih,SemiprimeD1StackRecoveryGridByteBounds.slopeRow_length]\n    ring\n/-- The actual slope cache is normalized and twice fitted, including W0. -/\ntheorem slope_width (w:Words) (width:List Bool) :\n    (getReg (Slopes.slope w width) .slope).numerator.magnitude.length=width.length ∧\n    (getReg (Slopes.slope w width) .slope).denominator.length=width.length:=by\n  unfold Slopes.slope SemiprimeD1StackRecoveryGridSite.result\n  change (getReg (putReg _ .slope _) .slope).numerator.magnitude.length=_ ∧ (getReg (putReg _ .slope _) .slope).denominator.length=_\n  rw [SemiprimeD1StackRecoveryGridRegisters.getReg_putReg]\n  exact SemiprimeD1StackRecoveryGridStateCaps.answer_width .slope _ width\n/-- Actual repeated frames enlarge only slopes; accumulated tails are retained and charged once in the word cap. -/\ntheorem framed_data (w:Words) (width:List Bool) (m B L:Nat)\n    (hW:width.length+2≤ B) (hBL:B≤ L) (hr:Caps.Registers w B) (hd:Caps.Data w L)\n    (hm:m*(4*width.length+5)≤ L) :\n    Caps.Registers (W.tailFramed w width m) B ∧Caps.Data (W.tailFramed w width m) (2*L):=by\n  obtain ⟨hr0,hd0⟩:=S.slopes_caps w width B L hW hBL hr hd\n  have hx:=slope_width w width\n  change (getReg (W.tailSlope w width) .slope).numerator.magnitude.length=width.length ∧ (getReg (W.tailSlope w width) .slope).denominator.length=width.length at hx\n  have ht:=hd0 (aux .slopes)\n  change ((W.tailSlope w width).auxiliary .slopes).length≤ L at ht\n  have hlen:(SemiprimeD1StackRecoveryGridRepeats.rows (getReg (W.tailSlope w width) .slope) m\n      ((W.tailSlope w width).auxiliary .slopes)).length≤2*L:=by\n    rw [rows_length,hx.1,hx.2]\n    have he:2*(width.length+width.length)+5=4*width.length+5:=by omega\n    rw [he]\n    omega\n  refine ⟨hr0,?_⟩\n  apply Caps.auxiliary_data _ .slopes _ (2*L) (fun k=>(hd0 k).trans (by omega)) hlen\n/-- Real marker-copy and each pair of actual slope frames are explicitly paid. -/\ntheorem repeats_le (w:Words) (width:List Bool) (m:Nat) :\n    Slopes.repeatBound (getReg (W.tailSlope w width) .slope) m≤100*(m+1)*(width.length+1):=by\n  have hx:=slope_width w width\n  change (getReg (W.tailSlope w width) .slope).numerator.magnitude.length=width.length ∧ (getReg (W.tailSlope w width) .slope).denominator.length=width.length at hx\n  unfold Slopes.repeatBound signed\n  rw [List.length_cons,hx.1,hx.2]\n  nlinarith\nattribute [local irreducible] Slopes.repeatBound S.siteCap S.powerCap\n/-- Same actual reciprocal/frame/fold/cleanup tail, with all private EOF drains and real returns. -/\ntheorem tail_le (w:Words) (width:List Bool) (m B L:Nat)\n    (hW:width.length+2≤ B) (hBL:B≤ L) (hr:Caps.Registers w B) (hd:Caps.Data w L)\n    (hm:m*(4*width.length+5)≤ L) :\n    W.tailBound w width m≤2*S.siteCap B L+100*(m+1)*(width.length+1)+2*S.siteCap B (2*L)+3000*(2*L+1):=by\n  have h0:=S.slopes_le w width B L hW hBL hr hd\n  have h1:=repeats_le w width m\n  obtain ⟨hr0,hd0⟩:=framed_data w width m B L hW hBL hr hd hm\n  have h2:=S.folds_le (W.tailFramed w width m) width B (2*L) hW (by omega) hr0 hd0\n  obtain ⟨_,hd1⟩:=S.folds_caps (W.tailFramed w width m) width B (2*L) hW (by omega) hr0 hd0\n  have h3:=S.cleanup_le (W.tailFolded w width m) (2*L) hd1\n  unfold W.tailBound\n  omega\n/-- Own body cap follows the same actual metadata, three differences, two powers and physical framed tail. -/\ntheorem work_le (w:Words) (width:List Bool) (h u order B L:Nat)\n    (hW:width.length+2≤ B) (hBL:B≤ L) (hr:Caps.Registers w B) (hd:Caps.Data w L)\n    (hm:h*(u-order)+1≤ L) (hbytes:h*(u-order)*(4*width.length+5)≤ L) :\n    W.runBound w width h u order≤100*(h+u+order+1)^2+5*S.siteCap B L+\n      2*S.powerCap (h*(u-order)) B L+100*(h*(u-order)+1)*(width.length+1)+2*S.siteCap B (2*L)+3000*(2*L+1):=by\n  have h0:=SemiprimeD1StackRecoveryGridMultiplicity.runBound_le h u order\n  have hmd:Caps.Data (W.metadata w h u order) L:=Caps.metadata_data w (h*(u-order)) L hd (by omega)\n  have h1:=S.bases_le (W.metadata w h u order) width B L hW hBL hr hmd\n  obtain ⟨hr1,hd1⟩:=S.bases_caps (W.metadata w h u order) width B L hW hBL hr hmd\n  have h2:=S.powers_le (W.bases w width h u order) width (h*(u-order)) B L hW hBL hm hr1 hd1\n  have hr2:=Caps.powers_registers (W.bases w width h u order) width (h*(u-order)) B hr1 hW\n  have hd2:=Caps.powers_data (W.bases w width h u order) width (h*(u-order)) L hd1 (by omega)\n  have h3:=tail_le (W.powers w width h u order) width (h*(u-order)) B L hW hBL hr2 hd2 hbytes\n  unfold W.runBound\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryGridWorkBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryNodeOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryNodeStorage\n/-! # Whole actual five-word source equals complete original acquireAt byte array\nEvery coefficient is acquired by real indexed reads/multiply/add/normalization;\noriginal metadata and paid W alone discharge canonical values/denominators.\nThe literal N-only caller and recursive scalar counter remain separate joins.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryNodeOriginal\nopen SemiprimeD1StackRecoveryNode SemiprimeD1StackRecoveryNodeEncoding\nopen SemiprimeD1StackRecoveryNodeBounds\n/-- ALL actual old140 source/cache/shadow words survive the whole weight call byte-for-byte. -/\ntheorem old_retained (a M u:ℕ) (selected:Fin (2^(a+1))) (t width:List Bool) (role:N.Stack):\n    result a M u selected t width (node role)=SemiprimeD1StackRecoveryNodeInputsEncoding.result a M u selected t width role:=\n  SemiprimeD1StackRecoveryNodeView.old_retained _ _ role\n/-- The complete chronological coefficient tape is the only newly acquired physical word. -/\ntheorem output_word (a M u:ℕ) (selected:Fin (2^(a+1))) (t width:List Bool):\n    result a M u selected t width output=tape a M u selected width:=by\n  unfold result V.result\n  rw [Function.update_self]\n/-- RAW complete array equality with original acquireAt, including q0/W0/defaults and operand order. -/\ntheorem words_original (a M u:ℕ) (selected:Fin (2^(a+1))) (width:List Bool):\n    words a M u selected width=(SemiprimeD1RecoveryNodeBits.acquireAt width a M u selected).words:=\n  SemiprimeD1StackRecoveryWeightsLegacy.array_acquireAt width a M u selected\n/-- Original dimension guard and actual W derive all canonical numerator/denominator fields internally. -/\ntheorem values_original (a M u:ℕ) (selected:Fin (2^(a+1))) (width:List Bool)\n    (hu:u≤M) (hW:SemiprimeD1RecoveryNodeBits.width a M≤width.length):\n    let actual:=words a M u selected width\n    let expected:=(SemiprimeD1JetRecoveryWeights.acquire a (SemiprimeD1TaperedLoss.height M u) u selected.val).weights.toList\n    actual.map SemiprimeRationalBits.RationalWord.value=expected ∧ (∀x∈actual,x.Valid) ∧\n      (∀x∈actual,SemiprimeRationalBits.Width x width.length) ∧\n      actual.map (fun x=>(x.numerator.value,SemiprimeBitArithmetic.bitValue x.denominator))=expected.map (fun x=>(x.num,x.den)):=\n  SemiprimeD1StackRecoveryWeightsLegacy.array_values width a M u selected hu hW\n/-- SAME actual whole source acquires the ENTIRE original local weights and retains the whole real old cache. -/\ntheorem source_run_original (a M u:ℕ) (selected:Fin (2^(a+1))) (t width:List Bool)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected.val):\n    ∃s≤polynomial a M u t width,SemiprimeD1StackCalls.run program s\n      (initial (List.replicate a true) (List.replicate M true) (List.replicate u true) t width)=some (done a M u selected t width) ∧\n      (done a M u selected t width).data output=\n        SemiprimeD1StackNormalizedInverse.tape (SemiprimeD1RecoveryNodeBits.acquireAt width a M u selected).words ∧\n      (∀role,(done a M u selected t width).data (node role)=SemiprimeD1StackRecoveryNodeInputsEncoding.result a M u selected t width role):=by\n  obtain ⟨s,hs,hr⟩:=source_run_bounded a M u selected t width ht\n  refine ⟨s,hs,hr,?_,old_retained a M u selected t width⟩\n  change result a M u selected t width output=_\n  rw [output_word,tape,words_original]\n/-- SAME actual-Grid-ready program continuation computes every remaining array/weight with no source replay. -/\ntheorem ready_run_original (a M u:ℕ) (selected:Fin (2^(a+1))) (t width:List Bool)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected.val):\n    ∃s≤polynomial a M u t width,SemiprimeD1StackCalls.run program s\n      (gridReady a M u selected t width)=some (done a M u selected t width) ∧\n      (done a M u selected t width).data output=\n        SemiprimeD1StackNormalizedInverse.tape (SemiprimeD1RecoveryNodeBits.acquireAt width a M u selected).words:=by\n  obtain ⟨s,hs,hr⟩:=ready_run_bounded a M u selected t width ht\n  refine ⟨s,hs,hr,?_⟩\n  change result a M u selected t width output=_\n  rw [output_word,tape,words_original]\nend RiemannGaussian.SemiprimeD1StackRecoveryNodeOriginal\n","RiemannGaussian.SemiprimeD1StackRootNetworkRowsComponents":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootNetworkRows\n/-! # Acquired-index alias and actual original-row ready call\nEvery original-network lookup contract is proved from the real compiled root.\nNo graph, routing, count or catalogue getter occurs in the program operands.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootNetworkRowsComponents\nopen SemiprimeD1StackRootNetworkRows SemiprimeD1StackProcedureTrace\nopen SemiprimeBitArithmetic (bitValue)\nnamespace E\nexport SemiprimeD1StackNetworkRowsExecution (ready done timeBound indexResult dictionaryRows)\nend E\nnamespace O\nexport SemiprimeD1StackNetworkRowsEncoding (ownerAt)\nexport SemiprimeD1StackNetworkRowsOriginal (original_contract)\nend O\nnamespace A\nexport SemiprimeD1StackRootOwnerIndexComponents (net rootowners)\nend A\nlocal notation \"ctl\" => (Sum.inl :Control→Label)\n/-- The physically retained original factor suffix, as a mathematical list specification only. -/\ndef rootfactors (bits:List Bool) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) :List SemiprimeD1LeafCounter.Vertex :=\n  (A.net bits hN fixed).right.toList\n/-- The actual acquired seventeen-role cache, before any factor suffix/lookup/row work. -/\ndef rowsSource (bits:List Bool) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) :C.State Q.Stack Q.Label :=\n  E.ready (A.rootowners bits hN fixed) (rootfactors bits hN fixed)\n/-- The actual final row/tally/cache bank; expected routing is proof notation only. -/\ndef rowsDone (bits:List Bool) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) :C.State Q.Stack Q.Label :=\n  E.done (A.rootowners bits hN fixed) (rootfactors bits hN fixed) (O.ownerAt (A.net bits hN fixed))\n/-- Whole physical store keeps every original source word and every new private row/tally word. -/\ndef result (bits:List Bool) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :Stack→List Bool :=\n  data (R.done bits hN fixed tail).data (rowsDone bits hN fixed).data\n/-- Generic exact projection through every shared or new actual row role. -/\ntheorem data_rows (root:R.Stack→List Bool) (rows:Q.Stack→List Bool)\n    (hi:∀k,root (R.indexStack k)=rows (.inl k)) (k:Q.Stack) :\n    data root rows (rowsStack k)=rows k :=by\n  rcases k with k|k\n  · exact hi k\n  · rfl\n/-- The actual index bank already acquired from N supplies every row-ready index operand without a copy or rerun. -/\ntheorem acquired_index (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool)\n    (k:SemiprimeD1StackNetworkOwnerIndex.Stack) :\n    (R.done bits hN fixed tail).data (R.indexStack k)=(rowsSource bits hN fixed).data (.inl k) :=\n  SemiprimeD1StackRootOwnerIndexOriginal.index_preserved bits hc hN fixed tail k\n/-- Either genuine original-input source runs inside this caller while every new row work word stays empty. -/\ntheorem root_lift (entry:R.Label) (pc:Control)\n    (hc:program (ctl pc)=.call (rootLabel entry) (ctl .rows))\n    (before after:C.State R.Stack R.Label) (q:Nat)\n    (he:before.pc=some entry) (hs:after.pc=none) (hb:before.frames=[]) (ha:after.frames=[])\n    (hr:SemiprimeD1StackCalls.run R.program q before=some after) :\n    Runs program (q+1) (ctl pc) (data before.data (fun _=>[])) (ctl .rows) (data after.data (fun _=>[])) :=by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program rootStack rootLabel Sum.inl_injective\n    R.program entry (fun _=>rfl) (ctl pc) (ctl .rows) hc q before after _ _ he hb hs ha hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · exact (hk k rfl).elim\n      · rfl\n/-- A literal row-ready call reuses its actual acquired index and preserves the caller's complete source bank. -/\ntheorem rows_lift (root:R.Stack→List Bool) (owners factors:List SemiprimeD1LeafCounter.Vertex) (route:Nat→List Bool)\n    (hp:∀v∈factors,∀p∈v.ports,SemiprimeD1StackOwnerFibre.values (SemiprimeD1StackUnaryDivmod.unary p) (E.dictionaryRows owners)=[route p] ∧\n      (route p).length≤owners.length+1)\n    (hi:∀k,root (R.indexStack k)=E.indexResult owners factors k) :\n    ∃q≤E.timeBound owners factors,Runs program (q+1) (ctl .rows) (data root (fun _=>[])) (ctl .done)\n      (data root (E.done owners factors route).data) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackNetworkRowsExecution.ready_run owners factors route hp\n  refine ⟨q,hq,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program rowsStack rowsLabel rows_injective\n    Q.program (.local .copyFactors) (fun _=>rfl) (ctl .rows) (ctl .done) rfl q\n    (E.ready owners factors) (E.done owners factors route) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k\n      rcases k with k|k\n      · exact hi k\n      · rcases k with k|k\n        · rfl\n        · cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k\n      apply data_rows\n      intro j\n      exact hi j\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · exact (hk (.inr k) rfl).elim\n/-- The original acquired root discharges all singleton/routing/owner-width contracts and starts the SAMEready program. -/\ntheorem rows_call (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :\n    ∃q≤E.timeBound (A.rootowners bits hN fixed) (rootfactors bits hN fixed),\n      Runs program (q+1) (ctl .rows) (data (R.done bits hN fixed tail).data (fun _=>[])) (ctl .done)\n        (result bits hN fixed tail) :=by\n  apply rows_lift\n  · exact O.original_contract (A.net bits hN fixed)\n      (SemiprimeD1StackRootOwnerIndexOriginal.original_wellFormed bits hN fixed)\n  · intro k\n    exact acquired_index bits hc hN fixed tail k\nend RiemannGaussian.SemiprimeD1StackRootNetworkRowsComponents\n","RiemannGaussian.SemiprimeD1StackRootPacketInventoryInputBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPacketInventoryEncoding\n/-! # Actual retained source words pay both copies and the complete real inventory\nBoth input byte lengths follow the SAME actual original-input producer trace.\nNo native key/catalogue/report size or supplied resource is transported.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPacketInventoryInputBounds\nopen SemiprimeD1StackRootPacketInventory SemiprimeD1StackRootPacketInventoryEncoding\nopen SemiprimeD1StackRootPacketInventoryInput SemiprimeD1StackRootPacketInventoryCalls\nopen SemiprimeBitArithmetic (bitValue)\n/-- Sole binary input bytes plus the SAME real producer's paid complete clock. -/\ndef envelope (bits:List Bool):Nat:=bits.length+SemiprimeD1StackRootRecoveryWidthBounds.runBound bits+1\n/-- Every actual stopped producer word is bounded by its own actual executed trace. -/\ntheorem root_word_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits) (k:R.Stack):\n    ((rootDone bits hN).data k).length ≤ envelope bits:=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackRootRecoveryWidthBounds.source_run_bounded bits hc hN\n  have h:=SemiprimeD1StackReturnLink.run_data_bound R.program q bits.length _ _\n    (SemiprimeD1StackRootRecoveryWidthStorage.initial_length bits) hr k\n  change ((rootDone bits hN).data k).length ≤ bits.length+q at h\n  unfold envelope\n  omega\n/-- Both consumer input lengths are physically paid, not estimated by an external key-count oracle. -/\ntheorem input_bytes (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits):\n    (SemiprimeD1TensorTapeCodec.vectorBits (A.keys bits hN)).length ≤ envelope bits ∧\n      (E.alphabet (A.dimension bits)).length ≤ envelope bits:=by\n  have hk:=root_word_bound bits hc hN Source.keysRole\n  have ha:=root_word_bound bits hc hN Source.catalogueRole\n  dsimp only [rootDone] at hk ha\n  rw [SemiprimeD1StackRootPacketInventorySources.keys_acquired bits hN] at hk\n  rw [SemiprimeD1StackRootPacketInventorySources.catalogue_acquired bits hN] at ha\n  exact ⟨hk,ha⟩\n/-- The actual source envelope pays each real metadata byte and every actual call/return. -/\ntheorem copy_time_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits):\n    inventoryCopyTime (rootDone bits hN).data ≤ 18*envelope bits:=by\n  have hk:=root_word_bound bits hc hN Source.keysRole\n  have ha:=root_word_bound bits hc hN Source.catalogueRole\n  have hp:1 ≤ envelope bits:=by unfold envelope;omega\n  unfold inventoryCopyTime\n  omega\n/-- SAME real59-role source cost is bounded from its actual two source-produced words. -/\ntheorem inventory_clock_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits):\n    B.byteBound (SemiprimeD1TensorTapeCodec.vectorBits (A.keys bits hN)) (E.alphabet (A.dimension bits)) ≤\n      1000000000000*3^4*(envelope bits)^4:=by\n  obtain ⟨hk,ha⟩:=input_bytes bits hc hN\n  have hp:1 ≤ envelope bits:=by unfold envelope;omega\n  have hs:(SemiprimeD1TensorTapeCodec.vectorBits (A.keys bits hN)).length+\n      (E.alphabet (A.dimension bits)).length+1 ≤ 3*envelope bits:=by omega\n  have h:=Nat.mul_le_mul_left 1000000000000 (Nat.pow_le_pow_left hs 4)\n  simpa only [B.byteBound,mul_pow,Nat.mul_assoc] using h\nend RiemannGaussian.SemiprimeD1StackRootPacketInventoryInputBounds\n","RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsBinding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsLoop\n/-! # Exact binding of physical issued references to original acquired phase banks -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsBinding\nopen SemiprimeD1StackRootPhaseFreshRecords SemiprimeD1StackRootPhaseFreshRecordsEncoding\nopen SemiprimeD1StackRootPhaseFreshRecordsSource SemiprimeD1StackRootPhaseFreshRecordsRows\nopen SemiprimeD1StackRootPhaseFreshRecordsLoop\nnamespace O\nexport SemiprimeD1StackRootPhaseParametersEncoding (exponentValue levelsValue edgeValue phases result references)\nexport SemiprimeD1StackRootPhaseParametersOriginal (heap_original counter_original output_original)\nend O\n/-- Literal chronological source indices and their corresponding phase words; proof specification only. -/\ndef entries (a u edges:Nat) (rows:List (List Bool)) :List (Entry (banks a u edges rows)) :=\n  List.ofFn (fun i:Fin rows.length=>(⟨i.val,by simpa only [banks,List.length_map] using i.isLt⟩,rows[i.val]))\n/-- Every actual issued ordinal refers to exactly its originally produced P48 bank. -/\ntheorem entries_bank (a u edges:Nat) (rows:List (List Bool)) (e:Entry (banks a u edges rows))\n    (he:e∈entries a u edges rows) :\n    (banks a u edges rows)[e.1.val]=SemiprimeD1StackPhaseCacheFreshComponents.phase a u edges e.2 [false,true] :=by\n  obtain ⟨i,rfl⟩:=List.mem_ofFn.mp he\n  exact bank_at a u edges rows i\n/-- Finite original source ordinals retain their literal chronological numeric order. -/\ntheorem finRange_values (m:Nat) :(List.finRange m).map Fin.val=List.range m :=by\n  induction m with\n  | zero=>rfl\n  | succ m ih=>simp only [List.finRange_succ,List.map_cons,List.map_map,Fin.val_zero,Fin.val_succ,\n      List.range_succ_eq_map,←ih,List.map_map,Function.comp_def,Nat.succ_eq_add_one]\n/-- The source's retained issued-reference vector is precisely the physical pointer-loop tape. -/\ntheorem entries_tape (a u edges:Nat) (rows:List (List Bool)) :\n    tape (entries a u edges rows)=SemiprimeD1TensorTapeCodec.vectorBits (O.references rows.length) :=by\n  rw [tape,A.rowTape_vector]\n  congr 1\n  unfold entries\n  rw [List.ofFn_eq_map,List.map_map]\n  change (List.finRange rows.length).map ((fun i=>List.replicate i true)∘Fin.val)=_\n  rw [←List.map_map,finRange_values]\n  rfl\n/-- Full85-cache records follow the original phase list exactly, including rejected phases. -/\ntheorem entries_cached (a u edges:Nat) (rows:List (List Bool)) :\n    cached a u edges (entries a u edges rows)=records a u edges rows :=by\n  unfold cached entries records\n  rw [List.map_ofFn]\n  exact List.ofFn_getElem_eq_map rows (record a u edges)\n/-- Actual N-only source heap, interpreted by the actual48-field restore grammar, with no new supplier. -/\ntheorem source_heap (bits:List Bool) :\n    O.result bits R.heap=E.heap (banks (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits) (O.phases bits)) :=by\n  rw [O.heap_original]\n  unfold E.heap\n  rw [records_bridge]\n/-- The physically retained source counter counts exactly the heap bank list. -/\ntheorem source_counter (bits:List Bool) :\n    O.result bits (R.aux .counter)=List.replicate\n      (banks (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits) (O.phases bits)).length true :=by\n  rw [O.counter_original]\n  simp only [banks,List.length_map]\n/-- The real source reference output is exactly the sweep reader, in its original forward order. -/\ntheorem source_reader (bits:List Bool) :\n    O.result bits R.output=tape (entries (O.exponentValue bits) (O.levelsValue bits) (O.edgeValue bits) (O.phases bits)) :=by\n  rw [O.output_original,entries_tape]\nend RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsBinding\n","RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsRows":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsSource\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsCleanView\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsSerialize\n/-! # One physical reference, whole cached Fresh call,85 frames, allocation and145 drains -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsRows\nopen SemiprimeD1StackRootPhaseFreshRecords SemiprimeD1StackRootPhaseFreshRecordsEncoding\nopen SemiprimeD1StackRootPhaseFreshRecordsPrimitives SemiprimeD1StackRootPhaseFreshRecordsCalls\nopen SemiprimeD1StackRootPhaseFreshRecordsView SemiprimeD1StackRootPhaseFreshRecordsSource\nopen SemiprimeD1StackRootPhaseFreshRecordsCleanView SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace E\nexport SemiprimeD1StackPhaseCacheFreshExecution (heap source done runBound)\nend E\n/-- Actual stopped logical client bank, including every shared P48 and Fresh field. -/\ndef stopped (root:R.Stack→List Bool) (a u edges:Nat) (t pointer:List Bool) :Q.Stack→List Bool :=\n  SemiprimeD1StackPhaseCacheFreshComponents.completed a u edges t [false,true] []\n    (root R.heap) (root (R.aux .counter)) pointer\n/-- The issued reference is logged by the real restoring body in chronological reverse history. -/\ndef nextHistory (n:Nat) (hist:List Bool) :List Bool :=\n  (true::frame (List.replicate n true) []).reverse++hist\n/-- Complete physical store after the client returned, before its85 framing calls. -/\ndef acquired (root:R.Stack→List Bool) (a u edges:Nat) (t pointer tail hp:List Bool) (n:Nat) (hist:List Bool) :Stack→List Bool :=\n  view root (stopped root a u edges t pointer) (work tail [] hp (List.replicate n true) [] hist [])\n/-- All actual work at the145-drain entry, with immutable source heap/count retained. -/\ndef logged (root:R.Stack→List Bool) (a u edges:Nat) (t pointer tail hp:List Bool) (n:Nat) (hist:List Bool) :Stack→List Bool :=\n  view root (stopped root a u edges t pointer)\n    (work tail (record a u edges t) (frame (record a u edges t) hp)\n      (List.replicate (n+1) true) (List.replicate n true) (nextHistory n hist) [])\n/-- Own physical row allowance pays the actual client value expansions, framing, heap and cleanup. -/\ndef rowBound (root:R.Stack→List Bool) (bs:List (SemiprimeD1StackPhaseWorkingPrecision.Stack→List Bool))\n    (i:Fin bs.length) (a u edges:Nat) (t tail hp:List Bool) (n:Nat) (hist:List Bool) :Nat :=\n  1000*(i.val+n+E.runBound bs i a u edges t [false,true] []+\n    SemiprimeD1StackRootPhaseFreshRecordsSerialize.freshMass (acquired root a u edges t (List.replicate i.val true) tail hp n hist)+\n    (record a u edges t).length+\n    SemiprimeD1StackRootPhaseFreshRecordsCleanup.mass (logged root a u edges t (List.replicate i.val true) tail hp n hist)+1)\n/-- A reference field is installed only by a physical copied-byte update. -/\ntheorem update_input_reference (hp cn ref axes next:List Bool) :\n    Function.update (Q.input hp cn ref axes) I.sourceReference next=Q.input hp cn next axes :=by\n  funext k\n  by_cases hk:k=I.sourceReference\n  · subst k;rw [Function.update_same];rfl\n  · rw [Function.update_of_ne hk,input_only,input_only]\n    by_cases hh:k=I.sourceHeap\n    · simp only [hh,ite_true]\n    · by_cases hc:k=I.sourceCounter\n      · simp only [hc,ite_true]\n      · simp only [hh,hc,hk,ite_false]\n/-- Actual row constructor pop exposes the following reference frame. -/\ntheorem header_row (root:R.Stack→List Bool) (pointer tail hp:List Bool) (n:Nat) (hist:List Bool) :\n    Runs program 1 .header (loop root (true::frame pointer tail) hp n hist) .parse\n      (view root (cacheInput root [] [false]) (work (frame pointer tail) [] hp (List.replicate n true) [] hist [])) :=by\n  apply one_base program _ _ (.pop (aux .reader) .finishSeed .finishSeed .parse) _ _ rfl\n  · rfl\n  · exact update_reader _ _ _ _ _ _ _ _ _ _\n/-- Validity is an actual parser-produced true bit, physically consumed before the source call. -/\ntheorem valid_row (root:R.Stack→List Bool) (pointer tail hp:List Bool) (n:Nat) (hist:List Bool) :\n    let bank:=view root (cacheInput root pointer [false]) (work tail [] hp (List.replicate n true) [] hist [])\n    Runs program 1 .check (Function.update bank (aux .valid) [true]) .freshCall bank :=by\n  dsimp only\n  apply one_base program _ _ (.pop (aux .valid) .abort .abort .freshCall) _ _ rfl\n  · rfl\n  · change Function.update (Function.update (view root (cacheInput root pointer [false])\n      (work tail [] hp (List.replicate n true) [] hist [])) (aux .valid) [true]) (aux .valid) []=_\n    rw [Function.update_idem]\n    exact Function.update_eq_self _ _\n/-- All85 framed words are taken from actual stopped Fresh fields, with shared P48 aliases respected. -/\ntheorem acquired_fresh (root:R.Stack→List Bool) (a u edges:Nat) (t pointer tail hp:List Bool)\n    (n:Nat) (hist:List Bool) (k:F.Stack) :\n    acquired root a u edges t pointer tail hp n hist (freshStack k)=freshResult a u edges t k :=by\n  rw [acquired,view_fresh]\n  exact SemiprimeD1StackPhaseCacheFreshComponents.fresh_data _ _ k\n/-- Complete same-program row preserves all188 original source cells, emits its85-word\nrecord once and physically clears all client work before advancing to the next reference. -/\ntheorem row_run (root:R.Stack→List Bool) (bs:List (SemiprimeD1StackPhaseWorkingPrecision.Stack→List Bool))\n    (i:Fin bs.length) (a u edges:Nat) (t tail hp:List Bool) (n:Nat) (hist:List Bool)\n    (hh:root R.heap=E.heap bs) (hc:root (R.aux .counter)=List.replicate bs.length true)\n    (hb:bs[i.val]=SemiprimeD1StackPhaseCacheFreshComponents.phase a u edges t [false,true]) :\n    ∃q ≤ rowBound root bs i a u edges t tail hp n hist,\n      Runs program q .header (loop root (true::frame (List.replicate i.val true) tail) hp n hist) .header\n        (loop root tail (frame (record a u edges t) hp) (n+1) (nextHistory n hist)) :=by\n  let ptr:=List.replicate i.val true\n  let w:=work tail [] hp (List.replicate n true) [] hist []\n  let initialQ:=cacheInput root ptr [false]\n  let qdone:=stopped root a u edges t ptr\n  let got:=acquired root a u edges t ptr tail hp n hist\n  let framed:=view root qdone (work tail (record a u edges t) hp (List.replicate n true) [] hist [])\n  let allocated:=view root qdone (work tail (record a u edges t) (frame (record a u edges t) hp)\n    (List.replicate (n+1) true) (List.replicate n true) hist [])\n  have h0:=header_row root ptr tail hp n hist\n  have h1:=parse_call (view root (cacheInput root [] [false]) (work (frame ptr tail) [] hp (List.replicate n true) [] hist [])) ptr tail rfl rfl rfl rfl\n  rw [update_reader,update_pointer] at h1\n  simp only [cacheInput,update_input_reference] at h1\n  have h2:=valid_row root ptr tail hp n hist\n  dsimp only at h2\n  obtain ⟨p,hpBound,h3⟩:=fresh_call root w bs i a u edges t hb\n  have hin:(E.source bs i []).data=initialQ:=by\n    change Q.input (E.heap bs) (List.replicate bs.length true) ptr [false]=cacheInput root ptr [false]\n    simp only [cacheInput,hh,hc]\n  have hout:(E.done bs i a u edges t [false,true] []).data=qdone:=by\n    change SemiprimeD1StackPhaseCacheFreshComponents.completed _ _ _ _ _ _ _ _ _=_\n    simp only [qdone,stopped,hh,hc,ptr]\n  rw [hin,hout] at h3\n  change Runs program (p+1) .freshCall (view root initialQ w) (.serialize 0) got at h3\n  obtain ⟨s,hsBound,h4⟩:=SemiprimeD1StackRootPhaseFreshRecordsSerialize.serialize_run got rfl rfl\n  have he4:Function.update got (aux .record) (freshRecord (fun k=>got (freshStack k)))=framed:=by\n    have he:(fun k=>got (freshStack k))=freshResult a u edges t:=funext (fun k=>acquired_fresh root a u edges t ptr tail hp n hist k)\n    rw [he]\n    exact update_currentRecord _ _ _ _ _ _ _ _ _ _\n  rw [he4] at h4\n  have h5:=allocate_call framed rfl rfl rfl\n  change Runs program (5*(List.replicate n true).length+6*(record a u edges t).length+8) .allocate framed .logReference\n    (Function.update (Function.update (Function.update framed (aux .heap) (frame (record a u edges t) hp))\n      (aux .counter) (true::List.replicate n true)) (aux .reference) (List.replicate n true)) at h5\n  rw [List.length_replicate,update_heap,update_counter,update_reference] at h5\n  change Runs program _ .allocate framed .logReference allocated at h5\n  obtain ⟨r,hrBound,h6⟩:=reference_call allocated rfl\n  have he6:Function.update allocated (aux .refsHistory)\n      ((true::frame (allocated (aux .reference)) []).reverse++allocated (aux .refsHistory))=\n      logged root a u edges t ptr tail hp n hist:=by\n    exact update_history _ _ _ _ _ _ _ _ _ _\n  rw [he6] at h6\n  obtain ⟨c,hcBound,h7⟩:=SemiprimeD1StackRootPhaseFreshRecordsCleanup.cleanup_run (logged root a u edges t ptr tail hp n hist)\n  rw [logged,cleared_view] at h7\n  have hclean:Q.input (qdone I.sourceHeap) (qdone I.sourceCounter) [] (qdone I.oldHeader)=cacheInput root [] [false]:=by\n    change Q.input (root R.heap) (root (R.aux .counter)) []\n      (SemiprimeD1StackPhaseCacheFreshComponents.completed _ _ _ _ _ _ _ _ _ I.oldHeader)=_\n    rw [completed_header]\n    rfl\n  change Q.input (qdone I.sourceHeap) (qdone I.sourceCounter) [] (qdone I.oldHeader)=_ at hclean\n  rw [hclean] at h7\n  change Runs program c (.clear 0) _ .header (loop root tail (frame (record a u edges t) hp) (n+1) (nextHistory n hist)) at h7\n  have hall:=compose (compose (compose (compose (compose (compose (compose h0 h1) h2) h3) h4) h5) h6) h7\n  refine ⟨_,?_,hall⟩\n  change r ≤ 6*(2*(List.replicate n true).length+3) at hrBound\n  rw [List.length_replicate] at hrBound\n  change s ≤ 85*(6*SemiprimeD1StackRootPhaseFreshRecordsSerialize.freshMass got+5)+1 at hsBound\n  unfold rowBound\n  change _ ≤ 1000*(i.val+n+_+SemiprimeD1StackRootPhaseFreshRecordsSerialize.freshMass got+_+_+1)\n  dsimp only [ptr] at hcBound\n  simp only [ptr,List.length_replicate]\n  omega\nend RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsRows\n","RiemannGaussian.SemiprimeD1StackRootPhaseGridPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseGridEncoding\n/-! # Real copied exponent bytes, binary-zero pushes and wrapped enumeration -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1500000\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseGridPrimitives\nopen SemiprimeD1StackRootPhaseGrid SemiprimeD1StackRootPhaseGridEncoding\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\n/-- Exact composition of actual fragments of the same fixed126-role source. -/\ntheorem compose {m n:Nat} {pc mid next:Label} {before middle after:Stack→List Bool}\n    (h:Runs program m pc before mid middle) (g:Runs program n mid middle next after) :\n    Runs program (m+n) pc before next after :=runs_trans program _ _ _ _ _ _ _ _ h g\n/-- One actual binary-zero-word push changes only its literal enum word. -/\ntheorem update_word (root:R.Stack→List Bool) (word counts work out next:List Bool) :\n    Function.update (view root word counts work out) (enumStack .word) next=view root next counts work out :=by\n  funext k;cases k with\n  | inl k=>rfl\n  | inr k=>cases k with\n    | inl k=>cases k <;> rfl\n    | inr i=>rfl\n/-- One actual count-byte pop retains every source and enumeration word. -/\ntheorem update_count (root:R.Stack→List Bool) (word counts work out next:List Bool) :\n    Function.update (view root word counts work out) count next=view root word next work out :=by\n  funext k;cases k with\n  | inl k=>rfl\n  | inr k=>cases k with\n    | inl k=>cases k <;> rfl\n    | inr i=>fin_cases i <;> rfl\n/-- Actual true guard bit chooses copying; it is never replaced by an evaluator. -/\ntheorem branch_true (root:R.Stack→List Bool) (hg:root R.output=[true]) :\n    Runs program 1 (ctl .branch) (prepared root) (ctl .copy) (prepared root) :=by\n  apply one_base program _ _ (.peek guard (ctl .done) (ctl .done) (ctl .copy)) _ _ rfl\n  · change some (SemiprimeD1StackBytecode.choose (ctl .done) (ctl .done) (ctl .copy) (root R.output).head?)=_\n    rw [hg];rfl\n  · rfl\n/-- Actual false guard skips copying, zero construction and every enumeration instruction. -/\ntheorem branch_false (root:R.Stack→List Bool) (hg:root R.output=[false]) :\n    Runs program 1 (ctl .branch) (prepared root) (ctl .done) (prepared root) :=by\n  apply one_base program _ _ (.peek guard (ctl .done) (ctl .done) (ctl .copy)) _ _ rfl\n  · change some (SemiprimeD1StackBytecode.choose (ctl .done) (ctl .done) (ctl .copy) (root R.output).head?)=_\n    rw [hg];rfl\n  · rfl\n/-- The parent exponent is read from its actual source word and retained by real Copy. -/\ntheorem copy_exponent (root:R.Stack→List Bool) (word:List Bool)\n    (ha:root (R.sourceStack SemiprimeD1StackRootParameters.exponent)=word) :\n    Runs program (5*word.length+4) (ctl .copy) (prepared root) (ctl .seed) (view root [] word [] []) :=by\n  apply included_call program copyStack copyLabel copy_injective SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (ctl .copy) (ctl .seed) rfl (5*word.length+3)\n    (SemiprimeD1StackCopy.state 0 none word [] []) (SemiprimeD1StackCopy.done word (word++[]))\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words word [] none\n  · constructor\n    · intro i;fin_cases i\n      · exact ha\n      · rfl\n      · rfl\n    · intro k _;rfl\n  · constructor\n    · intro i;fin_cases i\n      · exact ha\n      · change word=word++[];exact (List.append_nil word).symm\n      · rfl\n    · intro k hk\n      cases k with\n      | inl k=>rfl\n      | inr k=>cases k with\n        | inl k=>rfl\n        | inr i=>\n          fin_cases i\n          · exact (hk 1 rfl).elim\n          · rfl\n/-- One literal false bit seeds a nonempty binary zero word, even for exponent zero. -/\ntheorem seed_zero (root:R.Stack→List Bool) (counts:List Bool) :\n    Runs program 1 (ctl .seed) (view root [] counts [] []) (ctl .fill) (view root [false] counts [] []) :=by\n  apply one_base program _ _ (.push (enumStack .word) false (ctl .fill)) _ _ rfl\n  · rfl\n  · exact update_word _ _ _ _ _ _\n/-- Each actual exponent byte is popped and pays one literal false push. The\nresult has a linear binary width, never a unary2^a initialization. -/\ntheorem fill_zero (root:R.Stack→List Bool) (n k:Nat) :\n    Runs program (2*n+1) (ctl .fill) (view root (List.replicate k false) (List.replicate n true) [] [])\n      (ctl .enumerate) (view root (List.replicate (n+k) false) [] [] []) :=by\n  induction n generalizing k with\n  | zero=>\n    apply one_base program _ _ (.pop count (ctl .enumerate) (ctl .zero) (ctl .zero)) _ _ rfl\n    · rfl\n    · change Function.update (view root (List.replicate k false) [] [] []) count []=\n        view root (List.replicate (0+k) false) [] [] []\n      simpa only [Nat.zero_add] using update_count root (List.replicate k false) [] [] [] []\n  | succ n ih=>\n    have h0:Runs program 1 (ctl .fill) (view root (List.replicate k false) (List.replicate (n+1) true) [] [])\n        (ctl .zero) (view root (List.replicate k false) (List.replicate n true) [] []):=by\n      apply one_base program _ _ (.pop count (ctl .enumerate) (ctl .zero) (ctl .zero)) _ _ rfl\n      · rfl\n      · change Function.update (view root (List.replicate k false) (List.replicate (n+1) true) [] []) count\n          (List.replicate (n+1) true).tail=_\n        simp only [List.replicate_succ,List.tail_cons]\n        exact update_count _ _ _ _ _ _\n    have h1:Runs program 1 (ctl .zero) (view root (List.replicate k false) (List.replicate n true) [] [])\n        (ctl .fill) (view root (List.replicate (k+1) false) (List.replicate n true) [] []):=by\n      apply one_base program _ _ (.push (enumStack .word) false (ctl .fill)) _ _ rfl\n      · rfl\n      · change Function.update (view root (List.replicate k false) (List.replicate n true) [] []) (enumStack .word)\n          (false::List.replicate k false)=_\n        simpa only [List.replicate_succ] using update_word root (List.replicate k false) (List.replicate n true) [] [] (false::List.replicate k false)\n    have hh:=compose (compose h0 h1) (ih (k+1))\n    simpa only [show 1+1+(2*n+1)=2*(n+1)+1 by omega,show n+(k+1)=(n+1)+k by omega] using hh\n/-- The real frozen enumerator logs the binary zero, repeatedly increments to\noverflow and emits every phase word in chronological order, clearing all its work. -/\ntheorem enumerate_call (root:R.Stack→List Bool) (a:Nat) :\n    ∃t≤100*(a+2)*2^(a+1)+10, Runs program (t+1) (ctl .enumerate) (ready root a)\n      (ctl .done) (finished root true a) :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackAssignmentEnumerationBounds.zero_source_run (a+1)\n  refine ⟨t,by simpa only [Nat.add_assoc] using ht,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program enumStack enumLabel\n    (by intro i j h;exact Sum.inl.inj (Sum.inr.inj h)) A.code (A.control .bodyCall)\n    (fun _=>rfl) (ctl .enumerate) (ctl .done) rfl t\n    (SemiprimeD1StackCalls.initial (show A.Stack from .word) (A.control .bodyCall) (List.replicate (a+1) false))\n    (SemiprimeD1StackCalls.final (show A.Stack from .output) (grid a)) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k hk\n      cases k with\n      | inl k=>rfl\n      | inr k=>cases k with\n        | inl k=>exact (hk k rfl).elim\n        | inr i=>rfl\nend RiemannGaussian.SemiprimeD1StackRootPhaseGridPrimitives\n","RiemannGaussian.SemiprimeD1StackRootRecoveryWidthBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootRecoveryWidthExecution\n/-! # Own whole original-input width-source clock\nThe original root clock is retained once. Both actual unary metadata copies\nand the complete width source add a fixed original-bitlength polynomial.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootRecoveryWidthBounds\nopen SemiprimeD1StackRootRecoveryWidth SemiprimeD1StackRootRecoveryWidthEncoding\nopen SemiprimeD1StackRootRecoveryWidthExecution SemiprimeD1StackRootRecoveryWidthInput\nopen SemiprimeBitArithmetic (bitValue)\nnamespace WO\nexport SemiprimeD1StackRecoveryWidthOriginal (sizingCoefficient globalClockCoefficient original_envelope original_clock)\nend WO\n/-- Fixed coefficient pays both actual metadata copies and the real complete width source. -/\ndef clockCoefficient:Nat:=10*WO.sizingCoefficient+WO.globalClockCoefficient+20\n/-- SAME whole-source clock retains the actual root once and pays all added acquisition by a fixed polynomial. -/\ndef runBound (bits:List Bool):Nat:=\n  SemiprimeD1StackRootPacketPaddingBounds.runBound bits+clockCoefficient*(bits.length+1)^120\n/-- The two copied byte lengths equal the actual acquired unary metadata values. -/\ntheorem copy_time (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits):\n    widthCopyTime (rootDone bits hN).data=5*(O.originalA bits+O.originalM bits)+8:=by\n  unfold widthCopyTime\n  change 5*(((SemiprimeD1StackRootPacketPaddingEncoding.done bits hN).data O.exponentRole).length+\n    ((SemiprimeD1StackRootPacketPaddingEncoding.done bits hN).data O.edgesRole).length)+8=_\n  rw [SemiprimeD1StackRecoveryWidthOriginal.root_exponent bits hc hN,\n    SemiprimeD1StackRecoveryWidthOriginal.root_edges bits hN]\n  simp only [SemiprimeD1StackUnaryDivmod.unary,List.length_replicate]\n/-- Every actual original-input operation belongs to this SAME enclosing clock, with no native report transport. -/\ntheorem timeBound_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits):\n    timeBound bits hN ≤ runBound bits:=by\n  have hen:=WO.original_envelope bits hc hN\n  have hp:(bits.length+1)^10 ≤ (bits.length+1)^120:=Nat.pow_le_pow_right (by omega) (by decide:10 ≤ 120)\n  have ham:O.originalA bits+O.originalM bits ≤\n      SemiprimeD1StackRecoveryWidthEncoding.inputEnvelope (O.originalA bits) (O.originalM bits):=by\n    change O.originalA bits+O.originalM bits ≤ O.originalA bits+O.originalM bits+2^(O.originalA bits+1)+1\n    exact (Nat.le_add_right _ _).trans (Nat.le_add_right _ _)\n  have hmeta:O.originalA bits+O.originalM bits ≤ WO.sizingCoefficient*(bits.length+1)^120:=\n    (ham.trans hen).trans (Nat.mul_le_mul_left WO.sizingCoefficient hp)\n  have hw:=WO.original_clock bits hc hN\n  have hcopy:=copy_time bits hc hN\n  have hpos:1 ≤ (bits.length+1)^120:=Nat.one_le_pow _ _ (by omega)\n  unfold timeBound runBound clockCoefficient\n  rw [hcopy]\n  nlinarith only [hmeta,hw,hpos]\n/-- Actual genuine binary-input source halts with the whole root and width banks under its own bound. -/\ntheorem source_run_bounded (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits):\n    ∃q ≤ runBound bits,SemiprimeD1StackCalls.run program q (initial bits)=some (done bits hN):=by\n  obtain ⟨q,hq,hr⟩:=source_run bits hc hN\n  exact ⟨q,hq.trans (timeBound_le bits hc hN),hr⟩\nend RiemannGaussian.SemiprimeD1StackRootRecoveryWidthBounds\n","RiemannGaussian.SemiprimeD1StackRootRecoveryWidthCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootRecoveryWidthPrimitives\n/-! # Both real whole source calls, retaining the complete other bank -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootRecoveryWidthCalls\nopen SemiprimeD1StackRootRecoveryWidth SemiprimeD1StackProcedureTrace\nopen SemiprimeBitArithmetic (bitValue)\nlocal notation \"ctl\"=>Label.local\n/-- The actual binary-N source executes once with every actual width-source word retained. -/\ntheorem root_call (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (width:W.Stack→List Bool):\n    ∃q ≤ SemiprimeD1StackRootPacketPaddingBounds.runBound bits+1,Runs program q (ctl .start)\n      (data (R.initial bits).data width) (ctl (.copy .exponent))\n      (data (SemiprimeD1StackRootPacketPaddingEncoding.done bits hN).data width):=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackRootPacketPaddingBounds.source_run_bounded bits hc hN\n  refine ⟨q+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program rootStack Label.root Sum.inl_injective\n    R.program (.local .start) (fun _=>rfl) (ctl .start) (ctl (.copy .exponent)) rfl q\n    (R.initial bits) (SemiprimeD1StackRootPacketPaddingEncoding.done bits hN) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · exact (hk k rfl).elim\n      · rfl\n/-- Only the two physically copied acquired metadata words enter the real complete width source. -/\ntheorem width_call (a M:Nat) (root:R.Stack→List Bool):\n    ∃q ≤ SemiprimeD1StackRecoveryWidthBounds.polynomial a M+1,Runs program q (ctl .width)\n      (data root (W.initial (List.replicate a true) (List.replicate M true)).data) (ctl .done)\n      (data root (SemiprimeD1StackRecoveryWidthEncoding.done a M).data):=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackRecoveryWidthBounds.source_run_bounded a M\n  refine ⟨q+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program widthStack Label.width Sum.inr_injective\n    W.program .start (fun _=>rfl) (ctl .width) (ctl .done) rfl q\n    (W.initial (List.replicate a true) (List.replicate M true)) (SemiprimeD1StackRecoveryWidthEncoding.done a M)\n    _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · exact (hk k rfl).elim\nend RiemannGaussian.SemiprimeD1StackRootRecoveryWidthCalls\n","RiemannGaussian.SemiprimeD1StackRootScaleLeafDoubling":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootScaleLeafPrimitives\n/-! # Twenty paid physical doublings of the actually acquired input width -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option maxRecDepth 100000\nnamespace RiemannGaussian.SemiprimeD1StackRootScaleLeafDoubling\nopen SemiprimeD1StackRootScaleLeaf SemiprimeD1StackRootScaleLeafPrimitives\nopen SemiprimeD1StackProcedureTrace\n/-- Only the real scale and currently reused quotient/work word vary. -/\ndef data (base : Stack→List Bool) (n q : Nat) : Stack→List Bool :=\n  Function.update (Function.update base (aux .scale) (D.unary n)) (divStack .quotient) (D.unary q)\n/-- Fixed finite current-round label, never an input-length counter. -/\ndef phase (p : Fin 20) : Label :=.double ⟨p.val,by omega⟩\n/-- The current fixed round contains only actual pop/push instructions. -/\ntheorem phase_code (p : Fin 20) :\n    program (phase p)=.base (.pop (aux .scale) (.restore p) (.doublePush1 p) (.doublePush1 p)) :=by\n  simp [program,phase,p.isLt]\n/-- Each old metadata marker is physically popped and replaced by TWO work markers. -/\ntheorem consume (p : Fin 20) (base : Stack→List Bool) (n q : Nat) :\n    Runs program (3*n+1) (phase p) (data base n q) (.restore p) (data base 0 (q+2*n)) :=by\n  induction n generalizing q with\n  | zero=>\n    apply one_base program (phase p) (.restore p)\n      (.pop (aux .scale) (.restore p) (.doublePush1 p) (.doublePush1 p)) _ _ (phase_code p)\n    · rfl\n    · funext k;rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n  | succ n ih=>\n    have h0:Runs program 1 (phase p) (data base (n+1) q) (.doublePush1 p) (data base n q):=by\n      apply one_base program (phase p) (.doublePush1 p)\n        (.pop (aux .scale) (.restore p) (.doublePush1 p) (.doublePush1 p)) _ _ (phase_code p)\n      · rfl\n      · funext k;rcases k with k|k\n        · rfl\n        · rcases k with k|k\n          · cases k <;> rfl\n          · cases k <;> rfl\n    have h1:=push (.doublePush1 p) (.doublePush2 p) (divStack .quotient) (data base n q) rfl\n    have he1:Function.update (data base n q) (divStack .quotient) (true::data base n q (divStack .quotient))=\n        data base n (q+1):=by\n      funext k;rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n    rw [he1] at h1\n    have h2:=push (.doublePush2 p) (phase p) (divStack .quotient) (data base n (q+1)) rfl\n    have he2:Function.update (data base n (q+1)) (divStack .quotient)\n        (true::data base n (q+1) (divStack .quotient))=data base n (q+2):=by\n      funext k;rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · cases k <;> rfl\n        · cases k <;> rfl\n    rw [he2] at h2\n    have h:=join (join (join h0 h1) h2) (ih (q+2))\n    have ht:((1+1)+1)+(3*n+1)=3*(n+1)+1:=by omega\n    have hq:q+2+2*n=q+2*(n+1):=by omega\n    rw [ht,hq] at h\n    exact h\n/-- Both actual scan phases restore the doubled word and clear its work role. -/\ntheorem double_run (p : Fin 20) (base : Stack→List Bool) (n : Nat) :\n    Runs program (7*n+2) (phase p) (data base n 0)\n      (.double ⟨p.val+1,by omega⟩) (data base (2*n) 0) :=by\n  have h0:=consume p base n 0\n  simp only [Nat.zero_add] at h0\n  have h1:=SemiprimeD1StackPhysicalLoops.move_unary program (.restore p) (.restorePush p)\n    (.double ⟨p.val+1,by omega⟩) (divStack .quotient) (aux .scale) (by decide) rfl rfl base (2*n) []\n  have he0:Function.update (Function.update base (aux .scale) []) (divStack .quotient) (D.unary (2*n))=\n      data base 0 (2*n):=rfl\n  have he1:Function.update (Function.update base (aux .scale) (D.unary (2*n)++[]))\n      (divStack .quotient) []=data base (2*n) 0:=by rw [List.append_nil];rfl\n  dsimp only [D.unary] at he0 he1\n  rw [he0,he1] at h1\n  have h:=join h0 h1\n  have ht:(3*n+1)+(2*(2*n)+1)=7*n+2:=by omega\n  rw [ht] at h\n  exact h\n/-- Exact physically executed clock for a bounded number of fixed doubling phases. -/\ndef runTime (n rounds : Nat) : Nat :=7*n*(2^rounds-1)+2*rounds\n/-- Exact recurrence of the actual source clocks, including all EOF reads. -/\ntheorem runTime_step (n r : Nat) :runTime n (r+1)=(7*n+2)+runTime (2*n) r :=by\n  have hp:1≤2^r:=Nat.one_le_two_pow\n  have hs:2^r-1+1=2^r:=Nat.sub_add_cancel hp\n  have hp':1≤2^(r+1):=Nat.one_le_two_pow\n  have hs':2^(r+1)-1+1=2^(r+1):=Nat.sub_add_cancel hp'\n  unfold runTime\n  rw [pow_succ] at hs' ⊢\n  have he0:=congrArg (fun x:Nat=>14*n*x) hs\n  have he1:=congrArg (fun x:Nat=>7*n*x) hs'\n  nlinarith\n/-- Static bounded round index; no input counter is put in a program label. -/\ndef index (r : Nat) (_hr : r≤20) : Fin 21 :=⟨20-r,by omega⟩\n/-- The full twenty-round source scans and writes every acquired scale marker. -/\ntheorem rounds (base : Stack→List Bool) (r : Nat) (hr : r≤20) (n : Nat) :\n    Runs program (runTime n r) (.double (index r hr)) (data base n 0)\n      (.double 20) (data base (2^r*n) 0) :=by\n  induction r generalizing n with\n  | zero=>\n    have hi:index 0 hr=(20:Fin 21):=by apply Fin.ext;rfl\n    rw [hi]\n    simpa only [runTime,pow_zero,Nat.sub_self,Nat.mul_zero,Nat.zero_add,Nat.one_mul] using runs_refl program (.double 20) (data base n 0)\n  | succ r ih=>\n    let p:Fin 20:=⟨20-(r+1),by omega⟩\n    have hp:phase p=.double (index (r+1) hr):=by apply congrArg Label.double;apply Fin.ext;rfl\n    have hn:Label.double ⟨p.val+1,by omega⟩=.double (index r (by omega)):=by\n      apply congrArg Label.double\n      apply Fin.ext\n      dsimp [p,index]\n      omega\n    have h0:=double_run p base n\n    rw [hp,hn] at h0\n    have h1:=ih (by omega) (2*n)\n    have h:=join h0 h1\n    have ht:(7*n+2)+runTime (2*n) r=runTime n (r+1):=(runTime_step n r).symm\n    have hv:2^r*(2*n)=2^(r+1)*n:=by rw [pow_succ,Nat.mul_assoc]\n    rw [ht,hv] at h\n    exact h\n/-- Fully paid linear original-width envelope for the fixed twenty rounds. -/\ntheorem twenty_time (n : Nat) :runTime n 20≤8000000*(n+1) :=by norm_num [runTime];omega\nend RiemannGaussian.SemiprimeD1StackRootScaleLeafDoubling\n","RiemannGaussian.SemiprimeD1StackRootSelectionAcquireMonomial":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootSelectionAcquireBounds\n/-! # Fixed original-input rate for the same whole selected-key source\nThe real row producer has one scope exponential. A fixed polynomial of its\nactual resource bound raises only the fixed coefficient in that exponent.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootSelectionAcquireMonomial\nopen SemiprimeD1StackRootSelectionAcquireBounds SemiprimeD1StackRootSelectionAcquireInputBounds\nnamespace R\nexport SemiprimeD1StackRootNetworkRowsBounds\n  (runBound runBoundPrefix prefixPolynomial polynomial_monomial)\nend R\nnamespace Arity\nexport SemiprimeD1StackAllDescriptorRecordRootBounds (arityCapacity)\nend Arity\n/-- Fixed polynomial witnesses precede every input for the whole actual producer envelope. -/\ntheorem envelope_monomial :∃coef degree:Nat,∀bits:List Bool,\n    envelope bits ≤coef*(bits.length+1)^degree*2^(57*Arity.arityCapacity bits) :=by\n  obtain ⟨coef,degree,hpoly⟩:=R.polynomial_monomial\n  refine ⟨1+coef+10^51,degree+11,?_⟩\n  intro bits\n  let H:Nat:=(bits.length+1)^(degree+11)\n  let E:Nat:=2^(57*Arity.arityCapacity bits)\n  have hpos:1 ≤bits.length+1:=by omega\n  have he:1 ≤E:=Nat.pow_pos (by decide)\n  have hself:bits.length+1 ≤H:=by\n    simpa only [pow_one] using Nat.pow_le_pow_right hpos (by omega:1 ≤degree+11)\n  have hd:(bits.length+1)^degree ≤H:=Nat.pow_le_pow_right hpos (by omega)\n  have h10:(bits.length+1)^10 ≤H:=Nat.pow_le_pow_right hpos (by omega)\n  have hr0:R.runBound bits ≤coef*(bits.length+1)^degree*E:=by\n    unfold R.runBound R.runBoundPrefix\n    exact Nat.mul_le_mul_right E (hpoly bits.length)\n  have hr:R.runBound bits ≤coef*H*E:=\n    hr0.trans (Nat.mul_le_mul_right E (Nat.mul_le_mul_left coef hd))\n  have hp:parameterBound bits ≤10^51*H:=Nat.mul_le_mul_left (10^51) h10\n  have hlin:bits.length+parameterBound bits+1 ≤(1+10^51)*H:=by\n    nlinarith only [hself,hp]\n  have hpay:bits.length+parameterBound bits+1 ≤(bits.length+parameterBound bits+1)*E:=by\n    simpa only [Nat.mul_one] using Nat.mul_le_mul_left (bits.length+parameterBound bits+1) he\n  have hlinE:=hpay.trans (Nat.mul_le_mul_right E hlin)\n  change envelope bits ≤(1+coef+10^51)*H*E\n  unfold envelope\n  nlinarith only [hr,hlinE]\n/-- The SAME original-input whole-source bound has fixed coefficients and a fixed scope exponent. -/\ntheorem runBound_monomial :∃coef degree:Nat,∀bits:List Bool,\n    SemiprimeD1StackRootSelectionAcquireBounds.runBound bits ≤\n      coef*(bits.length+1)^degree*2^(5700*Arity.arityCapacity bits) :=by\n  obtain ⟨coef,degree,hbound⟩:=envelope_monomial\n  refine ⟨clockCoefficient*coef^100,degree*100,?_⟩\n  intro bits\n  have h:=Nat.mul_le_mul_left clockCoefficient (Nat.pow_le_pow_left (hbound bits) 100)\n  unfold SemiprimeD1StackRootSelectionAcquireBounds.runBound\n  calc\n    _ ≤clockCoefficient*(coef*(bits.length+1)^degree*2^(57*Arity.arityCapacity bits))^100:=h\n    _=(clockCoefficient*coef^100)*(bits.length+1)^(degree*100)*2^(5700*Arity.arityCapacity bits):=by\n      simp only [mul_pow,←pow_mul]\n      rw [show 57*Arity.arityCapacity bits*100=5700*Arity.arityCapacity bits by omega]\n      ring\nend RiemannGaussian.SemiprimeD1StackRootSelectionAcquireMonomial\n","RiemannGaussian.SemiprimeD1StackRootSelectionAcquireStorage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootSelectionAcquireBounds\n/-! # Genuine binary-input initialization and every2114-tape/return prefix\nBoth complete original-input producers and the complete acquired selection\nbank remain allocated. No cache, shadow or actual return cell is omitted.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootSelectionAcquireStorage\nopen SemiprimeD1StackRootSelectionAcquire SemiprimeD1StackRootSelectionAcquireEncoding\nopen SemiprimeD1StackRootSelectionAcquireExecution SemiprimeD1StackRootSelectionAcquireBounds\nopen SemiprimeD1StackCalls (run configuration)\nopen SemiprimeBitArithmetic (bitValue)\nlocal notation \"ctl\" => Label.local\n/-- Exactly one original binary input word is nonempty before any actual acquisition. -/\ntheorem input_single (bits:List Bool) :input bits=fun k=>if k=originalInput then bits else [] :=by\n  funext k\n  rcases k with k|k\n  · have h:=congrFun (SemiprimeD1StackRootNetworkRowsResources.input_single bits) k\n    simpa only [input,data,originalInput,rootStack,Sum.elim_inl,Sum.inl.injEq] using h\n  · rcases k with k|k <;> rfl\n/-- Every actual initialized word is paid by the sole binary-N input length. -/\ntheorem initial_length (bits:List Bool) (k:Stack) :((initial bits).data k).length ≤bits.length :=by\n  change (input bits k).length ≤bits.length\n  rw [input_single]\n  change (if k=originalInput then bits else []).length ≤bits.length\n  split_ifs <;> simp\n/-- Actual machine input is genuine Turing.initList, with no rows/counts/dimension/cache advice. -/\ntheorem initial_eq (bits:List Bool) :Turing.initList machine bits=configuration (initial bits) :=by\n  have hs:SemiprimeD1StackCalls.initial originalInput (ctl (.copy .number)) bits=initial bits:=by\n    apply congrArg (fun d=>(⟨some (ctl (.copy .number)),none,none,d,[]⟩:C.State Stack Label))\n    exact (input_single bits).symm\n  exact (SemiprimeD1StackCalls.initial_correct originalInput output (ctl (.copy .number)) program bits).symm.trans\n    (congrArg configuration hs)\n/-- Every successful actual prefix stops no later than the SAME actual source halt. -/\ntheorem prefix_fuel (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fuel:Nat) (out:C.State Stack Label) (hr:run program fuel (initial bits)=some out) :fuel ≤runBound bits :=by\n  obtain ⟨t,ht,he⟩:=source_run_bounded bits hc hN\n  have hh:run program 1 (done bits hN)=none:=rfl\n  have hf:fuel ≤t:=by\n    by_contra hn\n    have h:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add,hh,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- Every actually allocated role, including all retained source banks and shadows, is counted. -/\ntheorem word_sum (words:Stack→List Bool) (cap:Nat) (h:∀k,(words k).length ≤cap) :\n    (∑k:Stack,(words k).length) ≤2114*cap :=by\n  calc\n    _ ≤∑_k:Stack,cap:=Finset.sum_le_sum (fun k _=>h k)\n    _=2114*cap:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n/-- Every actual original-input prefix pays all2114 Boolean words and its genuine return stack. -/\ntheorem prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fuel:Nat) (out:C.State Stack Label) (hr:run program fuel (initial bits)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤2115*(bits.length+runBound bits) :=by\n  have ht:=prefix_fuel bits hc hN fuel out hr\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel bits.length _ out (initial_length bits) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length ≤0+fuel at hf\n  have hs:=word_sum out.data (bits.length+fuel) hd\n  omega\n/-- The genuine compiled finite source starts from binary N alone and uses its OWN whole clock. -/\nnoncomputable def machineOriginal (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) :StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (configuration (done bits hN))) (runBound bits) :=by\n  rw [initial_eq]\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output (ctl (.copy .number)) program\n  have h:=source_run_bounded bits hc hN\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- The identical genuine compiled prefixes include all data words and the actual none-labelled return tape. -/\ntheorem machine_prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun c=>c.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤2115*(bits.length+runBound bits) :=by\n  rw [initial_eq] at hr\n  have he:=SemiprimeD1StackCalls.run_correct originalInput output (ctl (.copy .number)) program fuel (initial bits)\n  have hh:=he.trans hr\n  cases hout:run program fuel (initial bits) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits hc hN fuel out hout\n/-- Every instruction expands to at most four genuine fixed-machine statements. -/\ntheorem compile_depth (pc:Label) :SemiprimeD1StackBytecode.statementDepth (machine.m pc) ≤4:=\n  SemiprimeD1StackCalls.compile_depth (ctl (.copy .number)) (program pc)\nend RiemannGaussian.SemiprimeD1StackRootSelectionAcquireStorage\n","RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootSourceOccurrences\nimport RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesBounds\n/-! # Genuine N-only compact occurrence-key initialization and all1873-role resources\nBoth full source banks and the two unused index-input shadows are included.\nTime and prefix bounds are attached to the same actual finite caller program.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesResources\nopen SemiprimeD1StackRootSourceOccurrences\nopen SemiprimeD1StackCalls (run configuration)\nlocal notation \"main\" => (Sum.inl Control.start :Label)\n/-- Both allocated source-input shadows and every other private empty occurrence role are physically empty. -/\ntheorem private_empty (k:Q.Stack):privateView (fun _=>[]) k=[]:=by cases k <;> rfl\n/-- The actual standard source initializes exactly one original binary-N word. -/\ntheorem input_single (bits:List Bool):input bits=fun k=>if k=originalInput then bits else []:=by\n  funext k\n  rcases k with k|k\n  · have h:=congrFun (SemiprimeD1StackRootNetworkRowsResources.input_single bits) k\n    simpa only [input,data,Sum.elim_inl,originalInput,rootStack,Sum.inl.injEq] using h\n  · change privateView (fun _=>[]) k=[]\n    exact private_empty k\n/-- Every actually initialized N-only word is paid by the physical binary input length. -/\ntheorem initial_length (bits:List Bool) (k:Stack):((initial bits).data k).length ≤bits.length:=by\n  change (input bits k).length ≤bits.length\n  rw [input_single]\n  by_cases hk:k=originalInput <;> simp [hk]\n/-- The explicit caller-prefix front door initializes only its actual N and prescription bytes. -/\ntheorem initial_prefix_length (bits pre:List Bool) (k:Stack):\n    ((initialPrefix bits pre).data k).length ≤bits.length+pre.length:=by\n  rcases k with k|k\n  · exact SemiprimeD1StackRootNetworkRowsResources.initial_prefix_length bits pre k\n  · change (privateView (fun _=>[]) k).length ≤bits.length+pre.length\n    rw [private_empty,List.length_nil]\n    exact Nat.zero_le _\n/-- A concrete halt bounds every successful prefix of the same deterministic actual caller. -/\ntheorem prefix_time {start finish:C.State Stack Label} (B:Nat)\n    (he:∃time ≤B,run program time start=some finish) (hh:run program 1 finish=none)\n    (fuel:Nat) (out:C.State Stack Label) (hr:run program fuel start=some out):fuel ≤B:=by\n  obtain ⟨time,ht,he⟩:=he\n  have hf:fuel ≤time:=by\n    by_contra hn\n    have h:fuel=time+(1+(fuel-(time+1))):=by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add,hh,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- Genuine compiled standard initialization starts with N alone at the literal source entry. -/\ntheorem initial_eq (bits:List Bool):Turing.initList machine bits=configuration (initial bits):=by\n  have hi:initial bits=SemiprimeD1StackCalls.initial originalInput main bits:=by\n    unfold initial SemiprimeD1StackCalls.initial\n    rw [input_single]\n  rw [hi]\n  exact (SemiprimeD1StackCalls.initial_correct originalInput output main program bits).symm\nopen SemiprimeD1StackRootSourceOccurrencesBounds\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimePublicAcquiredExecution (wireCount)\nattribute [local irreducible] runBound runBoundPrefix prefixPolynomial\n/-- No successful N-only prefix passes the same source's actual final halt. -/\ntheorem prefix_fuel (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fuel:Nat) (out:C.State Stack Label) (hr:run program fuel (initial bits)=some out):fuel ≤runBound bits:=\n  prefix_time _ (source_run_bounded bits hc hN) rfl fuel out hr\n/-- The actual prescribed bytes and retained tail use the same successful source's own bounded clock. -/\ntheorem prefix_fuel_prefix (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hr:run program fuel (initialPrefix bits (RE.prescription bits fixed tail))=some out):\n    fuel ≤runBoundPrefix bits (RE.prescription bits fixed tail).length:=\n  prefix_time _ (source_run_prefix_bounded bits hc hN fixed tail) rfl fuel out hr\n/-- Every1873allocated role, both empty input shadows, and all actual return cells are charged at every prefix. -/\ntheorem prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fuel:Nat) (out:C.State Stack Label) (hr:run program fuel (initial bits)=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤1874*(bits.length+runBound bits):=by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel bits.length _ _ (initial_length bits) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ _ hr\n  change out.frames.length ≤0+fuel at hf\n  have hs:=SemiprimeD1StackRootNetworkRecordsResources.word_sum_le out.data (bits.length+fuel) hd\n  rw [stack_card] at hs\n  have ht:=prefix_fuel bits hc hN fuel out hr\n  omega\n/-- Caller-prefix bytes and both complete source banks remain included at every actual prefix. -/\ntheorem prefix_cells_prefix (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hr:run program fuel (initialPrefix bits (RE.prescription bits fixed tail))=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤\n      1874*(bits.length+(RE.prescription bits fixed tail).length+\n        runBoundPrefix bits (RE.prescription bits fixed tail).length):=by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel\n    (bits.length+(RE.prescription bits fixed tail).length) _ _\n    (initial_prefix_length bits (RE.prescription bits fixed tail)) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ _ hr\n  change out.frames.length ≤0+fuel at hf\n  have hs:=SemiprimeD1StackRootNetworkRecordsResources.word_sum_le out.data\n    (bits.length+(RE.prescription bits fixed tail).length+fuel) hd\n  rw [stack_card] at hs\n  have ht:=prefix_fuel_prefix bits hc hN fixed tail fuel out hr\n  omega\n/-- Genuine compiled certificate starts at true Turing.initList with binary N alone. -/\nnoncomputable def occurrencesInTime (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits):StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (configuration (X.done bits hN [] []))) (runBound bits):=by\n  rw [initial_eq]\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output main program\n  have h:=source_run_bounded bits hc hN\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Genuine caller-prefix certificate executes the same fixed program on the actual input/tail bytes. -/\nnoncomputable def occurrencesPrefixInTime (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool):\n    StateTransition.EvalsToInTime machine.step\n      (configuration (initialPrefix bits (RE.prescription bits fixed tail)))\n      (some (configuration (X.done bits hN fixed tail)))\n      (runBoundPrefix bits (RE.prescription bits fixed tail).length):=by\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output main program\n  have h:=source_run_prefix_bounded bits hc hN fixed tail\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- All compiled N-only prefixes count every actual data word and real fixed-alphabet return symbol. -/\ntheorem machine_prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg):\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤1874*(bits.length+runBound bits):=by\n  rw [initial_eq] at hr\n  have he:=SemiprimeD1StackCalls.run_correct originalInput output main program fuel (initial bits)\n  have hh:=he.trans hr\n  cases hout:run program fuel (initial bits) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits hc hN fuel out hout\n/-- Explicit-prefix compiled states retain the same complete source/shadow and real-return accounting. -/\ntheorem machine_prefix_cells_prefix (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel]\n      (some (configuration (initialPrefix bits (RE.prescription bits fixed tail))))=some cfg):\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      1874*(bits.length+(RE.prescription bits fixed tail).length+\n        runBoundPrefix bits (RE.prescription bits fixed tail).length):=by\n  have he:=SemiprimeD1StackCalls.run_correct originalInput output main program fuel\n    (initialPrefix bits (RE.prescription bits fixed tail))\n  have hh:=he.trans hr\n  cases hout:run program fuel (initialPrefix bits (RE.prescription bits fixed tail)) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells_prefix bits hc hN fixed tail fuel out hout\n/-- A fixed coefficient and degree precede every original N in the actual whole-source time statement. -/\ntheorem source_run_monomial:∃coef degree:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits),∃time ≤\n      coef*(bits.length+1)^degree*2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits),\n        run program time (initial bits)=some (X.done bits hN [] []):=by\n  obtain ⟨coef,degree,hp⟩:=polynomial_monomial\n  refine ⟨coef,degree,?_⟩\n  intro bits hc hN\n  obtain ⟨time,ht,hr⟩:=source_run_bounded bits hc hN\n  have hb:runBound bits ≤coef*(bits.length+1)^degree*\n      2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=by\n    unfold runBound runBoundPrefix\n    exact Nat.mul_le_mul_right _ (hp bits.length)\n  exact ⟨time,ht.trans hb,hr⟩\n/-- Actual prefix/tail bytes have fixed polynomial witnesses before N and every prescribed list. -/\ntheorem source_run_prefix_monomial:∃coef degree:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool),∃time ≤\n      coef*(bits.length+(RE.prescription bits fixed tail).length+1)^degree*\n        2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits),\n      run program time (initialPrefix bits (RE.prescription bits fixed tail))=some (X.done bits hN fixed tail):=by\n  obtain ⟨coef,degree,hp⟩:=prefix_polynomial_monomial\n  refine ⟨coef,degree,?_⟩\n  intro bits hc hN fixed tail\n  obtain ⟨time,ht,hr⟩:=source_run_prefix_bounded bits hc hN fixed tail\n  have hb:runBoundPrefix bits (RE.prescription bits fixed tail).length ≤\n      coef*(bits.length+(RE.prescription bits fixed tail).length+1)^degree*\n        2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=by\n    unfold runBoundPrefix\n    exact Nat.mul_le_mul_right _ (hp bits.length (RE.prescription bits fixed tail).length)\n  exact ⟨time,ht.trans hb,hr⟩\n/-- Each actual source step expands into at most four genuine fixed-machine statements. -/\ntheorem compile_depth (pc:Label):SemiprimeD1StackBytecode.statementDepth (machine.m pc) ≤4:=\n  SemiprimeD1StackCalls.compile_depth main (program pc)\n/-- The complete data/return cap inherits fixed polynomial witnesses without changing its actual exponent. -/\ntheorem cell_cap (n P poly coef degree E:Nat) (hp:poly ≤coef*(n+P+1)^degree) (he:1 ≤E):\n    1874*(n+P+poly*E) ≤1874*(1+coef)*(n+P+1)^(degree+1)*E:=by\n  let S:=n+P+1\n  have hs:1 ≤S:=by dsimp [S];omega\n  have hd:S^degree ≤S^(degree+1):=Nat.pow_le_pow_right hs (by omega)\n  have hself:S ≤S^(degree+1):=by\n    simpa only [pow_one] using Nat.pow_le_pow_right hs (by omega:1 ≤degree+1)\n  have hbase:n+P ≤S^(degree+1)*E:=by\n    have h0:n+P ≤S^(degree+1):=(by dsimp [S];omega:n+P ≤S).trans hself\n    exact h0.trans (by simpa only [Nat.mul_one] using Nat.mul_le_mul_left (S^(degree+1)) he)\n  have hpoly:poly*E ≤coef*S^(degree+1)*E:=\n    Nat.mul_le_mul_right E (hp.trans (Nat.mul_le_mul_left coef hd))\n  change _ ≤1874*(1+coef)*S^(degree+1)*E\n  calc\n    _ ≤1874*(S^(degree+1)*E+coef*S^(degree+1)*E):=Nat.mul_le_mul_left 1874 (Nat.add_le_add hbase hpoly)\n    _= _:=by ring\n/-- Fixed monomial witnesses bound all actual N-only data/return prefixes before original N. -/\ntheorem prefix_monomial:∃coef degree:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (_hN:0 < bitValue bits) (fuel:Nat) (out:C.State Stack Label),\n    run program fuel (initial bits)=some out→\n      (∑k:Stack,(out.data k).length)+out.frames.length ≤coef*(bits.length+1)^degree*\n        2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=by\n  obtain ⟨coef,degree,hp⟩:=polynomial_monomial\n  refine ⟨1874*(1+coef),degree+1,?_⟩\n  intro bits hc hN fuel out hr\n  have he:1 ≤2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=Nat.pow_pos (by decide)\n  have hcap:1874*(bits.length+runBound bits) ≤1874*(1+coef)*(bits.length+1)^(degree+1)*\n      2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=by\n    unfold runBound runBoundPrefix\n    simpa only [Nat.add_zero] using cell_cap bits.length 0 (prefixPolynomial bits.length 1) coef degree\n      (2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits))\n      (by simpa only [Nat.add_zero] using hp bits.length) he\n  exact (prefix_cells bits hc hN fuel out hr).trans hcap\n/-- Every actual caller-prefix byte and both complete banks obey fixed monomial prefix witnesses. -/\ntheorem prefix_monomial_prefix:∃coef degree:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (_hN:0 < bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool) (fuel:Nat) (out:C.State Stack Label),\n    run program fuel (initialPrefix bits (RE.prescription bits fixed tail))=some out→\n      (∑k:Stack,(out.data k).length)+out.frames.length ≤\n        coef*(bits.length+(RE.prescription bits fixed tail).length+1)^degree*\n          2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=by\n  obtain ⟨coef,degree,hp⟩:=prefix_polynomial_monomial\n  refine ⟨1874*(1+coef),degree+1,?_⟩\n  intro bits hc hN fixed tail fuel out hr\n  have he:1 ≤2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=Nat.pow_pos (by decide)\n  have hcap:1874*(bits.length+(RE.prescription bits fixed tail).length+\n      runBoundPrefix bits (RE.prescription bits fixed tail).length) ≤\n      1874*(1+coef)*(bits.length+(RE.prescription bits fixed tail).length+1)^(degree+1)*\n        2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=by\n    unfold runBoundPrefix\n    exact cell_cap bits.length (RE.prescription bits fixed tail).length\n      (prefixPolynomial bits.length (RE.prescription bits fixed tail).length) coef degree\n      (2^(114*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits))\n      (hp bits.length (RE.prescription bits fixed tail).length) he\n  exact (prefix_cells_prefix bits hc hN fixed tail fuel out hr).trans hcap\nend RiemannGaussian.SemiprimeD1StackRootSourceOccurrencesResources\n","RiemannGaussian.SemiprimeD1StackScaleDescriptorRecordBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackScaleDescriptorRecord\n/-! # Complete actual scale metadata source bound and all362-role prefixes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1800000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackScaleDescriptorRecordBounds\nopen SemiprimeD1StackScaleDescriptorRecord\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- The entire actual source trace with its closed concrete original-checker clock. -/\ntheorem source_run_bounded (oldTemplate : Checker→List Bool) (raw : Fin 6→List Bool) (code : Fin 3)\n    (htag : raw 1=[true,true]) (htr : raw 2=List.replicate code.val true)\n    (hj : raw 3=SemiprimeD1StackUnaryDivmod.unary (raw 3).length)\n    (hk : raw 4=SemiprimeD1StackUnaryDivmod.unary (raw 4).length)\n    (hc : SemiprimeSourceCompactBits.Compact (raw 0)) (hN : 0<SemiprimeBitArithmetic.bitValue (raw 0))\n    (words : List (List Bool)) (M : Nat) (oldStage oldInverse hist out : List Bool)\n    (hl : ∀w∈words,w.length≤M) (hv : ∀w∈words,SemiprimeBitArithmetic.bitValue w≤M) :\n    ∃t≤runBound oldTemplate raw (code.val==2) words M oldStage oldInverse hist out,\n      SemiprimeD1StackCalls.run program t (initial oldTemplate raw oldStage oldInverse (vectorBits words) hist out)=\n        some (done raw (code.val==2) words hist out) :=by\n  obtain ⟨t,ht,hr⟩:=source_run oldTemplate raw code htag htr hj hk hc hN words oldStage oldInverse hist out\n  exact ⟨t,ht.trans (timeBound_le oldTemplate raw (code.val==2) words M oldStage oldInverse hist out hl hv),hr⟩\n/-- Every physical input is charged, including dirty template/selectors and all raw fields. -/\ndef inputSize (oldTemplate : Checker→List Bool) (raw : Fin 6→List Bool) (oldStage oldInverse bank hist out : List Bool) : Nat :=\n  SemiprimeD1StackSelectedDescriptorRecordBounds.inputSize I.static oldTemplate raw oldStage oldInverse bank hist out\n/-- All362 actual data roles, five dormant shadows, source fields and every\nactual nested return cell, before/inside/after selector computation and record acquisition. -/\ntheorem prefix_cells (oldTemplate : Checker→List Bool) (raw : Fin 6→List Bool) (code : Fin 3)\n    (htag : raw 1=[true,true]) (htr : raw 2=List.replicate code.val true)\n    (hj : raw 3=SemiprimeD1StackUnaryDivmod.unary (raw 3).length)\n    (hk : raw 4=SemiprimeD1StackUnaryDivmod.unary (raw 4).length)\n    (hc : SemiprimeSourceCompactBits.Compact (raw 0)) (hN : 0<SemiprimeBitArithmetic.bitValue (raw 0))\n    (words : List (List Bool)) (oldStage oldInverse hist out : List Bool) (fuel : Nat)\n    (finish : SemiprimeD1StackCalls.State Stack Label)\n    (hr : SemiprimeD1StackCalls.run program fuel\n      (initial oldTemplate raw oldStage oldInverse (vectorBits words) hist out)=some finish) :\n    (∑k:Stack,(finish.data k).length)+finish.frames.length≤\n      363*(inputSize oldTemplate raw oldStage oldInverse (vectorBits words) hist out+\n        timeBound oldTemplate raw (code.val==2) words oldStage oldInverse hist out+1) :=by\n  have hraw:SemiprimeD1StackDescriptorRecord.selected sourceMap (G.fields raw [false] [code.val==2]) I.static.raw=[]:=by\n    rw [selected_template];rfl\n  have hc0:SemiprimeD1StackStaticTableSpec.CheckerTrace I.static\n      (SemiprimeD1StackDescriptorRecord.selected sourceMap (G.fields raw [false] [code.val==2]))\n      (T.answer (raw 0) (raw 3) (raw 4) (code.val==2)) (T.budget (raw 0) (raw 3) (raw 4)):=by\n    rw [selected_template];exact T.actual_trace (raw 0) (raw 3) (raw 4) (code.val==2) hj hk hc hN\n  have h:=SemiprimeD1StackSelectedDescriptorRecordBounds.prefix_cells I.static sourceMap oldTemplate raw\n    2 code false htag htr rfl hraw (T.answer (raw 0) (raw 3) (raw 4) (code.val==2))\n    (T.budget (raw 0) (raw 3) (raw 4)) hc0 words oldStage oldInverse hist out fuel finish hr\n  rw [SemiprimeD1StackPublicScale.stack_card] at h\n  exact h\n/-- Same complete prefix inventory on the genuine compiled finite-control machine. -/\ntheorem machine_prefix_cells (oldTemplate : Checker→List Bool) (raw : Fin 6→List Bool) (code : Fin 3)\n    (htag : raw 1=[true,true]) (htr : raw 2=List.replicate code.val true)\n    (hj : raw 3=SemiprimeD1StackUnaryDivmod.unary (raw 3).length)\n    (hk : raw 4=SemiprimeD1StackUnaryDivmod.unary (raw 4).length)\n    (hc : SemiprimeSourceCompactBits.Compact (raw 0)) (hN : 0<SemiprimeBitArithmetic.bitValue (raw 0))\n    (words : List (List Bool)) (oldStage oldInverse hist out : List Bool) (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial oldTemplate raw oldStage oldInverse (vectorBits words) hist out)))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      363*(inputSize oldTemplate raw oldStage oldInverse (vectorBits words) hist out+\n        timeBound oldTemplate raw (code.val==2) words oldStage oldInverse hist out+1) :=by\n  have hraw:SemiprimeD1StackDescriptorRecord.selected sourceMap (G.fields raw [false] [code.val==2]) I.static.raw=[]:=by\n    rw [selected_template];rfl\n  have hc0:SemiprimeD1StackStaticTableSpec.CheckerTrace I.static\n      (SemiprimeD1StackDescriptorRecord.selected sourceMap (G.fields raw [false] [code.val==2]))\n      (T.answer (raw 0) (raw 3) (raw 4) (code.val==2)) (T.budget (raw 0) (raw 3) (raw 4)):=by\n    rw [selected_template];exact T.actual_trace (raw 0) (raw 3) (raw 4) (code.val==2) hj hk hc hN\n  have h:=SemiprimeD1StackSelectedDescriptorRecordBounds.machine_prefix_cells I.static sourceMap oldTemplate raw\n    2 code false htag htr rfl hraw (T.answer (raw 0) (raw 3) (raw 4) (code.val==2))\n    (T.budget (raw 0) (raw 3) (raw 4)) hc0 words oldStage oldInverse hist out fuel cfg hr\n  rw [SemiprimeD1StackPublicScale.stack_card] at h\n  exact h\nend RiemannGaussian.SemiprimeD1StackScaleDescriptorRecordBounds\n","RiemannGaussian.SemiprimeD1StackScopeLeafExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackScopeLeaf\n/-! # Closed actual scope-counted leaf trace, no cardinality header -/\nset_option autoImplicit false\nset_option synthInstance.maxSize 131072\nset_option maxRecDepth 131072\nset_option maxHeartbeats 3000000\nnamespace RiemannGaussian.SemiprimeD1StackScopeLeafExecution\nopen SemiprimeD1StackScopeLeaf\nnamespace PS\nexport SemiprimeD1StackVertexProductState (Values data address)\nend PS\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\nnamespace LS\nexport SemiprimeD1StackLeafState (data data_get data_product_update data_update)\nend LS\n\n/-- The original header tuple with context caches actually acquired by the first call. -/\ndef ready (ctx : SemiprimeD1JetAxes.Context) (pBits : List Bool)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) : PS.Values :=\n  Function.update (Function.update (SemiprimeD1StackLeafExecution.originalProductValues ctx pBits vertices)\n    .rank (unary ctx.rank)) .width (SemiprimeD1StackUnaryCounterExecution.markers ctx.precision)\n/-- Exact final store, preserving every original scope record and every leaf input. -/\ndef finalData (ctx : SemiprimeD1JetAxes.Context) (pBits : List Bool)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) (scopeWords : List (List Bool)) : Stack→List Bool :=\n  data (SemiprimeD1StackLeafExecution.finalData scopeWords.length ctx pBits [] vertices) (vectorBits scopeWords)\n/-- Closed actual stage budget: context, complete scope scan and the actual unary-ready leaf. -/\ndef budget (ctx : SemiprimeD1JetAxes.Context) (pBits : List Bool)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) (scopeWords : List (List Bool)) : ℕ :=\n  (1000*(SemiprimeD1StackJetContextBounds.resource ctx.axes pBits+1)^2+1)+\n    (11*(vectorBits scopeWords).length+6)+\n    (SemiprimeD1StackScopeLeafReady.budget scopeWords.length ctx vertices (ready ctx pBits vertices)+1)+1\n\n/-- Real original-header scope-counted execution. The only assignment width is\nacquired by physically scanning ALL scope records, including unused variables. -/\ntheorem source_run (ctx : SemiprimeD1JetAxes.Context) (hp : ctx.Positive) (pBits : List Bool)\n    (hprecision : SemiprimeBitArithmetic.bitValue pBits=ctx.precision)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) (scopeWords : List (List Bool)) :\n    ∃ m ≤ budget ctx pBits vertices scopeWords,\n      SemiprimeD1StackCalls.run program m\n        (initial (vectorBits (ctx.axes.map unary)) pBits\n          (SemiprimeD1StackVertexProduct.records vertices) (vectorBits scopeWords))=\n      some (⟨none,none,none,finalData ctx pBits vertices scopeWords,[]⟩:\n        SemiprimeD1StackCalls.State Stack Label) := by\n  let p:=SemiprimeD1StackLeafExecution.originalProductValues ctx pBits vertices\n  let v:=SemiprimeD1StackLeafExecution.originalValues []\n  let p1:=ready ctx pBits vertices\n  let inputLeaf:=LS.data p v\n  let readyLeaf:=LS.data p1 v\n  let countedLeaf:=LS.data p1 (Function.update v .counter (List.replicate scopeWords.length true))\n  let outputLeaf:=SemiprimeD1StackLeafExecution.finalData scopeWords.length ctx pBits [] vertices\n  obtain ⟨mc,hmc,hcontext⟩:=SemiprimeD1StackJetContextBounds.source_run_polynomial ctx.axes hp pBits\n  have h1 : Runs program (mc+1) .start (data inputLeaf (vectorBits scopeWords)) .countScopes\n      (data readyLeaf (vectorBits scopeWords)) := by\n    apply SemiprimeD1StackProcedureInclusion.included_call program contextStack Label.context contextStack_injective\n      X.program .start (fun _=>rfl) .start .countScopes rfl mc\n      (SemiprimeD1StackJetContext.initial (vectorBits (ctx.axes.map unary)) pBits)\n      (⟨none,none,none,SemiprimeD1StackJetContextCorrectness.finalData ctx.axes pBits,[]⟩:\n        SemiprimeD1StackCalls.State X.Stack X.Label)\n    · rfl\n    · rfl\n    · rfl\n    · rfl\n    · exact hcontext\n    · constructor\n      · intro k\n        change PS.data p (SemiprimeD1StackVertexProduct.contextStack k)=_\n        rw [SemiprimeD1StackVertexProductProjection.context_project]\n        fin_cases k <;> simp [p,SemiprimeD1StackLeafExecution.originalProductValues,\n          SemiprimeD1StackVertexProductState.values,SemiprimeD1StackJetContext.initial,\n          SemiprimeD1StackJetContext.bank,SemiprimeD1StackJetContext.cached,\n          SemiprimeD1StackJetContext.axesCache,SemiprimeD1StackJetContext.rankCache,\n          SemiprimeD1StackJetContext.widthCache,SemiprimeD1StackJetContext.precisionBits]\n      · intro k hk; rfl\n    · constructor\n      · intro k\n        change PS.data p1 (SemiprimeD1StackVertexProduct.contextStack k)=_\n        rw [SemiprimeD1StackVertexProductProjection.context_project]\n        fin_cases k <;> simp [p1,ready,SemiprimeD1StackLeafExecution.originalProductValues,\n          SemiprimeD1StackVertexProductState.values,SemiprimeD1StackJetContextCorrectness.finalData,\n          SemiprimeD1StackJetContext.bank,SemiprimeD1StackJetContext.cached,\n          SemiprimeD1StackJetContextExecution.ready,SemiprimeD1StackJetSuffix.data,SemiprimeD1StackAdder.store,\n          SemiprimeD1StackJetContext.axesCache,SemiprimeD1StackJetContext.rankCache,\n          SemiprimeD1StackJetContext.widthCache,SemiprimeD1StackJetContext.precisionBits,hprecision,\n          SemiprimeD1JetAxes.Context.rank]\n      · intro k hk\n        cases k with\n        | inr k => cases k <;> rfl\n        | inl k =>\n          have hr : k ≠ SemiprimeD1StackLeaf.productStack (PS.address .rank) :=\n            fun he=>hk SemiprimeD1StackJetContext.rankCache (congrArg leafStack he.symm)\n          have hw : k ≠ SemiprimeD1StackLeaf.productStack (PS.address .width) :=\n            fun he=>hk SemiprimeD1StackJetContext.widthCache (congrArg leafStack he.symm)\n          change LS.data p1 v k=LS.data p v k\n          dsimp only [p1,ready]\n          rw [LS.data_product_update,LS.data_product_update]\n          simp only [Function.update_of_ne hr,Function.update_of_ne hw]\n          rfl\n  have h2 : Runs program (SemiprimeD1StackDigitCountExecution.totalTime scopeWords+1)\n      .countScopes (data readyLeaf (vectorBits scopeWords)) .callLeaf (data countedLeaf (vectorBits scopeWords)) := by\n    apply SemiprimeD1StackProcedureInclusion.included_call program countStack Label.count countStack_injective\n      D.program (.inl .main) (fun _=>rfl) .countScopes .callLeaf rfl _\n      (SemiprimeD1StackDigitCountExecution.initial (vectorBits scopeWords))\n      (SemiprimeD1StackDigitCountExecution.done scopeWords)\n    · rfl\n    · rfl\n    · rfl\n    · rfl\n    · exact SemiprimeD1StackDigitCountExecution.acquire_run scopeWords\n    · constructor\n      · intro k\n        cases k\n        · rfl\n        · rfl\n        · exact LS.data_get p1 v .counter\n        · rfl\n        · rfl\n        · rfl\n        · rfl\n      · intro k hk; rfl\n    · constructor\n      · intro k\n        cases k\n        · rfl\n        · rfl\n        · exact LS.data_get p1 (Function.update v .counter (List.replicate scopeWords.length true)) .counter\n        · rfl\n        · rfl\n        · rfl\n        · rfl\n      · intro k hk\n        cases k with\n        | inr k => cases k <;> rfl\n        | inl k =>\n          have hn : k ≠ SemiprimeD1StackLeafState.address .counter :=\n            fun he=>hk .count (congrArg leafStack he.symm)\n          change LS.data p1 (Function.update v .counter (List.replicate scopeWords.length true)) k=LS.data p1 v k\n          rw [LS.data_update]\n          exact Function.update_of_ne hn _ _\n  obtain ⟨ml,hml,hleaf⟩:=SemiprimeD1StackScopeLeafReady.ready_run scopeWords.length ctx hp vertices p1 v\n    (by simp [p1,ready,SemiprimeD1StackLeafExecution.originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [p1,ready,SemiprimeD1StackLeafExecution.originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [p1,ready,SemiprimeD1StackLeafExecution.originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [p1,ready,SemiprimeD1StackLeafExecution.originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [p1,ready,SemiprimeD1StackLeafExecution.originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [p1,ready,SemiprimeD1StackLeafExecution.originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [p1,ready,SemiprimeD1StackLeafExecution.originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [p1,ready,SemiprimeD1StackLeafExecution.originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [p1,ready,SemiprimeD1StackLeafExecution.originalProductValues,SemiprimeD1StackVertexProductState.values])\n    rfl rfl rfl rfl rfl rfl\n    (by simp [p1,ready,SemiprimeD1StackLeafExecution.originalProductValues,SemiprimeD1StackVertexProductState.values])\n    (by simp [p1,ready,SemiprimeD1StackUnaryCounterExecution.markers]) (by simp [p1,ready])\n  have h3 : Runs program (ml+1) .callLeaf (data countedLeaf (vectorBits scopeWords)) .done\n      (data outputLeaf (vectorBits scopeWords)) := by\n    apply SemiprimeD1StackProcedureInclusion.included_call program leafStack Label.leaf\n      (by intro a b h; exact Sum.inl.inj h) L.program .makeZero (fun _=>rfl) .callLeaf .done rfl ml\n      (⟨some .makeZero,none,none,countedLeaf,[]⟩:SemiprimeD1StackCalls.State L.Stack L.Label)\n      (⟨none,none,none,outputLeaf,[]⟩:SemiprimeD1StackCalls.State L.Stack L.Label)\n    · rfl\n    · rfl\n    · rfl\n    · rfl\n    · exact hleaf\n    · constructor\n      · intro k; rfl\n      · intro k hk; rfl\n    · constructor\n      · intro k; rfl\n      · intro k hk\n        cases k with\n        | inl k => exact (hk k rfl).elim\n        | inr k => cases k <;> rfl\n  have hh:=runs_trans program _ _ _ _ _ _ _ _ h1 h2\n  have hh:=runs_trans program _ _ _ _ _ _ _ _ hh h3\n  have hinit : (initial (vectorBits (ctx.axes.map unary)) pBits\n      (SemiprimeD1StackVertexProduct.records vertices) (vectorBits scopeWords)).data=\n      data inputLeaf (vectorBits scopeWords) := by\n    apply congrArg (fun ds=>data ds (vectorBits scopeWords))\n    exact SemiprimeD1StackLeafExecution.initial_data ctx pBits [] vertices\n  obtain ⟨finish,hfinish,hAt⟩:=hh [] (initial (vectorBits (ctx.axes.map unary)) pBits\n    (SemiprimeD1StackVertexProduct.records vertices) (vectorBits scopeWords)) ⟨rfl,hinit,rfl⟩\n  have hhalt:=SemiprimeD1StackProcedureTrace.halt_run program .done rfl _ [] finish hAt\n  refine ⟨(mc+1)+(SemiprimeD1StackDigitCountExecution.totalTime scopeWords+1)+(ml+1)+1,?_,?_⟩\n  · have hd:=SemiprimeD1StackDigitCountExecution.totalTime_le scopeWords\n    unfold budget\n    change _≤(1000*(SemiprimeD1StackJetContextBounds.resource ctx.axes pBits+1)^2+1)+\n      (11*(vectorBits scopeWords).length+6)+(SemiprimeD1StackScopeLeafReady.budget scopeWords.length ctx vertices p1+1)+1\n    omega\n  · rw [SemiprimeD1StackReturnLink.run_add,hfinish,Option.bind_some,hhalt]\n    rfl\n\nend RiemannGaussian.SemiprimeD1StackScopeLeafExecution\n","RiemannGaussian.SemiprimeD1StackSourceAlphabet64Encoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64\nimport RiemannGaussian.SemiprimeD1StackOwnerLookup\n/-! # Exact compact-ID, high-base64-digit-first colour and binary-power byte specification -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceAlphabet64Encoding\nopen SemiprimeD1StackSourceAlphabet64\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimeSourceHistogramKeyBits (frame)\nopen SemiprimeSourceCompactBits (Compact trim)\n/-- Literal compact normalization of an ACTUAL little-endian word; mathematical specification only. -/\ndef compact (bits:List Bool) :List Bool :=(trim bits).bits\n/-- Actual reducer.trim output on the reversed word is the identical compact encoding. -/\ntheorem trim_reverse (bits:List Bool) :\n    SemiprimeD1StackReduceExecution.trimReverse bits.reverse=compact bits :=by\n  apply SemiprimeSourceCompactWordIds.compact_value_injective _ _\n    (SemiprimeD1StackReduceExecution.trimReverse_compact _) (SemiprimeSourceCompactBits.trim_compact _)\n  rw [SemiprimeD1StackReduceExecution.trimReverse_value,List.reverse_reverse,SemiprimeSourceCompactBits.trim_value]\n/-- A word with six physical bits per coordinate, in old head-major coordinate order. -/\ndef colours :Nat→List Bool→List (List Bool)\n  | 0,_=>[]\n  | a+1,reverseBits=>compact ((reverseBits.take 6).reverse)::colours a (reverseBits.drop 6)\n/-- Complete original-order row colour fields; there are NO vector tags between its fields. -/\ndef fields (colours:List (List Bool)) :List Bool :=colours.foldr frame []\n/-- One physical fixed-width word's exact complete colour row. -/\ndef row (a:Nat) (word:List Bool) :List Bool :=fields (colours a word.reverse)\n/-- Original actual6a-bit false-first increment enumeration, specified without a runtime cardinality operand. -/\ndef words (a:Nat) :List (List Bool) :=\n  SemiprimeD1StackAssignmentOrder.assignments (2^(6*a)) (List.replicate (6*a) false)\n/-- One canonical candidate and its complete compact colour row, in original ascending candidate order. -/\ndef entries (a:Nat) :List (List Bool×List Bool) :=(words a).map (fun word=>(compact word,row a word))\n/-- Exact old generic physical dictionary grammar used by the real lookup consumer. -/\ndef catalogue (a:Nat) :List Bool :=SemiprimeD1StackOwnerLookup.records (entries a) []\n/-- Binary ONE shifted by actual physical zero pushes, never unary numeric power padding. -/\ndef power (zeros:Nat) :List Bool :=List.replicate zeros false++[true]\n/-- Abstract complete30-role result keeps the actual raw enumerator vector and retained source width. -/\ndef result (a:Nat) :Stack→List Bool :=Sum.elim\n  (SemiprimeD1StackAssignmentLoop.data [] [] [] [] (SemiprimeD1TensorTapeCodec.vectorBits (words a)))\n  (fun k=>match k with\n    | .source=>List.replicate a true | .square=>power (12*a) | .cube=>power (18*a)\n    | .fourth=>power (24*a) | .head=>power (6*(4*a-1)) | .output=>catalogue a | _=>[])\n/-- Actual stopped configuration has clear flags and no pending real return cells. -/\ndef done (a:Nat) :C.State Stack Label :=⟨none,none,none,result a,[]⟩\n/-- Each actual normalized ID retains its numeric value and has canonical bytes. -/\ntheorem compact_spec (bits:List Bool) :bitValue (compact bits)=bitValue bits ∧ Compact (compact bits) :=\n  ⟨SemiprimeSourceCompactBits.trim_value _,SemiprimeSourceCompactBits.trim_compact _⟩\n/-- Compact colours have at most their actual six input bits. -/\ntheorem colour_width (bits:List Bool) :(compact ((bits.take 6).reverse)).length ≤ 6 :=\n  (SemiprimeSourceCompactBits.trim_length _).trans (by rw [List.length_reverse];exact List.length_take_le _ _)\n/-- Coordinate extraction retains EXACTLY the prescribed original row length. -/\ntheorem colours_length (a:Nat) (bits:List Bool) :(colours a bits).length=a :=by\n  induction a generalizing bits with\n  | zero=>rfl\n  | succ a ih=>simp only [colours,List.length_cons,ih]\n/-- Every framed compact colour costs at most thirteen actual bytes. -/\ntheorem fields_length (cs:List (List Bool)) (h:∀c∈cs,c.length ≤ 6) :(fields cs).length ≤ 13*cs.length :=by\n  induction cs with\n  | nil=>rfl\n  | cons c cs ih=>\n    have hc:=h c List.mem_cons_self\n    have ht:=ih (fun x hx=>h x (List.mem_cons_of_mem _ hx))\n    change (frame c (fields cs)).length ≤ _\n    rw [SemiprimeSourceHistogramKeyBits.frame_length,List.length_cons]\n    omega\n/-- Original row colour payload width is derived from real block widths, not an output-size supplier. -/\ntheorem row_length (a:Nat) (word:List Bool) :(row a word).length ≤ 13*a :=by\n  have hw:∀a:Nat,∀bits:List Bool,∀c∈colours a bits,c.length ≤ 6:=by\n    intro a\n    induction a with\n    | zero=>intro bits c hc;cases hc\n    | succ a ih=>\n      intro bits c hc\n      rcases List.mem_cons.mp hc with rfl|hc\n      · exact colour_width bits\n      · exact ih _ c hc\n  exact (fields_length _ (hw a word.reverse)).trans (by rw [colours_length])\n/-- Acquired raw assignment list contains exactly64^a candidates. -/\ntheorem words_length (a:Nat) :(words a).length=64^a :=by\n  rw [words,SemiprimeD1StackAssignmentOrder.assignments_length]\n  calc\n    2^(6*a)=(2^6)^a:=by rw [pow_mul]\n    _=64^a:=by norm_num\n/-- Every emitted actual assignment has exactly6a physical bits. -/\ntheorem word_width (a:Nat) (w:List Bool) (hw:w∈words a) :w.length=6*a :=\n  (SemiprimeD1StackAssignmentOrder.assignments_width _ _ w hw).trans List.length_replicate\nend RiemannGaussian.SemiprimeD1StackSourceAlphabet64Encoding\n","RiemannGaussian.SemiprimeD1StackSourceAlphabet64Execution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64Source\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64Finish\n/-! # Whole actual unary-width alphabet source: enumeration, every physical row and real halt -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceAlphabet64Execution\nopen SemiprimeD1StackSourceAlphabet64 SemiprimeD1StackSourceAlphabet64Encoding\nopen SemiprimeD1StackSourceAlphabet64Source SemiprimeD1StackSourceAlphabet64Primitives\nopen SemiprimeD1StackSourceAlphabet64Rows SemiprimeD1StackSourceAlphabet64Loop\nopen SemiprimeD1StackSourceAlphabet64Finish SemiprimeD1StackProcedureTrace\n/-- Whole fixed-program clock pays real setup/enum, all raw input bytes, each actual\nrow normalization/frame/cleanup and the sole whole final log reversal/halt. -/\ndef runBound (a:Nat) :Nat :=\n  95*a+100*(6*a+1)*2^(6*a)+21+\n  5*(SemiprimeD1TensorTapeCodec.vectorBits (words a)).length+4+\n  (2000*(a+1)*(words a).length+1)+2*(stream a (words a)).length+4+1\n/-- The actual raw counter vector is copied ONCE; every acquired binary-power word remains literal. -/\ntheorem copy_stream (a:Nat) :\n    Runs program (5*(SemiprimeD1TensorTapeCodec.vectorBits (words a)).length+4) .copyStream (enumerated a) .header\n      (boundary (enumerated a) (SemiprimeD1TensorTapeCodec.vectorBits (words a)) []) :=by\n  have h:=copy_call .stream .copyStream .header rfl (enumerated a) rfl rfl\n  have he:Function.update (enumerated a) (copyStack .stream 1) (enumerated a (copyStack .stream 0))=\n      boundary (enumerated a) (SemiprimeD1TensorTapeCodec.vectorBits (words a)) []:=by\n    funext k\n    rcases k with k|k\n    · rfl\n    · cases k <;> rfl\n  rw [he] at h\n  exact h\n/-- Generic final framing/projection lemma avoids any evaluated original-width native word source. -/\ntheorem finished_result (a:Nat) :finished (enumerated a) a (words a)=result a :=by\n  unfold finished\n  rw [stream_records]\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- Whole SAME literal source, from actual unary markers only; every compact candidate\nand every actual colour field is acquired, framed and returned in original chronological order. -/\ntheorem source_trace (a:Nat) :\n    ∃q,q+1 ≤ runBound a ∧ Runs program q .start (input (List.replicate a true)) .done (result a) :=by\n  obtain ⟨e,he,h0⟩:=prefix_run a\n  have h1:=copy_stream a\n  obtain ⟨r,hr,h2⟩:=rows_run (enumerated a) a (words a) [] (word_width a) rfl rfl rfl rfl rfl rfl\n  rw [List.append_nil] at h2\n  have h3:=finish_run (enumerated a) a (words a) rfl\n  rw [finished_result] at h3\n  have hall:=compose (compose (compose h0 h1) h2) h3\n  exact ⟨_,by unfold runBound;omega,hall⟩\n/-- Actual complete halt with all scratch/flags/real frames clear and all actual binary power words retained. -/\ntheorem source_run (a:Nat) :\n    ∃q ≤ runBound a,SemiprimeD1StackCalls.run program q (initial (List.replicate a true))=some (done a) :=by\n  obtain ⟨q,hq,hr⟩:=source_trace a\n  obtain ⟨finish,hf,hAt⟩:=hr [] (initial (List.replicate a true)) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program .done rfl (result a) [] finish hAt\n  exact ⟨q+1,hq,by rw [SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some];exact hh⟩\n/-- Genuine fixed finite-machine source certificate uses THIS complete own clock,\nnot a transported old histogram/classified report or an external candidate body. -/\nnoncomputable def alphabetInTime (a:Nat) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial (List.replicate a true)))\n      (some (SemiprimeD1StackCalls.configuration (done a))) (runBound a) :=by\n  apply SemiprimeD1StackCalls.evalsCorrect (aux .source) (aux .output) .start program\n  let h:=source_run a\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackSourceAlphabet64Execution\n","RiemannGaussian.SemiprimeD1StackSourceIncidenceEdges":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceEdgeFinish\n/-! # Complete real one-edge classification for every physically acquired prefix -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceIncidenceEdges\nopen SemiprimeD1StackSourceIncidence SemiprimeD1StackSourceIncidencePrimitives\nopen SemiprimeD1StackSourceIncidenceView SemiprimeD1StackSourceIncidenceCalls\nopen SemiprimeD1StackSourceIncidenceLookup SemiprimeD1StackSourceIncidenceEdgeFinish\nopen SemiprimeD1StackProcedureTrace SemiprimeD1StackSourceIncidenceSpec\nopen SemiprimeBitArithmetic (bitValue)\n/-- Own upper clock for every literal classifier branch; IDs here are proof interpretations of actual reads. -/\ndef edgeClock (ids:List (List Bool)) (left right:List Bool) :Nat :=\n  200*(left.length+right.length+(readID ids left).length+(readID ids right).length+1)+\n    500*(left.length+right.length+2)*((Env.dictionary ids).length+1)\n/-- Actual complete classifier: key loop test, paid lookup(s), physical found flags, saved fixed IDs,\nreal numeric ID comparison, cleanup and two-byte status emission. No verdict/remaining list is supplied. -/\ntheorem edge_run (ids:List (List Bool)) (chosen pfx:List Bool) (words:Aux→List Bool) (kind:Edge)\n    (hc:words .copyScratch=[]) (hs:words .eqScratch=[]) :\n    ∃q≤edgeClock ids (endpoint words false kind) (endpoint words true kind),\n      Runs program q (.edgeStart kind) (view ids chosen pfx words [] [] [] [] [] []) .edgeReturn\n        (view ids chosen pfx words [] [] []\n          [possible (edge ids (endpoint words false kind) (endpoint words true kind)),\n            drop (edge ids (endpoint words false kind) (endpoint words true kind))] [] []) :=by\n  let left:=endpoint words false kind\n  let right:=endpoint words true kind\n  let leftID:=readID ids left\n  let rightID:=readID ids right\n  have hkeys:=keys_run ids chosen pfx words kind hc hs\n  change Runs program ((5*left.length+4)+(5*right.length+4)+\n    (SemiprimeD1StackWordEqualExecution.executionTime left right+1)) _ _ _\n    (view ids chosen pfx words [] [] [] [decide (bitValue left=bitValue right)] [] []) at hkeys\n  have hpop:=pop_run (.keysEqual kind) .abort (.copyQuery kind false) (.status .stable) (aux .eqOutput)\n    (view ids chosen pfx words [] [] [] [decide (bitValue left=bitValue right)] [] [])\n    [decide (bitValue left=bitValue right)] rfl rfl\n  change Runs program 1 _ _ _ (Function.update\n    (view ids chosen pfx words [] [] [] [decide (bitValue left=bitValue right)] [] []) (aux .eqOutput) []) at hpop\n  rw [update_comparison] at hpop\n  have hkeyTime:=SemiprimeD1StackWordEqualExecution.executionTime_le left right\n  by_cases hloop:bitValue left=bitValue right\n  · simp only [hloop,decide_true,SemiprimeD1StackBytecode.choose,List.head?_cons] at hkeys hpop\n    have h:=join (join hkeys hpop) (status_run ids chosen pfx words .stable)\n    have he:edge ids left right=.stable:=by simp only [edge,hloop,ite_true]\n    refine ⟨_,?_,by\n      change Runs program _ _ _ _ (view ids chosen pfx words [] [] []\n        [possible (edge ids left right),drop (edge ids left right)] [] [])\n      simpa only [he,possible,drop] using h⟩\n    unfold edgeClock\n    dsimp only [left,right] at hkeyTime\n    nlinarith only [hkeyTime]\n  · simp only [hloop,decide_false,SemiprimeD1StackBytecode.choose,List.head?_cons] at hkeys hpop\n    obtain ⟨t,ht,hfirst⟩:=lookup_stage ids chosen pfx words kind false [] [] hc\n    by_cases hl:bitValue left < ids.length\n    · change Runs program t _ _ _ (view ids chosen pfx words left [] [] [] [decide (bitValue left < ids.length)]\n        (if bitValue left < ids.length then leftID else [])) at hfirst\n      simp only [hl,decide_true,ite_true] at hfirst\n      have hf:=found_pop ids chosen pfx words kind false true left [] [] leftID\n      have hs0:=save_first ids chosen pfx words kind left [] leftID hc\n      have hc0:=cleanup ids chosen pfx words kind false true left leftID [] leftID\n      have hj0:=jump_run (.afterLookup kind false true) (.copyQuery kind true)\n        (view ids chosen pfx words [] leftID [] [] [] []) rfl\n      have hprefix:=join (join (join (join (join (join hkeys hpop) hfirst) hf) hs0) hc0) hj0\n      obtain ⟨u,hu,hsecond⟩:=lookup_stage ids chosen pfx words kind true leftID [] hc\n      by_cases hr:bitValue right < ids.length\n      · change Runs program u _ _ _ (view ids chosen pfx words right leftID [] [] [decide (bitValue right < ids.length)]\n          (if bitValue right < ids.length then rightID else [])) at hsecond\n        simp only [hr,decide_true,ite_true] at hsecond\n        have hf1:=found_pop ids chosen pfx words kind true true right leftID [] rightID\n        have hs1:=save_second ids chosen pfx words kind right leftID rightID hc\n        have hc1:=cleanup ids chosen pfx words kind true true right leftID rightID rightID\n        have hfinish:=second_present ids chosen pfx words kind leftID rightID hs\n        have h:=join (join (join (join (join hprefix hsecond) hf1) hs1) hc1) hfinish\n        have hn:¬(ids.length ≤ bitValue left ∨ ids.length ≤ bitValue right):=by omega\n        have he:edge ids left right=if bitValue leftID=bitValue rightID then .stable else .reject:=by\n          simp only [edge,hloop,ite_false,hn,leftID,rightID]\n        refine ⟨_,?_,by\n          change Runs program _ _ _ _ (view ids chosen pfx words [] [] [] [possible (edge ids left right),drop (edge ids left right)] [] [])\n          rw [he]\n          by_cases hi:bitValue leftID=bitValue rightID\n          · simpa only [hi,ite_true,possible,drop] using h\n          · simpa only [hi,ite_false,possible,drop] using h⟩\n        unfold edgeClock\n        have hIDTime:=SemiprimeD1StackWordEqualExecution.executionTime_le leftID rightID\n        dsimp only [left,right,leftID,rightID] at ht hu hkeyTime hIDTime ⊢\n        nlinarith only [ht,hu,hkeyTime,hIDTime]\n      · change Runs program u _ _ _ (view ids chosen pfx words right leftID [] [] [decide (bitValue right < ids.length)]\n          (if bitValue right < ids.length then rightID else [])) at hsecond\n        simp only [hr,decide_false,ite_false] at hsecond\n        have hf1:=found_pop ids chosen pfx words kind true false right leftID [] []\n        have hc1:=cleanup ids chosen pfx words kind true false right leftID [] []\n        have hfinish:=second_missing ids chosen pfx words kind leftID\n        have h:=join (join (join (join hprefix hsecond) hf1) hc1) hfinish\n        have hfree:ids.length ≤ bitValue left ∨ ids.length ≤ bitValue right:=Or.inr (by omega)\n        have he:edge ids left right=.free:=by simp only [edge,hloop,ite_false,hfree,ite_true]\n        refine ⟨_,?_,by\n          change Runs program _ _ _ _ (view ids chosen pfx words [] [] []\n            [possible (edge ids left right),drop (edge ids left right)] [] [])\n          simpa only [he,possible,drop] using h⟩\n        unfold edgeClock\n        dsimp only [left,right,leftID,rightID] at ht hu hkeyTime ⊢\n        simp only [List.length_nil]\n        nlinarith only [ht,hu,hkeyTime]\n    · change Runs program t _ _ _ (view ids chosen pfx words left [] [] [] [decide (bitValue left < ids.length)]\n        (if bitValue left < ids.length then leftID else [])) at hfirst\n      simp only [hl,decide_false,ite_false] at hfirst\n      have hf:=found_pop ids chosen pfx words kind false false left [] [] []\n      have hc0:=cleanup ids chosen pfx words kind false false left [] [] []\n      have hfinish:=first_missing ids chosen pfx words kind\n      have h:=join (join (join (join (join hkeys hpop) hfirst) hf) hc0) hfinish\n      have hfree:ids.length ≤ bitValue left ∨ ids.length ≤ bitValue right:=Or.inl (by omega)\n      have he:edge ids left right=.free:=by simp only [edge,hloop,ite_false,hfree,ite_true]\n      refine ⟨_,?_,by\n        change Runs program _ _ _ _ (view ids chosen pfx words [] [] []\n          [possible (edge ids left right),drop (edge ids left right)] [] [])\n        simpa only [he,possible,drop] using h⟩\n      unfold edgeClock\n      dsimp only [left,right,leftID,rightID] at ht hkeyTime ⊢\n      simp only [List.length_nil]\n      nlinarith only [ht,hkeyTime]\nend RiemannGaussian.SemiprimeD1StackSourceIncidenceEdges\n","RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectPrimitives\n/-! # Actual environment initialization/extension and complete closed scorer calls\nEvery call instantiates a proved real source trace. All63 fields outside the\ncomponent image, and every genuine outer return frame, are preserved.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCalls\nopen SemiprimeD1StackSourceIncidenceSelect SemiprimeD1StackSourceIncidenceSelectPrimitives\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- Replace exactly the25 actual shared environment roles, preserving every other38 words. -/\ndef withEnvironment (before:Stack→List Bool) (env:E.Stack→List Bool) :Stack→List Bool :=\n  Sum.elim (Sum.elim env (fun k=>before (queryStack (Q.aux k)))) (fun k=>before (aux k))\n/-- Exact inclusion relation outside the25-role shared environment image. -/\ntheorem withEnvironment_rel (before:Stack→List Bool) (env:E.Stack→List Bool) :\n    Link.DataRel environmentStack before env (withEnvironment before env) :=by\n  constructor\n  · intro k;rfl\n  · intro k hk\n    rcases k with k|k\n    · rcases k with k|k\n      · exact (hk k rfl).elim\n      · rfl\n    · rfl\n/-- A physically empty environment is initialized by the real push/return source and its actual outer call. -/\ntheorem initialize_call (before:Stack→List Bool) (chosen q pfx:List Bool)\n    (hi:∀k,before (environmentStack k)=\n      (SemiprimeD1StackSourceEnvironmentExecution.initializeReady chosen q pfx).data k) :\n    Runs program 3 (ctl .initialize) before (ctl .copyOwners)\n      (withEnvironment before (SemiprimeD1StackSourceEnvironmentExecution.initializeDone chosen q pfx).data) :=by\n  apply environment_call .initialize .copyOwners (.local .initialize) rfl 2\n    (SemiprimeD1StackSourceEnvironmentExecution.initializeReady chosen q pfx)\n    (SemiprimeD1StackSourceEnvironmentExecution.initializeDone chosen q pfx) before _ rfl rfl rfl rfl\n    (SemiprimeD1StackSourceEnvironmentExecution.initialize_run chosen q pfx)\n  · exact ⟨hi,fun _ _=>rfl⟩\n  · exact withEnvironment_rel before _\n/-- Temporary and committed candidates use the SAME literal acquired-key extension, retaining arbitrary selected-vector bytes. -/\ntheorem extend_call (pc next:Control)\n    (hc:program (ctl pc)=.call (environmentLabel (.local .extend)) (ctl next))\n    (before:Stack→List Bool) (ids:List (List Bool)) (chosen q pfx:List Bool)\n    (hi:∀k,before (environmentStack k)=\n      (SemiprimeD1StackSourceEnvironmentExecution.extendReady ids chosen q pfx).data k) :\n    ∃t ≤ 101*(chosen.length+(SemiprimeD1StackSourceEnvironmentEncoding.variableKey ids.length).length+1)+1,\n      Runs program t (ctl pc) before (ctl next)\n        (withEnvironment before (SemiprimeD1StackSourceEnvironmentExecution.extendDone ids chosen q pfx).data) :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackSourceEnvironmentExecution.extend_run ids chosen q pfx\n  refine ⟨t+1,by omega,?_⟩\n  apply environment_call pc next (.local .extend) hc t\n    (SemiprimeD1StackSourceEnvironmentExecution.extendReady ids chosen q pfx)\n    (SemiprimeD1StackSourceEnvironmentExecution.extendDone ids chosen q pfx) before _ rfl rfl rfl rfl hr\n  · exact ⟨hi,fun _ _=>rfl⟩\n  · exact withEnvironment_rel before _\n/-- The complete closed47-role scorer is really called after each temporary extension; all25 environment roles are restored. -/\ntheorem query_call (first:Bool) (before:Stack→List Bool)\n    (i:SemiprimeD1StackSourceIncidenceEncoding.Inputs)\n    (hi:∀k,before (queryStack k)=(SemiprimeD1StackSourceIncidenceEncoding.source i).data k) :\n    ∃t ≤ SemiprimeD1StackSourceIncidenceExecution.runBound i+1,\n      Runs program t (ctl (.evaluate first)) before (ctl (.acquired first))\n        (Sum.elim (SemiprimeD1StackSourceIncidenceEncoding.result i) (fun k=>before (aux k))) :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackSourceIncidenceExecution.source_run i\n  refine ⟨t+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program queryStack Label.queryCode Sum.inl_injective\n    Q.program .start (fun _=>rfl) (ctl (.evaluate first)) (ctl (.acquired first)) rfl t\n    (SemiprimeD1StackSourceIncidenceEncoding.source i) (SemiprimeD1StackSourceIncidenceEncoding.done i)\n    before _ rfl rfl rfl rfl hr\n  · exact ⟨hi,fun _ _=>rfl⟩\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · exact (hk k rfl).elim\n      · rfl\nend RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCalls\n","RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCommit":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCalls\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectView\n/-! # Actual committed winner extension and newest-first selected-vector framing\nThe physically retained winning ID is copied to the shared environment, really\nextended at the saved current key and framed onto the old selected vector. Every\ncandidate/snapshot/incumbent/score word is physically drained before iteration.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCommit\nopen SemiprimeD1StackSourceIncidenceSelect SemiprimeD1StackSourceIncidenceSelectPrimitives\nopen SemiprimeD1StackSourceIncidenceSelectView SemiprimeD1StackSourceIncidenceSelectCalls\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace E\nexport SemiprimeD1StackSourceEnvironmentEncoding (variableKey)\nend E\nlocal notation \"ctl\" => Label.local\n/-- Own complete commit cap, including the real environment return, real Frame and all byte drains. -/\ndef commitBound (ids:List (List Bool)) (id savedScore:List Bool) :Nat :=\n  200*(id.length+(E.variableKey ids.length).length+savedScore.length+1)\n/-- The same source physically commits the exact winner and advances only after every private word is clear. -/\ntheorem commit_run (ids:List (List Bool))\n    (id savedScore stream square cube fourth catalogue owners factors todo:List Bool) :\n    ∃t ≤ commitBound ids id savedScore,\n      Runs program t (ctl .copyWinner)\n        (clean ids [] (vectorBits ids) stream square cube fourth catalogue owners factors todo []\n          (E.variableKey ids.length) id savedScore [])\n        (ctl .loopVariable)\n        (clean (id::ids) [] (vectorBits (id::ids)) stream square cube fourth catalogue owners factors todo [] [] [] [] []) :=by\n  let pfx:=vectorBits ids\n  let key:=E.variableKey ids.length\n  have h0:=copy_call .winner .copyWinner .commit rfl\n    (clean ids [] pfx stream square cube fourth catalogue owners factors todo [] key id savedScore []) id [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update\n    (clean ids [] pfx stream square cube fourth catalogue owners factors todo [] key id savedScore []) candidate (id++[])) at h0\n  rw [List.append_nil,clean_chosen] at h0\n  let before:=clean ids id pfx stream square cube fourth catalogue owners factors todo [] key id savedScore []\n  obtain ⟨t1,ht1,h1⟩:=extend_call .commit .frameWinner rfl before ids id [] pfx (fun _=>rfl)\n  have he:withEnvironment before (SemiprimeD1StackSourceEnvironmentExecution.extendDone ids id [] pfx).data=\n      clean (id::ids) id pfx stream square cube fourth catalogue owners factors todo [] key id savedScore []:=by\n    funext k\n    rcases k with k|k\n    · rcases k with k|k\n      · rcases k with k|k\n        · rcases k with k|k <;> cases k <;> rfl\n        · cases k <;> rfl\n      · cases k <;> rfl\n    · cases k <;> rfl\n  rw [he] at h1\n  have h2:=frame_call .frameWinner .prefixTag rfl\n    (clean (id::ids) id pfx stream square cube fourth catalogue owners factors todo [] key id savedScore []) id pfx rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update\n    (clean (id::ids) id pfx stream square cube fourth catalogue owners factors todo [] key id savedScore []) selected (frame id pfx)) at h2\n  rw [clean_pfx] at h2\n  have h3:=push_run .prefixTag (ctl .clearCommittedChosen) selected true\n    (clean (id::ids) id (frame id pfx) stream square cube fourth catalogue owners factors todo [] key id savedScore []) rfl\n  change Runs program 1 _ _ _ (Function.update\n    (clean (id::ids) id (frame id pfx) stream square cube fourth catalogue owners factors todo [] key id savedScore []) selected\n    (true::frame id pfx)) at h3\n  rw [clean_pfx] at h3\n  have h4:=drain_loop .clearCommittedChosen (ctl .clearSavedKey) candidate rfl\n    (clean (id::ids) id (true::frame id pfx) stream square cube fourth catalogue owners factors todo [] key id savedScore []) id rfl\n  rw [clean_chosen] at h4\n  have h5:=drain_loop .clearSavedKey (ctl .clearWinnerID) (aux .savedKey) rfl\n    (clean (id::ids) [] (true::frame id pfx) stream square cube fourth catalogue owners factors todo [] key id savedScore []) key rfl\n  rw [clean_savedKey] at h5\n  have h6:=drain_loop .clearWinnerID (ctl .clearWinnerScore) (aux .bestID) rfl\n    (clean (id::ids) [] (true::frame id pfx) stream square cube fourth catalogue owners factors todo [] [] id savedScore []) id rfl\n  rw [clean_bestID] at h6\n  have h7:=drain_loop .clearWinnerScore (ctl .loopVariable) (aux .bestScore) rfl\n    (clean (id::ids) [] (true::frame id pfx) stream square cube fourth catalogue owners factors todo [] [] [] savedScore []) savedScore rfl\n  rw [clean_bestScore] at h7\n  have h:=join (join (join (join (join (join (join h0 h1) h2) h3) h4) h5) h6) h7\n  refine ⟨_,?_,h⟩\n  change t1 ≤ 101*(id.length+key.length+1)+1 at ht1\n  change _ ≤ 200*(id.length+key.length+savedScore.length+1)\n  omega\nend RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCommit\n","RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectIncumbent":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectView\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectCompare\n/-! # Actual first-score caching and strict incumbent replacement\nThe first candidate is saved by finite control even when its ID and score are\nboth zero. Every later replacement uses only the real comparator's strict bit;\nties preserve both original incumbent words. Every erased score is drained.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectIncumbent\nopen SemiprimeD1StackSourceIncidenceSelect SemiprimeD1StackSourceIncidenceSelectPrimitives\nopen SemiprimeD1StackSourceIncidenceSelectView SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- Real copies cache the exact candidate and its actual acquired score without recomputation. -/\ntheorem save_run (pc scorePC:Control)\n    (hc:program (ctl pc)=.call (.copier .bestID 0) (ctl scorePC))\n    (hs:program (ctl scorePC)=.call (.copier .bestScore 0) (ctl .clearScore))\n    (ids:List (List Bool))\n    (id pfx stream square cube fourth catalogue owners factors todo reader savedKey newScore:List Bool) :\n    Runs program (5*id.length+5*newScore.length+8) (ctl pc)\n      (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey [] [] newScore)\n      (ctl .clearScore)\n      (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey id newScore newScore) :=by\n  have h0:=copy_call .bestID pc scorePC hc\n    (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey [] [] newScore)\n    id [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update\n    (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey [] [] newScore)\n      (aux .bestID) (id++[])) at h0\n  rw [List.append_nil,clean_bestID] at h0\n  have h1:=copy_call .bestScore scorePC .clearScore hs\n    (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey id [] newScore)\n    newScore [] rfl rfl rfl\n  change Runs program _ _ _ _ (Function.update\n    (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey id [] newScore)\n      (aux .bestScore) (newScore++[])) at h1\n  rw [List.append_nil,clean_bestScore] at h1\n  have h:=join h0 h1\n  have ht:(5*id.length+4)+(5*newScore.length+4)=5*id.length+5*newScore.length+8:=by omega\n  simpa only [ht] using h\n/-- The just-acquired score word is physically drained before the temporary dictionary is rolled back. -/\ntheorem clear_score (ids:List (List Bool))\n    (id pfx stream square cube fourth catalogue owners factors todo reader savedKey bestID bestScore newScore:List Bool) :\n    Runs program (newScore.length+1) (ctl .clearScore)\n      (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey bestID bestScore newScore)\n      (ctl .rollbackTag)\n      (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey bestID bestScore []) :=by\n  have h:=drain_loop .clearScore (ctl .rollbackTag) score rfl\n    (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey bestID bestScore newScore)\n    newScore rfl\n  rw [clean_total] at h\n  exact h\n/-- First-candidate status is explicit finite control; zero words cannot be mistaken for uninitialized state. -/\ntheorem first_run (ids:List (List Bool))\n    (id pfx stream square cube fourth catalogue owners factors todo reader savedKey newScore:List Bool) :\n    Runs program (5*id.length+6*newScore.length+9) (ctl (.acquired true))\n      (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey [] [] newScore)\n      (ctl .rollbackTag)\n      (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey id newScore []) :=by\n  have h0:=save_run (.acquired true) .saveFirstScore rfl rfl ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey newScore\n  have h1:=clear_score ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey id newScore newScore\n  have h:=join h0 h1\n  have ht:(5*id.length+5*newScore.length+8)+(newScore.length+1)=5*id.length+6*newScore.length+9:=by omega\n  simpa only [ht] using h\n/-- A computed strict improvement pays both incumbent drains and both real replacement copies. -/\ntheorem better_run (ids:List (List Bool))\n    (id pfx stream square cube fourth catalogue owners factors todo reader savedKey oldID oldScore newScore:List Bool) :\n    Runs program (oldID.length+oldScore.length+5*id.length+6*newScore.length+11) (ctl .clearBestID)\n      (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey oldID oldScore newScore)\n      (ctl .rollbackTag)\n      (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey id newScore []) :=by\n  have h0:=drain_loop .clearBestID (ctl .clearBestScore) (aux .bestID) rfl\n    (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey oldID oldScore newScore) oldID rfl\n  rw [clean_bestID] at h0\n  have h1:=drain_loop .clearBestScore (ctl .saveBetterID) (aux .bestScore) rfl\n    (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey [] oldScore newScore) oldScore rfl\n  rw [clean_bestScore] at h1\n  have h2:=save_run .saveBetterID .saveBetterScore rfl rfl ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey newScore\n  have h3:=clear_score ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey id newScore newScore\n  have h:=join (join (join h0 h1) h2) h3\n  have ht:(oldID.length+1)+(oldScore.length+1)+(5*id.length+5*newScore.length+8)+(newScore.length+1)=\n      oldID.length+oldScore.length+5*id.length+6*newScore.length+11:=by omega\n  simpa only [ht] using h\n/-- Every later actual acquired score returns the exact strict-update pair, retaining the incumbent on all ties. -/\ntheorem later_run (ids:List (List Bool))\n    (id pfx stream square cube fourth catalogue owners factors todo reader savedKey oldID oldScore newScore:List Bool) :\n    ∃t ≤ 100*(id.length+newScore.length+oldID.length+oldScore.length+1),\n      Runs program t (ctl (.acquired false))\n        (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey oldID oldScore newScore)\n        (ctl .rollbackTag)\n        (clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey\n          (SemiprimeD1StackSourceIncidenceSelectSpec.scoredPick (oldID,oldScore) (id,newScore)).1\n          (SemiprimeD1StackSourceIncidenceSelectSpec.scoredPick (oldID,oldScore) (id,newScore)).2 []) :=by\n  let before:=clean ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey oldID oldScore newScore\n  have h0:=SemiprimeD1StackSourceIncidenceSelectCompare.compare_run before newScore oldScore rfl rfl rfl rfl rfl\n  rw [SemiprimeD1StackSourceIncidenceSelectCompare.view_empty before rfl rfl rfl] at h0\n  have ht:=SemiprimeD1StackSourceIncidenceSelectCompare.compare_time_le newScore oldScore\n  have hp:=SemiprimeD1StackSourceIncidenceSelectSpec.real_less_pick (oldID,oldScore) (id,newScore)\n  cases hb:SemiprimeD1StackWordLessExecution.answer newScore oldScore with\n  | false=>\n    have h1:=clear_score ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey oldID oldScore newScore\n    simp only [hb,Bool.false_eq_true,ite_false] at h0 hp\n    rw [←hp]\n    refine ⟨_,by omega,join h0 h1⟩\n  | true=>\n    have h1:=better_run ids id pfx stream square cube fourth catalogue owners factors todo reader savedKey oldID oldScore newScore\n    simp only [hb,ite_true] at h0 hp\n    rw [←hp]\n    refine ⟨_,by omega,join h0 h1⟩\nend RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectIncumbent\n","RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelect\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectEncoding\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceExecution\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n/-! # Real selector calls, parses, comparisons and complete physical cleanup\nAll clocks below arise from actual included source traces. The dictionary,\ncurrent key, candidate and result are physical words; none is a source supplier.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectPrimitives\nopen SemiprimeD1StackSourceIncidenceSelect SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\nlocal notation \"ctl\" => Label.local\n/-- Exact chronological source-fragment composition preserves every real outer return. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Actual complete preserving copy, including both restoration loops and its real caller return. -/\ntheorem copy_call (what:Copy) (pc next:Control)\n    (hc:program (ctl pc)=.call (.copier what 0) (ctl next)) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copyStack what 0)=xs) (hy:before (copyStack what 1)=ys) (hs:before (copyStack what 2)=[]) :\n    Runs program (5*xs.length+4) (ctl pc) before (ctl next)\n      (Function.update before (copyStack what 1) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack what) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack what) (copy_injective what) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack what) (Label.copier what) (copy_injective what) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (ctl pc) (ctl next) hc (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\n/-- Complete real field read pays all input/output bits and leaves its physical true-valid flag. -/\ntheorem field_call (part:Part) (pc next:Control)\n    (hc:program (ctl pc)=.call (.parser part (Field.active .tagPop (none,false))) (ctl next))\n    (before:Stack→List Bool) (word tail:List Bool)\n    (hi:before (fieldStack part (.inl .input))=frame word tail)\n    (ho:before (fieldStack part (.inl .output))=[])\n    (hs:before (fieldStack part (.inl .scratch))=[])\n    (hv:before (fieldStack part (.inr ()))=[]) :\n    Runs program (8*word.length+7) (ctl pc) before (ctl next)\n      (Function.update (Function.update (Function.update before (fieldStack part (.inl .input)) tail)\n        (fieldStack part (.inl .output)) word) (fieldStack part (.inr ())) [true]) :=by\n  let start:=SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) []\n  let stop:SemiprimeD1StackBytecode.State Field.Stack Field.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩\n  have hin:Link.DataRel (fieldStack part) before start.store before:=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k\n        · exact hi\n        · exact hs\n        · exact ho\n      · cases k;exact hv\n    · intro k _;rfl\n  have h0:=Link.data_update (fieldStack part) (field_injective part) before start.store before hin (.inl .input) tail\n  have h1:=Link.data_update (fieldStack part) (field_injective part) before _ _ h0 (.inl .output) word\n  have h2:=Link.data_update (fieldStack part) (field_injective part) before _ _ h1 (.inr ()) [true]\n  have he:Function.update (Function.update (Function.update start.store (.inl .input) tail) (.inl .output) word) (.inr ()) [true]=stop.store:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h2\n  exact included_call program (fieldStack part) (Label.parser part) (field_injective part) Field.code\n    (Field.active .tagPop (none,false)) (fun _=>rfl) (ctl pc) (ctl next) hc (8*word.length+6) start stop before _ rfl rfl\n    (SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []) hin h2\n/-- Real preserving Frame writes a physical field onto its existing dictionary/vector tail. -/\ntheorem frame_call (pc next:Control)\n    (hc:program (ctl pc)=.call (.framer 0) (ctl next)) (before:Stack→List Bool) (word buffer:List Bool)\n    (hw:before (frameStack 0)=word) (hb:before (frameStack 1)=buffer) (hs:before (frameStack 2)=[]) :\n    Runs program (6*word.length+5) (ctl pc) before (ctl next)\n      (Function.update before (frameStack 1) (frame word buffer)) :=by\n  let start:=SemiprimeD1StackFrame.state 0 none word buffer []\n  let stop:=SemiprimeD1StackFrame.done word (frame word buffer)\n  have hi:Link.DataRel (frameStack) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hw\n      · exact hb\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (frameStack) (frame_injective) before start.store before hi (1:Fin 3) (frame word buffer)\n  have he:Function.update start.store 1 (frame word buffer)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (frameStack) Label.framer (frame_injective) SemiprimeD1StackFrame.code 0 (fun _=>rfl)\n    (ctl pc) (ctl next) hc (6*word.length+4) start stop before _ rfl rfl\n    (SemiprimeD1StackFrame.frame_words word buffer none) hi ho\n/-- One literal local push preserves the entire other physical bank and all real outer returns. -/\ntheorem push_run (pc:Control) (next:Label) (k:Stack) (b:Bool) (before:Stack→List Bool)\n    (hc:program (ctl pc)=.base (.push k b next)) :\n    Runs program 1 (ctl pc) before next (Function.update before k (b::before k)) :=\n  one_base program _ _ _ _ _ hc rfl rfl\n/-- One literal local pop consumes ONLYthe actual physical Boolean head. -/\ntheorem pop_run (pc:Control) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program (ctl pc)=.base (.pop k empty low high)) (hx:before k=xs) :\n    Runs program 1 (ctl pc) before (SemiprimeD1StackBytecode.choose empty low high xs.head?) (Function.update before k xs.tail) :=by\n  apply one_base program (ctl pc) _ (.pop k empty low high) before _ hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n/-- Real EOF peek does not silently discard any remaining singleton-result bytes. -/\ntheorem peek_run (pc:Control) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program (ctl pc)=.base (.peek k empty low high)) (hx:before k=xs) :\n    Runs program 1 (ctl pc) before (SemiprimeD1StackBytecode.choose empty low high xs.head?) before :=by\n  apply one_base program (ctl pc) _ (.peek k empty low high) before before hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · rfl\n/-- Every table/key/owner/row cleanup actually visits every byte and its final empty branch. -/\ntheorem drain_loop (pc:Control) (next:Label) (k:Stack)\n    (hc:program (ctl pc)=.base (.pop k next (ctl pc) (ctl pc))) (before:Stack→List Bool) (xs:List Bool) (hx:before k=xs) :\n    Runs program (xs.length+1) (ctl pc) before next (Function.update before k []) :=by\n  induction xs generalizing before with\n  | nil=>exact pop_run pc next (ctl pc) (ctl pc) k before [] hc hx\n  | cons b xs ih=>\n    have h0:=pop_run pc next (ctl pc) (ctl pc) k before (b::xs) hc hx\n    have h1:=ih (Function.update before k xs) (Function.update_self _ _ _)\n    have hh:=join (by cases b <;> exact h0) h1\n    simpa only [List.length_cons,Function.update_idem,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using hh\n/-- Actual five-word comparison consumes only copied operands and returns its computed strict borrow. -/\ntheorem less_call (before:Stack→List Bool) (a b:List Bool)\n    (ha:before (aux .compareLeft)=a) (hb:before (aux .compareRight)=b)\n    (hs:before (aux .compareScratch)=[]) (hd:before (aux .discard)=[]) (ho:before (aux .compareOutput)=[]) :\n    Runs program (SemiprimeD1StackWordLessExecution.totalTime a b+1) (ctl .compare) before (ctl .compared)\n      (Function.update (Function.update (Function.update before (aux .compareLeft) [])\n        (aux .compareRight) []) (aux .compareOutput) [SemiprimeD1StackWordLessExecution.answer a b]) :=by\n  let start:=SemiprimeD1StackWordLess.initial a b\n  let stop:=SemiprimeD1StackWordLessExecution.done a b\n  have hin:Link.DataRel lessStack before start.data before:=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k\n        · exact ha\n        · exact hb\n        · exact hs\n        · exact hd\n      · cases k;exact ho\n    · intro k _;rfl\n  have h0:=Link.data_update lessStack less_injective before start.data before hin (.inl .left) []\n  have h1:=Link.data_update lessStack less_injective before _ _ h0 (.inl .right) []\n  have h2:=Link.data_update lessStack less_injective before _ _ h1 (.inr ()) [SemiprimeD1StackWordLessExecution.answer a b]\n  have he:Function.update (Function.update (Function.update start.data (.inl .left) []) (.inl .right) [])\n      (.inr ()) [SemiprimeD1StackWordLessExecution.answer a b]=stop.data:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h2\n  exact SemiprimeD1StackProcedureCallsTrace.included_call program lessStack Label.less less_injective\n    Less.program .start (fun _=>rfl) (ctl .compare) (ctl .compared) rfl\n    (SemiprimeD1StackWordLessExecution.totalTime a b) start stop before _ rfl rfl rfl rfl\n    (SemiprimeD1StackWordLessExecution.source_run a b) hin h2\n/-- The shared environment instructions are included twice structurally, with every real return retained. -/\ntheorem environment_code (pc:E.Label) :\n    program (environmentLabel pc)=SemiprimeD1StackValidationLink.instruction environmentStack environmentLabel\n      (SemiprimeD1StackSourceEnvironment.program pc) :=by\n  change SemiprimeD1StackValidationLink.instruction queryStack Label.queryCode\n    (SemiprimeD1StackValidationLink.instruction Q.environmentStack (fun l=>(show Q.Label from .environment l))\n      (SemiprimeD1StackSourceEnvironment.program pc))=_\n  generalize SemiprimeD1StackSourceEnvironment.program pc=op\n  cases op with\n  | base op=>cases op <;> rfl\n  | call entry next=>rfl\n  | ret=>rfl\n/-- Every environment role is a direct distinct field of the actual scorer bank. -/\ntheorem environment_injective :Function.Injective environmentStack :=by\n  intro i j h\n  exact Sum.inl_injective (Sum.inl_injective h)\n/-- Generic caller preservation for the actual shared environment entry; only proved literal traces instantiate it. -/\ntheorem environment_call (pc next:Control) (entry:E.Label)\n    (hc:program (ctl pc)=.call (environmentLabel entry) (ctl next))\n    (time:Nat) (start stop:SemiprimeD1StackCalls.State E.Stack E.Label) (before after:Stack→List Bool)\n    (he:start.pc=some entry) (hf:start.frames=[]) (hn:stop.pc=none) (ht:stop.frames=[])\n    (hr:SemiprimeD1StackCalls.run SemiprimeD1StackSourceEnvironment.program time start=some stop)\n    (hin:Link.DataRel environmentStack before start.data before)\n    (hout:Link.DataRel environmentStack before stop.data after) :\n    Runs program (time+1) (ctl pc) before (ctl next) after :=\n  SemiprimeD1StackProcedureCallsTrace.included_call program environmentStack environmentLabel environment_injective\n    SemiprimeD1StackSourceEnvironment.program entry environment_code (ctl pc) (ctl next) hc time\n    start stop before after he hf hn ht hr hin hout\n/-- The real parser's true-valid byte is physically consumed before returning the complete unframed word. -/\ntheorem field_valid (part:Part) (pc validPC:Control) (next:Label)\n    (hc:program (ctl pc)=.call (.parser part (Field.active .tagPop (none,false))) (ctl validPC))\n    (hp:program (ctl validPC)=.base (.pop (aux .valid) (ctl .abort) (ctl .abort) next))\n    (before:Stack→List Bool) (word tail:List Bool)\n    (hi:before (fieldStack part (.inl .input))=frame word tail)\n    (ho:before (fieldStack part (.inl .output))=[])\n    (hs:before (fieldStack part (.inl .scratch))=[])\n    (hv:before (aux .valid)=[]) :\n    Runs program (8*word.length+8) (ctl pc) before next\n      (Function.update (Function.update before (fieldStack part (.inl .input)) tail)\n        (fieldStack part (.inl .output)) word) :=by\n  let after:=Function.update (Function.update before (fieldStack part (.inl .input)) tail)\n    (fieldStack part (.inl .output)) word\n  have hout:aux .valid ≠ fieldStack part (.inl .output):=\n    by\n      intro h\n      have he:=field_injective part (show fieldStack part (.inr ())=fieldStack part (.inl .output) from h)\n      cases he\n  have hin:aux .valid ≠ fieldStack part (.inl .input):=\n    by\n      intro h\n      have he:=field_injective part (show fieldStack part (.inr ())=fieldStack part (.inl .input) from h)\n      cases he\n  have hvalid:after (aux .valid)=[]:=by\n    dsimp only [after]\n    rw [Function.update_of_ne hout,Function.update_of_ne hin,hv]\n  have h0:=field_call part pc validPC hc before word tail hi ho hs hv\n  change Runs program (8*word.length+7) _ _ _ (Function.update after (aux .valid) [true]) at h0\n  have h1:=pop_run validPC (ctl .abort) (ctl .abort) next (aux .valid)\n    (Function.update after (aux .valid) [true]) [true] hp (Function.update_self _ _ _)\n  change Runs program 1 _ _ _ (Function.update (Function.update after (aux .valid) [true]) (aux .valid) []) at h1\n  have hz:Function.update after (aux .valid) []=after:=by\n    simpa only [hvalid] using (Function.update_eq_self (aux .valid) after)\n  rw [Function.update_idem,hz] at h1\n  have h:=join h0 h1\n  simpa only [Nat.add_assoc,SemiprimeD1StackBytecode.choose,List.head?_cons,after] using h\n/-- Unused colour bytes are parsed, validated and entirely drained; only the actual reader tail changes. -/\ntheorem field_discard (part:Part) (pc validPC drainPC:Control) (next:Label)\n    (hc:program (ctl pc)=.call (.parser part (Field.active .tagPop (none,false))) (ctl validPC))\n    (hp:program (ctl validPC)=.base (.pop (aux .valid) (ctl .abort) (ctl .abort) (ctl drainPC)))\n    (hd:program (ctl drainPC)=.base (.pop (fieldStack part (.inl .output)) next (ctl drainPC) (ctl drainPC)))\n    (before:Stack→List Bool) (word tail:List Bool)\n    (hi:before (fieldStack part (.inl .input))=frame word tail)\n    (ho:before (fieldStack part (.inl .output))=[])\n    (hs:before (fieldStack part (.inl .scratch))=[]) (hv:before (aux .valid)=[]) :\n    Runs program (9*word.length+9) (ctl pc) before next\n      (Function.update before (fieldStack part (.inl .input)) tail) :=by\n  let after:=Function.update before (fieldStack part (.inl .input)) tail\n  have hne:fieldStack part (.inl .output) ≠ fieldStack part (.inl .input):=\n    by\n      intro h\n      have he:=field_injective part h\n      cases he\n  have hzero:after (fieldStack part (.inl .output))=[]:=by\n    dsimp only [after]\n    rw [Function.update_of_ne hne,ho]\n  have h0:=field_valid part pc validPC (ctl drainPC) hc hp before word tail hi ho hs hv\n  have h1:=drain_loop drainPC next (fieldStack part (.inl .output)) hd\n    (Function.update after (fieldStack part (.inl .output)) word) word (Function.update_self _ _ _)\n  have hz:Function.update after (fieldStack part (.inl .output)) []=after:=by\n    simpa only [hzero] using (Function.update_eq_self (fieldStack part (.inl .output)) after)\n  rw [Function.update_idem,hz] at h1\n  have h:=join h0 h1\n  have ht:(8*word.length+8)+(word.length+1)=9*word.length+9:=by omega\n  simpa only [ht] using h\nend RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectPrimitives\n","RiemannGaussian.SemiprimeD1StackSourcePacketPaddingCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourcePacketPaddingPrimitives\n/-! # Real whole frequency acquisition once and optional actual counter-entry calls -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourcePacketPaddingCalls\nopen SemiprimeD1StackSourcePacketPadding SemiprimeD1StackSourcePacketPaddingPrimitives\nopen SemiprimeD1StackProcedureTrace\n/-- The whole actual key-only producer runs once, paying all real nested calls and preserving the acquired exponent/output fields. -/\ntheorem frequency_call (before:Stack→List Bool) (keys:List (List Bool))\n    (hi:∀k,before (frequencyStack k)=(SemiprimeD1StackSourceKeyFrequencyEncoding.source keys).data k) :\n    ∃q≤ SemiprimeD1StackSourceKeyFrequencyExecution.runBound keys+1,Runs program q .start before .copyCut\n      (Sum.elim (SemiprimeD1StackSourceKeyFrequencyEncoding.done keys).data (fun k=>before (aux k))) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackSourceKeyFrequencyExecution.source_run keys\n  refine ⟨q+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program frequencyStack Label.frequency frequency_injective\n    F.program .start (fun _=>rfl) .start .copyCut rfl q\n    (SemiprimeD1StackSourceKeyFrequencyEncoding.source keys) (SemiprimeD1StackSourceKeyFrequencyEncoding.done keys) _ _\n    rfl rfl rfl rfl hr\n  · exact ⟨hi,fun _ _=>rfl⟩\n  · constructor\n    · intro k;rfl\n    · intro k hk;rcases k with k|k\n      · exact (hk k rfl).elim\n      · rfl\n/-- Only actual high-suffix bytes are incremented; every other frequency/cache/exponent word is retained exactly. -/\ntheorem counter_call (before:Stack→List Bool) (word:List Bool)\n    (hw:before (frequencyStack F.oldCount)=word)\n    (hn:before (frequencyStack (F.aux .incNext))=[])\n    (hi:before (frequencyStack (F.aux .incScratch))=[])\n    (ht:before (frequencyStack (F.aux .trimScratch))=[])\n    (ho:before (frequencyStack (F.aux .count))=[])\n    (hl:before (frequencyStack (F.lookupStack (.inl .left)))=[])\n    (hr:before (frequencyStack (F.lookupStack (.inl .right)))=[]) :\n    ∃q≤40*(word.length+1)+2,Runs program q (.cutDone true) before .prefix\n      (Function.update (Function.update before (frequencyStack F.oldCount) []) (frequencyStack (F.aux .count))\n        (SemiprimeD1StackSourceEnvironmentEncoding.successor word)) :=by\n  let small:=fun k=>before (frequencyStack k)\n  let start:C.State F.Stack F.Label:=⟨some .increment,none,none,small,[]⟩\n  let stop:C.State F.Stack F.Label:=⟨none,none,none,Function.update (Function.update small F.oldCount []) (F.aux .count)\n    (SemiprimeD1StackSourceEnvironmentEncoding.successor word),[]⟩\n  obtain ⟨q,hq,htrace⟩:=SemiprimeD1StackSourceKeyFrequencyCounterEntry.source_run small word hw hn hi ht ho hl hr\n  have hin:Link.DataRel frequencyStack before start.data before:=⟨fun _=>rfl,fun _ _=>rfl⟩\n  have h0:=Link.data_update frequencyStack frequency_injective before start.data before hin F.oldCount []\n  have h1:=Link.data_update frequencyStack frequency_injective before _ _ h0 (F.aux .count)\n    (SemiprimeD1StackSourceEnvironmentEncoding.successor word)\n  refine ⟨q+1,by omega,?_⟩\n  exact SemiprimeD1StackProcedureCallsTrace.included_call program frequencyStack Label.frequency frequency_injective F.program\n    .increment (fun _=>rfl) (.cutDone true) .prefix rfl q start stop before _ rfl rfl rfl rfl htrace hin h1\nend RiemannGaussian.SemiprimeD1StackSourcePacketPaddingCalls\n","RiemannGaussian.SemiprimeD1StackStaticTable":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackDigitCountExecution\nimport RiemannGaussian.SemiprimeD1StackReverseWord\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\nimport RiemannGaussian.SemiprimeD1StackProcedureReturns\nimport RiemannGaussian.SemiprimeD1TensorTapeCodec\n/-! # Static finite checker to an actual whole truth-table compiler\nThe checker code and complete finite role inventory are fixed before every\ninput. Runtime data consist of original checker input words in a read-only\ntemplate and a physical scope-ID bank. A real scanner acquires its record\ncount. Every DFS leaf copies the template, reverses the real assignment,\nexecutes the fixed checker, emits its actual Boolean and clears every role.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackStaticTable\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace D\nexport SemiprimeD1StackDigitCount (Stack Label program data)\nend D\n/-- Compile-time parameters only. Neither the checker nor its role list belongs\nto a runtime configuration. Concrete clients instantiate one constant value. -/\nstructure Static (K L : Type) where\n  /-- Literal finite source program, fixed before input. -/\n  code : L→C.Instruction K L\n  /-- Fixed actual checker entry label. -/\n  entry : L\n  /-- Physical raw-assignment operand. -/\n  raw : K\n  /-- Physical singleton Boolean result operand. -/\n  output : K\n  /-- Computable literal inventory of all physical checker roles. -/\n  roles : List K\n  /-- Every role, including dormant private shadows, is visited. -/\n  complete : ∀k,k∈roles\n  /-- Every static role occurs exactly once. -/\n  nodup : roles.Nodup\n/-- Private DFS roles; physical scope counter.count is used directly as depth. -/\ninductive Aux where | prefix | work | scratch | reversed | output\n  deriving DecidableEq\ninstance : Fintype Aux := Fintype.ofList [.prefix,.work,.scratch,.reversed,.output]\n  (by intro k;cases k <;> simp)\n/-- All physical roles: real checker, read-only input template, real scope\ncounter and five DFS words. Every type is fixed before the original input. -/\nabbrev Stack (K : Type) := K⊕(K⊕(D.Stack⊕Aux))\n/-- Literal checker-bank role. -/\ndef checker {K : Type} (k : K) : Stack K := .inl k\n/-- Literal read-only original-input template role. -/\ndef template {K : Type} (k : K) : Stack K := .inr (.inl k)\n/-- Literal physical scanner/counting role. -/\ndef counter {K : Type} (k : D.Stack) : Stack K := .inr (.inr (.inl k))\n/-- Literal DFS-private physical role. -/\ndef aux {K : Type} (k : Aux) : Stack K := .inr (.inr (.inr k))\n/-- Fixed finite source labels. The role indices range over the STATIC role\ninventory only; no input number, template, assignment or count enters control. -/\ninductive Label (L : Type) (size : Nat) where\n  | start | build | finish | done | bad\n  | visit | fork | low | high | afterLow | setHigh | afterHigh | restore | returnDone\n  | leaf | prefixCopy | reversePrefix | check | verdict | leafCleanup | leafReturn\n  | load (position : Fin (size+1)) | loadCopy (position : Fin size)\n  | clear (position : Fin (size+1))\n  | zero (position : Fin 4) | one (position : Fin 6)\n  | checker (pc : L) | counter (pc : D.Label)\n  | copy (position : Option (Fin size)) (pc : Fin 9)\n  | reverse (table : Bool) (pc : Fin 4)\n  deriving Fintype\nvariable {K L : Type} [DecidableEq K] (s : Static K L)\n/-- Exactly one role at a fixed position of the compile-time inventory. -/\ndef role (position : Fin s.roles.length) : K := s.roles[position.val]\n/-- Actual preserving-copy wiring; none copies the reverse assignment prefix,\nsome copies one complete template word into its checker operand. -/\ndef copyStack (position : Option (Fin s.roles.length)) (k : Fin 3) : Stack K :=\n  if k=0 then position.elim (aux .prefix) (fun p=>template (role s p))\n  else if k=1 then position.elim (aux .work) (fun p=>checker (role s p)) else aux .scratch\n/-- Both actual consuming reversals, including direct raw-assignment delivery. -/\ndef reverseStack (table : Bool) (k : Fin 2) : Stack K :=\n  if k=0 then aux (if table then .reversed else .work)\n  else if table then aux .output else checker s.raw\n/-- Next static bank-copy position. -/\ndef loadNext (p : Fin s.roles.length) : Label L s.roles.length := .load ⟨p.val+1,by omega⟩\n/-- Literal zero/one root scalar codes, in the frozen tree codec. -/\ndef zeroBits (p : Fin 4) : Bool := [false,true,false,false][p.val]!\n/-- Literal accepted root scalar code. -/\ndef oneBits (p : Fin 6) : Bool := [false,true,true,true,false,false][p.val]!\n/-- The entire compiler program depends ONLY on the static checker. In\nparticular no N, template bytes, predicate, arity or budget is a parameter. -/\ndef program : Label L s.roles.length→C.Instruction (Stack K) (Label L s.roles.length)\n  | .start=>.call (.counter (.inl .main)) .build\n  | .build=>.call .visit .finish\n  | .finish=>.call (.reverse true 0) .done\n  | .done | .bad=>.base .halt\n  | .visit=>.base (.pop (counter .count) .leaf .fork .fork)\n  | .fork=>.base (.push (aux .reversed) true .low)\n  | .low=>.base (.push (aux .prefix) false .high)\n  | .high=>.call .visit .afterLow\n  | .afterLow=>.base (.pop (aux .prefix) .bad .setHigh .setHigh)\n  | .setHigh=>.base (.push (aux .prefix) true .afterHigh)\n  | .afterHigh=>.call .visit .restore\n  | .restore=>.base (.pop (aux .prefix) .bad .returnDone .returnDone)\n  | .returnDone=>.base (.push (counter .count) true .leafReturn)\n  | .leaf=>.call (.load 0) .prefixCopy\n  | .load pos=>if h:pos.val<s.roles.length then\n      .base (.pop (checker (role s ⟨pos.val,h⟩)) (.loadCopy ⟨pos.val,h⟩) (.load pos) (.load pos))\n      else .ret\n  | .loadCopy pos=>.call (.copy (some pos) 0) (loadNext s pos)\n  | .prefixCopy=>.call (.copy none 0) .reversePrefix\n  | .reversePrefix=>.call (.reverse false 0) .check\n  | .check=>.call (.checker s.entry) .verdict\n  | .verdict=>.base (.pop (checker s.output) .bad (.zero 0) (.one 0))\n  | .zero pos=>.base (.push (aux .reversed) (zeroBits pos)\n      (if h:pos.val<3 then .zero ⟨pos.val+1,by omega⟩ else .leafCleanup))\n  | .one pos=>.base (.push (aux .reversed) (oneBits pos)\n      (if h:pos.val<5 then .one ⟨pos.val+1,by omega⟩ else .leafCleanup))\n  | .leafCleanup=>.call (.clear 0) .leafReturn\n  | .leafReturn=>.ret\n  | .clear pos=>if h:pos.val<s.roles.length then\n      .base (.pop (checker (role s ⟨pos.val,h⟩)) (.clear ⟨pos.val+1,by omega⟩) (.clear pos) (.clear pos))\n      else .ret\n  | .checker pc=>SemiprimeD1StackValidationLink.instruction checker Label.checker (s.code pc)\n  | .counter pc=>SemiprimeD1StackValidationLink.instruction counter Label.counter (D.program pc)\n  | .copy pos pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack s pos) (Label.copy pos)\n      (SemiprimeD1StackCopy.code pc)\n  | .reverse table pc=>SemiprimeD1StackMultiplierLink.instruction (reverseStack s table) (Label.reverse table)\n      (SemiprimeD1StackReverseWord.code pc)\n/-- Complete data view. Functions here describe only fixed finite physical banks. -/\ndef store (live original : K→List Bool) (count : D.Stack→List Bool) (front work scratch hist out : List Bool) :\n    Stack K→List Bool := Sum.elim live (Sum.elim original (Sum.elim count (fun k=>match k with\n      | .prefix=>front | .work=>work | .scratch=>scratch | .reversed=>hist | .output=>out)))\n/-- Stable DFS view: checker empty, entire original input template and scope\nbank retained, actual unary count restored after each recursive visit. -/\ndef data (original : K→List Bool) (bank : List Bool) (depth : Nat) (front hist : List Bool) : Stack K→List Bool :=\n  store (fun _=>[]) original (D.data bank [] (List.replicate depth true) [] [] [] []) front [] [] hist []\n/-- The only initial data are actual checker-input template bytes and actual\nscope-bank bytes. No unary count, raw assignment, result or table is supplied. -/\ndef initial (original : K→List Bool) (bank : List Bool) : C.State (Stack K) (Label L s.roles.length) :=\n  ⟨some .start,none,none,data original bank 0 [] [],[]⟩\n/-- Fixed genuine finite machine for this one static checker. -/\ndef machine [Fintype K] [Fintype L] : Turing.FinTM2 :=\n  SemiprimeD1StackCalls.machine (counter .bank) (aux .output) .start (program s)\nomit [DecidableEq K] in\n/-- Complete role count, including BOTH actual checker and original-template banks. -/\ntheorem stack_card [Fintype K] : Fintype.card (Stack K)=2*Fintype.card K+12 := by\n  simp only [Stack,Fintype.card_sum,SemiprimeD1StackDigitCount.stack_card]\n  have ha:Fintype.card Aux=5:=by decide\n  omega\n/-- All actual finite flags and return-label control are fixed before input. -/\ntheorem control_finite [Fintype K] [Fintype L] : Finite (machine s).σ :=\n  SemiprimeD1StackCalls.control_finite (counter .bank) (aux .output) .start (program s)\nend RiemannGaussian.SemiprimeD1StackStaticTable\n","RiemannGaussian.SemiprimeD1StackStaticTableLeaf":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticTableLeafCalls\n/-! # Whole actual reusable static-checker leaf and its own bit clock -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1800000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackStaticTableLeaf\nopen SemiprimeD1StackStaticTable SemiprimeD1StackStaticTableSpec\nopen SemiprimeD1StackStaticTableLeafCalls SemiprimeD1StackStaticTableCleanup SemiprimeD1StackStaticTableEmit\nopen SemiprimeD1StackProcedureTrace SemiprimeD1StackProcedureReturns\nopen SemiprimeD1BooleanTreeStream (leafBytes)\nvariable {K L : Type} [DecidableEq K] [Fintype K] (s : Static K L)\n/-- Actual template, prefix, checker, codec and complete cleanup allowance.\nThe budget is a PROVED checker trace bound, never an executed source operand. -/\ndef leafBound (original : K→List Bool) (budget : Nat→Nat) (width : Nat) : Nat :=\n  s.roles.length*(6*inputBytes original+5)+7*width+budget width+\n    s.roles.length*(Fintype.card K*(inputBytes original+width+budget width)+1)+20\nomit [DecidableEq K] [Fintype K] in\n/-- Whole checker clearing preserves exactly the original template, scanner and DFS data. -/\ntheorem clean_withChecker (original : K→List Bool) (bank : List Bool) (depth : Nat)\n    (front hist : List Bool) (live : K→List Bool) :\n    clean (withChecker (data original bank depth front hist) live)=data original bank depth front hist := by\n  funext k;cases k <;> rfl\n/-- Actual post-checker inventory is bounded by executed pushes, not by an\nassumed workspace/canonicality/retention contract. The result pop only shrinks it. -/\ntheorem popped_inventory_le (original : K→List Bool) (raw : List Bool) (budget : Nat→Nat)\n    (t : Nat) (finish : C.State K L) (ht : t≤ budget raw.length)\n    (hr : C.run s.code t (checkerInitial s original raw)=some finish) (base : Stack K→List Bool) :\n    inventory (withChecker base (Function.update finish.data s.output []))≤\n      Fintype.card K*(inputBytes original+raw.length+budget raw.length) := by\n  have hp (k : K) :\n      ((withChecker base (Function.update finish.data s.output [])) (checker k)).length≤\n        inputBytes original+raw.length+budget raw.length := by\n    change (Function.update finish.data s.output [] k).length≤_\n    by_cases h:k=s.output\n    · subst k\n      rw [Function.update_self]\n      exact Nat.zero_le _\n    · rw [Function.update_of_ne h]\n      have hdata:=output_cell_le s original raw t finish hr k\n      omega\n  change (∑k:K,((withChecker base (Function.update finish.data s.output [])) (checker k)).length)≤_\n  calc\n    _≤∑_k:K,(inputBytes original+raw.length+budget raw.length):=Finset.sum_le_sum (fun k _=>hp k)\n    _= _:=by simp only [Finset.sum_const,Finset.card_univ,smul_eq_mul]\n/-- COMPLETE executed leaf: copy every actual template input, reverse the\nphysical prefix, call the fixed checker, consume its real singleton output,\nwrite each codec bit, drain ALL checker roles, and pop the real caller frame. -/\ntheorem leaf_returns (original : K→List Bool) (hraw : original s.raw=[])\n    (answer : List Bool→Bool) (budget : Nat→Nat) (hc : CheckerTrace s original answer budget)\n    (bank front hist : List Bool) :\n    ∃t≤ leafBound s original budget front.length,Returns (program s) t .leaf\n      (data original bank 0 front hist)\n      (data original bank 0 front ((leafBytes (answer front.reverse)).reverse++hist)) := by\n  let nextHist:=(leafBytes (answer front.reverse)).reverse++hist\n  obtain ⟨a,ha,h0⟩:=load_call s original bank front hist\n  have h1:=copy_prefix s original bank front hist\n  have h2:=reverse_prefix s original hraw bank front hist\n  obtain ⟨b,hb,finish,hr,hvalue,h3⟩:=checker_call s original answer budget hc bank front hist\n  have h4:=verdict_pop s original bank front hist finish.data (answer front.reverse) hvalue\n  have h5:=emit_run s (answer front.reverse) (Function.update finish.data s.output []) original bank front hist\n  let cleanupData:=withChecker (data original bank 0 front nextHist) (Function.update finish.data s.output [])\n  obtain ⟨c,hcTime,hclear⟩:=clear_returns s cleanupData\n  have h6:=SemiprimeD1StackProcedureReturns.call (program s) c .leafCleanup (.clear 0) .leafReturn\n    cleanupData (clean cleanupData) rfl hclear\n  have he:clean cleanupData=data original bank 0 front nextHist:=clean_withChecker original bank 0 front nextHist _\n  rw [he] at h6\n  have h:=runs_trans (program s) _ _ _ _ _ _ _ _ h0\n    (runs_trans (program s) _ _ _ _ _ _ _ _ h1\n      (runs_trans (program s) _ _ _ _ _ _ _ _ h2\n        (runs_trans (program s) _ _ _ _ _ _ _ _ h3\n          (runs_trans (program s) _ _ _ _ _ _ _ _ h4\n            (runs_trans (program s) _ _ _ _ _ _ _ _ h5 h6)))))\n  refine ⟨_,?_,of_runs (program s) _ .leaf .leafReturn _ _ h rfl⟩\n  have hInv:=popped_inventory_le s original front.reverse budget b finish\n    (by simpa only [List.length_reverse] using hb) hr (data original bank 0 front nextHist)\n  simp only [List.length_reverse] at hInv\n  have hlen:(leafBytes (answer front.reverse)).length≤6:=by cases answer front.reverse <;> decide\n  unfold leafBound\n  change inventory cleanupData≤_ at hInv\n  have hm:=Nat.mul_le_mul_left s.roles.length (Nat.add_le_add_right hInv 1)\n  omega\nomit [DecidableEq K] [Fintype K] in\n/-- The physically emitted local0/1 scalar is exactly the frozen tree-codec leaf. -/\ntheorem leaf_bytes (answer : List Bool→Bool) (raw : List Bool) :\n    leafBytes (answer raw)=SemiprimeD1TensorTapeCodec.tape (tree answer raw 0) :=\n  SemiprimeD1BooleanTreeStream.leafBytes_original _\nend RiemannGaussian.SemiprimeD1StackStaticTableLeaf\n","RiemannGaussian.SemiprimeD1StackStaticWordTableBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticWordTableExecution\n/-! # Complete same-source static-table time and every physical prefix cell -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackStaticWordTableBounds\nopen SemiprimeD1StackStaticWordTable SemiprimeD1StackStaticWordTableSpec\nopen SemiprimeD1StackStaticWordTableExecution SemiprimeD1StackStaticWordTableDFS\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nvariable {K L : Type} [DecidableEq K] [Fintype K] (s : Static K L)\n/-- Every leaf's physical output word is bounded by its proved actual source trace. -/\ntheorem answer_length (original : K→List Bool) (answer : List Bool→List Bool) (budget : Nat→Nat)\n    (hc : CheckerTrace s original answer budget) (raw : List Bool) :\n    (answer raw).length ≤ inputBytes original+raw.length+budget raw.length := by\n  obtain ⟨t,ht,finish,_,_,hr,hv⟩ := hc raw\n  have hh := output_cell_le s original raw t finish hr s.output\n  rw [hv] at hh\n  omega\n/-- Whole physical tree bytes retain every bit of each actually produced word. -/\ntheorem tree_length (original : K→List Bool) (answer : List Bool→List Bool) (budget : Nat→Nat)\n    (hc : CheckerTrace s original answer budget) (front : List Bool) (n : Nat) :\n    (tape (tree answer front n)).length+1 ≤\n      (2*(inputBytes original+front.length+n+budget (front.length+n))+5)*2^n := by\n  induction n generalizing front with\n  | zero =>\n    have hw := answer_length s original answer budget hc front\n    rw [←SemiprimeD1StackStaticWordTableEmit.leaf_bytes,SemiprimeD1StackStaticWordTableEmit.leafBytes_length]\n    simp only [Nat.add_zero,pow_zero,Nat.mul_one]\n    omega\n  | succ n ih =>\n    have hl := ih (front++[false])\n    have hr := ih (front++[true])\n    change (true::(tape (tree answer (front++[false]) n)++tape (tree answer (front++[true]) n))).length+1 ≤ _\n    have hfalse : (front++[false]).length+n=front.length+(n+1) := by simp only [List.length_append,List.length_singleton];omega\n    have htrue : (front++[true]).length+n=front.length+(n+1) := by simp only [List.length_append,List.length_singleton];omega\n    have hcf : inputBytes original+(front++[false]).length+n=inputBytes original+front.length+(n+1) := by\n      simp only [List.length_append,List.length_singleton];omega\n    have hct : inputBytes original+(front++[true]).length+n=inputBytes original+front.length+(n+1) := by\n      simp only [List.length_append,List.length_singleton];omega\n    rw [hfalse,hcf] at hl\n    rw [htrue,hct] at hr\n    simp only [List.length_cons,List.length_append,pow_succ,←Nat.mul_assoc]\n    omega\n/-- Every physical record contributes actual bytes, including an empty zero ID. -/\ntheorem scope_count_le (words : List (List Bool)) : words.length≤(vectorBits words).length := by\n  induction words with\n  | nil=>decide\n  | cons w ws ih=>\n    simp only [List.length_cons,vectorBits,SemiprimeSourceHistogramKeyBits.frame_length]\n    omega\n/-- Closed own source clock: physical scope bytes plus a fixed per-leaf\npolynomial in original input, actual arity and PROVED checker bit time. -/\ndef runBound (original : K→List Bool) (words : List (List Bool)) (budget : Nat→Nat) : Nat :=\n  (11*(vectorBits words).length+weight s original budget words.length+\n    4*(inputBytes original+words.length+budget words.length)+40)*2^words.length\n/-- Counter, every actual leaf/cleanup/return and complete physical final\nreversal satisfy the same own source bound, without an old native report. -/\ntheorem timeBound_le (original : K→List Bool) (words : List (List Bool))\n    (answer : List Bool→List Bool) (budget : Nat→Nat) (hc : CheckerTrace s original answer budget) :\n    timeBound s original words answer budget≤ runBound s original words budget := by\n  have hcount:=SemiprimeD1StackDigitCountExecution.totalTime_le words\n  have ht := tree_length s original answer budget hc [] words.length\n  simp only [List.length_nil,Nat.zero_add,Nat.add_zero] at ht\n  change (outputTape answer words).length+1 ≤ (2*(inputBytes original+words.length+budget words.length)+5)*2^words.length at ht\n  have hp:1≤(2:Nat)^words.length:=by\n    have h:0<(2:Nat)^words.length:=by positivity\n    omega\n  have hh:=Nat.mul_le_mul_left (11*(vectorBits words).length+12) hp\n  simp only [Nat.mul_one] at hh\n  unfold timeBound runBound\n  nlinarith\n/-- The complete proved source trace, using its own uniform whole-table clock. -/\ntheorem source_run_bounded (original : K→List Bool) (hraw : original s.raw=[])\n    (answer : List Bool→List Bool) (budget : Nat→Nat) (hc : CheckerTrace s original answer budget)\n    (words : List (List Bool)) :\n    ∃t≤ runBound s original words budget,C.run (program s) t (initial s original (vectorBits words))=\n      some (done s original words answer) := by\n  obtain ⟨t,ht,hr⟩:=source_run s original hraw answer budget hc words\n  exact ⟨t,ht.trans (timeBound_le s original words answer budget hc),hr⟩\n/-- Genuine fixed finite-machine time, with only original input template and\nphysical scope bytes initially present. No source evaluator or clock is run. -/\nnoncomputable def tableInTime [Fintype L] (original : K→List Bool) (hraw : original s.raw=[])\n    (answer : List Bool→List Bool) (budget : Nat→Nat) (hc : CheckerTrace s original answer budget)\n    (words : List (List Bool)) :\n    StateTransition.EvalsToInTime (machine s).step\n      (SemiprimeD1StackCalls.configuration (initial s original (vectorBits words)))\n      (some (SemiprimeD1StackCalls.configuration (done s original words answer))) (runBound s original words budget) := by\n  apply SemiprimeD1StackCalls.evalsCorrect (counter .bank) (aux .output) .start (program s)\n  let h:=source_run_bounded s original hraw answer budget hc words\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nomit [DecidableEq K] in\n/-- Every initialized physical field is paid by template and actual scope bytes. -/\ntheorem initial_cell_le (original : K→List Bool) (bank : List Bool) (key : Stack K) :\n    ((initial s original bank).data key).length≤ inputBytes original+bank.length := by\n  rcases key with k|k\n  · exact Nat.zero_le _\n  · rcases k with k|k\n    · have hs:(original k).length≤ inputBytes original:=by\n        change (original k).length≤∑j:K,(original j).length\n        exact Finset.single_le_sum (f:=fun j:K=>(original j).length) (fun _ _=>Nat.zero_le _) (Finset.mem_univ k)\n      change (original k).length≤_\n      omega\n    · rcases k with k|k\n      · cases k <;> simp [initial,data,store,D.data]\n      · cases k <;> exact Nat.zero_le _\n/-- Every successful physical prefix precedes this actual source's halt. -/\ntheorem prefix_fuel_le (original : K→List Bool) (hraw : original s.raw=[])\n    (answer : List Bool→List Bool) (budget : Nat→Nat) (hc : CheckerTrace s original answer budget)\n    (words : List (List Bool)) (fuel : Nat) (finish : C.State (Stack K) (Label L s.roles.length))\n    (hr : C.run (program s) fuel (initial s original (vectorBits words))=some finish) :\n    fuel≤ runBound s original words budget := by\n  obtain ⟨t,ht,he⟩:=source_run_bounded s original hraw answer budget hc words\n  have hf:fuel≤ t:=by\n    by_contra hn\n    have hs:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [hs,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:C.run (program s) 1 (done s original words answer)=none:=rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- ALL checker AND read-only template roles, all7 count roles, all5 DFS roles\nand every real nested return cell are bounded at EVERY actual prefix. -/\ntheorem prefix_cells (original : K→List Bool) (hraw : original s.raw=[])\n    (answer : List Bool→List Bool) (budget : Nat→Nat) (hc : CheckerTrace s original answer budget)\n    (words : List (List Bool)) (fuel : Nat) (finish : C.State (Stack K) (Label L s.roles.length))\n    (hr : C.run (program s) fuel (initial s original (vectorBits words))=some finish) :\n    (∑k:Stack K,(finish.data k).length)+finish.frames.length≤\n      (2*Fintype.card K+13)*(inputBytes original+(vectorBits words).length+runBound s original words budget+1) := by\n  let I:=inputBytes original+(vectorBits words).length\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound (program s) fuel I _ finish\n    (initial_cell_le s original (vectorBits words)) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound (program s) fuel _ finish hr\n  change finish.frames.length≤0+fuel at hf\n  have hs:(∑k:Stack K,(finish.data k).length)≤(2*Fintype.card K+12)*(I+fuel):=by\n    calc\n      _≤∑_k:Stack K,(I+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _= _:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le s original hraw answer budget hc words fuel finish hr\n  have hmul:=Nat.mul_le_mul_left (2*Fintype.card K+13) ht\n  dsimp [I] at hs\n  nlinarith\n/-- Every prefix of the ACTUAL compiled finite machine has the same complete\nBoolean payload and real return-cell bound; no shadow/readonly role is omitted. -/\ntheorem machine_prefix_cells [Fintype L] (original : K→List Bool) (hraw : original s.raw=[])\n    (answer : List Bool→List Bool) (budget : Nat→Nat) (hc : CheckerTrace s original answer budget)\n    (words : List (List Bool)) (fuel : Nat) (cfg : (machine s).Cfg)\n    (hr : (fun q=>q.bind (machine s).step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial s original (vectorBits words))))=some cfg) :\n    (∑k:Stack K,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      (2*Fintype.card K+13)*(inputBytes original+(vectorBits words).length+runBound s original words budget+1) := by\n  have he:=SemiprimeD1StackCalls.run_correct (counter .bank) (aux .output) .start (program s) fuel\n    (initial s original (vectorBits words))\n  have hh:(C.run (program s) fuel (initial s original (vectorBits words))).map\n      SemiprimeD1StackCalls.configuration=some cfg:=he.trans hr\n  cases hrun:C.run (program s) fuel (initial s original (vectorBits words)) with\n  | none=>rw [hrun] at hh;cases hh\n  | some finish=>\n    rw [hrun] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration finish=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells s original hraw answer budget hc words fuel finish hrun\n/-- Every actual data and return alphabet is finite before any input. -/\ntheorem all_alphabets_finite [Fintype L] (k : (machine s).K) : Finite ((machine s).Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite (counter .bank) (aux .output) .start (program s) k\n/-- Every included actual source instruction compiles to at most four\nfundamental commands; static checker calls remain real physical calls. -/\ntheorem compile_depth [Fintype L] (pc : Label L s.roles.length) :\n    SemiprimeD1StackBytecode.statementDepth ((machine s).m pc)≤4 :=\n  SemiprimeD1StackCalls.compile_depth (.start : Label L s.roles.length) (program s pc)\nend RiemannGaussian.SemiprimeD1StackStaticWordTableBounds\n","RiemannGaussian.SemiprimeD1StackStaticWordTableLeaf":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticWordTableLeafCalls\n/-! # Whole actual binary-coefficient leaf and complete physical cleanup -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackStaticWordTableLeaf\nopen SemiprimeD1StackStaticWordTable SemiprimeD1StackStaticWordTableSpec\nopen SemiprimeD1StackStaticWordTableLeafCalls SemiprimeD1StackStaticWordTableCleanup\nopen SemiprimeD1StackStaticWordTableEmit SemiprimeD1StackProcedureTrace SemiprimeD1StackProcedureReturns\nvariable {K L : Type} [DecidableEq K] [Fintype K] (s : Static K L)\n/-- Own executed template/assignment/source/framing/cleanup allowance; the\nsource budget is a proved trace bound and never a physical operand. -/\ndef leafBound (original : K → List Bool) (budget : Nat → Nat) (width : Nat) : Nat :=\n  s.roles.length*(6*inputBytes original+5)+7*width+budget width+\n    s.roles.length*(Fintype.card K*(inputBytes original+width+budget width)+1)+\n    50*(inputBytes original+width+budget width+1)+50\nomit [DecidableEq K] [Fintype K] in\n/-- Whole checker clearing preserves exactly the retained template/scanner/DFS words. -/\ntheorem clean_withChecker (original : K → List Bool) (bank : List Bool) (depth : Nat)\n    (front hist : List Bool) (live : K → List Bool) :\n    clean (withChecker (data original bank depth front hist) live)=data original bank depth front hist := by\n  funext k;cases k <;> rfl\n/-- The actual stopped source bank is bounded by its own executed pushes. -/\ntheorem checker_inventory_le (original : K → List Bool) (raw : List Bool) (budget : Nat → Nat)\n    (t : Nat) (finish : C.State K L) (ht : t ≤ budget raw.length)\n    (hr : C.run s.code t (checkerInitial s original raw)=some finish) (base : Stack K → List Bool) :\n    inventory (withChecker base finish.data) ≤\n      Fintype.card K*(inputBytes original+raw.length+budget raw.length) := by\n  have hp (k : K) : (finish.data k).length ≤ inputBytes original+raw.length+budget raw.length := by\n    have hh := output_cell_le s original raw t finish hr k\n    omega\n  change (∑ k : K, (finish.data k).length) ≤ _\n  calc\n    _ ≤ ∑ _k : K, (inputBytes original+raw.length+budget raw.length) := Finset.sum_le_sum (fun k _ => hp k)\n    _ = _ := by simp only [Finset.sum_const,Finset.card_univ,smul_eq_mul]\n/-- COMPLETE actual leaf: physically load every template role, reverse the\nactual assignment, call the fixed coefficient source, frame its actual word,\nwrite all tags/reversal, physically drain ALL checker roles, then really return. -/\ntheorem leaf_returns (original : K → List Bool) (hraw : original s.raw=[])\n    (answer : List Bool → List Bool) (budget : Nat → Nat) (hc : CheckerTrace s original answer budget)\n    (bank front hist : List Bool) :\n    ∃ t ≤ leafBound s original budget front.length, Returns (program s) t .leaf\n      (data original bank 0 front hist)\n      (data original bank 0 front ((leafBytes (answer front.reverse)).reverse++hist)) := by\n  let nextHist := (leafBytes (answer front.reverse)).reverse++hist\n  obtain ⟨a,ha,h0⟩ := load_call s original bank front hist\n  have h1 := copy_prefix s original bank front hist\n  have h2 := reverse_prefix s original hraw bank front hist\n  obtain ⟨b,hb,finish,hr,hvalue,h3⟩ := checker_call s original answer budget hc bank front hist\n  have h4 := emit_run s finish.data original bank front hist\n  rw [hvalue] at h4\n  let cleanupData := withChecker (data original bank 0 front nextHist) finish.data\n  obtain ⟨c,hcTime,hclear⟩ := clear_returns s cleanupData\n  have h5 := SemiprimeD1StackProcedureReturns.call (program s) c .leafCleanup (.clear 0) .leafReturn\n    cleanupData (clean cleanupData) rfl hclear\n  have he : clean cleanupData=data original bank 0 front nextHist := clean_withChecker original bank 0 front nextHist _\n  rw [he] at h5\n  have hh := runs_trans (program s) _ _ _ _ _ _ _ _ h0\n    (runs_trans (program s) _ _ _ _ _ _ _ _ h1\n      (runs_trans (program s) _ _ _ _ _ _ _ _ h2\n        (runs_trans (program s) _ _ _ _ _ _ _ _ h3\n          (runs_trans (program s) _ _ _ _ _ _ _ _ h4 h5))))\n  refine ⟨_,?_,of_runs (program s) _ .leaf .leafReturn _ _ hh rfl⟩\n  have hInv := checker_inventory_le s original front.reverse budget b finish\n    (by simpa only [List.length_reverse] using hb) hr (data original bank 0 front nextHist)\n  have hWord := output_cell_le s original front.reverse b finish hr s.output\n  rw [hvalue,List.length_reverse] at hWord\n  simp only [List.length_reverse] at hInv\n  unfold leafBound\n  change inventory cleanupData ≤ _ at hInv\n  have hm := Nat.mul_le_mul_left s.roles.length (Nat.add_le_add_right hInv 1)\n  omega\nend RiemannGaussian.SemiprimeD1StackStaticWordTableLeaf\n\n","RiemannGaussian.SemiprimeD1StackTransformDescriptorRecord":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSelectedDescriptorRecordBounds\nimport RiemannGaussian.SemiprimeD1StackTransformSelectorsOriginal\nimport RiemannGaussian.SemiprimeD1StackPublicTransformRecordOriginal\nimport RiemannGaussian.SemiprimeD1StackPublicTransformRecordClock\n/-! # Actual450-role transform descriptor, physical stage/inverse and entire row\nOnly original acquired fields/scope and charged dirty words are supplied.\nBoth singleton flags are pushed by bounded physical source decoding before\nthe actual complete template/table/serializer/logger source is called.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1800000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackTransformDescriptorRecord\nnamespace I\nexport SemiprimeD1StackPublicTransformTable (static inputTemplate)\nend I\nnamespace P\nexport SemiprimeD1StackPublicTransformTable.P (inputRole second inverse assignment)\nend P\nnamespace G\nexport SemiprimeD1StackSelectedDescriptorRecord (descriptorStack selectorStack rawSource history output fields)\nend G\nnamespace T\nexport SemiprimeD1StackPublicTransformTableTrace (answer budget actual_trace)\nend T\n/-- Fixed actual204-role complete transform checker. -/\nabbrev Checker :=SemiprimeD1StackPublicTransform.Stack\n/-- Static map ONLY N0 and the two ACTUALLY CONSTRUCTED singleton selectors1/2. -/\ndef sourceMap (k : Checker) : Option (Fin 6) :=\n  if k=P.inputRole then some 0 else if k=P.second then some 1 else if k=P.inverse then some 2 else none\n/-- All450 physical words, including every dormant loader/selector/record shadow. -/\nabbrev Stack :=SemiprimeD1StackSelectedDescriptorRecord.Stack Checker\n/-- All actual nested copy/load/checker/serializer/logger/return labels. -/\nabbrev Label :=SemiprimeD1StackSelectedDescriptorRecord.Label SemiprimeD1StackPublicTransform.Label I.static.roles.length\n/-- One literal fixed program, independent of original N and every descriptor value. -/\ndef program : Label→SemiprimeD1StackCalls.Instruction Stack Label :=\n  SemiprimeD1StackSelectedDescriptorRecord.program I.static sourceMap\n/-- Only actual original words/scope, caller accumulators and paid dirty words. -/\ndef initial (oldTemplate : Checker→List Bool) (raw : Fin 6→List Bool)\n    (oldStage oldInverse bank hist out : List Bool) : SemiprimeD1StackCalls.State Stack Label :=\n  SemiprimeD1StackSelectedDescriptorRecord.initial I.static oldTemplate raw oldStage oldInverse bank hist out\n/-- Same genuine finite machine before every original N and descriptor. -/\ndef machine : Turing.FinTM2 :=SemiprimeD1StackSelectedDescriptorRecord.machine I.static sourceMap\n/-- Literal original constructor code corresponding to the PROOF-side stage flag. -/\ndef tagCode (second : Bool) : Fin 18 :=if second then 3 else 1\n/-- Both literal original stage entries have the actual physical dispatch. -/\ntheorem tag_dispatch (second : Bool) : SemiprimeD1StackTransformSelectors.tagDispatch (tagCode second)=.copyTransform second :=by\n  cases second <;> rfl\n/-- Complete physical role count, including all alias shadows. -/\ntheorem stack_card : Fintype.card Stack=450 :=by\n  rw [SemiprimeD1StackSelectedDescriptorRecord.stack_card,SemiprimeD1StackPublicTransform.stack_card]\n/-- Selected ACTUAL source words equal exactly the frozen original initialization:\nN and two singleton flags, every source/cache/count/assignment/verdict empty. -/\ntheorem selected_template (raw : Fin 6→List Bool) (second inverse : Bool) :\n    SemiprimeD1StackDescriptorRecord.selected sourceMap (G.fields raw [second] [inverse])=\n      I.inputTemplate (raw 0) second inverse :=by\n  funext k\n  rw [SemiprimeD1StackPublicTransformTableTrace.template_only]\n  change (if k=P.inputRole then some 0 else if k=P.second then some 1 else if k=P.inverse then some 2 else none).elim []\n    (G.fields raw [second] [inverse])=_\n  by_cases hn:k=P.inputRole\n  · subst k;rfl\n  · by_cases hs:k=P.second\n    · subst k;rfl\n    · by_cases hi:k=P.inverse\n      · subst k;rfl\n      · simp only [hn,hs,hi,ite_false];rfl\n/-- Actual final state after both acquired selectors and the complete original row source. -/\ndef done (raw : Fin 6→List Bool) (second inverse : Bool) (words : List (List Bool)) (hist out : List Bool) :\n    SemiprimeD1StackCalls.State Stack Label :=\n  SemiprimeD1StackSelectedDescriptorRecord.done I.static sourceMap raw second inverse words\n    (T.answer (raw 0) second inverse) hist out\n/-- Complete own source clock; stage/inverse are proof-side output notation only. -/\ndef timeBound (oldTemplate : Checker→List Bool) (raw : Fin 6→List Bool) (second inverse : Bool)\n    (words : List (List Bool)) (oldStage oldInverse hist out : List Bool) : Nat :=\n  SemiprimeD1StackSelectedDescriptorRecordExecution.timeBound I.static sourceMap oldTemplate raw second inverse words\n    (T.answer (raw 0) second inverse) (T.budget (raw 0)) oldStage oldInverse hist out\n/-- Actual complete source. Both selectors are derived from the original raw\nconstructor/coord0 bytes; no generic checker or selector supplier remains. -/\ntheorem source_run (oldTemplate : Checker→List Bool) (raw : Fin 6→List Bool) (second : Bool) (code : Fin 3)\n    (htag : raw 1=List.replicate (tagCode second).val true) (htr : raw 2=List.replicate code.val true)\n    (hc : SemiprimeSourceCompactBits.Compact (raw 0)) (hN : 0<SemiprimeBitArithmetic.bitValue (raw 0))\n    (words : List (List Bool)) (oldStage oldInverse hist out : List Bool) :\n    ∃t≤timeBound oldTemplate raw second (code.val==2) words oldStage oldInverse hist out,\n      SemiprimeD1StackCalls.run program t (initial oldTemplate raw oldStage oldInverse\n        (SemiprimeD1TensorTapeCodec.vectorBits words) hist out)=some (done raw second (code.val==2) words hist out) :=by\n  apply SemiprimeD1StackSelectedDescriptorRecordExecution.source_run I.static sourceMap oldTemplate raw\n    (tagCode second) code second htag htr (tag_dispatch second)\n  · rw [selected_template];rfl\n  · rw [selected_template]\n    exact T.actual_trace (raw 0) second (code.val==2) hc hN\n/-- Same genuine fixed machine, including every actual nested return-stack cell. -/\nnoncomputable def recordInTime (oldTemplate : Checker→List Bool) (raw : Fin 6→List Bool) (second : Bool) (code : Fin 3)\n    (htag : raw 1=List.replicate (tagCode second).val true) (htr : raw 2=List.replicate code.val true)\n    (hc : SemiprimeSourceCompactBits.Compact (raw 0)) (hN : 0<SemiprimeBitArithmetic.bitValue (raw 0))\n    (words : List (List Bool)) (oldStage oldInverse hist out : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial oldTemplate raw oldStage oldInverse (SemiprimeD1TensorTapeCodec.vectorBits words) hist out))\n      (some (SemiprimeD1StackCalls.configuration (done raw second (code.val==2) words hist out)))\n      (timeBound oldTemplate raw second (code.val==2) words oldStage oldInverse hist out) :=by\n  apply SemiprimeD1StackSelectedDescriptorRecordExecution.recordInTime I.static sourceMap oldTemplate raw\n    (tagCode second) code second htag htr (tag_dispatch second)\n  · rw [selected_template];rfl\n  · rw [selected_template]\n    exact T.actual_trace (raw 0) second (code.val==2) hc hN\n/-- Closed whole original checker clock plus ACTUAL finite selectors, charged\ntemplate acquisition, paid ordinal serialization and all literal tensor frames. -/\ndef runBound (oldTemplate : Checker→List Bool) (raw : Fin 6→List Bool) (second inverse : Bool)\n    (words : List (List Bool)) (M : Nat) (oldStage oldInverse hist out : List Bool) : Nat :=\n  SemiprimeD1StackTransformSelectorsExecution.timeBound (raw 1) (raw 2) oldStage oldInverse+\n    SemiprimeD1StackDescriptorRecordExecution.prepareBound I.static oldTemplate (G.fields raw [second] [inverse])\n      (SemiprimeD1TensorTapeCodec.vectorBits words) hist out+\n    SemiprimeD1StackPublicTransformRecordClock.runBound (raw 0) second inverse words M+6\n/-- Complete same-source own bit clock, without native report transport. -/\ntheorem timeBound_le (oldTemplate : Checker→List Bool) (raw : Fin 6→List Bool) (second inverse : Bool)\n    (words : List (List Bool)) (M : Nat) (oldStage oldInverse hist out : List Bool)\n    (hl : ∀w∈words,w.length≤M) (hv : ∀w∈words,SemiprimeBitArithmetic.bitValue w≤M) :\n    timeBound oldTemplate raw second inverse words oldStage oldInverse hist out≤\n      runBound oldTemplate raw second inverse words M oldStage oldInverse hist out :=by\n  have h:=SemiprimeD1StackPublicTransformRecordClock.timeBound_le (raw 0) second inverse words M hl hv\n  change SemiprimeD1StackStaticRecordExecution.timeBound I.static\n    (I.inputTemplate (raw 0) second inverse) words (T.answer (raw 0) second inverse) (T.budget (raw 0))≤_ at h\n  unfold timeBound SemiprimeD1StackSelectedDescriptorRecordExecution.timeBound\n    SemiprimeD1StackDescriptorRecordExecution.timeBound runBound\n  rw [selected_template]\n  omega\n/-- The entire frozen436-role record result after actual selector/template acquisition. -/\ntheorem component_done (raw : Fin 6→List Bool) (second inverse : Bool) (words : List (List Bool)) (hist out : List Bool)\n    (k : SemiprimeD1StackPublicTransformRecord.Stack) :\n    (done raw second inverse words hist out).data (G.descriptorStack (SemiprimeD1StackDescriptorRecord.recordStack k))=\n      (SemiprimeD1StackPublicTransformRecordExecution.done (raw 0) second inverse words hist out).data k :=by\n  unfold done SemiprimeD1StackSelectedDescriptorRecord.done SemiprimeD1StackSelectedDescriptorRecord.data\n    SemiprimeD1StackDescriptorRecord.done\n  rw [selected_template]\n  rfl\n/-- All six original acquired words survive in their own physical locations. -/\ntheorem retained_raw (raw : Fin 6→List Bool) (second inverse : Bool) (words : List (List Bool))\n    (hist out : List Bool) (i : Fin 6) : (done raw second inverse words hist out).data (G.rawSource i)=raw i :=by\n  exact SemiprimeD1StackSelectedDescriptorRecordExecution.retained_raw I.static sourceMap raw second inverse words\n    (T.answer (raw 0) second inverse) hist out i\nend RiemannGaussian.SemiprimeD1StackTransformDescriptorRecord\n","RiemannGaussian.SemiprimeD1StackUnaryProductRaw":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackUnaryProduct\n\n/-! # Actual product of physical counter lengths with arbitrary marker bits\nThis successor proves an additional trace of the SAME frozen literal program.\nBoth zero and one payload bits are counter cells. No normalized unary input,\ndecoded length, product or work answer is supplied to the executing program.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 900000\nnamespace RiemannGaussian.SemiprimeD1StackUnaryProductRaw\nopen SemiprimeD1StackUnaryProduct\nopen SemiprimeD1StackUnaryDivmod (unary unary_add)\nopen SemiprimeD1StackFiniteControlPaths (SourcePath)\n\n/-- Every actual multiplier cell triggers the same real preserving copy,\nirrespective of its payload bit. -/\ntheorem product_exec (m d : List Bool) (product : List Bool) (flag : Option Bool) :\n    Executes (m.length*(2*d.length+3)+1) (cfg (some .loop) flag m d [] product)\n      (cfg none none [] d [] (unary (m.length*d.length)++product)) := by\n  induction m generalizing flag product with\n  | nil =>\n    simp only [List.length_nil,Nat.zero_mul,show unary 0=[] from rfl,List.nil_append]\n    apply SourcePath.next ?_ (.refl _)\n    simp [program,cfg,contents,Turing.TM2.step,Turing.TM2.stepAux]\n  | cons b m ih =>\n    have hs : Turing.TM2.step program (cfg (some .loop) flag (b::m) d [] product)=\n        some (cfg (some .drain) (some b) m d [] product) := by\n      cases b <;> simp [program,cfg,contents,Turing.TM2.step,Turing.TM2.stepAux]\n    have hc:=copy_exec (some b) m d product\n    have ht:=ih (unary d.length++product) none\n    have h:=SourcePath.next hs (exec_trans hc ht)\n    have he : 2*d.length+2+(m.length*(2*d.length+3)+1)+1=\n        (m.length+1)*(2*d.length+3)+1 := by ring\n    rw [he] at h\n    simpa only [List.length_cons,Nat.add_mul,Nat.one_mul,unary_add,List.append_assoc] using h\n\n/-- The frozen generated bytecode actually acquires the product of physical\ncounter lengths, retaining the exact arbitrary multiplicand bytes. -/\ntheorem product_run (m d : List Bool) :\n    ∃t≤5*(m.length*(2*d.length+3)+1),SemiprimeD1StackBytecode.run code t\n      ⟨some entry,none,contents m d [] []⟩=\n      some ⟨none,none,contents [] d [] (unary (m.length*d.length))⟩ := by\n  obtain ⟨t,ht,flag,he⟩:=SemiprimeD1StackFiniteControlPaths.path_refines program 5 program_depth\n    (product_exec m d [] none) none\n  exact ⟨t,ht,by simpa [List.append_nil,SemiprimeD1StackFiniteControlExecution.destination,cfg,code,entry]\n    using SemiprimeD1StackFiniteControlPaths.Executes.iterates he⟩\nend RiemannGaussian.SemiprimeD1StackUnaryProductRaw\n","RiemannGaussian.SemiprimeD1StackVectorTableExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVectorTableDFS\n/-! # Complete physical scope count, static-checker DFS and final tape reversal\nEvery runtime operand is a Boolean tape word. The checker program is static;\ntrace contracts and mathematical predicates occur only in correctness proofs.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackVectorTableExecution\nopen SemiprimeD1StackVectorTable SemiprimeD1StackVectorTableSpec SemiprimeD1StackVectorTableDFS\nopen SemiprimeD1StackVectorTablePrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nvariable {K L : Type} [DecidableEq K] [Fintype K] (s : Static K L)\n/-- Actual complete output bytes, specified at the physically counted scope arity. -/\ndef outputTape (answer : List Bool→List (List Bool)) (words : List (List Bool)) : List Bool :=tape (tree answer [] words.length)\n/-- The final real store keeps the original template, original scope bank and\nthe acquired count; every checker/work/prefix/reversal scratch role is empty. -/\ndef result (original : K→List Bool) (words : List (List Bool)) (answer : List Bool→List (List Bool)) : Stack K→List Bool :=\n  Function.update (data original (vectorBits words) words.length [] []) (aux .output) (outputTape answer words)\n/-- The real final halt clears finite Boolean/return flags and actual frames. -/\ndef done (original : K→List Bool) (words : List (List Bool)) (answer : List Bool→List (List Bool)) :\n    C.State (Stack K) (Label L s.roles.length) :=⟨none,none,none,result original words answer,[]⟩\nomit [Fintype K] in\n/-- The actual bank scanner acquires arity from real record tags, including\nempty ordinal-zero fields, while retaining all original checker inputs. -/\ntheorem count_call (original : K→List Bool) (words : List (List Bool)) :\n    Runs (program s) (SemiprimeD1StackDigitCountExecution.totalTime words+1) .start\n      (data original (vectorBits words) 0 [] []) .build\n      (data original (vectorBits words) words.length [] []) := by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call (program s) counter _root_.RiemannGaussian.SemiprimeD1StackStaticWordTable.Label.counter\n    (by intro a b h;exact Sum.inl.inj (Sum.inr.inj (Sum.inr.inj h))) D.program (.inl .main)\n    (fun _=>rfl) .start .build rfl _\n    (SemiprimeD1StackDigitCountExecution.initial (vectorBits words))\n    (SemiprimeD1StackDigitCountExecution.done words)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackDigitCountExecution.acquire_run words\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · cases k with\n          | inl k=>exact (hk k rfl).elim\n          | inr k=>rfl\nomit [Fintype K] in\n/-- Exactly one physical consuming reversal writes the complete original-order tape. -/\ntheorem reverse_table (original : K→List Bool) (words : List (List Bool)) (answer : List Bool→List (List Bool)) :\n    Runs (program s) (2*(outputTape answer words).length+3) .finish\n      (data original (vectorBits words) words.length [] (outputTape answer words).reverse) .done\n      (result original words answer) := by\n  have h:=reverse_call s true .finish .done rfl\n    (data original (vectorBits words) words.length [] (outputTape answer words).reverse)\n  have hd:Function.update\n      (data original (vectorBits words) words.length [] (outputTape answer words).reverse) (aux .reversed) []=\n      data original (vectorBits words) words.length [] [] := by\n    funext k\n    rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · cases k <;> rfl\n  change Runs (program s) (2*(outputTape answer words).reverse.length+3) .finish\n    (data original (vectorBits words) words.length [] (outputTape answer words).reverse) .done\n    (Function.update (Function.update\n      (data original (vectorBits words) words.length [] (outputTape answer words).reverse) (aux .reversed) [])\n      (aux .output) ((outputTape answer words).reverse.reverse++[])) at h\n  rw [List.length_reverse,List.reverse_reverse,List.append_nil,hd] at h\n  exact h\n/-- This SAME source's complete actual own clock, including all scope-byte\nscanning, per-leaf template copies/checks/drains, real returns and final output. -/\ndef timeBound (original : K→List Bool) (words : List (List Bool))\n    (answer : List Bool→List (List Bool)) (budget : Nat→Nat) : Nat :=\n  SemiprimeD1StackDigitCountExecution.totalTime words+\n    weight s original budget words.length*2^words.length+2*(outputTape answer words).length+7\n/-- Whole actual source from only the original checker-input template and a\nphysical scope-ID vector. No count, raw assignment, table or verdict is input. -/\ntheorem source_run (original : K→List Bool) (hraw : original s.raw=[])\n    (answer : List Bool→List (List Bool)) (budget : Nat→Nat) (hc : CheckerTrace s original answer budget)\n    (words : List (List Bool)) :\n    ∃t≤ timeBound s original words answer budget,C.run (program s) t\n      (initial s original (vectorBits words))=some (done s original words answer) := by\n  have h0:=count_call s original words\n  obtain ⟨t,ht,hvisit⟩:=visit_returns s original hraw answer budget hc (vectorBits words) words.length [] []\n  simp only [List.length_nil,Nat.zero_add,List.reverse_nil,List.append_nil] at ht hvisit\n  have h1:=SemiprimeD1StackProcedureReturns.call (program s) t .build .visit .finish _ _ rfl hvisit\n  have h2:=reverse_table s original words answer\n  have h:=runs_trans (program s) _ _ _ _ _ _ _ _ h0 (runs_trans (program s) _ _ _ _ _ _ _ _ h1 h2)\n  obtain ⟨finish,hr,hout⟩:=h [] (initial s original (vectorBits words)) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run (program s) .done rfl (result original words answer) [] finish hout\n  refine ⟨(SemiprimeD1StackDigitCountExecution.totalTime words+1)+\n    ((1+t)+(2*(outputTape answer words).length+3))+1,?_,?_⟩\n  · unfold timeBound;omega\n  · rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some,hh]\n    rfl\nend RiemannGaussian.SemiprimeD1StackVectorTableExecution\n","RiemannGaussian.SemiprimeD1StackVertexCatalogueModes":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexCataloguePrepare\n\n/-! # Actual complete eighteen-mode loop\nAll mode bodies are the fixed acquired-limit Cartesian program. Readonly\nsource formats below are an internal invariant of actual cache acquisition;\nthe N-only endpoint derives them instead of accepting parameter answers.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option synthInstance.maxSize 4096\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackVertexCatalogueModes\nopen SemiprimeD1StackVertexCatalogue SemiprimeD1StackVertexCatalogueComponents\nopen SemiprimeD1StackVertexCatalogueView SemiprimeD1StackVertexCataloguePrepare\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\nopen SemiprimeD1VertexCatalogueModes (Mode Role code previous order dims dimension roles)\nopen SemiprimeD1VertexCatalogueEncoding (modeCatalogue catalogue)\n\n/-- Actual acquired source-role formats; not a public supplied graph/count interface. -/\ndef RoleFormat (r t digits:ℕ) (base:Stack→List Bool) : Prop :=\n  ∀role,base (roleStack role)=List.replicate (dimension r t digits role) true\n/-- Exact literal original constructor prefix, used only to specify the actual loop output. -/\ndef prefixCatalogue (r t digits:ℕ) (mode:Mode) (output:List Bool) : List Bool :=\n  (order.take (code mode+1)).foldr (fun m out=>modeCatalogue r t digits m out) output\n/-- One actual mode preparation/body/tag transition budget. -/\ndef blockBudget (D:ℕ) : ℕ := 24*D+43*(D+18)^5+22\n\n/-- Original first block is the literal input-vertex Cartesian family. -/\ntheorem prefix_input (r t digits:ℕ) (output:List Bool) :\n    prefixCatalogue r t digits .input output=modeCatalogue r t digits .input output := rfl\n/-- Descending physical emission gives the exact ascending original constructor prefix. -/\ntheorem prefix_previous (r t digits:ℕ) (mode:Mode) (hm:mode≠.input) (output:List Bool) :\n    prefixCatalogue r t digits mode output=\n      prefixCatalogue r t digits (previous mode) (modeCatalogue r t digits mode output) := by\n  cases mode <;> simp_all [prefixCatalogue,order,code,previous]\n/-- The final physical starting mode covers the complete original list, without a supplied catalogue. -/\ntheorem prefix_full (r t digits:ℕ) (output:List Bool) : prefixCatalogue r t digits .flagOr output=catalogue r t digits output := rfl\n\n/-- Standalone numeric stage substitution does not unfold executable configurations. -/\ntheorem numeric_block (D p k:ℕ) (hp:p≤24*D+20) (hk:k≤43*(D+18)^5+1) : p+k+1≤blockBudget D := by\n  unfold blockBudget\n  omega\n\n/-- Complete actual mode recursion; every resource/source-format premise is an\ninternal invariant discharged by the original-input acquisition endpoint. -/\ntheorem mode_run (r t digits:ℕ) (base:Stack→List Bool) (D:ℕ)\n    (hs:base scratchStack=[]) (hf:RoleFormat r t digits base) (hb:RoleBound D base)\n    (mode:Mode) (limits:Fin 4→List Bool) (output:List Bool) (hl:LimitBound D limits) :\n    ∃m≤(code mode+1)*blockBudget D,Runs program m (.inl (.clearLimit mode 0))\n      (view base limits (List.replicate (code mode) true) output) (.inl .halt)\n      (view base (preparedLimits base .input) [] (prefixCatalogue r t digits mode output)) := by\n  suffices h:∀k,∀mode:Mode,code mode=k→∀limits output,LimitBound D limits→\n      ∃m≤(k+1)*blockBudget D,Runs program m (.inl (.clearLimit mode 0))\n        (view base limits (List.replicate (code mode) true) output) (.inl .halt)\n        (view base (preparedLimits base .input) [] (prefixCatalogue r t digits mode output)) by\n    exact h (code mode) mode rfl limits output hl\n  intro k\n  induction k using Nat.strong_induction_on with\n  | h k ih =>\n    intro mode hk limits output hl\n    obtain ⟨p,hp,hprep⟩:=prepare_run base limits (List.replicate (code mode) true) output mode D hs hl hb\n    have hshape:∀j,preparedLimits base mode j=List.replicate (dims r t digits mode j) true:=fun j=>hf (roles mode j)\n    have hdim:∀j,dims r t digits mode j≤D:=by\n      intro j\n      have h:=hb (roles mode j)\n      rw [hf] at h\n      simpa only [List.length_replicate,dims] using h\n    obtain ⟨q,hq,hkernel⟩:=kernel_call base (dims r t digits mode) (preparedLimits base mode)\n      (List.replicate (code mode) true) output mode D hshape hdim\n    change Runs program q (.inl (.runMode mode))\n      (view base (preparedLimits base mode) (List.replicate (code mode) true) output)\n      (.inl (.afterMode mode))\n      (view base (preparedLimits base mode) (List.replicate (code mode) true) (modeCatalogue r t digits mode output)) at hkernel\n    have hqc:q≤43*(D+18)^5+1:=by\n      rw [List.length_replicate] at hq\n      exact hq.trans (Nat.add_le_add_right (Nat.mul_le_mul_left 43\n        (Nat.pow_le_pow_left (by have h:=SemiprimeD1VertexCatalogueModes.code_le mode;omega) 5)) 1)\n    have hblock:=numeric_block D p q hp hqc\n    by_cases hm:mode=.input\n    · subst mode\n      have hj:Runs program 1 (.inl (.afterMode .input))\n          (view base (preparedLimits base .input) [] (modeCatalogue r t digits .input output)) (.inl .halt)\n          (view base (preparedLimits base .input) [] (modeCatalogue r t digits .input output)):=\n        one_base program _ _ (.jump (.inl .halt)) _ _ rfl rfl rfl\n      have h:=hprep.trans (hkernel.trans hj)\n      refine ⟨p+(q+1),?_,?_⟩\n      · have hz:k=0:=by simpa only [code] using hk.symm\n        simpa only [hz,Nat.zero_add,Nat.one_mul,Nat.add_assoc] using hblock\n      · simpa only [code,prefix_input] using h\n    · have hpcode:=SemiprimeD1VertexCatalogueModes.previous_code mode hm\n      have hlt:code (previous mode)<k:=by omega\n      have hlim:LimitBound D (preparedLimits base mode):=fun j=>hb (roles mode j)\n      obtain ⟨z,hz,hprev⟩:=ih (code (previous mode)) hlt (previous mode) rfl (preparedLimits base mode)\n        (modeCatalogue r t digits mode output) hlim\n      have hpop:=pop_run (.inl (.afterMode mode)) (.inl (.clearLimit (previous mode) 0))\n        (kernelStack (Kernel.aux 3))\n        (view base (preparedLimits base mode) (List.replicate (code mode) true) (modeCatalogue r t digits mode output))\n        (by simp only [program,ite_eq_right hm])\n      change Runs program 1 _ _ _ (Function.update\n        (view base (preparedLimits base mode) (List.replicate (code mode) true) (modeCatalogue r t digits mode output))\n        (kernelStack (Kernel.aux 3)) (List.replicate (code mode) true).tail) at hpop\n      have ht:(List.replicate (code mode) true).tail=List.replicate (code (previous mode)) true:=by\n        rw [List.tail_replicate]\n        congr 1\n        omega\n      rw [ht,view_tag] at hpop\n      have h:=hprep.trans (hkernel.trans (hpop.trans hprev))\n      refine ⟨p+(q+(1+z)),?_,?_⟩\n      · rw [hpcode,hk] at hz\n        calc\n          p+(q+(1+z))≤blockBudget D+k*blockBudget D:=by omega\n          _=(k+1)*blockBudget D:=by ring\n      · simpa only [prefix_previous r t digits mode hm output] using h\nend RiemannGaussian.SemiprimeD1StackVertexCatalogueModes\n","RiemannGaussian.SemiprimeD1StackVertexReadExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexRead\n\n/-! # Exact executed vertex read from original physical argument tapes -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackVertexReadExecution\nopen SemiprimeD1StackVertexRead\nopen SemiprimeD1TensorTapeCodec (tape vectorBits)\nnamespace P\nexport SemiprimeD1StackProcedureTrace (At Runs included_call runs_trans halt_run)\nend P\nnamespace M\nexport SemiprimeD1StackMultiplierLink (DataRel)\nend M\nlocal notation \"ctl\" => SemiprimeD1StackVertexRead.control\n\n/-- Byte specification of already prepared unary original port indices. -/\ndef portTape (ports : List ℕ) : List Bool := vectorBits (ports.map (fun i => List.replicate i true))\n\n/-- Original physical arguments; acquisition of these tapes remains a caller operation. -/\ndef input (v : SemiprimeD1LeafCounter.Vertex) (assignment portTail tableTail : List Bool) :\n    Stack → List Bool :=\n  data (portTape v.ports++portTail) assignment [] [] [] [] (tape v.table++tableTail) [] []\n\n/-- Physical intermediate store: gathered bits are already the actual tree path. -/\ndef gathered (v : SemiprimeD1LeafCounter.Vertex) (assignment portTail tableTail : List Bool) :\n    Stack → List Bool :=\n  data portTail assignment [] [] [] (SemiprimeD1LeafCounter.gather assignment v.ports).bits\n    (tape v.table++tableTail) [] []\n\n/-- Exact output encoded jet vector and exact preserved original argument suffixes. -/\ndef output (v : SemiprimeD1LeafCounter.Vertex) (assignment portTail tableTail : List Bool) :\n    Stack → List Bool :=\n  data portTail assignment [] [] [] [] tableTail []\n    (vectorBits (SemiprimeD1TensorTapeLeaf.evaluateVertex v assignment).words)\n\n/-- Literal original local assignment matches the table reader's path width. -/\ntheorem gathered_drop (v : SemiprimeD1LeafCounter.Vertex) (assignment : List Bool) :\n    (SemiprimeD1LeafCounter.gather assignment v.ports).bits.drop v.ports.length=[] := by\n  rw [←SemiprimeD1LeafCounter.gather_length assignment v.ports]\n  exact List.drop_length\n\n/-- Exact byte payload equality, with no new evaluation/representation premise. -/\ntheorem lookup_words (v : SemiprimeD1LeafCounter.Vertex) (assignment : List Bool) :\n    (SemiprimeD1TensorTables.lookup v.table (SemiprimeD1LeafCounter.gather assignment v.ports).bits).words=\n      (SemiprimeD1TensorTapeLeaf.evaluateVertex v assignment).words := by\n  exact (SemiprimeD1TensorTapeLookup.fromTable_words v.table _).symm\n\n/-- Closed actual instruction budget, retaining both calls and final halt. -/\ndef budget (assignment ports tableTape : ℕ) : ℕ :=\n  SemiprimeD1StackGatherBytecode.budget assignment ports+\n    SemiprimeD1StackTreeBytecode.budget tableTape+3\n\n/-- Actual gather call puts the original local bits directly on the tree path stack. -/\ntheorem gather_call (v : SemiprimeD1LeafCounter.Vertex) (assignment portTail tableTail : List Bool) :\n    ∃m≤SemiprimeD1StackGatherBytecode.budget assignment.length (portTape v.ports).length+1,\n      P.Runs code m (ctl .start) (input v assignment portTail tableTail)\n        (ctl .gathered) (gathered v assignment portTail tableTail) := by\n  obtain ⟨m,hm,hr⟩ := SemiprimeD1StackGatherBytecode.original_gather_run assignment v.ports portTail []\n  simp only [List.append_nil] at hr\n  refine ⟨m+1,?_,?_⟩\n  · simpa only [portTape] using Nat.add_le_add_right hm 1\n  apply P.included_call code gatherStack gatherLabel gatherStack_injective G.code G.entry\n    (fun _ => rfl) (ctl .start) (ctl .gathered) rfl m _ _\n    (input v assignment portTail tableTail) (gathered v assignment portTail tableTail) rfl rfl hr\n  · constructor\n    · intro k; cases k <;> rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k; cases k <;> rfl\n    · intro k hk\n      cases k with\n      | ports => exact (hk .input rfl).elim\n      | assignment => exact (hk .assignment rfl).elim\n      | reader => exact (hk .reader rfl).elim\n      | scratch => exact (hk .scratch rfl).elim\n      | accumulator => exact (hk .accumulator rfl).elim\n      | path => exact (hk .output rfl).elim\n      | tableTape => rfl\n      | tasks => rfl\n      | output => rfl\n\n/-- Actual tree call scans selected/skipped subtrees and produces the original entry. -/\ntheorem tree_call (v : SemiprimeD1LeafCounter.Vertex) (assignment portTail tableTail : List Bool) :\n    ∃m≤SemiprimeD1StackTreeBytecode.budget (tape v.table).length+1,\n      P.Runs code m (ctl .gathered) (gathered v assignment portTail tableTail)\n        (ctl .done) (output v assignment portTail tableTail) := by\n  obtain ⟨m,hm,hr⟩ := SemiprimeD1StackTreeBytecode.tree_run v.table\n    (SemiprimeD1LeafCounter.gather assignment v.ports).bits tableTail\n  rw [gathered_drop,lookup_words] at hr\n  refine ⟨m+1,by omega,?_⟩\n  apply P.included_call code treeStack treeLabel treeStack_injective T.code T.entry\n    (fun _ => rfl) (ctl .gathered) (ctl .done) rfl m _ _\n    (gathered v assignment portTail tableTail) (output v assignment portTail tableTail) rfl rfl hr\n  · constructor\n    · intro k; cases k <;> rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k; cases k <;> rfl\n    · intro k hk\n      cases k with\n      | ports => rfl\n      | assignment => rfl\n      | reader => rfl\n      | scratch => exact (hk .scratch rfl).elim\n      | accumulator => rfl\n      | path => exact (hk .path rfl).elim\n      | tableTape => exact (hk .input rfl).elim\n      | tasks => exact (hk .tasks rfl).elim\n      | output => exact (hk .output rfl).elim\n\n/-- Closed original vertex pipeline executes both literal callees, then cleanly halts. -/\ntheorem vertex_run (v : SemiprimeD1LeafCounter.Vertex) (assignment portTail tableTail : List Bool) :\n    ∃m≤budget assignment.length (portTape v.ports).length (tape v.table).length,\n      C.run code m ⟨some (ctl .start),none,none,input v assignment portTail tableTail,[]⟩=\n      some ⟨none,none,none,output v assignment portTail tableTail,[]⟩ := by\n  obtain ⟨m,hm,hg⟩ := gather_call v assignment portTail tableTail\n  obtain ⟨n,hn,ht⟩ := tree_call v assignment portTail tableTail\n  have both := P.runs_trans code m n _ _ _ _ _ _ hg ht\n  obtain ⟨last,hr,hl⟩ := both []\n    (⟨some (ctl .start),none,none,input v assignment portTail tableTail,[]⟩ : C.State Stack Label)\n    ⟨rfl,rfl,rfl⟩\n  have hend := P.halt_run code (ctl .done) rfl (output v assignment portTail tableTail) [] last hl\n  refine ⟨m+n+1,by unfold budget; omega,?_⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some,hend]\n\nend RiemannGaussian.SemiprimeD1StackVertexReadExecution\n","RiemannGaussian.SemiprimeD1StackWeightedModeCatalogueOrders":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWeightedModeCatalogueSlots\n/-! # Actual order-major mode catalogue scan, including zero slots -/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWeightedModeCatalogueOrders\nopen SemiprimeD1StackWeightedModeCatalogue SemiprimeD1StackWeightedModeCatalogueView\nopen SemiprimeD1StackWeightedModeCataloguePrimitives SemiprimeD1StackWeightedModeCatalogueSlots\nopen SemiprimeD1StackWeightedModeView (unary unary_length unary_succ history history_append)\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => (Sum.inl :Control→Label)\n/-- Literal weight rows in the next acquired consecutive orders. -/\ndef orderWeights (slots first count:Nat):List (List Bool):=\n  (List.range count).flatMap (fun k=>slotWeights (first+k) slots)\n/-- Literal label rows in the next acquired consecutive orders. -/\ndef orderLabels (slots first count:Nat):List (List Bool):=\n  (List.range count).flatMap (fun k=>slotLabels (first+k) 0 slots)\ntheorem orderWeights_cons (slots first count:Nat):\n    orderWeights slots first (count+1)=slotWeights first slots++orderWeights slots (first+1) count:=by\n  rw [orderWeights,List.range_succ_eq_map]\n  simp only [List.flatMap_cons,List.flatMap_map,Nat.add_zero]\n  congr 1\n  apply congrArg ((List.range count).flatMap)\n  funext k\n  congr 1\n  omega\ntheorem orderLabels_cons (slots first count:Nat):\n    orderLabels slots first (count+1)=slotLabels first 0 slots++orderLabels slots (first+1) count:=by\n  rw [orderLabels,List.range_succ_eq_map]\n  simp only [List.flatMap_cons,List.flatMap_map,Nat.add_zero]\n  congr 1\n  apply congrArg ((List.range count).flatMap)\n  funext k\n  congr 1\n  omega\n/-- A nonempty order copies the computed slot product, emits every pair, then increments both metadata words. -/\ntheorem order_step (p t width n j:Nat) (wh lh:List Bool):\n    ∃time ≤100*(p*t+1)*(j+p*t+2)+5*(p*t)+8,Runs program time (ctl .orderCheck)\n      (store (scanning p t width (n+1) j 0 0 wh lh)) (ctl .orderCheck)\n      (store (scanning p t width n (j+1) 0 0\n        (history (slotWeights j (p*t)) wh) (history (slotLabels j 0 (p*t)) lh))):=by\n  let a:=scanning p t width (n+1) j 0 0 wh lh\n  let b:=scanning p t width (n+1) j (p*t) 0 wh lh\n  let wh':=history (slotWeights j (p*t)) wh\n  let lh':=history (slotLabels j 0 (p*t)) lh\n  let c:=scanning p t width (n+1) j 0 0 wh' lh'\n  let d:Words:={c with orders:=unary n}\n  let e:Words:={d with order:=unary (j+1)}\n  have h0:Runs program 1 (ctl .orderCheck) (store a) (ctl .copySlots) (store a):=by\n    apply one_base program _ _ _ _ _ rfl\n    · simp only [SemiprimeD1StackBytecode.execute,store,aux,a,scanning,unary_succ,List.head?_cons,\n        SemiprimeD1StackBytecode.choose]\n    · rfl\n  have h1:=copy_call true .copySlots .slotCheck rfl (store a) (unary (p*t)) [] rfl rfl rfl\n  rw [List.append_nil,store_write,unary_length] at h1\n  change Runs program (5*(p*t)+4) _ _ _ (store b) at h1\n  obtain ⟨u,hu,h2⟩:=slots_run p t width (n+1) j (p*t) 0 wh lh\n  change Runs program u _ (store b) _ (store c) at h2\n  have h3:=pop_run .orderPop .catalogueSeed .incrementOrder .incrementOrder (aux .orders) (store c)\n    (unary (n+1)) rfl rfl\n  rw [unary_succ,store_write] at h3\n  change Runs program 1 _ _ (ctl .incrementOrder) (store d) at h3\n  have h4:=push_run .incrementOrder .incrementWeight (aux .order) true (store d) rfl\n  rw [store_write] at h4\n  change Runs program 1 _ _ _ (store e) at h4\n  have h5:=push_run .incrementWeight .orderCheck (aux .weight) true (store e) rfl\n  rw [store_write] at h5\n  change Runs program 1 _ _ _ (store (scanning p t width n (j+1) 0 0 wh' lh')) at h5\n  have h:=join h0 (join h1 (join h2 (join h3 (join h4 h5))))\n  refine ⟨1+((5*(p*t)+4)+(u+(1+(1+1)))),?_,h⟩\n  simp only [Nat.add_zero] at hu\n  omega\n/-- Fixed arithmetic closure for the actual per-order scan costs. -/\ntheorem order_overhead (slots j n:Nat):\n    100*(slots+1)*(j+slots+2)+5*slots+8 ≤1000*(slots+1)*(j+n+slots+3):=by\n  nlinarith\n/-- Complete physical catalogue enumeration, with work polynomial in its actual finite dimensions. -/\ntheorem orders_run (p t width n j:Nat) (wh lh:List Bool):\n    ∃time ≤1000*(n+1)*(p*t+1)*(j+n+p*t+2),Runs program time (ctl .orderCheck)\n      (store (scanning p t width n j 0 0 wh lh)) (ctl .catalogueSeed)\n      (store (scanning p t width 0 (j+n) 0 0\n        (history (orderWeights (p*t) j n) wh) (history (orderLabels (p*t) j n) lh))):=by\n  induction n generalizing j wh lh with\n  | zero=>\n    refine ⟨1,?_,?_⟩\n    · have h:0 < 1000*(0+1)*(p*t+1)*(j+0+p*t+2):=by positivity\n      omega\n    ·\n      have h:Runs program 1 (ctl .orderCheck) (store (scanning p t width 0 j 0 0 wh lh))\n        (ctl .catalogueSeed) (store (scanning p t width 0 j 0 0 wh lh)):=\n      one_base program _ _ _ _ _ rfl rfl rfl\n      simpa only [Nat.add_zero,orderWeights,orderLabels,List.range_zero,List.flatMap_nil,history,\n        List.foldr_nil,List.reverse_nil,List.nil_append] using h\n  | succ n ih=>\n    obtain ⟨u,hu,h0⟩:=order_step p t width n j wh lh\n    obtain ⟨v,hv,h1⟩:=ih (j+1) (history (slotWeights j (p*t)) wh) (history (slotLabels j 0 (p*t)) lh)\n    have h:=join h0 h1\n    refine ⟨u+v,?_,?_⟩\n    · have he:1000*(n+1+1)*(p*t+1)*(j+(n+1)+p*t+2)=\n          1000*(n+1)*(p*t+1)*(j+1+n+p*t+2)+1000*(p*t+1)*(j+n+p*t+3):=by ring\n      rw [he]\n      have hh:=order_overhead (p*t) j n\n      omega\n    · rw [orderWeights_cons,orderLabels_cons,history_append,history_append]\n      have he:(j+1)+n=j+(n+1):=by omega\n      simpa only [he] using h\nend RiemannGaussian.SemiprimeD1StackWeightedModeCatalogueOrders\n","RiemannGaussian.SemiprimeD1StackWordFit":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProcedureTrace\nimport RiemannGaussian.SemiprimeD1StackPhysicalLoops\nimport RiemannGaussian.SemiprimeBitDivision\n\n/-! # Literal width fitting for public checker words\nThe binary template is retained by a real Copy call. Each copied template cell\ncauses a physical operand read and zero-padding when absent. Excess operand\ncells are physically cleared, then the accumulated word is actually reversed.\nThe template VALUE is never decoded; only its physical width is used.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 700000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWordFit\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\n\n/-- Five fixed Boolean data roles: input, cache, counter, scratch and output. -/\nabbrev Stack := Fin 5\n/-- Actual operand stack. -/\ndef operand : Stack := 0\n/-- Retained actual binary width template. -/\ndef template : Stack := 1\n/-- Disposable physical copy of the template, not a unary decoded value. -/\ndef counter : Stack := 2\n/-- Shared real copy-restoration and reverse-accumulation scratch. -/\ndef scratch : Stack := 3\n/-- Fixed-width fitted word output. -/\ndef output : Stack := 4\n/-- Three distinct literal Copy roles. -/\ndef copyStack (k : Fin 3) : Stack := if k=0 then template else if k=1 then counter else scratch\n/-- Actual finite labels, fixed before all operand lengths. -/\ninductive Label where\n  | start | take | read | save (b : Bool) | clear | restore | write (b : Bool) | done\n  | copy (pc : Fin 9)\n  deriving DecidableEq,Fintype,Repr\n\n/-- ONE finite instruction table; no fitting/value/arithmetic opcode exists. -/\ndef program : Label→C.Instruction Stack Label\n  | .start => .call (.copy 0) .take\n  | .take => .base (.pop counter .clear .read .read)\n  | .read => .base (.pop operand (.save false) (.save false) (.save true))\n  | .save b => .base (.push scratch b .take)\n  | .clear => .base (.pop operand .restore .clear .clear)\n  | .restore => .base (.pop scratch .done (.write false) (.write true))\n  | .write b => .base (.push output b .restore)\n  | .done => .base .halt\n  | .copy pc => SemiprimeD1StackMultiplierLink.instruction copyStack Label.copy (SemiprimeD1StackCopy.code pc)\n\n/-- Exact mathematical view of the physical payload. -/\ndef store (word cached count acc out : List Bool) : Stack→List Bool := fun k=>\n  if k=0 then word else if k=1 then cached else if k=2 then count else if k=3 then acc else out\n/-- Prepared physical word/template source entry; all work and return cells empty. -/\ndef initial (word cached : List Bool) : C.State Stack Label :=\n  ⟨some .start,none,none,store word cached [] [] [],[]⟩\n/-- Fixed actual machine; acquiring the physical template is the caller's task. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine operand output .start program\n/-- Real Copy operands are pairwise distinct. -/\ntheorem copyStack_injective : Function.Injective copyStack := by decide\n/-- All data and real return-tag alphabets are finite before the input. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite operand output .start program\n/-- Finite transient control contains no word, natural value or evaluator. -/\ntheorem control_finite : Finite machine.σ :=\n  SemiprimeD1StackCalls.control_finite operand output .start program\n\nend RiemannGaussian.SemiprimeD1StackWordFit\n","RiemannGaussian.SemiprimeD1WeightedCardinality":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1WeightedPotential\nimport RiemannGaussian.SemiprimeD1ModeCatalog\nimport RiemannGaussian.SemiprimeD1EulerBound\n\n/-! # Actual weighted-mode menu cardinality at every aspect ratio\nThe exponent is controlled by weighted precision, not Boolean support entropy.\nOriginal packet construction and recursive tensor factorization remain separate.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1WeightedCardinality\nopen SemiprimeD1WeightedTuples\nopen SemiprimeD1WeightedPotential SemiprimeD1ModeCatalog\nopen scoped BigOperators\n\n/-- Finite Euler bound applied to the actually enumerated positive-weight list. -/\ntheorem length_le_exp {ws : List ℕ} {a : ℝ} (ha : 0<a)\n    (K B P : ℕ) (hpos : ∀w∈ws,0<w) (hmax : ∀w∈ws,w≤K)\n    (hmult : ∀w,ws.count w≤B) :\n    ((tuples ws P).length:ℝ)≤ Real.exp (a*P+2*B/a) := by\n  have hc := length_le_potential ha hpos P\n  rw [normalizer_exp ha hpos,←Real.exp_add] at hc\n  have he := SemiprimeD1EulerBound.euler_log_sum_le a ha K\n  have he' : (∑j∈Finset.range K,logFactor a (j+1))≤2/a := by\n    simpa [logFactor,Nat.cast_add,Nat.cast_one] using he\n  have hs := (logsum_multiplicity ha K B hmax hmult).trans\n    (mul_le_mul_of_nonneg_left he' (Nat.cast_nonneg B))\n  apply hc.trans\n  apply Real.exp_le_exp.mpr\n  calc\n    _ ≤ a*P+(B:ℝ)*(2/a) := add_le_add le_rfl hs\n    _ = _ := by ring\n\n/-- Optimized coloured-partition bound for all B/P, including zero cases. -/\ntheorem length_le_sqrt (ws : List ℕ) (K B P : ℕ)\n    (hpos : ∀w∈ws,0<w) (hmax : ∀w∈ws,w≤K)\n    (hmult : ∀w,ws.count w≤B) :\n    ((tuples ws P).length:ℝ)≤ Real.exp (3*Real.sqrt ((B:ℝ)*P)) := by\n  by_cases hP : P=0\n  · subst P\n    simp [tuples_zero]\n  by_cases hB : B=0\n  · subst B\n    have hw : ws=[] := by\n      cases ws with\n      | nil => rfl\n      | cons w ws => have hc := hmult w; simp at hc\n    simp [hw,tuples]\n  have hBR : (0:ℝ)<B := Nat.cast_pos.mpr (Nat.pos_of_ne_zero hB)\n  have hPR : (0:ℝ)<P := Nat.cast_pos.mpr (Nat.pos_of_ne_zero hP)\n  have ha : 0<Real.sqrt (B:ℝ)/Real.sqrt (P:ℝ) :=\n    div_pos (Real.sqrt_pos.mpr hBR) (Real.sqrt_pos.mpr hPR)\n  have h := length_le_exp ha K B P hpos hmax hmult\n  simpa only [balance_exponent hBR hPR] using h\n\n/-- Acquired padded D1 modes have the floor-based bound, without D≈sqrt(u).\nThe only packet input is its genuine packing estimate, not a mode answer. -/\ntheorem packet_menu_bound (packets a i M P : ℕ) (hi : i≤a)\n    (hpackets : packets*2^a≤3*M) :\n    ((acquireModes packets (2^(i+1)) P).values.length:ℝ)≤\n      Real.exp (3*Real.sqrt (((6*M/2^(a-i):ℕ):ℝ)*P)) := by\n  rw [acquireModes_values]\n  exact length_le_sqrt _ P _ P (weights_positive _ _) (weights_le _ _)\n    (packet_multiplicity packets a i M P · hi hpackets)\n\n/-- Polynomial work factor for the actual catalogue and tuple traversal. -/\ndef modeFactor (slots P : ℕ) : ℕ := 20*(P+10)*(P*slots+1)^2\n\n/-- Explicit acquired catalogue, weight-copy and final report overhead. -/\ndef modeOverhead (slots P : ℕ) : ℕ := (10*P+10+P*(10*slots+10))+10*(P*slots)+10\n\n/-- Actual acquired native work has the same arbitrary-aspect exponential rate.\nThis is not an assertion that the native scalar/list report is a bit/tape clock. -/\ntheorem packet_work_bound (packets a i M P : ℕ) (hi : i≤a)\n    (hpackets : packets*2^a≤3*M) :\n    ((acquireModes packets (2^(i+1)) P).work:ℝ)≤\n      (modeFactor (packets*2^(i+1)) P:ℝ)*\n        Real.exp (3*Real.sqrt (((6*M/2^(a-i):ℕ):ℝ)*P))+\n          (modeOverhead (packets*2^(i+1)) P:ℝ) := by\n  have hn : (acquireModes packets (2^(i+1)) P).work≤\n      modeFactor (packets*2^(i+1)) P*(acquireModes packets (2^(i+1)) P).values.length+\n        modeOverhead (packets*2^(i+1)) P := by\n    simpa only [modeFactor,modeOverhead,Nat.add_assoc] using\n      acquireModes_work_le packets (2^(i+1)) P\n  have hr : ((acquireModes packets (2^(i+1)) P).work:ℝ)≤\n      (modeFactor (packets*2^(i+1)) P:ℝ)*\n        ((acquireModes packets (2^(i+1)) P).values.length:ℝ)+\n          (modeOverhead (packets*2^(i+1)) P:ℝ) := by exact_mod_cast hn\n  exact hr.trans (add_le_add (mul_le_mul_of_nonneg_left\n    (packet_menu_bound packets a i M P hi hpackets) (Nat.cast_nonneg _)) le_rfl)\n\nend RiemannGaussian.SemiprimeD1WeightedCardinality\n","RiemannGaussian.SemiprimeD1WordPacketTableClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1WordPacketEntryClock\nimport RiemannGaussian.SemiprimeD1ChildWordNetwork\nimport RiemannGaussian.SemiprimeD1ChildNetworkTapeBudget\nimport RiemannGaussian.SemiprimeD1ChildTableClock\n\n/-! # Actual eager packet-table acquisition and canonical recopy clock\nThe actual header and fresh producer are retained per table. Every assignment\nexecutes the concrete packet evaluator; its coefficient-recursion factor is\nkept explicit until the original schedule absorbs it.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 150000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1WordPacketTableClock\nopen SemiprimeD1JetAxes SemiprimeD1JetAffineCoefficient SemiprimeD1JetAffineCoefficientBounds\nopen SemiprimeD1JetWordPacketEntryBits SemiprimeD1WordPacketEntryClock\nopen SemiprimeD1PacketEntryBits (borrow)\nopen SemiprimeD1ChildNetworkTapeBudget (copyTable_clock)\nopen SemiprimeD1ChildTableCopyTape (tapeBudget tableCap)\nopen SemiprimeD1ChildNetwork\n\n/-- Actual complete eager packet table, with producer/header retained once. -/\ndef tableClock (ctx : Context) (a A K P T B L E H Z : ℕ) : ℕ :=\n  H+Z+(entryClock ctx a A K P T B L E+7)*2^A+L+12\n\n/-- Every actual assignment is charged; numerical caps describe original\nacquired data only, never desired table/entry/clock answers. -/\ntheorem acquire_clock {V : ℕ} (header : SemiprimeD1PacketTensorTables.Header V)\n    (ctx : Context) (z : JetRun) (hz : Good ctx z.words) (a : ℕ) (i : Fin a)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ) (A K P T B E : ℕ)\n    (hA : header.endpoints.length  ≤  A) (hK : header.masks.items.length=K)\n    (hmode : ∀item∈header.masks.items,item.mode.order  ≤  P)\n    (htile : ∀item∈header.masks.items,item.tile  ≤  T) (hbeta : ∀b∈beta,b  ≤  B)\n    (hslot : ∀e∈header.endpoints,e.slot.length  ≤  a) (hedge : ∀e∈header.endpoints,e.edge.length  ≤  E) :\n    (SemiprimeD1JetWordPacketTables.acquire header ctx z a i t beta).clock  ≤ \n      tableClock ctx a A K P T B beta.length E header.clock z.clock := by\n  have hbuild := SemiprimeD1TensorTables.build_clock header.endpoints.length\n    (entryClock ctx a A K P T B beta.length E)\n    (evaluate ctx (borrow z) a i t header.masks header.endpoints beta) (by\n      intro bits _\n      have h := evaluate_clock ctx (borrow z) hz a i t header.masks header.endpoints beta bits P T B E\n        hmode htile hbeta hslot hedge\n      rw [hK] at h\n      exact h.trans (entryClock_mono_arity ctx a _ A K P T B beta.length E hA))\n  have hpow : 2^header.endpoints.length  ≤  (2:ℕ)^A := Nat.pow_le_pow_right (by decide) hA\n  have hcap := Nat.mul_le_mul_left (entryClock ctx a A K P T B beta.length E+7) hpow\n  have hout : (SemiprimeD1TensorTables.build header.endpoints.length\n      (evaluate ctx (borrow z) a i t header.masks header.endpoints beta)).clock  ≤ \n      (entryClock ctx a A K P T B beta.length E+7)*2^A :=\n    (Nat.le_trans (Nat.le_add_right _ 5) hbuild).trans hcap\n  change header.clock+z.clock+\n    (SemiprimeD1TensorTables.build header.endpoints.length\n      (evaluate ctx (borrow z) a i t header.masks header.endpoints beta)).clock+beta.length+12  ≤  _\n  exact Nat.add_le_add_right (Nat.add_le_add_right\n    (Nat.add_le_add_left hout (header.clock+z.clock)) beta.length) 12\n\n/-- Whole actual new-factor vertex, including repeated graph acquisition and table recopy. -/\ndef rightClock (ctx : Context) (a A K P T B L E H Z G e : ℕ) : ℕ :=\n  tableClock ctx a A K P T B L E H Z+G+(tapeBudget (tableCap ctx A)+7)*2^A+A+e+10\n\n/-- Actual right-vertex acquisition retains its header, fresh input, graph and\nfull canonical-port recopy reports separately. -/\ntheorem rightOne_clock {r a : ℕ} (net : SemiprimeD1TensorNetwork.Network) (source : Source net a)\n    (i : Fin a) (g : Fin r) (ctx : Context) (z : JetRun) (hz : Good ctx z.words)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ)\n    (e : Fin (SemiprimeD1TensorNetworkLayout.childRows (graph net source i g)).length)\n    (A K P T B E : ℕ)\n    (hA : (SemiprimeD1PacketTensorTables.prepare (SemiprimeD1TensorNetwork.owner net.rows)\n      source (packetIndex net source i g e) i g).endpoints.length  ≤  A)\n    (hK : (SemiprimeD1PacketTensorTables.prepare (SemiprimeD1TensorNetwork.owner net.rows)\n      source (packetIndex net source i g e) i g).masks.items.length=K)\n    (hmode : ∀item∈(SemiprimeD1PacketTensorTables.prepare (SemiprimeD1TensorNetwork.owner net.rows)\n      source (packetIndex net source i g e) i g).masks.items,item.mode.order  ≤  P)\n    (htile : ∀item∈(SemiprimeD1PacketTensorTables.prepare (SemiprimeD1TensorNetwork.owner net.rows)\n      source (packetIndex net source i g e) i g).masks.items,item.tile  ≤  T)\n    (hbeta : ∀b∈beta,b  ≤  B)\n    (hslot : ∀endpoint∈(SemiprimeD1PacketTensorTables.prepare (SemiprimeD1TensorNetwork.owner net.rows)\n      source (packetIndex net source i g e) i g).endpoints,endpoint.slot.length  ≤  a)\n    (hedge : ∀endpoint∈(SemiprimeD1PacketTensorTables.prepare (SemiprimeD1TensorNetwork.owner net.rows)\n      source (packetIndex net source i g e) i g).endpoints,endpoint.edge.length  ≤  E) :\n    (SemiprimeD1ChildWordNetwork.rightOne net source i g ctx z t beta e).2  ≤ \n      rightClock ctx a A K P T B beta.length E\n        (SemiprimeD1PacketTensorTables.prepare (SemiprimeD1TensorNetwork.owner net.rows)\n          source (packetIndex net source i g e) i g).clock z.clock (graph net source i g).work e.val := by\n  let header := SemiprimeD1PacketTensorTables.prepare (SemiprimeD1TensorNetwork.owner net.rows)\n    source (packetIndex net source i g e) i g\n  let table := SemiprimeD1JetWordPacketTables.acquire header ctx z a i t beta\n  let ports := SemiprimeD1TensorNetwork.rightPorts\n    (SemiprimeD1TensorNetworkLayout.childRows (graph net source i g)) e\n  have htable := acquire_clock header ctx z hz a i t beta A K P T B E hA hK hmode htile hbeta hslot hedge\n  have hgood := SemiprimeD1JetWordPacketTables.acquire_good header ctx z a i t beta\n  have hcopy := copyTable_clock ports table.table\n  have hports : ports.length  ≤  A := (rightOne_degree net source i g e).le.trans hA\n  have hstorage:=SemiprimeD1ChildTableCopyTape.storage_le_cap ctx table.table hgood A hA\n  have hlookup:=Nat.add_le_add_right (SemiprimeD1ChildTableCopyTape.tapeBudget_mono hstorage) 7\n  have hpow : 2^ports.length  ≤  (2:ℕ)^A := Nat.pow_le_pow_right (by decide) hports\n  have hcopyCap : (SemiprimeD1ChildNetworkTape.copyTable ports table.table).2  ≤  (tapeBudget (tableCap ctx A)+7)*2^A :=\n    hcopy.trans (Nat.mul_le_mul hlookup hpow)\n  change table.clock+(graph net source i g).work+(SemiprimeD1ChildNetworkTape.copyTable ports table.table).2+ports.length+e.val+10  ≤  _\n  exact Nat.add_le_add_right (Nat.add_le_add_right (Nat.add_le_add\n    (Nat.add_le_add (Nat.add_le_add htable (le_refl _)) hcopyCap) hports) e.val) 10\n\nend RiemannGaussian.SemiprimeD1WordPacketTableClock\n","RiemannGaussian.SemiprimeD1WordTapeFrameBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1WordTapePhaseBudget\nimport RiemannGaussian.SemiprimeD1WordTapeRecursiveReport\n\n/-! # Actual word/tape frame budget from original local data\nThe new phase factory and actual tape leaf have their own reports. Only the\nunchanged physical recovery report is transported by literal block equality.\nThe envelope has no recursive solved-value or advised-cost input. Literal child\nconstructors remain explicit for their subsequent uniform resource substitution.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 600000\nnamespace RiemannGaussian.SemiprimeD1WordTapeFrameBudget\nopen SemiprimeD1JetAxes SemiprimeD1TensorNetwork SemiprimeD1RecursiveCounter\nopen SemiprimeD1RecursiveCallTree SemiprimeD1PhysicalRecursiveClock\nopen SemiprimeD1WordTapeRecursiveCounter SemiprimeD1WordTapeRecursiveReport\nopen SemiprimeD1WordTapePhaseBudget\nopen SemiprimeD1JetAffineCoefficient (JetRun)\nattribute [local irreducible] SemiprimeD1OriginalModeAcquisition.acquire\n\n/-- Actual-data local budget independent of recursive child solutions or fuel.\nRepeated child constructors/source/menu/header reports remain explicit. -/\ndef budget (s : ℕ) (parent : Call) : ℕ :=\n  let lam:=SemiprimeD1PackingReady.logarithm s\n  let M:=edgeCount parent.net\n  if activeTest s lam parent.depth M then\n    let a:=SemiprimeD1Schedule.exponent lam parent.depth\n    let u:=SemiprimeD1Schedule.levels lam parent.depth\n    let P:=SemiprimeD1ModeRate.workingPrecision M u a 0 parent.ctx.precision\n    (((List.finRange (SemiprimeD1WireKernelOriginal.size a)).map (phaseBudget parent a u)).sum)+\n      parent.ctx.rank*SemiprimeD1PhysicalRecoveryLocalBudget.budget a M parent.ctx.precision parent.ctx.rank P+\n      (SemiprimeD1RecoveryWeightRun.geometry a 0).work+\n      20*(s+lam+parent.depth+M+a+u+P+parent.ctx.rank+SemiprimeD1WireKernelOriginal.size a+1)\n  else (SemiprimeD1TensorTapeLeaf.leaf parent.ctx parent.net).clock+s+lam+parent.depth+M+8\n\n/-- Only unchanged physical recovery reports agree after literal block-cache\nrefinement. Changed word/tape phase acquisition clocks are excluded. -/\ntheorem recoveries_clock (next : Context → Network → JetRun) (parent : Call) (a u : ℕ)\n    (hp : parent.ctx.Positive) (hu : u  ≤  edgeCount parent.net) :\n    let P:=SemiprimeD1ModeRate.workingPrecision (edgeCount parent.net) u a 0 parent.ctx.precision\n    (((List.range parent.ctx.rank).map\n      (SemiprimeD1PhysicalRecursiveCounter.recoverCoordinate parent.ctx a (edgeCount parent.net) u P\n        (SemiprimeD1WordTapeRecursiveClock.retained next parent a u))).map CoordinateRun.clock).sum  ≤\n      parent.ctx.rank*SemiprimeD1PhysicalRecoveryLocalBudget.budget a (edgeCount parent.net)\n        parent.ctx.precision parent.ctx.rank P := by\n  dsimp only\n  let fs:=SemiprimeD1WordTapeRecursiveClock.retained next parent a u\n  let gs:=SemiprimeD1RecursiveRecovery.retained next parent.ctx parent.net a u\n  let P:=SemiprimeD1ModeRate.workingPrecision (edgeCount parent.net) u a 0 parent.ctx.precision\n  have hb : fs.map PhaseRun.blocks=gs.map PhaseRun.blocks := by\n    apply Array.toList_inj.mp\n    simp only [fs,gs,SemiprimeD1WordTapeRecursiveClock.retained,\n      SemiprimeD1RecursiveRecovery.retained,Array.toList_map,List.map_map,Function.comp_def]\n    apply List.map_congr_left\n    intro t ht\n    exact (SemiprimeD1WordTapeRecursivePhase.phase_data next next parent a u t hp hu\n      (fun _ _ _=>rfl)).1\n  have ho : (List.range parent.ctx.rank).map\n      (SemiprimeD1PhysicalRecursiveCounter.recoverCoordinate parent.ctx a (edgeCount parent.net) u P fs)=\n    (List.range parent.ctx.rank).map\n      (SemiprimeD1PhysicalRecursiveCounter.recoverCoordinate parent.ctx a (edgeCount parent.net) u P gs) := by\n    apply List.map_congr_left\n    intro k hk\n    exact recoverCoordinate_congr parent.ctx a (edgeCount parent.net) u P fs gs k hb\n  change (((List.range parent.ctx.rank).map\n    (SemiprimeD1PhysicalRecursiveCounter.recoverCoordinate parent.ctx a (edgeCount parent.net) u P fs)).map\n      CoordinateRun.clock).sum ≤ _\n  rw [ho]\n  exact SemiprimeD1PhysicalRecoveryLocalBudget.recoveries_clock next parent.ctx parent.net a u hu\n\n/-- The actual erased structural successor has an original-data local envelope;\nno source, child, shape, fit or callback-work supplier is a premise. -/\ntheorem frame_clock (s fuel : ℕ) (parent : Call) (hpos : parent.ctx.Positive) :\n    (frame s parent (eraseClock (SemiprimeD1WordTapeRecursiveCounter.run s fuel (parent.depth+1)))).clock  ≤\n      budget s parent := by\n  dsimp only [frame,budget]\n  split\n  · rename_i ha\n    let lam:=SemiprimeD1PackingReady.logarithm s\n    let a:=SemiprimeD1Schedule.exponent lam parent.depth\n    let u:=SemiprimeD1Schedule.levels lam parent.depth\n    let next:=eraseClock (SemiprimeD1WordTapeRecursiveCounter.run s fuel (parent.depth+1))\n    have hu : u  ≤  edgeCount parent.net := ((activeTest_correct _ _ _ _).mp ha).2.2\n    have hp : (((List.finRange (SemiprimeD1WireKernelOriginal.size a)).map\n        (SemiprimeD1WordTapeRecursivePhase.phase next parent.ctx parent.net a u)).map PhaseRun.clock).sum  ≤\n        ((List.finRange (SemiprimeD1WireKernelOriginal.size a)).map (phaseBudget parent a u)).sum := by\n      simp only [List.map_map,Function.comp_def]\n      apply List.sum_le_sum\n      intro t ht\n      exact phase_local_clock s fuel parent a u t hpos hu\n    have hr:=recoveries_clock next parent a u hpos hu\n    dsimp only at hr\n    change _+_+_+_  ≤  _+_+_+_\n    simp only [List.length_map,List.length_finRange]\n    exact Nat.add_le_add_right (Nat.add_le_add_right (Nat.add_le_add hp hr) _) _\n  · exact le_rfl\n\n/-- Local contribution is bounded only on the REAL remaining-fuel states.\nThe zero-fuel inactive-test premise is a schedule guard, not a leaf-size answer. -/\ntheorem localWork_bound (s fuel : ℕ) (parent : Call) (hpos : parent.ctx.Positive)\n    (hz : fuel=0 → activeTest s (SemiprimeD1PackingReady.logarithm s) parent.depth (edgeCount parent.net)=false) :\n    localWork s fuel parent  ≤  budget s parent := by\n  cases fuel with\n  | zero =>\n    simp only [localWork,budget,hz rfl,Bool.false_eq_true,ite_false]\n    omega\n  | succ fuel => exact frame_clock s fuel parent hpos\n\n/-- Actual successor report is bounded by its closed original-data local frame\nplus the actual recursive reports in the literal child inventory. -/\ntheorem run_clock (s fuel : ℕ) (parent : Call) (hpos : parent.ctx.Positive) :\n    (SemiprimeD1WordTapeRecursiveCounter.run s (fuel+1) parent.depth parent.ctx parent.net).clock  ≤\n      budget s parent+((children s parent).map (fun c =>\n        (SemiprimeD1WordTapeRecursiveCounter.run s fuel c.depth c.ctx c.net).clock)).sum := by\n  rw [SemiprimeD1WordTapeRecursiveReport.run_clock s fuel parent hpos]\n  exact Nat.add_le_add_right (frame_clock s fuel parent hpos) _\n\nend RiemannGaussian.SemiprimeD1WordTapeFrameBudget\n","RiemannGaussian.SemiprimeD1ZeroBoundaryTables":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1BooleanTreeStreamOriginal\nimport RiemannGaussian.SemiprimeD1StackPublicZeroOriginal\nimport RiemannGaussian.SemiprimeD1BooleanRootTablesOriginal\n/-! # One physical true bit and EOF acquire the entire original zero boundary\nAll tables and predicates below are mathematical specifications. The source\nwill supply only literal true and an actually acquired physical depth word.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 8192\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeD1ZeroBoundaryTables\nopen SemiprimeD1TensorTables SemiprimeBitArithmetic\nnamespace S\nexport SemiprimeD1BooleanTreeStream (table bytes words)\nend S\n/-- EOF produces a genuinely zero tensor at every remaining depth. -/\ntheorem nil_entry (n : ℕ) (input : Fin n→Bool) : valueAt (S.table n []) input=S.words false := by\n  induction n with\n  | zero=>rfl\n  | succ n ih=>\n    cases h:input 0 <;> simp only [S.table,List.drop_nil,valueAt,h,Bool.false_eq_true,ite_false,ite_true] <;>\n      exact ih (fun j=>input j.succ)\n/-- There is at least one leaf at every physical depth, including depth zero. -/\ntheorem singleton_drop (n : ℕ) : ([true]:List Bool).drop (2^n)=[] := by\n  apply List.drop_eq_nil_of_le\n  have h:0<(2:ℕ)^n:=by positivity\n  simp only [List.length_cons,List.length_nil]\n  omega\n/-- The one true stream entry accepts EXACTLY the original zero word, in the\noriginal first-port-outermost false-first order; every later entry is EOF-false. -/\ntheorem zero_entry (n : ℕ) (input : Fin n→Bool) :\n    valueAt (S.table n [true]) input=S.words (decide (bitValue (List.ofFn input)=0)) := by\n  induction n with\n  | zero=>rfl\n  | succ n ih=>\n    cases h:input 0\n    · simp only [S.table,valueAt,h,Bool.false_eq_true,ite_false]\n      rw [ih]\n      congr 1\n      apply decide_eq_decide.mpr\n      simp only [List.ofFn_succ,bitValue,h,bitNat,Bool.false_eq_true,ite_false,Nat.zero_add]\n      omega\n    · simp only [S.table,valueAt,h,ite_true,singleton_drop]\n      rw [nil_entry]\n      have hz : ¬bitValue (List.ofFn input)=0 := by\n        simp only [List.ofFn_succ,bitValue,h,bitNat,ite_true]\n        omega\n      simp only [hz,decide_false]\n/-- Original zero word means all original Boolean coordinates are false. -/\ntheorem zero_iff (n : ℕ) (input : Fin n→Bool) :\n    bitValue (List.ofFn input)=0 ↔ ∀j,input j=false := by\n  induction n with\n  | zero=>simp [bitValue]\n  | succ n ih=>\n    rw [Fin.forall_fin_succ]\n    cases h:input 0 <;> simp [List.ofFn_succ,bitValue,bitNat,h,←ih (fun j=>input j.succ)]\n/-- Finite literal table entries uniquely determine the complete typed tree. -/\ntheorem table_ext {n : ℕ} (a b : Table n) (h : ∀input,valueAt a input=valueAt b input) : a=b := by\n  induction a with\n  | leaf ws=>\n    cases b with\n    | leaf vs=>exact congrArg Table.leaf (h (fun j=>Fin.elim0 j))\n  | @fork n lo hi il ih=>\n    cases b with\n    | fork left right=>\n      apply congrArg₂ Table.fork\n      · apply il\n        intro input\n        simpa only [valueAt,Fin.cons_zero,Bool.false_eq_true,ite_false,Fin.cons_succ] using h (Fin.cons false input)\n      · apply ih\n        intro input\n        simpa only [valueAt,Fin.cons_zero,ite_true,Fin.cons_succ] using h (Fin.cons true input)\n/-- Whole old materialization is read in its exact original port order. -/\ntheorem build_entry (n : ℕ) (producer : List Bool→SemiprimeD1JetRingBits.Run) (input : Fin n→Bool) :\n    valueAt (build n producer).table input=(producer (List.ofFn input)).words := by\n  have h:=build_value n producer (List.ofFn input) (by simp)\n  rw [lookup_value _ _ (by simp)] at h\n  simpa only [List.getElem_ofFn] using h\n/-- The old original initial-carry verdict is precisely unsigned word zero,\nfor EVERY original ordered finite assignment, including all high-zero padding. -/\ntheorem initial_zero (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (input : Fin (SemiprimeMacroParameters.firstAxis (SemiprimeMacroParameters.bitLength (bitValue bits))*\n      SemiprimeMacroParameters.secondAxis (SemiprimeMacroParameters.bitLength (bitValue bits))+1)→Bool) :\n    (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN .carryInitial input).accepted=\n      decide (bitValue (List.ofFn input)=0) := by\n  have hz:=SemiprimeD1StackPublicZeroOriginal.initial_original bits hc hN input\n  change decide (bitValue (SemiprimeD1StackPublicZeroExecution.word bits (List.ofFn input))=0)=_ at hz\n  rw [SemiprimeD1StackPublicZeroOriginal.word_full bits (List.ofFn input) (by\n    rw [List.length_ofFn,SemiprimeD1StackPublicZeroOriginal.public_width bits hc])] at hz\n  exact hz.symm\n/-- The old original terminal-carry verdict has the SAME zero-word meaning. -/\ntheorem terminal_zero (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n    (input : Fin (SemiprimeMacroParameters.firstAxis (SemiprimeMacroParameters.bitLength (bitValue bits))*\n      SemiprimeMacroParameters.secondAxis (SemiprimeMacroParameters.bitLength (bitValue bits))+1)→Bool) :\n    (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN .carryTerminal input).accepted=\n      decide (bitValue (List.ofFn input)=0) := by\n  have hz:=SemiprimeD1StackPublicZeroOriginal.terminal_original bits hc hN input\n  change decide (bitValue (SemiprimeD1StackPublicZeroExecution.word bits (List.ofFn input))=0)=_ at hz\n  rw [SemiprimeD1StackPublicZeroOriginal.word_full bits (List.ofFn input) (by\n    rw [List.length_ofFn,SemiprimeD1StackPublicZeroOriginal.public_width bits hc])] at hz\n  exact hz.symm\n/-- ENTIRE original initial-carry tensor, exact false-first/port-outermost order;\nthe actual entry source is still only ONE true bit and physical EOF. -/\ntheorem initial_reference (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits) :\n    S.table (SemiprimeMacroParameters.firstAxis (SemiprimeMacroParameters.bitLength (bitValue bits))*\n      SemiprimeMacroParameters.secondAxis (SemiprimeMacroParameters.bitLength (bitValue bits))+1) [true]=\n      SemiprimeD1BooleanRootTablesOriginal.reference (bitValue bits) hN (.inl .carryInitial) := by\n  apply table_ext\n  intro input\n  rw [zero_entry]\n  dsimp only [SemiprimeD1BooleanRootTablesOriginal.reference,SemiprimeMacroGraph.subdividedArity,SemiprimeMacroGraph.arity]\n  rw [build_entry]\n  have hget : (fun j=>((List.ofFn input).toArray[j.val]?).getD false)=input := by\n    funext j\n    simp only [List.getElem?_toArray,List.getElem?_ofFn,j.isLt,dite_true,Option.getD_some]\n  change S.words (decide (bitValue (List.ofFn input)=0))=\n    S.words (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN .carryInitial\n      (fun j=>((List.ofFn input).toArray[j.val]?).getD false)).accepted\n  have he:=congrArg (fun f=>S.words (SemiprimeMacroEntryBitCheck.publicBitEntry\n    (bitValue bits) hN .carryInitial f).accepted) hget\n  exact (he.trans (congrArg S.words (initial_zero bits hc hN input))).symm\n/-- ENTIRE original terminal-carry tensor is the SAME acquired tree. -/\ntheorem terminal_reference (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits) :\n    S.table (SemiprimeMacroParameters.firstAxis (SemiprimeMacroParameters.bitLength (bitValue bits))*\n      SemiprimeMacroParameters.secondAxis (SemiprimeMacroParameters.bitLength (bitValue bits))+1) [true]=\n      SemiprimeD1BooleanRootTablesOriginal.reference (bitValue bits) hN (.inl .carryTerminal) := by\n  apply table_ext\n  intro input\n  rw [zero_entry]\n  dsimp only [SemiprimeD1BooleanRootTablesOriginal.reference,SemiprimeMacroGraph.subdividedArity,SemiprimeMacroGraph.arity]\n  rw [build_entry]\n  have hget : (fun j=>((List.ofFn input).toArray[j.val]?).getD false)=input := by\n    funext j\n    simp only [List.getElem?_toArray,List.getElem?_ofFn,j.isLt,dite_true,Option.getD_some]\n  change S.words (decide (bitValue (List.ofFn input)=0))=\n    S.words (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN .carryTerminal\n      (fun j=>((List.ofFn input).toArray[j.val]?).getD false)).accepted\n  have he:=congrArg (fun f=>S.words (SemiprimeMacroEntryBitCheck.publicBitEntry\n    (bitValue bits) hN .carryTerminal f).accepted) hget\n  exact (he.trans (congrArg S.words (terminal_zero bits hc hN input))).symm\n/-- The ACTUAL integral coefficient of EACH boundary entry is its original\nzero indicator, BEFORE any contraction/product or precision reduction. -/\ntheorem literal_entry_coefficient (n : ℕ) (input : Fin n→Bool) :\n    SemiprimeD1JetAlgebra.coefficient (SemiprimeD1JetBoxIndex.dims [])\n      (SemiprimeD1JetBoxIndex.exponent [] 0)\n      (SemiprimeD1JetBoxIndex.exponent_inBox [] 0 (by simp) (by decide))\n      (SemiprimeD1JetLiteralLift.literal [] (valueAt (S.table n [true]) input))=\n      if bitValue (List.ofFn input)=0 then 1 else 0 := by\n  rw [SemiprimeD1JetLiteralLift.literal_coefficient [] _ (by simp) 0 (by decide),zero_entry]\n  by_cases hz:bitValue (List.ofFn input)=0 <;>\n    simp [S.words,hz,bitValue,bitNat]\n\nend RiemannGaussian.SemiprimeD1ZeroBoundaryTables\n","RiemannGaussian.SemiprimeFibreAccumulatorHeight":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeCounterPacketHeight\n\n/-!\n# Explicit partial separated-fibre accumulators\n\nFinite local-localSets sets and label-localSets sets are expanded into actual loop\nrecords. Inactive groups have one dummy Boolean choice, not a multiplicity.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnoncomputable section\nnamespace RiemannGaussian.SemiprimeFibreAccumulatorHeight\nopen scoped BigOperators\nopen Polynomial\nopen SemiprimeCounterCompose SemiprimeCounterPacketHeight SemiprimeCounterSeparation\nopen SemiprimeCounterNative SemiprimeStreamingTensor SemiprimeJetArrayHeight\nattribute [local instance] Classical.propDecidable\n\nvariable {G Y : Type*} [Fintype G] [DecidableEq G] {L : G → Type*}\n\n/-- Actual localSets choices, with a sole dummy assignment for inactive groups. -/\ndef options (groups : Finset G) (localSets : (g : G) → Finset (L g → Bool))\n    (g : G) : Finset (L g → Bool) :=\n  if g ∈ groups then localSets g else {fun _ => false}\n\n/-- The actual gated local factor in the product-of-localSets-sums expansion. -/\ndef leaf (groups : Finset G) (gate : (g : G) → (L g → Bool) → Prop)\n    (value : (g : G) → (L g → Bool) → Polynomial ℚ)\n    (g : G) (a : L g → Bool) : Polynomial ℚ :=\n  if g ∈ groups then if gate g a then value g a else 0 else 1\n\n/-- Exact expansion of a partial product of partial local sums. -/\ntheorem partial_product_expansion (groups : Finset G)\n    (localSets : (g : G) → Finset (L g → Bool))\n    (gate : (g : G) → (L g → Bool) → Prop)\n    (value : (g : G) → (L g → Bool) → Polynomial ℚ) :\n    (∏ g ∈ groups, ∑ a ∈ localSets g, if gate g a then value g a else 0) =\n      ∑ a ∈ Fintype.piFinset (options groups localSets), ∏ g, leaf groups gate value g (a g) := by\n  have hlocal (g : G) :\n      (∑ a ∈ options groups localSets g, leaf groups gate value g a) =\n      if g ∈ groups then ∑ a ∈ localSets g, if gate g a then value g a else 0 else 1 := by\n    by_cases hg : g ∈ groups <;> simp [options, leaf, hg]\n  rw [← Finset.prod_univ_sum]\n  simp_rw [hlocal]\n  simp only [← Finset.prod_filter, Finset.filter_mem_eq_inter, Finset.univ_inter]\n\n/-- Literal zero-or-one weight of all selected local gates. -/\ndef gateWeight (groups : Finset G) (gate : (g : G) → (L g → Bool) → Prop)\n    (a : (g : G) → L g → Bool) : ℤ :=\n  if ∀ g ∈ groups, gate g (a g) then 1 else 0\n\n/-- Gating is factored as a literal 0/1 scalar before any sum cancellation. -/\ntheorem product_leaf (groups : Finset G)\n    (gate : (g : G) → (L g → Bool) → Prop)\n    (value : (g : G) → (L g → Bool) → Polynomial ℚ)\n    (a : (g : G) → L g → Bool) :\n    (∏ g, leaf groups gate value g (a g)) =\n      C (gateWeight groups gate a : ℚ) * ∏ g ∈ groups, value g (a g) := by\n  have hprod : (∏ g, leaf groups gate value g (a g)) =\n      ∏ g ∈ groups, if gate g (a g) then value g (a g) else 0 := by\n    simp only [leaf]\n    exact (Finset.prod_filter (fun g => g ∈ groups)\n      (fun g => if gate g (a g) then value g (a g) else 0)).symm.trans (by simp)\n  rw [hprod]\n  by_cases h : ∀ g ∈ groups, gate g (a g)\n  · simp only [gateWeight, ite_eq_left h, Int.cast_one, C_1, one_mul]\n    apply Finset.prod_congr rfl\n    intro g hg\n    rw [ite_eq_left (h g hg)]\n  · simp only [gateWeight, ite_eq_right h, Int.cast_zero, C_0, zero_mul]\n    push Not at h\n    obtain ⟨g, hg, hgate⟩ := h\n    exact Finset.prod_eq_zero hg (by simp only [ite_eq_right hgate])\n\n/-- Explicit prefix records: each label paired with its actual finite local choices. -/\ndef records (labels : Finset Y) (groups : Finset G)\n    (localSets : Y → (g : G) → Finset (L g → Bool)) :\n    Finset ((_y : Y) × ((g : G) → L g → Bool)) :=\n  labels.sigma (fun y => Fintype.piFinset (options groups (localSets y)))\n\n/-- A prefix record family never exceeds labels times all Boolean assignments. -/\ntheorem records_card_le [∀ g, Fintype (L g)] (labels : Finset Y) (groups : Finset G)\n    (localSets : Y → (g : G) → Finset (L g → Bool)) :\n    (records labels groups localSets).card ≤ labels.card * Fintype.card ((g : G) → L g → Bool) := by\n  rw [records, Finset.card_sigma]\n  calc\n    _ ≤ ∑ _y ∈ labels, Fintype.card ((g : G) → L g → Bool) :=\n      Finset.sum_le_sum (fun _ _ => Finset.card_le_univ _)\n    _ = _ := by simp\n\n/-- Full signed label-localSets expansion, with every selected local-localSets choice. -/\ntheorem accumulator_expansion (labels : Finset Y) (groups : Finset G)\n    (localSets : Y → (g : G) → Finset (L g → Bool))\n    (gate : Y → (g : G) → (L g → Bool) → Prop)\n    (value : Y → (g : G) → (L g → Bool) → Polynomial ℚ) (weight : Y → ℤ) :\n    (∑ y ∈ labels, C (weight y : ℚ) *\n      ∏ g ∈ groups, ∑ a ∈ localSets y g, if gate y g a then value y g a else 0) =\n      ∑ rec ∈ records labels groups localSets,\n        C ((weight rec.1 * gateWeight groups (gate rec.1) rec.2 : ℤ) : ℚ) *\n          ∏ g ∈ groups, value rec.1 g (rec.2 g) := by\n  simp_rw [partial_product_expansion, product_leaf]\n  simp only [records, Finset.sum_sigma, Finset.mul_sum, Int.cast_mul, C_mul, mul_assoc]\n\n/-- A selected product of fibre products is precisely the selected-factor product. -/\ntheorem prod_selected_fibres {E C : Type*} [Fintype E] [CommMonoid C]\n    (assigned : E → G) (groups : Finset G) (f : E → C) :\n    (∏ g ∈ groups, ∏ e ∈ Finset.univ.filter (fun e => assigned e=g), f e) =\n      ∏ e ∈ Finset.univ.filter (fun e => assigned e ∈ groups), f e := by\n  classical\n  have h := Fintype.prod_fiberwise assigned (fun e => if assigned e ∈ groups then f e else 1)\n  have hi (g : G) :\n      (∏ e : {e // assigned e=g}, if assigned e.val ∈ groups then f e.val else 1) =\n      if g ∈ groups then ∏ e ∈ Finset.univ.filter (fun e => assigned e=g), f e else 1 := by\n    have hr : ∀ e : {e // assigned e=g},\n        (if assigned e.val ∈ groups then f e.val else 1) = (if g ∈ groups then f e.val else 1) := by\n      intro e\n      rw [e.property]\n    simp_rw [hr]\n    by_cases hg : g ∈ groups\n    · simp only [ite_eq_left hg]\n      exact (Finset.prod_subtype (p := fun e => assigned e=g)\n        (Finset.univ.filter (fun e => assigned e=g)) (by intro e; simp) f).symm\n    · simp only [ite_eq_right hg, Finset.prod_const_one]\n  simp_rw [hi] at h\n  simpa only [← Finset.prod_filter, Finset.filter_mem_eq_inter, Finset.univ_inter] using h\n\nsection Native\nvariable {V E : Type} [Fintype V] [DecidableEq V] [Fintype E]\n\n/-- Actual full Boolean representative/update used by one group scan. -/\ndef state (arity : E → ℕ) (rows : (e : E) → Fin (arity e) → V → Polynomial ℚ)\n    (t : ℚ) (d : NodeCertificate arity (fun e i v => (rows e i v).eval t))\n    (label : (g : d.Group) → d.Summary g) (g : d.Group) (a : d.Local g → Bool) :\n    (g : d.Group) → d.Local g → Bool := Function.update (d.representative label) g a\n\n/-- Actual corrected local group value at its recorded representative/update. -/\ndef nativeValue (arity : E → ℕ) (Tentry : (e : E) → (Fin (arity e) → Bool) → ℤ)\n    (rows : (e : E) → Fin (arity e) → V → Polynomial ℚ) (t : ℚ) (R : ℕ)\n    (d : NodeCertificate arity (fun e i v => (rows e i v).eval t))\n    (label : (g : d.Group) → d.Summary g) (U : Finset V) (g : d.Group) (a : d.Local g → Bool) : Polynomial ℚ :=\n  groupValue arity (fun e b => (Tentry e b : ℚ)) d.assigned\n    (groupedRows arity (fun e i v => (rows e i v).eval t) d)\n    (nativeCorrection arity rows t R U) g (state arity rows t d label g a)\n\n/-- Factor-dependent Boolean bases retain each group's actual recorded update. -/\ndef nativeBase (arity : E → ℕ) (rows : (e : E) → Fin (arity e) → V → Polynomial ℚ)\n    (t : ℚ) (d : NodeCertificate arity (fun e i v => (rows e i v).eval t))\n    (label : (g : d.Group) → d.Summary g) (a : (g : d.Group) → d.Local g → Bool) (e : E) : Finset V :=\n  (splitAssignment d.grouping).symm (state arity rows t d label (d.assigned e) (a (d.assigned e)))\n\n/-- The actual partial group product is a masked native factor product with\nindependent recorded bases; no measurement or row-span cancellation is used. -/\ntheorem native_product_eq [DecidableEq E] (arity : E → ℕ)\n    (Tentry : (e : E) → (Fin (arity e) → Bool) → ℤ)\n    (rows : (e : E) → Fin (arity e) → V → Polynomial ℚ) (t : ℚ) (R : ℕ)\n    (d : NodeCertificate arity (fun e i v => (rows e i v).eval t)) (groups : Finset d.Group)\n    (label : (g : d.Group) → d.Summary g) (U : Finset V) (a : (g : d.Group) → d.Local g → Bool) :\n    (∏ g ∈ groups, nativeValue arity Tentry rows t R d label U g (a g)) =\n      nativeTerm arity (fun e b => if d.assigned e ∈ groups then Tentry e b else 1)\n        rows t R (nativeBase arity rows t d label a) U := by\n  let f := fun e => evaluate (arity e) (fun b => C (Tentry e b : ℚ))\n    (fun i => correctedPort (rows e i) t R (nativeBase arity rows t d label a e) U)\n  have hg (g : d.Group) : nativeValue arity Tentry rows t R d label U g (a g) =\n      ∏ e ∈ Finset.univ.filter (fun e => d.assigned e=g), f e := by\n    let x := (splitAssignment d.grouping).symm (state arity rows t d label g (a g))\n    have h := groupValue_corrected_product arity Tentry rows t R d g x U\n    simp only [x, Equiv.apply_symm_apply] at h\n    rw [nativeValue, h]\n    apply Finset.prod_congr rfl\n    intro e he\n    have heq := (Finset.mem_filter.mp he).2\n    dsimp only [f, nativeBase]\n    rw [heq]\n  simp_rw [hg]\n  rw [prod_selected_fibres]\n  have hmask := masked_nativeTerm (Finset.univ.filter (fun e => d.assigned e ∈ groups))\n    arity Tentry rows t R (nativeBase arity rows t d label a) U\n  simpa only [Finset.mem_filter, Finset.mem_univ, true_and, f] using hmask.symm\n\n/-- The literal measurement/forced-coordinate gate of the counter's local scan. -/\ndef nativeGate (arity : E → ℕ) (rows : (e : E) → Fin (arity e) → V → Polynomial ℚ)\n    (t : ℚ) (d : NodeCertificate arity (fun e i v => (rows e i v).eval t))\n    (label : (g : d.Group) → d.Summary g) (S : Finset V) (g : d.Group) (a : d.Local g → Bool) : Prop :=\n  d.measurement g a=label g ∧ localForced arity (fun e i v => (rows e i v).eval t) d S g a\n\n/-- Actual signed label-prefix/product-of-local-prefix-sums expression. -/\ndef nativeAccumulator (arity : E → ℕ)\n    (Tentry : (e : E) → (Fin (arity e) → Bool) → ℤ)\n    (rows : (e : E) → Fin (arity e) → V → Polynomial ℚ) (t : ℚ) (R : ℕ)\n    (d : NodeCertificate arity (fun e i v => (rows e i v).eval t))\n    (labels : Finset Y) (groups : Finset d.Group)\n    (localSets : Y → (g : d.Group) → Finset (d.Local g → Bool))\n    (label : Y → (g : d.Group) → d.Summary g) (forced correction : Y → Finset V) (weight : Y → ℤ) : Polynomial ℚ :=\n  ∑ y ∈ labels, C (weight y : ℚ) * ∏ g ∈ groups, ∑ a ∈ localSets y g,\n    if nativeGate arity rows t d (label y) (forced y) g a then\n      nativeValue arity Tentry rows t R d (label y) (correction y) g a else 0\n\nomit [Fintype E] in\n/-- Prefix records use no more than 2^n Boolean choices for each label. -/\ntheorem native_records_card (arity : E → ℕ)\n    (rows : (e : E) → Fin (arity e) → V → Polynomial ℚ) (t : ℚ)\n    (d : NodeCertificate arity (fun e i v => (rows e i v).eval t))\n    (labels : Finset Y) (groups : Finset d.Group)\n    (localSets : Y → (g : d.Group) → Finset (d.Local g → Bool)) :\n    (records labels groups localSets).card ≤ labels.card * 2^Fintype.card V := by\n  have hc : Fintype.card ((g : d.Group) → d.Local g → Bool) = 2^Fintype.card V := by\n    calc\n      _ = Fintype.card (Finset V) := (Fintype.card_congr (splitAssignment d.grouping)).symm\n      _ = _ := by simp\n  simpa only [hc] using records_card_le labels groups localSets\n\n/-- The actual partial accumulator expands to 0/1-gated selected native terms. -/\ntheorem nativeAccumulator_expansion [DecidableEq E] (arity : E → ℕ)\n    (Tentry : (e : E) → (Fin (arity e) → Bool) → ℤ)\n    (rows : (e : E) → Fin (arity e) → V → Polynomial ℚ) (t : ℚ) (R : ℕ)\n    (d : NodeCertificate arity (fun e i v => (rows e i v).eval t))\n    (labels : Finset Y) (groups : Finset d.Group)\n    (localSets : Y → (g : d.Group) → Finset (d.Local g → Bool))\n    (label : Y → (g : d.Group) → d.Summary g) (forced correction : Y → Finset V) (weight : Y → ℤ) :\n    nativeAccumulator arity Tentry rows t R d labels groups localSets label forced correction weight =\n      ∑ rec ∈ records labels groups localSets,\n        C ((weight rec.1*gateWeight groups\n          (nativeGate arity rows t d (label rec.1) (forced rec.1)) rec.2 : ℤ) : ℚ) *\n        nativeTerm arity (fun e b => if d.assigned e ∈ groups then Tentry e b else 1)\n          rows t R (nativeBase arity rows t d (label rec.1) rec.2) (correction rec.1) := by\n  unfold nativeAccumulator\n  rw [accumulator_expansion]\n  simp_rw [native_product_eq]\n\n/-- Actual partial summary/fibre accumulators have one original-incidence\npower denominator, with every label and local-prefix record counted. -/\ntheorem built_accumulator_representation [DecidableEq E] (arity : E → ℕ)\n    (Tentry : (e : E) → (Fin (arity e) → Bool) → ℤ)\n    {r Q : ℕ} (owner : ((e : E) × Fin (arity e)) → V)\n    (en : SemiprimeSourceLayout.Enumerations ((e : E) × Fin (arity e)) V E r Q)\n    (ε : ℚ) (R B T J : ℕ) (hJ : 1 ≤ J)\n    (howner : ∀ v, (Finset.univ.filter (fun i => owner i = v)).card ≤ B)\n    (hQ : 1 ≤ Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R ≤ Q)\n    (hentry : ∀ e a, |Tentry e a| ≤ 1) (t : ℤ) (ht : |t| ≤ (T : ℤ))\n    (d : NodeCertificate arity (fun e i v => ((builtRows arity owner en ε R) e i v).eval (t : ℚ)))\n    (labels : Finset Y) (groups : Finset d.Group)\n    (localSets : Y → (g : d.Group) → Finset (d.Local g → Bool))\n    (label : Y → (g : d.Group) → d.Summary g) (forced correction : Y → Finset V)\n    (weight : Y → ℤ) (hw : ∀ y ∈ labels, |weight y| ≤ 1) (k : ℕ) (hk : k < J) :\n    Representation ((nativeAccumulator arity Tentry (builtRows arity owner en ε R) (t : ℚ) R d\n      labels groups localSets label forced correction weight).coeff k)\n      ((SemiprimeSourceRowHeight.rowDenominator Q R)^(∑ e, arity e))\n      (labels.card*2^Fintype.card V*termBound (V := V) arity\n        (SemiprimeSourceRowHeight.rowDenominator Q R) R (B*2^SemiprimeSourceRowHeight.rowNumeratorExponent Q R) T J) := by\n  rw [nativeAccumulator_expansion]\n  have hmask : ∀ e b, |(if d.assigned e ∈ groups then Tentry e b else 1 : ℤ)| ≤ 1 := by\n    intro e b\n    split_ifs\n    · exact hentry e b\n    · norm_num\n  have hweight : ∀ rec ∈ records labels groups localSets,\n      |weight rec.1*gateWeight groups\n        (nativeGate arity (builtRows arity owner en ε R) (t : ℚ) d (label rec.1) (forced rec.1)) rec.2| ≤ 1 := by\n    intro rec hr\n    have hy := (Finset.mem_sigma.mp hr).1\n    have hg : |gateWeight groups\n        (nativeGate arity (builtRows arity owner en ε R) (t : ℚ) d (label rec.1) (forced rec.1)) rec.2| ≤ 1 := by\n      unfold gateWeight\n      split_ifs <;> norm_num\n    rw [abs_mul]\n    exact (mul_le_mul (hw rec.1 hy) hg (abs_nonneg _) (by norm_num)).trans_eq (by norm_num)\n  have h := built_signed_terms_representation (records labels groups localSets) arity\n    (fun e b => if d.assigned e ∈ groups then Tentry e b else 1) owner en ε R B T J hJ\n    howner hQ hAQ hmask t ht\n    (fun rec => nativeBase arity (builtRows arity owner en ε R) (t : ℚ) d (label rec.1) rec.2)\n    (fun rec => correction rec.1)\n    (fun rec => weight rec.1*gateWeight groups\n      (nativeGate arity (builtRows arity owner en ε R) (t : ℚ) d (label rec.1) (forced rec.1)) rec.2)\n    hweight k hk\n  apply representation_mono h\n  exact Nat.mul_le_mul_right _ (native_records_card arity (builtRows arity owner en ε R) (t : ℚ) d labels groups localSets)\n\n/-- Different label records may stop at different group/local prefixes. This\nincludes all completed records and the currently unfinished nested-loop record. -/\ntheorem built_varying_accumulator_representation [DecidableEq E] (arity : E → ℕ)\n    (Tentry : (e : E) → (Fin (arity e) → Bool) → ℤ)\n    {r Q : ℕ} (owner : ((e : E) × Fin (arity e)) → V)\n    (en : SemiprimeSourceLayout.Enumerations ((e : E) × Fin (arity e)) V E r Q)\n    (ε : ℚ) (R B T J : ℕ) (hJ : 1 ≤ J)\n    (howner : ∀ v, (Finset.univ.filter (fun i => owner i = v)).card ≤ B)\n    (hQ : 1 ≤ Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R ≤ Q)\n    (hentry : ∀ e a, |Tentry e a| ≤ 1) (t : ℤ) (ht : |t| ≤ (T : ℤ))\n    (d : NodeCertificate arity (fun e i v => ((builtRows arity owner en ε R) e i v).eval (t : ℚ)))\n    (labels : Finset Y) (groups : Y → Finset d.Group)\n    (localSets : Y → (g : d.Group) → Finset (d.Local g → Bool))\n    (label : Y → (g : d.Group) → d.Summary g) (forced correction : Y → Finset V)\n    (weight : Y → ℤ) (hw : ∀ y ∈ labels, |weight y| ≤ 1) (k : ℕ) (hk : k < J) :\n    Representation ((∑ y ∈ labels, C (weight y : ℚ) * ∏ g ∈ groups y, ∑ a ∈ localSets y g,\n      if nativeGate arity (builtRows arity owner en ε R) (t : ℚ) d (label y) (forced y) g a then\n        nativeValue arity Tentry (builtRows arity owner en ε R) (t : ℚ) R d (label y) (correction y) g a else 0).coeff k)\n      ((SemiprimeSourceRowHeight.rowDenominator Q R)^(∑ e, arity e))\n      (labels.card*2^Fintype.card V*termBound (V := V) arity\n        (SemiprimeSourceRowHeight.rowDenominator Q R) R (B*2^SemiprimeSourceRowHeight.rowNumeratorExponent Q R) T J) := by\n  rw [Polynomial.finsetSum_coeff]\n  have h := representation_sum labels\n    (fun y => (C (weight y : ℚ) * ∏ g ∈ groups y, ∑ a ∈ localSets y g,\n      if nativeGate arity (builtRows arity owner en ε R) (t : ℚ) d (label y) (forced y) g a then\n        nativeValue arity Tentry (builtRows arity owner en ε R) (t : ℚ) R d (label y) (correction y) g a else 0).coeff k)\n    ((SemiprimeSourceRowHeight.rowDenominator Q R)^(∑ e, arity e))\n    (2^Fintype.card V*termBound (V := V) arity (SemiprimeSourceRowHeight.rowDenominator Q R) R\n      (B*2^SemiprimeSourceRowHeight.rowNumeratorExponent Q R) T J) (by\n        intro y hy\n        have hh := built_accumulator_representation arity Tentry owner en ε R B T J hJ howner hQ hAQ\n          hentry t ht d {y} (groups y) localSets label forced correction weight (by\n            intro z hz\n            have he : z=y := Finset.mem_singleton.mp hz\n            subst z\n            exact hw y hy) k hk\n        simpa only [nativeAccumulator, Finset.sum_singleton, Finset.card_singleton, one_mul] using hh)\n  convert h using 1\n  ring\n\n/-- Record-dependent constant-one factor masks also cover unfinished local\nfactor products without changing the original scopes or incidence denominator. -/\ntheorem built_recordwise_accumulator_representation [DecidableEq E] (arity : E → ℕ)\n    (Tentry : Y → (e : E) → (Fin (arity e) → Bool) → ℤ)\n    {r Q : ℕ} (owner : ((e : E) × Fin (arity e)) → V)\n    (en : SemiprimeSourceLayout.Enumerations ((e : E) × Fin (arity e)) V E r Q)\n    (ε : ℚ) (R B T J : ℕ) (hJ : 1 ≤ J)\n    (howner : ∀ v, (Finset.univ.filter (fun i => owner i = v)).card ≤ B)\n    (hQ : 1 ≤ Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R ≤ Q)\n    (t : ℤ) (ht : |t| ≤ (T : ℤ))\n    (d : NodeCertificate arity (fun e i v => ((builtRows arity owner en ε R) e i v).eval (t : ℚ)))\n    (labels : Finset Y) (hentry : ∀ y ∈ labels, ∀ e a, |Tentry y e a| ≤ 1)\n    (groups : Y → Finset d.Group)\n    (localSets : Y → (g : d.Group) → Finset (d.Local g → Bool))\n    (label : Y → (g : d.Group) → d.Summary g) (forced correction : Y → Finset V)\n    (weight : Y → ℤ) (hw : ∀ y ∈ labels, |weight y| ≤ 1) (k : ℕ) (hk : k < J) :\n    Representation ((∑ y ∈ labels, C (weight y : ℚ) * ∏ g ∈ groups y, ∑ a ∈ localSets y g,\n      if nativeGate arity (builtRows arity owner en ε R) (t : ℚ) d (label y) (forced y) g a then\n        nativeValue arity (Tentry y) (builtRows arity owner en ε R) (t : ℚ) R d (label y) (correction y) g a else 0).coeff k)\n      ((SemiprimeSourceRowHeight.rowDenominator Q R)^(∑ e, arity e))\n      (labels.card*2^Fintype.card V*termBound (V := V) arity\n        (SemiprimeSourceRowHeight.rowDenominator Q R) R (B*2^SemiprimeSourceRowHeight.rowNumeratorExponent Q R) T J) := by\n  rw [Polynomial.finsetSum_coeff]\n  have h := representation_sum labels\n    (fun y => (C (weight y : ℚ) * ∏ g ∈ groups y, ∑ a ∈ localSets y g,\n      if nativeGate arity (builtRows arity owner en ε R) (t : ℚ) d (label y) (forced y) g a then\n        nativeValue arity (Tentry y) (builtRows arity owner en ε R) (t : ℚ) R d (label y) (correction y) g a else 0).coeff k)\n    ((SemiprimeSourceRowHeight.rowDenominator Q R)^(∑ e, arity e))\n    (2^Fintype.card V*termBound (V := V) arity (SemiprimeSourceRowHeight.rowDenominator Q R) R\n      (B*2^SemiprimeSourceRowHeight.rowNumeratorExponent Q R) T J) (by\n        intro y hy\n        have hh := built_accumulator_representation arity (Tentry y) owner en ε R B T J hJ howner hQ hAQ\n          (hentry y hy) t ht d {y} (groups y) localSets label forced correction weight (by\n            intro z hz\n            have he : z=y := Finset.mem_singleton.mp hz\n            subst z\n            exact hw y hy) k hk\n        simpa only [nativeAccumulator, Finset.sum_singleton, Finset.card_singleton, one_mul] using hh)\n  convert h using 1\n  ring\n\nend Native\n\nend RiemannGaussian.SemiprimeFibreAccumulatorHeight\n\n#print axioms RiemannGaussian.SemiprimeFibreAccumulatorHeight.built_accumulator_representation\n#print axioms RiemannGaussian.SemiprimeFibreAccumulatorHeight.built_varying_accumulator_representation\n\n#print axioms RiemannGaussian.SemiprimeFibreAccumulatorHeight.built_recordwise_accumulator_representation\n","RiemannGaussian.SemiprimeFibreArrayExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeArrayOps\nimport RiemannGaussian.SemiprimeRepresentativeExecution\nimport RiemannGaussian.SemiprimeCounterEnumeration\n\n/-!\n# Executed array traversals for separated counter packets\n\nThese routines execute truncated-array operations and retain callback work.\nTheir polynomial specifications are proofs, not runtime polynomial suppliers.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeFibreArrayExecution\nopen scoped BigOperators\nopen Polynomial SemiprimeJetArray SemiprimeArrayOps\nopen SemiprimeRepresentativeExecution\n\n/-- A concrete jet result, charged arithmetic/reads, and array/control charges. -/\nstructure Run where\n  /-- Actual cached array and its arithmetic/access report. -/\n  jet : InverseReport\n  /-- Additional allocation and finite-loop control charges. -/\n  control : ℕ\n\n/-- Combined operation ledger; integer/rational bit costs are separate. -/\ndef Run.work (r : Run) : ℕ := r.jet.arithmetic + r.jet.reads + r.control\n\n/-- Low coefficients of an actual array represent the specified polynomial. -/\ndef Spec (J : ℕ) (r : Run) (P : Polynomial ℚ) : Prop :=\n  ∀ i < J, coefficient r.jet.coefficients i = P.coeff i\n\n/-- Allocate a zero array with its finite allocation charge. -/\ndef zeroRun (J : ℕ) : Run := ⟨zeroJet J,J+1⟩\n/-- Allocate the truncated constant-one array with its allocation charge. -/\ndef oneRun (J : ℕ) : Run := ⟨oneJet J,J+1⟩\n\n/-- Both callback reports are included when their actual arrays are added. -/\ndef addRun (J : ℕ) (a b : Run) : Run :=\n  let out := addJet a.jet.coefficients b.jet.coefficients J\n  ⟨⟨out.coefficients,a.jet.arithmetic+b.jet.arithmetic+out.arithmetic,\n      a.jet.reads+b.jet.reads+out.reads⟩,a.control+b.control+J+1⟩\n\n/-- Both callback reports are included in the actual cached multiplication. -/\ndef mulRun (J : ℕ) (a b : Run) : Run :=\n  let out := multiply a.jet.coefficients b.jet.coefficients J\n  ⟨⟨out.coefficients,a.jet.arithmetic+b.jet.arithmetic+out.arithmetic,\n      a.jet.reads+b.jet.reads+out.reads⟩,a.control+b.control+J+1⟩\n\n/-- Actual scaling also retains the work acquiring the input array. -/\ndef scaleRun (J : ℕ) (a : Run) (c : ℚ) : Run :=\n  let out := scaleJet a.jet.coefficients c J\n  ⟨⟨out.coefficients,a.jet.arithmetic+out.arithmetic,a.jet.reads+out.reads⟩,\n    a.control+J+1⟩\n\ntheorem zeroRun_spec (J : ℕ) : Spec J (zeroRun J) 0 := by\n  intro i hi\n  exact (zeroJet_coefficient J i).trans (coeff_zero i).symm\n\ntheorem oneRun_spec (J : ℕ) : Spec J (oneRun J) 1 := by\n  intro i hi\n  change coefficient (oneJet J).coefficients i = (1 : Polynomial ℚ).coeff i\n  rw [oneJet_coefficient J i hi,coeff_one]\n\ntheorem addRun_spec (J : ℕ) (a b : Run) (P Q : Polynomial ℚ)\n    (ha : Spec J a P) (hb : Spec J b Q) : Spec J (addRun J a b) (P+Q) := by\n  intro i hi\n  change coefficient (addJet a.jet.coefficients b.jet.coefficients J).coefficients i = _\n  rw [addJet_coefficient _ _ _ _ hi,ha i hi,hb i hi,coeff_add]\n\ntheorem mulRun_spec (J : ℕ) (a b : Run) (P Q : Polynomial ℚ)\n    (ha : Spec J a P) (hb : Spec J b Q) : Spec J (mulRun J a b) (P*Q) :=\n  specification_of_asPolynomial _ _ _ (multiply_correct _ _ J P Q ha hb)\n\ntheorem scaleRun_spec (J : ℕ) (a : Run) (c : ℚ) (P : Polynomial ℚ)\n    (ha : Spec J a P) : Spec J (scaleRun J a c) (C c*P) := by\n  intro i hi\n  change coefficient (scaleJet a.jet.coefficients c J).coefficients i = _\n  rw [scaleJet_coefficient _ _ _ _ hi,ha i hi,coeff_C_mul]\n\ntheorem addRun_work (J : ℕ) (a b : Run) :\n    (addRun J a b).work = a.work+b.work+(4*J+1) := by\n  simp only [Run.work,addRun,addJet]\n  omega\n\ntheorem mulRun_work (J : ℕ) (a b : Run) :\n    (mulRun J a b).work = a.work+b.work+(2*J*(J+1)+J+1) := by\n  simp only [Run.work,mulRun,(multiply_work _ _ _).1,(multiply_work _ _ _).2]\n  ring\n\ntheorem scaleRun_work (J : ℕ) (a : Run) (c : ℚ) :\n    (scaleRun J a c).work = a.work+(3*J+1) := by\n  simp only [Run.work,scaleRun,scaleJet]\n  omega\n\n/-- Sum actual callback arrays over Boolean words, without a truth-table list. -/\ndef sumBits (J : ℕ) : (n : ℕ) → ((Fin n → Bool) → Run) → Run\n  | 0, f => f Fin.elim0\n  | n+1, f => addRun J (sumBits J n (fun x => f (Fin.cons false x)))\n      (sumBits J n (fun x => f (Fin.cons true x)))\n\n/-- All low coefficients of the binary array traversal are the literal finite sum. -/\ntheorem sumBits_spec (J n : ℕ) (f : (Fin n → Bool) → Run)\n    (P : (Fin n → Bool) → Polynomial ℚ) (hf : ∀ x, Spec J (f x) (P x)) :\n    Spec J (sumBits J n f) (∑ x, P x) := by\n  classical\n  induction n with\n  | zero =>\n    have he : (∑ x : Fin 0 → Bool, P x) = P Fin.elim0 := by\n      rw [Fintype.sum_unique]\n      congr 1\n    exact he.symm ▸ hf Fin.elim0\n  | succ n ih =>\n    have h := addRun_spec J _ _ _ _\n      (ih (fun x => f (Fin.cons false x)) (fun x => P (Fin.cons false x)) (fun x => hf _))\n      (ih (fun x => f (Fin.cons true x)) (fun x => P (Fin.cons true x)) (fun x => hf _))\n    rw [← (Fin.consEquiv (fun _ : Fin (n+1) => Bool)).sum_comp,\n      Fintype.sum_prod_type,Fintype.sum_bool]\n    change Spec J (addRun J _ _)\n      ((∑ x, P (Fin.cons true x)) + ∑ x, P (Fin.cons false x))\n    rw [add_comm (∑ x, P (Fin.cons true x)) (∑ x, P (Fin.cons false x))]\n    exact h\n\n/-- Callback work is multiplied only by the actual local Boolean scan size. -/\ntheorem sumBits_work (J n B : ℕ) (f : (Fin n → Bool) → Run)\n    (hf : ∀ x, (f x).work ≤ B) :\n    (sumBits J n f).work + (4*J+1) ≤ 2^n*(B+(4*J+1)) := by\n  induction n with\n  | zero => simpa only [sumBits,pow_zero,one_mul] using Nat.add_le_add_right (hf Fin.elim0) _\n  | succ n ih =>\n    have hl := ih (fun x => f (Fin.cons false x)) (fun x => hf _)\n    have hr := ih (fun x => f (Fin.cons true x)) (fun x => hf _)\n    rw [sumBits,addRun_work,pow_succ]\n    nlinarith\n\n/-- A finite factor/group product retains one recursive suffix and one callback. -/\ndef productList {A : Type} (J : ℕ) : List A → (A → Run) → Run\n  | [], _ => oneRun J\n  | a::tail, f => mulRun J (f a) (productList J tail f)\n\ntheorem productList_spec {A : Type} (J : ℕ) (xs : List A) (f : A → Run)\n    (P : A → Polynomial ℚ) (hf : ∀ x ∈ xs, Spec J (f x) (P x)) :\n    Spec J (productList J xs f) ((xs.map P).prod) := by\n  induction xs with\n  | nil => exact oneRun_spec J\n  | cons a tail ih =>\n    exact mulRun_spec J _ _ _ _ (hf a (by simp))\n      (ih (fun x hx => hf x (by simp [hx])))\n\ntheorem productList_work {A : Type} (J B : ℕ) (xs : List A) (f : A → Run)\n    (hf : ∀ x ∈ xs, (f x).work ≤ B) :\n    (productList J xs f).work ≤ xs.length*(B+(2*J*(J+1)+J+1))+(J+1) := by\n  induction xs with\n  | nil => simp [productList,oneRun,Run.work,oneJet]\n  | cons a tail ih =>\n    have hh := hf a (by simp)\n    have ht := ih (fun x hx => hf x (by simp [hx]))\n    rw [productList,mulRun_work,List.length_cons]\n    nlinarith\n\n/-- Tail-recursive range sum: only the current array accumulator is passed onward. -/\ndef sumFrom (J : ℕ) (f : ℕ → Run) : ℕ → ℕ → Run → Run\n  | 0, _, acc => acc\n  | fuel+1, start, acc => sumFrom J f fuel (start+1) (addRun J acc (f start))\n\ntheorem sumFrom_spec (J fuel start : ℕ) (f : ℕ → Run) (P : ℕ → Polynomial ℚ)\n    (acc : Run) (A : Polynomial ℚ) (ha : Spec J acc A)\n    (hf : ∀ i, start ≤ i → i < start+fuel → Spec J (f i) (P i)) :\n    Spec J (sumFrom J f fuel start acc) (A+∑ i ∈ Finset.range fuel, P (start+i)) := by\n  induction fuel generalizing start acc A with\n  | zero => simpa [sumFrom] using ha\n  | succ fuel ih =>\n    have h := ih (start+1) (addRun J acc (f start)) (A+P start)\n      (addRun_spec J acc (f start) A (P start) ha (hf start (by omega) (by omega)))\n      (fun i hi hj => hf i (by omega) (by omega))\n    simpa only [sumFrom,Finset.sum_range_succ',Nat.add_zero,Nat.add_assoc,\n      Nat.add_comm 1,add_assoc,add_comm (P start)] using h\n\ntheorem sumFrom_work (J fuel start B : ℕ) (f : ℕ → Run) (acc : Run)\n    (hf : ∀ i, start ≤ i → i < start+fuel → (f i).work ≤ B) :\n    (sumFrom J f fuel start acc).work ≤ acc.work+fuel*(B+(4*J+1)) := by\n  induction fuel generalizing start acc with\n  | zero => simp [sumFrom]\n  | succ fuel ih =>\n    have hh := hf start (by omega) (by omega)\n    have ht := ih (start+1) (addRun J acc (f start)) (fun i hi hj => hf i (by omega) (by omega))\n    rw [addRun_work] at ht\n    change (sumFrom J f fuel (start+1) (addRun J acc (f start))).work ≤ _\n    nlinarith\n\n/-- Gate the actual callback, including the cost of a rejected local word. -/\ndef gateRun (J : ℕ) (test : TestReport) (body : Unit → Run) : Run :=\n  if test.accepted then\n    let result := body ()\n    ⟨result.jet,result.control+test.work+1⟩\n  else\n    let result := zeroRun J\n    ⟨result.jet,result.control+test.work+1⟩\n\ntheorem gateRun_spec (J : ℕ) (test : TestReport) (body : Unit → Run)\n    (P : Polynomial ℚ) (hbody : Spec J (body ()) P) :\n    Spec J (gateRun J test body) (if test.accepted then P else 0) := by\n  cases ht : test.accepted\n  · simpa only [gateRun,ht,Bool.false_eq_true,ite_false,Spec] using zeroRun_spec J\n  · simpa only [gateRun,ht,ite_true,Spec] using hbody\n\ntheorem gateRun_work (J B : ℕ) (test : TestReport) (body : Unit → Run)\n    (hb : (body ()).work ≤ B) :\n    (gateRun J test body).work ≤ test.work+B+J+2 := by\n  cases ht : test.accepted <;> simp only [gateRun,ht,Bool.false_eq_true,ite_false,ite_true,\n    Run.work,zeroRun,zeroJet] at * <;> omega\n\n/-- Literal measurement AND forced-bit gate, with both actual test reports. -/\ndef fibreTest (n m : ℕ) (rows : Fin m → Fin n → ℤ) (target : Fin m → ℤ)\n    (forced bits : Fin n → Bool) : TestReport :=\n  let measured := measurementTest n m rows target bits\n  let fixed := forcedTest n forced bits\n  ⟨measured.accepted && fixed.accepted,measured.work+fixed.work+1⟩\n\ntheorem fibreTest_correct (n m : ℕ) (rows : Fin m → Fin n → ℤ) (target : Fin m → ℤ)\n    (forced bits : Fin n → Bool) :\n    (fibreTest n m rows target forced bits).accepted = true ↔\n      (∀ j, (∑ i, if bits i then rows j i else 0) = target j) ∧\n        (∀ i, forced i = true → bits i = true) := by\n  simp only [fibreTest,Bool.and_eq_true,measurementTest_correct,forcedTest_correct]\n\ntheorem fibreTest_work (n m : ℕ) (rows : Fin m → Fin n → ℤ) (target : Fin m → ℤ)\n    (forced bits : Fin n → Bool) :\n    (fibreTest n m rows target forced bits).work = m*(4*n+3)+4*n+3 := by\n  simp only [fibreTest,measurementTest_work,forcedTest_work]\n  omega\n\n/-- One group's fibre is scanned directly; no fibre list is constructed. -/\ndef scanGroup (J n m : ℕ) (rows : Fin m → Fin n → ℤ) (target : Fin m → ℤ)\n    (forced : Fin n → Bool) (value : (Fin n → Bool) → Run) : Run :=\n  sumBits J n (fun bits => gateRun J (fibreTest n m rows target forced bits) (fun _ => value bits))\n\ntheorem scanGroup_spec (J n m : ℕ) (rows : Fin m → Fin n → ℤ) (target : Fin m → ℤ)\n    (forced : Fin n → Bool) (value : (Fin n → Bool) → Run)\n    (P : (Fin n → Bool) → Polynomial ℚ) (hv : ∀ bits, Spec J (value bits) (P bits)) :\n    Spec J (scanGroup J n m rows target forced value)\n      (∑ bits, if (∀ j, (∑ i, if bits i then rows j i else 0) = target j) ∧\n          (∀ i, forced i = true → bits i = true) then P bits else 0) := by\n  classical\n  have h := sumBits_spec J n _ _ (fun bits => gateRun_spec J\n    (fibreTest n m rows target forced bits) (fun _ => value bits) (P bits) (hv bits))\n  simpa only [scanGroup,fibreTest_correct] using h\n\ntheorem scanGroup_work (J n m B : ℕ) (rows : Fin m → Fin n → ℤ) (target : Fin m → ℤ)\n    (forced : Fin n → Bool) (value : (Fin n → Bool) → Run)\n    (hv : ∀ bits, (value bits).work ≤ B) :\n    (scanGroup J n m rows target forced value).work ≤\n      2^n*(B+m*(4*n+3)+4*n+5*J+6) := by\n  have hg (bits : Fin n → Bool) := gateRun_work J B\n    (fibreTest n m rows target forced bits) (fun _ => value bits) (hv bits)\n  simp only [fibreTest_work] at hg\n  have hs := sumBits_work J n (m*(4*n+3)+4*n+3+B+J+2) _ hg\n  change (sumBits J n _).work ≤ _\n  nlinarith\n\n/-- One concrete signed-box tuple; representatives are acquired once, then groups\nare scanned separately and their actual arrays multiplied. -/\ndef fibreAt (J r : ℕ) (h m W : Fin r → ℕ)\n    (rows : (g : Fin r) → Fin (m g) → Fin (h g) → ℤ)\n    (y : (g : Fin r) → SemiprimeLayoutCertificates.Summary (Fin (h g)) (Fin (m g)) (W g))\n    (forced : (g : Fin r) → Fin (h g) → Bool)\n    (value : (g : Fin r) → ((k : Fin r) → Fin (h k) → Bool) → Run) : Run :=\n  let reps := acquireRepresentatives r h m W rows y\n  let result := productList J (List.ofFn (fun g : Fin r => g)) (fun g =>\n    scanGroup J (h g) (m g) (rows g) (summaryTarget (h g) (m g) (W g) (y g)) (forced g)\n      (fun bits => value g (Function.update reps.words g bits)))\n  ⟨result.jet,result.control+reps.work+1⟩\n\n/-- Its exact value is the finite product of native forced measurement fibres.\nThe callback specification is local; no whole-fibre count or H value is supplied. -/\ntheorem fibreAt_spec (J r : ℕ) (h m W : Fin r → ℕ)\n    (rows : (g : Fin r) → Fin (m g) → Fin (h g) → ℤ)\n    (y : (g : Fin r) → SemiprimeLayoutCertificates.Summary (Fin (h g)) (Fin (m g)) (W g))\n    (forced : (g : Fin r) → Fin (h g) → Bool)\n    (value : (g : Fin r) → ((k : Fin r) → Fin (h k) → Bool) → Run)\n    (P : (g : Fin r) → ((k : Fin r) → Fin (h k) → Bool) → Polynomial ℚ)\n    (hv : ∀ g x, Spec J (value g x) (P g x)) :\n    Spec J (fibreAt J r h m W rows y forced value)\n      (∏ g, ∑ bits : Fin (h g) → Bool,\n        if (∀ j, (∑ i, if bits i then rows g j i else 0) =\n              summaryTarget (h g) (m g) (W g) (y g) j) ∧\n            (∀ i, forced g i = true → bits i = true)\n        then P g (Function.update\n          (fun k => summaryRepresentative (h k) (m k) (W k) (rows k) (y k)) g bits)\n        else 0) := by\n  classical\n  have hreps : (acquireRepresentatives r h m W rows y).words =\n      (fun k => summaryRepresentative (h k) (m k) (W k) (rows k) (y k)) := by\n    funext k\n    exact acquireRepresentatives_words r h m W rows y k\n  have hs := productList_spec J (List.ofFn (fun g : Fin r => g)) _ _\n    (fun g _ => scanGroup_spec J (h g) (m g) (rows g)\n      (summaryTarget (h g) (m g) (W g) (y g)) (forced g)\n      (fun bits => value g (Function.update (acquireRepresentatives r h m W rows y).words g bits))\n      (fun bits => P g (Function.update (acquireRepresentatives r h m W rows y).words g bits))\n      (fun bits => hv g _))\n  simp only [List.map_ofFn,List.prod_ofFn,Function.comp_apply,hreps] at hs\n  simpa only [fibreAt,Spec,hreps] using hs\n\n/-- Group scans contribute a SUM of local exponential costs, never a Cartesian\nenumeration of all global Boolean assignments. -/\ntheorem fibreAt_work (J r H M B : ℕ) (h m W : Fin r → ℕ)\n    (rows : (g : Fin r) → Fin (m g) → Fin (h g) → ℤ)\n    (y : (g : Fin r) → SemiprimeLayoutCertificates.Summary (Fin (h g)) (Fin (m g)) (W g))\n    (forced : (g : Fin r) → Fin (h g) → Bool)\n    (value : (g : Fin r) → ((k : Fin r) → Fin (h k) → Bool) → Run)\n    (hh : ∀ g, h g ≤ H) (hm : ∀ g, m g ≤ M) (hv : ∀ g x, (value g x).work ≤ B) :\n    (fibreAt J r h m W rows y forced value).work ≤\n      r*(2^H*(B+M*(4*H+3)+4*H+5*J+6)+(2*J*(J+1)+J+1))+(J+1) +\n        r*(2^H*(M*(4*H+3)+3))+1 := by\n  have hscan (g : Fin r) :\n      (scanGroup J (h g) (m g) (rows g) (summaryTarget (h g) (m g) (W g) (y g))\n        (forced g) (fun bits => value g (Function.update\n          (acquireRepresentatives r h m W rows y).words g bits))).work ≤\n          2^H*(B+M*(4*H+3)+4*H+5*J+6) := by\n    apply (scanGroup_work J (h g) (m g) B _ _ _ _ (fun bits => hv g _)).trans\n    apply Nat.mul_le_mul (Nat.pow_le_pow_right (by decide) (hh g))\n    have hgh := hh g\n    have hb := Nat.mul_le_mul (hm g) (show 4*h g+3 ≤ 4*H+3 by omega)\n    omega\n  have hp := productList_work J (2^H*(B+M*(4*H+3)+4*H+5*J+6))\n    (List.ofFn (fun g : Fin r => g)) _ (fun g _ => hscan g)\n  have hr := acquireRepresentatives_work_le r h m W rows y\n  have hr' : (acquireRepresentatives r h m W rows y).work ≤ r*(2^H*(M*(4*H+3)+3)) := by\n    apply hr.trans\n    calc\n      _ ≤ ∑ _g : Fin r, 2^H*(M*(4*H+3)+3) := by\n        apply Finset.sum_le_sum\n        intro g hg\n        apply Nat.mul_le_mul (Nat.pow_le_pow_right (by decide) (hh g))\n        have hgh := hh g\n        have hb := Nat.mul_le_mul (hm g) (show 4*h g+3 ≤ 4*H+3 by omega)\n        omega\n      _ = _ := by simp\n  simp only [List.length_ofFn] at hp\n  simp only [fibreAt,Run.work]\n  unfold Run.work at hp\n  omega\n\nend RiemannGaussian.SemiprimeFibreArrayExecution\n","RiemannGaussian.SemiprimeFullSetupBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeFullSetupCounter\nimport RiemannGaussian.SemiprimePaidEnumeratedSource\n\n/-! # Numeric bounds for the actual full-setup counter's setup ledger\nOnly the setup part is bounded here. Native counting and primitive bit/address\ncomposition are separate. Large measurement magnitudes are not input dimensions.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 50000\nnamespace RiemannGaussian.SemiprimeFullSetupBudget\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT\nopen SemiprimeRuntimeDesignAcquisition\nvariable {n F r Q : ℕ} [NeZero r]\n\n/-- The literal setup sum occurring in the actual full counter. -/\ndef setupWork (arity : Fin F → ℕ) (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (eps : ℚ) (R B : ℕ) : ℕ :=\n  let en := SemiprimePaidFiniteEnumerations.indexed n F r Q arity\n  let owner := fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2\n  let source := SemiprimeMaterializedOriginalSource.acquire owner Sigma.fst en.value eps R\n  let raw := SemiprimePaidRawAcquisition.acquire arity coordinate en.value eps R B\n  let bits := SemiprimePaidMeasurementBound.bits B Q R\n  let designs := Array.ofFn (fun t : Fin Q => SemiprimePaidRuntimeDesign.build\n    (SemiprimePaidRawAcquisition.raw (n:=n) (F:=F) raw.value t)\n    (SemiprimePaidRawAcquisition.reader (n:=n) raw.value t) bits)\n  en.work+source.work+raw.work+(designs.toList.map (fun x => x.work)).sum+10*Q+20\n\n/-- Selector group budgets are monotone in the actual matrix dimensions. -/\ntheorem groupBudget_mono {m h p n bits a b : ℕ} (hm : m≤p) (hh : h≤n) (hab : a≤b) :\n    SemiprimePaidRuntimeDesign.groupBudget m h bits a ≤\n      SemiprimePaidRuntimeDesign.groupBudget p n bits b := by\n  unfold SemiprimePaidRuntimeDesign.groupBudget SemiprimeEncodedRowSelection.budget\n    SemiprimeRowSelectionBits.runBudget SemiprimeRowSelectionBits.insertBudget\n    SemiprimeRowSelectionBits.residualRowBudget SemiprimeRowSelectionBits.normalizeRowBudget\n    SemiprimeRowSelectionBits.updateRowBudget SemiprimeRowSelectionBitArithmetic.residualBudget\n    SemiprimeMaterializedSelectionTemporaries.selectorWidth\n    SemiprimeMaterializedSelectionTemporaries.leafBits\n    SemiprimeMaterializedSelectionTemporaries.residualBits\n    SemiprimeMaterializedSelectionTemporaries.normalizeBits\n    SemiprimeMaterializedSelectionTemporaries.updateBits\n  all_goals simp only [SemiprimeMaterializedSelectionTemporaries.normalizeBits,\n    SemiprimeMaterializedSelectionTemporaries.residualBits,\n    SemiprimeMaterializedSelectionTemporaries.leafBits]; gcongr\n\n/-- Setup-only design envelope uses the safe polynomial column bound n. -/\ndef designBudget (n F r p bits readBudget : ℕ) : ℕ :=\n  3*(n+1)^2+r*(5*n+1)+r*SemiprimePaidRuntimeDesign.groupBudget p n bits readBudget+\n    100*(n+F+r+1)^4*(1+r*p)\n\n/-- The actual build budget is bounded without using selected rank as an exponent. -/\ntheorem buildBudget_le (d : RawDesign n F) (p bits readBudget : ℕ)\n    (hc : ∀ g,d.count g≤p) :\n    SemiprimePaidRuntimeDesign.buildBudget d bits readBudget ≤\n      designBudget n F d.r p bits readBudget := by\n  have hh (g : Fin d.r) : headSize d g≤n := by\n    exact (List.length_filter_le _ _).trans_eq (by simp [SemiprimeFiniteEnumerations.fin])\n  have hs := Finset.sum_le_sum (fun g (_ : g∈(Finset.univ : Finset (Fin d.r))) =>\n    groupBudget_mono (bits:=bits) (hc g) (hh g) (le_refl readBudget))\n  have ht := Finset.sum_le_sum (fun g (_ : g∈(Finset.univ : Finset (Fin d.r))) => hc g)\n  simp only [Finset.sum_const,Finset.card_univ,Fintype.card_fin,smul_eq_mul] at hs ht\n  unfold SemiprimePaidRuntimeDesign.buildBudget designBudget\n  gcongr\n\n/-- A polynomial source envelope replacing the subset expansion by paid alphabet D. -/\ndef sourceBudget (M n A D T N Q R : ℕ) : ℕ :=\n  SemiprimeMaterializedSourceWords.producerBudget A T N Q+\n  SemiprimeMaterializedSourceAcquisition.packingBudget M D Q (4*N+6*(N+1)^2+7)+\n  (D*(D*(D*SemiprimeMaterializedSourceRows.rowPolynomial Q R+2)+3)+1+\n    (Q*(R+1)+Q+R+R^2)+(2*Q*(R+1)+R^2)+1)+\n  M*(n*(R+2+M*(2*(3*M+1)+2*(D*(7*Q+4)+1)+R+7+4*(R+1)+1)+2)+3)+2+\n  M+M*n+1+M+D+9\n\n/-- Actual source costs have a fixed polynomial bound at the native alphabet. -/\ntheorem sourceBudget_le (M n A D T N Q R start : ℕ)\n    (hD : 2^(2*Q)≤D) (hstart : start≤Q) :\n    SemiprimeMaterializedOriginalSource.budget M n A D T N Q R start ≤\n      sourceBudget M n A D T N Q R := by\n  have hr := SemiprimeMaterializedSourceRows.rowBudget_polynomial Q R D hD\n  unfold SemiprimeMaterializedOriginalSource.budget SemiprimeMaterializedSourceAcquisition.budget\n    SemiprimeMaterializedSourcePullback.acquireBudget SemiprimeMaterializedSourceRows.acquireBudget\n    sourceBudget\n  simp only [Nat.add_assoc]\n  gcongr\n\n/-- Raw setup envelope with interval start replaced by its public upper bound Q. -/\ndef rawBudget (n F M r Q R D A : ℕ) : ℕ :=\n  SemiprimePaidSourceMetadata.budget n F M D A (M^2+Q*n^2) (n+F) Q+\n  SemiprimePaidOriginalConstraints.polynomial M n A D (M^2+Q*n^2) (n+F) Q R Q r+\n  4*R+1+M*D+M+12\n\n/-- Both the word-menu and interval substitutions preserve the raw setup envelope. -/\ntheorem rawBudget_le (n F M r Q R D a A : ℕ) (ha : a≤A)\n    (hAQ : Subexp.TailInterval.intervalStart r Q R≤Q) :\n    SemiprimePaidRawAcquisition.budget n F r Q R M D a (M^2+Q*n^2) (n+F) ≤\n      rawBudget n F M r Q R D A := by\n  unfold SemiprimePaidRawAcquisition.budget rawBudget\n    SemiprimePaidSourceMetadata.budget SemiprimePaidOriginalConstraints.polynomial\n    SemiprimePaidConstraintAcquisition.polynomial SemiprimePaidConstraintAcquisition.universalPolynomial\n    SemiprimeMaterializedSourceWords.producerBudget SemiprimeMaterializedScoreSearch.evaluatorBudget\n  gcongr\n\n/-- Literal fixed polynomial in original dimensions and the two alphabet sizes. -/\ndef setupBudget (n F M r Q R B D A : ℕ) : ℕ :=\n  SemiprimePaidFiniteEnumerations.polynomial n F M Q A A+\n  sourceBudget M n A D (M^2+Q*n^2) (n+F) Q R+\n  rawBudget n F M r Q R D A+\n  Q*designBudget n F r (M*D+M) (SemiprimePaidMeasurementBound.bits B Q R)\n    (2*(Q+r+(M*D+M)+n)+14)+10*Q+20\n\n/-- One actual physical design has a uniform polynomial setup bound. -/\ntheorem physical_work_bound (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n) (eps : ℚ) (R B : ℕ)\n    (howner : ∀ v, (Finset.univ.filter\n      (fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2=v)).card≤B)\n    (hQ : 1≤Q) (hAQ : Subexp.TailInterval.intervalStart r Q R≤Q) (t : Fin Q) :\n    (SemiprimePaidRuntimeDesign.build\n      (SemiprimePaidRawAcquisition.raw (n:=n) (F:=F)\n        (SemiprimePaidRawAcquisition.acquire arity coordinate\n          (SemiprimeFiniteEnumerations.indexed n F r Q arity) eps R B).value t)\n      (SemiprimePaidRawAcquisition.reader (n:=n)\n        (SemiprimePaidRawAcquisition.acquire arity coordinate\n          (SemiprimeFiniteEnumerations.indexed n F r Q arity) eps R B).value t)\n      (SemiprimePaidMeasurementBound.bits B Q R)).work ≤\n    designBudget n F r ((∑ e,arity e)*r^(2*Q)+(∑ e,arity e))\n      (SemiprimePaidMeasurementBound.bits B Q R)\n      (2*(Q+r+((∑ e,arity e)*r^(2*Q)+(∑ e,arity e))+n)+14) := by\n  let en := SemiprimeFiniteEnumerations.indexed n F r Q arity\n  let snapshot := (SemiprimePaidRawAcquisition.acquire arity coordinate en eps R B).value\n  let d : RawDesign n F := SemiprimePaidRawAcquisition.raw snapshot t\n  let p := (∑ e,arity e)*r^(2*Q)+(∑ e,arity e)\n  let bits := SemiprimePaidMeasurementBound.bits B Q R\n  let rb := 2*(Q+r+p+n)+14\n  have hc : snapshot.count≤p := by\n    have h := SemiprimeCachedRawConstraints.acquired_count_le arity coordinate en eps R\n    have hM : en.incidences.values.length=∑ e,arity e :=\n      SemiprimeFiniteEnumerations.indexedIncidences_length F arity\n    have hD : en.types.values.length=r^(2*Q) := SemiprimeFiniteEnumerations.universal_length r Q\n    rw [hM,hD] at h\n    exact h\n  have hb : ∀ g j v, |d.rows g j v|≤(2^bits : ℕ) := by\n    dsimp only [d,snapshot,en]\n    rw [SemiprimePaidRawAcquisition.acquire_raw]\n    intro g j v\n    exact (SemiprimeAcquiredSourceCounter.raw_bounded arity coordinate eps R B howner hQ hAQ t g j v).trans\n      (by exact_mod_cast SemiprimePaidMeasurementBound.bound_le B Q R)\n  have hr : ∀ g j v,(SemiprimePaidRawAcquisition.reader (n:=n) snapshot t g j v).work≤rb := by\n    intro g j v\n    have h := SemiprimePaidRawAcquisition.acquire_reader_work arity coordinate en eps R B t g j v\n    apply h.trans\n    dsimp only [rb]\n    exact Nat.add_le_add_right (Nat.mul_le_mul_left 2\n      (Nat.add_le_add_right (Nat.add_le_add_left hc (Q+r)) n)) 14\n  have hw := SemiprimePaidRuntimeDesign.build_work d\n    (SemiprimePaidRawAcquisition.reader (n:=n) snapshot t) bits rb\n    (fun g j v => SemiprimePaidRawAcquisition.reader_value snapshot t g j v) hb hr\n  exact hw.trans (buildBudget_le d p bits rb (fun _ => hc))\n\n/-- Every setup report in the actual full counter is bounded from original parameters. -/\ntheorem setup_work_bound (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n) (eps : ℚ) (R B : ℕ)\n    (hr : 2≤r)\n    (howner : ∀ v, (Finset.univ.filter\n      (fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2=v)).card≤B)\n    (hQ : 1≤Q) (hAQ : Subexp.TailInterval.intervalStart r Q R≤Q) :\n    setupWork (r:=r) (Q:=Q) arity coordinate eps R B ≤\n      setupBudget n F (∑ e,arity e) r Q R B (r^(2*Q)) (r^Q) := by\n  let en := SemiprimePaidFiniteEnumerations.indexed n F r Q arity\n  let owner := fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2\n  have he := SemiprimePaidFiniteEnumerations.indexed_work_polynomial n F r Q arity hQ\n  have hs := SemiprimeMaterializedOriginalSource.acquire_work (n:=n) (r:=r) (Q:=Q) owner Sigma.fst en.value eps R\n  have hx := SemiprimePaidRawAcquisition.acquire_work_native (n:=n) (r:=r) (Q:=Q) arity coordinate en.value hr eps R B\n  have ht : en.value.wordTail.length≤r^Q := by\n    rw [SemiprimePaidFiniteEnumerations.indexed_value]\n    exact (List.length_filter_le _ _).trans_eq (SemiprimeFiniteEnumerations.words_length r Q)\n  rw [SemiprimePaidFiniteEnumerations.indexed_incidence_length,\n    SemiprimePaidFiniteEnumerations.indexed_universal_length,\n    SemiprimePaidFiniteEnumerations.indexed_score_length,\n    SemiprimePaidFiniteEnumerations.indexed_indices_length] at hs hx\n  have hsource := hs.trans ((SemiprimePaidEnumeratedSource.sourceBudget_mono_words\n    (∑ e,arity e) n en.value.wordTail.length (r^Q) (r^(2*Q)) ((∑ e,arity e)^2+Q*n^2)\n    (n+F) Q R (SemiprimeMaterializedSourcePullback.centered r Q R) ht).trans\n    (sourceBudget_le (∑ e,arity e) n (r^Q) (r^(2*Q)) ((∑ e,arity e)^2+Q*n^2)\n      (n+F) Q R (SemiprimeMaterializedSourcePullback.centered r Q R)\n      (Nat.pow_le_pow_left hr _) hAQ))\n  have hraw := hx.trans (rawBudget_le n F (∑ e,arity e) r Q R (r^(2*Q)) en.value.wordTail.length (r^Q) ht hAQ)\n  have hd := Finset.sum_le_sum (fun t (_ : t∈(Finset.univ : Finset (Fin Q))) =>\n    physical_work_bound arity coordinate eps R B howner hQ hAQ t)\n  simp only [Finset.sum_const,Finset.card_univ,Fintype.card_fin,smul_eq_mul] at hd\n  unfold setupWork setupBudget\n  dsimp only\n  simp only [Array.toList_ofFn,List.map_ofFn,List.sum_ofFn,Function.comp_apply]\n  dsimp only [en,owner] at hsource hraw\n  simp only [SemiprimePaidFiniteEnumerations.indexed_value] at hsource hraw ⊢\n  apply Nat.add_le_add_right\n  apply Nat.add_le_add_right\n  apply Nat.add_le_add\n  · exact Nat.add_le_add (Nat.add_le_add he hsource) hraw\n  · let f := fun en : SemiprimeSourceLayout.Enumerations\n        ((e : Fin F) × Fin (arity e)) (Fin n) (Fin F) r Q =>\n      ∑ t : Fin Q, (SemiprimePaidRuntimeDesign.build\n        (SemiprimePaidRawAcquisition.raw (n:=n) (F:=F)\n          (SemiprimePaidRawAcquisition.acquire arity coordinate en eps R B).value t)\n        (SemiprimePaidRawAcquisition.reader (n:=n)\n          (SemiprimePaidRawAcquisition.acquire arity coordinate en eps R B).value t)\n        (SemiprimePaidMeasurementBound.bits B Q R)).work\n    have hEq := congrArg f (SemiprimePaidFiniteEnumerations.indexed_value n F r Q arity)\n    exact hEq.le.trans hd\n\n/-- The native report uses the actual physical designs and source arrays. -/\ndef nativeWork (arity : Fin F → ℕ) (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (eps : ℚ) (R B J : ℕ)\n    (T : (e : Fin F) → (Fin (arity e) → Bool) → SemiprimeLocalArrayFrontend.EntryReport) : ℕ :=\n  let en := SemiprimePaidFiniteEnumerations.indexed n F r Q arity\n  let owner := fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2\n  let source := SemiprimeMaterializedOriginalSource.acquire owner Sigma.fst en.value eps R\n  let raw := SemiprimePaidRawAcquisition.acquire arity coordinate en.value eps R B\n  let bits := SemiprimePaidMeasurementBound.bits B Q R\n  let designs := Array.ofFn (fun t : Fin Q => SemiprimePaidRuntimeDesign.build\n    (SemiprimePaidRawAcquisition.raw (n:=n) (F:=F) raw.value t)\n    (SemiprimePaidRawAcquisition.reader (n:=n) raw.value t) bits)\n  (SemiprimeMaterializedFibreNative.count Q J R\n    (fun t => (designs[t.val]'(by simp [designs])).value)\n    (fun e i v => SemiprimeSourceArrayAcquisition.read en.value.incidences source.value ⟨e,i⟩ v) T).work\n\n/-- Exact additive separation of ACTUAL setup from ACTUAL native execution. -/\ntheorem count_work_eq_setup_add_native (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n) (eps : ℚ) (R B J : ℕ)\n    (T : (e : Fin F) → (Fin (arity e) → Bool) → SemiprimeLocalArrayFrontend.EntryReport) :\n    (SemiprimeFullSetupCounter.count (r:=r) (Q:=Q) arity coordinate eps R B J T).work=\n      setupWork (r:=r) (Q:=Q) arity coordinate eps R B+\n      nativeWork (r:=r) (Q:=Q) arity coordinate eps R B J T := by\n  unfold SemiprimeFullSetupCounter.count setupWork nativeWork\n  dsimp only\n  omega\n\nend RiemannGaussian.SemiprimeFullSetupBudget\n","RiemannGaussian.SemiprimeHermiteReportStagePolynomial":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeHermiteBitsSetupBudget\nimport RiemannGaussian.SemiprimeReportPolynomialGrowth\n\n/-! # Explicit separated-cardinality polynomials for physical Hermite packets\nOnly original LOCAL and HEAD powers occur, represented by independent paid\nresources. No power of a common dimension bound replaces either cardinality.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 4000000\nnamespace RiemannGaussian.SemiprimeHermiteReportStagePolynomial\nopen scoped BigOperators\nopen SemiprimeNodeArrayExecution (RuntimeDesign)\n\n/-- Original source width has a fixed polynomial resource envelope. -/\ndef inputEnvelope (S : ℕ) : ℕ := SemiprimeNativeInputBits.polynomial S S S S S\n\n/-- Actual computed input bits are bounded, rather than assumed at resource scale. -/\ntheorem inputBits_le_envelope (n B Q R J S : ℕ)\n    (hn : n ≤ S) (hB : B ≤ S) (hQ : Q ≤ S) (hR : R ≤ S) (hJ : J ≤ S) :\n    SemiprimeNativeInputBits.inputBits n B Q R J ≤ inputEnvelope S := by\n  apply (SemiprimeNativeInputBits.inputBits_le_polynomial n B Q R J).trans\n  unfold inputEnvelope SemiprimeNativeInputBits.polynomial\n  gcongr\n\n/-- Physical group polynomial with its actual local truth count separated. -/\ndef groupPolynomial (n F R J b s w A E Ew : ℕ) : ℕ :=\n  let W := SemiprimeNativeGroupBits.groupWidth b R F s\n  let loc := w*SemiprimeCorrectedPortBitsBounds.portBudget W A R J n+\n    Ew*(E+(w+1)*SemiprimeLocalBitsBounds.nodeBudget J W)+\n    (20*(w+1)*(J+1)*(W+1)*(Ew+1)+10*w+10)\n  F*(loc+(3*J+1)+SemiprimeNativeGroupBitsBudget.multiplyBudget W J+J+3)+\n    (3*J+1)+SemiprimeNativeGroupBits.groupControl n F J W+\n    J*(20000*(2*W+1)^3+5)+2*J+1+\n    SemiprimeNativeBitsCounter.inputControl n F s R W\n\n/-- Exact equality, including the old harmless nonnegative group-boundary overestimate. -/\ntheorem groupBudget_eq_polynomial (n F R J b s w A E : ℕ) :\n    SemiprimeNativeBitsCounterBudget.groupBudget n F R J b s w A E=\n      groupPolynomial n F R J b s w A E (2^w) := by\n  rfl\n\n/-- A diagonal physical group envelope uses only the LOCAL count resource. -/\ndef groupEnvelope (S : ℕ) : ℕ :=\n  groupPolynomial S S S S (inputEnvelope S) S S (S+1) S S\n\n/-- Scalar monotonicity keeps 2^w independent of the coarse resource S. -/\ntheorem groupBudget_le_envelope (n F R J b s w E S : ℕ)\n    (hn : n ≤ S) (hF : F ≤ S) (hR : R ≤ S) (hJ : J ≤ S) (hb : b ≤ inputEnvelope S)\n    (hs : s ≤ S) (hw : w ≤ S) (hE : E ≤ S) (hEw : 2^w ≤ S) :\n    SemiprimeNativeBitsCounterBudget.groupBudget n F R J b s w (R+1) E ≤ groupEnvelope S := by\n  rw [groupBudget_eq_polynomial]\n  unfold groupEnvelope groupPolynomial\n  dsimp only\n  simp only [SemiprimeNativeGroupBits.groupWidth,SemiprimeNativeGroupBits.factorExponent,\n    SemiprimeNativeLocalBits.publicWidth,SemiprimeNativeLocalBits.portExponent,\n    SemiprimeCorrectedPortBits.portWidth,SemiprimeLocalBitsBounds.bufferWidth,\n    SemiprimeCorrectedPortBitsBounds.portBudget,SemiprimeCorrectedPortBitsBounds.shiftStepBudget,\n    SemiprimeCorrectedPortBitsBounds.maskBudget,SemiprimeCorrectedPortBitsBounds.addBudget,\n    SemiprimeCorrectedPortBitsBounds.multiplyBudget,SemiprimeLocalBitsBounds.nodeBudget,\n    SemiprimeLocalBitsBounds.scaleBudget,SemiprimeLocalBitsBounds.addBudget,\n    SemiprimeLocalBitsBounds.multiplyBudget,SemiprimeLocalBitsBounds.accessBudget,\n    SemiprimeNativeGroupBitsBudget.multiplyBudget,SemiprimeNativeGroupBits.groupControl,\n    SemiprimeNativeBitsCounter.inputControl]\n  gcongr\n\n/-- A HEAD count is separated in the physical head and support node polynomial. -/\ndef nodePolynomial (W n J r H M B Y Cq Eh : ℕ) : ℕ :=\n  let head := 3*J+1+Eh*(B+2*M+4*H+3*J+5+SemiprimeWordFoldBounds.addBudget W J)\n  let one := r*(head+SemiprimeNativeGroupBitsBudget.multiplyBudget W J+J+3)+(3*J+1)+\n    r*(Eh*(2*M+3)+H+1)+r+1\n  let fibre := 3*J+1+Y*(one+SemiprimeWordFoldBounds.addBudget W J)\n  Cq*(fibre+SemiprimeWordFoldBounds.scaleBudget W J+3*n+1+\n    n*(2*SemiprimeWordFoldBounds.addBudget W J+1))+\n    (r*(Eh*(H+M*(4*H+2)+3))+r+1)\n\n/-- Exact node traversal identity at its actual finite cardinalities. -/\ntheorem nodeBudget_eq_polynomial (W n J r H M B Y : ℕ) :\n    SemiprimeMaterializedWordFibreBounds.nodeBudget W n J r H M B Y=\n      nodePolynomial W n J r H M B Y\n        (SemiprimeCounterEnumeration.weightedCount n (J-1)) (2^H) := by\n  rfl\n\n/-- Original head and group dimensions give a polynomial packet width. -/\ndef nodeWidthEnvelope (S : ℕ) : ℕ :=\n  SemiprimeWordPacketWidth.packetWidth (inputEnvelope S) S S S S S S (1+S*S) S S\n\n/-- Complete physical word-node envelope including actual parameter/control work. -/\ndef nodeEnvelope (S : ℕ) : ℕ :=\n  nodePolynomial (nodeWidthEnvelope S) S S S S S (groupEnvelope S) S S S+\n    40*(S+S+S+S+S*S+inputEnvelope S+S+S+nodeWidthEnvelope S+1)^2+20\n\n/-- Actual head cap uses the given HEAD count, never a new 2^S bound. -/\ntheorem headCap_le {n F : ℕ} (d : RuntimeDesign n F) (H S : ℕ)\n    (hr : d.r ≤ S) (hh : ∀ g,d.h g ≤ H) (hEh : 2^H ≤ S) :\n    SemiprimeWordPacketCounter.headCap d ≤ 1+S*S := by\n  have h : (∑ g,2^(d.h g)) ≤ d.r*2^H := by\n    calc\n      _  ≤  ∑ _g : Fin d.r,2^H := Finset.sum_le_sum (fun g _ => Nat.pow_le_pow_right (by decide) (hh g))\n      _ = _ := by simp\n  unfold SemiprimeWordPacketCounter.headCap\n  exact Nat.add_le_add_left (h.trans (Nat.mul_le_mul hr hEh)) 1\n\n/-- All actual width parameters, summary cardinalities and HEAD caps are acquired resources. -/\ntheorem nodeWidth_le_envelope {n F : ℕ} (b R J H S : ℕ) (arity : Fin F → ℕ)\n    (d : RuntimeDesign n F) (hn : n ≤ S) (hF : F ≤ S) (hs : (∑ e,arity e) ≤ S)\n    (hb : b ≤ inputEnvelope S) (hR : R ≤ S) (hJ : J ≤ S) (hr : d.r ≤ S)\n    (hh : ∀ g,d.h g ≤ H) (hEh : 2^H ≤ S)\n    (hY : SemiprimePacketArrayExecution.summaryCount d.r d.h d.m d.W ≤ S)\n    (hCq : SemiprimeCounterEnumeration.weightedCount n (J-1) ≤ S) :\n    SemiprimeWordPacketCounter.nodeWidth b R J arity d ≤ nodeWidthEnvelope S := by\n  have hp := headCap_le d H S hr hh hEh\n  unfold SemiprimeWordPacketCounter.nodeWidth nodeWidthEnvelope\n  simp only [SemiprimeWordPacketWidth.packetWidth,SemiprimeWordPacketWidth.productExponent,\n    SemiprimeNativeGroupBitsHeight.exponent,SemiprimeNativeGroupBits.factorExponent,SemiprimeNativeGroupBits.groupWidth,\n    SemiprimeNativeLocalBits.publicWidth,SemiprimeNativeLocalBits.portExponent,\n    SemiprimeCorrectedPortBits.portWidth,SemiprimeLocalBitsBounds.bufferWidth]\n  gcongr\n\n/-- Full actual physical node bound, with independent head/local/support resources. -/\ntheorem nodeBudget_le_envelope {n F : ℕ} (b J R H M w E S : ℕ)\n    (arity : Fin F → ℕ) (d : RuntimeDesign n F)\n    (hn : n ≤ S) (hF : F ≤ S) (hs : (∑ e,arity e) ≤ S)\n    (hb : b ≤ inputEnvelope S) (hJ : J ≤ S) (hR : R ≤ S)\n    (hH : H ≤ S) (hM : M ≤ S) (hw : w ≤ S) (hE : E ≤ S)\n    (hr : d.r ≤ S) (hh : ∀ g,d.h g ≤ H) (hm : ∀ g,d.m g ≤ M)\n    (hY : SemiprimePacketArrayExecution.summaryCount d.r d.h d.m d.W ≤ S)\n    (hCq : SemiprimeCounterEnumeration.weightedCount n (J-1) ≤ S)\n    (hEw : 2^w ≤ S) (hEh : 2^H ≤ S) :\n    SemiprimeWordPacketCounterBudget.nodeBudget b J R H M\n      (SemiprimeNativeBitsCounterBudget.groupBudget n F R J b (∑ e,arity e) w (R+1) E) arity d ≤\n        nodeEnvelope S := by\n  have hwidth := nodeWidth_le_envelope b R J H S arity d hn hF hs hb hR hJ hr hh hEh hY hCq\n  have hg := groupBudget_le_envelope n F R J b (∑ e,arity e) w E S hn hF hR hJ hb hs hw hE hEw\n  have hsum : (∑ g,d.m g) ≤ S*S := by\n    calc\n      _ ≤ ∑ _g : Fin d.r,M := Finset.sum_le_sum (fun g _ => hm g)\n      _ = d.r*M := by simp\n      _ ≤ S*S := Nat.mul_le_mul hr hM\n  have hp : SemiprimeMaterializedWordFibreBounds.nodeBudget\n      (SemiprimeWordPacketCounter.nodeWidth b R J arity d) n J d.r H M\n      (SemiprimeNativeBitsCounterBudget.groupBudget n F R J b (∑ e,arity e) w (R+1) E)\n      (SemiprimePacketArrayExecution.summaryCount d.r d.h d.m d.W) ≤\n      nodePolynomial (nodeWidthEnvelope S) S S S S S (groupEnvelope S) S S S := by\n    rw [nodeBudget_eq_polynomial]\n    unfold nodePolynomial\n    dsimp only\n    simp only [SemiprimeWordFoldBounds.addBudget,SemiprimeWordFoldBounds.scaleBudget,\n      SemiprimeCorrectedPortBitsBounds.addBudget,SemiprimeNativeGroupBitsBudget.multiplyBudget]\n    gcongr\n  have hc : SemiprimeWordPacketCounter.nodeControl b R J arity d ≤\n      40*(S+S+S+S+S*S+inputEnvelope S+S+S+nodeWidthEnvelope S+1)^2+20 := by\n    unfold SemiprimeWordPacketCounter.nodeControl\n    gcongr\n  unfold SemiprimeWordPacketCounterBudget.nodeBudget nodeEnvelope\n  omega\n\nend RiemannGaussian.SemiprimeHermiteReportStagePolynomial\n","RiemannGaussian.SemiprimeMacroEntryExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimePublicFactorCount\nimport Batteries.Data.BitVec.Lemmas\n\n/-! # Explicit arithmetic behind the ordered macro entry tables -/\nset_option autoImplicit false\nset_option maxHeartbeats 800000\nnamespace RiemannGaussian.SemiprimeMacroEntryExecution\nopen scoped BigOperators\nopen SemiprimeBooleanNetwork SemiprimeMacroFermatNetwork\nopen SemiprimeMacroGraphSemantics\n\n/-- Executable little-endian decoder, with one multiply/add per input bit. -/\ndef binaryDecode {width : ℕ} (input : Fin width → Bool) : ℕ := Nat.ofBits input\n\n/-- The decoder is the literal weighted binary sum on the ordered ports. -/\ntheorem binaryDecode_eq_sum {width : ℕ} (input : Fin width → Bool) :\n    binaryDecode input = ∑ i : Fin width, (input i).toNat * 2^i.val := by\n  induction width with\n  | zero => simp [binaryDecode]\n  | succ width ih =>\n    rw [Fin.sum_univ_succ]\n    simp only [Fin.val_zero, pow_zero, Nat.mul_one, Fin.val_succ, pow_succ]\n    rw [show binaryDecode input = 2 * binaryDecode (input ∘ Fin.succ) + (input 0).toNat\n      from Nat.ofBits_succ input, ih]\n    rw [Finset.mul_sum]\n    simp only [Function.comp_apply]\n    have hs : (∑ x : Fin width, 2 * ((input x.succ).toNat * 2^x.val)) =\n        ∑ x : Fin width, (input x.succ).toNat * (2^x.val * 2) := by\n      apply Finset.sum_congr rfl\n      intro x _\n      ring\n    rw [hs]\n    omega\n\n/-- The old finite-equivalence inverse is exactly the executable decoder. -/\ntheorem readWord_eq_binaryDecode {width : ℕ} (input : Fin width → Bool) :\n    readWord width input = binaryDecode input := by\n  have he : (BitVec.ofFnLE input).getLsb = input := by\n    funext i\n    exact BitVec.getLsb_ofFnLE input i\n  calc\n    readWord width input = readWord width (BitVec.ofFnLE input).getLsb := congrArg _ he.symm\n    _ = decode (BitVec.ofFnLE input) := readWord_bits (BitVec.ofFnLE input)\n    _ = binaryDecode input := BitVec.toNat_ofFnLE input\n\n/-- Closed-form inverse of the transform length in the actual Fermat ring. -/\ndef explicitNormalizer (depth : ℕ) : MacroRing depth :=\n  -(2 : MacroRing depth)^(macroLength depth-(depth+1))\n\n/-- No prime-modulus or modular-inverse oracle is needed for this inverse. -/\ntheorem explicitNormalizer_spec (depth : ℕ) :\n    (macroLength depth : MacroRing depth) * explicitNormalizer depth = 1 := by\n  have hle : depth+1 ≤ macroLength depth := by\n    unfold macroLength\n    exact Nat.le_of_lt (Nat.lt_two_pow_self)\n  unfold explicitNormalizer\n  rw [show (macroLength depth : MacroRing depth) = (2 : MacroRing depth)^(depth+1) by\n    simp only [macroLength, Nat.cast_pow, Nat.cast_ofNat]]\n  rw [mul_neg, ← pow_add, Nat.add_sub_of_le hle]\n  have hf := SemiprimeBitFermatArithmetic.fermat_radix (macroLength depth)\n  simp only [Nat.cast_pow, Nat.cast_ofNat] at hf\n  rw [hf]\n  ring\n\n/-- Every semantics configuration has exactly this computable normalizer. -/\ntheorem normalizer_eq_explicit (p : Config) : p.normalizer=explicitNormalizer p.depth := by\n  have h := explicitNormalizer_spec p.depth\n  calc\n    p.normalizer = p.normalizer * ((macroLength p.depth : MacroRing p.depth) * explicitNormalizer p.depth) := by rw [h]; ring\n    _ = (macroLength p.depth : MacroRing p.depth) * p.normalizer * explicitNormalizer p.depth := by ring\n    _ = explicitNormalizer p.depth := by rw [p.normalizer_spec]; ring\n\n\n/-- Explicit width argument matches each actual ordered word block. -/\ndef decodeWord (width : ℕ) (input : Fin width → Bool) : ℕ := binaryDecode input\n\n/-- Executable second-stage normalization, including the inverse transform. -/\ndef explicitNormalization (p : Config) : SemiprimeMacroGraph.Transform → MacroRing p.depth\n  | .inl _ => 1\n  | .inr _ => explicitNormalizer p.depth\n\nopen SemiprimeMacroGraph\n\n/-- Same literal tests with only binary decoding and the explicit normalizer. -/\ndef executableLocalPredicate (p : Config) : (v : Vertex p.r p.t p.digits)→(LocalSlot v→Bool)→Prop\n  | .input _ i,x =>\n      let word := decodeWord (p.r*p.t+1) (fun bit => x (.inl bit))\n      if hi : i.val<p.digits then\n        word<2^(p.width ⟨i.val,hi⟩) ∧\n          ∀ j : {j : Fin p.digits // j.val=i.val},x (.inr j)=digitFlag i.val word\n      else word=0\n  | .first tr _,x =>\n      let input := fun j : Fin p.t => decodeWord (p.r*p.t+1) (fun bit => x (.inl (j,bit)))\n      let output := fun k : Fin p.t => decodeWord (p.r*p.t+1) (fun bit => x (.inr (k,bit)))\n      (∀ j,input j<2^(p.r*p.t)+1) ∧ (∀ k,output k<2^(p.r*p.t)+1) ∧\n        ∀ k,(output k : MacroRing p.depth)=\n          ∑ j : Fin p.t,(input j : MacroRing p.depth)*(root p tr^p.r)^(j.val*k.val)\n  | .scale tr j k,x =>\n      let input := decodeWord (p.r*p.t+1) (fun bit => x (.inl bit))\n      let output := decodeWord (p.r*p.t+1) (fun bit => x (.inr bit))\n      input<2^(p.r*p.t)+1 ∧ output<2^(p.r*p.t)+1 ∧\n        (output : MacroRing p.depth)=(input : MacroRing p.depth)*root p tr^(j.val*k.val)\n  | .second tr _,x =>\n      let input := fun j : Fin p.r => decodeWord (p.r*p.t+1) (fun bit => x (.inl (j,bit)))\n      let output := fun k : Fin p.r => decodeWord (p.r*p.t+1) (fun bit => x (.inr (k,bit)))\n      (∀ j,input j<2^(p.r*p.t)+1) ∧ (∀ k,output k<2^(p.r*p.t)+1) ∧\n        ∀ k,(output k : MacroRing p.depth)=explicitNormalization p tr*\n          ∑ j : Fin p.r,(input j : MacroRing p.depth)*(root p tr^p.t)^(j.val*k.val)\n  | .product _,x =>\n      let input := fun side : Fin 2 => decodeWord (p.r*p.t+1) (fun bit => x (.inl (side,bit)))\n      let output := decodeWord (p.r*p.t+1) (fun bit => x (.inr bit))\n      (∀ side,input side<2^(p.r*p.t)+1) ∧ output<2^(p.r*p.t)+1 ∧\n        (output : MacroRing p.depth)=(input 0 : MacroRing p.depth)*(input 1 : MacroRing p.depth)\n  | .carryInitial,x => decodeWord (p.r*p.t+1) x=0\n  | .carry k,x =>\n      let coefficient := decodeWord (p.r*p.t+1) (fun bit => x (.inl (0,bit)))\n      let previous := decodeWord (p.r*p.t+1) (fun bit => x (.inl (1,bit)))\n      let next := decodeWord (p.r*p.t+1) (fun bit => x (.inr bit))\n      coefficient<2^(p.r*p.t)+1 ∧ previous<2^(p.r*p.t) ∧ next<2^(p.r*p.t) ∧\n        coefficient+previous=p.target k.val+2^p.bits*next\n  | .carryTerminal,x => decodeWord (p.r*p.t+1) x=0\n  | .orGate _ _,x => x 2=(x 0 || x 1)\n  | .inputCheck _,x => x 0=true\n\n\n/-- Every literal arithmetic predicate is preserved, including integer carries. -/\ntheorem executableLocalPredicate_iff (p : Config) (v : Vertex p.r p.t p.digits)\n    (input : LocalSlot v → Bool) :\n    executableLocalPredicate p v input ↔ localTable p v input := by\n  cases v <;> simp only [executableLocalPredicate, localTable, decodeWord,\n    ← readWord_eq_binaryDecode]\n  simp only [explicitNormalization, normalization]\n  split <;> simp only [normalizer_eq_explicit]\n\n/-- Actual executable zero/one entry on the compiler's ordered bit ports. -/\ninstance executableLocalPredicateDecidable (p : Config) (v : Vertex p.r p.t p.digits)\n    (input : LocalSlot v → Bool) : Decidable (executableLocalPredicate p v input) := by\n  cases v <;> unfold executableLocalPredicate <;> infer_instance\n\n/-- Execute the decidable finite arithmetic checks without a truth table. -/\ndef executableEntry (p : Config) (v : Vertex p.r p.t p.digits)\n    (input : Fin (arity v) → Bool) : Bool :=\n  decide (executableLocalPredicate p v (fun slot => input (localSlotFinEquiv v slot)))\n\n/-- The executable entry is exactly the previously counted literal tensor. -/\ntheorem executableEntry_eq_table (p : Config) (v : Vertex p.r p.t p.digits)\n    (input : Fin (arity v) → Bool) : executableEntry p v input = table p v input := by\n  apply Bool.eq_iff_iff.mpr\n  simp only [executableEntry, table, decide_eq_true_eq]\n  exact executableLocalPredicate_iff p v _\n\n\n/-- Instrumented decoder: the returned value is computed by the very recursion\nwhose primitive bit-read/multiply/add work is accumulated in the second field. -/\ndef decodeRun : {width : ℕ} → (Fin width → Bool) → ℕ × ℕ\n  | 0, _ => (0,0)\n  | _+1, input =>\n      let tail := decodeRun (input ∘ Fin.succ)\n      (2*tail.1+(input 0).toNat,tail.2+3)\n\n/-- The tracked data path computes the executable word decoder. -/\ntheorem decodeRun_value {width : ℕ} (input : Fin width → Bool) :\n    (decodeRun input).1=binaryDecode input := by\n  induction width with\n  | zero => rfl\n  | succ width ih =>\n    simp only [decodeRun]\n    rw [ih]\n    exact (Nat.ofBits_succ input).symm\n\n/-- Exact primitive word-decoding work, not an external clock annotation. -/\ntheorem decodeRun_work {width : ℕ} (input : Fin width → Bool) :\n    (decodeRun input).2=3*width := by\n  induction width with\n  | zero => rfl\n  | succ width ih => simp only [decodeRun,ih]; omega\n\n/-- Explicit repeated-multiplication ring power, returning actual product work. -/\ndef powerRun {α : Type*} [Monoid α] (base : α) : ℕ → α × ℕ\n  | 0 => (1,0)\n  | e+1 => let previous := powerRun base e\n           (previous.1*base,previous.2+1)\n\n/-- Both tracked outputs of repeated multiplication are exact. -/\ntheorem powerRun_correct {α : Type*} [Monoid α] (base : α) (e : ℕ) :\n    powerRun base e=(base^e,e) := by\n  induction e with\n  | zero => simp [powerRun]\n  | succ e ih => simp only [powerRun,ih,pow_succ]\n\n/-- A DFT output evaluated by explicit products and additions; no DFT oracle. -/\ndef dotRun {α : Type*} [CommRing α] (base : α) (stride frequency : ℕ)\n    (input : ℕ → α) : ℕ → α × ℕ\n  | 0 => (0,0)\n  | count+1 =>\n      let previous := dotRun base stride frequency input count\n      let power := powerRun base (stride*(count*frequency))\n      (previous.1+input count*power.1,previous.2+power.2+2)\n\n/-- The computed value is precisely the polynomial DFT output used locally. -/\ntheorem dotRun_value {α : Type*} [CommRing α] (base : α) (stride frequency count : ℕ)\n    (input : ℕ → α) :\n    (dotRun base stride frequency input count).1=\n      ∑ j ∈ Finset.range count,input j*(base^stride)^(j*frequency) := by\n  induction count with\n  | zero => simp [dotRun]\n  | succ count ih =>\n    simp only [dotRun,powerRun_correct,ih,Finset.sum_range_succ,pow_mul]\n\n/-- Exact ring-operation count for that same output computation. -/\ntheorem dotRun_work {α : Type*} [CommRing α] (base : α) (stride frequency count : ℕ)\n    (input : ℕ → α) :\n    (dotRun base stride frequency input count).2=\n      ∑ j ∈ Finset.range count,(stride*(j*frequency)+2) := by\n  induction count with\n  | zero => simp [dotRun]\n  | succ count ih => simp only [dotRun,powerRun_correct,ih,Finset.sum_range_succ]; omega\n\n/-- Uniform polynomial work for a local output with all indices at most n. -/\ntheorem dotRun_work_le {α : Type*} [CommRing α] (base : α)\n    {stride frequency count n : ℕ} (hs : stride≤n) (hf : frequency≤n) (hc : count≤n)\n    (input : ℕ → α) :\n    (dotRun base stride frequency input count).2 ≤ n*(n^3+2) := by\n  rw [dotRun_work]\n  calc\n    _ ≤ ∑ _j ∈ Finset.range count,(n^3+2) := by\n      apply Finset.sum_le_sum\n      intro j hj\n      have hjn : j≤n := (Nat.le_of_lt (Finset.mem_range.mp hj)).trans hc\n      have hm := Nat.mul_le_mul hs (Nat.mul_le_mul hjn hf)\n      nlinarith\n    _ = count*(n^3+2) := by simp\n    _ ≤ n*(n^3+2) := Nat.mul_le_mul_right _ hc\n\n\nopen SemiprimeMacroBitNetwork SemiprimeMacroParameters\n\n/-- Literal public configuration with executable normalization data. -/\ndef executablePublicConfig (N : ℕ) (hN : 0<N) : Config where\n  depth := macroDepth (bitLength N)\n  r := firstAxis (bitLength N)\n  t := secondAxis (bitLength N)\n  digits := digitCount (bitLength N)\n  bits := radixBits (bitLength N)\n  shape := (axes_product _).trans (transform_eq_macroLength (bitLength_pos hN))\n  quarter := (axes_product _).trans (transform_eq_four_radixBits (bitLength_pos hN))\n  bits_pos := radixBits_pos (bitLength_pos hN)\n  digits_pos := (digitCount_bounds (bitLength_pos hN)).1\n  digits_le := (digitCount_bounds (bitLength_pos hN)).2\n  width i := activeDigitBits (bitLength N) i.val\n  width_le i := (activeDigitBits_bounds (bitLength_pos hN) i.isLt).2\n  target := targetDigit (bitLength N) N\n  target_lt i hi := Nat.mod_lt _ (by positivity)\n  normalizer := explicitNormalizer (macroDepth (bitLength N))\n  normalizer_spec := explicitNormalizer_spec (macroDepth (bitLength N))\n\n\n/-- Replacing choice by its explicit value preserves the entire public config. -/\ntheorem executablePublicConfig_eq (N : ℕ) (hN : 0<N) :\n    executablePublicConfig N hN = SemiprimePublicFactorCount.publicConfig N hN := by\n  have hn := normalizer_eq_explicit (SemiprimePublicFactorCount.publicConfig N hN)\n  unfold executablePublicConfig SemiprimePublicFactorCount.publicConfig\n  congr 1\n  exact hn.symm\n\n/-- Dependent table equality under equality of numerical configurations. -/\ntheorem congrArg_heq (f : (p : Config) → ((v : Vertex p.r p.t p.digits) →\n    (Fin (arity v) → Bool) → Bool)) {p q : Config} (h : p=q) : HEq (f p) (f q) := by\n  cases h\n  rfl\n\n/-- The fully public executable table retains the existing counted tensor. -/\ndef publicEntry (N : ℕ) (hN : 0<N)\n    (v : Vertex (firstAxis (bitLength N)) (secondAxis (bitLength N)) (digitCount (bitLength N)))\n    (input : Fin (arity v) → Bool) : Bool := executableEntry (executablePublicConfig N hN) v input\n\n/-- Entrywise refinement at the actual public graph shape. -/\ntheorem publicEntry_eq (N : ℕ) (hN : 0<N)\n    (v : Vertex (firstAxis (bitLength N)) (secondAxis (bitLength N)) (digitCount (bitLength N)))\n    (input : Fin (arity v) → Bool) :\n    publicEntry N hN v input = table (SemiprimePublicFactorCount.publicConfig N hN) v input := by\n  unfold publicEntry\n  erw [executableEntry_eq_table]\n  have ht : HEq (table (executablePublicConfig N hN))\n      (table (SemiprimePublicFactorCount.publicConfig N hN)) := by\n    apply congrArg_heq table (executablePublicConfig_eq N hN)\n  exact congrFun (congrFun (eq_of_heq ht) v) input\n\nend RiemannGaussian.SemiprimeMacroEntryExecution\n","RiemannGaussian.SemiprimeMacroFlagExtension":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeMacroGraph\nimport RiemannGaussian.SemiprimeMacroBitNetwork\n\n/-!\n# Canonical extension of actual macro graph flag wires\n\nThe digit flags determine every OR output uniquely. The terminal check reads\nexactly whether a source digit flag is true, including the one-digit graph.\nNo assumption about accepted multiplication or a counter is used here.\n-/\nnamespace RiemannGaussian.SemiprimeMacroFlagExtension\n\nopen SemiprimeMacroGraph\n\n/-- Executable orPrefix OR, with false padding outside the digit range. -/\ndef orPrefix {d : ℕ} (hd : 0 < d) (flags : Fin d → Bool) : ℕ → Bool\n  | 0 => flags ⟨0, hd⟩\n  | k + 1 => orPrefix hd flags k || if h : k + 1 < d then flags ⟨k + 1, h⟩ else false\n\n/-- Canonical values of the literal digit and non-initial OR wires. -/\ndef buildFlags {d : ℕ} (hd : 0 < d) (flags : Fin 2 → Fin d → Bool) :\n    FlagSignal d → Bool\n  | .digit side i => flags side i\n  | .orOut side i => orPrefix hd (flags side) (i.val + 1)\n\n@[simp] theorem buildFlags_digit {d : ℕ} (hd : 0 < d)\n    (flags : Fin 2 → Fin d → Bool) (side : Fin 2) (i : Fin d) :\n    buildFlags hd flags (.digit side i) = flags side i := rfl\n\n/-- The actual previous-wire index, not an abstract list predecessor. -/\ndef previous {d : ℕ} (hd : 0 < d) (values : FlagSignal d → Bool)\n    (side : Fin 2) (i : Fin (d - 1)) : Bool :=\n  if hi : i.val = 0 then values (.digit side ⟨0, hd⟩)\n  else values (.orOut side ⟨i.val - 1, by have := i.isLt; omega⟩)\n\n/-- The literal terminal wire also covers the d=1 case without an OR output. -/\ndef terminal {d : ℕ} (hd : 0 < d) (values : FlagSignal d → Bool)\n    (side : Fin 2) : Bool :=\n  if he : d = 1 then values (.digit side ⟨0, hd⟩)\n  else values (.orOut side ⟨d - 2, by omega⟩)\n\n/-- Every generated value satisfies its actual local OR-vertex equation. -/\ntheorem buildFlags_or {d : ℕ} (hd : 0 < d) (flags : Fin 2 → Fin d → Bool)\n    (side : Fin 2) (i : Fin (d - 1)) :\n    buildFlags hd flags (.orOut side i) =\n      (previous hd (buildFlags hd flags) side i ||\n        flags side ⟨i.val + 1, by have := i.isLt; omega⟩) := by\n  have hi : i.val + 1 < d := by have := i.isLt; omega\n  change orPrefix hd (flags side) (i.val + 1) =\n    ((if hz : i.val = 0 then flags side ⟨0, hd⟩ else\n      orPrefix hd (flags side) (i.val - 1 + 1)) || flags side ⟨i.val + 1, hi⟩)\n  rw [orPrefix]\n  simp only [dite_eq_left hi]\n  by_cases hz : i.val = 0\n  · simp only [dite_eq_left hz]\n    congr 1\n    rw [hz]\n    rfl\n  · have hp : i.val - 1 + 1 = i.val := by omega\n    simp only [dite_eq_right hz, hp]\n\n/-- Prefix truth is precisely a true digit within its index range. -/\ntheorem prefix_true_iff {d : ℕ} (hd : 0 < d) (flags : Fin d → Bool)\n    (k : ℕ) (hk : k < d) :\n    orPrefix hd flags k = true ↔ ∃ i : Fin d, i.val ≤ k ∧ flags i = true := by\n  induction k with\n  | zero =>\n    simp only [orPrefix]\n    constructor\n    · intro h; exact ⟨⟨0, hd⟩, Nat.le_refl 0, h⟩\n    · rintro ⟨i, hi, hf⟩\n      have he : i = ⟨0, hd⟩ := Fin.ext (by change i.val = 0; omega)\n      simpa [he] using hf\n  | succ k ih =>\n    have hprev : k < d := by omega\n    simp only [orPrefix, dite_eq_left hk, Bool.or_eq_true, ih hprev]\n    constructor\n    · rintro (⟨i, hi, hf⟩ | hf)\n      · exact ⟨i, by omega, hf⟩\n      · exact ⟨⟨k + 1, hk⟩, Nat.le_refl _, hf⟩\n    · rintro ⟨i, hi, hf⟩\n      by_cases he : i.val = k + 1\n      · right\n        have hx : i = ⟨k + 1, hk⟩ := Fin.ext he\n        simpa [hx] using hf\n      · exact Or.inl ⟨i, by omega, hf⟩\n\n/-- The terminal reads exactly the OR of all digit flags. -/\ntheorem terminal_buildFlags_iff {d : ℕ} (hd : 0 < d)\n    (flags : Fin 2 → Fin d → Bool) (side : Fin 2) :\n    terminal hd (buildFlags hd flags) side = true ↔ ∃ i, flags side i = true := by\n  have hlast : d - 1 < d := by omega\n  have hterm : terminal hd (buildFlags hd flags) side = orPrefix hd (flags side) (d - 1) := by\n    by_cases he : d = 1\n    · simp [terminal, he, buildFlags, orPrefix]\n    · have hs : d - 2 + 1 = d - 1 := by omega\n      simp [terminal, he, buildFlags, hs]\n  rw [hterm, prefix_true_iff hd (flags side) (d - 1) hlast]\n  constructor\n  · rintro ⟨i, _, hf⟩; exact ⟨i, hf⟩\n  · rintro ⟨i, hf⟩; exact ⟨i, by have := i.isLt; omega, hf⟩\n\n/-- Local digit and OR checks admit no additional internal extension choices. -/\ntheorem unique_flags {d : ℕ} (hd : 0 < d) (flags : Fin 2 → Fin d → Bool)\n    (values : FlagSignal d → Bool)\n    (hdigit : ∀ side i, values (.digit side i) = flags side i)\n    (hor : ∀ side (i : Fin (d - 1)), values (.orOut side i) =\n      (previous hd values side i || flags side ⟨i.val + 1, by have := i.isLt; omega⟩)) :\n    values = buildFlags hd flags := by\n  have hout : ∀ (side : Fin 2) (k : ℕ) (hk : k < d - 1),\n      values (.orOut side ⟨k, hk⟩) = orPrefix hd (flags side) (k + 1) := by\n    intro side k\n    induction k with\n    | zero =>\n      intro hk\n      have hb : 1 < d := by omega\n      simpa [previous, orPrefix, hdigit, hb] using hor side ⟨0, hk⟩\n    | succ k ih =>\n      intro hk\n      have hprev : k < d - 1 := by omega\n      have hb : k + 1 + 1 < d := by omega\n      have he : k + 1 - 1 = k := by omega\n      simpa [previous, orPrefix, he, hb, ih hprev] using hor side ⟨k + 1, hk⟩\n  funext signal\n  cases signal with\n  | digit side i => exact hdigit side i\n  | orOut side i => exact hout side i.val i.isLt\n\n/-- Exactly one complete flag assignment satisfies the actual local equations. -/\ntheorem existsUnique_flags {d : ℕ} (hd : 0 < d) (flags : Fin 2 → Fin d → Bool) :\n    ∃! values : FlagSignal d → Bool,\n      (∀ side i, values (.digit side i) = flags side i) ∧\n      (∀ side (i : Fin (d - 1)), values (.orOut side i) =\n        (previous hd values side i || flags side ⟨i.val + 1, by have := i.isLt; omega⟩)) := by\n  refine ⟨buildFlags hd flags, ⟨buildFlags_digit hd flags, buildFlags_or hd flags⟩, ?_⟩\n  intro values h\n  exact unique_flags hd flags values h.1 h.2\n\n/-- Actual source input flag, with the special low-digit nontriviality check. -/\ndef inputFlag {d bits : ℕ} (words : Fin d → BitVec bits) (i : Fin d) : Bool :=\n  if i.val = 0 then decide (2 ≤ SemiprimeBooleanNetwork.decode (words i))\n  else decide (SemiprimeBooleanNetwork.decode (words i) ≠ 0)\n\n/-- True source flags are equivalent to a nontrivial actual radix operand. -/\ntheorem inputFlag_exists_iff {d bits : ℕ} (hd : 0 < d)\n    (words : Fin d → BitVec bits) (hbits : 0 < bits) :\n    (∃ i, inputFlag words i = true) ↔ 2 ≤ SemiprimeBooleanNetwork.operand words := by\n  cases d with\n  | zero => omega\n  | succ d =>\n    have he := SemiprimeMacroBitNetwork.actual_input_flag words hbits\n    rw [SemiprimeMacroBitNetwork.or_terminal] at he\n    have ht :\n        ((List.ofFn (fun i : Fin d => SemiprimeBooleanNetwork.decode (words i.succ))).map\n          (fun digit => decide (digit ≠ 0))).any id = true ↔\n          ∃ i : Fin d, SemiprimeBooleanNetwork.decode (words i.succ) ≠ 0 := by\n      rw [List.any_map, List.any_eq_true]\n      constructor\n      · rintro ⟨x, hx, hp⟩\n        obtain ⟨i, rfl⟩ := List.mem_ofFn.mp hx\n        exact ⟨i, by simpa using hp⟩\n      · rintro ⟨i, hi⟩\n        exact ⟨_, List.mem_ofFn.mpr ⟨i, rfl⟩, by simpa using hi⟩\n    simp only [Bool.or_eq_true, decide_eq_true_eq, ht,\n      SemiprimeBooleanNetwork.nontrivialFlag] at he\n    simpa [Fin.exists_fin_succ, inputFlag] using he\n\n/-- Canonical terminal truth for the actual bit-array input checks. -/\ntheorem terminal_inputFlag_iff {d bits : ℕ} (hd : 0 < d)\n    (words : Fin 2 → Fin d → BitVec bits) (hbits : 0 < bits) (side : Fin 2) :\n    terminal hd (buildFlags hd (fun s => inputFlag (words s))) side = true ↔\n      2 ≤ SemiprimeBooleanNetwork.operand (words side) := by\n  rw [terminal_buildFlags_iff, inputFlag_exists_iff hd (words side) hbits]\n\nend RiemannGaussian.SemiprimeMacroFlagExtension\n\n#print axioms RiemannGaussian.SemiprimeMacroFlagExtension.buildFlags_or\n#print axioms RiemannGaussian.SemiprimeMacroFlagExtension.terminal_buildFlags_iff\n#print axioms RiemannGaussian.SemiprimeMacroFlagExtension.unique_flags\n#print axioms RiemannGaussian.SemiprimeMacroFlagExtension.existsUnique_flags\n\n#print axioms RiemannGaussian.SemiprimeMacroFlagExtension.inputFlag_exists_iff\n#print axioms RiemannGaussian.SemiprimeMacroFlagExtension.terminal_inputFlag_iff\n","RiemannGaussian.SemiprimeMaterializedRate":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeScheduledSupportRate\nimport RiemannGaussian.SemiprimeScheduledCounter\n\n/-! # Aggregate rate for the actual materialized public counter\n\nThis bounds a resource envelope, not an implementation's running time. The\nliteral support count and scheduled summary/head/arity bounds are retained.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnoncomputable section\nnamespace RiemannGaussian.SemiprimeMaterializedRate\nopen Filter\nopen scoped Topology\nopen SemiprimeCounterRate SemiprimeSourceLayoutRate SemiprimeScheduledSupportRate\n\n/-- Exact integer-log decay used by the scheduled source summary bound. -/\ndef decay (lam : ℕ) : ℝ := (Nat.clog 2 lam : ℝ)^2 / Real.sqrt (lam : ℝ)\n\n/-- The actual ceiling-log expression, rather than a smooth surrogate, vanishes. -/\ntheorem decay_zero : Tendsto decay atTop (𝓝 0) := by\n  have hn : Tendsto (fun n : ℕ => (n : ℝ)) atTop atTop := tendsto_natCast_atTop_atTop\n  have hl := (tendsto_rpow_neg_atTop (show (0 : ℝ)<1/4 by norm_num)).comp hn\n  apply squeeze_zero' (Eventually.of_forall (fun n => by dsimp [decay]; positivity)) ?_ hl\n  filter_upwards [eventually_clog_power_le_rpow 2 (1/4) (by norm_num),\n    eventually_ge_atTop (1 : ℕ)] with n h hpos\n  have hp : (0 : ℝ)<n := Nat.cast_pos.mpr (by omega)\n  have he : (n : ℝ)^(1/4 : ℝ)/Real.sqrt (n : ℝ)=(n : ℝ)^(-(1/4) : ℝ) := by\n    rw [Real.sqrt_eq_rpow,← Real.rpow_sub hp]\n    norm_num\n  change (Nat.clog 2 n : ℝ)^2 / Real.sqrt (n : ℝ)≤(n : ℝ)^(-(1/4) : ℝ)\n  rw [← he]\n  exact div_le_div_of_nonneg_right h (by positivity)\n\n/-- Actual summary envelope from the proved total-rank estimate. -/\ndef summaryEnvelope (n : ℕ) : ℝ :=\n  Real.exp (48*(n : ℝ)*decay (Nat.clog 2 n)*Real.log 2)\n\n/-- The original head bound, rounded upward only in the real exponent. -/\ndef headEnvelope (n : ℕ) : ℝ :=\n  Real.exp ((2*(n : ℝ)/scheduledGroupCount (Nat.clog 2 n))*Real.log 2)\n\n/-- Degree-d polynomial preprocessing plus literal supports and the public\nsummary, head and growing-scope truth-table envelopes. -/\ndef budget (d n : ℕ) : ℝ := (n : ℝ)^d +\n  SemiprimeCounterEnumeration.weightedCount n (cutoff n) + summaryEnvelope n +\n  headEnvelope n + Real.exp (512*(n : ℝ)^(3/4 : ℝ)*Real.log 2)\n\n/-- Every prescribed exponential rate absorbs the scheduled summary bound. -/\ntheorem summary_subexponential (ε : ℝ) (hε : 0<ε) :\n    ∀ᶠ n : ℕ in atTop, summaryEnvelope n≤Real.exp (ε*(n : ℝ)) := by\n  have hl := ((decay_zero.comp tendsto_clog_two_atTop).const_mul (48*Real.log 2))\n  simp only [mul_zero] at hl\n  filter_upwards [hl.eventually (gt_mem_nhds hε)] with n hn\n  apply Real.exp_le_exp.mpr\n  have hm := mul_le_mul_of_nonneg_right hn.le (show (0 : ℝ)≤n by positivity)\n  simp only [Function.comp_apply] at hm\n  convert hm using 1\n  ring\n\n/-- The actual head exponent is dominated by the source summary envelope. -/\ntheorem eventually_head_le_summary :\n    ∀ᶠ n : ℕ in atTop, headEnvelope n≤ summaryEnvelope n := by\n  filter_upwards [(tendsto_clog_two_atTop.comp tendsto_clog_two_atTop).eventually\n    (eventually_ge_atTop 64)] with n hn\n  have hi := source_inverse_group_budget hn\n  apply Real.exp_le_exp.mpr\n  dsimp [headEnvelope,summaryEnvelope,decay]\n  have hh := mul_le_mul_of_nonneg_left hi (show (0 : ℝ)≤2*n by positivity)\n  have hlog := Real.log_nonneg (show (1 : ℝ)≤2 by norm_num)\n  have hm := mul_le_mul_of_nonneg_right hh hlog\n  have hnon : (0 : ℝ)≤(n : ℝ)*(Nat.clog 2 (Nat.clog 2 n) : ℝ)^2 /\n      Real.sqrt (Nat.clog 2 n : ℝ)*Real.log 2 := by positivity\n  ring_nf at hm hnon ⊢\n  linarith\n\n/-- A fixed polynomial in the graph size is absorbed without a unit-cost\narithmetic premise. This is only the numerical envelope. -/\ntheorem polynomial_subexponential (d : ℕ) (ε : ℝ) (hε : 0<ε) :\n    ∀ᶠ n : ℕ in atTop, (n : ℝ)^d≤Real.exp (ε*(n : ℝ)) := by\n  have h := tendsto_natCast_atTop_atTop.eventually (eventually_polynomial_exp_rho_le (d : ℝ) 0 ε hε)\n  filter_upwards [h, eventually_ge_atTop (1 : ℕ)] with n hn hpos\n  simpa [Real.rpow_natCast] using hn\n\n/-- The actual growing-scope envelope is subexponential. -/\ntheorem scope_subexponential (ε : ℝ) (hε : 0<ε) :\n    ∀ᶠ n : ℕ in atTop,\n      Real.exp (512*(n : ℝ)^(3/4 : ℝ)*Real.log 2)≤Real.exp (ε*(n : ℝ)) := by\n  have h := tendsto_natCast_atTop_atTop.eventually (eventually_polynomial_counter_with_arity_le 0 0 (512*Real.log 2) ε hε)\n  filter_upwards [h, eventually_ge_atTop (1 : ℕ)] with n hn hpos\n  simpa [mul_assoc,mul_left_comm,mul_comm] using hn\n\n/-- Five actual resource components together satisfy every exponential target. -/\ntheorem budget_subexponential (d : ℕ) (ε : ℝ) (hε : 0<ε) :\n    ∀ᶠ n : ℕ in atTop, budget d n≤Real.exp (ε*(n : ℝ)) := by\n  have he : 0<ε/2 := by positivity\n  have hc := tendsto_natCast_atTop_atTop.eventually (eventually_constant_polynomial_exp_rho_le 5 0 0 (ε/2) he)\n  filter_upwards [polynomial_subexponential d (ε/2) he,\n    scheduled_support_subexponential (ε/2) he,summary_subexponential (ε/2) he,\n    eventually_head_le_summary,scope_subexponential (ε/2) he,hc] with n hp hs hy hh hw hc\n  have hhead := hh.trans hy\n  have hsum : budget d n≤5*Real.exp ((ε/2)*(n : ℝ)) := by dsimp [budget]; linarith\n  have hfive : (5 : ℝ)≤Real.exp ((ε/2)*(n : ℝ)) := by simpa using hc\n  calc\n    budget d n≤5*Real.exp ((ε/2)*(n : ℝ)) := hsum\n    _≤Real.exp ((ε/2)*(n : ℝ))*Real.exp ((ε/2)*(n : ℝ)) :=\n      mul_le_mul_of_nonneg_right hfive (Real.exp_nonneg _)\n    _=Real.exp (ε*(n : ℝ)) := by rw [← Real.exp_add]; congr 1; ring\n\n/-- Fixed powers, polynomial bit widths, and a fixed leading constant preserve\nsubexponential growth of the fully materialized resource budget. -/\ntheorem fixed_polynomial_subexponential (d a k : ℕ) (C ε : ℝ) (hε : 0<ε) :\n    ∀ᶠ n : ℕ in atTop,\n      C*(n : ℝ)^a*(budget d n)^k≤Real.exp (ε*(n : ℝ)) := by\n  let δ := ε/((k : ℝ)+1)\n  have hδ : 0<δ := by dsimp [δ]; positivity\n  have hp := tendsto_natCast_atTop_atTop.eventually\n    (eventually_constant_polynomial_exp_rho_le C (a : ℝ) 0 δ hδ)\n  filter_upwards [budget_subexponential d δ hδ,hp,eventually_ge_atTop (1 : ℕ)]\n    with n hs hp hn\n  have hbudget : 0≤budget d n := by\n    have hs0 : (0 : ℝ)≤SemiprimeCounterEnumeration.weightedCount n (cutoff n) := by positivity\n    have hy0 : 0 ≤ summaryEnvelope n := Real.exp_nonneg _\n    have hh0 : 0 ≤ headEnvelope n := Real.exp_nonneg _\n    dsimp only [budget]\n    positivity\n  have hpow : (budget d n)^k≤(Real.exp (δ*(n : ℝ)))^k := by gcongr\n  have hp' : C*(n : ℝ)^a≤Real.exp (δ*(n : ℝ)) := by\n    simpa [Real.rpow_natCast] using hp\n  calc\n    C*(n : ℝ)^a*(budget d n)^k≤\n        Real.exp (δ*(n : ℝ))*(budget d n)^k :=\n      mul_le_mul_of_nonneg_right hp' (pow_nonneg hbudget k)\n    _≤Real.exp (δ*(n : ℝ))*(Real.exp (δ*(n : ℝ)))^k :=\n      mul_le_mul_of_nonneg_left hpow (Real.exp_nonneg _)\n    _=Real.exp (ε*(n : ℝ)) := by\n      rw [← Real.exp_nat_mul,← Real.exp_add]\n      congr 1\n      dsimp [δ]\n      field_simp\n      ring\n\n/-- Literal public network size tends to infinity, from the proved input-edge\ninjection; this is not a separately supplied graph-size assumption. -/\ntheorem public_size_atTop : Tendsto SemiprimeMacroParameters.variableCount atTop atTop := by\n  apply tendsto_atTop_mono' atTop (f₁ := fun n : ℕ => n) ?_ tendsto_id\n  filter_upwards [eventually_ge_atTop (1 : ℕ)] with L hL\n  exact SemiprimeMacroParameters.input_le_variableCount (by omega)\n\n/-- Every fixed polynomial in the actual public aggregate is exponentially\nnegligible in the ORIGINAL input bit length. -/\ntheorem public_fixed_polynomial_subexponential (d a k : ℕ) (C ε : ℝ) (hε : 0<ε) :\n    ∀ᶠ L : ℕ in atTop,\n      C*(SemiprimeMacroParameters.variableCount L : ℝ)^a*\n        (budget d (SemiprimeMacroParameters.variableCount L))^k≤Real.exp (ε*(L : ℝ)) := by\n  have he : 0<ε/6400 := by positivity\n  filter_upwards [public_size_atTop.eventually\n    (fixed_polynomial_subexponential d a k C (ε/6400) he),eventually_ge_atTop (1 : ℕ)]\n    with L h hL\n  apply h.trans\n  apply Real.exp_le_exp.mpr\n  have hb : (SemiprimeMacroParameters.variableCount L : ℝ)≤6400*(L : ℝ) := by\n    exact_mod_cast SemiprimeMacroParameters.variableCount_le (show 0<L by omega)\n  nlinarith\n\n/-- The literal public summary cardinality is dominated by the acquired\nscheduled envelope, using the actual constructed rank theorem. -/\ntheorem public_summary_le {L : ℕ} (hL : 0<L)\n    (hg : sourceLayoutGuard (SemiprimeMacroParameters.variableCount L)\n      (SemiprimeMacroParameters.scopeBound L))\n    (hν : 64≤Nat.clog 2 (Nat.clog 2 (SemiprimeMacroParameters.variableCount L)))\n    (t : Fin (SemiprimeScheduledCounter.publicParameters hL hg).Q) :\n    (SemiprimeConstructedCounter.summaryCount\n      (SemiprimeScheduledCounter.publicParameters hL hg) t : ℝ)≤\n      summaryEnvelope (SemiprimeMacroParameters.variableCount L) := by\n  apply (Real.le_exp_log _).trans\n  apply Real.exp_le_exp.mpr\n  convert SemiprimeScheduledCounter.public_summary_log_bound hL hg hν t using 1\n  simp only [decay]\n  ring\n\n/-- Actual original-coordinate head cardinalities satisfy the scheduled bound;\nno independent small-head hypothesis is supplied. -/\ntheorem public_head_card_le {L : ℕ} (hL : 0<L)\n    (hg : sourceLayoutGuard (SemiprimeMacroParameters.variableCount L)\n      (SemiprimeMacroParameters.scopeBound L))\n    (t : Fin (SemiprimeScheduledCounter.publicParameters hL hg).Q)\n    (g : Fin (SemiprimeScheduledCounter.publicParameters hL hg).r) :\n    (Fintype.card {v // (SemiprimeConstructedCounter.layout\n      (SemiprimeScheduledCounter.publicParameters hL hg)).head t v=g} : ℚ)≤\n      3*(SemiprimeMacroParameters.variableCount L : ℚ)/\n        (2*(scheduledGroupCount (Nat.clog 2 (SemiprimeMacroParameters.variableCount L)) : ℚ)) := by\n  exact SemiprimeSourceLayout.builtLayout_head_bound _ _ _ _ _ 2\n    (SemiprimeMacroParameters.scopeBound L)\n    (SemiprimeScheduledCounter.packingGuard (SemiprimeMacroParameters.scopeBound L) hg\n      (SemiprimeScheduledCounter.public_occurrences hL) SemiprimeMacroParameters.actual_arity_le\n      (SemiprimeScheduledCounter.public_incidence_card hL)) t g\n\n\n/-- Literal per-node/per-head resource sum. Taking a maximum over the finitely\nmany nodes and heads has the same uniform upper bound proved below. -/\ndef actualBudget (d L : ℕ) (hL : 0<L)\n    (hg : sourceLayoutGuard (SemiprimeMacroParameters.variableCount L)\n      (SemiprimeMacroParameters.scopeBound L))\n    (t : Fin (SemiprimeScheduledCounter.publicParameters hL hg).Q)\n    (g : Fin (SemiprimeScheduledCounter.publicParameters hL hg).r) : ℝ :=\n  let n := SemiprimeMacroParameters.variableCount L\n  (n : ℝ)^d + SemiprimeCounterEnumeration.weightedCount n (cutoff n) +\n    SemiprimeConstructedCounter.summaryCount (SemiprimeScheduledCounter.publicParameters hL hg) t +\n    (2 : ℝ)^Fintype.card {v // (SemiprimeConstructedCounter.layout\n      (SemiprimeScheduledCounter.publicParameters hL hg)).head t v=g} +\n    (2 : ℝ)^SemiprimeMacroParameters.scopeBound L\n\n/-- Actual acquired summary cardinalities, actual head truth-table sizes and\nactual public scopes lie in the aggregate envelope. -/\ntheorem actualBudget_le (d L : ℕ) (hL : 0<L)\n    (hg : sourceLayoutGuard (SemiprimeMacroParameters.variableCount L)\n      (SemiprimeMacroParameters.scopeBound L))\n    (hν : 64≤Nat.clog 2 (Nat.clog 2 (SemiprimeMacroParameters.variableCount L)))\n    (t : Fin (SemiprimeScheduledCounter.publicParameters hL hg).Q)\n    (g : Fin (SemiprimeScheduledCounter.publicParameters hL hg).r) :\n    actualBudget d L hL hg t g≤budget d (SemiprimeMacroParameters.variableCount L) := by\n  have hy := public_summary_le hL hg hν t\n  have hh := public_head_card_le hL hg t g\n  have hhR :\n      (Fintype.card {v // (SemiprimeConstructedCounter.layout\n        (SemiprimeScheduledCounter.publicParameters hL hg)).head t v=g} : ℝ)≤\n        3*(SemiprimeMacroParameters.variableCount L : ℝ)/\n          (2*(scheduledGroupCount (Nat.clog 2 (SemiprimeMacroParameters.variableCount L)) : ℝ)) := by\n    simpa only [Rat.cast_div,Rat.cast_mul,Rat.cast_ofNat,Rat.cast_natCast] using\n      ((Rat.cast_le (K := ℝ)).mpr hh)\n  have hr : (0 : ℝ)<scheduledGroupCount (Nat.clog 2 (SemiprimeMacroParameters.variableCount L)) := by\n    exact_mod_cast (show 0<scheduledGroupCount (Nat.clog 2 (SemiprimeMacroParameters.variableCount L)) by\n      have := (scheduled_parameter_ranges hν).1; omega)\n  have hhead : (2 : ℝ)^Fintype.card {v // (SemiprimeConstructedCounter.layout\n      (SemiprimeScheduledCounter.publicParameters hL hg)).head t v=g}≤\n      headEnvelope (SemiprimeMacroParameters.variableCount L) := by\n    rw [← Real.rpow_natCast,Real.rpow_def_of_pos (by norm_num : (0 : ℝ)<2)]\n    apply Real.exp_le_exp.mpr\n    have hh' : (Fintype.card {v // (SemiprimeConstructedCounter.layout\n        (SemiprimeScheduledCounter.publicParameters hL hg)).head t v=g} : ℝ)≤\n        2*(SemiprimeMacroParameters.variableCount L : ℝ)/\n          scheduledGroupCount (Nat.clog 2 (SemiprimeMacroParameters.variableCount L)) := by\n      apply hhR.trans\n      apply (div_le_div_iff₀ (by positivity : (0 : ℝ)<2*scheduledGroupCount\n        (Nat.clog 2 (SemiprimeMacroParameters.variableCount L))) hr).mpr\n      nlinarith\n    have hm := mul_le_mul_of_nonneg_right hh' (Real.log_nonneg (show (1 : ℝ)≤2 by norm_num))\n    nlinarith\n  have hscope : (2 : ℝ)^SemiprimeMacroParameters.scopeBound L≤\n      Real.exp (512*(SemiprimeMacroParameters.variableCount L : ℝ)^(3/4 : ℝ)*Real.log 2) := by\n    rw [← Real.rpow_natCast,Real.rpow_def_of_pos (by norm_num : (0 : ℝ)<2)]\n    apply Real.exp_le_exp.mpr\n    have hm := mul_le_mul_of_nonneg_right (SemiprimeMacroParameters.scopeBound_le_variableCount_rpow hL)\n      (Real.log_nonneg (show (1 : ℝ)≤2 by norm_num))\n    nlinarith\n  dsimp only [actualBudget,budget]\n  linarith\n\n/-- The literal public sum, not independent supplied subexponential factors,\nretains every fixed polynomial overhead in the original bit length. -/\ntheorem actual_fixed_polynomial_subexponential (d a k : ℕ) (C ε : ℝ)\n    (hC : 0≤C) (hε : 0<ε) :\n    ∀ᶠ L : ℕ in atTop, ∀ (hL : 0<L)\n      (hg : sourceLayoutGuard (SemiprimeMacroParameters.variableCount L)\n        (SemiprimeMacroParameters.scopeBound L))\n      (t : Fin (SemiprimeScheduledCounter.publicParameters hL hg).Q)\n      (g : Fin (SemiprimeScheduledCounter.publicParameters hL hg).r),\n      C*(SemiprimeMacroParameters.variableCount L : ℝ)^a*(actualBudget d L hL hg t g)^k≤\n        Real.exp (ε*(L : ℝ)) := by\n  have hv := (tendsto_clog_two_atTop.comp tendsto_clog_two_atTop).comp public_size_atTop\n  filter_upwards [public_fixed_polynomial_subexponential d a k C ε hε,\n    hv.eventually (eventually_ge_atTop 64)] with L h hν\n  intro hL hg t g\n  apply le_trans ?_ h\n  have hb := actualBudget_le d L hL hg hν t g\n  have hn : 0≤actualBudget d L hL hg t g := by\n    dsimp only [actualBudget]\n    positivity\n  gcongr\n\n/-- Natural input bit length tends to infinity; no real-log surrogate is used\nwhen instantiating the actual public compiler. -/\ntheorem size_atTop : Tendsto Nat.size atTop atTop := by\n  apply tendsto_atTop.2\n  intro m\n  filter_upwards [eventually_ge_atTop (2^m)] with N hN\n  exact (Nat.lt_size.mpr hN).le\n\n/-- The proved public graph envelope, at its ACTUAL integer input bit length,\nis eventually below every positive power of the original input. -/\ntheorem public_fixed_polynomial_subpower (d a k : ℕ) (C ε : ℝ) (hε : 0<ε) :\n    ∀ᶠ N : ℕ in atTop,\n      C*(SemiprimeMacroParameters.variableCount N.size : ℝ)^a*\n        (budget d (SemiprimeMacroParameters.variableCount N.size))^k≤(N : ℝ)^ε := by\n  have hδ : 0<ε*Real.log 2/2 := by positivity\n  filter_upwards [size_atTop.eventually\n    (public_fixed_polynomial_subexponential d a k C (ε*Real.log 2/2) hδ),\n    eventually_ge_atTop (2 : ℕ)] with N h hN\n  have hpos : 0<N.size := Nat.size_pos.mpr (by omega)\n  have hlow : 2^(N.size-1)≤N := Nat.lt_size.mp (by omega)\n  have hl := Real.log_le_log (by positivity : (0 : ℝ)<2^(N.size-1))\n    (show (2 : ℝ)^(N.size-1)≤N by exact_mod_cast hlow)\n  rw [Real.log_pow,Nat.cast_sub hpos,Nat.cast_one] at hl\n  have hl2 : Real.log 2≤Real.log (N : ℝ) :=\n    Real.log_le_log (by norm_num) (by exact_mod_cast hN)\n  have hn : (0 : ℝ)<N := by positivity\n  apply h.trans\n  rw [Real.rpow_def_of_pos hn]\n  apply Real.exp_le_exp.mpr\n  nlinarith\n\n/-- In particular, any fixed polynomial resource ledger instantiated with the\nactual aggregate has a sixth-power numerical bound. This does not identify a\nprogram's clock with that ledger. -/\ntheorem public_fixed_polynomial_sixth (d a k : ℕ) (C : ℝ) :\n    ∀ᶠ N : ℕ in atTop,\n      C*(SemiprimeMacroParameters.variableCount N.size : ℝ)^a*\n        (budget d (SemiprimeMacroParameters.variableCount N.size))^k≤(N : ℝ)^(1/6 : ℝ) :=\n  public_fixed_polynomial_subpower d a k C (1/6) (by norm_num)\n\n/-- The original integer input's ACTUAL finite summary/head/scope sum has the\nsame subpower rate, uniformly over constructed source nodes and heads. -/\ntheorem actual_fixed_polynomial_subpower (d a k : ℕ) (C ε : ℝ)\n    (hC : 0≤C) (hε : 0<ε) :\n    ∀ᶠ N : ℕ in atTop, ∀ (hL : 0<N.size)\n      (hg : sourceLayoutGuard (SemiprimeMacroParameters.variableCount N.size)\n        (SemiprimeMacroParameters.scopeBound N.size))\n      (t : Fin (SemiprimeScheduledCounter.publicParameters hL hg).Q)\n      (g : Fin (SemiprimeScheduledCounter.publicParameters hL hg).r),\n      C*(SemiprimeMacroParameters.variableCount N.size : ℝ)^a*\n        (actualBudget d N.size hL hg t g)^k≤(N : ℝ)^ε := by\n  have hv := ((tendsto_clog_two_atTop.comp tendsto_clog_two_atTop).comp public_size_atTop).comp size_atTop\n  filter_upwards [public_fixed_polynomial_subpower d a k C ε hε,\n    hv.eventually (eventually_ge_atTop 64)] with N h hν\n  intro hL hg t g\n  apply le_trans ?_ h\n  have hb := actualBudget_le d N.size hL hg hν t g\n  have hn : 0≤actualBudget d N.size hL hg t g := by\n    dsimp only [actualBudget]\n    positivity\n  gcongr\n\n/-- Sixth-power rate for the literal acquired public resource sum, still only\nan analytic theorem until an executed clock is bounded by this expression. -/\ntheorem actual_fixed_polynomial_sixth (d a k : ℕ) (C : ℝ) (hC : 0≤C) :\n    ∀ᶠ N : ℕ in atTop, ∀ (hL : 0<N.size)\n      (hg : sourceLayoutGuard (SemiprimeMacroParameters.variableCount N.size)\n        (SemiprimeMacroParameters.scopeBound N.size))\n      (t : Fin (SemiprimeScheduledCounter.publicParameters hL hg).Q)\n      (g : Fin (SemiprimeScheduledCounter.publicParameters hL hg).r),\n      C*(SemiprimeMacroParameters.variableCount N.size : ℝ)^a*\n        (actualBudget d N.size hL hg t g)^k≤(N : ℝ)^(1/6 : ℝ) :=\n  actual_fixed_polynomial_subpower d a k C (1/6) hC (by norm_num)\n\nend RiemannGaussian.SemiprimeMaterializedRate\n","RiemannGaussian.SemiprimePaidRawAcquisition":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeCachedRawConstraints\nimport RiemannGaussian.SemiprimePaidSourceMetadata\nimport RiemannGaussian.SemiprimeEncodedRowSelection\n\n/-! # Actual cached source metadata and rows supply the raw design\nThe source search, integer family, row count and measurement bound are acquired\nbefore the raw design is exposed. Runtime callbacks read only retained data.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimePaidRawAcquisition\nopen OAI.Algorithms.SubexponentialSAT\nopen SemiprimeMaterializedSourceUniversal SemiprimeRuntimeDesignAcquisition\nvariable {n F r Q : ℕ} [NeZero r]\n\n/-- Original source data retained across every node/head selector call. -/\nstructure Snapshot (I : Type) (r Q : ℕ) where\n  /-- Cached original head and factor labels, including unowned coordinates. -/\n  metadata : SemiprimePaidSourceMetadata.Metadata r\n  /-- Fully acquired original integer entries. -/\n  family : SemiprimePaidConstraintAcquisition.Family I r Q\n  /-- Cached literal padded row count. -/\n  count : ℕ\n  /-- Cached source measurement bound. -/\n  bound : ℕ\n\n/-- Acquire both original searches, their output caches and the actual bound power. -/\ndef acquire (arity : Fin F → ℕ) (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (en : SemiprimeSourceLayout.Enumerations ((e : Fin F) × Fin (arity e)) (Fin n) (Fin F) r Q)\n    (eps : ℚ) (R B : ℕ) : Run (Snapshot ((e : Fin F) × Fin (arity e)) r Q) :=\n  let owner := fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2\n  let metadata := SemiprimePaidSourceMetadata.acquire owner Sigma.fst en eps\n  let family := SemiprimePaidOriginalConstraints.acquire owner Sigma.fst en eps R\n  let power := SemiprimeMaterializedSourceWords.powNatRun (8*Q) (2*R)\n  let count := family.value.indices.length\n  ⟨⟨metadata.value,family.value,count,B*2*power.value⟩,\n    metadata.work+family.work+power.work+count+12⟩\n\n/-- Raw data backed entirely by the acquired original caches. -/\ndef raw {I : Type} (snapshot : Snapshot I r Q) (t : Fin Q) : RawDesign n F :=\n  SemiprimeCachedRawConstraints.make\n    (SemiprimePaidSourceMetadata.head snapshot.metadata t)\n    (SemiprimePaidSourceMetadata.assigned snapshot.metadata t) snapshot.count\n    (fun g j v => (SemiprimeCachedRawConstraints.read\n      (SemiprimePaidSourceMetadata.head snapshot.metadata t) snapshot.family t g j.val v).value)\n    snapshot.bound\n\n/-- Actual masked cached read, with its work supplied to physical row acquisition. -/\ndef reader {I : Type} (snapshot : Snapshot I r Q) (t : Fin Q)\n    (g : Fin r) (j : Fin snapshot.count) (v : Fin n) : SemiprimeEncodedRowSelection.IntRun :=\n  let out := SemiprimeCachedRawConstraints.read\n    (SemiprimePaidSourceMetadata.head snapshot.metadata t) snapshot.family t g j.val v\n  ⟨out.value,out.work⟩\n\n/-- The report-bearing reader is the actual raw design's integer callback. -/\ntheorem reader_value {I : Type} (snapshot : Snapshot I r Q) (t : Fin Q)\n    (g : Fin r) (j : Fin snapshot.count) (v : Fin n) :\n    (reader snapshot t g j v).value=(raw (n:=n) (F:=F) snapshot t).rows g j v := rfl\n\n/-- The entire cached raw record equals the former searched record, including\nall outside-head zero columns and all original padded row indices. -/\ntheorem acquire_raw (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n) (eps : ℚ) (R B : ℕ) (t : Fin Q) :\n    raw (n:=n) (F:=F) (acquire arity coordinate (SemiprimeFiniteEnumerations.indexed n F r Q arity) eps R B).value t=\n      SemiprimeAcquiredSourceCounter.raw (r:=r) arity coordinate eps R B t := by\n  let en := SemiprimeFiniteEnumerations.indexed n F r Q arity\n  let owner := fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2\n  unfold acquire raw\n  dsimp only\n  rw [SemiprimeMaterializedSourceWords.powNatRun_value]\n  change SemiprimeCachedRawConstraints.data\n    (SemiprimePaidSourceMetadata.head (SemiprimePaidSourceMetadata.acquire owner Sigma.fst en eps).value t)\n    (SemiprimePaidSourceMetadata.assigned (SemiprimePaidSourceMetadata.acquire owner Sigma.fst en eps).value t)\n    (SemiprimePaidOriginalConstraints.acquire owner Sigma.fst en eps R).value\n    (SemiprimeAcquiredSourceCounter.measurementBound B Q R) t=_\n  exact SemiprimeCachedRawConstraints.data_eq arity coordinate eps R B t _ _\n    (SemiprimePaidSourceMetadata.head_acquire owner Sigma.fst en eps t)\n    (SemiprimePaidSourceMetadata.assigned_acquire owner Sigma.fst en eps t)\n\nomit [NeZero r] in\n/-- The acquired cardinality is the original padded row-list length. -/\ntheorem acquire_count (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (en : SemiprimeSourceLayout.Enumerations ((e : Fin F) × Fin (arity e)) (Fin n) (Fin F) r Q)\n    (eps : ℚ) (R B : ℕ) :\n    (acquire arity coordinate en eps R B).value.count=\n      (SemiprimeSourceConstraintAcquisition.rowIndices\n        (fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2) Sigma.fst en eps).values.length :=\n  SemiprimeCachedRawConstraints.acquired_count arity coordinate en eps R\n\n/-- Complete original-coordinate entry bounds transfer to the actual cached record. -/\ntheorem acquire_bounded (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n) (eps : ℚ) (R B : ℕ)\n    (howner : ∀ v, (Finset.univ.filter\n      (fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2=v)).card≤B)\n    (hQ : 1≤Q) (hAQ : Subexp.TailInterval.intervalStart r Q R≤Q) (t : Fin Q) :\n    ∀ g j v, |(raw (n:=n) (F:=F) (acquire arity coordinate\n      (SemiprimeFiniteEnumerations.indexed n F r Q arity) eps R B).value t).rows g j v|≤\n      ((raw (n:=n) (F:=F) (acquire arity coordinate\n        (SemiprimeFiniteEnumerations.indexed n F r Q arity) eps R B).value t).W g : ℤ) := by\n  rw [acquire_raw]\n  exact SemiprimeAcquiredSourceCounter.raw_bounded arity coordinate eps R B howner hQ hAQ t\n\n/-- Closed polynomial setup envelope with all separately executed searches retained. -/\ndef budget (n F r Q R M D A T N : ℕ) : ℕ :=\n  SemiprimePaidSourceMetadata.budget n F M D A T N Q+\n  SemiprimePaidOriginalConstraints.polynomial M n A D T N Q R\n    (Subexp.TailInterval.intervalStart r Q R) r+4*R+1+M*D+M+12\n\nomit [NeZero r] in\n/-- Full source-metadata, integer-family, count and bound-power acquisition ledger. -/\ntheorem acquire_work_native (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (en : SemiprimeSourceLayout.Enumerations ((e : Fin F) × Fin (arity e)) (Fin n) (Fin F) r Q)\n    (hr : 2≤r) (eps : ℚ) (R B : ℕ) :\n    (acquire arity coordinate en eps R B).work≤\n      budget n F r Q R en.incidences.values.length en.types.values.length en.wordTail.length\n        en.terms.values.length en.indices.values.length := by\n  let owner := fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2\n  have hm := SemiprimePaidSourceMetadata.acquire_work owner Sigma.fst en eps\n  have hf := SemiprimePaidOriginalConstraints.acquire_work_native owner Sigma.fst en hr eps R\n  have hc := SemiprimeCachedRawConstraints.acquired_count_le arity coordinate en eps R\n  dsimp only [owner] at hm hf\n  unfold acquire budget\n  dsimp only\n  rw [SemiprimeMaterializedSourceWords.powNatRun_work]\n  omega\n\n/-- A selector reads only stored data; no source search is repeated per entry. -/\ntheorem acquire_reader_work (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (en : SemiprimeSourceLayout.Enumerations ((e : Fin F) × Fin (arity e)) (Fin n) (Fin F) r Q)\n    (eps : ℚ) (R B : ℕ) (t : Fin Q) (g : Fin r)\n    (j : Fin (acquire arity coordinate en eps R B).value.count) (v : Fin n) :\n    (reader (acquire arity coordinate en eps R B).value t g j v).work≤\n      2*(Q+r+(acquire arity coordinate en eps R B).value.count+n)+14 := by\n  have hp := acquire_count arity coordinate en eps R B\n  have h := SemiprimeCachedRawConstraints.read_acquire_work arity coordinate en eps R\n    (SemiprimePaidSourceMetadata.head (acquire arity coordinate en eps R B).value.metadata t)\n    t g (j.cast hp) v\n  calc\n    _ ≤ 2*(Q+r+(SemiprimeSourceConstraintAcquisition.rowIndices\n      (fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2) Sigma.fst en eps).values.length+n)+14 := h\n    _ = _ := by rw [hp]\n\nend RiemannGaussian.SemiprimePaidRawAcquisition\n","RiemannGaussian.SemiprimePublicCounterBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeFullCounterBudget\nimport RiemannGaussian.SemiprimePublicBudgetDimensions\nimport RiemannGaussian.SemiprimeFullSetupScheduledController\n\n/-! # Uniform acquired-counter and public-controller budgets\nThe counter bound is derived from the original indexed graph and scheduled\npacking guards. No counter-report, head, rank, or summary budget is assumed.\nThe result closes the mixed retained-report premise, not a primitive-bit model.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2200000\nnamespace RiemannGaussian.SemiprimePublicCounterBudget\nopen scoped BigOperators\nopen SemiprimePublicAcquiredExecution SemiprimeScheduledFactorExecution\nopen SemiprimeMacroParameters SemiprimeIndexedDesignResources\n\n/-- Balanced actual-head upper bound used only where native execution needs it. -/\ndef headBound (N : ℕ) : ℕ := ⌈3*(wireCount N : ℚ)/(2*(groups N : ℚ))⌉₊\n\n/-- Parameter-only complete summary box, using the acquired total-rank budget. -/\ndef summaryBound (N : ℕ) : ℕ :=\n  (2*wireCount N*SemiprimeAcquiredSourceCounter.measurementBound 2 (points N) (degree N)+1)^\n    (4*wireCount N/(groups N*lambda N))\n\n/-- One original-input numerical envelope for every reachable prefix counter. -/\ndef counterBudget (N : ℕ) : ℕ :=\n  SemiprimeFullCounterBudget.budget (wireCount N) (factorCount N) (2*wireCount N)\n    (groups N) (points N) (degree N) 2 (precision N)\n    (SemiprimePublicBudgetDimensions.entryEnvelope (wireCount N))\n    (scopeBound (bitLength N)) (headBound N) (4*wireCount N) (summaryBound N)\n\n/-- The ACTUAL executed counter has one derived uniform bound over every\nreachable prefix; no counter-work or selected-resource premise remains. -/\ntheorem counter_work (N : ℕ) (hN : 0<N) (hg : fastGuard N) [NeZero (groups N)]\n    (fixed : List (Fin (wireCount N) × Bool)) (hf : fixed.length ≤ wireCount N) :\n    (SemiprimeFullSetupPublicController.counter N hN (groups N) (points N)\n      (epsilon N) (degree N) (precision N) fixed).work ≤ counterBudget N := by\n  let _ : NeZero (SemiprimeCounterRate.scheduledGroupCount (Nat.clog 2 (wireCount N))) :=\n    ⟨by change groups N ≠ 0; exact NeZero.ne (groups N)⟩\n  have hsource := fastGuard_source N hg\n  have hh := scheduled_head_bound (indexedArity N) (indexedCoordinate N hN)\n    (scopeBound (bitLength N)) hsource (indexed_occurrences N hN)\n    (indexedArity_le N) (indexed_incidence_count N hN)\n  have hm := scheduled_measurement_le (indexedArity N) (indexedCoordinate N hN)\n    (scopeBound (bitLength N)) hsource (indexed_occurrences N hN)\n    (indexedArity_le N) (indexed_incidence_count N hN)\n  have hy := scheduled_summary_bound (indexedArity N) (indexedCoordinate N hN)\n    (scopeBound (bitLength N)) hsource (indexed_occurrences N hN)\n    (indexedArity_le N) (indexed_incidence_count N hN)\n  have hT (e : Fin (factorCount N)) (eta : Fin (indexedArity N e) → Bool) :\n      (SemiprimeAcquiredPrefixSearch.entry (indexedArity N) (indexedCoordinate N hN)\n        (indexedEntry N hN) fixed e eta).arithmetic ≤\n          SemiprimePublicBudgetDimensions.entryEnvelope (wireCount N) ∧\n      (SemiprimeAcquiredPrefixSearch.entry (indexedArity N) (indexedCoordinate N hN)\n        (indexedEntry N hN) fixed e eta).reads ≤\n          SemiprimePublicBudgetDimensions.entryEnvelope (wireCount N) := by\n    have ht := SemiprimeFullSetupPublicController.entry_work_le N hN fixed hf e eta\n    have hb := SemiprimePublicBudgetDimensions.entryBudget_le N hN\n    exact ⟨ht.1.trans hb,ht.2.trans hb⟩\n  have h := SemiprimeFullCounterBudget.count_work (r:=groups N) (Q:=points N)\n    (indexedArity N) (indexedCoordinate N hN) (epsilon N) (degree N) 2 (precision N)\n    (SemiprimePublicBudgetDimensions.entryEnvelope (wireCount N))\n    (scopeBound (bitLength N)) (headBound N) (4*wireCount N) (summaryBound N)\n    (SemiprimeAcquiredPrefixSearch.entry (indexedArity N) (indexedCoordinate N hN)\n      (indexedEntry N hN) fixed)\n    hg.2.2.1 (indexed_occurrences N hN)\n    (Nat.le_trans (by decide : 1 ≤ 2) hg.2.2.2.1) (guard_interval N hg)\n    hh hm hy (indexedArity_le N) hT\n  simpa only [SemiprimeFullSetupPublicController.counter,counterBudget,\n    indexed_incidence_count N hN] using h\n\n/-- Complete derived fast-branch report envelope, including repeated setup for\nevery query and the actual decoder/controller terms. -/\ndef controllerBudget (N : ℕ) : ℕ :=\n  (wireCount N+1)*(counterBudget N+wireCount N+3*(wireCount N+1)^2+\n    SemiprimePublicBudgetDimensions.decoderEnvelope (wireCount N)+19)\n\n/-- The public fast controller no longer assumes an unexplained count budget B. -/\ntheorem run_work (N : ℕ) (hN : 0<N) (hg : fastGuard N) [NeZero (groups N)] :\n    (SemiprimeFullSetupScheduledController.run N).work ≤ controllerBudget N := by\n  have h := SemiprimeFullSetupScheduledController.run_fast_work N hN hg (counterBudget N)\n    (fun fixed hf => counter_work N hN hg fixed hf)\n  have hd := SemiprimePublicBudgetDimensions.decoderBudget_le N hN (wireCount N) (le_refl _)\n  exact h.trans (by unfold controllerBudget; gcongr)\n\n/-- Every sufficiently large input executes under the derived public envelope.\nThis is a bound on the retained mixed report, not yet a primitive bit theorem. -/\ntheorem eventually_run_work :\n    ∀ᶠ N : ℕ in Filter.atTop, (SemiprimeFullSetupScheduledController.run N).work ≤ controllerBudget N := by\n  filter_upwards [eventually_fastGuard,Filter.eventually_gt_atTop 0] with N hg hN\n  let _ : NeZero (groups N) := ⟨Nat.ne_of_gt (guard_groups_pos N hg)⟩\n  exact run_work N hN hg\n\nend RiemannGaussian.SemiprimePublicCounterBudget\n","RiemannGaussian.SemiprimePublicCounterResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimePublicCounterBudget\nimport RiemannGaussian.SemiprimeMaterializedRate\n\n/-! # Closed exponential resources of the actual public counter\nOnly parameter envelopes are compared to the established rate functions.\nNo default-layout identity or complete primitive machine clock is asserted.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nnoncomputable section\nnamespace RiemannGaussian.SemiprimePublicCounterResources\nopen scoped BigOperators\nopen SemiprimePublicCounterBudget SemiprimePublicAcquiredExecution\nopen SemiprimeScheduledFactorExecution SemiprimeCounterRate SemiprimeSourceLayoutRate\nopen SemiprimeMacroParameters SemiprimeMaterializedRate\n\n/-- The literal closed floor-power envelope lies below the real rate envelope. -/\ntheorem closed_summary_le {n : ℕ} (hν : 64≤ Nat.clog 2 (Nat.clog 2 n)) :\n    ((sourceSignatureBase n^\n      (4*n/(scheduledGroupCount (Nat.clog 2 n)*Nat.clog 2 n)):ℕ):ℝ)≤ summaryEnvelope n := by\n  have hlog := SemiprimeIndexedDesignResources.summary_envelope_log hν\n  have hp : (0:ℝ)<((sourceSignatureBase n^\n      (4*n/(scheduledGroupCount (Nat.clog 2 n)*Nat.clog 2 n)):ℕ):ℝ) := by\n    exact_mod_cast (pow_pos (show 0< sourceSignatureBase n by unfold sourceSignatureBase; omega) _)\n  apply (Real.log_le_iff_le_exp hp).mp\n  convert hlog using 1\n  dsimp [summaryEnvelope,decay]\n  ring\n\n/-- The actual public summary envelope is the closed indexed envelope above. -/\ntheorem summaryBound_le (N : ℕ) (hν : 64≤ Nat.clog 2 (Nat.clog 2 (wireCount N))) :\n    (summaryBound N:ℝ)≤ summaryEnvelope (wireCount N) := by\n  simpa only [summaryBound,groups,points,degree,lambda,sourceSignatureBase,sourceHeight,\n    SemiprimeAcquiredSourceCounter.measurementBound] using closed_summary_le (n:=wireCount N) hν\n\n/-- Rounding a balanced head costs at most the gap between 3/2 and 2,\nprovided the actual input has at least two coordinates per group. -/\ntheorem ceil_head_le {n r : ℕ} (hr : 0< r) (hnr : 2*r≤ n) :\n    (⌈3*(n:ℚ)/(2*(r:ℚ))⌉₊:ℝ)≤2*(n:ℝ)/(r:ℝ) := by\n  have hrq : (0:ℚ)< r := by exact_mod_cast hr\n  have hnrq : 2*(r:ℚ)≤ n := by exact_mod_cast hnr\n  have hc := Nat.ceil_lt_add_one (show (0:ℚ)≤3*(n:ℚ)/(2*(r:ℚ)) by positivity)\n  have hm := mul_le_mul_of_nonneg_right (le_of_lt hc) (le_of_lt hrq)\n  have he1 : (3*(n:ℚ)/(2*(r:ℚ)))*(2*(r:ℚ))=3*(n:ℚ) :=\n    div_mul_cancel₀ _ (by positivity)\n  have he2 : (2*(n:ℚ)/(r:ℚ))*(r:ℚ)=2*(n:ℚ) := div_mul_cancel₀ _ (ne_of_gt hrq)\n  have hq : (⌈3*(n:ℚ)/(2*(r:ℚ))⌉₊:ℚ)≤2*(n:ℚ)/(r:ℚ) := by\n    apply (le_div_iff₀ hrq).mpr\n    nlinarith\n  have hcR := (Rat.cast_le (K:=ℝ)).mpr hq\n  simpa only [Rat.cast_natCast,Rat.cast_div,Rat.cast_mul,Rat.cast_ofNat] using hcR\n\n/-- The actual fast guard pays enough headroom for the ceiling. -/\ntheorem fast_headroom (N : ℕ) (hg : fastGuard N) : 2*groups N≤ wireCount N := by\n  rcases hg with ⟨hn,hw,hr,hQ,hR,hs,he,heh,hl,hh,hwidth,hload⟩\n  have hrr : groups N≤ groups N^2 := by nlinarith only [hr]\n  calc\n    2*groups N≤16*groups N^2 := by nlinarith only [hrr]\n    _ ≤16*points N*groups N^2 := by gcongr; omega\n    _ ≤ wireCount N := hh\n\n/-- The literal native 2^H factor fits the known head envelope. -/\ntheorem headBound_le (N : ℕ) (hg : fastGuard N) :\n    ((2:ℕ)^headBound N:ℝ)≤ headEnvelope (wireCount N) := by\n  have hh := ceil_head_le (guard_groups_pos N hg) (fast_headroom N hg)\n  change (headBound N:ℝ)≤2*(wireCount N:ℝ)/(groups N:ℝ) at hh\n  norm_num only [Nat.cast_ofNat]\n  rw [← Real.rpow_natCast,\n    Real.rpow_def_of_pos (by norm_num : (0:ℝ)<2)]\n  apply Real.exp_le_exp.mpr\n  have hm := mul_le_mul_of_nonneg_right hh (Real.log_nonneg (show (1:ℝ)≤2 by norm_num))\n  simpa only [headEnvelope,groups,lambda,mul_comm] using hm\n\n/-- Original growing arity, with the ACTUAL public wire count in the exponent. -/\ntheorem scopeBound_le (N : ℕ) (hN : 0< N) :\n    ((2:ℕ)^scopeBound (bitLength N):ℝ)≤\n      Real.exp (512*(wireCount N:ℝ)^(3/4:ℝ)*Real.log 2) := by\n  have hs := scopeBound_le_variableCount_rpow (bitLength_pos hN)\n  rw [← wireCount_eq N] at hs\n  norm_num only [Nat.cast_ofNat]\n  rw [← Real.rpow_natCast,\n    Real.rpow_def_of_pos (by norm_num : (0:ℝ)<2)]\n  apply Real.exp_le_exp.mpr\n  have hm := mul_le_mul_of_nonneg_right hs (Real.log_nonneg (show (1:ℝ)≤2 by norm_num))\n  simpa only [mul_comm] using hm\n\n/-- The actual finite precision uses exactly the established inclusive cutoff. -/\ntheorem supportCount_eq (N : ℕ) :\n    SemiprimeCounterEnumeration.weightedCount (wireCount N) (precision N-1)=\n      SemiprimeCounterEnumeration.weightedCount (wireCount N)\n        (SemiprimeScheduledSupportRate.cutoff (wireCount N)) := by\n  simp only [precision_formula,SemiprimeScheduledSupportRate.cutoff,Nat.add_sub_cancel]\n\nend RiemannGaussian.SemiprimePublicCounterResources\n","RiemannGaussian.SemiprimeRHCancellation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSquareProductCover\nimport Mathlib.Algebra.BigOperators.Ring.Finset\n\n/-!\n# Signed-product cancellation with the original row targets retained\n\nThe RH proof's `ZetaRieszPrimeFourier.divisorCharacter_eq_primeProduct`\nuses signed subset expansion to replace a complete divisor character by\nits Euler factors. Here the same finite ring algebra is applied to the\noriginal collision differences. Its product retains every prime-field\ncollision; using row increments as the Euler factors tests something else.\n\nRemoving a row's centre phase preserves its collision only if the target\nis rephased too. A mixed difference then has a small separable axis term\nAND the exact mixed centre-power term. A kernel-checked semiprime control\nshows that even retaining this latter term in a signed sum can erase an\noriginal proper hit. The collision product keeps that hit.\n\nThese identities do not bound the cost of constructing the coupled centres\nor computing the full collision product. They prove no factoring exponent.\n-/\n\nnamespace RiemannGaussian.SemiprimeRHCancellation\n\nopen scoped BigOperators\n\n/-- Original row differences, with their common target unchanged. -/\ndef collisionProduct {R ι : Type*} [CommRing R]\n    (S : Finset ι) (r : ι → R) (t : R) : R := ∏ j ∈ S, (r j-t)\n\n/-- The complete signed subset expansion retains every target factor.\nIt is a mathematical expansion, not an algorithm that enumerates subsets. -/\ntheorem collisionProduct_eq_subset_expansion {R ι : Type*} [CommRing R]\n    [DecidableEq ι] (S : Finset ι) (r : ι → R) (t : R) :\n    collisionProduct S r t =\n      ∑ J ∈ S.powerset, (∏ j ∈ J, r j) * (-t)^((S \\ J).card) := by\n  classical\n  simp only [collisionProduct, sub_eq_add_neg]\n  rw [Finset.prod_add]\n  simp only [Finset.prod_const]\n\n/-- Over a hidden prime field the product detects exactly the union\nof the original target collisions, including repeated row values. -/\ntheorem collisionProduct_map_zero_iff {R F ι : Type*} [CommRing R]\n    [CommRing F] [IsDomain F] (φ : R →+* F)\n    (S : Finset ι) (r : ι → R) (t : R) :\n    φ (collisionProduct S r t) = 0 ↔ ∃ j ∈ S, φ (r j) = φ t := by\n  classical\n  simp only [collisionProduct, map_prod, map_sub, Finset.prod_eq_zero_iff, sub_eq_zero]\n\n/-- The Euler-factor normalization removes only an invertible common\ntarget. The factors are the original rows, not their phase increments. -/\ntheorem collisionProduct_eq_euler_product {R ι : Type*} [CommRing R]\n    (S : Finset ι) (r : ι → R) (t : Rˣ) :\n    collisionProduct S r (t : R) =\n      (-(t : R))^S.card * ∏ j ∈ S, (1-r j*((t⁻¹ : Rˣ) : R)) := by\n  have h (j : ι) : r j-(t : R) =\n      (-(t : R))*(1-r j*((t⁻¹ : Rˣ) : R)) := by\n    have ht : (t : R)*((t⁻¹ : Rˣ) : R)=1 := by simp\n    linear_combination -(r j)*ht\n  simp_rw [collisionProduct, h]\n  rw [Finset.prod_mul_distrib, Finset.prod_const]\n\n/-- Euler expansion collapses the complete signed subset character\nto its listed atomic factors over any commutative ring. -/\ntheorem signedSubsetSum_eq_euler_product {R ι : Type*} [CommRing R]\n    (S : Finset ι) (z : ι → R) :\n    (∑ J ∈ S.powerset, (-1 : R)^J.card * ∏ j ∈ J, z j) =\n      ∏ j ∈ S, (1-z j) := by\n  classical\n  have h := Finset.prod_one_add (f := fun j => -z j) S\n  simpa only [sub_eq_add_neg, Finset.prod_neg] using h.symm\n\n/-- The short signed-subset circuit vanishes exactly when an ATOMIC\nfactor equals one. It is not a test for an arbitrary original subset row. -/\ntheorem signedSubsetSum_zero_iff {R ι : Type*} [CommRing R] [IsDomain R]\n    (S : Finset ι) (z : ι → R) :\n    (∑ J ∈ S.powerset, (-1 : R)^J.card * ∏ j ∈ J, z j) = 0 ↔\n      ∃ j ∈ S, z j = 1 := by\n  classical\n  rw [signedSubsetSum_eq_euler_product]\n  simp only [Finset.prod_eq_zero_iff, sub_eq_zero]\n  constructor\n  · rintro ⟨j, hj, he⟩\n    exact ⟨j, hj, he.symm⟩\n  · rintro ⟨j, hj, he⟩\n    exact ⟨j, hj, he.symm⟩\n\n/-- Multiplying every original difference by its own unit phase\nretains its product up to one unit, without discarding a target channel. -/\ntheorem collisionProduct_rephase {R ι : Type*} [CommRing R]\n    (S : Finset ι) (r : ι → R) (t : R) (u : ι → Rˣ) :\n    (∏ j ∈ S, ((u j : R)*r j-(u j : R)*t)) =\n      (∏ j ∈ S, (u j : R))*collisionProduct S r t := by\n  simp only [← mul_sub, Finset.prod_mul_distrib, collisionProduct]\n\n/-- Multiplication by a public unit preserves the entire GCD signal,\nincluding prime powers and aggregate saturation, for every modulus. -/\ntheorem unit_mul_gcd_eq {n : ℕ} (u : (ZMod n)ˣ) (x : ZMod n) :\n    n.gcd ((u : ZMod n)*x).val=n.gcd x.val := by\n  rw [ZMod.val_mul]\n  calc\n    n.gcd ((u : ZMod n).val*x.val % n) =\n        ((u : ZMod n).val*x.val % n).gcd n := Nat.gcd_comm _ _\n    _ = n.gcd ((u : ZMod n).val*x.val) := (Nat.gcd_rec _ _).symm\n    _ = n.gcd x.val := by\n      rw [Nat.gcd_comm n _, Nat.gcd_comm n x.val]\n      exact (ZMod.val_coe_unit_coprime u).gcd_mul_left_cancel x.val\n\n/-- Applying the RH-style Euler normalization to the original row\ndifferences preserves the exact GCD for every modulus, including squares.\nThere is no new assumption about the unknown local orders. -/\ntheorem collisionProduct_euler_gcd_eq {n : ℕ} {ι : Type*}\n    (S : Finset ι) (r : ι → ZMod n) (t : (ZMod n)ˣ) :\n    n.gcd (collisionProduct S r (t : ZMod n)).val=\n      n.gcd (∏ j ∈ S, (1-r j*((t⁻¹ : (ZMod n)ˣ) : ZMod n))).val := by\n  have he : (((-t)^S.card : (ZMod n)ˣ) : ZMod n)=(-(t : ZMod n))^S.card := by simp\n  rw [collisionProduct_eq_euler_product, ← he]\n  exact unit_mul_gcd_eq ((-t)^S.card) _\n\n/-- Public centre normalization, with the same normalization applied\nto the baby target. There is no hidden-prime input. -/\ndef rephasedResidual {R : Type*} [CommRing R]\n    (g : Rˣ) (N a b c : ℤ) (t : R) : R :=\n  ((g^(a*N+b) : Rˣ) : R)-t*((g^c : Rˣ) : R)\n\n/-- Exact common-phase extraction retains the coupled centre power\nin the transformed target. -/\ntheorem rephasedResidual_eq {R : Type*} [CommRing R]\n    (g : Rˣ) (N a b c : ℤ) (t : R) :\n    rephasedResidual g N a b c t =\n      ((g^c : Rˣ) : R)*((SemiprimeRowStructure.rowAnchor (G := Rˣ) g N a b c : R)-t) := by\n  have h : g^c*SemiprimeRowStructure.rowAnchor g N a b c=g^(a*N+b) := by\n    simp only [SemiprimeRowStructure.rowAnchor, ← zpow_add]\n    congr 1\n    ring\n  have hv := congrArg (fun x : Rˣ => (x : R)) h\n  simp only [Units.val_mul] at hv\n  unfold rephasedResidual\n  rw [← hv]\n  ring\n\n/-- Rephasing preserves each individual collision over every nonzero\nprime-field image. It does not authorize summing different residuals. -/\ntheorem rephasedResidual_map_zero_iff {R F : Type*} [CommRing R]\n    [CommRing F] [IsDomain F] (φ : R →+* F)\n    (g : Rˣ) (N a b c : ℤ) (t : R) :\n    φ (rephasedResidual g N a b c t) = 0 ↔\n      φ (SemiprimeRowStructure.rowAnchor (G := Rˣ) g N a b c : R) = φ t := by\n  rw [rephasedResidual_eq, map_mul, map_sub]\n  have hne : φ ((g^c : Rˣ) : R) ≠ 0 :=\n    (Units.map φ.toMonoidHom (g^c)).ne_zero\n  rw [mul_eq_zero_iff_left hne, sub_eq_zero]\n\n/-- The target-preserving row normalization keeps the exact public GCD,\nwithout a squarefree-modulus or hidden-prime assumption. -/\ntheorem rephasedResidual_gcd_eq {n : ℕ} (g : (ZMod n)ˣ)\n    (N a b c : ℤ) (t : ZMod n) :\n    n.gcd (rephasedResidual g N a b c t).val=\n      n.gcd ((SemiprimeRowStructure.rowAnchor (G := (ZMod n)ˣ) g N a b c : ZMod n)-t).val := by\n  rw [rephasedResidual_eq]\n  exact unit_mul_gcd_eq (g^c) _\n\n/-- The two-dimensional signed difference cancels the axis powers\ninto a short Euler product. The exact centre-power companion survives.\nEven this complete signed value need not preserve an individual hit. -/\ntheorem rephasedResidual_mixed_difference {R : Type*} [CommRing R]\n    (g : Rˣ) (N a b u v c00 c01 c10 c11 : ℤ) (t : R) :\n    rephasedResidual g N a b c00 t-\n      rephasedResidual g N a (b+v) c01 t-\n      rephasedResidual g N (a+u) b c10 t+\n      rephasedResidual g N (a+u) (b+v) c11 t =\n      ((g^(a*N+b) : Rˣ) : R)*\n        (((g^(u*N) : Rˣ) : R)-1)*(((g^v : Rˣ) : R)-1)-\n      t*(((g^c00 : Rˣ) : R)-((g^c01 : Rˣ) : R)-\n        ((g^c10 : Rˣ) : R)+((g^c11 : Rˣ) : R)) := by\n  have h01 : g^(a*N+(b+v)) = g^(a*N+b)*g^v := by rw [← zpow_add]; congr 1; ring\n  have h10 : g^((a+u)*N+b) = g^(a*N+b)*g^(u*N) := by rw [← zpow_add]; congr 1; ring\n  have h11 : g^((a+u)*N+(b+v)) = g^(a*N+b)*g^(u*N)*g^v := by\n    rw [← zpow_add, ← zpow_add]\n    congr 1\n    ring\n  simp only [rephasedResidual, h01, h10, h11, Units.val_mul]\n  ring\n\n/-- A complete two-block divisor orbit has one common product centre.\nIts signed multiplicative ratio removes that centre exactly, leaving\nonly an N+1 projected-period test. No factor of the input is supplied. -/\ntheorem rowAnchor_block_divisor_ratio {G : Type*} [CommGroup G]\n    (g : G) (N r s c : ℤ) :\n    (SemiprimeRowStructure.rowAnchor g N 1 (r*s) c*\n        SemiprimeRowStructure.rowAnchor g N (r*s) 1 c)/\n      (SemiprimeRowStructure.rowAnchor g N r s c*\n        SemiprimeRowStructure.rowAnchor g N s r c) =\n      g^((r-1)*(s-1)*(N+1)) := by\n  simp only [SemiprimeRowStructure.rowAnchor, ← zpow_add]\n  rw [div_eq_mul_inv, ← zpow_neg, ← zpow_add]\n  congr 1\n  ring\n\n/-- The short common-centre orbit signal is precisely an order\ndivisibility condition, rather than the union of its original row hits. -/\ntheorem block_divisor_ratio_eq_one_iff {G : Type*} [CommGroup G]\n    (g : G) (N r s c : ℤ) :\n    (SemiprimeRowStructure.rowAnchor g N 1 (r*s) c*\n        SemiprimeRowStructure.rowAnchor g N (r*s) 1 c)/\n      (SemiprimeRowStructure.rowAnchor g N r s c*\n        SemiprimeRowStructure.rowAnchor g N s r c) = 1 ↔\n      (orderOf g : ℤ) ∣ (r-1)*(s-1)*(N+1) := by\n  rw [rowAnchor_block_divisor_ratio, orderOf_dvd_iff_zpow_eq_one]\n\n/-- Public positive-exponent form of the literal rephased row.\nExact integer square roots are used in its centre. -/\ndef literalResidual (N g a b i : ℕ) : ZMod N :=\n  (g : ZMod N)^(a*N+b)-\n    (g : ZMod N)^(SemiprimeLehmanCoverage.literalCentre N (a*b))*(g : ZMod N)^i\n\nset_option maxRecDepth 32768 in\n/-- A genuine offset-zero weighted row outside the small-factor\nprefix has a proper GCD after rephasing. Its centre is literal. -/\ntheorem control_literal_row_hit :\n    SemiprimeLehmanCoverage.literalCentre 3036046577 (12*17)=1573981 ∧\n      12*65521+17*46337=1573981 ∧\n      (literalResidual 3036046577 2 12 17 0).val=2754363954 ∧\n      Nat.gcd 3036046577 (literalResidual 3036046577 2 12 17 0).val=46337 := by\n  norm_num [literalResidual, SemiprimeLehmanCoverage.literalCentre,\n    SemiprimeLehmanCoverage.ceilSqrt]\n  reduce_mod_char\n  norm_num [ZMod.val_ofNat]\n\nset_option maxRecDepth 32768 in\n/-- Keeping the centre companion in the signed four-corner sum still\nloses the original proper hit. The centre-free axis product is also a unit. -/\ntheorem control_mixed_difference_misses :\n    Nat.gcd 3036046577\n      (literalResidual 3036046577 2 12 17 0-\n        literalResidual 3036046577 2 12 19 0-\n        literalResidual 3036046577 2 13 17 0+\n        literalResidual 3036046577 2 13 19 0).val=1 ∧\n      Nat.gcd 3036046577\n        (((2 : ZMod 3036046577)^(12*3036046577+17))*\n          ((2 : ZMod 3036046577)^3036046577-1)*((2 : ZMod 3036046577)^2-1)).val=1 := by\n  norm_num [literalResidual, SemiprimeLehmanCoverage.literalCentre,\n    SemiprimeLehmanCoverage.ceilSqrt]\n  reduce_mod_char\n  norm_num [ZMod.val_ofNat]\n\nset_option maxRecDepth 32768 in\n/-- The original four collision factors keep the proper prime signal\non the same exact block, before any signed-amplitude collapse. -/\ntheorem control_collision_product_preserves_hit :\n    Nat.gcd 3036046577\n      (literalResidual 3036046577 2 12 17 0*\n        literalResidual 3036046577 2 12 19 0*\n        literalResidual 3036046577 2 13 17 0*\n        literalResidual 3036046577 2 13 19 0).val=46337 := by\n  norm_num [literalResidual, SemiprimeLehmanCoverage.literalCentre,\n    SemiprimeLehmanCoverage.ceilSqrt]\n  reduce_mod_char\n  norm_num [ZMod.val_ofNat]\n\n/-- All four control rows are primitive and belong to the full\nweight budget. The witness is not an artefact of a nonprimitive row. -/\ntheorem control_primitive_weight_budget :\n    Nat.Coprime 12 17 ∧ Nat.Coprime 12 19 ∧\n      Nat.Coprime 13 17 ∧ Nat.Coprime 13 19 ∧ 13*19 ≤ 39^2 := by norm_num\n\nset_option maxRecDepth 32768 in\n/-- The exact common-centre divisor cancellation can lose BOTH\nproper prime signals on a genuine weighted-hit control. -/\ntheorem control_divisor_orbit_ratio_misses :\n    Nat.gcd 3036046577\n      (((2 : ZMod 3036046577)^((12-1)*(17-1)*(3036046577+1))-1).val)=1 ∧\n      Nat.gcd 3036046577 (literalResidual 3036046577 2 17 12 0).val=65521 := by\n  norm_num [literalResidual, SemiprimeLehmanCoverage.literalCentre,\n    SemiprimeLehmanCoverage.ceilSqrt]\n  reduce_mod_char\n  norm_num [ZMod.val_ofNat]\n\nend RiemannGaussian.SemiprimeRHCancellation\n","RiemannGaussian.SemiprimeRowStructure":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeOrderSeparation\nimport Mathlib.Tactic.Group\n\n/-!\n# Common structure of weighted factor-sum rows\n\nThe centre depends on the product of the weights. Its exponential is the\ncoupled part left after the two axis powers have been shared. A four-corner\nidentity tests exactly whether a proposed separable batch is valid in a\ngroup; a collapse in only one prime component is already a separating signal.\n\nThese are algebraic identities, not a coverage or bit-complexity theorem.\nThis side-investigation algebra is checked in the ordinary library; numerical probes remain optional.\n-/\n\nnamespace RiemannGaussian.SemiprimeRowStructure\n\n/-- Weighted anchor, before any loss of the two weight indices. -/\ndef rowAnchor {G : Type*} [CommGroup G]\n    (g : G) (N a b centre : ℤ) : G := g ^ (a*N+b-centre)\n\n/-- A product-group cache preserves each literal anchor exactly. -/\ntheorem rowAnchor_factor {G : Type*} [CommGroup G]\n    (g : G) (N a b centre : ℤ) :\n    rowAnchor g N a b centre = (g^N)^a * g^b * (g⁻¹)^centre := by\n  simp only [rowAnchor, ← zpow_mul, inv_zpow, ← zpow_neg, ← zpow_add]\n  congr 1\n  ring\n\n/-- The normalized four-corner defect contains only the four centres.\nThe large N-dependent axis powers cancel before the test. -/\ntheorem rowAnchor_cross_ratio {G : Type*} [CommGroup G]\n    (g : G) (N a a' b b' c00 c01 c10 c11 : ℤ) :\n    (rowAnchor g N a b c00 * rowAnchor g N a' b' c11) /\n      (rowAnchor g N a b' c01 * rowAnchor g N a' b c10) =\n      g ^ (c01+c10-c00-c11) := by\n  simp only [rowAnchor, ← zpow_add]\n  rw [div_eq_mul_inv, ← zpow_neg, ← zpow_add]\n  congr 1\n  ring\n\n/-- An exact local test for separability; approximate real centres do not\nlicense replacing a modular anchor matrix by an outer product. -/\ntheorem rowAnchor_cross_eq_iff {G : Type*} [CommGroup G]\n    (g : G) (N a a' b b' c00 c01 c10 c11 : ℤ) :\n    rowAnchor g N a b c00 * rowAnchor g N a' b' c11 =\n      rowAnchor g N a b' c01 * rowAnchor g N a' b c10 ↔\n      g ^ (c01+c10-c00-c11) = 1 := by\n  rw [← div_eq_one, rowAnchor_cross_ratio]\n\n/-- The centre-curvature test is precisely a local-order divisibility test.\nIt is not a guarantee that any tested curvature has the required divisor. -/\ntheorem rowAnchor_cross_eq_iff_order_dvd {G : Type*} [CommGroup G]\n    (g : G) (N a a' b b' c00 c01 c10 c11 : ℤ) :\n    rowAnchor g N a b c00 * rowAnchor g N a' b' c11 =\n      rowAnchor g N a b' c01 * rowAnchor g N a' b c10 ↔\n      (orderOf g : ℤ) ∣ c01+c10-c00-c11 := by\n  rw [rowAnchor_cross_eq_iff, orderOf_dvd_iff_zpow_eq_one]\n\n/-- A four-corner collapse in just one prime component immediately factors\nthe input; there is no need to build the large row collision polynomial. -/\ntheorem centre_defect_separates {p q signal : ℕ} (hq : q.Prime)\n    (hp : p ∣ signal) (hnq : ¬q ∣ signal) :\n    Nat.gcd (p*q) signal = p := by\n  exact SemiprimeOrderSeparation.gcd_semiprime_of_separating_residue hq hp hnq\n\n/-- Swapping the two weight indices cancels their common centre exactly.\nAll such ratios depend only on the weight difference, not on its product. -/\ntheorem rowAnchor_swap_ratio {G : Type*} [CommGroup G]\n    (g : G) (N a b centre : ℤ) :\n    rowAnchor g N a b centre / rowAnchor g N b a centre =\n      g ^ ((a-b)*(N-1)) := by\n  simp only [rowAnchor]\n  rw [div_eq_mul_inv, ← zpow_neg, ← zpow_add]\n  congr 1\n  ring\n\n/-- The raw signed difference retains an invertible common prefix.\nThis is the ring version of shared-phase cancellation; the resulting\nsignal is exactly the N-1 projected-period signal. -/\ntheorem rowAnchor_swap_difference {K : Type*} [CommRing K]\n    (g : Kˣ) (N a b centre : ℤ) :\n    (rowAnchor (G := Kˣ) g N a b centre : K) -\n      (rowAnchor (G := Kˣ) g N b a centre : K) =\n      (rowAnchor (G := Kˣ) g N b a centre : K) *\n        (((g ^ ((a-b)*(N-1)) : Kˣ) : K) - 1) := by\n  have h : rowAnchor g N a b centre =\n      rowAnchor g N b a centre * g ^ ((a-b)*(N-1)) := by\n    simp only [rowAnchor, ← zpow_add]\n    congr 1\n    ring\n  rw [h, Units.val_mul]\n  ring\n\n/-- The companion even channel also shares the same cheap projected\nperiod; it adds a minus-one test, not a new weighted-centre observable. -/\ntheorem rowAnchor_swap_sum {K : Type*} [CommRing K]\n    (g : Kˣ) (N a b centre : ℤ) :\n    (rowAnchor (G := Kˣ) g N a b centre : K) +\n      (rowAnchor (G := Kˣ) g N b a centre : K) =\n      (rowAnchor (G := Kˣ) g N b a centre : K) *\n        (((g ^ ((a-b)*(N-1)) : Kˣ) : K) + 1) := by\n  have h : rowAnchor g N a b centre =\n      rowAnchor g N b a centre * g ^ ((a-b)*(N-1)) := by\n    simp only [rowAnchor, ← zpow_add]\n    congr 1\n    ring\n  rw [h, Units.val_mul]\n  ring\n\n/-- Retaining the target-one boundary gives a root-preserving paired\nproduct. The cheap difference mode alone is insufficient: the common\nprefix still enters both the linear and quadratic terms. -/\ntheorem rowAnchor_swap_target_product {K : Type*} [CommRing K]\n    (g : Kˣ) (N a b centre : ℤ) :\n    ((rowAnchor (G := Kˣ) g N a b centre : K) - 1) *\n      ((rowAnchor (G := Kˣ) g N b a centre : K) - 1) =\n      (rowAnchor (G := Kˣ) g N b a centre : K)^2 *\n        ((g ^ ((a-b)*(N-1)) : Kˣ) : K) -\n      (rowAnchor (G := Kˣ) g N b a centre : K) *\n        (((g ^ ((a-b)*(N-1)) : Kˣ) : K) + 1) + 1 := by\n  have h : rowAnchor g N a b centre =\n      rowAnchor g N b a centre * g ^ ((a-b)*(N-1)) := by\n    simp only [rowAnchor, ← zpow_add]\n    congr 1\n    ring\n  rw [h, Units.val_mul]\n  ring\n\n/-- Reciprocal trace cancellation preserves both target-one hits and\ntarget-minus-one hits. It retains the product prefix as well as the\nratio; no unknown prime field or division by a nonunit is used. -/\ntheorem unit_trace_collision_factorization {K : Type*} [CommRing K]\n    (x y : Kˣ) :\n    ((x : K)^2 - 1) * ((y : K)^2 - 1) =\n      ((x*y : Kˣ) : K) *\n        (((x*y : Kˣ) : K) + (((x*y)⁻¹ : Kˣ) : K) -\n          ((x/y : Kˣ) : K) - ((y/x : Kˣ) : K)) := by\n  have hx : (x : K) * ((x⁻¹ : Kˣ) : K) = 1 := by simp\n  have hy : (y : K) * ((y⁻¹ : Kˣ) : K) = 1 := by simp\n  simp only [div_eq_mul_inv, mul_inv_rev, Units.val_mul]\n  linear_combination\n    -((y : K) * ((y⁻¹ : Kˣ) : K)) * hx - hy +\n      ((x : K)^2) * hy + ((y : K)^2) * hx\n\n/-- In either hidden prime field, the joined trace detects exactly the\nunion of the two rows' squared target-one collisions. It creates no\nfield collision except an existing target-one or target-minus-one hit. -/\ntheorem unit_trace_collision_iff {K : Type*} [CommRing K] [IsDomain K]\n    (x y : Kˣ) :\n    (((x*y : Kˣ) : K) + (((x*y)⁻¹ : Kˣ) : K) -\n        ((x/y : Kˣ) : K) - ((y/x : Kˣ) : K) = 0) ↔\n      (x : K)^2 = 1 ∨ (y : K)^2 = 1 := by\n  have h := unit_trace_collision_factorization x y\n  have hne : ((x*y : Kˣ) : K) ≠ 0 := Units.ne_zero _\n  rw [← mul_eq_zero_iff_left hne, ← h, mul_eq_zero, sub_eq_zero, sub_eq_zero]\n\n/-- Cheap row-swap cancellation can destroy the only original hit.\nThe centre is the literal ceil(2 sqrt(77*1*2)), not a synthetic phase.\nNeither the even nor the odd swapped channel replaces the target-one test. -/\ntheorem swap_cancellation_does_not_preserve_hit :\n    24^2 < 4*77*1*2 ∧ 4*77*1*2 ≤ 25^2 ∧\n      2^(1*77+2-25) % 77 = 71 ∧ 2^(2*77+1-25) % 77 = 23 ∧\n      Nat.gcd 77 (71-1) = 7 ∧\n      Nat.gcd 77 (71-23) = 1 ∧ Nat.gcd 77 (71+23) = 1 := by\n  norm_num\n\nend RiemannGaussian.SemiprimeRowStructure\n","RiemannGaussian.SemiprimeSeedLcm":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeCollisionPeeling\n\n/-!\n# Deterministic seed extension by a growing common modulus\n\nA degree-M power polynomial cannot vanish at M+1 distinct small residues.\nAfter the ordinary prefix these integer seeds are units. A bounded order\nwhose public prime tests are clear extends a known common modulus by LCM;\nthe extension doubles whenever the new seed was not annihilated by M.\nThe remaining large-order branch must still be handled at sixth-root cost.\n-/\n\nnamespace RiemannGaussian.SemiprimeSeedLcm\n\nopen Polynomial SemiprimeGroupSelection SemiprimeCartesianCompletion\nopen SemiprimeProgressionPrefix SemiprimeCollisionPeeling\n\n/-- A positive power polynomial misses at least one of the next M+1\ndistinct integers in a prime field. -/\ntheorem small_power_nonroot {p M : ℕ} (hp : p.Prime) (hM : 0<M)\n    (hsmall : M+1<p) : ∃ k, 0<k ∧ k≤M+1 ∧ (k : ZMod p)^M≠1 := by\n  classical\n  let : Fact p.Prime := ⟨hp⟩\n  let f : Fin (M+1) → ZMod p := fun i => ((i.val+1 : ℕ) : ZMod p)\n  have hf : Function.Injective f := by\n    intro i j he\n    have hei := congrArg ZMod.val he\n    have hi : i.val+1<p := by omega\n    have hj : j.val+1<p := by omega\n    change (((i.val+1 : ℕ) : ZMod p)).val=(((j.val+1 : ℕ) : ZMod p)).val at hei\n    rw [ZMod.val_natCast, ZMod.val_natCast, Nat.mod_eq_of_lt hi, Nat.mod_eq_of_lt hj] at hei\n    apply Fin.ext\n    omega\n  by_contra hn\n  push Not at hn\n  have heval : ∀ i, ((X : (ZMod p)[X])^M-C 1).eval (f i)=0 := by\n    intro i\n    simp only [eval_sub, eval_pow, eval_X, eval_C, f]\n    exact sub_eq_zero.mpr (hn (i.val+1) (by omega) (by omega))\n  have hdegree : ((X : (ZMod p)[X])^M-C 1).natDegree<M+1 := by\n    rw [natDegree_X_pow_sub_C]\n    omega\n  have hz := eq_zero_of_natDegree_lt_card_of_eval_eq_zero\n    ((X : (ZMod p)[X])^M-C 1) hf heval (by simpa only [Fintype.card_fin] using hdegree)\n  exact X_pow_sub_C_ne_zero hM 1 hz\n\n/-- A new order not dividing M increases its positive LCM by at least\na factor two; equality and fractional increases cannot occur. -/\ntheorem lcm_doubles {M m : ℕ} (hM : 0<M) (hm : 0<m) (hnot : ¬m∣M) :\n    2*M≤Nat.lcm M m := by\n  have hpos := Nat.lcm_pos hM hm\n  obtain ⟨a, ha⟩ := Nat.dvd_lcm_left M m\n  have hne : a≠1 := by\n    intro he\n    have heq : Nat.lcm M m=M := by simpa only [he, mul_one] using ha\n    exact hnot (heq ▸ Nat.dvd_lcm_right M m)\n  have hapos : 0<a := by nlinarith\n  have ha2 : 2≤a := by omega\n  nlinarith\n\n/-- Public search for a seed not annihilated by the current exponent. -/\nnoncomputable def seedChoice (N M : ℕ) : Option ℕ :=\n  ((List.range (M+1)).map fun i => i+1).find?\n    (fun k => decide ((k : ZMod N)^M≠1))\n\ntheorem seedChoice_some {N M k : ℕ} (hs : seedChoice N M=some k) :\n    0<k ∧ k≤M+1 ∧ (k : ZMod N)^M≠1 := by\n  have hmem := List.mem_of_find?_eq_some hs\n  obtain ⟨i, hi, he⟩ := List.mem_map.mp hmem\n  have hb := List.mem_range.mp hi\n  have htest := List.find?_some hs\n  exact ⟨by omega, by omega, by simpa only [decide_eq_true_eq] using htest⟩\n\n/-- The actual public scan cannot exhaust before the prime-field degree\nbound. No reference prime enters the scan itself. -/\ntheorem seedChoice_succeeds {N p M : ℕ} (hp : p.Prime) (hpN : p∣N)\n    (hM : 0<M) (hsmall : M+1<p) : ∃ k, seedChoice N M=some k := by\n  obtain ⟨k, hk, hkM, hnonroot⟩ := small_power_nonroot hp hM hsmall\n  have hn : (k : ZMod N)^M≠1 := by\n    intro he\n    have hcast := congrArg (ZMod.castHom hpN (ZMod p)) he\n    apply hnonroot\n    simpa only [map_pow, map_natCast, map_one] using hcast\n  have hmem : k∈(List.range (M+1)).map (fun i => i+1) := by\n    apply List.mem_map.mpr\n    exact ⟨k-1, List.mem_range.mpr (by omega), by omega⟩\n  cases hs : seedChoice N M with\n  | some k' => exact ⟨k', rfl⟩\n  | none =>\n    have ht := List.find?_eq_none.mp hs k hmem\n    simp only [decide_eq_true_eq] at ht\n    contradiction\n\n/-- A failed complete prefix makes every selected small seed a public\nunit; this is derived rather than supplied as hidden local-order data. -/\ntheorem seedChoice_unit_after_prefix {N B M k : ℕ} (hM : 0<M) (hMB : M<B)\n    (hcover : B^2<N) (hnone : SemiprimeStrassenPrefix.factorPrefix N B=none)\n    (hs : seedChoice N M=some k) : N.Coprime k := by\n  obtain ⟨hk, hkM, _⟩ := seedChoice_some hs\n  apply SemiprimeStrassenPrefix.prefix_none_coprime_integer hcover hnone hk\n  have hB : 1≤B := by omega\n  nlinarith\n\n/-- A clear bounded order extends the preceding common modulus and\nretains its geometric growth certificate. -/\ntheorem certified_lcm_extension {p q M e : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (g : (ZMod (p*q))ˣ) (hM : 0<M) (hmp : M∣p-1) (hmq : M∣q-1)\n    (he : 0<e) (hpow : g^e=1) (hnot : g^M≠1)\n    (hs : scanProper (p*q) (primePowerValues (p*q) (peelOrder g e) g)=none) :\n    0<Nat.lcm M (peelOrder g e) ∧\n      Nat.lcm M (peelOrder g e)∣p-1 ∧\n      Nat.lcm M (peelOrder g e)∣q-1 ∧\n      2*M≤Nat.lcm M (peelOrder g e) := by\n  let : NeZero (p*q) := ⟨Nat.mul_ne_zero hp.ne_zero hq.ne_zero⟩\n  have hm := peelOrder_eq_order g he hpow\n  have hmpos := (peelOrder_pos_dvd g he).1\n  have hclear := primePowerValues_none_clear g hm.symm hmpos hs\n  have hmpow : g^(peelOrder g e)=1 := by rw [hm]; exact pow_orderOf_eq_one g\n  obtain ⟨hdp, hdq⟩ := SemiprimeCommonOrder.common_modulus_of_public_checks hp hq g hmpos hmpow hclear\n  have hnotdvd : ¬peelOrder g e∣M := by\n    rw [hm]\n    exact fun hd => hnot ((orderOf_dvd_iff_pow_eq_one).mp hd)\n  exact ⟨Nat.lcm_pos hM hmpos, Nat.lcm_dvd hmp hdp, Nat.lcm_dvd hmq hdq,\n    lcm_doubles hM hmpos hnotdvd⟩\n\n/-- A successful factor, an explicit above-cap seed, or a failed attempt. -/\ninductive Route where\n  | factor (d : ℕ)\n  | largeBase (k : ℕ)\n  | unresolved\n  deriving DecidableEq\n\n/-- The complete mathematical certificate carried by a successful route. -/\ndef GoodRoute (N b : ℕ) : Route → Prop\n  | .factor d => ProperDivisor N d\n  | .largeBase k => ∃ hc : k.Coprime N, b^2<orderOf (ZMod.unitOfCoprime k hc)\n  | .unresolved => False\n\n/-- Preserve a checked factor result in the public routing datatype. -/\ndef factorRoute : Option ℕ → Route\n  | some d => .factor d\n  | none => .unresolved\n\n/-- Deterministic small-seed loop. A derived order is only accumulated\nafter its prime-power GCD scan has supplied a clear common certificate. -/\nnoncomputable def seedLoop (N B b : ℕ) : ℕ → ℕ → Route\n  | 0, M => if B≤M then factorRoute (factorProgression N M B) else .unresolved\n  | fuel+1, M =>\n    if B≤M then factorRoute (factorProgression N M B) else\n      match seedChoice N M with\n      | none => .unresolved\n      | some k =>\n        match checkedSignal N ((k : ZMod N)^M-1).val with\n        | some d => .factor d\n        | none =>\n          if hc : k.Coprime N then\n            let g := ZMod.unitOfCoprime k hc\n            match boundedCollision N b g with\n            | none => .largeBase k\n            | some (i,j) =>\n              let m := peelOrder g (j*b-i)\n              match scanProper N (primePowerValues N m g) with\n              | some d => .factor d\n              | none => seedLoop N B b fuel (Nat.lcm M m)\n          else factorRoute (checkedSignal N k)\n\n/-- Sufficient logarithmic fuel discharges every seed and small-order\nbranch. The only nonfactor outcome is a certified above-cap public unit. -/\ntheorem seedLoop_progress {p q B b fuel M : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p≤q) (hB : 0<B) (hbudget : p*q≤B^6) (hcover : B^2<p*q)\n    (hnone : SemiprimeStrassenPrefix.factorPrefix (p*q) B=none)\n    (hM : 0<M) (hmp : M∣p-1) (hmq : M∣q-1) (hpay : B≤2^fuel*M) :\n    GoodRoute (p*q) b (seedLoop (p*q) B b fuel M) := by\n  classical\n  let : NeZero (p*q) := ⟨Nat.mul_ne_zero hp.ne_zero hq.ne_zero⟩\n  have hpB := SemiprimeStrassenPrefix.prefix_none_excludes_small_prime hcover hp\n    (dvd_mul_right p q) hnone\n  induction fuel generalizing M with\n  | zero =>\n    have hsize : B≤M := by simpa only [pow_zero, one_mul] using hpay\n    obtain ⟨d, hd⟩ := factorProgression_semiprime hp hq hpq hB hsize hpB hbudget hmp hmq\n    simp only [seedLoop, ite_eq_left hsize, hd, factorRoute, GoodRoute]\n    exact factorProgression_sound hd\n  | succ fuel ih =>\n    by_cases hsize : B≤M\n    · obtain ⟨d, hd⟩ := factorProgression_semiprime hp hq hpq hB hsize hpB hbudget hmp hmq\n      simp only [seedLoop, ite_eq_left hsize, hd, factorRoute, GoodRoute]\n      exact factorProgression_sound hd\n    · have hMB : M<B := by omega\n      have hsmall : M+1<p :=\n        (show M+1≤B by omega).trans_lt ((Nat.le_pow (by decide : 0<2)).trans_lt hpB)\n      obtain ⟨k, hseed⟩ := seedChoice_succeeds hp (dvd_mul_right p q) hM hsmall\n      have hunit : k.Coprime (p*q) :=\n        (seedChoice_unit_after_prefix hM hMB hcover hnone hseed).symm\n      let g := ZMod.unitOfCoprime k hunit\n      have hg : (g : ZMod (p*q))=(k : ZMod (p*q)) := ZMod.coe_unitOfCoprime k hunit\n      have hnot : g^M≠1 := by\n        intro he\n        have hv := congrArg (fun u : (ZMod (p*q))ˣ => (u : ZMod (p*q))) he\n        exact (seedChoice_some hseed).2.2 (by\n          simpa only [Units.val_pow_eq_pow_val, hg, Units.val_one] using hv)\n      cases hsignal : checkedSignal (p*q) ((k : ZMod (p*q))^M-1).val with\n      | some d =>\n        simp only [seedLoop, ite_eq_right hsize, hseed, hsignal, GoodRoute]\n        exact checkedSignal_sound hsignal\n      | none =>\n        have hstep : seedLoop (p*q) B b (fuel+1) M=\n            (match boundedCollision (p*q) b g with\n            | none => .largeBase k\n            | some (i,j) =>\n              match scanProper (p*q) (primePowerValues (p*q) (peelOrder g (j*b-i)) g) with\n              | some d => .factor d\n              | none => seedLoop (p*q) B b fuel (Nat.lcm M (peelOrder g (j*b-i)))) := by\n          simp only [seedLoop, ite_eq_right hsize, hseed, hsignal, dite_eq_left hunit]\n          rfl\n        rw [hstep]\n        cases hcollision : boundedCollision (p*q) b g with\n        | none =>\n          simp only [GoodRoute]\n          exact ⟨hunit, boundedCollision_none_large g hcollision⟩\n        | some pair =>\n          obtain ⟨i,j⟩ := pair\n          dsimp only\n          obtain ⟨he, _, hpow⟩ := boundedCollision_annihilator g hcollision\n          cases hscan : scanProper (p*q) (primePowerValues (p*q) (peelOrder g (j*b-i)) g) with\n          | some d => exact scanProper_sound hscan\n          | none =>\n            obtain ⟨hpositive, hdp, hdq, hdoubles⟩ :=\n              certified_lcm_extension hp hq g hM hmp hmq he hpow hnot hscan\n            have hnewpay : B≤2^fuel*Nat.lcm M (peelOrder g (j*b-i)) := by\n              have hmul := Nat.mul_le_mul_left (2^fuel) hdoubles\n              have heq : 2^(fuel+1)*M=2^fuel*(2*M) := by rw [pow_succ]; ring\n              rw [heq] at hpay\n              exact hpay.trans hmul\n            exact ih hpositive hdp hdq hnewpay\n\n/-- Squares and the complete small-factor prefix are checked before\nthe logarithmically fueled common-modulus loop. -/\nnoncomputable def routeByWidth (N B : ℕ) : Route :=\n  if B<4 then factorRoute (SemiprimeLehmanCoverage.factor N) else\n    match SemiprimeCommonOrder.recoverSquare N with\n    | some d => .factor d\n    | none =>\n      match SemiprimeStrassenPrefix.factorPrefix N B with\n      | some d => .factor d\n      | none => seedLoop N B (2*B) (Nat.clog 2 B) 1\n\n/-- The early classical fallback has a constant numerical-input ceiling. -/\ntheorem small_width_input_bound {N B : ℕ} (hbudget : N≤B^6) (hsmall : B<4) :\n    N≤729 := by\n  calc\n    N≤B^6 := hbudget\n    _≤3^6 := by gcongr; omega\n    _=729 := by norm_num\n\n/-- Every semiprime is routed into a proper factor or a certified unit\nof order above 4B^2. No seed menu or hidden order premise is assumed. -/\ntheorem routeByWidth_semiprime {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p≤q) (hbudget : p*q≤B^6) (hlower : (B-1)^6<p*q) :\n    GoodRoute (p*q) (2*B) (routeByWidth (p*q) B) := by\n  unfold routeByWidth\n  split_ifs with hsmall\n  · obtain ⟨d, hd, hproper⟩ := SemiprimeLehmanCoverage.factor_semiprime hp hq\n    simpa only [hd, factorRoute, GoodRoute] using hproper\n  · have hB : 4≤B := by omega\n    cases hsquare : SemiprimeCommonOrder.recoverSquare (p*q) with\n    | some d => exact SemiprimeCommonOrder.recoverSquare_sound hsquare\n    | none =>\n      dsimp only\n      cases hprefix : SemiprimeStrassenPrefix.factorPrefix (p*q) B with\n      | some d => exact SemiprimeStrassenPrefix.prefix_sound hprefix\n      | none =>\n        dsimp only\n        apply seedLoop_progress hp hq hpq (by omega) hbudget\n          (SemiprimeStrassenPrefix.sixth_budget_prefix_below_input hB hlower)\n          hprefix (by decide) (one_dvd _) (one_dvd _)\n        simpa only [mul_one] using Nat.le_pow_clog (by decide : 1<2) B\n\n/-- One public input, with every seed selected and every order derived\ninside the procedure. The above-cap branch remains a research frontier. -/\nnoncomputable def publicRoute (N : ℕ) : Route :=\n  routeByWidth N (SemiprimeLehmanCoverage.sixthWidth N)\n\n/-- Universal factor-or-large-order coverage for the literal N-only\nprocedure, including squares and arbitrary semiprime factor ratios. -/\ntheorem publicRoute_semiprime {p q : ℕ} (hp : p.Prime) (hq : q.Prime) :\n    GoodRoute (p*q) (2*SemiprimeLehmanCoverage.sixthWidth (p*q)) (publicRoute (p*q)) := by\n  have hbudget := SemiprimeLehmanCoverage.sixthWidth_upper (p*q)\n  have hlower := SemiprimeLehmanCoverage.sixthWidth_lower (Nat.mul_pos hp.pos hq.pos)\n  unfold publicRoute\n  rcases le_total p q with hpq | hqp\n  · exact routeByWidth_semiprime hp hq hpq hbudget hlower\n  · have h := routeByWidth_semiprime (B:=SemiprimeLehmanCoverage.sixthWidth (p*q)) hq hp hqp\n      (by simpa only [Nat.mul_comm q p] using hbudget)\n      (by simpa only [Nat.mul_comm q p] using hlower)\n    simpa only [Nat.mul_comm q p] using h\n\n/-- Retain each modulus at which the literal loop attempts seed selection. -/\nnoncomputable def seedModuli (N B b : ℕ) : ℕ → ℕ → List ℕ\n  | 0, _ => []\n  | fuel+1, M =>\n    if B≤M then [] else M::\n      match seedChoice N M with\n      | none => []\n      | some k =>\n        match checkedSignal N ((k : ZMod N)^M-1).val with\n        | some _ => []\n        | none =>\n          if hc : k.Coprime N then\n            let g := ZMod.unitOfCoprime k hc\n            match boundedCollision N b g with\n            | none => []\n            | some (i,j) =>\n              let m := peelOrder g (j*b-i)\n              match scanProper N (primePowerValues N m g) with\n              | some _ => []\n              | none => seedModuli N B b fuel (Nat.lcm M m)\n          else []\n\n/-- The actual control path has at most fuel seed stages and at most\nB*fuel candidate power tests, including all small-order extensions. -/\ntheorem seedModuli_budget (N B b fuel M : ℕ) :\n    (seedModuli N B b fuel M).length≤fuel ∧\n      ((seedModuli N B b fuel M).map (fun a => a+1)).sum≤B*fuel := by\n  induction fuel generalizing M with\n  | zero => simp only [seedModuli, List.length_nil, List.map_nil, List.sum_nil, mul_zero, le_refl, and_self]\n  | succ fuel ih =>\n    rw [seedModuli]\n    split_ifs with hsize\n    · exact ⟨Nat.zero_le _, Nat.zero_le _⟩\n    · have hstep : ∀ tail : List ℕ, tail.length≤fuel ∧\n          (tail.map (fun a => a+1)).sum≤B*fuel →\n          (M::tail).length≤fuel+1 ∧ ((M::tail).map (fun a => a+1)).sum≤B*(fuel+1) := by\n        intro tail ht\n        simp only [List.length_cons, List.map_cons, List.sum_cons]\n        constructor\n        · omega\n        · rw [Nat.mul_add, Nat.mul_one]\n          omega\n      apply hstep\n      repeat' first\n        | exact ih _\n        | exact ⟨Nat.zero_le _, Nat.zero_le _⟩\n        | split\n      dsimp only\n      repeat' first\n        | exact ih _\n        | exact ⟨Nat.zero_le _, Nat.zero_le _⟩\n        | split\n\n/-- With the literal public fuel and block, all candidate powers fit\nB*clog(2,B), and the two lookup lists fit 4B*clog(2,B) records in total.\nSorting, stripping and polynomial arithmetic are separate work categories. -/\ntheorem logarithmic_setup_budget (N B : ℕ) :\n    ((seedModuli N B (2*B) (Nat.clog 2 B) 1).map (fun a => a+1)).sum≤B*Nat.clog 2 B ∧\n      4*B*(seedModuli N B (2*B) (Nat.clog 2 B) 1).length≤4*B*Nat.clog 2 B := by\n  have h := seedModuli_budget N B (2*B) (Nat.clog 2 B) 1\n  exact ⟨h.2, Nat.mul_le_mul_left (4*B) h.1⟩\n\n/-- The saved Mersenne control has both primes beyond the prefix and\nan actual common order below the public sixth-root width. -/\ntheorem control_mersenne_arithmetic :\n    Nat.Prime 13367 ∧ Nat.Prime 164511353 ∧ 13367*164511353=2199023255551 ∧\n      114^6<(2199023255551 : ℕ) ∧ 2199023255551≤115^6 ∧ (115 : ℕ)^2<13367 := by\n  norm_num\n\n/-- The small-order control's public annihilating power is exact. -/\ntheorem control_mersenne_power : (2 : ZMod 2199023255551)^41=1 := by\n  reduce_mod_char\n\n/-- This literal order is verified from public powers, not supplied to\nthe runtime loop as numerical advice. -/\ntheorem control_mersenne_order (g : (ZMod 2199023255551)ˣ)\n    (hg : (g : ZMod 2199023255551)=2) : orderOf g=41 := by\n  let : Fact (Nat.Prime 41) := ⟨by decide⟩\n  have hpow : g^41=1 := by\n    apply Units.ext\n    simpa only [Units.val_pow_eq_pow_val, hg, Units.val_one] using control_mersenne_power\n  have hne : g≠1 := by\n    intro he\n    have hv := congrArg (fun u : (ZMod 2199023255551)ˣ => (u : ZMod 2199023255551)) he\n    simp only [hg, Units.val_one] at hv\n    exact (by decide : (2 : ZMod 2199023255551)≠1) hv\n  exact orderOf_eq_prime hpow hne\n\nset_option maxRecDepth 32768 in\n/-- The actual small-integer scan leaves the order-41 seed for base three. -/\ntheorem control_mersenne_next_seed : seedChoice 2199023255551 41=some 3 := by\n  have hlist : (List.range (41+1)).map (fun i => i+1)=\n      1::2::3::(List.range' 3 39).map (fun i => i+1) := by decide\n  have hthree : (3 : ZMod 2199023255551)^41≠1 := by decide\n  rw [seedChoice, hlist]\n  simp [List.find?, control_mersenne_power, hthree]\n\n/-- All semiprime and width premises of the new route are discharged\non the prefix-clear control with a formerly unresolved small order. -/\ntheorem control_mersenne_routing :\n    GoodRoute 2199023255551 230 (routeByWidth 2199023255551 115) := by\n  obtain ⟨hp, hq, hprod, hlower, hbudget, _⟩ := control_mersenne_arithmetic\n  have h := routeByWidth_semiprime hp hq (by norm_num)\n    (B:=115) (by simpa only [hprod] using hbudget)\n    (by simpa only [hprod, show (115-1 : ℕ)=114 from rfl] using hlower)\n  simpa only [hprod] using h\n\nend RiemannGaussian.SemiprimeSeedLcm\n","RiemannGaussian.SemiprimeSourceClassifiedCountsClock":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceClassifiedCounts\nimport RiemannGaussian.SemiprimeSourceIncidenceCountBitsBounds\n\n/-! # Actual complete classified-score report\nAll optimized locals, lane adders, prefix copies and final weighting are paid.\nNo candidate completion or unary cardinality/count expansion occurs.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nset_option maxRecDepth 8192\nnamespace RiemannGaussian.SemiprimeSourceClassifiedCountsClock\nopen SemiprimeMaterializedScoreEnvironment (ScoreProgram support)\nopen SemiprimeSourceWordIdEnvironment (Env ValidIds)\nopen SemiprimeSourceWordIdEnvironmentBounds (KeysBound)\nopen SemiprimeSourceClassifiedCounts SemiprimeBitArithmetic SemiprimeRationalBits\nopen SemiprimeReportPolynomialGrowth\n\n/-- Structural lane width from acquired cached power width and actual program count. -/\ndef laneWidth (r Q T : ℕ) : ℕ := SemiprimeSourceCountPowers.width r Q+T\n/-- Actual input width for the final two multipliers and adder. -/\ndef operandWidth (r Q T K : ℕ) : ℕ := K+laneWidth r Q T\n\n/-- Both physical sequential lane widths follow actual acquired cache/adder growth. -/\ntheorem sequential_length (r Q : ℕ) (defaultID : List Bool) (programs : List (ScoreProgram Q))\n    (n : ℕ) (fixedIDs : List (List Bool)) :\n    (sequential (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q)\n      defaultID programs n fixedIDs).incidence.length ≤ laneWidth r Q programs.length ∧\n    (sequential (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q)\n      defaultID programs n fixedIDs).head.length ≤ laneWidth r Q programs.length :=\n  evaluate_length r Q programs (List.range' fixedIDs.length n)\n    (SemiprimeSourceWordIdEnvironment.initial defaultID fixedIDs).value\n\n/-- Final physical score width has no L^4 term or desired-count premise. -/\ntheorem score_width (r Q : ℕ) (weights : SemiprimeSourceScoreWeightBits.Weights)\n    (defaultID : List Bool) (programs : List (ScoreProgram Q)) (n : ℕ) (fixedIDs : List (List Bool)) (K : ℕ)\n    (ha : weights.incidence.length ≤ K) (hb : weights.head.length ≤ K) :\n    Width (score (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q)\n      weights defaultID programs n fixedIDs).word (3*operandWidth r Q programs.length K+1) := by\n  have h := sequential_length r Q defaultID programs n fixedIDs\n  have hw := SemiprimeSourceScoreWeightBits.combine_length weights\n    (sequential (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q)\n      defaultID programs n fixedIDs).incidence\n    (sequential (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q)\n      defaultID programs n fixedIDs).head (operandWidth r Q programs.length K)\n    (ha.trans (by unfold operandWidth;omega)) (hb.trans (by unfold operandWidth;omega))\n    (h.1.trans (by unfold operandWidth;omega)) (h.2.trans (by unfold operandWidth;omega))\n  exact ⟨hw,by change 1 ≤ 3*operandWidth r Q programs.length K+1;omega⟩\n\n/-- Conservative joint cap of the two actual constant-classifier local branches. -/\ndef localBudget (r Q L N s : ℕ) : ℕ :=\n  SemiprimeSourceHeadCountBitsBounds.budget r Q L N s+\n    SemiprimeSourceIncidenceCountBitsBounds.countBudget r Q L N s\n\n/-- Every local report follows from concrete acquired bank/cache and finite metadata. -/\ntheorem local_clock (r Q : ℕ) [NeZero r] (p : ScoreProgram Q) (remaining : List ℕ) (env : Env) (N s : ℕ)\n    (he : ValidIds (SemiprimeSourceWordBank.acquire r Q).ids env)\n    (hf : env.fixedIDs.length ≤ N) (ho : env.overrides.length ≤ s) (hk : KeysBound (N+1) env)\n    (hn : remaining.length ≤ N) (hp : ∀ i∈support p,i ≤ N) :\n    (localCount (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q)\n      p remaining env).clock ≤ localBudget r Q (r^Q) N s := by\n  cases p with\n  | incidence a b c d =>\n    have h := SemiprimeSourceIncidenceCountBitsBounds.count_work r Q env a b c d remaining N s he hf ho hk hn\n      (hp a (by simp [support])) (hp b (by simp [support]))\n      (hp c (by simp [support])) (hp d (by simp [support]))\n    exact h.trans (by unfold localBudget;omega)\n  | head q a b =>\n    have h := SemiprimeSourceHeadCountBitsBounds.count_original_clock r Q env q a b remaining N s\n      he hf ho hk hn (hp a (by simp [support])) (hp b (by simp [support]))\n    exact h.trans (by unfold localBudget;omega)\n\n/-- Actual finite lane accumulation and all local classifiers. -/\ndef evaluateBudget (r Q L N s T : ℕ) : ℕ :=\n  T*(localBudget r Q L N s+11*laneWidth r Q T+12)+1\n\n/-- Every actual program suffix has the classified physical report bound. -/\ntheorem evaluate_clock (r Q : ℕ) [NeZero r] (programs : List (ScoreProgram Q))\n    (remaining : List ℕ) (env : Env) (N s : ℕ)\n    (he : ValidIds (SemiprimeSourceWordBank.acquire r Q).ids env)\n    (hf : env.fixedIDs.length ≤ N) (ho : env.overrides.length ≤ s) (hk : KeysBound (N+1) env)\n    (hn : remaining.length ≤ N) (hp : ∀ p∈programs,∀ i∈support p,i ≤ N) :\n    (evaluate (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q)\n      programs remaining env).clock ≤ evaluateBudget r Q (r^Q) N s programs.length := by\n  induction programs with\n  | nil => simp [evaluate,evaluateBudget]\n  | cons p programs ih =>\n    have ht := local_clock r Q p remaining env N s he hf ho hk hn (hp p List.mem_cons_self)\n    have hc := ih (fun p h => hp p (List.mem_cons_of_mem _ h))\n    have hl := evaluate_length r Q programs remaining env\n    have hloc := local_length r Q p remaining env\n    have ci := addBits_cost\n      (localCount (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q) p remaining env).bits\n      (evaluate (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q) programs remaining env).incidence false\n    have ch := addBits_cost\n      (localCount (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q) p remaining env).bits\n      (evaluate (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q) programs remaining env).head false\n    have mi : max\n        (localCount (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q) p remaining env).bits.length\n        (evaluate (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q) programs remaining env).incidence.length ≤\n        laneWidth r Q programs.length := by apply max_le <;> unfold laneWidth <;> omega\n    have mh : max\n        (localCount (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q) p remaining env).bits.length\n        (evaluate (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q) programs remaining env).head.length ≤\n        laneWidth r Q programs.length := by apply max_le <;> unfold laneWidth <;> omega\n    cases p <;> simp only [evaluate,evaluateBudget,List.length_cons,laneWidth] at * <;> nlinarith\n\n/-- Original prefix-ID copy and all classifiers; no free-variable pushes occur. -/\ndef sequentialBudget (r Q N L T : ℕ) : ℕ :=\n  8*L+N*(8*L+4)+7+evaluateBudget r Q L N 0 T+2*N+8\n\n/-- Concrete original prefix metadata closes the entire classified sequential report. -/\ntheorem sequential_clock (r Q : ℕ) [NeZero r] (defaultID : List Bool)\n    (programs : List (ScoreProgram Q)) (n : ℕ) (fixedIDs : List (List Bool)) (N : ℕ)\n    (hd : defaultID∈(SemiprimeSourceWordBank.acquire r Q).ids)\n    (hf : ∀ id∈fixedIDs,id∈(SemiprimeSourceWordBank.acquire r Q).ids)\n    (hlen : fixedIDs.length+n ≤ N) (hp : ∀ p∈programs,∀ i∈support p,i ≤ N) :\n    (sequential (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q)\n      defaultID programs n fixedIDs).clock ≤ sequentialBudget r Q N (r^Q) programs.length := by\n  have he := SemiprimeSourceWordIdEnvironment.initial_valid _ defaultID fixedIDs hd hf\n  have hc := evaluate_clock r Q programs (List.range' fixedIDs.length n)\n    (SemiprimeSourceWordIdEnvironment.initial defaultID fixedIDs).value N 0 he\n    (by simpa only [SemiprimeSourceWordIdEnvironment.initial,SemiprimeSourceChoiceBits.copyIDs_value] using\n      (show fixedIDs.length ≤ N by omega))\n    (by simp [SemiprimeSourceWordIdEnvironment.initial])\n    (by simp [KeysBound,SemiprimeSourceWordIdEnvironment.initial])\n    (by simp only [List.length_range'];omega) hp\n  have hi := SemiprimeSourceWordIdEnvironment.initial_work defaultID fixedIDs (2*r^Q)\n    (fun id hid => SemiprimeSourceWordBankAcquisitionBudget.acquire_ids_bounded r Q id (hf id hid))\n  have hdw := SemiprimeSourceWordBankAcquisitionBudget.acquire_ids_bounded r Q defaultID hd\n  have hinit : (SemiprimeSourceWordIdEnvironment.initial defaultID fixedIDs).work ≤\n      8*r^Q+N*(8*r^Q+4)+7 := by\n    apply hi.trans\n    calc\n      _ ≤ 4*(2*r^Q)+N*(4*(2*r^Q)+4)+7 := by gcongr;omega\n      _ = 8*r^Q+N*(8*r^Q+4)+7 := by ring\n  simp only [sequential,sequentialBudget]\n  omega\n\n/-- Complete callback work from cached powers/weights and actual physical lanes. -/\ndef scoreBudget (r Q N L T K : ℕ) : ℕ :=\n  sequentialBudget r Q N L T+SemiprimeSourceScoreWeightBits.combineBudget (operandWidth r Q T K)+5\n\n/-- Original bank/weights/prefix metadata derive all actual score operations. -/\ntheorem score_clock (r Q : ℕ) [NeZero r] (weights : SemiprimeSourceScoreWeightBits.Weights)\n    (defaultID : List Bool) (programs : List (ScoreProgram Q)) (n : ℕ) (fixedIDs : List (List Bool)) (N K : ℕ)\n    (hd : defaultID∈(SemiprimeSourceWordBank.acquire r Q).ids)\n    (hf : ∀ id∈fixedIDs,id∈(SemiprimeSourceWordBank.acquire r Q).ids)\n    (hlen : fixedIDs.length+n ≤ N) (hp : ∀ p∈programs,∀ i∈support p,i ≤ N)\n    (ha : weights.incidence.length ≤ K) (hb : weights.head.length ≤ K) :\n    (score (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q)\n      weights defaultID programs n fixedIDs).clock ≤ scoreBudget r Q N (r^Q) programs.length K := by\n  have hs := sequential_clock r Q defaultID programs n fixedIDs N hd hf hlen hp\n  have hl := sequential_length r Q defaultID programs n fixedIDs\n  have hc := SemiprimeSourceScoreWeightBits.combine_clock weights\n    (sequential (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q) defaultID programs n fixedIDs).incidence\n    (sequential (SemiprimeSourceWordBank.acquire r Q) (SemiprimeSourceCountPowers.acquire r Q) defaultID programs n fixedIDs).head\n    (operandWidth r Q programs.length K)\n    (ha.trans (by unfold operandWidth;omega)) (hb.trans (by unfold operandWidth;omega))\n    (hl.1.trans (by unfold operandWidth;omega)) (hl.2.trans (by unfold operandWidth;omega))\n  simp only [score,scoreBudget]\n  omega\n/-- Pure six-resource monotonicity, independent of all actual source expressions. -/\ntheorem scoreBudget_mono {r Q N L T K r' Q' N' L' T' K' : ℕ}\n    (hr : r ≤ r') (hQ : Q ≤ Q') (hN : N ≤ N') (hL : L ≤ L')\n    (hT : T ≤ T') (hK : K ≤ K') :\n    scoreBudget r Q N L T K ≤ scoreBudget r' Q' N' L' T' K' := by\n  simp only [scoreBudget,sequentialBudget,evaluateBudget,localBudget,operandWidth,laneWidth,\n    SemiprimeSourceCountPowers.width,SemiprimeSourceScoreWeightBits.combineBudget,\n    SemiprimeSourceHeadCountBitsBounds.budget,SemiprimeSourceIncidenceCountBitsBounds.countBudget,\n    SemiprimeSourceIncidenceCountBitsBounds.edgeBudget,\n    SemiprimeSourceWordIdPredicateBounds.terminalBudget,\n    SemiprimeSourceWordIdPredicateBounds.programBudget,\n    SemiprimeSourceWordIdPredicateBounds.terminalStepBudget,\n    SemiprimeSourceWordIdPredicateBounds.bankReadBudget,\n    SemiprimeSourceWordIdPredicateBounds.colourReadBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.readBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.scanStep,\n    SemiprimeSourceWordIdEnvironmentBounds.keyBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.idCopyBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.eqBudget,\n    SemiprimeSourceScorePredicateBitsBounds.copyBudget,\n    SemiprimeSourceScorePredicateBitsBounds.equalityBudget]\n  gcongr\n\n/-- Fixed constants precede the whole original materialized-resource family. -/\ntheorem scoreBudget_monomial : ∃ C k : ℕ,∀ S,scoreBudget S S S S S S ≤ C*(S+1)^k := by\n  change Bound (fun S => scoreBudget S S S S S S)\n  simp only [scoreBudget,sequentialBudget,evaluateBudget,localBudget,operandWidth,laneWidth,\n    SemiprimeSourceCountPowers.width,SemiprimeSourceScoreWeightBits.combineBudget,\n    SemiprimeSourceHeadCountBitsBounds.budget,SemiprimeSourceIncidenceCountBitsBounds.countBudget,\n    SemiprimeSourceIncidenceCountBitsBounds.edgeBudget,\n    SemiprimeSourceWordIdPredicateBounds.terminalBudget,\n    SemiprimeSourceWordIdPredicateBounds.programBudget,\n    SemiprimeSourceWordIdPredicateBounds.terminalStepBudget,\n    SemiprimeSourceWordIdPredicateBounds.bankReadBudget,\n    SemiprimeSourceWordIdPredicateBounds.colourReadBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.readBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.scanStep,\n    SemiprimeSourceWordIdEnvironmentBounds.keyBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.idCopyBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.eqBudget,\n    SemiprimeSourceScorePredicateBitsBounds.copyBudget,\n    SemiprimeSourceScorePredicateBitsBounds.equalityBudget]\n  boundArithmetic\n\nend RiemannGaussian.SemiprimeSourceClassifiedCountsClock\n","RiemannGaussian.SemiprimeSourceHistogramFeatureBitsBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramFeatureBits\nimport RiemannGaussian.SemiprimeSourceHistogramTrieBounds\nimport RiemannGaussian.SemiprimeSourceHistogramSquaresBounds\n\n/-! # Original-cap widths and paid filtered-feature acquisition\nLookup/report bounds follow actual compact prefix payloads and original variable\ncodes; no intermediate width or dictionary-clock answer is supplied. Cached port\nacquisition is paid once by its outer caller, separate from these query passes.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeSourceHistogramFeatureBitsBounds\nopen SemiprimeSourceHistogramFeatureBits\nopen SemiprimeSourceHistogramPortKeys (PortRecord)\nopen SemiprimeSourceHistogramTrie (Trie CompactCounters)\nopen SemiprimeSourceHistogramTrieBounds (CountCap)\nopen SemiprimeSourceIncidenceHistogram (Feature)\n\n/-- One common original-dimensional variable/word-ID component width. -/\ndef width (N L : ℕ) : ℕ := max (SemiprimeSourceHistogramPortKeys.keyWidth N) (Nat.clog 2 (L+1))\n\n/-- Compact represented variable keys fit their original finite code universe. -/\ntheorem keyRep_length (N code : ℕ) (key : List Bool) (h : KeyRep N code key) :\n    key.length ≤ SemiprimeSourceHistogramPortKeys.keyWidth N := by\n  apply SemiprimeSourceCompactBits.compact_length_of_lt _ h.1\n  rw [h.2.1]\n  have hc := h.2.2\n  have hp:=Nat.le_pow_clog (by decide : 1<(2:ℕ)) (N+1)\n  unfold SemiprimeSourceHistogramPortKeys.keyWidth\n  omega\n\n/-- Every acquired feature component has a width derived from original caps. -/\ntheorem component_length (dict : Trie) (f : Feature) (key : List Bool) (N L : ℕ)\n    (hk : key.length ≤ SemiprimeSourceHistogramPortKeys.keyWidth N)\n    (hc : CompactCounters dict) (hv : CountCap dict L) :\n    (component dict f key).bits.length ≤ width N L := by\n  have hl:=SemiprimeSourceHistogramTrieBounds.lookup_length dict key L hc (hv key)\n  by_cases h1 : f=1\n  · simp only [component,h1,ite_true,SemiprimeSourceCompactBits.copy_bits]\n    exact hk.trans (le_max_left _ _)\n  · by_cases h2 : f=2\n    · simpa [component,h2,width] using hl.trans (le_max_right (SemiprimeSourceHistogramPortKeys.keyWidth N) (Nat.clog 2 (L+1)))\n    · simp [component,h1,h2]\n\n/-- One copied variable key or acquired/copied fixed label and finite control. -/\ndef componentBudget (B : ℕ) : ℕ := 11*B+12\n\n/-- Actual prefix-trie lookup and component copying are charged at derived width. -/\ntheorem component_clock (dict : Trie) (f : Feature) (key : List Bool) (N L : ℕ)\n    (hk : key.length ≤ SemiprimeSourceHistogramPortKeys.keyWidth N)\n    (hc : CompactCounters dict) (hv : CountCap dict L) :\n    (component dict f key).clock ≤ componentBudget (width N L) := by\n  have hkey : key.length ≤ width N L := hk.trans (le_max_left _ _)\n  have hl := SemiprimeSourceHistogramTrieBounds.stored_length dict key L hc (hv key)\n  have hs : (SemiprimeSourceHistogramTrie.stored dict key).length ≤ width N L :=\n    hl.trans (le_max_right _ _)\n  have lookup := SemiprimeSourceHistogramTrieBounds.lookup_clock dict key (width N L) hs\n  have copied := SemiprimeSourceCompactBits.copy_clock key\n  by_cases h1 : f=1\n  · simp only [component,h1,ite_true,componentBudget]\n    omega\n  · by_cases h2 : f=2\n    · have hlk : (SemiprimeSourceHistogramTrie.lookup dict key).clock ≤ componentBudget (width N L) := by\n        unfold componentBudget\n        omega\n      simpa [component,h2] using hlk\n    · simp [component,h1,h2,componentBudget]\n\n/-- Physical feature-key framing plus both components and native mask stage. -/\ndef oneBudget (B : ℕ) : ℕ := 28*B+47\n\n/-- One actual original cached row pays both component reports and framing. -/\ntheorem one_clock (dict : Trie) (k s : ℕ) (f g : Feature) (row : PortRecord) (N L : ℕ)\n    (hr : RecordRep N row) (hc : CompactCounters dict) (hv : CountCap dict L) :\n    (one dict k s f g row).work ≤ oneBudget (width N L) := by\n  have hown:=keyRep_length N _ row.ownerKey hr.1\n  have hfac:=keyRep_length N _ row.factorKey hr.2\n  have ha:=component_clock dict f row.ownerKey N L hown hc hv\n  have hb:=component_clock dict g row.factorKey N L hfac hc hv\n  have hal:=component_length dict f row.ownerKey N L hown hc hv\n  have frame:=SemiprimeSourceHistogramKeyBits.pair_clock\n    (component dict f row.ownerKey).bits (component dict g row.factorKey).bits\n  by_cases hm : (eligible k s f row.ownerCode && eligible k s g row.factorCode)=true\n  · simp only [one,hm,ite_true]\n    unfold oneBudget componentBudget at *\n    omega\n  · simp [one,hm,oneBudget]\n\n/-- The exact produced key count is at most the original cache size. -/\ntheorem produce_length (dict : Trie) (k s : ℕ) (f g : Feature) (rows : List PortRecord) :\n    (produce dict k s f g rows).value.length ≤ rows.length := by\n  rw [produce_value,List.length_map]\n  exact List.length_filter_le _ _\n\n/-- All actually produced framed key widths follow original variable/label caps. -/\ntheorem produce_key_length (dict : Trie) (k s : ℕ) (f g : Feature) (rows : List PortRecord)\n    (N L : ℕ) (hr : ∀ row∈rows,RecordRep N row)\n    (hc : CompactCounters dict) (hv : CountCap dict L) :\n    ∀ key∈(produce dict k s f g rows).value,key.length ≤ 3*width N L+1 := by\n  intro key hkey\n  rw [produce_value] at hkey\n  rcases List.mem_map.mp hkey with ⟨row,hrow,rfl⟩\n  have hg:=hr row (List.mem_filter.mp hrow).1\n  have ha:=component_length dict f row.ownerKey N L (keyRep_length N _ _ hg.1) hc hv\n  have hb:=component_length dict g row.factorKey N L (keyRep_length N _ _ hg.2) hc hv\n  rw [component_bits] at ha hb\n  unfold jointBytes\n  rw [SemiprimeSourceHistogramKeyBits.frame_length]\n  omega\n\n/-- Every row is tested once and every eligible physical lookup/copy is paid. -/\ntheorem produce_clock (dict : Trie) (k s : ℕ) (f g : Feature) (rows : List PortRecord)\n    (N L : ℕ) (hr : ∀ row∈rows,RecordRep N row)\n    (hc : CompactCounters dict) (hv : CountCap dict L) :\n    (produce dict k s f g rows).work ≤ rows.length*(oneBudget (width N L)+4)+1 := by\n  induction rows with\n  | nil => simp [produce]\n  | cons row rows ih =>\n    have ha:=one_clock dict k s f g row N L (hr row List.mem_cons_self) hc hv\n    have ht:=ih (fun row hrow => hr row (List.mem_cons_of_mem _ hrow))\n    simp only [produce,List.length_cons,Nat.add_mul,Nat.one_mul]\n    cases h : (one dict k s f g row).value <;> simp only <;> omega\n\n/-- Actual query acquisition budget; no setup or histogram answer is an input. -/\ndef budget (N L M : ℕ) : ℕ :=\n  M*(oneBudget (width N L)+4)+1+\n    SemiprimeSourceHistogramSquaresBounds.budget (3*width N L+1) M+3\n\n/-- Actual produced key list and actual square-count fold are both retained. -/\ntheorem acquire_clock (dict : Trie) (k s : ℕ) (f g : Feature) (rows : List PortRecord)\n    (N L : ℕ) (hr : ∀ row∈rows,RecordRep N row)\n    (hc : CompactCounters dict) (hv : CountCap dict L) :\n    (acquire dict k s f g rows).clock ≤ budget N L rows.length := by\n  let keys:=(produce dict k s f g rows).value\n  have hp:=produce_clock dict k s f g rows N L hr hc hv\n  have hl:=produce_length dict k s f g rows\n  have hk:=produce_key_length dict k s f g rows N L hr hc hv\n  have hs:=SemiprimeSourceHistogramSquaresBounds.fold_clock keys []\n    SemiprimeSourceHistogramSquares.initial (3*width N L+1) rows.length\n    SemiprimeSourceHistogramSquares.initial_good (by simpa using hl) hk\n  have hm : keys.length*(SemiprimeSourceHistogramSquaresBounds.stepBudget (3*width N L+1) rows.length+3) ≤\n      rows.length*(SemiprimeSourceHistogramSquaresBounds.stepBudget (3*width N L+1) rows.length+3) :=\n    Nat.mul_le_mul_right _ hl\n  change (SemiprimeSourceHistogramSquares.acquire keys).clock ≤\n    1+keys.length*(SemiprimeSourceHistogramSquaresBounds.stepBudget (3*width N L+1) rows.length+3)+1 at hs\n  dsimp only [keys] at hs hm\n  unfold acquire budget SemiprimeSourceHistogramSquaresBounds.budget\n  dsimp only\n  omega\n\n/-- Original acquired cached ports discharge all variable-key shape/width premises. -/\ntheorem acquirePorts_clock {n F : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (ports : List ((e : Fin F)×Fin (arity e)))\n    (dict : Trie) (k s : ℕ) (f g : Feature) (L : ℕ)\n    (hc : CompactCounters dict) (hv : CountCap dict L) :\n    (acquire dict k s f g\n      (SemiprimeSourceHistogramPortKeys.acquirePorts owner ports).value).clock ≤ budget (n+F) L ports.length := by\n  have h:=acquire_clock dict k s f g _ (n+F) L (acquirePorts_rep owner ports) hc hv\n  simpa only [SemiprimeSourceHistogramPortKeys.acquirePorts_value,List.length_map] using h\n\n\n/-- The actual accumulated collision word is always compact. -/\ntheorem acquire_compact (dict : Trie) (k s : ℕ) (f g : Feature) (rows : List PortRecord) :\n    SemiprimeSourceCompactBits.Compact (acquire dict k s f g rows).bits :=\n  (SemiprimeSourceHistogramSquares.acquire_good (produce dict k s f g rows).value).2.2.2\n\n/-- No derived feature histogram can exceed the original ordered port-pair count. -/\ntheorem acquire_value_le (dict : Trie) (k s : ℕ) (f g : Feature) (rows : List PortRecord) :\n    SemiprimeBitArithmetic.bitValue (acquire dict k s f g rows).bits ≤ rows.length^2 := by\n  change SemiprimeBitArithmetic.bitValue\n    (SemiprimeSourceHistogramSquares.acquire (produce dict k s f g rows).value).bits ≤ _\n  rw [SemiprimeSourceHistogramSquares.acquire_value]\n  exact (SemiprimeSourceHistogramSquaresBounds.collisions_le _).trans\n    (Nat.pow_le_pow_left (produce_length dict k s f g rows) 2)\n\n/-- Original cache size derives the actual final output-word width internally. -/\ntheorem acquire_length (dict : Trie) (k s : ℕ) (f g : Feature) (rows : List PortRecord) :\n    (acquire dict k s f g rows).bits.length ≤ Nat.clog 2 (rows.length^2+1) := by\n  apply SemiprimeSourceCompactBits.compact_length_of_lt _ (acquire_compact dict k s f g rows)\n  have h:=acquire_value_le dict k s f g rows\n  have hp:=Nat.le_pow_clog (by decide : 1<(2:ℕ)) (rows.length^2+1)\n  omega\n\n/-- This acquired persistent histogram-trie node count is charged per produced key;\nit is not asserted to be a complete auxiliary-heap bound. -/\ntheorem acquire_nodes (dict : Trie) (k s : ℕ) (f g : Feature) (rows : List PortRecord)\n    (N L : ℕ) (hr : ∀ row∈rows,RecordRep N row)\n    (hc : CompactCounters dict) (hv : CountCap dict L) :\n    SemiprimeSourceHistogramTrie.nodes (acquire dict k s f g rows).trie ≤\n      rows.length*(3*width N L+2) := by\n  have h:=SemiprimeSourceHistogramSquaresBounds.acquire_nodes (produce dict k s f g rows).value\n    (3*width N L+1) (produce_key_length dict k s f g rows N L hr hc hv)\n  have hl:=produce_length dict k s f g rows\n  change SemiprimeSourceHistogramTrie.nodes\n    (SemiprimeSourceHistogramSquares.acquire (produce dict k s f g rows).value).trie ≤ _\n  apply h.trans\n  simpa only [Nat.add_assoc] using Nat.mul_le_mul_right (3*width N L+1+1) hl\n\nend RiemannGaussian.SemiprimeSourceHistogramFeatureBitsBounds\n","RiemannGaussian.SemiprimeSourceHistogramHeadRefinement":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramHeadBits\n\n/-! # Exact original-coordinate semantics of the physical head key stream\nCanonical numeric encodings and Word-valued labels below are proof-side only.\nThe executed producer still consumes only cached physical keys/rows and IDs.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceHistogramHeadRefinement\nopen SemiprimeBitArithmetic SemiprimeRationalBits\nopen SemiprimeSourceHistogramHeadBits\nopen SemiprimeSourceHistogramKeyBits (frame)\nopen SemiprimeSourceCompactBits (Compact)\nopen OAI.Algorithms.SubexponentialSAT.MulticolorTypes\n\n/-- Proof-side unique compact byte string for a natural number. -/\ndef numberKey (n : ℕ) : List Bool :=\n  (SemiprimeSourceCompactBits.trim (SemiprimeSourceOffsetInputsCore.natBits n).bits).bits\n\n/-- The proof encoding has exactly its named numerical value. -/\ntheorem numberKey_value (n : ℕ) : bitValue (numberKey n)=n := by\n  simp only [numberKey,SemiprimeSourceCompactBits.trim_value,\n    SemiprimeSourceOffsetInputsCore.natBits_value]\n\n/-- The proof encoding is compact, including literal zero. -/\ntheorem numberKey_compact (n : ℕ) : Compact (numberKey n) :=\n  SemiprimeSourceCompactBits.trim_compact _\n\n/-- Canonical numerical encodings cannot alias. -/\ntheorem numberKey_injective : Function.Injective numberKey := by\n  intro a b h\n  simpa only [numberKey_value] using congrArg bitValue h\n\nprivate theorem compact_lists (xs ys : List (List Bool))\n    (hx : ∀ x∈xs,Compact x) (hy : ∀ y∈ys,Compact y)\n    (hv : xs.map bitValue=ys.map bitValue) : xs=ys := by\n  induction xs generalizing ys with\n  | nil => cases ys <;> simp_all\n  | cons x xs ih =>\n    cases ys with\n    | nil => simp at hv\n    | cons y ys =>\n      have he := List.cons.inj hv\n      have hxy := SemiprimeSourceCompactWordIds.compact_value_injective _ _\n        (hx x (by simp)) (hy y (by simp)) he.1\n      rw [hxy,ih ys (fun z hz => hx z (List.mem_cons_of_mem x hz))\n        (fun z hz => hy z (List.mem_cons_of_mem y hz)) he.2]\n\nprivate theorem finRange_values (Q : ℕ) : (List.finRange Q).map Fin.val=List.range Q := by\n  apply List.ext_getElem\n  · simp\n  · intro i hi hj\n    simp\n\n/-- Actual acquired coordinate IDs are precisely the canonical numerical bytes. -/\ntheorem coordinate_ids (Q : ℕ) :\n    (SemiprimeSourceCompactWordIds.acquire Q).value=\n      (List.finRange Q).map (fun q => numberKey q.val) := by\n  apply compact_lists\n  · exact SemiprimeSourceCompactWordIds.acquire_compact Q\n  · intro key hk\n    obtain ⟨q,_,rfl⟩ := List.mem_map.mp hk\n    exact numberKey_compact q.val\n  · rw [SemiprimeSourceCompactWordIds.acquire_values,List.map_map]\n    simpa only [Function.comp_def,numberKey_value] using (finRange_values Q).symm\n\n/-- The acquired physical compact colour fields are the original finite coordinates. -/\ntheorem row_fields (r Q : ℕ) [NeZero r] (id : List Bool)\n    (hi : id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    ((SemiprimeSourceWordBank.readRow (SemiprimeSourceCompactWordBank.acquire r Q) id).value.map\n      (fun x => (SemiprimeSourceCompactBits.trim x.numerator.magnitude).bits))=\n      (List.finRange Q).map (fun q =>\n        numberKey ((SemiprimeSourceWordBankSemantics.decode r Q id) q).val) := by\n  apply compact_lists\n  · intro key hk\n    obtain ⟨x,_,rfl⟩ := List.mem_map.mp hk\n    exact SemiprimeSourceCompactBits.trim_compact _\n  · intro key hk\n    obtain ⟨q,_,rfl⟩ := List.mem_map.mp hk\n    exact numberKey_compact _\n  · apply (Nat.cast_injective (R:=ℚ)).list_map\n    have h := SemiprimeSourceHistogramRowKeys.original_colour_values r Q id hi\n    simpa only [List.map_map,Function.comp_def,numberKey_value,\n      SemiprimeSourceWordBankRows.coordinates,List.ofFn_eq_map] using h\n\nprivate theorem keys_fields (qs : List (List Bool)) (row : List RationalWord) :\n    SemiprimeSourceHistogramRowKeys.keys qs row=\n      (qs.zip (row.map (fun x => (SemiprimeSourceCompactBits.trim x.numerator.magnitude).bits))).map\n        (fun p => frame p.1 p.2) := by\n  induction qs generalizing row with\n  | nil => rfl\n  | cons q qs ih => cases row with\n    | nil => rfl\n    | cons x xs => exact congrArg (List.cons _) (ih xs)\n\nprivate theorem zip_same {A B C : Type*} (xs : List A) (f : A→B) (g : A→C) :\n    (xs.map f).zip (xs.map g)=xs.map (fun x => (f x,g x)) := by\n  induction xs with\n  | nil => rfl\n  | cons x xs ih => simp only [List.map_cons,List.zip_cons_cons,ih]\n\n/-- Original encoded row parsing yields exactly coordinate-major semantic keys. -/\ntheorem readKeys_semantic (r Q : ℕ) [NeZero r] (id : List Bool)\n    (hi : id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    (SemiprimeSourceHistogramRowKeys.readKeys (SemiprimeSourceHistogramRows.acquire r Q)\n      (SemiprimeSourceCompactWordIds.acquire Q).value id).keys=\n      (List.finRange Q).map (fun q => frame (numberKey q.val)\n        (numberKey ((SemiprimeSourceWordBankSemantics.decode r Q id) q).val)) := by\n  rw [SemiprimeSourceHistogramRowKeys.readKeys_original r Q id hi,keys_fields,\n    coordinate_ids,row_fields r Q id hi,zip_same,List.map_map]\n  rfl\n\n/-- Proof-side physical key of one actual original vertex-coordinate occurrence. -/\ndef headKey (r Q : ℕ) [NeZero r] (fixed : List (List Bool)) (v : ℕ) (q : Fin Q) : List Bool :=\n  frame (numberKey q.val)\n    (numberKey ((SemiprimeSourceHistogramDictRefinement.labels r Q fixed v) q).val)\n\n/-- Actual key equality is exactly original coordinate/colour equality. -/\ntheorem headKey_eq_iff (r Q : ℕ) [NeZero r] (fixed : List (List Bool))\n    (v w : ℕ) (q t : Fin Q) : headKey r Q fixed v q=headKey r Q fixed w t ↔\n      (q.val,((SemiprimeSourceHistogramDictRefinement.labels r Q fixed v) q).val)=\n        (t.val,((SemiprimeSourceHistogramDictRefinement.labels r Q fixed w) t).val) := by\n  unfold headKey\n  rw [SemiprimeSourceHistogramRowKeys.key_eq_iff,Prod.mk.injEq]\n  exact and_congr (numberKey_injective.eq_iff) (numberKey_injective.eq_iff)\n\n/-- Actual prefix data discharges the fixed-vertex key interpretation internally. -/\ntheorem original_one (r Q : ℕ) [NeZero r] (fixed : List (List Bool))\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids)\n    (key : List Bool) (hk : Compact key) :\n    (SemiprimeSourceHistogramRowKeys.readKeys\n      (SemiprimeSourceHistogramRowKeys.acquireCaches r Q).source.dictionary\n      (SemiprimeSourceHistogramRowKeys.acquireCaches r Q).coordinates\n      (SemiprimeSourceHistogramTrie.stored (SemiprimeSourceHistogramPrefix.acquire fixed).trie key)).keys=\n      (List.finRange Q).map (headKey r Q fixed (bitValue key)) := by\n  rw [SemiprimeSourceHistogramRowKeys.acquireCaches_dictionary,\n    SemiprimeSourceHistogramRowKeys.acquireCaches_coordinates,\n    readKeys_semantic r Q _ (SemiprimeSourceHistogramDictRefinement.stored_mem r Q fixed hf key)]\n  have hd := SemiprimeSourceHistogramDictRefinement.stored_decode r Q fixed key hk\n  rw [hd]\n  rfl\n\n/-- Exact original fixed-major occurrence stream, without quadratic term generation. -/\ntheorem produce_original_keys {n : ℕ} (r Q : ℕ) [NeZero r] (fixed : List (List Bool))\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids)\n    (k s : ℕ) (is : List (Fin n)) :\n    (produce (SemiprimeSourceHistogramRowKeys.acquireCaches r Q)\n      (SemiprimeSourceHistogramPrefix.acquire fixed).trie k s (verticesWith is).value).keys=\n      (is.filter (fun v => !(SemiprimeSourceHistogramFeatureBits.active k s v.val))).flatMap\n        (fun v => (List.finRange Q).map (headKey r Q fixed v.val)) := by\n  rw [produce_keys,verticesWith_value]\n  unfold keyList\n  rw [List.flatMap_map]\n  induction is with\n  | nil => rfl\n  | cons i is ih =>\n    have he := original_one r Q fixed hf (vertex i).value.key (vertex_rep i).1\n    rw [(vertex_rep i).2] at he\n    have hc : (vertex i).value.code=i.val := rfl\n    by_cases ha : SemiprimeSourceHistogramFeatureBits.active k s i.val=true\n    · simp only [List.flatMap_cons,hc,ha,ite_true,List.nil_append,\n        List.filter_cons,Bool.not_true,Bool.false_eq_true,ite_false,ih]\n    · simp only [List.flatMap_cons,hc,ha,Bool.false_eq_true,ite_false,List.filter_cons,\n        Bool.not_false,ite_true,List.flatMap_cons]\n      rw [he,ih]\n\nend RiemannGaussian.SemiprimeSourceHistogramHeadRefinement\n","RiemannGaussian.SemiprimeSourceHistogramSearch":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramQueryCorrectness\nimport RiemannGaussian.SemiprimeSourceWordIdControl\nimport RiemannGaussian.SemiprimeSourceScoreCountOrder\nimport RiemannGaussian.SemiprimeSourceScorePhysicalCaller\n\n/-! # Actual original source selection from one acquired histogram cache\nThe executed selector uses compact bank IDs and the concrete physical histogram\nquery. Original quadratic term lists and native word functions occur only in\nrefinement specifications. No score callback is supplied by the caller.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeSourceHistogramSearch\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT.MulticolorTypes\nopen SemiprimeMaterializedWords SemiprimeRationalBits\nopen SemiprimeSourceWordIdControl\nopen SemiprimeSourceWordBankSemantics (decode)\n\n/-- Compact acquired candidate IDs have the exact old first/tail menu ordering. -/\ntheorem tail_decode (n F r Q : ℕ) [NeZero r] (arity : Fin F→ℕ) :\n    ((SemiprimeSourceCompactWordBank.acquire r Q).ids.tail.map (decode r Q))=\n      (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value.wordTail := by\n  have h:=SemiprimeSourceCompactWordBank.ids_indexed n F r Q arity\n  rw [SemiprimeSourceCompactWordBank.default_head,List.map_cons] at h\n  exact (List.cons.inj h).2\n\n/-- The literal compact-zero candidate is the original first source word. -/\ntheorem first_decode (n F r Q : ℕ) [NeZero r] (arity : Fin F→ℕ) :\n    decode r Q []=(SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value.wordFirst := by\n  rw [SemiprimeSourceCompactWordBank.decode_default]\n  rfl\n\n/-- Actual canonical candidate membership, with no advised menu coverage. -/\ntheorem candidates_valid (r Q : ℕ) [NeZero r] :\n    InMenu (SemiprimeSourceCompactWordBank.acquire r Q).ids\n      ([]::(SemiprimeSourceCompactWordBank.acquire r Q).ids.tail) := by\n  intro id hi\n  simpa only [←SemiprimeSourceCompactWordBank.default_head r Q] using hi\n\n/-- The original count specification is exactly the old indexed sequential\ncount, not merely a proportional score or a permuted source term list. -/\ntheorem counts_indexed (n F r Q : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (fixed : List (List Bool)) (s : ℕ) :\n    let en := (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value\n    let programs := (SemiprimeMaterializedSourceWords.compileAll owner Sigma.fst\n      en.indices.values en.terms.values).value\n    SemiprimeSourceHistogramQueryCorrectness.originalCounts n F r Q arity owner fixed s=\n      (SemiprimeSourceScoreCountsObjective.sequentialCounts en.wordFirst en.wordTail programs s\n        (fixed.map (decode r Q))).value := by\n  dsimp only\n  have hfields:=SemiprimeSourceWordIdMetadata.indexed_fields n F r Q arity\n  have hmenu : (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value.wordFirst::\n      (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value.wordTail=\n      (SemiprimeFiniteEnumerations.words r Q).values :=\n    (SemiprimeSourceCompactWordBank.ids_indexed n F r Q arity).symm.trans\n      (SemiprimeSourceCompactWordBank.ids_decode r Q)\n  unfold SemiprimeSourceHistogramQueryCorrectness.originalCounts\n    SemiprimeSourceScoreCountsObjective.sequentialCounts\n  dsimp only\n  simp only [SemiprimeSourceHistogramHeadOriginal.originalEnv,List.length_map]\n  rw [hfields.2.1,hfields.2.2,←hmenu,first_decode n F r Q arity]\n\n/-- The concrete acquired query has exactly the original integer count objective\non every actual compact-menu prefix. No score/count oracle is supplied. -/\ntheorem query_integerValue (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (fixed : List (List Bool)) (s : ℕ)\n    (hf : InMenu (SemiprimeSourceCompactWordBank.acquire r Q).ids fixed) :\n    let en := (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value\n    let programs := (SemiprimeMaterializedSourceWords.compileAll owner Sigma.fst\n      en.indices.values en.terms.values).value\n    (SemiprimeSourceHistogramQuery.score\n      (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner) fixed s).word.value=\n      (SemiprimeSourceScoreCountOrder.integerValue (∑ e,arity e) n lam (r^(2*Q))\n        en.wordFirst en.wordTail programs s (fixed.map (decode r Q)):ℚ) := by\n  dsimp only\n  rw [SemiprimeSourceHistogramQueryCorrectness.score_original n F r Q lam arity owner fixed s hf]\n  simp only [counts_indexed]\n  rfl\n\n/-- Actual histogram queries preserve every original comparison, including ties. -/\ntheorem query_order (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (fixed : List (List Bool)) (v w : List Bool) (s : ℕ) (offset : ℚ)\n    (hf : InMenu (SemiprimeSourceCompactWordBank.acquire r Q).ids fixed)\n    (hv : v∈(SemiprimeSourceCompactWordBank.acquire r Q).ids)\n    (hw : w∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) (hlam : 0<lam) :\n    let en := (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value\n    let programs := (SemiprimeMaterializedSourceWords.compileAll owner Sigma.fst\n      en.indices.values en.terms.values).value\n    let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n    (SemiprimeSourceHistogramQuery.score cache (v::fixed) s).word.value ≤\n      (SemiprimeSourceHistogramQuery.score cache (w::fixed) s).word.value ↔\n    (SemiprimeMaterializedScoreSearch.sequential en.wordFirst en.wordTail programs\n      (((∑ e,arity e : ℕ):ℚ)/((r:ℚ)*(lam:ℚ)*(r^(2*Q):ℕ))) ((n:ℚ)/(2*(r:ℚ)))\n      offset s (decode r Q v::fixed.map (decode r Q))).value ≤\n    (SemiprimeMaterializedScoreSearch.sequential en.wordFirst en.wordTail programs\n      (((∑ e,arity e : ℕ):ℚ)/((r:ℚ)*(lam:ℚ)*(r^(2*Q):ℕ))) ((n:ℚ)/(2*(r:ℚ)))\n      offset s (decode r Q w::fixed.map (decode r Q))).value := by\n  dsimp only\n  rw [query_integerValue n F r Q lam arity owner (v::fixed) s (inMenu_cons _ fixed v hv hf),\n    query_integerValue n F r Q lam arity owner (w::fixed) s (inMenu_cons _ fixed w hw hf)]\n  let en := (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value\n  let programs := (SemiprimeMaterializedSourceWords.compileAll owner Sigma.fst\n    en.indices.values en.terms.values).value\n  have hcard : (en.wordFirst::en.wordTail).length^4=(r^(2*Q))^2 := by\n    simpa only [SemiprimeSourceOffsetHeight.caller_universal_length] using\n      SemiprimeSourceScoreCountOrder.caller_cardinality en\n  have hc:=SemiprimeSourceScoreCountOrder.integer_le_iff (∑ e,arity e) n lam (r^(2*Q))\n    en.wordFirst en.wordTail programs offset s s\n    ((v::fixed).map (decode r Q)) ((w::fixed).map (decode r Q))\n    (NeZero.pos r) hlam (pow_pos (NeZero.pos r) _) hcard\n  exact (show ((SemiprimeSourceScoreCountOrder.integerValue (∑ e,arity e) n lam (r^(2*Q))\n      en.wordFirst en.wordTail programs s ((v::fixed).map (decode r Q)):ℚ) ≤\n      (SemiprimeSourceScoreCountOrder.integerValue (∑ e,arity e) n lam (r^(2*Q))\n        en.wordFirst en.wordTail programs s ((w::fixed).map (decode r Q)):ℚ)) ↔\n      SemiprimeSourceScoreCountOrder.integerValue (∑ e,arity e) n lam (r^(2*Q))\n        en.wordFirst en.wordTail programs s ((v::fixed).map (decode r Q)) ≤\n      SemiprimeSourceScoreCountOrder.integerValue (∑ e,arity e) n lam (r^(2*Q))\n        en.wordFirst en.wordTail programs s ((w::fixed).map (decode r Q)) from by exact_mod_cast Iff.rfl).trans hc\n\n/-- Acquire setup ONCE, then use only the shared compact bank and concrete\nhistogram query for every original prefix/candidate score. -/\ndef run (n F r Q lam : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) : Run (List (List Bool)) :=\n  let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n  let bank := cache.rows.source.bank\n  let N := cache.data.metadata.indices.length\n  let result := SemiprimeSourceChoiceBits.run [] bank.ids.tail\n    (fun tokens fixed => SemiprimeSourceHistogramQuery.score cache fixed tokens.length) N []\n  ⟨result.value,cache.clock+result.work+N+4⟩\n\n/-- The setup acquisition report and every executed query/controller report remain paid. -/\ntheorem run_retains_setup (n F r Q lam : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner).clock ≤\n      (run n F r Q lam arity owner).work := by\n  unfold run\n  dsimp only\n  omega\n\n/-- Every selected output remains an actual compact candidate ID. -/\ntheorem run_valid (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    InMenu (SemiprimeSourceCompactWordBank.acquire r Q).ids (run n F r Q lam arity owner).value := by\n  change InMenu _ (SemiprimeSourceChoiceBits.run []\n    (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner).rows.source.bank.ids.tail\n    _ _ []).value\n  rw [SemiprimeSourceHistogramSetup.bank_actual]\n  exact assign_inMenu _ [] (SemiprimeSourceCompactWordBank.acquire r Q).ids.tail _ _ []\n    (candidates_valid r Q) (by simp [InMenu])\n\n\n/-- The actual selector returns one acquired ID for every original variable. -/\ntheorem run_length (n F r Q lam : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (run n F r Q lam arity owner).value.length=n+F := by\n  simp only [run,SemiprimeSourceChoiceBits.run,SemiprimeSourceChoiceBits.assign_length,\n    List.length_nil,Nat.zero_add,SemiprimeSourceChoiceBits.acquireTokens_value,List.length_replicate,\n    SemiprimeSourceHistogramSetup.metadata_actual]\n  exact (SemiprimeSourceHistogramMetadata.sizes n F Q arity).2.2.2.2\n\n/-- The concrete one-setup histogram selector returns exactly the old indexed\nsource search labels, including every original left-on-tie decision. -/\ntheorem run_refines (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (offset : ℚ) (hlam : 0<lam) :\n    let en := (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value\n    let programs := (SemiprimeMaterializedSourceWords.compileAll owner Sigma.fst\n      en.indices.values en.terms.values).value\n    (run n F r Q lam arity owner).value.map (decode r Q)=\n      (SemiprimeMaterializedScoreSearch.search en.wordFirst en.wordTail programs\n        (((∑ e,arity e : ℕ):ℚ)/((r:ℚ)*(lam:ℚ)*(r^(2*Q):ℕ))) ((n:ℚ)/(2*(r:ℚ)))\n        offset en.indices.values.length).value := by\n  let en := (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value\n  let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n  let programs := (SemiprimeMaterializedSourceWords.compileAll owner Sigma.fst\n    en.indices.values en.terms.values).value\n  have hn : cache.data.metadata.indices.length=en.indices.values.length := by\n    rw [SemiprimeSourceHistogramSetup.metadata_actual,\n      (SemiprimeSourceHistogramMetadata.original_fields n F Q arity).2,\n      (SemiprimeSourceWordIdMetadata.indexed_fields n F r Q arity).2.2]\n  have h:=SemiprimeSourceWordIdControl.run_decode\n    (SemiprimeSourceCompactWordBank.acquire r Q).ids (decode r Q) []\n    (SemiprimeSourceCompactWordBank.acquire r Q).ids.tail\n    (fun tokens fixed => SemiprimeSourceHistogramQuery.score cache fixed tokens.length)\n    (SemiprimeMaterializedScoreSearch.sequential en.wordFirst en.wordTail programs\n      (((∑ e,arity e : ℕ):ℚ)/((r:ℚ)*(lam:ℚ)*(r^(2*Q):ℕ))) ((n:ℚ)/(2*(r:ℚ))) offset)\n    (fun tokens fixed _ => SemiprimeSourceHistogramQuery.score_valid _ _ _)\n    (fun tokens fixed hf v hv w hw => query_order n F r Q lam arity owner fixed v w\n      tokens.length offset hf hv hw hlam)\n    en.indices.values.length [] (candidates_valid r Q) (by simp [InMenu])\n  rw [first_decode n F r Q arity,tail_decode n F r Q arity] at h\n  change (SemiprimeSourceChoiceBits.run [] cache.rows.source.bank.ids.tail\n    (fun tokens fixed => SemiprimeSourceHistogramQuery.score cache fixed tokens.length)\n    cache.data.metadata.indices.length []).value.map (decode r Q)=_\n  rw [SemiprimeSourceHistogramSetup.bank_actual,hn]\n  exact h\n\n\n/-- Exact old original source-caller labels from the new physical histogram\nselector, with no old descriptor list or old score callback on the runtime path. -/\ntheorem indexed_refines (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (hlam : 0<lam) :\n    let en := (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value\n    (run n F r Q lam arity owner).value.map (decode r Q)=\n      (SemiprimeSourceScorePhysicalCaller.computed owner Sigma.fst en lam).value := by\n  let en := (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value\n  let programs := (SemiprimeMaterializedSourceWords.compileAll owner Sigma.fst\n    en.indices.values en.terms.values).value\n  have hnew:=run_refines n F r Q lam arity owner 0 hlam\n  have hcard : (en.wordFirst::en.wordTail).length^4=(r^(2*Q))^2 := by\n    simpa only [SemiprimeSourceOffsetHeight.caller_universal_length] using\n      SemiprimeSourceScoreCountOrder.caller_cardinality en\n  have hold:=SemiprimeSourceScorePhysicalSearch.run_refines en.incidences.values.length n lam\n    en.wordFirst en.wordTail programs en.indices.values.length 0 (NeZero.pos r) hlam hcard\n  have hM : en.incidences.values.length=∑ e,arity e :=\n    SemiprimePaidFiniteEnumerations.indexed_incidence_length n F r Q arity\n  rw [←hM] at hnew\n  exact hnew.trans hold.symm\n\n/-- Exact ORIGINAL computed source labels for any shared proof-side offset.\nCandidate order, output order and all left-on-tie decisions are unchanged. -/\ntheorem indexed_original (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (hlam : 0<lam) (offset : ℚ) :\n    let en := (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value\n    (run n F r Q lam arity owner).value.map (decode r Q)=\n      (SemiprimeMaterializedSourceWords.computedList owner Sigma.fst en.wordFirst en.wordTail\n        en.terms.values en.indices.values (SemiprimeSourceScorePhysicalCaller.originalX en lam)\n        ((n:ℚ)/(2*(r:ℚ))) offset).value :=\n  (indexed_refines n F r Q lam arity owner hlam).trans\n    (SemiprimeSourceScorePhysicalCaller.computed_refines owner Sigma.fst\n      (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value lam hlam offset)\n\nend RiemannGaussian.SemiprimeSourceHistogramSearch\n","RiemannGaussian.SemiprimeSourceHistogramTrie":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceCompactBits\n\n/-! # Deterministic paid Boolean-key frequency trie\nTerminal values are optional compact physical counter words. Empty and prefix keys\nare distinct. Sibling/reference reuse is explicit persistent-node bookkeeping,\nnot a complete pointer/tape representation theorem.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceHistogramTrie\nopen SemiprimeBitArithmetic\nopen SemiprimeSourceCompactBits (Compact)\n\n/-- Physical Boolean-key trie, with a separate counter at each terminal position. -/\ninductive Trie where\n  /-- No terminal or child nodes have been acquired. -/\n  | empty\n  /-- Optional frequency payload and false/true children. -/\n  | node (payload : Option (List Bool)) (falseChild trueChild : Trie)\n  deriving Repr\n\n/-- Constant-field terminal lookup; no semantic count interpretation is executed. -/\ndef payload : Trie → Option (List Bool)\n  | .empty => none\n  | .node v _ _ => v\n\n/-- Actual one-bit branch selection. -/\ndef child : Trie → Bool → Trie\n  | .empty,_ => .empty\n  | .node _ l _,false => l\n  | .node _ _ r,true => r\n\n/-- Replace one actual branch while retaining the untouched immutable sibling. -/\ndef replace (t : Trie) (b : Bool) (next : Trie) : Trie :=\n  .node (payload t) (if b then child t false else next) (if b then next else child t true)\n\n/-- Proof-side physical payload at a key, absent keys denoting literal empty zero. -/\ndef stored (t : Trie) : List Bool → List Bool\n  | [] => (payload t).getD []\n  | b::bs => stored (child t b) bs\n\n/-- Mathematical frequency specification, never called to execute trie operations. -/\ndef value (t : Trie) (key : List Bool) : ℕ := bitValue (stored t key)\n\n/-- Physical lookup copies only the actual selected terminal counter. -/\ndef lookup : Trie → List Bool → SemiprimeSourceCompactBits.Report\n  | .empty,_ => ⟨[],2⟩\n  | .node v _ _,[] =>\n    let out := SemiprimeSourceCompactBits.copy (v.getD [])\n    ⟨out.bits,out.clock+8⟩\n  | .node _ l r,b::bs =>\n    let out := lookup (if b then r else l) bs\n    ⟨out.bits,out.clock+8⟩\n\n/-- Single-path update returns a physically copied OLD frequency and the new trie. -/\nstructure Bump where\n  /-- Exact old counter bits, physically copied once at the selected terminal. -/\n  old : List Bool\n  /-- Actual updated persistent trie. -/\n  trie : Trie\n  /-- Every visited key/node, terminal copy and compact increment report. -/\n  clock : ℕ\n\n/-- One actual key-path traversal; no second lookup or integer-count oracle. -/\ndef bump (t : Trie) : List Bool → Bump\n  | [] =>\n    let old := (payload t).getD []\n    let copied := SemiprimeSourceCompactBits.copy old\n    let next := SemiprimeSourceCompactBits.increment old\n    ⟨copied.bits,.node (some next.bits) (child t false) (child t true),copied.clock+next.clock+20⟩\n  | b::bs =>\n    let out := bump (child t b) bs\n    ⟨out.old,replace t b out.trie,out.clock+20⟩\n\n/-- Empty trie defaults are literal zero for all keys. -/\ntheorem stored_empty (key : List Bool) : stored .empty key=[] := by\n  induction key with\n  | nil => rfl\n  | cons b bs ih => simpa only [stored,child] using ih\n\n/-- Physical lookups preserve exact stored payload bits. -/\ntheorem lookup_bits (t : Trie) (key : List Bool) : (lookup t key).bits=stored t key := by\n  induction key generalizing t with\n  | nil => cases t <;> simp [lookup,stored,payload,SemiprimeSourceCompactBits.copy_bits]\n  | cons b bs ih =>\n    cases t with\n    | empty => simp [lookup,stored_empty]\n    | node v l r => cases b <;> simp [lookup,stored,child,ih]\n\n/-- Numeric lookup is exact, including absent and prefix keys. -/\ntheorem lookup_value (t : Trie) (key : List Bool) : bitValue (lookup t key).bits=value t key := by\n  rw [lookup_bits]\n  rfl\n\n/-- Bump returns the exact old physical payload from the same traversal. -/\ntheorem bump_old (t : Trie) (key : List Bool) : (bump t key).old=stored t key := by\n  induction key generalizing t with\n  | nil => simp only [bump,stored,SemiprimeSourceCompactBits.copy_bits]\n  | cons b bs ih => exact ih (child t b)\n\n/-- Exact changed-key payload and preservation of every other key, including prefixes. -/\ntheorem bump_stored (t : Trie) (key query : List Bool) :\n    stored (bump t key).trie query=\n      if query=key then (SemiprimeSourceCompactBits.increment (stored t key)).bits else stored t query := by\n  induction key generalizing t query with\n  | nil =>\n    cases query with\n    | nil => rfl\n    | cons b bs => cases t <;> cases b <;> simp [bump,stored,child,payload]\n  | cons b bs ih =>\n    cases query with\n    | nil => simp [bump,stored,replace,payload]\n    | cons c cs =>\n      cases b <;> cases c <;> simp [bump,stored,replace,child,ih]\n\n/-- Actual updated frequency, with no advised stored count or encoded answer. -/\ntheorem bump_value (t : Trie) (key query : List Bool) :\n    value (bump t key).trie query=if query=key then value t query+1 else value t query := by\n  unfold value\n  rw [bump_stored]\n  split_ifs with h\n  · subst query\n    exact SemiprimeSourceCompactBits.increment_value _\n  · rfl\n\n/-- Empty/default and prefix-terminal updates are included in exact same-key increment. -/\ntheorem bump_same (t : Trie) (key : List Bool) : value (bump t key).trie key=value t key+1 := by\n  simp only [bump_value,ite_true]\n\n/-- A distinct key's frequency is unchanged. -/\ntheorem bump_other (t : Trie) (key query : List Bool) (h : query≠key) :\n    value (bump t key).trie query=value t query := by simp only [bump_value,h,ite_false]\n\n/-- Logical persistent-node inventory; duplicate references are conservatively counted. -/\ndef nodes : Trie → ℕ\n  | .empty => 0\n  | .node _ l r => 1+nodes l+nodes r\n\n/-- Only one key path allocates nodes; no unvisited subtree is rebuilt. -/\ntheorem bump_nodes (t : Trie) (key : List Bool) :\n    nodes (bump t key).trie ≤ nodes t+key.length+1 := by\n  induction key generalizing t with\n  | nil => cases t <;> simp [bump,nodes,child,payload]\n  | cons b bs ih =>\n    have h := ih (child t b)\n    cases t <;> cases b <;> simp only [bump,replace,nodes,child,payload,List.length_cons,\n      Bool.false_eq_true,ite_false,ite_true] at h ⊢ <;> omega\n\n/-- Canonical counters at every stored terminal, absent positions included. -/\ndef CompactCounters (t : Trie) : Prop := ∀ key,Compact (stored t key)\n\n/-- Empty original dictionary has compact zero everywhere. -/\ntheorem empty_compact : CompactCounters .empty := by intro key;rw [stored_empty];trivial\n\n/-- Every actual update preserves canonical frequency counters. -/\ntheorem bump_compact (t : Trie) (key : List Bool) (ht : CompactCounters t) :\n    CompactCounters (bump t key).trie := by\n  intro query\n  rw [bump_stored]\n  split_ifs\n  · exact SemiprimeSourceCompactBits.increment_compact _\n  · exact ht query\n\nend RiemannGaussian.SemiprimeSourceHistogramTrie\n","RiemannGaussian.SemiprimeSourceIncidencePairAverage":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHeadCountFormula\n\n/-! # Conditional whole-word equality averages without completion enumeration -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceIncidencePairAverage\nopen OAI.Algorithms.SubexponentialSAT\nopen ConditionalExpectation LocalExpectation MulticolorTypes\nopen SemiprimeSourceHeadCountFormula\n\n/-- Conditional equality probability: a loop is certain; a genuinely free\nnonloop costs one uniform word; anchored endpoints are actually compared. -/\ndef pairPotential {W : Type*} [DecidableEq W] (L : ℕ) (remaining : List ℕ)\n    (ω : ℕ → W) (a c : ℕ) : ℚ :=\n  if a=c then 1 else if a∈remaining ∨ c∈remaining then 1/(L:ℚ)\n  else if ω a=ω c then 1 else 0\n\n/-- Averaging a fixed scalar multiple is exact on the supplied finite list. -/\ntheorem mean_mul_right {W : Type*} (alphabet : List W) (f : W → ℚ) (v : ℚ) :\n    mean alphabet (fun w => f w*v)=mean alphabet f*v := by\n  have hs : (alphabet.map (fun w => f w*v)).sum=(alphabet.map f).sum*v := by\n    induction alphabet with\n    | nil => simp\n    | cons a as ih => simp only [List.map_cons,List.sum_cons,ih];ring\n  simp only [mean,hs];ring\n\n/-- Symmetric scalar extraction, including the empty-list convention. -/\ntheorem mean_mul_left {W : Type*} (alphabet : List W) (f : W → ℚ) (v : ℚ) :\n    mean alphabet (fun w => v*f w)=v*mean alphabet f := by\n  simpa only [mul_comm v] using mean_mul_right alphabet f v\n\n/-- The actual complete canonical menu assigns probability exactly 1/L to\none specified whole word; no random or field-order assumption is used. -/\ntheorem mean_delta (r Q : ℕ) (w : Word r Q) :\n    mean (alphabet r Q) (fun z => if z=w then 1 else 0)=1/(r^Q:ℕ) := by\n  classical\n  have hs : ((alphabet r Q).map (fun z => if z=w then (1:ℚ) else 0)).sum=1 := by\n    have hu : (alphabet r Q).toFinset=Finset.univ := by\n      ext z\n      simp only [List.mem_toFinset,Finset.mem_univ,iff_true]\n      exact (SemiprimeFiniteEnumerations.words r Q).complete z\n    have hn : (alphabet r Q).Nodup := (SemiprimeFiniteEnumerations.words r Q).nodup\n    rw [← List.sum_toFinset _ hn,hu]\n    simp\n  simp only [mean,hs,alphabet_length]\n\n/-- Updating a key outside an edge cannot change its conditional potential. -/\ntheorem pair_update_other {W : Type*} [DecidableEq W] (L : ℕ) (remaining : List ℕ)\n    (ω : ℕ → W) (a c i : ℕ) (w : W) (hia : i≠a) (hic : i≠c) :\n    pairPotential L remaining (Function.update ω i w) a c=\n      pairPotential L remaining ω a c := by\n  simp only [pairPotential,Function.update_of_ne (Ne.symm hia),\n    Function.update_of_ne (Ne.symm hic)]\n\n/-- One exact elimination step, valid for every current anchored environment. -/\ntheorem pair_mean_step (r Q : ℕ) (hr : 0<r) (remaining : List ℕ)\n    (ω : ℕ → Word r Q) (a c i : ℕ) (hi : i∉remaining) :\n    mean (alphabet r Q) (fun w => pairPotential (r^Q) remaining\n      (Function.update ω i w) a c)=pairPotential (r^Q) (i::remaining) ω a c := by\n  classical\n  have hne : alphabet r Q≠[] := by\n    have hl : 0<(alphabet r Q).length := by rw [alphabet_length];exact pow_pos hr Q\n    exact List.ne_nil_of_length_pos hl\n  by_cases hac : a=c\n  · subst c\n    simpa only [pairPotential,ite_eq_left_iff,ite_true] using mean_const (alphabet r Q) hne (1:ℚ)\n  by_cases hia : i=a\n  · subst i\n    by_cases hc : c∈remaining\n    · simp only [pairPotential,hac,ite_false,List.mem_cons_self,true_or,ite_true,hc,or_true]\n      exact mean_const _ hne _\n    · simp only [pairPotential,hac,ite_false,hi,hc,false_or,List.mem_cons_self,true_or,\n        ite_true,Function.update_same,Function.update_of_ne (Ne.symm hac)]\n      exact mean_delta r Q (ω c)\n  by_cases hic : i=c\n  · subst i\n    by_cases ha : a∈remaining\n    · simp only [pairPotential,hac,ite_false,List.mem_cons_self,or_true,ite_true,ha,true_or]\n      exact mean_const _ hne _\n    · simp only [pairPotential,hac,ite_false,hi,ha,false_or,List.mem_cons_self,or_true,\n        ite_true,Function.update_same,Function.update_of_ne hac]\n      simpa only [eq_comm] using mean_delta r Q (ω a)\n  · simp_rw [pair_update_other (r^Q) remaining ω a c i _ hia hic]\n    rw [mean_const _ hne]\n    simp only [pairPotential,List.mem_cons,Ne.symm hia,Ne.symm hic,false_or]\n\n/-- At an empty remaining list the potential is the literal equality test. -/\ntheorem pair_nil {W : Type*} [DecidableEq W] (L : ℕ) (ω : ℕ → W) (a c : ℕ) :\n    pairPotential L [] ω a c=(if ω a=ω c then 1 else 0) := by\n  by_cases h : a=c\n  · subst c;simp [pairPotential]\n  · simp [pairPotential,h]\n\n/-- Exact conditional average of one whole-word equality for every prefix. -/\ntheorem pair_average (r Q : ℕ) (hr : 0<r) (remaining : List ℕ)\n    (hn : remaining.Nodup) (ω : ℕ → Word r Q) (a c : ℕ) :\n    wordExpectation (alphabet r Q) (fun v => if v a=v c then 1 else 0)\n      remaining ω=pairPotential (r^Q) remaining ω a c := by\n  induction remaining generalizing ω with\n  | nil => simp only [wordExpectation,pair_nil]\n  | cons i rest ih =>\n    simp only [wordExpectation]\n    have hmap : (fun w => wordExpectation (alphabet r Q)\n        (fun v => if v a=v c then 1 else 0) rest (Function.update ω i w))=\n        (fun w => pairPotential (r^Q) rest (Function.update ω i w) a c) := by\n      funext w\n      exact ih hn.of_cons _\n    rw [hmap]\n    exact pair_mean_step r Q hr rest ω a c i (List.nodup_cons.mp hn).1\n\n/-- Disjoint equality pairs remain independent after an arbitrary ordered\nprefix, including all aliases within either pair. -/\ntheorem separated_average (r Q : ℕ) (hr : 0<r) (remaining : List ℕ)\n    (hn : remaining.Nodup) (ω : ℕ → Word r Q) (a b c d : ℕ)\n    (hab : a≠b) (had : a≠d) (hcb : c≠b) (hcd : c≠d) :\n    wordExpectation (alphabet r Q)\n      (fun v => (if v a=v c then 1 else 0)*(if v b=v d then 1 else 0))\n      remaining ω=pairPotential (r^Q) remaining ω a c*\n        pairPotential (r^Q) remaining ω b d := by\n  induction remaining generalizing ω with\n  | nil => simp only [wordExpectation,pair_nil]\n  | cons i rest ih =>\n    simp only [wordExpectation]\n    have hmap : (fun w => wordExpectation (alphabet r Q)\n        (fun v => (if v a=v c then 1 else 0)*(if v b=v d then 1 else 0))\n        rest (Function.update ω i w))=\n      (fun w => pairPotential (r^Q) rest (Function.update ω i w) a c*\n        pairPotential (r^Q) rest (Function.update ω i w) b d) := by\n      funext w\n      exact ih hn.of_cons _\n    rw [hmap]\n    by_cases hia : i=a ∨ i=c\n    · have hib : i≠b := by rcases hia with h|h <;> subst i <;> assumption\n      have hid : i≠d := by rcases hia with h|h <;> subst i <;> assumption\n      simp_rw [pair_update_other (r^Q) rest ω b d i _ hib hid]\n      rw [mean_mul_right,pair_mean_step r Q hr rest ω a c i (List.nodup_cons.mp hn).1]\n      congr 1\n      simp only [pairPotential,List.mem_cons,Ne.symm hib,Ne.symm hid,false_or]\n    · have hia' : i≠a := fun h => hia (Or.inl h)\n      have hic : i≠c := fun h => hia (Or.inr h)\n      simp_rw [pair_update_other (r^Q) rest ω a c i _ hia' hic]\n      rw [mean_mul_left,pair_mean_step r Q hr rest ω b d i (List.nodup_cons.mp hn).1]\n      congr 1\n      simp only [pairPotential,List.mem_cons,Ne.symm hia',Ne.symm hic,false_or]\n\nend RiemannGaussian.SemiprimeSourceIncidencePairAverage\n","RiemannGaussian.SemiprimeSourceScoreWeightBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceOffsetInputsCore\n\n/-! # Physical unsigned weighting of the original integer source counts\nAll multiplications and the final sum execute Boolean circuits. Natural dimensions\nremain host loop inputs at the explicitly acquired initializer boundary.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceScoreWeightBits\nopen SemiprimeBitArithmetic SemiprimeSourceOffsetInputsCore SemiprimeRationalBits\n\n/-- Two cached integer weights and the work of their actual acquisition. -/\nstructure Weights where\n  /-- Weight of the incidence count. -/\n  incidence : List Bool\n  /-- Weight of the head count. -/\n  head : List Bool\n  /-- Seven executed multiplication reports and control/cell work. -/\n  clock : ℕ\n\n/-- Cache both weights once from the four original acquired unsigned words. -/\ndef weights (M n lam U : List Bool) : Weights :=\n  let nn := mulBits n n\n  let ll := mulBits lam lam\n  let uu := mulBits U U\n  let nl := mulBits nn.bits ll.bits\n  let a := mulBits nl.bits uu.bits\n  let mm := mulBits M M\n  let b := mulBits [false,false,true] mm.bits\n  ⟨a.bits,b.bits,bitCost nn+bitCost ll+bitCost uu+bitCost nl+bitCost a+\n    bitCost mm+bitCost b+M.length+n.length+lam.length+U.length+30⟩\n\n/-- Exact incidence and head coefficients of the physical weighted count. -/\ntheorem weights_value (M n lam U : List Bool) :\n    bitValue (weights M n lam U).incidence=bitValue n^2*bitValue lam^2*bitValue U^2 ∧\n      bitValue (weights M n lam U).head=4*bitValue M^2 := by\n  simp only [weights,mulBits_correct,bitValue,bitNat,Bool.false_eq_true,ite_false,\n    ite_true]\n  constructor <;> ring\n\n/-- Per-candidate physical multiplication and summation, reusing cached weights. -/\ndef combine (w : Weights) (I H : List Bool) : NatRun :=\n  let a := mulBits w.incidence I\n  let b := mulBits w.head H\n  let out := addBits a.bits b.bits false\n  ⟨out.bits,bitCost a+bitCost b+bitCost out+I.length+H.length+10⟩\n\n/-- The count words, rather than advised count integers, drive the circuit. -/\ntheorem combine_value (w : Weights) (I H : List Bool) :\n    bitValue (combine w I H).bits=\n      bitValue w.incidence*bitValue I+bitValue w.head*bitValue H := by\n  simp [combine,addBits_correct,mulBits_correct,bitNat]\n\n/-- Denominator-one physical comparator input, without rational normalization. -/\ndef scoreWord (w : Weights) (I H : List Bool) : RationalWord :=\n  ⟨⟨false,(combine w I H).bits⟩,[true]⟩\n\n/-- A denominator-one output is always legal, independently of its magnitude. -/\ntheorem scoreWord_valid (w : Weights) (I H : List Bool) : (scoreWord w I H).Valid := by\n  change 0<(1:ℕ)\n  decide\n\n/-- Decoding is used only to state correctness of the physical output. -/\ntheorem scoreWord_value (w : Weights) (I H : List Bool) :\n    (scoreWord w I H).value=\n      ((bitValue w.incidence*bitValue I+bitValue w.head*bitValue H:ℕ):ℚ) := by\n  simp [scoreWord,RationalWord.value,SemiprimeBitIndexClipping.SignedWord.value,\n    combine_value,bitValue,bitNat]\n\n/-- Uniform physical size for both cached weights. -/\ndef weightWidth (L : ℕ) : ℕ := 100*(L+1)\n\n/-- Both actual weight arrays have polynomial size in the original input widths. -/\ntheorem weights_length (M n lam U : List Bool) (L : ℕ)\n    (hM : M.length ≤ L) (hn : n.length ≤ L) (hl : lam.length ≤ L) (hU : U.length ≤ L) :\n    (weights M n lam U).incidence.length ≤ weightWidth L ∧\n      (weights M n lam U).head.length ≤ weightWidth L := by\n  have h1 := mulBits_length n n\n  have h2 := mulBits_length lam lam\n  have h3 := mulBits_length U U\n  have h4 := mulBits_length (mulBits n n).bits (mulBits lam lam).bits\n  have h5 := mulBits_length (mulBits (mulBits n n).bits (mulBits lam lam).bits).bits\n    (mulBits U U).bits\n  have h6 := mulBits_length M M\n  have h7 := mulBits_length [false,false,true] (mulBits M M).bits\n  simp only [List.length_cons,List.length_nil] at h7\n  dsimp only [weights,weightWidth]\n  constructor <;> omega\n\n/-- Generic physical multiplier cost with bounded original operand arrays. -/\ntheorem mul_cost_le (a b : List Bool) (L : ℕ) (ha : a.length ≤ L) (hb : b.length ≤ L) :\n    bitCost (mulBits a b) ≤ 12*L*(2*L+2)+1 := by\n  apply (mulBits_cost a b).trans\n  gcongr\n  omega\n\n/-- Closed acquisition budget for the seven cached-weight products. -/\ndef weightBudget (L : ℕ) : ℕ :=\n  7*(12*weightWidth L*(2*weightWidth L+2)+1)+4*L+30\n\n/-- All actual products and their original input scans are retained. -/\ntheorem weights_clock (M n lam U : List Bool) (L : ℕ)\n    (hM : M.length ≤ L) (hn : n.length ≤ L) (hl : lam.length ≤ L) (hU : U.length ≤ L) :\n    (weights M n lam U).clock ≤ weightBudget L := by\n  let K := weightWidth L\n  have hk : L ≤ K := by dsimp [K,weightWidth];omega\n  have h1 := mulBits_length n n\n  have h2 := mulBits_length lam lam\n  have h3 := mulBits_length U U\n  have h4 := mulBits_length (mulBits n n).bits (mulBits lam lam).bits\n  have h6 := mulBits_length M M\n  have hc1 := mul_cost_le n n K (hn.trans hk) (hn.trans hk)\n  have hc2 := mul_cost_le lam lam K (hl.trans hk) (hl.trans hk)\n  have hc3 := mul_cost_le U U K (hU.trans hk) (hU.trans hk)\n  have hc4 := mul_cost_le (mulBits n n).bits (mulBits lam lam).bits K\n    (by dsimp [K,weightWidth];omega) (by dsimp [K,weightWidth];omega)\n  have hc5 := mul_cost_le (mulBits (mulBits n n).bits (mulBits lam lam).bits).bits\n    (mulBits U U).bits K (by dsimp [K,weightWidth];omega) (by dsimp [K,weightWidth];omega)\n  have hc6 := mul_cost_le M M K (hM.trans hk) (hM.trans hk)\n  have hc7 := mul_cost_le [false,false,true] (mulBits M M).bits K\n    (by simp only [List.length_cons,List.length_nil];dsimp [K,weightWidth];omega)\n    (by dsimp [K,weightWidth];omega)\n  dsimp only [weights,weightBudget]\n  change _ ≤ 7*(12*K*(2*K+2)+1)+4*L+30\n  omega\n\n/-- Uniform per-candidate output width from actual operand widths. -/\ntheorem combine_length (w : Weights) (I H : List Bool) (L : ℕ)\n    (ha : w.incidence.length ≤ L) (hb : w.head.length ≤ L)\n    (hi : I.length ≤ L) (hh : H.length ≤ L) :\n    (combine w I H).bits.length ≤ 3*L+1 := by\n  have h1 := mulBits_length w.incidence I\n  have h2 := mulBits_length w.head H\n  have h3 := (addBits_counts (mulBits w.incidence I).bits\n    (mulBits w.head H).bits false).2.2.2.2\n  dsimp only [combine]\n  omega\n\n/-- Per-candidate Boolean circuit and original count scans. -/\ndef combineBudget (L : ℕ) : ℕ := 2*(12*L*(2*L+2)+1)+33*L+2*L+14\n\n/-- Polynomial per-candidate cost requires only actual operand widths. -/\ntheorem combine_clock (w : Weights) (I H : List Bool) (L : ℕ)\n    (ha : w.incidence.length ≤ L) (hb : w.head.length ≤ L)\n    (hi : I.length ≤ L) (hh : H.length ≤ L) :\n    (combine w I H).clock ≤ combineBudget L := by\n  have h1 := mulBits_length w.incidence I\n  have h2 := mulBits_length w.head H\n  have hc1 := mul_cost_le w.incidence I L ha hi\n  have hc2 := mul_cost_le w.head H L hb hh\n  have hc3 := addBits_cost (mulBits w.incidence I).bits (mulBits w.head H).bits false\n  have hmax : max (mulBits w.incidence I).bits.length (mulBits w.head H).bits.length ≤ 3*L := by\n    apply max_le <;> omega\n  dsimp only [combine,combineBudget]\n  omega\n\nend RiemannGaussian.SemiprimeSourceScoreWeightBits\n","RiemannGaussian.SemiprimeSourceWordBankBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceWordBankSemantics\n\n/-! # Physical original word-bank validity, widths and acquisition/lookup work -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceWordBankBounds\nopen SemiprimeSourceWordBank SemiprimeSourceWordBankRows SemiprimeRationalBits\nopen SemiprimeSourceScorePredicateBits SemiprimeSourceScorePredicateBitsBounds\nopen SemiprimeBitArithmetic SemiprimeBitDivision SemiprimeBitPrimeScan SemiprimeBitProductSort\nopen SemiprimeSourceOffsetInputsCore SemiprimeMaterializedSourceUniversal\n\n/-- Every physically acquired original colour is valid with width derived from r. -/\ntheorem colours_good (r : ℕ) :\n    ∀ x∈(colours r).value,x.Valid ∧ Width x (r+1) := by\n  intro x hx\n  simp only [colours,collect_value,SemiprimePaidFiniteEnumerationLists.fin_value,List.mem_map] at hx\n  obtain ⟨i,_,rfl⟩ := hx\n  exact ⟨(encodeNat_spec i.val).2.1,width_mono (encodeNat_spec i.val).2.2 (by omega)⟩\n\n/-- Generic row construction preserves all actually copied payloads and their bounds. -/\ntheorem rowsWith_good (cs : List RationalWord) (W q : ℕ)\n    (hc : ∀ x∈cs,x.Valid ∧ Width x W) :\n    ∀ row∈(rowsWith cs q).value,∀ x∈row,x.Valid ∧ Width x W := by\n  induction q with\n  | zero => simp [rowsWith]\n  | succ q ih =>\n    intro row hr x hx\n    simp only [rowsWith,collect_value,SemiprimePaidFiniteEnumerationLists.product_value,List.mem_map] at hr\n    obtain ⟨p,hp,rfl⟩ := hr\n    rw [prepend_value] at hx\n    rcases List.mem_cons.mp hx with rfl|hx\n    · exact hc p.1 (List.mem_product.mp hp).1\n    · exact ih p.2 (List.mem_product.mp hp).2 x hx\n\n/-- Original acquired bank payloads have a uniform original-dimension bound. -/\ntheorem acquire_good (r Q : ℕ) :\n    ∀ row∈(acquire r Q).rows,∀ x∈row,x.Valid ∧ Width x (r+1) :=\n  rowsWith_good (colours r).value (r+1) Q (colours_good r)\n\n/-- Original row lengths are exact, not a supplied generic cache condition. -/\ntheorem acquire_row_length (r Q : ℕ) :\n    ∀ row∈(acquire r Q).rows,row.length=Q := rowsWith_length _ _\n\n/-- Even out-of-range lookup preserves validity and payload-width bounds. -/\ntheorem readRow_good (r Q : ℕ) (id : List Bool) :\n    ∀ x∈(readRow (acquire r Q) id).value,x.Valid ∧ Width x (r+1) := by\n  rw [readRow_value]\n  cases h : (acquire r Q).rows[bitValue id]? with\n  | none => simp\n  | some row => exact acquire_good r Q row (List.mem_of_getElem? h)\n\n/-- Physical lookup includes every visited-row copy, address test and decrement. -/\ntheorem readRows_clock (rows : List Row) (address : List Bool) (W Q B : ℕ)\n    (hB : 1≤B) (ha : address.length≤B)\n    (hr : ∀ row∈rows,row.length≤Q ∧ ∀ x∈row,Width x W) :\n    (readRows rows address).work≤(rows.length+1)*(copyBudget W Q+15*B+30) := by\n  induction rows generalizing address with\n  | nil => simp only [readRows,List.length_nil];omega\n  | cons row rows ih =>\n    have hh := hr row List.mem_cons_self\n    have hv := copyRow_work row W Q hh\n    have ht := nonzeroBits_cost address\n    have hd := subBits_cost address [true] false\n    have hlen : (subBits address [true] false).result.bits.length≤B := by\n      rw [(subBits_counts address [true] false).2.2.2.2]\n      simp only [List.length_cons,List.length_nil]\n      exact max_le ha hB\n    have hc := ih (subBits address [true] false).result.bits hlen\n      (fun row h => hr row (List.mem_cons_of_mem _ h))\n    have hm : max address.length [true].length≤B := max_le ha (by simpa using hB)\n    simp only [readRows,List.length_cons]\n    split_ifs <;> dsimp only <;> nlinarith\n\n/-- Explicit original bank lookup work, paid in original cardinality and bit lengths. -/\ntheorem readRow_clock (r Q : ℕ) (id : List Bool) (B : ℕ) (hB : 1≤B) (hi : id.length≤B) :\n    (readRow (acquire r Q) id).work≤\n      (r^Q+1)*(copyBudget (r+1) Q+15*B+30) := by\n  have h := readRows_clock (acquire r Q).rows id (r+1) Q B hB hi (by\n    intro row hr\n    exact ⟨(acquire_row_length r Q row hr).le,fun x hx => (acquire_good r Q row hr x hx).2⟩)\n  simpa only [acquire,readRow,SemiprimeSourceWordBankSemantics.rows_length] using h\n\nend RiemannGaussian.SemiprimeSourceWordBankBounds\n","RiemannGaussian.SemiprimeStagedSeed":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHead\n\n/-!\n# Raw seed screening and checked staged projection\n\nThe raw N-1 power has coprime local orders. With the public repetition\ncount, a factorial stage cannot send two nontrivial local components to\none simultaneously. Checking the GCD after every stage therefore exposes\na proper factor before a nontrivial raw seed can collapse globally.\nFinding a raw seed within a sixth-root public scan remains a separate\nunproved requirement; no universal factoring exponent is claimed here.\n-/\n\nnamespace RiemannGaussian.SemiprimeStagedSeed\n\nopen SemiprimeCentreFreeCover\n\n/-- A successor stage reuses the preceding power. -/\ntheorem stagedProjection_succ {G : Type*} [Monoid G] (g : G) (i L : ℕ) :\n    stagedProjection g (i+1) L=(stagedProjection g i L)^((i+1)^L) := by\n  simp only [stagedProjection, List.range_succ, List.foldl_append, List.foldl_cons,\n    List.foldl_nil]\n\n/-- Once the smaller prime factors have been removed, one stage cannot\nannihilate both nontrivial components of coprime local order. -/\ntheorem factorial_step_not_both_one {G H : Type*} [Group G] [Finite G]\n    [Group H] [Finite H] (g : G) (h : H) (i L : ℕ)\n    (hc : (orderOf g).Coprime (orderOf h))\n    (hgBound : orderOf g<2^L) (hhBound : orderOf h<2^L)\n    (hg : g^((i.factorial)^L)≠1) (hh : h^((i.factorial)^L)≠1) :\n    ¬(g^(((i+1).factorial)^L)=1 ∧ h^(((i+1).factorial)^L)=1) := by\n  intro hnext\n  have he (x : G) : x^(((i+1).factorial)^L)=\n      (x^((i.factorial)^L))^((i+1)^L) := by\n    rw [Nat.factorial_succ, mul_pow, Nat.mul_comm, pow_mul]\n  have he' (x : H) : x^(((i+1).factorial)^L)=\n      (x^((i.factorial)^L))^((i+1)^L) := by\n    rw [Nat.factorial_succ, mul_pow, Nat.mul_comm, pow_mul]\n  obtain ⟨r, hr, hrd⟩ := Nat.exists_prime_and_dvd\n    (fun horder => hg (orderOf_eq_one_iff.mp horder))\n  obtain ⟨s, hs, hsd⟩ := Nat.exists_prime_and_dvd\n    (fun horder => hh (orderOf_eq_one_iff.mp horder))\n  have hrpow : r ∣ (i+1)^L := hrd.trans\n    (orderOf_dvd_of_pow_eq_one (he g ▸ hnext.1))\n  have hspow : s ∣ (i+1)^L := hsd.trans\n    (orderOf_dvd_of_pow_eq_one (he' h ▸ hnext.2))\n  have hrle := Nat.le_of_dvd (show 0 < i+1 by omega) (hr.dvd_of_dvd_pow hrpow)\n  have hsle := Nat.le_of_dvd (show 0 < i+1 by omega) (hs.dvd_of_dvd_pow hspow)\n  have hrgt := factorial_projection_rough g (le_refl _) hgBound hr hrd\n  have hsgt := factorial_projection_rough h (le_refl _) hhBound hs hsd\n  have hrs : r=s := by omega\n  have hcp := hc.of_dvd (hrd.trans (orderOf_pow_dvd _))\n    (hsd.trans (orderOf_pow_dvd _))\n  rw [← hrs, Nat.coprime_self] at hcp\n  exact hr.ne_one hcp\n\n/-- The public logarithmic repetition count dominates the raw order in\neither prime field; no local order is an algorithm input. -/\ntheorem raw_order_lt_public_repetitions {p q : ℕ} (hp : p.Prime) (hq : 0<q)\n    (g : (ZMod p)ˣ) : orderOf (g^(p*q-1))<2^(Nat.clog 2 (p*q+1)) := by\n  let : Fact p.Prime := ⟨hp⟩\n  have hbound : orderOf (g^(p*q-1))≤p-1 :=\n    Nat.le_of_dvd (by have h := hp.one_lt; omega)\n      (ZMod.orderOf_units_dvd_card_sub_one _)\n  have hpN : p-1<p*q+1 := by\n    have hpp : p≤p*q := by nlinarith\n    omega\n  exact hbound.trans_lt (hpN.trans_le (Nat.le_pow_clog (by decide) _))\n\n/-- Every stage is mapped from the same retained public raw seed. -/\ntheorem map_staged_raw {N r : ℕ} (hrN : r∣N) (g : (ZMod N)ˣ) (i L : ℕ) :\n    Units.map (ZMod.castHom hrN (ZMod r)).toMonoidHom\n      (stagedProjection (g^(N-1)) i L)=\n    ((Units.map (ZMod.castHom hrN (ZMod r)).toMonoidHom g)^(N-1))^\n      ((i.factorial)^L) := by\n  rw [stagedProjection_eq]\n  simp only [map_pow]\n\n/-- Retain the public unit at every stage, before extracting its GCD. -/\ndef publicStage {N : ℕ} (g : (ZMod N)ˣ) (i : ℕ) : (ZMod N)ˣ :=\n  stagedProjection (g^(N-1)) i (Nat.clog 2 (N+1))\n\n/-- Literal public residual GCD at a charged projection stage. -/\ndef stageGcd {N : ℕ} (g : (ZMod N)ˣ) (i : ℕ) : ℕ :=\n  N.gcd ((publicStage g i : ZMod N)-1).val\n\n/-- A clear preceding stage rules out a globally trivial successor.\nAny component which closes first must therefore expose a proper GCD. -/\ntheorem stage_gcd_ne_modulus_of_clear {p q : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (g : (ZMod (p*q))ˣ) (i : ℕ) (hclear : stageGcd g i=1) :\n    stageGcd g (i+1)≠p*q := by\n  let : NeZero (p*q) := ⟨Nat.mul_ne_zero hp.ne_zero hq.ne_zero⟩\n  let L := Nat.clog 2 (p*q+1)\n  let gp := Units.map (ZMod.castHom (dvd_mul_right p q) (ZMod p)).toMonoidHom g\n  let gq := Units.map (ZMod.castHom (dvd_mul_left q p) (ZMod q)).toMonoidHom g\n  change (p*q).gcd ((stagedProjection (g^(p*q-1)) i L : (ZMod (p*q))ˣ)-1 :\n    ZMod (p*q)).val=1 at hclear\n  have hpClear := clear_unit_component_order_ne_one hp (dvd_mul_right p q)\n    (stagedProjection (g^(p*q-1)) i L) hclear\n  have hqClear := clear_unit_component_order_ne_one hq (dvd_mul_left q p)\n    (stagedProjection (g^(p*q-1)) i L) hclear\n  rw [map_staged_raw] at hpClear hqClear\n  have hstep := factorial_step_not_both_one (gp^(p*q-1)) (gq^(p*q-1)) i L\n    (SemiprimeOrderSeparation.projected_orders_coprime hp hq gp gq)\n    (raw_order_lt_public_repetitions hp hq.pos gp)\n    (by simpa [Nat.mul_comm] using raw_order_lt_public_repetitions hq hp.pos gq)\n    (fun he => hpClear (orderOf_eq_one_iff.mpr he))\n    (fun he => hqClear (orderOf_eq_one_iff.mpr he))\n  intro hcollapse\n  have hz := SemiprimeSourceHead.residual_zero_of_gcd_eq_modulus\n    ((publicStage g (i+1) : ZMod (p*q))-1) hcollapse\n  have hunit : publicStage g (i+1)=1 :=\n    Units.ext (sub_eq_zero.mp hz)\n  apply hstep\n  constructor\n  · have he := congrArg (Units.map\n      (ZMod.castHom (dvd_mul_right p q) (ZMod p)).toMonoidHom) hunit\n    simpa only [publicStage, map_staged_raw, map_one] using he\n  · have he := congrArg (Units.map\n      (ZMod.castHom (dvd_mul_left q p) (ZMod q)).toMonoidHom) hunit\n    simpa only [publicStage, map_staged_raw, map_one] using he\n\n/-- A globally nontrivial raw seed cannot start at the full-modulus GCD. -/\ntheorem raw_gcd_ne_modulus {N : ℕ} [NeZero N] (g : (ZMod N)ˣ)\n    (hraw : g^(N-1)≠1) : stageGcd g 0≠N := by\n  intro he\n  have hz := SemiprimeSourceHead.residual_zero_of_gcd_eq_modulus\n    ((publicStage g 0 : ZMod N)-1) he\n  apply hraw\n  have hu : publicStage g 0=1 := Units.ext (sub_eq_zero.mp hz)\n  simpa only [publicStage, stagedProjection, List.range_zero, List.foldl_nil] using hu\n\n/-- Every GCD after screening is clear unless an actual proper factor\nhas appeared in this same public trace. -/\ntheorem all_stages_clear_of_no_proper {p q : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (g : (ZMod (p*q))ˣ) (hraw : g^(p*q-1)≠1) (B : ℕ)\n    (hno : ∀ i≤B, ¬(1<stageGcd g i ∧ stageGcd g i<p*q)) :\n    stageGcd g B=1 := by\n  let : NeZero (p*q) := ⟨Nat.mul_ne_zero hp.ne_zero hq.ne_zero⟩\n  have hN : 0<p*q := Nat.mul_pos hp.pos hq.pos\n  have hpos (i : ℕ) : 0<stageGcd g i := Nat.gcd_pos_of_pos_left _ hN\n  have hle (i : ℕ) : stageGcd g i≤p*q := Nat.gcd_le_left _ hN\n  induction B with\n  | zero =>\n    have hnN := raw_gcd_ne_modulus g hraw\n    have hn := hno 0 (le_refl _)\n    have hl := hle 0\n    have hp0 := hpos 0\n    omega\n  | succ B ih =>\n    have hprev := ih (fun i hi => hno i (by omega))\n    have hnN := stage_gcd_ne_modulus_of_clear hp hq g B hprev\n    have hn := hno (B+1) (le_refl _)\n    have hl := hle (B+1)\n    have hp0 := hpos (B+1)\n    omega\n\n/-- Screening once suffices: either a staged GCD is a proper factor or\nthe final projected unit has clear GCD. This does not assert a short\nscan always contains such a raw seed. -/\ntheorem public_projection_clear_or_factor {p q : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (g : (ZMod (p*q))ˣ) (hraw : g^(p*q-1)≠1) (B : ℕ) :\n    (∃ i≤B, SemiprimeGroupSelection.ProperDivisor (p*q) (stageGcd g i)) ∨\n      stageGcd g B=1 := by\n  by_cases he : ∃ i≤B, 1<stageGcd g i ∧ stageGcd g i<p*q\n  · obtain ⟨i, hi, h1, hN⟩ := he\n    exact Or.inl ⟨i, hi, h1, hN, Nat.gcd_dvd_left _ _⟩\n  · right\n    apply all_stages_clear_of_no_proper hp hq g hraw B\n    intro i hi hh\n    exact he ⟨i, hi, hh⟩\n\n/-- The last retained stage is precisely the original public projector. -/\ntheorem publicStage_eq_projectedUnit {N : ℕ} (g : (ZMod N)ˣ) (B : ℕ) :\n    publicStage g B=projectedUnit g B := by\n  exact stagedProjection_eq _ _ _\n\n/-- Computing all stage values uses a scan, retaining each preceding\npower rather than recomputing separate factorial projections. -/\ndef unitTrace {N : ℕ} (g : (ZMod N)ˣ) (B : ℕ) : List (ZMod N)ˣ :=\n  (List.range B).scanl (fun x i => x^((i+1)^(Nat.clog 2 (N+1)))) (g^(N-1))\n\n/-- B power stages retain B+1 checked residual values, including raw. -/\ntheorem unitTrace_length {N : ℕ} (g : (ZMod N)ˣ) (B : ℕ) :\n    (unitTrace g B).length=B+1 := by\n  simp [unitTrace]\n\n/-- Each scan entry is the original factorial projection at its label. -/\ntheorem unitTrace_eq_map {N : ℕ} (g : (ZMod N)ˣ) (B : ℕ) :\n    unitTrace g B=(List.range (B+1)).map (publicStage g) := by\n  apply List.ext_getElem\n  · simp [unitTrace_length]\n  · intro i hi hj\n    have hiB : i≤B := by rw [unitTrace_length] at hi; omega\n    simp only [unitTrace, List.getElem_scanl, List.take_range,\n      Nat.min_eq_left hiB, List.getElem_map, List.getElem_range]\n    rfl\n\n/-- Stage residuals are literal unit-minus-one values; their GCDs are\nextracted only at the checked scan. -/\ndef residualTrace {N : ℕ} (g : (ZMod N)ˣ) (B : ℕ) : List ℕ :=\n  (unitTrace g B).map (fun u : (ZMod N)ˣ => ((u : ZMod N)-1).val)\n\n/-- A public, checked projection scan; every returned value divides N. -/\ndef checkedProjection {N : ℕ} (g : (ZMod N)ˣ) (B : ℕ) : Option ℕ :=\n  SemiprimeCartesianCompletion.scanProper N (residualTrace g B)\n\ntheorem checkedProjection_sound {N d B : ℕ} (g : (ZMod N)ˣ)\n    (hs : checkedProjection g B=some d) : SemiprimeGroupSelection.ProperDivisor N d :=\n  SemiprimeCartesianCompletion.scanProper_sound hs\n\n/-- Only B+1 GCD queries are charged to this one checked projection.\nThis is an operation count, not a bit-complexity theorem. -/\ntheorem checkedProjection_gcd_count {N : ℕ} (g : (ZMod N)ˣ) (B : ℕ) :\n    SemiprimeCartesianCompletion.scanGcdCount N (residualTrace g B)≤B+1 := by\n  have h := SemiprimeCartesianCompletion.scanGcdCount_le N (residualTrace g B)\n  simpa only [residualTrace, List.length_map, unitTrace_length] using h\n\n/-- The executable retained trace supplies the clear final certificate\nif its checked scan returns no factor. -/\ntheorem checkedProjection_none_clear {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (g : (ZMod (p*q))ˣ) (hraw : g^(p*q-1)≠1)\n    (hnone : checkedProjection g B=none) : stageGcd g B=1 := by\n  apply all_stages_clear_of_no_proper hp hq g hraw B\n  intro i hi hproper\n  have hm : ((publicStage g i : ZMod (p*q))-1).val ∈ residualTrace g B := by\n    rw [residualTrace, unitTrace_eq_map, List.map_map]\n    exact List.mem_map.mpr ⟨i, List.mem_range.mpr (by omega), rfl⟩\n  have hn := (SemiprimeCartesianCompletion.scanProper_none_iff _ _).mp hnone _ hm\n  change 1<(p*q).gcd ((publicStage g i : ZMod (p*q))-1).val ∧\n    (p*q).gcd ((publicStage g i : ZMod (p*q))-1).val<p*q at hproper\n  simp only [SemiprimeGroupSelection.checkedSignal] at hn\n  simp [hproper] at hn\n\n/-- A final scalar collapse of a screened seed forces a preceding proper\nfactor in the checked trace. It is not a failure of staged projection. -/\ntheorem checkedProjection_succeeds_of_final_kernel {p q B : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (g : (ZMod (p*q))ˣ)\n    (hraw : g^(p*q-1)≠1) (hfinal : projectedUnit g B=1) :\n    ∃ d, checkedProjection g B=some d := by\n  cases he : checkedProjection g B with\n  | some d => exact ⟨d, rfl⟩\n  | none =>\n    have hh := checkedProjection_none_clear hp hq g hraw he\n    have hN : stageGcd g B=p*q := by\n      simp only [stageGcd, publicStage_eq_projectedUnit, hfinal, Units.val_one,\n        sub_self, ZMod.val_zero, Nat.gcd_zero_right]\n    have hp1 := hp.one_lt\n    have hq1 := hq.one_lt\n    have hpq1 : 1<p*q := by nlinarith\n    omega\n\n/-- Raw seed usability depends only on public N and the candidate base.\nIt does not perform any factorial stage or construct a row. -/\ndef rawSeedTest (N a : ℕ) : Bool :=\n  decide (a.Coprime N ∧ (a : ZMod N)^(N-1)≠1)\n\n/-- B consecutive public candidate bases, from 2 through B+1. -/\ndef screenSeed (N B : ℕ) : Option ℕ :=\n  (List.range' 2 B).find? (rawSeedTest N)\n\n/-- The screen retains a usable base and its exact public range. -/\ntheorem screenSeed_sound {N B a : ℕ} (hs : screenSeed N B=some a) :\n    2≤a ∧ a<B+2 ∧ a.Coprime N ∧ (a : ZMod N)^(N-1)≠1 := by\n  have hm := List.mem_of_find?_eq_some hs\n  have ht := List.find?_some hs\n  have hb : 2≤a ∧ a<2+B := List.mem_range'_1.mp hm\n  have hu : a.Coprime N ∧ (a : ZMod N)^(N-1)≠1 := by\n    simpa only [rawSeedTest, decide_eq_true_eq] using ht\n  exact ⟨hb.1, by omega, hu⟩\n\n/-- An exhausted scan means all its unit bases lie in the raw kernel.\nNo theorem here excludes this outcome for a sixth-root width. -/\ntheorem screenSeed_none_iff (N B : ℕ) : screenSeed N B=none ↔\n    ∀ a, 2≤a → a<B+2 → a.Coprime N → (a : ZMod N)^(N-1)=1 := by\n  simp [screenSeed, rawSeedTest, Nat.add_comm]\n\n/-- The raw test count stops at the first usable seed. -/\ndef rawScanCount (N : ℕ) : List ℕ → ℕ\n  | [] => 0\n  | a :: tail => 1+if rawSeedTest N a then 0 else rawScanCount N tail\n\ntheorem rawScanCount_le (N : ℕ) (bases : List ℕ) :\n    rawScanCount N bases≤bases.length := by\n  induction bases with\n  | nil => simp [rawScanCount]\n  | cons a tail ih =>\n    cases ht : rawSeedTest N a <;> simp [rawScanCount, ht]\n    omega\n\n/-- At most B raw powers and B unit GCD checks precede the single\nfactorial projection. A short-scan coverage guarantee is still open. -/\ntheorem screenSeed_test_count (N B : ℕ) : rawScanCount N (List.range' 2 B)≤B := by\n  simpa only [List.length_range'] using rawScanCount_le N (List.range' 2 B)\n\n/-- The screened natural base supplies an actual public unit and a\nnontrivial raw power; local orders are not additional inputs. -/\ntheorem screenSeed_unit_certificate {N B a : ℕ} (hs : screenSeed N B=some a) :\n    ∃ g : (ZMod N)ˣ, (g : ZMod N)=(a : ZMod N) ∧ g^(N-1)≠1 := by\n  obtain ⟨_, _, hc, hn⟩ := screenSeed_sound hs\n  obtain ⟨g, hg⟩ := (ZMod.isUnit_iff_coprime a N).mpr hc\n  refine ⟨g, hg, ?_⟩\n  intro he\n  apply hn\n  have hv := congrArg (fun u : (ZMod N)ˣ => (u : ZMod N)) he\n  simpa only [Units.val_pow_eq_pow_val, hg, Units.val_one] using hv\n\n/-- When both field cardinalities divide a common exponent, the final\nscalar power is one for every public unit. This certificate uses both\nretained reductions, not an observed single-base failure. -/\ntheorem common_field_exponent_kernel {p q E : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p≠q) (g : (ZMod (p*q))ˣ) (hpE : p-1∣E) (hqE : q-1∣E) :\n    g^E=1 := by\n  let : Fact p.Prime := ⟨hp⟩\n  let : Fact q.Prime := ⟨hq⟩\n  apply Units.ext\n  apply SemiprimeIntervalJet.eq_of_prime_reductions hp hq hpq\n  · let gp := Units.map (ZMod.castHom (dvd_mul_right p q) (ZMod p)).toMonoidHom g\n    have hh : gp^E=1 := orderOf_dvd_iff_pow_eq_one.mp\n      ((ZMod.orderOf_units_dvd_card_sub_one gp).trans hpE)\n    have he := congrArg (fun u : (ZMod p)ˣ => (u : ZMod p)) hh\n    simpa [gp, RingHom.toMonoidHom] using he\n  · let gq := Units.map (ZMod.castHom (dvd_mul_left q p) (ZMod q)).toMonoidHom g\n    have hh : gq^E=1 := orderOf_dvd_iff_pow_eq_one.mp\n      ((ZMod.orderOf_units_dvd_card_sub_one gq).trans hqE)\n    have he := congrArg (fun u : (ZMod q)ˣ => (u : ZMod q)) hh\n    simpa [gq, RingHom.toMonoidHom] using he\n\nset_option maxRecDepth 32768 in\n/-- All final projected bases collapse on the saved kernel input, even\nthough an earlier raw GCD can already recover a factor. -/\ntheorem control_all_final_bases_kernel (g : (ZMod 1373653)ˣ) :\n    projectedUnit g 11=1 := by\n  unfold projectedUnit\n  rw [← pow_mul]\n  apply common_field_exponent_kernel (p:=829) (q:=1657)\n    (by norm_num) (by norm_num) (by norm_num) g <;> norm_num [Nat.clog]\n\nset_option maxRecDepth 32768 in\n/-- The raw screen's first two bases are trivial; the third exposes 829\nwithout constructing any rows or completing the factorial projection. -/\ntheorem control_raw_seed_factor :\n    (2 : ZMod 1373653)^(1373653-1)=1 ∧\n    (3 : ZMod 1373653)^(1373653-1)=1 ∧\n    (5 : ZMod 1373653)^(1373653-1)=1370338 ∧\n    Nat.gcd 1373653 (1370338-1)=829 := by\n  norm_num\n  reduce_mod_char\n  norm_num\n\n/-- Squaring the first raw-kernel base keeps base 4 in that kernel. -/\ntheorem control_raw_four_kernel : (4 : ZMod 1373653)^(1373653-1)=1 := by\n  have he : (4 : ZMod 1373653)=(2 : ZMod 1373653)^2 := by norm_num\n  rw [he, ← pow_mul, Nat.mul_comm, pow_mul, control_raw_seed_factor.1, one_pow]\n\n/-- A deliberately short two-base scan is exhausted on this semiprime.\nThis is a control of the failure branch, not a sixth-root counterexample. -/\ntheorem control_two_base_screen_exhausted : screenSeed 1373653 2=none := by\n  change ([2, 3] : List ℕ).find? (rawSeedTest 1373653)=none\n  simp [rawSeedTest, control_raw_seed_factor.1, control_raw_seed_factor.2.1]\n\nset_option maxRecDepth 32768 in\n/-- A nontrivial raw seed exposes 19 at stage 3 on 19*29, even though\nthe final scalar projection at width 7 is globally one. -/\ntheorem control_staged_factor_before_final (g : (ZMod 551)ˣ)\n    (hg : (g : ZMod 551)=2) :\n    stageGcd g 0=1 ∧ stageGcd g 2=1 ∧ stageGcd g 3=19 ∧\n      (projectedUnit g 7 : ZMod 551)=1 := by\n  simp only [stageGcd, publicStage, stagedProjection_eq, projectedUnit,\n    Units.val_pow_eq_pow_val, hg]\n  norm_num [Nat.clog]\n  reduce_mod_char\n  norm_num [ZMod.val_ofNat]\n\nend RiemannGaussian.SemiprimeStagedSeed\n","RiemannGaussian.SemiprimeStrassenPrefix":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeLehmanCoverage\nimport Mathlib.Data.Nat.Factorial.BigOperators\n\n/-!\n# A complete small-factor prefix from one degree-B polynomial\n\nStrassen's additive cover has B roots and B evaluation points. Its B²\ninteger candidates need not be materialized. The polynomial and all target\nvalues are retained, including a column whose GCD is the entire modulus.\nSuch a column triggers at most one length-B leaf scan.\n\nThe no-factor result is equivalent to coprimality of the original factorial\nprefix when B² < N. This supplies the exact premise of the complete Lehman\ncomplement. The query count below excludes polynomial construction and\nevaluation; no full one-sixth bit-operation theorem is inferred.\n-/\n\nnamespace RiemannGaussian.SemiprimeStrassenPrefix\n\nopen scoped BigOperators\nopen Polynomial\nopen SemiprimeCartesianCompletion SemiprimeGroupSelection\n\n/-- One polynomial for all blocks of the public integer prefix. -/\nnoncomputable def blockPolynomial {R : Type*} [CommRing R] (B : ℕ) : R[X] :=\n  ∏ i ∈ Finset.range B, (X + C ((i+1 : ℕ) : R))\n\n/-- Every evaluation keeps exactly its original integer block. -/\ntheorem blockPolynomial_eval {R : Type*} [CommRing R] (B j : ℕ) :\n    (blockPolynomial (R := R) B).eval ((j*B : ℕ) : R) =\n      ((B*(j+1)).descFactorial B : R) := by\n  have h : (∏ i ∈ Finset.range B, (j*B+i+1)) = (B*(j+1)).descFactorial B := by\n    rw [Nat.mul_add, Nat.mul_one, Nat.mul_comm B j,\n      Nat.add_descFactorial_eq_ascFactorial, Nat.ascFactorial_eq_prod_range]\n    apply Finset.prod_congr rfl\n    intro i _\n    omega\n  simp only [blockPolynomial, eval_prod, eval_add, eval_X, eval_C]\n  rw [← h, Nat.cast_prod]\n  apply Finset.prod_congr rfl\n  intro i _\n  push_cast\n  ring\n\n/-- The joined modular detector equals the original factorial, without\nconstructing that factorial as an integer in the polynomial algorithm. -/\ntheorem blockPolynomial_joined {R : Type*} [CommRing R] (B : ℕ) :\n    (∏ j ∈ Finset.range B,\n      (blockPolynomial (R := R) B).eval ((j*B : ℕ) : R)) = ((B^2).factorial : R) := by\n  simp_rw [blockPolynomial_eval]\n  rw [← Nat.cast_prod, ← SemiprimeGroupCoverage.prefixProduct,\n    SemiprimeGroupCoverage.prefixProduct_eq_factorial]\n\n/-- Lazy canonical residues for one ambiguous polynomial column. -/\ndef blockLeaves (N B j : ℕ) : List ℕ :=\n  (List.range B).map fun i => (j*B+i+1) % N\n\n/-- B evaluated columns, identified by the public block index. -/\nnoncomputable def blockColumns (N B : ℕ) : List (ℕ × ℕ) :=\n  (List.range B).map fun j =>\n    (j, ((blockPolynomial (R := ZMod N) B).eval ((j*B : ℕ) : ZMod N)).val)\n\n/-- Recover the first nonunit block, with a single lazy leaf scan if the\naggregate GCD is N. No B-by-B candidate list is an input. -/\nnoncomputable def factorPrefix (N B : ℕ) : Option ℕ :=\n  recoverColumns N (blockLeaves N B) (blockColumns N B)\n\n/-- A polynomial column has precisely the same GCD as its lazy leaves. -/\ntheorem block_column_gcd_eq (N B j : ℕ) :\n    N.gcd ((blockPolynomial (R := ZMod N) B).eval ((j*B : ℕ) : ZMod N)).val =\n      N.gcd (blockLeaves N B j).prod := by\n  have h : ((blockLeaves N B j).prod : ZMod N) =\n      (blockPolynomial (R := ZMod N) B).eval ((j*B : ℕ) : ZMod N) := by\n    simp only [blockLeaves, Nat.cast_list_prod, List.map_map,\n      blockPolynomial, eval_prod, eval_add, eval_X, eval_C]\n    rw [← List.prod_toFinset _ (List.nodup_range (n := B)), List.toFinset_range]\n    apply Finset.prod_congr rfl\n    intro i _\n    dsimp only [Function.comp_apply]\n    rw [ZMod.natCast_mod]\n    push_cast\n    ring\n  rw [← h, ZMod.val_natCast, Nat.gcd_rec N,\n    Nat.gcd_rec N ((blockLeaves N B j).prod), Nat.mod_mod]\n\n/-- Every represented integer is positive and inside the quadratic cover. -/\ntheorem block_integer_bounds {B i j : ℕ} (hi : i < B) (hj : j < B) :\n    0 < j*B+i+1 ∧ j*B+i+1 ≤ B^2 := by\n  have hB : 0 < B := by omega\n  have hjB : (j+1)*B ≤ B*B := Nat.mul_le_mul_right B (by omega)\n  constructor\n  · omega\n  · nlinarith\n\n/-- In the original input regime every lazy leaf is nonzero modulo N.\nThis is what makes whole-modulus column recovery complete. -/\ntheorem blockLeaves_bounds {N B j : ℕ} (hcover : B^2 < N) (hj : j < B) :\n    ∀ v ∈ blockLeaves N B j, 0 < v ∧ v < N := by\n  intro v hv\n  obtain ⟨i, hi, rfl⟩ := List.mem_map.mp hv\n  have hb := block_integer_bounds (List.mem_range.mp hi) hj\n  rw [Nat.mod_eq_of_lt (hb.2.trans_lt hcover)]\n  exact ⟨hb.1, hb.2.trans_lt hcover⟩\n\n/-- Every integer in the prefix occurs at a public block/leaf position. -/\ntheorem prefix_integer_decomposition {B k : ℕ} (hk : 0 < k) (hkB : k ≤ B^2) :\n    ∃ j i : ℕ, j < B ∧ i < B ∧ k = j*B+i+1 := by\n  have hB : 0 < B := by nlinarith\n  refine ⟨(k-1)/B, (k-1)%B, ?_, Nat.mod_lt _ hB, ?_⟩\n  · apply (Nat.div_lt_iff_lt_mul hB).mpr\n    have hk' : k-1 < B^2 := by omega\n    simpa only [pow_two] using hk'\n  · have he := Nat.mod_add_div (k-1) B\n    rw [Nat.mul_comm B] at he\n    omega\n\n/-- A returned factor is certified for every modulus and cover width. -/\ntheorem prefix_sound {N B d : ℕ} (hh : factorPrefix N B = some d) :\n    ProperDivisor N d := recoverColumns_sound hh\n\n/-- Every nonunit integer in the full prefix forces successful recovery.\nBoth hidden primes may be in one block; no separating-column premise is\nassumed. -/\ntheorem prefix_succeeds_of_nonunit {N B k : ℕ} (hcover : B^2 < N)\n    (hk : 0 < k) (hkB : k ≤ B^2) (hg : N.gcd k ≠ 1) :\n    ∃ d, factorPrefix N B = some d := by\n  obtain ⟨j, i, hj, hi, he⟩ := prefix_integer_decomposition hk hkB\n  apply recoverColumns_succeeds\n  · intro c hc\n    obtain ⟨j', _, rfl⟩ := List.mem_map.mp hc\n    exact block_column_gcd_eq N B j'\n  · intro c hc\n    obtain ⟨j', hj', rfl⟩ := List.mem_map.mp hc\n    exact blockLeaves_bounds hcover (List.mem_range.mp hj')\n  · let v := ((blockPolynomial (R := ZMod N) B).eval ((j*B : ℕ) : ZMod N)).val\n    refine ⟨(j, v), List.mem_map.mpr ⟨j, List.mem_range.mpr hj, rfl⟩, ?_⟩\n    change N.gcd ((blockPolynomial (R := ZMod N) B).eval ((j*B : ℕ) : ZMod N)).val ≠ 1\n    rw [block_column_gcd_eq]\n    intro hunit\n    have hleaf : k ∈ blockLeaves N B j := by\n      apply List.mem_map.mpr\n      refine ⟨i, List.mem_range.mpr hi, ?_⟩\n      rw [← he, Nat.mod_eq_of_lt (hkB.trans_lt hcover)]\n    exact hg (Nat.coprime_list_prod_right_iff.mp hunit k hleaf)\n\n/-- This unconditional prefix covers every small proper divisor,\nincluding repeated prime factors. -/\ntheorem prefix_succeeds_of_small_divisor {N B p : ℕ} (hcover : B^2 < N)\n    (hp : 1 < p) (hpN : p ∣ N) (hpB : p ≤ B^2) :\n    ∃ d, factorPrefix N B = some d := by\n  apply prefix_succeeds_of_nonunit hcover (by omega) hpB\n  rw [Nat.gcd_eq_right hpN]\n  omega\n\n/-- A failed prefix excludes every nonunit integer in its whole cover. -/\ntheorem prefix_none_coprime_integer {N B k : ℕ} (hcover : B^2 < N)\n    (hnone : factorPrefix N B = none) (hk : 0 < k) (hkB : k ≤ B^2) :\n    N.Coprime k := by\n  change N.gcd k = 1\n  by_contra h\n  obtain ⟨d, hd⟩ := prefix_succeeds_of_nonunit hcover hk hkB h\n  rw [hnone] at hd\n  contradiction\n\n/-- No-factor recovery supplies exactly the original factorial-clear\npremise, with no reference primes, orders or smoothness assumptions. -/\ntheorem prefix_none_implies_clear {N B : ℕ} (hcover : B^2 < N)\n    (hnone : factorPrefix N B = none) :\n    N.gcd (SemiprimeGroupCoverage.prefixProduct B) = 1 := by\n  rw [SemiprimeGroupCoverage.prefixProduct_eq_factorial]\n  have h : ∀ k : ℕ, k ≤ B^2 → N.Coprime k.factorial := by\n    intro k\n    induction k with\n    | zero => simp\n    | succ k ih =>\n      intro hk\n      rw [Nat.factorial_succ]\n      exact (prefix_none_coprime_integer hcover hnone (Nat.succ_pos k) hk).mul_right\n        (ih (by omega))\n  exact h (B^2) le_rfl\n\n/-- Modular reduction of a block changes no GCD of its integer value. -/\ntheorem block_column_gcd_eq_descFactorial (N B j : ℕ) :\n    N.gcd ((blockPolynomial (R := ZMod N) B).eval ((j*B : ℕ) : ZMod N)).val =\n      N.gcd ((B*(j+1)).descFactorial B) := by\n  rw [blockPolynomial_eval, ZMod.val_natCast, Nat.gcd_rec N,\n    Nat.gcd_rec N ((B*(j+1)).descFactorial B), Nat.mod_mod]\n\nprivate theorem recoverColumns_none_of_units (N : ℕ) (leaves : ℕ → List ℕ)\n    (columns : List (ℕ × ℕ)) (hu : ∀ c ∈ columns, N.gcd c.2 = 1) :\n    recoverColumns N leaves columns = none := by\n  induction columns with\n  | nil => rfl\n  | cons c tail ih =>\n    rcases c with ⟨j, v⟩\n    rw [recoverColumns, ite_eq_left (hu (j, v) (by simp))]\n    exact ih (fun c hc => hu c (List.mem_cons_of_mem _ hc))\n\n/-- The compressed prefix has exactly the same complete no-small-factor\ncriterion as the original B²-term factorial detector. -/\ntheorem prefix_none_iff_clear {N B : ℕ} (hcover : B^2 < N) :\n    factorPrefix N B = none ↔ N.gcd (SemiprimeGroupCoverage.prefixProduct B) = 1 := by\n  constructor\n  · exact prefix_none_implies_clear hcover\n  · intro hclear\n    apply recoverColumns_none_of_units\n    intro c hc\n    obtain ⟨j, hj, rfl⟩ := List.mem_map.mp hc\n    rw [block_column_gcd_eq_descFactorial]\n    change N.Coprime (SemiprimeGroupCoverage.prefixProduct B) at hclear\n    exact Nat.coprime_prod_right_iff.mp hclear j (Finset.mem_range.mpr (List.mem_range.mp hj))\n\n/-- The exact prefix/complement interface rules out every small prime,\nwithout providing the algorithm with that prime. -/\ntheorem prefix_none_excludes_small_prime {N B p : ℕ} (hcover : B^2 < N)\n    (hp : p.Prime) (hpN : p ∣ N) (hnone : factorPrefix N B = none) : B^2 < p := by\n  apply SemiprimeGroupCoverage.failed_prefix_excludes_small_prime hp hpN\n  rw [← SemiprimeGroupCoverage.prefixProduct_eq_factorial]\n  exact prefix_none_implies_clear hcover hnone\n\n/-- The polynomial is the exact root product of B supplied roots. -/\ntheorem blockPolynomial_eq_rootPolynomial {R : Type*} [CommRing R] (B : ℕ) :\n    blockPolynomial (R := R) B = rootPolynomial (Finset.range B)\n      (fun i => -((i+1 : ℕ) : R)) := by\n  simp only [blockPolynomial, rootPolynomial, map_neg, sub_neg_eq_add]\n\n/-- The input polynomial has degree B over every nonzero coefficient ring. -/\ntheorem blockPolynomial_degree {R : Type*} [CommRing R] [Nontrivial R] (B : ℕ) :\n    (blockPolynomial (R := R) B).natDegree = B := by\n  rw [blockPolynomial_eq_rootPolynomial]\n  simpa only [rootPolynomial, Finset.card_range] using\n    natDegree_finsetProd_X_sub_C_eq_card (Finset.range B) (fun i => -((i+1 : ℕ) : R))\n\n/-- Each leaf list has B entries and is constructed only if needed. -/\ntheorem blockLeaves_length (N B j : ℕ) : (blockLeaves N B j).length = B := by\n  simp [blockLeaves]\n\n/-- Only B polynomial evaluations are supplied to recovery. -/\ntheorem blockColumns_length (N B : ℕ) : (blockColumns N B).length = B := by\n  simp [blockColumns]\n\n/-- The complete prefix needs at most 2B GCD queries after polynomial\nevaluation, even if the first nonunit column has GCD N. Polynomial and\nbit-operation costs are separate obligations. -/\ntheorem prefix_gcd_bound (N B : ℕ) :\n    recoveryGcdCount N (blockLeaves N B) (blockColumns N B) ≤ 2*B := by\n  have h := recoveryGcdCount_le (n := N) (cap := B)\n    (columns := blockColumns N B) (leaves := blockLeaves N B)\n    (fun c _ => (blockLeaves_length N B c.1).le)\n  simpa only [blockColumns_length, two_mul] using h\n\n/-- Every nontrivial ceiling-sixth-root input lies above the entire\nquadratic prefix. Small inputs are handled by the finite baseline. -/\ntheorem sixth_budget_prefix_below_input {N B : ℕ} (hB : 4 ≤ B)\n    (hlower : (B-1)^6 < N) : B^2 < N := by\n  have hpow : B^2 ≤ B^4 := by\n    have h := Nat.le_pow (a := B^2) (by decide : 0 < 2)\n    convert h using 1\n    ring\n  exact hpow.trans_lt ((SemiprimeGroupCoverage.sixth_budget_above_quadratic_prefix hB).trans hlower)\n\n/-- Replace the factorial-prefix construction with the B-point polynomial\nbatch; retain the universally correct literal Lehman complement. This is\nan algorithm specification, not a formal fast-polynomial implementation. -/\nnoncomputable def factorByBatchCover (N B : ℕ) : Option ℕ :=\n  if B < 4 ∨ N.sqrt^2 = N then SemiprimeLehmanCoverage.factorByCover N B\n  else match factorPrefix N B with\n    | some d => some d\n    | none => SemiprimeLehmanCoverage.factorAfterPrefix N B\n\n/-- Every result from the updated public factorizer is a proper divisor. -/\ntheorem factorByBatchCover_sound {N B d : ℕ}\n    (hh : factorByBatchCover N B = some d) : ProperDivisor N d := by\n  unfold factorByBatchCover at hh\n  split_ifs at hh with hearly\n  · exact SemiprimeLehmanCoverage.factorByCover_sound hh\n  · cases hp : factorPrefix N B with\n    | none => exact SemiprimeLehmanCoverage.factorAfterPrefix_sound (by simpa only [hp] using hh)\n    | some d' =>\n      have he : d' = d := by simpa only [hp, Option.some.injEq] using hh\n      subst d'\n      exact prefix_sound hp\n\n/-- Universal correctness survives the compressed prefix replacement.\nAll small-factor, square and arbitrary-factor-ratio cases are retained. -/\ntheorem factorByBatchCover_semiprime {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p ≤ q) (hbudget : p*q ≤ B^6) (hlower : (B-1)^6 < p*q) :\n    ∃ d, factorByBatchCover (p*q) B = some d := by\n  by_cases hearly : B < 4 ∨ (p*q).sqrt^2 = p*q\n  · obtain ⟨d, hd⟩ := SemiprimeLehmanCoverage.factorByCover_semiprime hp hq hpq hbudget hlower\n    exact ⟨d, by simpa only [factorByBatchCover, ite_eq_left hearly] using hd⟩\n  · have hB : 4 ≤ B := by omega\n    have hsquare : (p*q).sqrt^2 ≠ p*q := fun h => hearly (Or.inr h)\n    have hstrict : p < q := by\n      apply lt_of_le_of_ne hpq\n      intro heq\n      apply hsquare\n      rw [← heq]\n      simp [← pow_two]\n    cases hprefix : factorPrefix (p*q) B with\n    | some d => exact ⟨d, by simp only [factorByBatchCover, ite_eq_right hearly, hprefix]⟩\n    | none =>\n      have hclear := prefix_none_implies_clear (sixth_budget_prefix_below_input hB hlower) hprefix\n      obtain ⟨d, hd⟩ := SemiprimeLehmanCoverage.factorAfterPrefix_succeeds\n        hp hq hstrict (by omega) hbudget hclear\n      exact ⟨d, by simpa only [factorByBatchCover, ite_eq_right hearly, hprefix] using hd⟩\n\n/-- One public input; the width is obtained solely from its sixth-power\nbudget. The centre-coupled complement still exceeds the target work. -/\nnoncomputable def factor (N : ℕ) : Option ℕ :=\n  factorByBatchCover N (SemiprimeLehmanCoverage.sixthWidth N)\n\n/-- Soundness requires no semiprimality promise. -/\ntheorem factor_sound {N d : ℕ} (hh : factor N = some d) : ProperDivisor N d :=\n  factorByBatchCover_sound hh\n\n/-- Every prime product is factored by the updated full specification,\nincluding squares and either ordering. No one-sixth bit bound is claimed. -/\ntheorem factor_semiprime {p q : ℕ} (hp : p.Prime) (hq : q.Prime) :\n    ∃ d, factor (p*q) = some d ∧ ProperDivisor (p*q) d := by\n  have hN : 0 < p*q := Nat.mul_pos hp.pos hq.pos\n  have hbudget := SemiprimeLehmanCoverage.sixthWidth_upper (p*q)\n  have hlower := SemiprimeLehmanCoverage.sixthWidth_lower hN\n  have hs : ∃ d, factor (p*q) = some d := by\n    rcases le_total p q with hpq | hqp\n    · exact factorByBatchCover_semiprime hp hq hpq hbudget hlower\n    · have h := factorByBatchCover_semiprime hq hp hqp\n        (SemiprimeLehmanCoverage.sixthWidth_upper (q*p))\n        (SemiprimeLehmanCoverage.sixthWidth_lower (Nat.mul_pos hq.pos hp.pos))\n      simpa only [factor, Nat.mul_comm] using h\n  obtain ⟨d, hd⟩ := hs\n  exact ⟨d, hd, factor_sound hd⟩\n\n/-- A block containing both primes has GCD N, but its lazy scan still\nreturns a proper factor. This certificate uses the exact polynomial. -/\ntheorem saturated_column_control :\n    Nat.gcd 35 ((4*(1+1)).descFactorial 4) = 35 ∧\n      factorPrefix 35 4 = some 5 := by\n  have hc : blockColumns 35 4 = [(0,24), (1,0), (2,15), (3,0)] := by\n    simp only [blockColumns]\n    simp only [blockPolynomial_eval]\n    norm_num [List.range_succ, Nat.descFactorial, ZMod.val_natCast, ZMod.val_ofNat]\n  rw [factorPrefix, hc]\n  norm_num [List.range_succ, Nat.descFactorial, blockLeaves, recoverColumns, scanProper, checkedSignal]\n\n/- The reference small-factor algorithm is Strassen's polynomial method,\nas recalled in Harvey, arXiv:2010.05450, Proposition 2.5. The implementation\ncost theorem and the full implicit Lehman search remain separate. -/\n\nend RiemannGaussian.SemiprimeStrassenPrefix\n","RiemannGaussian.SemiprimeStreamingTensor":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport Mathlib\n\n/-!\n# Streaming evaluation of Boolean tensor entries\n\nThe recursive evaluator computes the genuine multilinear extension at arbitrary\nring inputs while retaining the supplied Boolean entry function. Its instrumented\nversion records calls at the leaves and recursion depth on the same branches.\n\nThis is the local algebraic evaluator used by the proposed large-scope counting\nextension. Primitive-machine compilation, entry-evaluator costs, coefficient\nheights, workspace and the complete factoring bound are separate obligations.\n-/\n\nnamespace RiemannGaussian.SemiprimeStreamingTensor\nopen scoped BigOperators\nvariable {R : Type*} [CommRing R]\n\n/-- Depth-first multilinear evaluation: no truth-table list is an input. -/\ndef evaluate : (w : ℕ) → ((Fin w → Bool) → R) → (Fin w → R) → R\n  | 0, T, _ => T Fin.elim0\n  | w + 1, T, x =>\n      (1 - x 0) * evaluate w (fun a => T (Fin.cons false a)) (fun i => x i.succ) +\n      x 0 * evaluate w (fun a => T (Fin.cons true a)) (fun i => x i.succ)\n\n/-- Embed a Boolean input as zero or one in the coefficient ring. -/\ndef bit (b : Bool) : R := if b then 1 else 0\n\ntheorem boolean_recovery (w : ℕ) (T : (Fin w → Bool) → R) (a : Fin w → Bool) :\n    evaluate w T (fun i => bit (a i)) = T a := by\n  induction w with\n  | zero =>\n    change T Fin.elim0 = T a\n    congr 1\n    funext i\n    exact Fin.elim0 i\n  | succ w ih =>\n    simp only [evaluate]\n    rw [ih, ih]\n    have ha : Fin.cons (a 0) (fun i => a i.succ) = a := by\n      funext i\n      refine Fin.cases ?_ (fun j => ?_) i <;> rfl\n    cases h : a 0 <;> simp only [bit, Bool.false_eq_true, ↓reduceIte, sub_zero,\n      one_mul, zero_mul, add_zero, sub_self, zero_add]\n    · exact congrArg T (by simpa only [h] using ha)\n    · exact congrArg T (by simpa only [h] using ha)\n\n/-- Number of leaf evaluations in the complete binary recursion on the arity. -/\ndef leafCount : ℕ → ℕ\n  | 0 => 1\n  | w + 1 => leafCount w + leafCount w\n\n/-- Recursion depth of the streaming evaluator on the given arity. -/\ndef recursionDepth : ℕ → ℕ\n  | 0 => 0\n  | w + 1 => recursionDepth w + 1\n\ntheorem leafCount_eq (w : ℕ) : leafCount w = 2 ^ w := by\n  induction w with\n  | zero => rfl\n  | succ w ih => simp [leafCount, ih, pow_succ, Nat.mul_two]\n\ntheorem recursionDepth_eq (w : ℕ) : recursionDepth w = w := by\n  induction w with\n  | zero => rfl\n  | succ w ih => simp [recursionDepth, ih]\n\n/-- Exact tensor-product interpolation formula, without a materialized table. -/\ntheorem evaluate_eq_sum (w : ℕ) (T : (Fin w → Bool) → R) (x : Fin w → R) :\n    evaluate w T x = ∑ a : Fin w → Bool,\n      T a * ∏ i, (if a i then x i else 1 - x i) := by\n  classical\n  induction w with\n  | zero =>\n    simp only [evaluate, Fintype.prod_empty, mul_one, Fintype.sum_unique]\n    congr 1\n  | succ w ih =>\n    rw [← (Fin.consEquiv (fun _ : Fin (w + 1) => Bool)).sum_comp]\n    rw [Fintype.sum_prod_type]\n    simp only [Fin.consEquiv_apply, Fin.prod_univ_succ, Fin.cons_zero, Fin.cons_succ]\n    simp only [Fintype.sum_bool]\n    simp only [Bool.false_eq_true, ↓reduceIte]\n    conv_rhs => rw [add_comm]\n    rw [evaluate, ih, ih]\n    rw [Finset.mul_sum, Finset.mul_sum]\n    apply congrArg₂ (· + ·)\n    · apply Finset.sum_congr rfl\n      intro a ha\n      change _ = T (Fin.cons false a) * _\n      ring\n    · apply Finset.sum_congr rfl\n      intro a ha\n      change _ = T (Fin.cons true a) * _\n      ring\n\n/-- Instrumented version: each leaf performs the table call and each internal\nnode combines the values and actual recursive call counts/depths. -/\ndef evaluateTracked : (w : ℕ) → ((Fin w → Bool) → R) → (Fin w → R) → R × ℕ × ℕ\n  | 0, T, _ => (T Fin.elim0, 1, 0)\n  | w + 1, T, x =>\n      let left := evaluateTracked w (fun a => T (Fin.cons false a)) (fun i => x i.succ)\n      let right := evaluateTracked w (fun a => T (Fin.cons true a)) (fun i => x i.succ)\n      ((1 - x 0) * left.1 + x 0 * right.1,\n        left.2.1 + right.2.1, max left.2.2 right.2.2 + 1)\n\ntheorem evaluateTracked_eq (w : ℕ) (T : (Fin w → Bool) → R) (x : Fin w → R) :\n    evaluateTracked w T x = (evaluate w T x, 2 ^ w, w) := by\n  induction w with\n  | zero => rfl\n  | succ w ih =>\n    simp [evaluateTracked, evaluate, ih, pow_succ, Nat.mul_two]\n\n/-- Exact interpolation together with the evaluator's recursive call/depth counts. -/\ntheorem evaluateTracked_eq_sum (w : ℕ) (T : (Fin w → Bool) → R) (x : Fin w → R) :\n    evaluateTracked w T x =\n      (∑ a : Fin w → Bool, T a * ∏ i, (if a i then x i else 1 - x i), 2 ^ w, w) := by\n  rw [evaluateTracked_eq, evaluate_eq_sum]\n\n/-- At Boolean inputs the tracked value is the original local tensor entry. -/\ntheorem evaluateTracked_at_boolean (w : ℕ) (T : (Fin w → Bool) → R)\n    (a : Fin w → Bool) :\n    evaluateTracked w T (fun i => bit (a i)) = (T a, 2 ^ w, w) := by\n  rw [evaluateTracked_eq, boolean_recovery]\n\n/-- Substituting degree-r paths in the streaming multilinear evaluator costs\nonly the true number of local ports in polynomial degree. -/\ntheorem natDegree_evaluate_le {C : Type*} [CommRing C] (w : ℕ)\n    (T : (Fin w → Bool) → C) (paths : Fin w → Polynomial C) (r : ℕ)\n    (hp : ∀ i, (paths i).natDegree ≤ r) :\n    (evaluate w (fun a => Polynomial.C (T a)) paths).natDegree ≤ w * r := by\n  induction w with\n  | zero => simp [evaluate]\n  | succ w ih =>\n    simp only [evaluate]\n    have hsub : ((1 : Polynomial C) - paths 0).natDegree ≤ r :=\n      (Polynomial.natDegree_sub_le _ _).trans (max_le (by simp) (hp 0))\n    apply Polynomial.natDegree_add_le_of_degree_le\n    · simpa only [Nat.succ_mul, Nat.add_comm] using\n        (Polynomial.natDegree_mul_le).trans\n          (Nat.add_le_add hsub (ih _ _ (fun i => hp i.succ)))\n    · simpa only [Nat.succ_mul, Nat.add_comm] using\n        (Polynomial.natDegree_mul_le).trans\n          (Nat.add_le_add (hp 0) (ih _ _ (fun i => hp i.succ)))\n\n/-- A sum of tensor products has degree controlled by total port incidence,\nwithout multiplying maximum arity by the number of tensor vertices. -/\ntheorem natDegree_sum_product_evaluate_le\n    {C E X : Type*} [CommRing C] [Fintype E] [Fintype X]\n    (arity : E → ℕ) (T : (e : E) → (Fin (arity e) → Bool) → C)\n    (paths : X → (e : E) → Fin (arity e) → Polynomial C) (r : ℕ)\n    (hp : ∀ x e i, (paths x e i).natDegree ≤ r) :\n    (∑ x, ∏ e, evaluate (arity e) (fun a => Polynomial.C (T e a)) (paths x e)).natDegree\n      ≤ (∑ e, arity e) * r := by\n  classical\n  apply Polynomial.natDegree_sum_le_of_forall_le\n  intro x hx\n  refine (Polynomial.natDegree_prod_le _ _).trans ?_\n  calc\n    ∑ e, (evaluate (arity e) (fun a => Polynomial.C (T e a)) (paths x e)).natDegree\n        ≤ ∑ e, arity e * r := by\n      apply Finset.sum_le_sum\n      intro e he\n      exact natDegree_evaluate_le _ _ _ _ (hp x e)\n    _ = (∑ e, arity e) * r := by rw [Finset.sum_mul]\n\n#print axioms natDegree_evaluate_le\n#print axioms natDegree_sum_product_evaluate_le\n#print axioms evaluateTracked_eq_sum\n#print axioms evaluateTracked_at_boolean\n#print axioms evaluateTracked_eq\n#print axioms boolean_recovery\n#print axioms evaluate_eq_sum\n#print axioms leafCount_eq\n#print axioms recursionDepth_eq\nend RiemannGaussian.SemiprimeStreamingTensor\n\n","RiemannGaussian.SemiprimeTotientWindow":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeLongPowerRouting\n\n/-!\n# Retained global collisions around a public totient centre\n\nBoth rough local periods are odd. Their actual global order therefore\ndivides the quarter totient. A short, labelled global collision recovers\nthat quarter totient when the factor-sum offset fits the public window.\nThe true order is never supplied. Wider offsets and the every-run bit\nbound remain open.\n-/\n\nnamespace RiemannGaussian.SemiprimeTotientWindow\n\nopen SemiprimeGroupSelection SemiprimeLocalOrderRouting SemiprimeCentreFreeCover\nopen SemiprimeLongPowerRouting SemiprimeProgressionPrefix\n\n/-- Retain the actual totient as a proof-side arithmetic object. -/\ndef totientCore (p q : ℕ) : ℕ := (p-1)*(q-1)\n\n/-- The useful annihilator need not be the exact global order. -/\ndef quarterTotient (p q : ℕ) : ℕ := totientCore p q/4\n\n/-- This estimate is computed from N and its integer square root only. -/\ndef quarterCentre (N : ℕ) : ℕ := (N+1-2*N.sqrt)/4\n\n/-- Retain the literal factor-sum offset for the coverage theorem. -/\ndef quarterOffset (p q : ℕ) : ℕ := (p+q-2*(p*q).sqrt)/4\n\n/-- The literal factor sum is at least twice the public square root. -/\ntheorem factor_sum_ge_twice_sqrt (p q : ℕ) : 2*(p*q).sqrt≤p+q := by\n  have hZ : 4*(p : ℤ)*q≤((p : ℤ)+q)^2 := by\n    nlinarith [sq_nonneg ((p : ℤ)-q)]\n  have hN : 4*p*q≤(p+q)^2 := by exact_mod_cast hZ\n  nlinarith [Nat.sqrt_le' (p*q)]\n\n/-- Preserve both the product and sum in the exact totient identity. -/\ntheorem totient_sum_identity {p q : ℕ} (hp : 1<p) (hq : 1<q) :\n    p*q+1=totientCore p q+(p+q) := by\n  unfold totientCore\n  have hP := Nat.sub_add_cancel hp.le\n  have hQ := Nat.sub_add_cancel hq.le\n  nlinarith\n\n/-- Both literal field cardinalities are even on the long complement. -/\ntheorem four_dvd_totient {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hB : 2≤B) (h : (ZMod (p*q))ˣ) (hc : CoreData p q B h) :\n    4∣totientCore p q := by\n  obtain ⟨hP,hQ⟩ := local_card_bounds hp hq h hc.1\n  have hp2 : p≠2 := by\n    intro he\n    rw [he] at hP\n    norm_num only [Nat.reduceSub] at hP\n    nlinarith\n  have hq2 : q≠2 := by\n    intro he\n    rw [he] at hQ\n    norm_num only [Nat.reduceSub] at hQ\n    nlinarith\n  have hpD : 2∣p-1 := (even_iff_two_dvd).mp (hp.even_sub_one hp2)\n  have hqD : 2∣q-1 := (even_iff_two_dvd).mp (hq.even_sub_one hq2)\n  simpa only [totientCore] using Nat.mul_dvd_mul hpD hqD\n\n/-- The original rough periods certify that the global period is odd. -/\ntheorem core_order_coprime_four {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpq : p≠q) (hB : 2≤B) (h : (ZMod (p*q))ˣ) (hc : CoreData p q B h) :\n    (orderOf h).Coprime 4 := by\n  have hleft : (orderOf (leftUnit h)).Coprime 2 :=\n    (Nat.prime_two.coprime_iff_not_dvd.mpr\n      (fun hd => by have hh:=hc.2.2.1 2 Nat.prime_two hd; omega)).symm\n  have hright : (orderOf (rightUnit h)).Coprime 2 :=\n    (Nat.prime_two.coprime_iff_not_dvd.mpr\n      (fun hd => by have hh:=hc.2.2.2 2 Nat.prime_two hd; omega)).symm\n  have htwo : (orderOf h).Coprime 2 := by\n    rw [global_order_eq_lcm hp hq hpq h,hc.2.1.lcm_eq_mul]\n    exact hleft.mul_left hright\n  simpa using htwo.pow_right 2\n\n/-- No order acquisition is needed: the projected unit is annihilated\nby the quarter totient, which is proved larger than the factor sum. -/\ntheorem quarter_totient_properties {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hB : 2≤B) (hbudget : p*q≤B^6) (h : (ZMod (p*q))ˣ)\n    (hc : CoreData p q B h) :\n    h^(quarterTotient p q)=1 ∧ quarterTotient p q∣totientCore p q ∧\n      p+q<quarterTotient p q := by\n  have hpq := core_distinct (by omega : 0<B) h hc\n  have h4 := four_dvd_totient hp hq hB h hc\n  obtain ⟨hM,hS⟩ := global_order_totient_and_sum hp hq hpq (by omega) hbudget h hc.1 hc.2.1\n  change orderOf h∣totientCore p q at hM\n  have he : 4*quarterTotient p q=totientCore p q := Nat.mul_div_cancel' h4\n  rw [←he] at hM\n  have hD : orderOf h∣quarterTotient p q :=\n    (core_order_coprime_four hp hq hpq hB h hc).dvd_of_dvd_mul_left hM\n  have hT : 0<quarterTotient p q := by\n    have hP := hp.one_lt\n    have hQ := hq.one_lt\n    have hpositive : 0<totientCore p q := Nat.mul_pos (by omega) (by omega)\n    nlinarith\n  exact ⟨(orderOf_dvd_iff_pow_eq_one).mp hD,Nat.div_dvd_of_dvd h4,\n    hS.trans_le (Nat.le_of_dvd hT hD)⟩\n\n/-- The public centre is the actual quarter totient plus the retained\noffset, including every floor and remainder exactly. -/\ntheorem quarter_centre_encoding {p q : ℕ} (hp : 1<p) (hq : 1<q)\n    (h4 : 4∣totientCore p q) :\n    quarterCentre (p*q)=quarterTotient p q+quarterOffset p q := by\n  have hid := totient_sum_identity hp hq\n  have hamgm := factor_sum_ge_twice_sqrt p q\n  have hm := Nat.mod_eq_zero_of_dvd h4\n  unfold quarterCentre quarterTotient quarterOffset\n  omega\n\n/-- Retain b shifted giant values with their original block labels. -/\nnoncomputable def shiftedRecords {N : ℕ} (h : (ZMod N)ˣ) (C b : ℕ) : List (ℕ×ℕ) :=\n  (List.range b).map fun j => (((h^C*(h^(b*j))⁻¹ : (ZMod N)ˣ) : ZMod N).val,j)\n\n/-- The actual ordered global lookup keeps equal residues and labels. -/\nnoncomputable def shiftedCollision {N : ℕ} (h : (ZMod N)ˣ) (C b : ℕ) : Option (ℕ×ℕ) :=\n  matchSorted (sortedRecords (babyRecords N b h)) (sortedRecords (shiftedRecords h C b))\n\n/-- Each input list has b entries, including before and after sorting. -/\ntheorem shifted_records_budget {N : ℕ} (h : (ZMod N)ˣ) (C b : ℕ) :\n    (sortedRecords (babyRecords N b h)).length=b ∧\n    (sortedRecords (shiftedRecords h C b)).length=b := by\n  simp only [sortedRecords,List.length_mergeSort,babyRecords,shiftedRecords,\n    List.length_map,List.length_range,and_self]\n\n/-- The merge makes at most 2b comparisons; construction and both sorts\nremain charged setup rather than a supplied table. -/\ntheorem shifted_merge_budget {N : ℕ} (h : (ZMod N)ˣ) (C b : ℕ) :\n    matchComparisons (sortedRecords (babyRecords N b h))\n      (sortedRecords (shiftedRecords h C b))≤2*b := by\n  have he := matchComparisons_le (sortedRecords (babyRecords N b h))\n    (sortedRecords (shiftedRecords h C b))\n  obtain ⟨hb,hg⟩ := shifted_records_budget h C b\n  simpa only [hb,hg,two_mul] using he\n\n/-- A global equality retains its bounded offset instead of being\ndiscarded as a full-modulus GCD. -/\ntheorem shiftedCollision_sound {N C b i j : ℕ} [NeZero N] (h : (ZMod N)ˣ)\n    (hs : shiftedCollision h C b=some (i,j)) :\n    i<b ∧ j<b ∧ b*j+i<b^2 ∧ h^(b*j+i)=h^C := by\n  obtain ⟨x,hx,y,hy,hv,hxi,hyj⟩ := matchSorted_sound hs\n  obtain ⟨u,hu,rfl⟩ := List.mem_map.mp (mem_sortedRecords.mp hx)\n  obtain ⟨v,hvb,rfl⟩ := List.mem_map.mp (mem_sortedRecords.mp hy)\n  dsimp only at hxi hyj hv\n  rw [←hxi,←hyj]\n  have hi := List.mem_range.mp hu\n  have hj := List.mem_range.mp hvb\n  have hbound : b*v+u<b^2 := by\n    have hh := Nat.mul_le_mul_left b (show v+1≤b by omega)\n    nlinarith\n  have he : h^u=h^C*(h^(b*v))⁻¹ := Units.ext (ZMod.val_injective N hv)\n  have hh := congrArg (fun z : (ZMod N)ˣ => z*h^(b*v)) he\n  rw [mul_assoc,inv_mul_cancel,mul_one,←pow_add] at hh\n  exact ⟨hi,hj,hbound,by simpa only [Nat.add_comm] using hh⟩\n\n/-- Every offset below b² has an actual retained global collision in\nthe implemented two-list lookup, including the zero offset. -/\ntheorem shiftedCollision_succeeds {N C b d : ℕ} (h : (ZMod N)ˣ)\n    (hd : d<b^2) (he : h^d=h^C) : ∃ pair, shiftedCollision h C b=some pair := by\n  have hb : 0<b := by nlinarith\n  let i := d%b\n  let j := d/b\n  have hi : i<b := Nat.mod_lt d hb\n  have hj : j<b := (Nat.div_lt_iff_lt_mul hb).mpr (by nlinarith)\n  have hde : b*j+i=d := by simpa only [i,j,Nat.add_comm] using Nat.mod_add_div d b\n  have hunit : h^i=h^C*(h^(b*j))⁻¹ := by\n    rw [←he,←hde,Nat.add_comm (b*j) i,pow_add,mul_assoc,mul_inv_cancel,mul_one]\n  have hbm : (((h^i : (ZMod N)ˣ) : ZMod N).val,i)∈sortedRecords (babyRecords N b h) :=\n    mem_sortedRecords.mpr (List.mem_map.mpr ⟨i,List.mem_range.mpr hi,rfl⟩)\n  have hgm : (((h^C*(h^(b*j))⁻¹ : (ZMod N)ˣ) : ZMod N).val,j)∈\n      sortedRecords (shiftedRecords h C b) :=\n    mem_sortedRecords.mpr (List.mem_map.mpr ⟨j,List.mem_range.mpr hj,rfl⟩)\n  cases hs : shiftedCollision h C b with\n  | some pair => exact ⟨pair,rfl⟩\n  | none =>\n    have hn := matchSorted_none_no_common\n      (sortedRecords_pairwise (babyRecords N b h))\n      (sortedRecords_pairwise (shiftedRecords h C b)) hs _ hbm _ hgm\n    exact False.elim (hn (congrArg (fun z : (ZMod N)ˣ => (z : ZMod N).val) hunit))\n\n/-- A supplied large totient divisor gives a checked smaller-factor\ncandidate. This arithmetic helper does not acquire its modulus. -/\ntheorem known_totient_divisor_recovers {p q t : ℕ} (hp : 1<p) (hq : 1<q)\n    (hpq : p≤q) (ht : t∣totientCore p q) (hs : p+q<t) :\n    recoverKnownOrder (p*q) t=some p := by\n  have hc := sumCandidate_of_sum hpq (sumSignal_eq_sum hp hq ht hs)\n  have hg : (p*q).gcd p=p := Nat.gcd_eq_right (dvd_mul_right p q)\n  unfold recoverKnownOrder\n  rw [hc,checkedSignal,hg,ite_eq_left]\n  exact ⟨hp,by nlinarith⟩\n\n/-- Search only the public quarter-centre window, preserving offset\nlabels even when the original GCD would be the full input. -/\nnoncomputable def recoverQuarter {N : ℕ} (h : (ZMod N)ˣ) (B : ℕ) : Option ℕ :=\n  match shiftedCollision h (quarterCentre N) (2*B) with\n  | none => none\n  | some (i,j) => recoverKnownOrder N (quarterCentre N-((2*B)*j+i))\n\n/-- Every returned quarter-window candidate is independently checked. -/\ntheorem recoverQuarter_sound {N B f : ℕ} (h : (ZMod N)ˣ)\n    (hf : recoverQuarter h B=some f) : ProperDivisor N f := by\n  unfold recoverQuarter at hf\n  split at hf\n  · contradiction\n  · exact recoverKnownOrder_sound hf\n\n/-- A short retained global offset is unique when the actual period\nexceeds the whole window. Neither its value nor its factorization is input. -/\ntheorem shiftedCollision_unique_offset {N C b d i j : ℕ} [NeZero N]\n    (h : (ZMod N)ˣ) (hd : d<b^2) (hm : b^2<orderOf h) (he : h^d=h^C)\n    (hs : shiftedCollision h C b=some (i,j)) : b*j+i=d := by\n  obtain ⟨_,_,hbound,hpow⟩ := shiftedCollision_sound h hs\n  exact pow_injOn_Iio_orderOf (x:=h) (hbound.trans hm) (hd.trans hm)\n    (hpow.trans he.symm)\n\n/-- Every covered quarter-centre offset recovers a proper factor through\nthe actual sorted lookup and checked quadratic decoder. -/\ntheorem recoverQuarter_complete {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hB : 2≤B) (hbudget : p*q≤B^6) (h : (ZMod (p*q))ˣ)\n    (hc : CoreData p q B h) (hoff : quarterOffset p q<(2*B)^2) :\n    ∃ f, recoverQuarter h B=some f ∧ ProperDivisor (p*q) f := by\n  let : NeZero (p*q) := ⟨Nat.mul_ne_zero hp.ne_zero hq.ne_zero⟩\n  have hpq := core_distinct (by omega : 0<B) h hc\n  obtain ⟨hpow,hdiv,hlarge⟩ := quarter_totient_properties hp hq hB hbudget h hc\n  have henc := quarter_centre_encoding hp.one_lt hq.one_lt (four_dvd_totient hp hq hB h hc)\n  have he : h^(quarterOffset p q)=h^(quarterCentre (p*q)) := by\n    rw [henc,pow_add,hpow,one_mul]\n  obtain ⟨⟨i,j⟩,hs⟩ := shiftedCollision_succeeds h hoff he\n  have hlocal : orderOf (leftUnit h)∣orderOf h := by\n    rw [global_order_eq_lcm hp hq hpq h]\n    exact Nat.dvd_lcm_left _ _\n  have hm : (2*B)^2<orderOf h :=\n    hc.1.1.trans_le (Nat.le_of_dvd (orderOf_pos h) hlocal)\n  have hlabel := shiftedCollision_unique_offset h hoff hm he hs\n  have hsub : quarterCentre (p*q)-((2*B)*j+i)=quarterTotient p q := by\n    rw [hlabel,henc]\n    omega\n  have hdecode : ∃ f, recoverKnownOrder (p*q) (quarterTotient p q)=some f ∧\n      ProperDivisor (p*q) f := by\n    by_cases horder : p≤q\n    · have hf := known_totient_divisor_recovers hp.one_lt hq.one_lt horder hdiv hlarge\n      exact ⟨p,hf,recoverKnownOrder_sound hf⟩\n    · have horder' : q≤p := by omega\n      have hdiv' : quarterTotient p q∣totientCore q p := by\n        simpa only [totientCore,Nat.mul_comm] using hdiv\n      have hlarge' : q+p<quarterTotient p q := by omega\n      have hf := known_totient_divisor_recovers hq.one_lt hp.one_lt horder' hdiv' hlarge'\n      rw [Nat.mul_comm q p] at hf\n      exact ⟨q,hf,recoverKnownOrder_sound hf⟩\n  obtain ⟨f,hf,hproper⟩ := hdecode\n  exact ⟨f,by simpa only [recoverQuarter,hs,hsub] using hf,hproper⟩\n\n/-- A failed actual quarter window certifies a large literal factor-sum\ngap. It is a strengthened residual population, not universal recovery. -/\ntheorem recoverQuarter_none_gap {p q B : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hB : 2≤B) (hbudget : p*q≤B^6) (h : (ZMod (p*q))ˣ)\n    (hc : CoreData p q B h) (hn : recoverQuarter h B=none) :\n    4*(2*B)^2≤p+q-2*(p*q).sqrt := by\n  have hbig : (2*B)^2≤quarterOffset p q := by\n    by_contra he\n    obtain ⟨f,hf,_⟩ := recoverQuarter_complete hp hq hB hbudget h hc (by omega)\n    rw [hn] at hf\n    contradiction\n  unfold quarterOffset at hbig\n  omega\n\n/-- Retain the complete labelled window before decoding its summary. -/\nstructure Source (N : ℕ) where\n  /-- The cached active unit from the preceding long-power route. -/\n  active : (ZMod N)ˣ\n  /-- Public quarter-totient centre used for this window. -/\n  centre : ℕ\n  /-- Public centre power, retained as a group element. -/\n  target : (ZMod N)ˣ\n  /-- Sorted baby residues with all original exponent labels. -/\n  babies : List (ℕ×ℕ)\n  /-- Sorted shifted residues with all original block labels. -/\n  giants : List (ℕ×ℕ)\n  /-- The actual global equality returned by the ordered merge. -/\n  collision : Option (ℕ×ℕ)\n  /-- The checked factor candidate decoded from that equality. -/\n  factor : Option ℕ\n\n/-- Build each window source once from the cached unit and public input;\nretain the actual lists and match even when the decoder has no factor. -/\nnoncomputable def buildSource {N : ℕ} (h : (ZMod N)ˣ) (B : ℕ) : Source N :=\n  let C := quarterCentre N\n  let target := h^C\n  let babies := sortedRecords (babyRecords N (2*B) h)\n  let giants := sortedRecords (shiftedRecords h C (2*B))\n  let collision := matchSorted babies giants\n  let factor := match collision with\n    | none => none\n    | some (i,j) => recoverKnownOrder N (C-((2*B)*j+i))\n  ⟨h,C,target,babies,giants,collision,factor⟩\n\n/-- The factor option is a downstream view of the retained source. -/\ntheorem buildSource_factor {N : ℕ} (h : (ZMod N)ˣ) (B : ℕ) :\n    (buildSource h B).factor=recoverQuarter h B := rfl\n\n/-- Two actual 2B-entry sorted lists require at most 4B merge comparisons.\nPower construction, both sorts and their bit costs remain separate charges. -/\ntheorem buildSource_budget {N : ℕ} (h : (ZMod N)ˣ) (B : ℕ) :\n    (buildSource h B).babies.length=2*B ∧ (buildSource h B).giants.length=2*B ∧\n    matchComparisons (buildSource h B).babies (buildSource h B).giants≤4*B := by\n  obtain ⟨hb,hg⟩ := shifted_records_budget h (quarterCentre N) (2*B)\n  refine ⟨hb,hg,?_⟩\n  have hh := shifted_merge_budget h (quarterCentre N) (2*B)\n  change matchComparisons (sortedRecords (babyRecords N (2*B) h))\n    (sortedRecords (shiftedRecords h (quarterCentre N) (2*B)))≤4*B\n  omega\n\n/-- Every source decoder checks its candidate independently. -/\ntheorem buildSource_sound {N B d : ℕ} (h : (ZMod N)ˣ)\n    (hd : (buildSource h B).factor=some d) : ProperDivisor N d :=\n  recoverQuarter_sound h hd\n\n/-- Every semiprime's public sixth-root width is at least two. -/\ntheorem sixthWidth_ge_two {N : ℕ} (hN : 4≤N) :\n    2≤SemiprimeLehmanCoverage.sixthWidth N := by\n  have hpos := SemiprimeKernelDescent.sixthWidth_pos (by omega : 0<N)\n  have hbudget := SemiprimeLehmanCoverage.sixthWidth_upper N\n  by_contra he\n  have hw : SemiprimeLehmanCoverage.sixthWidth N=1 := by omega\n  rw [hw] at hbudget\n  norm_num at hbudget\n  omega\n\n/-- A retained window certificate comes from the actual preceding long\nroute. It does not supply the numerical order or quarter totient. -/\ninductive WindowCertified : {N : ℕ} → Source N → Prop where\n  | remaining {p q : ℕ} {g h z s : (ZMod (p*q))ˣ}\n      (hp : p.Prime) (hq : q.Prime)\n      (hd : GoodPower p q (SemiprimeLehmanCoverage.sixthWidth (p*q)) (.remaining g h z s)) :\n      WindowCertified (buildSource h (SemiprimeLehmanCoverage.sixthWidth (p*q)))\n\n/-- A certified source's successful factor is proper for its literal input. -/\ntheorem windowCertified_factor {N d : ℕ} {source : Source N}\n    (hc : WindowCertified source) (hd : source.factor=some d) : ProperDivisor N d := by\n  cases hc with\n  | remaining hp hq hdata => exact buildSource_sound _ hd\n\n/-- A failed certified source retains a true semiprime and the large\nliteral factor-sum gap, including the actual public leaf width. -/\ntheorem windowCertified_gap {N : ℕ} {source : Source N}\n    (hc : WindowCertified source) (hn : source.factor=none) :\n    ∃ p q, p.Prime ∧ q.Prime ∧ N=p*q ∧\n      4*(2*SemiprimeLehmanCoverage.sixthWidth N)^2≤p+q-2*N.sqrt := by\n  cases hc with\n  | @remaining p q g h z s hp hq hdata =>\n    have hN : 4≤p*q := by nlinarith [hp.two_le,hq.two_le]\n    have hcore : CoreData p q (SemiprimeLehmanCoverage.sixthWidth (p*q)) h := by\n      rw [hdata.2.1]\n      exact projected_core g hdata.1\n    exact ⟨p,q,hp,hq,rfl,recoverQuarter_none_gap hp hq (sixthWidth_ge_two hN)\n      (SemiprimeLehmanCoverage.sixthWidth_upper _) h hcore hn⟩\n\n/-- Refine only an actual remaining power leaf; factor leaves construct\nno new source. The cached active unit is used without reprojecting. -/\nnoncomputable def sourceForLeaf {N : ℕ} : PowerRoute N → Option (Source N)\n  | .remaining _ h _ _ => some (buildSource h (SemiprimeLehmanCoverage.sixthWidth N))\n  | _ => none\n\n/-- A certified preceding leaf gives a certified actual window source. -/\ntheorem sourceForLeaf_certified {N : ℕ} {leaf : PowerRoute N} {source : Source N}\n    (hc : PowerCertified leaf) (hs : sourceForLeaf leaf=some source) : WindowCertified source := by\n  cases hc with\n  | factor hp hq hd => simp only [sourceForLeaf] at hs; contradiction\n  | remaining hp hq hd =>\n    have he := Option.some.inj hs\n    rw [←he]\n    exact .remaining hp hq hd\n\n/-- Every certified nonfactor leaf supplies an actual retained window. -/\ntheorem sourceForLeaf_exists {N : ℕ} {leaf : PowerRoute N} (hc : PowerCertified leaf)\n    (hn : ∀ d, leaf≠.factor d) : ∃ source, sourceForLeaf leaf=some source := by\n  cases leaf with\n  | factor d => exact False.elim (hn d rfl)\n  | remaining g h z s => exact ⟨_,rfl⟩\n  | unresolved => exact False.elim (powerCertified_not_unresolved hc)\n\n/-- Reuse an already recovered original factor, or transport only a new\nwindow factor through the preceding retained descent. -/\nnoncomputable def factorWithSource {N : ℕ} (parent : SemiprimeLongPowerRouting.Packet N)\n    (source : Option (Source (SemiprimeKernelDescent.leafInput parent.source))) : Option ℕ :=\n  match parent.factor with\n  | some d => some d\n  | none => match source with\n    | none => none\n    | some source => match source.factor with\n      | none => none\n      | some d => transportCandidate parent.source d\n\n/-- The richer packet retains the preceding complete descent and its\npower channels alongside the actual labelled window. -/\nstructure Packet (N : ℕ) where\n  /-- Complete preceding public result and every original parent frame. -/\n  parent : SemiprimeLongPowerRouting.Packet N\n  /-- The actual new source, if the remaining leaf required a window. -/\n  source : Option (Source (SemiprimeKernelDescent.leafInput parent.source))\n  /-- Downstream checked original-input factor when available. -/\n  factor : Option ℕ\n\n/-- N-only public refinement uses the preceding result once and reuses\nits projected unit. Every new source and successful transport is charged. -/\nnoncomputable def publicPacket (N : ℕ) : Packet N :=\n  let parent := SemiprimeLongPowerRouting.publicPacket N\n  let source := sourceForLeaf parent.leaf\n  ⟨parent,source,factorWithSource parent source⟩\n\n/-- Every original-input factor from the full quarter-window refinement\nis proper, including an already successful preceding stage. -/\ntheorem publicPacket_sound {p q d : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hf : (publicPacket (p*q)).factor=some d) : ProperDivisor (p*q) d := by\n  dsimp only [publicPacket] at hf\n  unfold factorWithSource at hf\n  cases hold : (SemiprimeLongPowerRouting.publicPacket (p*q)).factor with\n  | some f =>\n    simp only [hold] at hf\n    obtain ⟨e,he,hproper⟩ | hn := SemiprimeLongPowerRouting.publicPacket_cases hp hq\n    · rw [hold] at he\n      have hed : e=d := (Option.some.inj he).symm.trans (Option.some.inj hf)\n      rwa [hed] at hproper\n    · have hfalse := hn.1\n      rw [hold] at hfalse\n      contradiction\n  | none =>\n    simp only [hold] at hf\n    cases hs : sourceForLeaf (SemiprimeLongPowerRouting.publicPacket (p*q)).leaf with\n    | none => simp only [hs] at hf; contradiction\n    | some source =>\n      simp only [hs] at hf\n      cases hd : source.factor with\n      | none => simp only [hd] at hf; contradiction\n      | some f =>\n        simp only [hd] at hf\n        exact transportCandidate_sound (SemiprimeKernelDescent.publicTrace_certified hp hq) hf\n\n/-- The full public result either recovers an original factor or keeps\nan actual certified long window whose literal factor-sum gap is large. -/\ntheorem publicPacket_cases {p q : ℕ} (hp : p.Prime) (hq : q.Prime) :\n    (∃ d,(publicPacket (p*q)).factor=some d ∧ ProperDivisor (p*q) d) ∨\n    ((publicPacket (p*q)).factor=none ∧ ∃ source,\n      (publicPacket (p*q)).source=some source ∧ WindowCertified source ∧ source.factor=none ∧\n      ∃ u v, u.Prime ∧ v.Prime ∧\n        SemiprimeKernelDescent.leafInput (publicPacket (p*q)).parent.source=u*v ∧\n        4*(2*SemiprimeLehmanCoverage.sixthWidth\n          (SemiprimeKernelDescent.leafInput (publicPacket (p*q)).parent.source))^2≤\n            u+v-2*(SemiprimeKernelDescent.leafInput (publicPacket (p*q)).parent.source).sqrt) := by\n  cases hf : (publicPacket (p*q)).factor with\n  | some d => exact Or.inl ⟨d,rfl,publicPacket_sound hp hq hf⟩\n  | none =>\n    right\n    refine ⟨rfl,?_⟩\n    obtain ⟨d,hd,hproper⟩ | ⟨hn,hc,hnot⟩ := SemiprimeLongPowerRouting.publicPacket_cases hp hq\n    · have he : (publicPacket (p*q)).factor=some d := by\n        simp only [publicPacket,factorWithSource,hd]\n      rw [hf] at he\n      contradiction\n    · obtain ⟨source,hs⟩ := sourceForLeaf_exists hc hnot\n      have hsource := sourceForLeaf_certified hc hs\n      have hnone : source.factor=none := by\n        cases hd : source.factor with\n        | none => rfl\n        | some d =>\n          have hproper := windowCertified_factor hsource hd\n          obtain ⟨f,hf',_⟩ := transportCandidate_complete\n            (SemiprimeKernelDescent.publicTrace_certified hp hq) hproper\n          have he : (publicPacket (p*q)).factor=some f := by\n            simp only [publicPacket,factorWithSource,hn,hs,hd]\n            exact hf'\n          rw [hf] at he\n          contradiction\n      exact ⟨source,hs,hsource,hnone,windowCertified_gap hsource hnone⟩\n\n/-- An actual leaf source has exactly two linear-size lists and one\nbounded merge, independently of which labelled equality was selected. -/\ntheorem sourceForLeaf_budget {N : ℕ} {leaf : PowerRoute N} {source : Source N}\n    (hs : sourceForLeaf leaf=some source) :\n    source.babies.length=2*SemiprimeLehmanCoverage.sixthWidth N ∧\n      source.giants.length=2*SemiprimeLehmanCoverage.sixthWidth N ∧\n      matchComparisons source.babies source.giants≤4*SemiprimeLehmanCoverage.sixthWidth N := by\n  cases leaf with\n  | factor d => simp only [sourceForLeaf] at hs; contradiction\n  | unresolved => simp only [sourceForLeaf] at hs; contradiction\n  | remaining g h z s =>\n    have he := Option.some.inj hs\n    rw [←he]\n    exact buildSource_budget h _\n\n/-- Every new source fits the ORIGINAL input's sixth-root width after\nall retained descents. This does not assert a complete bit backend. -/\ntheorem publicPacket_source_budget {p q : ℕ} (hp : p.Prime) (hq : q.Prime)\n    {source : Source (SemiprimeKernelDescent.leafInput (publicPacket (p*q)).parent.source)}\n    (hs : (publicPacket (p*q)).source=some source) :\n    source.babies.length≤2*SemiprimeLehmanCoverage.sixthWidth (p*q) ∧\n      source.giants.length≤2*SemiprimeLehmanCoverage.sixthWidth (p*q) ∧\n      matchComparisons source.babies source.giants≤4*SemiprimeLehmanCoverage.sixthWidth (p*q) := by\n  have hb := sourceForLeaf_budget hs\n  have hw := SemiprimeKernelDescent.sixthWidth_mono\n    (certified_leaf_input_le (SemiprimeKernelDescent.publicTrace_certified hp hq))\n  change source.babies.length=2*SemiprimeLehmanCoverage.sixthWidth\n      (SemiprimeKernelDescent.leafInput (SemiprimeKernelDescent.publicTrace (p*q))) ∧\n    source.giants.length=2*SemiprimeLehmanCoverage.sixthWidth\n      (SemiprimeKernelDescent.leafInput (SemiprimeKernelDescent.publicTrace (p*q))) ∧\n    matchComparisons source.babies source.giants≤4*SemiprimeLehmanCoverage.sixthWidth\n      (SemiprimeKernelDescent.leafInput (SemiprimeKernelDescent.publicTrace (p*q))) at hb\n  omega\n\nset_option maxRecDepth 32768 in\n/-- Exact quarter offsets and quadratic decoders for the three old long\nleaves. Literal preceding route selection remains a separate replay. -/\ntheorem control_old_leaf_arithmetic :\n    quarterOffset 44963 62347=354 ∧ (354 : ℕ)<(2*38)^2 ∧\n    quarterCentre 2803308161=700800567 ∧\n    recoverKnownOrder 2803308161 (700800567-354)=some 44963 ∧\n    quarterOffset 714107 1013003=6515 ∧ (6515 : ℕ)<(2*95)^2 ∧\n    quarterCentre 723392533321=180847708068 ∧\n    recoverKnownOrder 723392533321 (180847708068-6515)=some 714107 ∧\n    quarterOffset 74099 197599=7423 ∧ (7423 : ℕ)<(2*50)^2 ∧\n    quarterCentre 14641888301=3660411574 ∧\n    recoverKnownOrder 14641888301 (3660411574-7423)=some 74099 := by\n  norm_num [quarterOffset,quarterCentre,recoverKnownOrder,sumCandidate,sumSignal,checkedSignal]\n\n/-- The old first leaf's global equality carries a nonzero, bounded\noffset. Both scalar powers are checked by fast modular arithmetic. -/\ntheorem control_first_leaf_powers :\n    (183584004 : ZMod 2803308161)^700800567=1216857719 ∧\n    (183584004 : ZMod 2803308161)^354=1216857719 := by\n  constructor <;> reduce_mod_char\n\nset_option maxRecDepth 32768 in\n/-- A larger selected control lies beyond the covered window. These\nexact arithmetic facts do not assert an unconditional failure theorem. -/\ntheorem control_large_gap_arithmetic :\n    (1000000007 : ℕ)*1400000543=1400000552800003801 ∧\n    quarterOffset 1000000007 1400000543=8392042 ∧\n    (2*1058 : ℕ)^2=4477456 ∧ (4477456 : ℕ)<8392042 ∧\n    1400000552800003801≤(1058 : ℕ)^6 := by\n  norm_num [quarterOffset]\n\nend RiemannGaussian.SemiprimeTotientWindow\n"};
